function _G.loadBTRConfig()
    if isfile and readfile and isfile(BTR_CONFIG_FILE) then
        pcall(function()
            local raw = readfile(BTR_CONFIG_FILE)
            local data = game:GetService("HttpService"):JSONDecode(raw)
            if data then
                if data.antiCopyReaction then _G.BTR_ANTI_COPY_REACTION = data.antiCopyReaction end
                if data.bringMethod then _G.BringMethod = tostring(data.bringMethod) end
                if data.selectedOutfitSlot then _G.BTR_OUTFIT_SLOT = tonumber(data.selectedOutfitSlot) or 1 end
                if data.autoRun and type(data.autoRun) == "table" then
                    for k, v in pairs(data.autoRun) do
                        _G.BTR_AUTORUN[k] = (v == true)
                    end
                end
                if data.selectedWallpaper then
                    local sw = tostring(data.selectedWallpaper)
                    if sw:find("Wallpaper 1") or sw:find("Wallpaper 2") or sw:find("Wallpaper 3") or sw:find("Wallpaper 4") or sw == "Default" then
                        _G.BTR_SELECTED_WALLPAPER = "Default (132435635669992)"
                    else
                        _G.BTR_SELECTED_WALLPAPER = sw
                    end
                else
                    _G.BTR_SELECTED_WALLPAPER = "Default (132435635669992)"
                end
                if data.customWallpaperId then
                    _G.BTR_CUSTOM_WALLPAPER_ID = tostring(data.customWallpaperId)
                end
                if data.customWallpapersHistory and type(data.customWallpapersHistory) == "table" then
                    _G.BTR_CUSTOM_WALLPAPERS_HISTORY = data.customWallpapersHistory
                end
                if data.selectedIcon then
                    local si = tostring(data.selectedIcon)
                    if si == "Default" then
