local function plainReplace(str, search, repl)
    search = string.gsub(search, "\r\n", "\n")
    str = string.gsub(str, "\r\n", "\n")
    local idx = string.find(str, search, 1, true)
    while idx do
        str = string.sub(str, 1, idx - 1) .. repl .. string.sub(str, idx + #search)
        idx = string.find(str, search, idx + #repl, true)
    end
    return str
end

