    pctLbl.Size = UDim2.new(0, 60, 0, 18)
    pctLbl.Position = UDim2.new(1, -85, 0, 114)
    pctLbl.BackgroundTransparency = 1
    pctLbl.Text = "0%"
    pctLbl.TextColor3 = Color3.fromRGB(0, 220, 255)
