    pctLbl.TextSize = 11
    pctLbl.TextXAlignment = Enum.TextXAlignment.Right

    
    local barBg = Instance.new("Frame", card)
    barBg.Name = "BarBackground"
    barBg.Size = UDim2.new(1, -50, 0, 4)
    barBg.Position = UDim2.new(0, 25, 0, 138)
    barBg.BackgroundColor3 = Color3.fromRGB(24, 25, 34)
    barBg.BorderSizePixel = 0
    Instance.new("UICorner", barBg).CornerRadius = UDim.new(1, 0)

    local barFill = Instance.new("Frame", barBg)
    barFill.Name = "BarFill"
    barFill.Size = UDim2.new(0, 0, 1, 0)
    barFill.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    barFill.BorderSizePixel = 0
    Instance.new("UICorner", barFill).CornerRadius = UDim.new(1, 0)

    local barGrad = Instance.new("UIGradient", barFill)
    barGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(0, 220, 255)),
        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(160, 60, 255)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 0, 128))
    })

    card.Position = UDim2.new(0.5, -220, 0.5, -78)
    card.BackgroundTransparency = 1
    title.TextTransparency = 1
    subtitle.TextTransparency = 1
    statusLbl.TextTransparency = 1
    pctLbl.TextTransparency = 1
    badgeFrame.BackgroundTransparency = 1
    badgeLbl.TextTransparency = 1
    verLbl.TextTransparency = 1
    barBg.BackgroundTransparency = 1

    TweenService:Create(card, TweenInfo.new(0.4, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
        Position = UDim2.new(0.5, -220, 0.5, -88),
        BackgroundTransparency = 0.12
    }):Play()
    TweenService:Create(title, TweenInfo.new(0.3), { TextTransparency = 0 }):Play()
    TweenService:Create(subtitle, TweenInfo.new(0.3), { TextTransparency = 0 }):Play()
    TweenService:Create(statusLbl, TweenInfo.new(0.3), { TextTransparency = 0 }):Play()
    TweenService:Create(pctLbl, TweenInfo.new(0.3), { TextTransparency = 0 }):Play()
    TweenService:Create(badgeFrame, TweenInfo.new(0.3), { BackgroundTransparency = 0.85 }):Play()
    TweenService:Create(badgeLbl, TweenInfo.new(0.3), { TextTransparency = 0 }):Play()
    TweenService:Create(verLbl, TweenInfo.new(0.3), { TextTransparency = 0 }):Play()
    TweenService:Create(barBg, TweenInfo.new(0.3), { BackgroundTransparency = 0 }):Play()

    
    task.spawn(function()
        local function setProgress(pct, statusText)
            pctLbl.Text = tostring(math.floor(pct * 100)) .. "%"
            if statusText then statusLbl.Text = "> " .. statusText end
            TweenService:Create(barFill, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Size = UDim2.new(math.clamp(pct, 0, 1), 0, 1, 0)
            }):Play()
        end

        setProgress(0.12, "Connecting to Brookhaven...")
        if not game:IsLoaded() then game.Loaded:Wait() end
        task.wait(0.04)

        local char = lp.Character or lp.CharacterAdded:Wait()
        if not char:FindFirstChild("HumanoidRootPart") then
            char:WaitForChild("HumanoidRootPart", 3)
        end
        task.wait(0.04)

        local maxWait = 120.0
        local elapsed = 0
        local currentVisualProg = 0.08

                                                                                          
        while not _G.BTR_ALL_LOADED and elapsed < maxWait do
            task.wait(0.03)
            elapsed = elapsed + 0.03
            local realTarget = _G.BTR_LOAD_PROGRESS or 0.10
            realTarget = math.clamp(realTarget, 0.05, 0.98)
                                                              
            currentVisualProg = currentVisualProg + (realTarget - currentVisualProg) * 0.35
            local currentStatus = _G.BTR_LOAD_STATUS or "Loading interface & modules..."
            setProgress(currentVisualProg, currentStatus)
        end

                                                                           
        setProgress(1.0, "Ready! Welcome ❤️")
        task.wait(0.35)

        TweenService:Create(card, TweenInfo.new(0.35, Enum.EasingStyle.Quart, Enum.EasingDirection.In), {
            Position = UDim2.new(0.5, -220, 0.5, -78),
            BackgroundTransparency = 1
        }):Play()
        TweenService:Create(title, TweenInfo.new(0.25), { TextTransparency = 1 }):Play()
        TweenService:Create(subtitle, TweenInfo.new(0.25), { TextTransparency = 1 }):Play()
        TweenService:Create(statusLbl, TweenInfo.new(0.25), { TextTransparency = 1 }):Play()
        TweenService:Create(pctLbl, TweenInfo.new(0.25), { TextTransparency = 1 }):Play()
        TweenService:Create(badgeFrame, TweenInfo.new(0.25), { BackgroundTransparency = 1 }):Play()
        TweenService:Create(badgeLbl, TweenInfo.new(0.25), { TextTransparency = 1 }):Play()
        TweenService:Create(verLbl, TweenInfo.new(0.25), { TextTransparency = 1 }):Play()
        TweenService:Create(barBg, TweenInfo.new(0.25), { BackgroundTransparency = 1 }):Play()
        TweenService:Create(barFill, TweenInfo.new(0.25), { BackgroundTransparency = 1 }):Play()
        TweenService:Create(bgOverlay, TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { BackgroundTransparency = 1 }):Play()
        TweenService:Create(blur, TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Size = 0 }):Play()

        task.wait(0.45)
        pcall(function() blur:Destroy() end)
        pcall(function() sg:Destroy() end)
        if onFinish then onFinish() end

                                                                                
        task.delay(1.5, function()
            _G.BTR_STARTUP_SILENT = false
        end)
    end)
end

                                                               
                                                               
                                                               
                                                           
                                                               
local BTR_VERSION = "v2.7"
local BTR_TOUR_FLAG_FILE = "btr_interactive_tour_v5.flag"
local BTR_PATCH_FLAG_FILE = "btr_patchnotes_v8.flag"

                                            
_G.BTR_TOUR_COMPLETED = nil
_G.BTR_PATCHNOTES_SEEN = nil

                                            
local function _cleanupBTRTutorial()
    local CoreGui = (gethui and gethui()) or game:GetService("CoreGui")
    local lp = game:GetService("Players").LocalPlayer
    local pg = lp and lp:FindFirstChild("PlayerGui")
    
    local existingTour = CoreGui:FindFirstChild("BTR_TutorialGui") or (pg and pg:FindFirstChild("BTR_TutorialGui"))
    if existingTour then pcall(function() existingTour:Destroy() end) end

    local existingNotice = CoreGui:FindFirstChild("BTR_Welcome_Modal") or (pg and pg:FindFirstChild("BTR_Welcome_Modal"))
    if existingNotice then pcall(function() existingNotice:Destroy() end) end

    local existingPatch = CoreGui:FindFirstChild("BTR_PatchNotes_Modal") or (pg and pg:FindFirstChild("BTR_PatchNotes_Modal"))
    if existingPatch then pcall(function() existingPatch:Destroy() end) end
end
_cleanupBTRTutorial()

local function hasCompletedTour()
    if _G.BTR_TOUR_COMPLETED then return true end
    if isfile and type(isfile) == "function" then
        local ok, res = pcall(function() return isfile(BTR_TOUR_FLAG_FILE) end)
        if ok and res then return true end
    end
    return false
end

local function markTourCompleted()
    _G.BTR_TOUR_COMPLETED = true
    if writefile and type(writefile) == "function" then
        pcall(function() writefile(BTR_TOUR_FLAG_FILE, "seen") end)
    end
end

local function hasSeenPatchNotes()
    if _G.BTR_PATCHNOTES_SEEN then return true end
    if isfile and type(isfile) == "function" then
        local ok, res = pcall(function() return isfile(BTR_PATCH_FLAG_FILE) end)
        if ok and res then return true end
    end
    return false
end

local function markPatchNotesSeen()
    _G.BTR_PATCHNOTES_SEEN = true
    if writefile and type(writefile) == "function" then
        pcall(function() writefile(BTR_PATCH_FLAG_FILE, "seen") end)
    end
end

