    btnOk.BackgroundColor3 = Color3.fromRGB(240, 45, 65)
    btnOk.Font = Enum.Font.GothamBold
    btnOk.TextSize = 11
    btnOk.TextColor3 = Color3.fromRGB(255, 255, 255)
    btnOk.Text = "Explore Updates"
    btnOk.Parent = footer
    Instance.new("UICorner", btnOk).CornerRadius = UDim.new(0, 8)

    local isClosing = false
    local function dismiss(openTour)
        if isClosing then return end
        isClosing = true
        markPatchNotesSeen()
        pcall(function()
            TweenService:Create(cardStroke, TweenInfo.new(0.2), { Transparency = 1 }):Play()
            TweenService:Create(card, TweenInfo.new(0.2), { BackgroundTransparency = 1 }):Play()
            TweenService:Create(bgOverlay, TweenInfo.new(0.25), { BackgroundTransparency = 1 }):Play()
        end)
        task.wait(0.26)
        pcall(function() sg:Destroy() end)
        if openTour and startBTRTutorial then
            task.spawn(function() startBTRTutorial(true) end)
        end
    end

    btnOk.Activated:Connect(function() dismiss(false) end)
    closeBtn.Activated:Connect(function() dismiss(false) end)
    btnTour.Activated:Connect(function() dismiss(true) end)

    TweenService:Create(bgOverlay, TweenInfo.new(0.3), { BackgroundTransparency = 0.45 }):Play()
    TweenService:Create(card, TweenInfo.new(0.3), { BackgroundTransparency = 0, Position = UDim2.new(0.5, 0, 0.5, 0) }):Play()
    TweenService:Create(cardStroke, TweenInfo.new(0.3), { Transparency = 0.2 }):Play()
end
_G.BTR_ShowPatchNotes = showBTRPatchNotes

                                                               
                                                                      
                                                               
startBTRTutorial = function(force)
    if not force and hasCompletedTour() then return end

    local TweenService = game:GetService("TweenService")
    local CoreGui = (gethui and gethui()) or game:GetService("CoreGui")
    local Players = game:GetService("Players")
    local lp = Players.LocalPlayer
    if not lp then return end

    _cleanupBTRTutorial()

    local sg = Instance.new("ScreenGui")
    sg.Name = "BTR_TutorialGui"
    sg.ResetOnSpawn = false
    sg.IgnoreGuiInset = true
    sg.DisplayOrder = 1000001
    pcall(function() sg.Parent = CoreGui end)
    if not sg.Parent then sg.Parent = lp:WaitForChild("PlayerGui") end

    local backdrop = Instance.new("TextButton")
    backdrop.Name = "TutorialBackdrop"
    backdrop.Text = ""
    backdrop.AutoButtonColor = false
    backdrop.Size = UDim2.new(1, 0, 1, 0)
    backdrop.BackgroundColor3 = Color3.fromRGB(6, 8, 12)
    backdrop.BackgroundTransparency = 0.55
    backdrop.BorderSizePixel = 0
    backdrop.Parent = sg

    local spotlight = Instance.new("Frame")
    spotlight.Name = "SpotlightBox"
    spotlight.BackgroundTransparency = 1
    spotlight.BorderSizePixel = 0
    spotlight.Visible = false
    spotlight.Parent = sg

