    local sStroke = Instance.new("UIStroke", spotlight)
    sStroke.Color = Color3.fromRGB(0, 245, 255)
    sStroke.Thickness = 2.4

    task.spawn(function()
        while spotlight and spotlight.Parent do
            TweenService:Create(sStroke, TweenInfo.new(0.7, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
                Color = Color3.fromRGB(255, 60, 80)
            }):Play()
            task.wait(0.75)
            if not spotlight or not spotlight.Parent then break end
            TweenService:Create(sStroke, TweenInfo.new(0.7, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
                Color = Color3.fromRGB(0, 245, 255)
            }):Play()
            task.wait(0.75)
        end
