    badge.Size = UDim2.new(0, 110, 0, 22)
    badge.Position = UDim2.new(0, 16, 0.5, -11)
    badge.BackgroundColor3 = Color3.fromRGB(0, 210, 255)
    badge.BackgroundTransparency = 0.8
    badge.Text = "STEP 1 OF 5"
    badge.TextColor3 = Color3.fromRGB(0, 230, 255)
    badge.Font = Enum.Font.GothamBold
    badge.TextSize = 10
    badge.Parent = header
    Instance.new("UICorner", badge).CornerRadius = UDim.new(0, 6)

    local btnSkip = Instance.new("TextButton")
    btnSkip.Size = UDim2.new(0, 70, 0, 24)
    btnSkip.Position = UDim2.new(1, -84, 0.5, -12)
    btnSkip.BackgroundColor3 = Color3.fromRGB(28, 30, 42)
    btnSkip.Text = "Skip"
    btnSkip.TextColor3 = Color3.fromRGB(180, 185, 200)
    btnSkip.Font = Enum.Font.GothamMedium
    btnSkip.TextSize = 10
    btnSkip.Parent = header
    Instance.new("UICorner", btnSkip).CornerRadius = UDim.new(0, 6)

    local scroll = Instance.new("ScrollingFrame")
    scroll.Size = UDim2.new(1, 0, 1, -102)
