    sLayout.Padding = UDim.new(0, 8)

    local titleLbl = Instance.new("TextLabel")
    titleLbl.LayoutOrder = 1
    titleLbl.Size = UDim2.new(1, 0, 0, 22)
    titleLbl.BackgroundTransparency = 1
    titleLbl.Text = ""
    titleLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
    titleLbl.Font = Enum.Font.GothamBold
    titleLbl.TextSize = 14
    titleLbl.TextXAlignment = Enum.TextXAlignment.Left
    titleLbl.Parent = scroll

    local bodyLbl = Instance.new("TextLabel")
    bodyLbl.LayoutOrder = 2
    bodyLbl.Size = UDim2.new(1, 0, 0, 0)
    bodyLbl.AutomaticSize = Enum.AutomaticSize.Y
    bodyLbl.BackgroundTransparency = 1
    bodyLbl.Text = ""
    bodyLbl.TextColor3 = Color3.fromRGB(190, 195, 215)
    bodyLbl.Font = Enum.Font.Gotham
    bodyLbl.TextSize = 11
    bodyLbl.TextWrapped = true
    bodyLbl.TextXAlignment = Enum.TextXAlignment.Left
    bodyLbl.LineHeight = 1.25
    bodyLbl.Parent = scroll

    local tipBox = Instance.new("Frame")
    tipBox.LayoutOrder = 3
    tipBox.Size = UDim2.new(1, 0, 0, 0)
    tipBox.AutomaticSize = Enum.AutomaticSize.Y
