    tipBox.BorderSizePixel = 0
    tipBox.Parent = scroll
    Instance.new("UICorner", tipBox).CornerRadius = UDim.new(0, 8)
    local tStroke = Instance.new("UIStroke", tipBox)
    tStroke.Color = Color3.fromRGB(0, 220, 255)
    tStroke.Thickness = 1

    local tipPad = Instance.new("UIPadding", tipBox)
    tipPad.PaddingTop = UDim.new(0, 6)
    tipPad.PaddingBottom = UDim.new(0, 6)
    tipPad.PaddingLeft = UDim.new(0, 10)
    tipPad.PaddingRight = UDim.new(0, 10)

    local tipLbl = Instance.new("TextLabel")
    tipLbl.Size = UDim2.new(1, 0, 0, 0)
    tipLbl.AutomaticSize = Enum.AutomaticSize.Y
