    tipLbl.TextColor3 = Color3.fromRGB(0, 240, 255)
    tipLbl.Font = Enum.Font.GothamMedium
    tipLbl.TextSize = 10
    tipLbl.TextWrapped = true
    tipLbl.TextXAlignment = Enum.TextXAlignment.Left
    tipLbl.Parent = tipBox

    local footer = Instance.new("Frame")
    footer.Size = UDim2.new(1, 0, 0, 52)
    footer.Position = UDim2.new(0, 0, 1, -52)
    footer.BackgroundColor3 = Color3.fromRGB(20, 23, 32)
    footer.BorderSizePixel = 0
    footer.Parent = card
    Instance.new("UICorner", footer).CornerRadius = UDim.new(0, 14)

    local btnBack = Instance.new("TextButton")
    btnBack.Size = UDim2.new(0, 85, 0, 32)
    btnBack.Position = UDim2.new(0, 14, 0.5, -16)
    btnBack.BackgroundColor3 = Color3.fromRGB(30, 34, 48)
    btnBack.Text = "< Previous"
    btnBack.TextColor3 = Color3.fromRGB(180, 185, 205)
    btnBack.Font = Enum.Font.GothamBold
    btnBack.TextSize = 11
    btnBack.Parent = footer
    Instance.new("UICorner", btnBack).CornerRadius = UDim.new(0, 8)

    local stepDots = Instance.new("TextLabel")
    stepDots.Size = UDim2.new(1, -210, 1, 0)
    stepDots.Position = UDim2.new(0, 105, 0, 0)
    stepDots.BackgroundTransparency = 1
    stepDots.Text = "● ○ ○ ○ ○"
    stepDots.TextColor3 = Color3.fromRGB(0, 210, 255)
    stepDots.Font = Enum.Font.GothamBold
    stepDots.TextSize = 13
    stepDots.Parent = footer

    local btnNext = Instance.new("TextButton")
    btnNext.Size = UDim2.new(0, 95, 0, 32)
    btnNext.Position = UDim2.new(1, -109, 0.5, -16)
    btnNext.BackgroundColor3 = Color3.fromRGB(0, 180, 240)
    btnNext.Text = "Next >"
    btnNext.TextColor3 = Color3.fromRGB(255, 255, 255)
    btnNext.Font = Enum.Font.GothamBold
    btnNext.TextSize = 11
    btnNext.Parent = footer
    Instance.new("UICorner", btnNext).CornerRadius = UDim.new(0, 8)

    local steps = {
        {
            badge = "STEP 1 OF 5",
            title = "Navigation & Search",
            body = "Toggle the hub anytime with [RightControl] on PC or by tapping the floating BTR button on mobile.\n\nUse the top search bar to instantly find any feature without scrolling through tabs.",
            tip = "The floating BTR icon is draggable anywhere on your screen.",
            getTarget = function()
                return _G.BTR_GetHubFrame and _G.BTR_GetHubFrame()
            end
        },
        {
            badge = "STEP 2 OF 5",
            title = "Prop Trolls & Cleanup Rules",
            body = "Troll tabs use Brookhaven's PropMaker to spawn lethal synced physics objects (Bring, Monster, Orbit, Void, Vuivre) that lock onto targets.\n\nThe script automatically removes the cardboard box 1s after placing props so your hands stay free.",
            tip = "RULE: Always click [Clear All Props] when turning off a troll to completely wipe props and prevent glitches.",
            getTarget = function()
                return _G.BTR_GetHubFrame and _G.BTR_GetHubFrame()
            end
        },
        {
            badge = "STEP 3 OF 5",
            title = "FE Morphs & Wear Cooldown",
            body = "Transform into Goku, Spider-Man, Sonic.Exe, or C00lkid with custom sound effects, animations, and tool abilities.\n\nBrookhaven requires a 2.1-second delay between outfit accessories-the script automatically queues items with this timing so the server accepts the morph.",
            tip = "Use [Remove Tools Morph] in Morph Tools Management to reset all morph items and tools at once.",
            getTarget = function()
                return _G.BTR_GetHubFrame and _G.BTR_GetHubFrame()
            end
        },
        {
            badge = "STEP 4 OF 5",
            title = "Protection & Anti-AFK",
            body = "Keep your character secure with Anti-Sit, Anti-Copy, and built-in Anti-AFK so Roblox doesn't kick you after 20 minutes.\n\nServer Hop in Settings lets you quickly switch between empty or crowded Brookhaven servers.",
            tip = "Anti-AFK runs automatically in the background.",
            getTarget = function()
                return _G.BTR_GetHubFrame and _G.BTR_GetHubFrame()
            end
        },
        {
            badge = "STEP 5 OF 5",
            title = "Themes & Replayability",
            body = "Customize wallpapers, accent colors, and UI scale in the Settings tab.\n\nYou can replay this walkthrough anytime via [Settings -> Replay Guided Tutorial] or check latest updates via [View Patch Notes & Updates].",
            tip = "All hub preferences are auto-saved to your executor workspace.",
            getTarget = function()
                return _G.BTR_GetHubFrame and _G.BTR_GetHubFrame()
            end
        }
    }

    local currentStep = 1

    local function updateStep(stepIndex)
        currentStep = math.clamp(stepIndex, 1, #steps)
        local data = steps[currentStep]

        badge.Text = data.badge
        titleLbl.Text = data.title
        bodyLbl.Text = data.body
        tipLbl.Text = data.tip

        local dots = ""
        for i = 1, #steps do
            dots = dots .. (i == currentStep and "● " or "○ ")
        end
        stepDots.Text = dots:sub(1, -2)

        btnBack.Visible = (currentStep > 1)

        if currentStep == #steps then
            btnNext.Text = "Done"
            btnNext.BackgroundColor3 = Color3.fromRGB(60, 210, 110)
        else
            btnNext.Text = "Next >"
            btnNext.BackgroundColor3 = Color3.fromRGB(0, 180, 240)
        end

        pcall(function()
            local target = data.getTarget and data.getTarget()
            if target and target.Parent and target.Visible then
                spotlight.Visible = true
                local pos = target.AbsolutePosition
                local size = target.AbsoluteSize
                spotlight.Position = UDim2.new(0, pos.X - 6, 0, pos.Y - 6)
                spotlight.Size = UDim2.new(0, size.X + 12, 0, size.Y + 12)
            else
                spotlight.Visible = false
            end
        end)
    end

    local isClosing = false
    local function finishTour()
        if isClosing then return end
        isClosing = true
        markTourCompleted()
        pcall(function()
            TweenService:Create(cStroke, TweenInfo.new(0.2), { Transparency = 1 }):Play()
            TweenService:Create(card, TweenInfo.new(0.2), { BackgroundTransparency = 1 }):Play()
            TweenService:Create(backdrop, TweenInfo.new(0.25), { BackgroundTransparency = 1 }):Play()
            if spotlight then spotlight.Visible = false end
        end)
        task.wait(0.26)
        pcall(function() sg:Destroy() end)
    end

    btnNext.Activated:Connect(function()
        if currentStep < #steps then
            updateStep(currentStep + 1)
        else
            finishTour()
        end
    end)

    btnBack.Activated:Connect(function()
        if currentStep > 1 then
            updateStep(currentStep - 1)
        end
    end)

    btnSkip.Activated:Connect(function()
        finishTour()
    end)

    updateStep(1)
end
