_G.BTR_GetHubFrame = function()
    local candidates = {}
    pcall(function() table.insert(candidates, game:GetService("CoreGui")) end)
    pcall(function() if gethui then table.insert(candidates, gethui()) end end)
    pcall(function()
        local pGui = game:GetService("Players").LocalPlayer:FindFirstChild("PlayerGui")
        if pGui then table.insert(candidates, pGui) end
    end)

    for _, container in ipairs(candidates) do
        local redzGui = container:FindFirstChild("redz Library V5")
        if redzGui then
            local hub = redzGui:FindFirstChild("Hub")
            if hub and hub:IsA("GuiObject") then
                return hub
            end
        end
        local hub = container:FindFirstChild("Hub", true)
        if hub and hub:IsA("GuiObject") then
            return hub
        end
    end
    return nil
end

_G.BTR_SetHubScale = function(scalePercent)
    _G.BTR_HUB_SCALE = math.clamp(tonumber(scalePercent) or 100, 50, 200)
    local scaleFactor = _G.BTR_HUB_SCALE / 100
    local hub = _G.BTR_GetHubFrame()
    if hub then
        local scaleObj = hub:FindFirstChild("BTR_Hub_Scale")
        if not scaleObj then
            scaleObj = Instance.new("UIScale")
            scaleObj.Name = "BTR_Hub_Scale"
            scaleObj.Scale = scaleFactor
            scaleObj.Parent = hub
        else
            local ts = game:GetService("TweenService")
            ts:Create(scaleObj, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Scale = scaleFactor
            }):Play()
        end

        local screenGui = hub:FindFirstAncestorOfClass("ScreenGui")
        if screenGui then
            local dropHolder = screenGui:FindFirstChild("Dropdown")
            if dropHolder then
                for _, child in ipairs(dropHolder:GetChildren()) do
                    if child:IsA("GuiObject") then
                        local dScale = child:FindFirstChild("BTR_Hub_Scale")
                        if not dScale then
                            dScale = Instance.new("UIScale")
                            dScale.Name = "BTR_Hub_Scale"
                            dScale.Scale = scaleFactor
                            dScale.Parent = child
                        else
                            local ts = game:GetService("TweenService")
                            ts:Create(dScale, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                                Scale = scaleFactor
                            }):Play()
                        end
                    end
                end
            end
        end
    end
end

_G.BTR_SetWallpaper = function(name)
    _G.BTR_SELECTED_WALLPAPER = name
    local tex = _G.BTR_WALLPAPERS[name]
    if not tex then
        for k, v in pairs(_G.BTR_WALLPAPERS) do
            if k == name or k:find(tostring(name), 1, true) then
                tex = v
                break
            end
        end
    end
    if name == "Custom ID" or tex == "CUSTOM" then
        local cleanId = tostring(_G.BTR_CUSTOM_WALLPAPER_ID or ""):gsub("%D", "")
        if cleanId:len() > 3 then
            tex = "rbxassetid://" .. cleanId
        else
            tex = _G.BTR_WALLPAPERS["Default (132435635669992)"]
        end
    elseif tex == nil then
        tex = _G.BTR_WALLPAPERS["Default (132435635669992)"]
    end

    local hub = _G.BTR_GetHubFrame()
    if hub then
        local bgImg = hub:FindFirstChild("BTR_Background_Image")
        if not bgImg then
            bgImg = Instance.new("ImageLabel")
            bgImg.Name = "BTR_Background_Image"
            bgImg.Size = UDim2.new(1, 0, 1, 0)
            bgImg.Position = UDim2.new(0, 0, 0, 0)
            bgImg.BackgroundTransparency = 1
            bgImg.ScaleType = Enum.ScaleType.Crop
            bgImg.ResampleMode = Enum.ResamplerMode.Default
            bgImg.ZIndex = 0

            local corner = Instance.new("UICorner")
            corner.CornerRadius = UDim.new(0, 10)
            corner.Parent = bgImg

            bgImg.Parent = hub
        end

        local menuTrans = 1 - ((_G.BTR_MENU_OPACITY or 100) / 100)

        if tex == "" or name == "None" then
            bgImg.Visible = false
            hub.BackgroundTransparency = menuTrans
        else
            bgImg.Visible = true
            bgImg.Image = tex
            bgImg.ImageTransparency = menuTrans
            hub.BackgroundTransparency = 1

            task.spawn(function()
                pcall(function()
                    game:GetService("ContentProvider"):PreloadAsync({ bgImg })
                end)
            end)
        end

        if _G.BTR_ApplyMenuCustoms then
            _G.BTR_ApplyMenuCustoms()
        end
    end
end

_G.BTR_SetHubIcon = function(name)
    _G.BTR_SELECTED_ICON = name or "Option 1"
    local tex = _G.BTR_ICONS and _G.BTR_ICONS[_G.BTR_SELECTED_ICON]
    if _G.BTR_SELECTED_ICON == "Custom ID" or tex == "CUSTOM" then
        local cleanId = tostring(_G.BTR_CUSTOM_ICON_ID or ""):gsub("%D", "")
        if cleanId:len() > 3 then
            tex = "rbxassetid://" .. cleanId
        else
            tex = _G.BTR_ICONS["Option 1"] or _G.BTR_ICONS["Default"]
        end
    elseif not tex or tex == "" then
        tex = _G.BTR_ICONS["Option 1"] or _G.BTR_ICONS["Default"]
    end

    
    if _G.BTR_FloatingButton then
        pcall(function()
            _G.BTR_FloatingButton.Image = tex
        end)
    end

    
    pcall(function()
        local hub = _G.BTR_GetHubFrame()
        if hub then
            local topBar = hub:FindFirstChild("TopBar") or hub:FindFirstChild("Top Bar") or hub:FindFirstChild("Header")
            if topBar then
                for _, descendant in ipairs(topBar:GetDescendants()) do
                    if descendant:IsA("ImageLabel") and not descendant:FindFirstAncestor("Buttons") then
                        descendant.Image = tex
                    end
                end
            end
        end
    end)
end

local rainbowCatRunning = false
local rainbowTextRunning = false
local rainbowHeaderRunning = false

_G.BTR_ApplyNoAnimation = function()
    local hub = _G.BTR_GetHubFrame()
    if not hub then return end
    local containers = hub:FindFirstChild("Containers", true)
    if not containers then return end

    local function hookContainer(cont)
        if cont:IsA("ScrollingFrame") and not cont:FindFirstChild("BTR_NoAnimHook") then
            local tag = Instance.new("BoolValue")
            tag.Name = "BTR_NoAnimHook"
            tag.Parent = cont

            cont:GetPropertyChangedSignal("Size"):Connect(function()
                if _G.BTR_NO_ANIMATION and cont.Size ~= UDim2.new(1, 0, 1, 0) then
                    cont.Size = UDim2.new(1, 0, 1, 0)
                end
            end)
        end
    end

    for _, c in ipairs(containers:GetChildren()) do
        hookContainer(c)
        if _G.BTR_NO_ANIMATION and c:IsA("ScrollingFrame") then
            c.Size = UDim2.new(1, 0, 1, 0)
        end
    end

    if not containers:FindFirstChild("BTR_ChildAddedHook") then
        local tag = Instance.new("BoolValue")
        tag.Name = "BTR_ChildAddedHook"
        tag.Parent = containers

        containers.ChildAdded:Connect(function(child)
            hookContainer(child)
            if _G.BTR_NO_ANIMATION and child:IsA("ScrollingFrame") then
                child.Size = UDim2.new(1, 0, 1, 0)
            end
        end)
    end
end

_G.BTR_ApplyMenuCustoms = function()
    pcall(function()
        local hub = _G.BTR_GetHubFrame()
        if not hub then return end

        local menuOpacityVal = math.clamp(_G.BTR_MENU_OPACITY or 100, 5, 100)
        local menuTrans = 1 - (menuOpacityVal / 100)

                                                   
        local hubCorner = hub:FindFirstChildOfClass("UICorner")
        if not hubCorner then
            hubCorner = Instance.new("UICorner")
            hubCorner.CornerRadius = UDim.new(0, 10)
            hubCorner.Parent = hub
        end

        local screenGui = hub:FindFirstAncestorOfClass("ScreenGui")
        if screenGui and not screenGui:FindFirstChild("BTR_Hub_Shadow") then
            local shadow = Instance.new("ImageLabel")
            shadow.Name = "BTR_Hub_Shadow"
            shadow.AnchorPoint = hub.AnchorPoint
            shadow.Position = hub.Position
            shadow.Size = UDim2.new(hub.Size.X.Scale, hub.Size.X.Offset + 36, hub.Size.Y.Scale, hub.Size.Y.Offset + 36)
            shadow.BackgroundTransparency = 1
            shadow.Image = "rbxassetid://6015897843"
            shadow.ImageColor3 = Color3.fromRGB(0, 0, 0)
            shadow.ImageTransparency = 0.45
            shadow.ScaleType = Enum.ScaleType.Slice
            shadow.SliceCenter = Rect.new(49, 49, 450, 450)
            shadow.ZIndex = math.max(0, hub.ZIndex - 1)
            shadow.Visible = hub.Visible
            shadow.Parent = screenGui

            hub:GetPropertyChangedSignal("Visible"):Connect(function()
                shadow.Visible = hub.Visible
            end)
            hub:GetPropertyChangedSignal("Position"):Connect(function()
                shadow.Position = hub.Position
            end)
            hub:GetPropertyChangedSignal("Size"):Connect(function()
                shadow.Size = UDim2.new(hub.Size.X.Scale, hub.Size.X.Offset + 36, hub.Size.Y.Scale, hub.Size.Y.Offset + 36)
            end)
        end

        local hubStroke = hub:FindFirstChild("BTR_Hub_ContrastStroke")
        if not hubStroke then
            hubStroke = Instance.new("UIStroke")
            hubStroke.Name = "BTR_Hub_ContrastStroke"
            hubStroke.Thickness = 1.3
            hubStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            hubStroke.Color = Color3.fromRGB(255, 255, 255)

            local grad = Instance.new("UIGradient")
            grad.Name = "ContrastGrad"
            grad.Rotation = 45
            grad.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0.00, Color3.fromRGB(0, 220, 255)),
                ColorSequenceKeypoint.new(0.50, Color3.fromRGB(160, 60, 255)),
                ColorSequenceKeypoint.new(1.00, Color3.fromRGB(0, 220, 255))
            })
            grad.Parent = hubStroke
            hubStroke.Parent = hub
        end

        local topBar = hub:FindFirstChild("Top Bar", true) or hub:FindFirstChild("TopBar", true) or hub:FindFirstChild("Header", true)
        if topBar and not topBar:FindFirstChild("BTR_TopBar_Accent") then
            local accent = Instance.new("Frame")
            accent.Name = "BTR_TopBar_Accent"
            accent.Size = UDim2.new(1, 0, 0, 1)
            accent.Position = UDim2.new(0, 0, 1, -1)
            accent.BorderSizePixel = 0
            accent.BackgroundColor3 = Color3.fromRGB(0, 220, 255)

            local aGrad = Instance.new("UIGradient")
            aGrad.Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 1),
                NumberSequenceKeypoint.new(0.5, 0.2),
                NumberSequenceKeypoint.new(1, 1)
            })
            aGrad.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.fromRGB(0, 220, 255)),
                ColorSequenceKeypoint.new(0.5, Color3.fromRGB(170, 60, 255)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(0, 220, 255))
            })
            aGrad.Parent = accent
            accent.Parent = topBar
        end

        local bgImg = hub:FindFirstChild("BTR_Background_Image")
        if bgImg and bgImg.Visible and bgImg.Image ~= "" then
            bgImg.ImageTransparency = menuTrans
            hub.BackgroundTransparency = 1
        else
            hub.BackgroundTransparency = menuTrans
        end

                                                           
        if _G.BTR_FloatingButton and _G.BTR_FloatingButton.Parent then
            local btn = _G.BTR_FloatingButton
            local fCorner = btn:FindFirstChildOfClass("UICorner")
            if not fCorner then
                fCorner = Instance.new("UICorner")
                fCorner.CornerRadius = UDim.new(0, 8)
                fCorner.Parent = btn
            end

            local fStroke = _G.BTR_FloatingStroke or btn:FindFirstChildOfClass("UIStroke")
            if not fStroke then
                fStroke = Instance.new("UIStroke")
                fStroke.Parent = btn
                _G.BTR_FloatingStroke = fStroke
            end
            fStroke.Thickness = 1.6
            fStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            fStroke.Color = Color3.fromRGB(255, 255, 255)

            local fGrad = fStroke:FindFirstChild("RainbowSheen")
            if not fGrad then
                fGrad = Instance.new("UIGradient")
                fGrad.Name = "RainbowSheen"
                fGrad.Color = ColorSequence.new({
                    ColorSequenceKeypoint.new(0.00, Color3.fromRGB(255, 0, 70)),
                    ColorSequenceKeypoint.new(0.18, Color3.fromRGB(255, 140, 0)),
                    ColorSequenceKeypoint.new(0.36, Color3.fromRGB(255, 235, 0)),
                    ColorSequenceKeypoint.new(0.54, Color3.fromRGB(0, 255, 140)),
                    ColorSequenceKeypoint.new(0.72, Color3.fromRGB(0, 190, 255)),
                    ColorSequenceKeypoint.new(0.90, Color3.fromRGB(190, 50, 255)),
                    ColorSequenceKeypoint.new(1.00, Color3.fromRGB(255, 0, 70))
                })
                fGrad.Parent = fStroke

                local ts = game:GetService("TweenService")
                local rotTween = ts:Create(fGrad, TweenInfo.new(4, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1), {
                    Rotation = 360
                })
                rotTween:Play()
            end
        end

        
        local catOpacityVal = math.clamp(_G.BTR_CATEGORY_OPACITY or 100, 0, 100)
        local catTrans = 1 - (catOpacityVal / 100)
        local catColName = _G.BTR_CATEGORY_COLOR or "White"
        local catCol = _G.BTR_CATEGORY_COLORS[catColName] or Color3.fromRGB(240, 240, 245)

        local tabScroll = hub:FindFirstChild("Tab Scroll", true)
        if tabScroll then
            for _, child in ipairs(tabScroll:GetChildren()) do
                if child:IsA("TextButton") or child:IsA("GuiButton") then
                    
                    child.BackgroundTransparency = catTrans
                    if catColName ~= "Rainbow" then
                        rainbowCatRunning = false
                        if catColName == "White" then
                            
                            child.BackgroundColor3 = Color3.fromRGB(245, 245, 250)
                        else
                            child.BackgroundColor3 = catCol
                        end
                    end

                    
                    for _, sub in ipairs(child:GetChildren()) do
                        if sub:IsA("TextLabel") then
                            sub.TextTransparency = catTrans * 0.4
                            if catColName == "White" then
                                
                                sub.TextColor3 = Color3.fromRGB(18, 18, 22)
                                sub.TextStrokeTransparency = 1
                            else
                                sub.TextColor3 = Color3.fromRGB(255, 255, 255)
                                sub.TextStrokeTransparency = 0.5
                                sub.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
                            end
                        elseif sub:IsA("ImageLabel") then
                            sub.ImageTransparency = catTrans * 0.4
                            if catColName == "White" then
                                
                                sub.ImageColor3 = Color3.fromRGB(18, 18, 22)
                            else
                                sub.ImageColor3 = Color3.fromRGB(255, 255, 255)
                            end
                        elseif sub:IsA("Frame") then
                            
                            sub.BackgroundTransparency = 1
                            sub.Visible = false
                        end
                    end
                end
            end
        end

        
        if catColName == "Rainbow" then
            if not rainbowCatRunning then
                rainbowCatRunning = true
                task.spawn(function()
                    while _G.BTR_CATEGORY_COLOR == "Rainbow" and hub and hub.Parent do
                        local tScroll = hub:FindFirstChild("Tab Scroll", true)
                        if tScroll then
                            local catOp = math.clamp(_G.BTR_CATEGORY_OPACITY or 100, 0, 100)
                            local cTrans = 1 - (catOp / 100)
                            local idx = 0
                            for _, child in ipairs(tScroll:GetChildren()) do
                                if child:IsA("TextButton") or child:IsA("GuiButton") then
                                    idx = idx + 1
                                    local waveCol = Color3.fromHSV((tick() * 0.35 + idx * 0.08) % 1, 0.85, 1)
                                    child.BackgroundColor3 = waveCol
                                    child.BackgroundTransparency = cTrans
                                    for _, sub in ipairs(child:GetChildren()) do
                                        if sub:IsA("TextLabel") then
                                            sub.TextColor3 = Color3.fromRGB(255, 255, 255)
                                            sub.TextStrokeTransparency = 0.4
                                            sub.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
                                            sub.TextTransparency = cTrans * 0.4
                                        elseif sub:IsA("ImageLabel") then
                                            sub.ImageColor3 = Color3.fromRGB(255, 255, 255)
                                            sub.ImageTransparency = cTrans * 0.4
                                        elseif sub:IsA("Frame") then
                                            sub.BackgroundColor3 = waveCol
                                            sub.BackgroundTransparency = cTrans
                                        end
                                    end
                                end
                            end
                        end
                        if _G.BTR_FloatingButton and _G.BTR_FloatingButton.Parent then
                            local fStroke = _G.BTR_FloatingStroke or _G.BTR_FloatingButton:FindFirstChildOfClass("UIStroke")
                            local rCol = Color3.fromHSV((tick() * 0.25) % 1, 0.85, 1)
                            if fStroke then fStroke.Color = rCol end
                        end
                        task.wait(0.06)
                    end
                    rainbowCatRunning = false
                end)
            end
        end
    end)
end

_G.BTR_ApplyTextColors = function(targetCont)
    pcall(function()
        local choice = _G.BTR_TEXT_COLOR or "Default"
        if choice == "Default" then
            return
        end

        local hub = _G.BTR_GetHubFrame()
        if not hub then return end

        local col = _G.BTR_TEXT_COLORS[choice] or Color3.fromRGB(240, 240, 245)

        local function applyToCont(cont)
            if not cont then return end
            for _, v in ipairs(cont:GetDescendants()) do
                if v:IsA("TextLabel") and v.Name ~= "Title" and v.Name ~= "SubTitle" then
                    v.TextColor3 = col
                end
            end
        end

        if choice ~= "Rainbow" then
            rainbowTextRunning = false
            if targetCont then
                applyToCont(targetCont)
            else
                local containers = hub:FindFirstChild("Containers", true)
                if containers then applyToCont(containers) end

                local rz = _G.BTR_REDZ_LIB or redzlib
                if rz and rz.Tabs then
                    for _, tabData in ipairs(rz.Tabs) do
                        if tabData.Cont then applyToCont(tabData.Cont) end
                    end
                end
            end
        else
            if not rainbowTextRunning then
                rainbowTextRunning = true
                task.spawn(function()
                    while _G.BTR_TEXT_COLOR == "Rainbow" and rainbowTextRunning and hub and hub.Parent do
                        local cList = hub:FindFirstChild("Containers", true)
                        if cList then
                            local i = 0
                            for _, v in ipairs(cList:GetDescendants()) do
                                if v:IsA("TextLabel") and v.Name ~= "Title" and v.Name ~= "SubTitle" then
                                    i = i + 1
                                    v.TextColor3 = Color3.fromHSV((tick() * 0.3 + i * 0.03) % 1, 0.85, 1)
                                end
                            end
                        end
                        task.wait(0.08)
                    end
                    rainbowTextRunning = false
                    if _G.BTR_ApplyTextColors then _G.BTR_ApplyTextColors() end
                end)
            end
        end
    end)
end

_G.BTR_ApplyHeaderStyle = function()
    pcall(function()
        local hub = _G.BTR_GetHubFrame()
        if not hub then return end

        local fontName = _G.BTR_TITLE_FONT or "GothamBlack"
        local chosenFont = _G.BTR_TITLE_FONTS[fontName] or Enum.Font.GothamBlack

        local styleName = _G.BTR_TITLE_STYLE or "Cyberpunk (Pink & Cyan)"
        local styleData = _G.BTR_TITLE_STYLES[styleName]

        
        local topBar = hub:FindFirstChild("Top Bar", true) or hub:FindFirstChild("TopBar", true) or hub:FindFirstChild("Header", true)
        local titleLabel = nil
        local subTitleLabel = nil

        if topBar then
            titleLabel = topBar:FindFirstChild("Title") or topBar:FindFirstChildWhichIsA("TextLabel")
            subTitleLabel = (titleLabel and titleLabel:FindFirstChild("SubTitle")) or topBar:FindFirstChild("SubTitle", true)
        else
            for _, desc in ipairs(hub:GetDescendants()) do
                if desc:IsA("TextLabel") and not desc:FindFirstAncestor("Containers") and not desc:FindFirstAncestor("MainScroll") then
                    if desc.Name == "Title" then
                        titleLabel = desc
                    elseif desc.Name == "SubTitle" then
                        subTitleLabel = desc
                    end
                end
            end
        end

        if titleLabel then
            titleLabel.RichText = true
            titleLabel.Font = chosenFont
            titleLabel.TextSize = 20
            titleLabel.TextStrokeTransparency = 0.6
            titleLabel.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
            if type(styleData) == "table" and styleData.format then
                titleLabel.Text = styleData.format
            end
        end

        if subTitleLabel then
            subTitleLabel.RichText = true
            subTitleLabel.Font = chosenFont
            subTitleLabel.TextSize = 13
            if type(styleData) == "table" and styleData.sub then
                subTitleLabel.Text = styleData.sub
            end
        end

        if styleName == "Rainbow Chroma (Animated Wave)" then
            if not rainbowHeaderRunning then
                rainbowHeaderRunning = true
                task.spawn(function()
                    while _G.BTR_TITLE_STYLE == "Rainbow Chroma (Animated Wave)" and hub and hub.Parent do
                        local t1 = Color3.fromHSV(tick() * 0.4 % 1, 0.9, 1):ToHex()
                        local t2 = Color3.fromHSV((tick() * 0.4 + 0.3) % 1, 0.9, 1):ToHex()
                        if titleLabel and titleLabel.Parent then
                            titleLabel.RichText = true
                            titleLabel.Text = "<font color=\"#" .. t1 .. "\"><b>BTR</b></font> <font color=\"#" .. t2 .. "\"><b>CLIENT</b></font>"
                        end
                        if subTitleLabel and subTitleLabel.Parent then
                            subTitleLabel.RichText = true
                            subTitleLabel.Text = "<font color=\"#" .. t2 .. "\">by</font> <font color=\"#" .. t1 .. "\"><b>Ash</b></font>"
                        end
                        task.wait(0.06)
                    end
                    rainbowHeaderRunning = false
                end)
            end
        end
    end)
end

pcall(function()
    task.spawn(function()
        local hubFrame = nil
        for attempt = 1, 60 do
            hubFrame = _G.BTR_GetHubFrame()
