        btn.Position = UDim2.new(0, 20, 0, 20) 
        btn.Name = "BTR_Floating_Toggle"
        btn.Visible = false

        
        local function toggleHub()
            local hub = _G.BTR_GetHubFrame()
            if hub then
                hub.Visible = not hub.Visible
            elseif Window and Window.Minimize then
                pcall(function() Window:Minimize() end)
            end
        end

        
        btn.Activated:Connect(toggleHub)
        btn.MouseButton1Click:Connect(toggleHub)

        _G.BTR_FloatingButton = btn
        _G.BTR_FloatingStroke = minimizeObj.Stroke
    end

    
    local uis = game:GetService("UserInputService")
    uis.InputBegan:Connect(function(input, gpe)
        if not gpe and (input.KeyCode == Enum.KeyCode.RightControl) then
            local hub = _G.BTR_GetHubFrame()
            if hub then
                hub.Visible = not hub.Visible
            elseif Window and Window.Minimize then
                pcall(function() Window:Minimize() end)
            end
        end
    end)
end)

