local OwnerTab = nil
local function _verifyBtrOwnerIdentity(plr)
    plr = plr or game:GetService("Players").LocalPlayer
    if not plr or not plr:IsA("Player") then return false end
                                                      
    return (plr.UserId == 10909094240 or (bit32 and bit32.bxor(plr.UserId % 4294967296, 2018809492) == 0))
end

if _verifyBtrOwnerIdentity(_infoLP) then
    OwnerTab = Window:MakeTab({
        "Owner",
        "rbxassetid://10723415766"
    })
end
