        _speedConn = game:GetService("RunService").Heartbeat:Connect(function()
            local h = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
            if h and _customSpeed > 16 and h.WalkSpeed ~= _customSpeed then
                h.WalkSpeed = _customSpeed
            end
        end)
