    if not UIS.TouchEnabled then return end

    local pg = lp and lp:FindFirstChild("PlayerGui")
    if not pg then return end

    local sg = Instance.new("ScreenGui")
    sg.Name = "BTR_FlyMobileGui"
    sg.ResetOnSpawn = false
    sg.DisplayOrder = 9999
    pcall(function() sg.Parent = game:GetService("CoreGui") end)
    if not sg.Parent then sg.Parent = pg end
    _flyMobileGui = sg

    local container = Instance.new("Frame")
    container.Size = UDim2.new(0, 54, 0, 114)
    container.Position = UDim2.new(1, -70, 0.5, -57)
    container.BackgroundTransparency = 1
    container.Parent = sg

    local upBtn = Instance.new("TextButton")
    upBtn.Size = UDim2.new(1, 0, 0, 52)
    upBtn.Position = UDim2.new(0, 0, 0, 0)
    upBtn.BackgroundColor3 = Color3.fromRGB(18, 20, 28)
    upBtn.BackgroundTransparency = 0.25
    upBtn.Text = "▲"
    upBtn.TextColor3 = Color3.fromRGB(0, 220, 255)
    upBtn.TextSize = 20
    upBtn.Font = Enum.Font.GothamBold
    upBtn.Parent = container

    local upCorner = Instance.new("UICorner")
    upCorner.CornerRadius = UDim.new(0, 10)
    upCorner.Parent = upBtn

    local upStroke = Instance.new("UIStroke")
    upStroke.Color = Color3.fromRGB(0, 200, 255)
    upStroke.Thickness = 1.2
    upStroke.Parent = upBtn

