PlayerTab:AddToggle({
    Name = "Fly",
    Description = "WASD / Joystick to move | Space / ▲ to ascend | Shift / ▼ to descend",
    Default = false,
    Callback = function(value)
        local lp  = game:GetService("Players").LocalPlayer
        local UIS = game:GetService("UserInputService")
        local RS  = game:GetService("RunService")
        if not value then
            if _flyConn then _flyConn:Disconnect(); _flyConn = nil end
            if _flyBG then _flyBG:Destroy(); _flyBG = nil end
            if _flyBV then _flyBV:Destroy(); _flyBV = nil end
            _cleanupFlyMobileControls()
            local char = lp.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hum then
                hum.PlatformStand = false
                pcall(function() hum:ChangeState(Enum.HumanoidStateType.Freefall) end)
            end
            if hrp then hrp.AssemblyLinearVelocity = Vector3.new(0,0,0) end
            return
        end
        local char = lp.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum then return end

        hum.PlatformStand = false
        pcall(function()
            hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
            hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)
            hum:ChangeState(Enum.HumanoidStateType.Freefall)
        end)

        _flyBG = Instance.new("BodyGyro", hrp)
        _flyBG.P = 9e4
        _flyBG.MaxTorque = Vector3.new(9e9, 9e9, 9e9)
        _flyBG.CFrame = hrp.CFrame

        _flyBV = Instance.new("BodyVelocity", hrp)
        _flyBV.Velocity = Vector3.new(0, 0, 0)
        _flyBV.MaxForce = Vector3.new(9e9, 9e9, 9e9)

        _setupFlyMobileControls()

        _flyConn = RS.Heartbeat:Connect(function()
            local c = lp.Character
            local h = c and c:FindFirstChild("HumanoidRootPart")
            local hm = c and c:FindFirstChildOfClass("Humanoid")
            if not h or not hm or not _flyBV or not _flyBG then return end
            local cam = workspace.CurrentCamera
            if not cam then return end

            local camCF = cam.CFrame
            local camLook = camCF.LookVector
            local camRight = camCF.RightVector
            local dir = Vector3.new(0, 0, 0)
            local spd = 60

            if UIS:IsKeyDown(Enum.KeyCode.W) then dir = dir + camLook end
            if UIS:IsKeyDown(Enum.KeyCode.S) then dir = dir - camLook end
            if UIS:IsKeyDown(Enum.KeyCode.A) then dir = dir - camRight end
            if UIS:IsKeyDown(Enum.KeyCode.D) then dir = dir + camRight end
            if UIS:IsKeyDown(Enum.KeyCode.Space) then dir = dir + Vector3.new(0, 1, 0) end
            if UIS:IsKeyDown(Enum.KeyCode.LeftShift) then dir = dir - Vector3.new(0, 1, 0) end

            local moveDir = hm.MoveDirection
            if moveDir.Magnitude > 0.05 then
                local camLookH = Vector3.new(camLook.X, 0, camLook.Z)
                if camLookH.Magnitude > 0.01 then camLookH = camLookH.Unit end
                local camRightH = Vector3.new(camRight.X, 0, camRight.Z)
                if camRightH.Magnitude > 0.01 then camRightH = camRightH.Unit end

                local fwd = moveDir:Dot(camLookH)
                local stf = moveDir:Dot(camRightH)
                dir = dir + (camLook * fwd) + (camRight * stf)
            end

            if hm.Jump then
                dir = dir + Vector3.new(0, 1, 0)
            end

            if _flyMobileUp then dir = dir + Vector3.new(0, 1, 0) end
            if _flyMobileDown then dir = dir - Vector3.new(0, 1, 0) end

            _flyBV.Velocity = (dir.Magnitude > 0) and (dir.Unit * spd) or Vector3.new(0, 0, 0)
            _flyBG.CFrame = camCF
        end)
    end
})

local _noClipConn = nil
local _noClipParts = {}
PlayerTab:AddToggle({
    Name = "NoClip",
    Description = "Walk through walls and objects",
    Default = false,
    Callback = function(value)
        if _noClipConn then
            _noClipConn:Disconnect()
            _noClipConn = nil
        end
        
        local lp = game:GetService("Players").LocalPlayer
        
        if not value then
            for part, _ in pairs(_noClipParts) do
                if part and part.Parent then
                    pcall(function() part.CanCollide = true end)
                end
            end
            _noClipParts = {}
            return
        end
        
        _noClipParts = {}
        _noClipConn = game:GetService("RunService").Stepped:Connect(function()
            local char = lp.Character
            if not char then return end
            for _, p in ipairs(char:GetDescendants()) do
                if p:IsA("BasePart") and p.CanCollide == true and p.Name ~= "HumanoidRootPart" and not p:IsA("Accessory") and p.Parent and not p.Parent:IsA("Accessory") then
                    p.CanCollide = false
                    _noClipParts[p] = true
                end
            end
        end)
    end
})

