local InvisActive       = false
local invisToggleRef    = nil
local invisClone        = nil
local invisRealChar     = nil
local invisDiedConn     = nil
local invisSteppedConn  = nil
local invisCamConn      = nil

local DesyncActive      = false
local desyncToggleRef   = nil
local desyncClone       = nil
local desyncHighlight   = nil
local desyncRealChar    = nil
local desyncDiedConn    = nil
local desyncFrozenCF    = nil
local desyncSteppedConn = nil
local desyncCamConn     = nil

local function stopInvisible()
    if invisDiedConn then
        invisDiedConn:Disconnect()
        invisDiedConn = nil
    end
    if invisSteppedConn then
        invisSteppedConn:Disconnect()
        invisSteppedConn = nil
    end
    if invisCamConn then
        invisCamConn:Disconnect()
        invisCamConn = nil
    end

    local lp = game:GetService("Players").LocalPlayer
    local returnCF = nil

    if invisClone and invisClone:FindFirstChild("HumanoidRootPart") then
        returnCF = invisClone.HumanoidRootPart.CFrame
    end

    local char = invisRealChar or lp.Character
    if char and char.Parent then
        char.Parent = workspace
        local root = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChildOfClass("Humanoid")
        if root then
            root.Anchored = false
            if returnCF then
                root.CFrame = returnCF
            end
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end
        for _, p in ipairs(char:GetDescendants()) do
            if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and not p:IsA("Accessory") and p.Parent and not p.Parent:IsA("Accessory") then
                p.CanCollide = true
            end
        end
        lp.Character = char
        local cam = workspace.CurrentCamera
        if cam and hum then
            cam.CameraType = Enum.CameraType.Custom
            cam.CameraSubject = hum
        end
        local anim = char:FindFirstChild("Animate")
        if anim then
            anim.Disabled = true
            task.wait(0.05)
            anim.Disabled = false
        end
    end

    if invisClone then
        pcall(function() invisClone:Destroy() end)
        invisClone = nil
    end

    invisRealChar = nil
    InvisActive = false
end

local function stopDesync()
    if desyncDiedConn then
        desyncDiedConn:Disconnect()
        desyncDiedConn = nil
    end
    if desyncSteppedConn then
        desyncSteppedConn:Disconnect()
        desyncSteppedConn = nil
    end
    if desyncCamConn then
        desyncCamConn:Disconnect()
        desyncCamConn = nil
    end

    local lp = game:GetService("Players").LocalPlayer
    local returnCF = desyncFrozenCF

    if desyncClone and desyncClone:FindFirstChild("HumanoidRootPart") then
        returnCF = desyncClone.HumanoidRootPart.CFrame
    end

    if desyncHighlight then
        pcall(function() desyncHighlight:Destroy() end)
        desyncHighlight = nil
    end

    local char = desyncRealChar or lp.Character
    if char and char.Parent then
        local root = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChildOfClass("Humanoid")
        if root then
            root.Anchored = false
            if returnCF then
                root.CFrame = returnCF
            end
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end
        for _, p in ipairs(char:GetDescendants()) do
            if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and not p:IsA("Accessory") and p.Parent and not p.Parent:IsA("Accessory") then
                p.CanCollide = true
            end
        end
        lp.Character = char
        local cam = workspace.CurrentCamera
        if cam and hum then
            cam.CameraType = Enum.CameraType.Custom
            cam.CameraSubject = hum
        end
        local anim = char:FindFirstChild("Animate")
        if anim then
            anim.Disabled = true
            task.wait(0.05)
            anim.Disabled = false
        end
    end

    if desyncClone then
        pcall(function() desyncClone:Destroy() end)
        desyncClone = nil
    end

    desyncFrozenCF = nil
    desyncRealChar = nil
    DesyncActive = false
end

local lp = game:GetService("Players").LocalPlayer
lp.CharacterAdded:Connect(function(newChar)
    if newChar == invisClone or newChar == desyncClone then
        return
    end
    if InvisActive then
        stopInvisible()
        if invisToggleRef then pcall(function() invisToggleRef:Set(false) end) end
    end
    if DesyncActive then
        stopDesync()
        if desyncToggleRef then pcall(function() desyncToggleRef:Set(false) end) end
    end
end)

invisToggleRef = PlayerTab:AddToggle({
    Name = "Invisible (FE)",
    Description = "Hides your server body in Lighting while you walk freely in ghost mode locally",
    Default = false,
    Callback = function(Value)
        if Value == InvisActive then return end

        if Value then
            if DesyncActive then
                stopDesync()
                if desyncToggleRef then
                    pcall(function() desyncToggleRef:Set(false) end)
                end
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = "Conflict Resolved", Text = "Desync disabled because Invisible was enabled!", Duration = 3
                })
            end

            local player = game:GetService("Players").LocalPlayer
            local char = player.Character
            if not char then return end
            local root = char:FindFirstChild("HumanoidRootPart")
            local hum = char:FindFirstChildOfClass("Humanoid")
            if not root or not hum then return end

            InvisActive = true
            invisRealChar = char
            local origCF = root.CFrame

            char.Archivable = true
            local clone = char:Clone()
            char.Archivable = false
            clone.Name = ""
            invisClone = clone

            for _, p in ipairs(clone:GetDescendants()) do
                if p:IsA("BasePart") then
                    p.Transparency = (p.Name == "HumanoidRootPart" and 1 or 0.5)
                end
            end

            char:MoveTo(Vector3.new(0, math.pi * 1000000, 0))
            local cam = workspace.CurrentCamera
            if cam then
                cam.CameraType = Enum.CameraType.Scriptable
            end
            task.wait(0.15)
            if cam then
                cam.CameraType = Enum.CameraType.Custom
            end
            char.Parent = game:GetService("Lighting")

            clone.Parent = workspace
            local cloneRoot = clone:FindFirstChild("HumanoidRootPart")
            local cloneHum = clone:FindFirstChildOfClass("Humanoid")
            if cloneRoot then
                cloneRoot.CFrame = origCF
                cloneRoot.Anchored = false
                cloneRoot.AssemblyLinearVelocity = Vector3.zero
                cloneRoot.AssemblyAngularVelocity = Vector3.zero
            end

            player.Character = clone
            if cam and cloneHum then
                cam.CameraType = Enum.CameraType.Custom
                cam.CameraSubject = cloneHum
            end

            local anim = clone:FindFirstChild("Animate")
            if anim then
                anim.Disabled = true
                task.wait(0.05)
                anim.Disabled = false
            end

            invisCamConn = game:GetService("RunService").RenderStepped:Connect(function()
                if not InvisActive or not clone or not clone.Parent or not cloneHum or cloneHum.Health <= 0 then return end
                local currentCam = workspace.CurrentCamera
                if currentCam and currentCam.CameraSubject ~= cloneHum then
                    currentCam.CameraType = Enum.CameraType.Custom
                    currentCam.CameraSubject = cloneHum
                end
            end)

            local voidHeight = workspace.FallenPartsDestroyHeight
            invisSteppedConn = game:GetService("RunService").Stepped:Connect(function()
                pcall(function()
                    if clone and clone.Parent and cloneRoot then
                        if cloneRoot.Position.Y <= (voidHeight + 25) then
                            stopInvisible()
                            if invisToggleRef then pcall(function() invisToggleRef:Set(false) end) end
                        end
                    end
                end)
            end)

            if cloneHum then
                invisDiedConn = cloneHum.Died:Connect(function()
                    stopInvisible()
                    if invisToggleRef then pcall(function() invisToggleRef:Set(false) end) end
                end)
            end

            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = "Invisible (FE)", Text = "Invisible ON! Server body hidden, camera on ghost.", Duration = 3
            })
        else
            stopInvisible()
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = "Invisible (FE)", Text = "Invisible OFF! Re-synced.", Duration = 3
            })
        end
    end
})

desyncToggleRef = PlayerTab:AddToggle({
    Name = "Desync",
    Description = "Freezes your server body where you stood while you move freely locally",
    Default = false,
    Callback = function(Value)
        if Value == DesyncActive then return end

        if Value then
            if InvisActive then
                stopInvisible()
                if invisToggleRef then
                    pcall(function() invisToggleRef:Set(false) end)
                end
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = "Conflict Resolved", Text = "Invisible disabled because Desync was enabled!", Duration = 3
                })
            end

            local player = game:GetService("Players").LocalPlayer
            local char = player.Character
            if not char then return end
            local root = char:FindFirstChild("HumanoidRootPart")
            local hum = char:FindFirstChildOfClass("Humanoid")
            if not root or not hum then return end

            DesyncActive = true
            desyncRealChar = char
            desyncFrozenCF = root.CFrame

            root.Anchored = true

            pcall(function()
                local hl = Instance.new("Highlight")
                hl.Name = "BTR_DesyncHighlight"
                hl.FillColor = Color3.fromRGB(255, 30, 30)
                hl.OutlineColor = Color3.fromRGB(255, 255, 255)
                hl.FillTransparency = 0.4
                hl.OutlineTransparency = 0
                hl.Parent = char
                desyncHighlight = hl
            end)

            char.Archivable = true
            local clone = char:Clone()
            char.Archivable = false
            clone.Name = ""
            desyncClone = clone

            for _, p in ipairs(clone:GetDescendants()) do
                if p:IsA("BasePart") then
                    p.Transparency = (p.Name == "HumanoidRootPart" and 1 or 0.5)
                end
            end

            clone.Parent = workspace
            local cloneRoot = clone:FindFirstChild("HumanoidRootPart")
            local cloneHum = clone:FindFirstChildOfClass("Humanoid")
            if cloneRoot then
                cloneRoot.CFrame = desyncFrozenCF
                cloneRoot.Anchored = false
                cloneRoot.AssemblyLinearVelocity = Vector3.zero
                cloneRoot.AssemblyAngularVelocity = Vector3.zero
            end

            player.Character = clone
            local cam = workspace.CurrentCamera
            if cam and cloneHum then
                cam.CameraType = Enum.CameraType.Custom
                cam.CameraSubject = cloneHum
            end

            local anim = clone:FindFirstChild("Animate")
            if anim then
                anim.Disabled = true
                task.wait(0.05)
                anim.Disabled = false
            end

            desyncCamConn = game:GetService("RunService").RenderStepped:Connect(function()
                if not DesyncActive or not clone or not clone.Parent or not cloneHum or cloneHum.Health <= 0 then return end
                local currentCam = workspace.CurrentCamera
                if currentCam and currentCam.CameraSubject ~= cloneHum then
                    currentCam.CameraType = Enum.CameraType.Custom
                    currentCam.CameraSubject = cloneHum
                end
            end)

            local voidHeight = workspace.FallenPartsDestroyHeight
            desyncSteppedConn = game:GetService("RunService").Stepped:Connect(function()
                pcall(function()
                    if clone and clone.Parent and cloneRoot then
                        if cloneRoot.Position.Y <= (voidHeight + 25) then
                            stopDesync()
                            if desyncToggleRef then pcall(function() desyncToggleRef:Set(false) end) end
                        end
                    end
                end)
            end)

            if cloneHum then
                desyncDiedConn = cloneHum.Died:Connect(function()
                    stopDesync()
                    if desyncToggleRef then pcall(function() desyncToggleRef:Set(false) end) end
                end)
            end

            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = "Desync", Text = "Desync ON! Server body frozen, camera on ghost.", Duration = 3
            })
        else
            stopDesync()
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = "Desync", Text = "Desync OFF! Position re-synced.", Duration = 3
            })
        end
    end
})
end

