                Duration = 3
            })
        end)
    end

    
    
    
    local function autoCorrectText(text)
        if not text or text == "" then return text end
        local s = " " .. text .. " "

        
        s = s:gsub("(%f[%a])ca va(%f[%A])", "%1ça va%2")
        s = s:gsub("(%f[%a])Ca va(%f[%A])", "%1Ça va%2")
        s = s:gsub("(%f[%a])ca(%f[%A])", "%1ça%2")
        s = s:gsub("(%f[%a])Ca(%f[%A])", "%1Ça%2")
        s = s:gsub("(%f[%a])garcon(%f[%A])", "%1garçon%2")
        s = s:gsub("(%f[%a])garcons(%f[%A])", "%1garçons%2")
        s = s:gsub("(%f[%a])francais(%f[%A])", "%1français%2")
        s = s:gsub("(%f[%a])francaise(%f[%A])", "%1française%2")
        s = s:gsub("(%f[%a])francaises(%f[%A])", "%1françaises%2")
        s = s:gsub("(%f[%a])facon(%f[%A])", "%1façon%2")
        s = s:gsub("(%f[%a])facons(%f[%A])", "%1façons%2")
        s = s:gsub("(%f[%a])lecon(%f[%A])", "%1leçon%2")
        s = s:gsub("(%f[%a])lecons(%f[%A])", "%1leçons%2")
        s = s:gsub("(%f[%a])recu(%f[%A])", "%1reçu%2")
        s = s:gsub("(%f[%a])decu(%f[%A])", "%1déçu%2")
        s = s:gsub("(%f[%a])c est(%f[%A])", "%1c'est%2")
        s = s:gsub("(%f[%a])cest(%f[%A])", "%1c'est%2")
        s = s:gsub("(%f[%a])j ai(%f[%A])", "%1j'ai%2")
        s = s:gsub("(%f[%a])jai(%f[%A])", "%1j'ai%2")
        s = s:gsub("(%f[%a])j espere(%f[%A])", "%1j'espère%2")
        s = s:gsub("(%f[%a])jespere(%f[%A])", "%1j'espère%2")
        s = s:gsub("(%f[%a])j adore(%f[%A])", "%1j'adore%2")
        s = s:gsub("(%f[%a])jadore(%f[%A])", "%1j'adore%2")
        s = s:gsub("(%f[%a])j aime(%f[%A])", "%1j'aime%2")
        s = s:gsub("(%f[%a])jaime(%f[%A])", "%1j'aime%2")
        s = s:gsub("(%f[%a])j arrive(%f[%A])", "%1j'arrive%2")
        s = s:gsub("(%f[%a])jarrive(%f[%A])", "%1j'arrive%2")
        s = s:gsub("(%f[%a])deja(%f[%A])", "%1déjà%2")
        s = s:gsub("(%f[%a])tres(%f[%A])", "%1très%2")
        s = s:gsub("(%f[%a])meme(%f[%A])", "%1même%2")
        s = s:gsub("(%f[%a])apres(%f[%A])", "%1après%2")
        s = s:gsub("(%f[%a])tkt(%f[%A])", "%1t'inquiète%2")
        s = s:gsub("(%f[%a])psk(%f[%A])", "%1parce que%2")
        s = s:gsub("(%f[%a])pck(%f[%A])", "%1parce que%2")
        s = s:gsub("(%f[%a])stp(%f[%A])", "%1s'il te plaît%2")
        s = s:gsub("(%f[%a])svp(%f[%A])", "%1s'il vous plaît%2")
        s = s:gsub("(%f[%a])dsl(%f[%A])", "%1désolé%2")
        s = s:gsub("(%f[%a])voila(%f[%A])", "%1voilà%2")
        s = s:gsub("(%f[%a])aussi(%f[%A])", "%1aussi%2")

        
        s = s:gsub("(%f[%a])dont(%f[%A])", "%1don't%2")
        s = s:gsub("(%f[%a])cant(%f[%A])", "%1can't%2")
        s = s:gsub("(%f[%a])wont(%f[%A])", "%1won't%2")
        s = s:gsub("(%f[%a])didnt(%f[%A])", "%1didn't%2")
        s = s:gsub("(%f[%a])isnt(%f[%A])", "%1isn't%2")
        s = s:gsub("(%f[%a])im(%f[%A])", "%1I'm%2")
        s = s:gsub("(%f[%a])ive(%f[%A])", "%1I've%2")
        s = s:gsub("(%f[%a])youre(%f[%A])", "%1you're%2")
        s = s:gsub("(%f[%a])theyre(%f[%A])", "%1they're%2")
        s = s:gsub("(%f[%a])idk(%f[%A])", "%1I don't know%2")
        s = s:gsub("(%f[%a])tbh(%f[%A])", "%1to be honest%2")
        s = s:gsub("(%f[%a])rn(%f[%A])", "%1right now%2")
        s = s:gsub("(%f[%a])bc(%f[%A])", "%1because%2")
        s = s:gsub("(%f[%a])pls(%f[%A])", "%1please%2")
        s = s:gsub("(%f[%a])thx(%f[%A])", "%1thank you%2")

        s = s:sub(2, -2)
        local firstChar = s:match("^%s*(%a)")
        if firstChar and firstChar:lower() == firstChar then
            s = s:gsub("^%s*" .. firstChar, firstChar:upper(), 1)
        end
        return s
    end

    
    
    
    local function requestHttp(url)
        local req = (syn and syn.request) or (http and http.request) or http_request or (fluxus and fluxus.request) or request
        if req then
            local ok, resp = pcall(function()
                return req({
                    Url = url,
                    Method = "GET",
                    Headers = {
                        ["User-Agent"] = "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"
                    }
                })
            end)
            if ok and resp and (resp.StatusCode == 200 or resp.Status == 200) then
                return resp.Body
            end
        end
        if game.HttpGet then
            local ok, res = pcall(function()
                return game:HttpGet(url)
            end)
            if ok and res then return res end
        end
        return nil
    end

    local function translateText(text, fromLang, toLang)
        if not text or text == "" then return text, fromLang end
        fromLang = fromLang or "auto"
        toLang = toLang or "es"
        if fromLang == toLang and fromLang ~= "auto" then return text, fromLang end

        local encoded = HttpService:UrlEncode(text)

        
        local gUrl = "https://clients5.google.com/translate_a/t?client=dict-chrome-ex&sl=" .. fromLang .. "&tl=" .. toLang .. "&q=" .. encoded
        local gRes = requestHttp(gUrl)
        if gRes then
            local ok, data = pcall(function() return HttpService:JSONDecode(gRes) end)
            if ok and data and type(data) == "table" and data[1] then
                local trans = nil
                local detected = nil
                if type(data[1]) == "table" then
                    trans = tostring(data[1][1] or "")
                    detected = tostring(data[1][2] or "")
                elseif type(data[1]) == "string" then
                    trans = tostring(data[1])
                end
                if trans and trans ~= "" then
                    return trans, detected
                end
            end
        end

        
        local gtxUrl = "https://translate.googleapis.com/translate_a/single?client=gtx&sl=" .. fromLang .. "&tl=" .. toLang .. "&dt=t&q=" .. encoded
        local gtxRes = requestHttp(gtxUrl)
        if gtxRes then
            local ok, data = pcall(function() return HttpService:JSONDecode(gtxRes) end)
            if ok and data and type(data) == "table" and data[1] then
                local str = ""
                for _, seg in ipairs(data[1]) do
                    if type(seg) == "table" and seg[1] then
                        str = str .. tostring(seg[1])
                    end
                end
                if str ~= "" then
                    local det = nil
                    if data[3] and type(data[3]) == "string" then
                        det = data[3]
                    elseif data[2] and type(data[2]) == "string" then
                        det = data[2]
                    end
                    return str, det
                end
            end
        end

        
        local srcPair = (fromLang == "auto" and "fr" or fromLang)
        local memUrl = "https://api.mymemory.translated.net/get?q=" .. encoded .. "&langpair=" .. srcPair .. "|" .. toLang
        local memRes = requestHttp(memUrl)
        if memRes then
            local ok, data = pcall(function() return HttpService:JSONDecode(memRes) end)
            if ok and data and data.responseData and data.responseData.translatedText then
                return tostring(data.responseData.translatedText), srcPair
            end
        end

        return text, fromLang
    end

    local function formatOutgoingMessage(original, translated, toLang)
        if _G.OutgoingFormat == "Translated Only" then
            return translated
        elseif _G.OutgoingFormat == "Trans + Original" then
            return translated .. " (" .. original .. ")"
        elseif _G.OutgoingFormat == "Tagged [LANG]" then
            return "[" .. string.upper(toLang) .. "] " .. translated
        end
        return translated
    end

    
    
    
    local function sendChatMsg(msg)
        if not msg or msg == "" then return end
        isSendingInternal = true

        local sent = false
        pcall(function()
            if TextChatService then
                local targetChannel = nil

                local cfg = TextChatService:FindFirstChildOfClass("ChatInputBarConfiguration") or TextChatService:FindFirstChild("ChatInputBarConfiguration")
                if cfg and cfg.TargetTextChannel then
                    targetChannel = cfg.TargetTextChannel
                end

                if not targetChannel then
                    local channels = TextChatService:FindFirstChild("TextChannels") or TextChatService:WaitForChild("TextChannels", 1)
                    if channels then
                        targetChannel = channels:FindFirstChild("RBXGeneral")
                        if not targetChannel then
                            for _, ch in ipairs(channels:GetChildren()) do
                                if ch:IsA("TextChannel") and ch.Name ~= "RBXSystem" then
                                    targetChannel = ch
                                    break
                                end
                            end
                        end
                    end
                end

                if targetChannel then
                    targetChannel:SendAsync(msg)
                    sent = true
                end
            end
        end)

        if not sent then
            pcall(function()
                local defaultChat = ReplicatedStorage:FindFirstChild("DefaultChatSystemChatEvents")
                local sayMsg = defaultChat and (defaultChat:FindFirstChild("SayMessageRequest") or defaultChat:WaitForChild("SayMessageRequest", 1))
                if sayMsg then
                    sayMsg:FireServer(msg, "All")
                    sent = true
                end
            end)
        end

        if not sent then
            pcall(function()
                if TextChatService and TextChatService.TextChannels then
                    local gen = TextChatService.TextChannels:FindFirstChild("RBXGeneral")
                    if gen then
                        gen:SendAsync(msg)
                        sent = true
                    end
                end
            end)
        end

        task.wait(0.12)
        isSendingInternal = false
    end

    
    
    
    local recentIncomingCache = {}
    local function isDuplicateIncoming(senderName, rawText)
        local now = os.clock()
        for k, t in pairs(recentIncomingCache) do
            if now - t > 4 then
                recentIncomingCache[k] = nil
            end
        end
        local key = tostring(senderName) .. "::" .. tostring(rawText)
        if recentIncomingCache[key] and (now - recentIncomingCache[key] < 3.0) then
            return true
        end
        recentIncomingCache[key] = now
        return false
    end

    local function displayTranslatedIncoming(senderName, original, translated, detected)
        local tag = string.upper(detected or "TRAD")
        local displayed = false

        
        pcall(function()
            if TextChatService then
                local channels = TextChatService:FindFirstChild("TextChannels")
                local rbxGeneral = channels and channels:FindFirstChild("RBXGeneral")
                if rbxGeneral then
                    rbxGeneral:DisplaySystemMessage(string.format("<font color='#00E5FF'>[%s] %s:</font> %s", tag, senderName, translated))
                    displayed = true
                end
            end
        end)

        
        if not displayed then
            pcall(function()
                StarterGui:SetCore("ChatMakeSystemMessage", {
                    Text = string.format("[%s] %s: %s", tag, senderName, translated),
                    Color = Color3.fromRGB(0, 229, 255),
                    Font = Enum.Font.SourceSansBold,
                    FontSize = Enum.FontSize.Size18
                })
            end)
        end
    end

    local function handleIncomingMessage(senderName, rawText)
        if not _G.AutoTranslateIncomingEnabled then return end
        if not rawText or rawText == "" then return end
        if senderName == LocalPlayer.Name or senderName == LocalPlayer.DisplayName then return end
        if isDuplicateIncoming(senderName, rawText) then return end

        task.spawn(function()
            local translated, detected = translateText(rawText, "auto", _G.IncomingTargetLang)
            if detected and detected:lower() == _G.IncomingTargetLang:lower() then return end
            if translated and translated ~= "" and translated:lower() ~= rawText:lower() then
                displayTranslatedIncoming(senderName, rawText, translated, detected)
            end
        end)
    end

    
    pcall(function()
        if TextChatService then
            TextChatService.MessageReceived:Connect(function(textChatMessage)
                local textSource = textChatMessage.TextSource
                if textSource then
                    local sender = Players:GetPlayerByUserId(textSource.UserId)
                    if sender and sender ~= LocalPlayer then
                        handleIncomingMessage(sender.DisplayName or sender.Name, textChatMessage.Text)
                    end
                end
            end)
        end
    end)

    
    local function hookPlayerLegacyChat(p)
        p.Chatted:Connect(function(msg)
            if p ~= LocalPlayer then
                handleIncomingMessage(p.DisplayName or p.Name, msg)
            end
        end)
    end
    for _, p in ipairs(Players:GetPlayers()) do
        hookPlayerLegacyChat(p)
    end
    Players.PlayerAdded:Connect(hookPlayerLegacyChat)

    
    
    
    
    local function isChatBar(tb)
        if not tb or not tb:IsA("TextBox") then return false end

        
        local p = tb
        while p do
            if p.Name == "RedzLib" or p.Name == "RedzLibHub" or p.Name == "BTR_UI" or p.Name == "AutoTranslateGui" then
                return false
            end
            p = p.Parent
        end

        if tb.Name == "ChatBar" then return true end
        if tb.PlaceholderText and (tb.PlaceholderText:lower():find("chat") or tb.PlaceholderText:find("Message") or tb.PlaceholderText:find("parler") or tb.PlaceholderText:find("discuter")) then
            return true
        end

        local isCore = false
        pcall(function()
            local expChat = CoreGui:FindFirstChild("ExperienceChat")
            if expChat and tb:IsDescendantOf(expChat) then
                isCore = true
            end
        end)
        if isCore then return true end

        if TextChatService then
            local cfg = TextChatService:FindFirstChildOfClass("ChatInputBarConfiguration") or TextChatService:FindFirstChild("ChatInputBarConfiguration")
            if cfg and cfg.TextBox == tb then
                return true
            end
        end

        local pg = LocalPlayer:FindFirstChildOfClass("PlayerGui")
        if pg then
            local chat = pg:FindFirstChild("Chat") or pg:FindFirstChild("ExperienceChat")
            if chat and tb:IsDescendantOf(chat) then
                return true
            end
        end

        return false
    end

    local function bindChatTextBox(tb)
        if not tb or not tb:IsA("TextBox") or hookedTextBoxes[tb] then return end
        hookedTextBoxes[tb] = true

        
        local isUpdatingLive = false
        tb:GetPropertyChangedSignal("Text"):Connect(function()
            if isUpdatingLive then return end
            if not _G.AutoCorrectEnabled then return end

            local current = tb.Text
            if not current or current == "" then return end

            local lastChar = current:sub(-1)
            if lastChar == " " or lastChar == "," or lastChar == "." or lastChar == "!" or lastChar == "?" then
                local corrected = autoCorrectText(current)
                if corrected ~= current then
                    isUpdatingLive = true
                    local oldLen = #current
                    local oldCursor = tb.CursorPosition
                    tb.Text = corrected
                    if oldCursor >= oldLen then
                        tb.CursorPosition = #corrected + 1
                    end
                    isUpdatingLive = false
                end
            end
        end)

        
        tb.FocusLost:Connect(function(enterPressed)
            if enterPressed and not isHandlingEnter then
                local rawText = tb.Text
                if rawText and rawText ~= "" and _G.AutoTranslateOutgoingEnabled then
                    isHandlingEnter = true
                    tb.Text = ""
                    task.spawn(function()
                        local toProcess = rawText
                        if _G.AutoCorrectEnabled then
                            toProcess = autoCorrectText(toProcess)
                        end
                        local trans = translateText(toProcess, "auto", _G.OutgoingTargetLang)
                        local finalMsg = formatOutgoingMessage(rawText, trans, _G.OutgoingTargetLang)
                        sendChatMsg(finalMsg)
                        task.wait(0.15)
                        isHandlingEnter = false
                    end)
                end
            end
        end)
    end

    
    UserInputService.InputBegan:Connect(function(input, gameProcessed)
        if input.KeyCode == Enum.KeyCode.Return or input.KeyCode == Enum.KeyCode.KeypadEnter then
            if isHandlingEnter then return end

            local focusedTb = UserInputService:GetFocusedTextBox()
            if not focusedTb then
                for tb, _ in pairs(hookedTextBoxes) do
                    if tb and tb.Parent and tb:IsFocused() then
                        focusedTb = tb
                        break
                    end
                end
            end

            if focusedTb and isChatBar(focusedTb) then
                local rawText = focusedTb.Text
                if rawText and rawText ~= "" then
                    if _G.AutoTranslateOutgoingEnabled then
                        isHandlingEnter = true
                        
                        focusedTb.Text = ""
                        pcall(function() focusedTb:ReleaseFocus() end)

                        task.spawn(function()
                            local toProcess = rawText
                            if _G.AutoCorrectEnabled then
                                toProcess = autoCorrectText(toProcess)
                            end

                            local trans = translateText(toProcess, "auto", _G.OutgoingTargetLang)
                            local finalMsg = formatOutgoingMessage(rawText, trans, _G.OutgoingTargetLang)

                            sendChatMsg(finalMsg)

                            task.wait(0.15)
                            isHandlingEnter = false
                        end)
                    elseif _G.AutoCorrectEnabled then
                        local corrected = autoCorrectText(rawText)
                        if corrected ~= rawText then
                            focusedTb.Text = corrected
                        end
                    end
                end
            end
        end
    end)

    
    local function scanAndBindAll()
        pcall(function()
            local focused = UserInputService:GetFocusedTextBox()
            if focused and isChatBar(focused) then
                bindChatTextBox(focused)
            end
        end)

        pcall(function()
            if TextChatService then
                local cfg = TextChatService:FindFirstChildOfClass("ChatInputBarConfiguration") or TextChatService:FindFirstChild("ChatInputBarConfiguration")
                if cfg and cfg.TextBox and cfg.TextBox:IsA("TextBox") then
                    bindChatTextBox(cfg.TextBox)
                end
            end
        end)

        pcall(function()
            local expChat = CoreGui:FindFirstChild("ExperienceChat")
            if expChat then
                for _, desc in ipairs(expChat:GetDescendants()) do
                    if desc:IsA("TextBox") then
                        bindChatTextBox(desc)
                    end
                end
            end
        end)

        pcall(function()
            local pg = LocalPlayer:FindFirstChildOfClass("PlayerGui")
            if pg then
                for _, desc in ipairs(pg:GetDescendants()) do
                    if desc:IsA("TextBox") and (desc.Name == "ChatBar" or isChatBar(desc)) then
                        bindChatTextBox(desc)
                    end
                end
            end
        end)
    end

    scanAndBindAll()

    pcall(function()
        CoreGui.DescendantAdded:Connect(function(desc)
            if desc:IsA("TextBox") and isChatBar(desc) then
                bindChatTextBox(desc)
            end
        end)
    end)

    pcall(function()
        local pg = LocalPlayer:WaitForChild("PlayerGui", 5)
        if pg then
            pg.DescendantAdded:Connect(function(desc)
                if desc:IsA("TextBox") and isChatBar(desc) then
                    bindChatTextBox(desc)
                end
            end)
        end
    end)

    
    if hookmetamethod and getnamecallmethod and newcclosure then
        pcall(function()
            local oldNamecall
            oldNamecall = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
                if not (_G.AutoTranslateOutgoingEnabled or _G.AutoCorrectEnabled) or isSendingInternal or checkcaller() then
                    return oldNamecall(self, ...)
                end

                local method = getnamecallmethod()
                local args = {...}

                local shouldProcess = _G.AutoTranslateOutgoingEnabled or _G.AutoCorrectEnabled

                
                if shouldProcess and (method == "SendAsync" or method == "sendAsync") and self:IsA("TextChannel") then
                    local rawText = args[1]
                    if typeof(rawText) == "string" and rawText ~= "" then
                        task.spawn(function()
                            local processedText = rawText
                            if _G.AutoCorrectEnabled then
                                processedText = autoCorrectText(processedText)
                            end
                            if _G.AutoTranslateOutgoingEnabled then
                                local trans = translateText(processedText, "auto", _G.OutgoingTargetLang)
                                processedText = formatOutgoingMessage(rawText, trans, _G.OutgoingTargetLang)
                            end

                            isSendingInternal = true
                            pcall(function() self:SendAsync(processedText) end)
                            task.wait(0.05)
                            isSendingInternal = false
                        end)
                        return nil
                    end
                end

                
                if shouldProcess and (method == "FireServer" or method == "fireServer") and self.Name == "SayMessageRequest" then
                    local rawText = args[1]
                    local channel = args[2] or "All"
                    if typeof(rawText) == "string" and rawText ~= "" then
                        task.spawn(function()
                            local processedText = rawText
                            if _G.AutoCorrectEnabled then
                                processedText = autoCorrectText(processedText)
                            end
                            if _G.AutoTranslateOutgoingEnabled then
                                local trans = translateText(processedText, "auto", _G.OutgoingTargetLang)
                                processedText = formatOutgoingMessage(rawText, trans, _G.OutgoingTargetLang)
                            end

                            isSendingInternal = true
                            pcall(function() self:FireServer(processedText, channel) end)
                            task.wait(0.05)
                            isSendingInternal = false
                        end)
                        return nil
                    end
                end

                return oldNamecall(self, ...)
            end))
        end)
    end

    
    
    

    
