                    if isRainbowBioActive then
                        local colBio = getInterpolatedColor(bioColorMode, bioCol1, bioCol2, bioCol3, tProg)
                        colorRemote:FireServer("PickingRPBioColor", colBio)
                    end
                end
            end)
        end
        task.wait(0.08)
    end
end)
