    pcall(function()
        local RE = game:GetService("ReplicatedStorage"):FindFirstChild("RE")
        local clr = RE and RE:FindFirstChild("1Clea1rTool1s")
        if clr then
            clr:FireServer("ClearAllTools")
            clr:FireServer("ClosePropMenu")
        end
    end)
end

    
    
    
    
    
