                    task.wait(0.08)
                end
            end)
            return true
        end

        local function sbStop()
            sbLoopRunning = false
            sbSession = sbSession + 1 
            local RE2 = game:GetService("ReplicatedStorage"):FindFirstChild("RE")
            if RE2 then
                local ct = RE2:FindFirstChild("1Clea1rTool1s")
