                sbMode = "Skeleton"
            elseif value == "Skeleton + Smoke" then
                sbMode = "Combo"
            else
                sbMode = value
            end
            warn("[SB] sbMode dropdown -> " .. tostring(sbMode))
        end)

        
        
        
        smokeColors = {"SmokePurple", "SmokeBlue", "SmokeYellow"}
        smokeColorDropdown = TrollV2Tab:AddDropdown({
            Name = "Smoke Colors",
            Description = "Choose the smoke colors (also used in Skeleton + Smoke)",
            Options = {"All 3 (Purple + Blue + Yellow)", "Purple + Blue", "Purple + Yellow", "Blue + Yellow", "Purple only", "Blue only", "Yellow only"},
            Default = "All 3 (Purple + Blue + Yellow)",
        })
        smokeColorDropdown:Callback(function(value)
            if value == "Purple + Blue" then smokeColors = {"SmokePurple", "SmokeBlue"}
            elseif value == "Purple + Yellow" then smokeColors = {"SmokePurple", "SmokeYellow"}
            elseif value == "Blue + Yellow" then smokeColors = {"SmokeBlue", "SmokeYellow"}
            elseif value == "Purple only" then smokeColors = {"SmokePurple"}
            elseif value == "Blue only" then smokeColors = {"SmokeBlue"}
            elseif value == "Yellow only" then smokeColors = {"SmokeYellow"}
