            if value then
                if not _G.TrollTarget or _G.TrollTarget == "---" then
                    pcall(function() _G.SpecialBlindToggle:Set(false) end)
                    game:GetService("StarterGui"):SetCore("SendNotification", { Title = "Special Blind", Text = "Select a target first!", Duration = 3 })
                    return
                end
