do
    local Players = game:GetService("Players")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local RunService = game:GetService("RunService")
    local LocalPlayer = Players.LocalPlayer

    local ShipSystem = {
        tornadoActive = false,
        currentShip = nil,
        antiSitWasActive = false,
        prevFling = false,
        tornadoSession = 0
    }

    
    local tornadoSpot = "Position"

    

    

    

    local tornadoHouseOwner = nil

    
    local tornadoHouseOwner = nil

    local function getHouseOwner(lot)
        local nm = lot.Name or ""
        
        local short = nm:gsub("House$", "")
        local owner = short:match("^(.*)_%d+$")
        if owner and owner ~= "" then return owner end
        
        if short ~= "" then return short end
        return nil
    end

    local function getHouseLot(ownerName)
        local lotsFolder = workspace:FindFirstChild("001_Lots")
        if not lotsFolder then return nil end
        local target = string.lower(ownerName)
        for _, lot in pairs(lotsFolder:GetChildren()) do
            if lot:IsA("Model") then
                local owner = getHouseOwner(lot)
                if owner and string.lower(owner) == target then
                    return lot
                end
            end
        end
        return nil
    end

    local function getHousePosition(ownerName)
        local lot = getHouseLot(ownerName)
        if not lot then return nil end
        
        local spawnPart = lot:FindFirstChild("HouseSpawnPosition") or lot:FindFirstChild("Spawn") or lot:FindFirstChildOfClass("SpawnLocation")
        if spawnPart then
            if spawnPart:IsA("BasePart") then
                return spawnPart.Position
            end
        end
        
        local ok, origin = pcall(function() return lot:GetBoundingBox() end)
        if ok and origin then return origin.Position end
        local pp = lot.PrimaryPart or lot:FindFirstChildOfClass("BasePart")
        if pp then return pp.Position end
        return nil
    end

    local function refreshHouseList()
        local list = {}
        local lotsFolder = workspace:FindFirstChild("001_Lots")
        if lotsFolder then
            for _, lot in pairs(lotsFolder:GetChildren()) do
                if lot:IsA("Model") then
                    local owner = getHouseOwner(lot)
                    if owner and string.find(lot.Name, "House") then
                        local dup = false
                        for _, o in pairs(list) do
                            if string.lower(tostring(o)) == string.lower(owner) then dup = true break end
                        end
                        if not dup then table.insert(list, owner) end
                    end
                end
            end
        end
        table.sort(list)
        return list
    end

    local function spawnPirateShip()
        local character = LocalPlayer.Character
        if not character then return nil end

        local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
        if not humanoidRootPart then return nil end

        humanoidRootPart.CFrame = CFrame.new(1754, -2, 58)
        task.wait(0.5)

        local re = ReplicatedStorage:WaitForChild("RE")
        local carRemote = re:FindFirstChild("1Ca1r")
        if carRemote then
            carRemote:FireServer("PickingBoat", "PirateFree")
        end
        task.wait(1)

        local vehicles = workspace:WaitForChild("Vehicles", 5)
        if vehicles then
            for _ = 1, 15 do
                local ship = vehicles:FindFirstChild(LocalPlayer.Name .. "Car")
                if ship then return ship end
                task.wait(0.2)
            end
        end
        return nil
    end

    local function playShipAudio()
        local audioID = 9068077052
        local args = {workspace, audioID, 1}

        for i = 1, 5 do
            local re = ReplicatedStorage.RE:FindFirstChild("1Gu1nSound1s")
            if re then
                re:FireServer(unpack(args))
            end

            if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
                local sound = Instance.new("Sound")
                sound.SoundId = "rbxassetid://" .. audioID
                sound.Parent = LocalPlayer.Character.HumanoidRootPart
                sound:Play()

                task.wait(1.5)
                sound:Destroy()
            end
        end
    end

    local function startTornado()
        local character = LocalPlayer.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
        if not character or not humanoid or not humanoidRootPart then return end

        local targetCenter = humanoidRootPart.Position
        if tornadoSpot == "House" and tornadoHouseOwner then
            local housePos = getHousePosition(tornadoHouseOwner)
            if housePos then
                targetCenter = housePos
            end
        end

        _G.VehicleFlingActive = true
        pcall(function()
            humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
        end)

        ShipSystem.tornadoActive = true
        ShipSystem.currentShip = spawnPirateShip()
        if not ShipSystem.currentShip then
            _G.VehicleFlingActive = false
            ShipSystem.tornadoActive = false
            return
        end

        local seat = ShipSystem.currentShip:FindFirstChild("Body")
        seat = seat and seat:FindFirstChild("VehicleSeat")
        if not seat then
            seat = ShipSystem.currentShip:FindFirstChildWhichIsA("VehicleSeat", true) or ShipSystem.currentShip:FindFirstChildWhichIsA("Seat", true)
        end
        if not seat then
            _G.VehicleFlingActive = false
            ShipSystem.tornadoActive = false
            return
        end

        if not ShipSystem.currentShip.PrimaryPart then
            ShipSystem.currentShip.PrimaryPart = seat
        end

        local sitTimeout = tick() + 6
        repeat
            task.wait(0.1)
            if not ShipSystem.tornadoActive then return end
            humanoidRootPart.CFrame = seat.CFrame * CFrame.new(0, 1, 0)
        until humanoid.SeatPart == seat or tick() > sitTimeout

        if humanoid.SeatPart ~= seat then
            _G.VehicleFlingActive = false
            ShipSystem.tornadoActive = false
            return
        end

        task.spawn(playShipAudio)

        task.delay(4, function()
            if not ShipSystem.tornadoActive then return end
            if humanoid.SeatPart then
                humanoid.Sit = false
            end
            pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.GettingUp) end)
            pcall(function() humanoid.Jump = true end)
            task.wait(0.05)
            pcall(function() humanoid.Jump = false end)
            if humanoidRootPart then
                humanoidRootPart.CFrame = CFrame.new(targetCenter + Vector3.new(0, 3, 0))
            end
            _G.VehicleFlingActive = false
        end)

        task.spawn(function()
            local re = ReplicatedStorage:WaitForChild("RE"):WaitForChild("1Player1sCa1r")
            while ShipSystem.tornadoActive and ShipSystem.currentShip and ShipSystem.currentShip.Parent do
                re:FireServer("Flip")
                task.wait(0.5)
            end
        end)

        local c = targetCenter
        local r = (tornadoSpot == "House") and 5 or 12
        local waypoints = {
            c + Vector3.new(0, 2, -r),
            c + Vector3.new(-r, 2, r),
            c + Vector3.new(r, 2, r),
            c + Vector3.new(r, 2, -r),
            c + Vector3.new(-r, 2, -r)
        }

        ShipSystem.currentShip:SetPrimaryPartCFrame(CFrame.new(waypoints[1]))

        local currentIndex = 1
        local nextIndex = 2
        local moveSpeed = 30
        local rotationSpeed = math.rad(720)
        local progress = 0
        local currentRotation = 0

        local connection
        connection = RunService.Heartbeat:Connect(function(dt)
            if not ShipSystem.tornadoActive or not ShipSystem.currentShip or not ShipSystem.currentShip.PrimaryPart or not ShipSystem.currentShip.Parent then
                connection:Disconnect()
                return
            end

            local startPos = waypoints[currentIndex]
            local endPos = waypoints[nextIndex]

            progress = progress + (moveSpeed * dt) / (startPos - endPos).Magnitude
            if progress >= 1 then
                progress = 0
                currentIndex = nextIndex
                nextIndex = (nextIndex % #waypoints) + 1
            end

            local newPos = startPos:lerp(endPos, progress)
            currentRotation = currentRotation + rotationSpeed * dt

            local cframe = CFrame.new(newPos) * CFrame.Angles(0, currentRotation, 0)
            ShipSystem.currentShip:SetPrimaryPartCFrame(cframe)
        end)
    end

    local function stopTornado()
        ShipSystem.tornadoActive = false
        _G.VehicleFlingActive = false

        task.spawn(function()
            local args = {"DeleteAllVehicles"}
            local re = ReplicatedStorage:WaitForChild("RE"):WaitForChild("1Ca1r")
            if re then
                re:FireServer(unpack(args))
            end
        end)
    end

                
    local isTornadoSpotUpdating = false 
    local _tornadoSpotLabel = "Current Position"
    local _tornadoSpotLabels = {}

    local function buildTornadoOptions()
        local opts = {"Current Position"}
        local houses = refreshHouseList()
        _tornadoSpotLabels = {}
        for _, h in pairs(houses) do
            local lbl = "House: " .. h
            table.insert(opts, lbl)
            _tornadoSpotLabels[lbl] = h
        end
        return opts
    end

    local tornadoSpotDropdown = TrollV2Tab:AddDropdown({
        Name = "Tornado Zone",
        Description = "Current Position = the ship circles around you | House: <player> = circles around that player's house",
        Options = buildTornadoOptions(),
        Default = "Current Position",
    })
    tornadoSpotDropdown:Callback(function(value)
        if isTornadoSpotUpdating then return end 
        if type(value) == "string" and string.sub(value, 1, 7) == "House: " then
            tornadoSpot = "House"
            tornadoHouseOwner = string.sub(value, 8)
        else
            tornadoSpot = "Position"
            tornadoHouseOwner = nil
        end
        _tornadoSpotLabel = value
        warn("[TORNADO V2] Spot -> " .. tostring(value))
    end)

    
    local function softRefreshTornadoSpots()
        local prevLabel = _tornadoSpotLabel
        local prevOwner = tornadoHouseOwner
        local opts = buildTornadoOptions()
        
        local stillThere = false
        if prevLabel == "Current Position" then
            stillThere = true
        elseif prevOwner and _tornadoSpotLabels["House: " .. prevOwner] then
            stillThere = true
        end
        isTornadoSpotUpdating = true
        pcall(function() tornadoSpotDropdown:Set(opts) end)
        if stillThere then
            
            
            if prevOwner then
                pcall(function() tornadoSpotDropdown:SetValue("House: " .. prevOwner) end)
            else
                pcall(function() tornadoSpotDropdown:SetValue("Current Position") end)
            end
            tornadoSpot = prevOwner and "House" or "Position"
            tornadoHouseOwner = prevOwner
            _tornadoSpotLabel = prevLabel
        else
            
            pcall(function() tornadoSpotDropdown:SetValue("Current Position") end)
            tornadoSpot = "Position"
            tornadoHouseOwner = nil
            _tornadoSpotLabel = "Current Position"
        end
        isTornadoSpotUpdating = false
    end

    
    task.spawn(function()
        local lotsFolder = workspace:WaitForChild("001_Lots", 10)
        if not lotsFolder then return end
        lotsFolder.ChildAdded:Connect(function()
            task.wait(0.5)
            pcall(softRefreshTornadoSpots)
        end)
        lotsFolder.ChildRemoved:Connect(function()
            task.wait(0.3)
            pcall(softRefreshTornadoSpots)
        end)
    end)

    
    task.spawn(function()
        local lastSig = ""
        while true do
            task.wait(12)
            local opts = buildTornadoOptions()
            local sig = table.concat(opts, "|")
            if sig ~= lastSig then
                lastSig = sig
                pcall(softRefreshTornadoSpots)
            end
        end
    end)
local tornadoLockOwner = false 
    local TornadoToggle = TrollV2Tab:AddToggle({
        Name = "Pirate Ship Tornado",
        Description = "Pulls Pirate Ship to the Square",
        Default = false
    })

    TornadoToggle:Callback(function(Value)
        if Value then
            if _G.TornadoLock then
                pcall(function() game:GetService("StarterGui"):SetCore("SendNotification", {Title="Pirate Ship Tornado", Text="Tornado already active! Turn off the other one first.", Duration=3}) end)
                TornadoToggle:SetValue(false)
                return
            end
            tornadoLockOwner = true
            _G.TornadoLock = true
            task.spawn(function()
                startTornado()
                task.wait(5)
                TornadoToggle:SetValue(false)
            end)
        else
            stopTornado()
            if tornadoLockOwner then
                tornadoLockOwner = false
                _G.TornadoLock = false
            end
        end
    end)
end

                                                                                         

do
    local Players = game:GetService("Players")
    local Workspace = game:GetService("Workspace")
    local StarterGui = game:GetService("StarterGui")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local RunService = game:GetService("RunService")
    local SoundService = game:GetService("SoundService")

    local LocalPlayer = Players.LocalPlayer

    local function bhNotify(title, text, duration)
        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = title or "Black Hole",
                Text = text or "",
                Duration = duration or 3
            })
        end)
    end

    local BLACK_HOLE_CENTER_POS = Vector3.new(-26, 21, 14)
    local PLAYER_TP_POS = Vector3.new(-27, 10, 1)

    local RE = ReplicatedStorage:WaitForChild("RE", 5)
    local ToolRemote = RE and RE:WaitForChild("1Too1l", 5)
    local ClearRemote = RE and RE:WaitForChild("1Clea1rTool1s", 5)

    local BH_PROP_NAME = "FloorCushion"
    local BH_PROP_CATEGORY = "Furniture"

    local blackHoleRunning = false
    local blackHoleSession = 0
    local blackHolePower = 50000
    local propCount = 15

    local originalWalkSpeed = 16
    local originalJumpPower = 50
    local isMovementLocked = false

    local function lockMovement(lock)
        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local root = char and char:FindFirstChild("HumanoidRootPart")

        if lock then
            isMovementLocked = true
            if hum then
                originalWalkSpeed = hum.WalkSpeed > 0 and hum.WalkSpeed or originalWalkSpeed
                originalJumpPower = hum.JumpPower > 0 and hum.JumpPower or originalJumpPower
                hum.WalkSpeed = 0
                hum.JumpPower = 0
            end
            if root then root.Anchored = true end
        else
            isMovementLocked = false
            if hum then
                hum.WalkSpeed = (originalWalkSpeed and originalWalkSpeed > 0) and originalWalkSpeed or 16
                hum.JumpPower = (originalJumpPower and originalJumpPower > 0) and originalJumpPower or 50
            end
            if root then root.Anchored = false end
        end
    end

    local blackHoleFolder = nil
    local blackHoleAnchorPart = nil
    local blackHoleAtt1 = nil
    local forcedParts = {}
    local forcedVehicles = {}
    local heartbeatConn = nil
    local descendantConn = nil

    local function findVehicleModel(part)
        if not part then return nil end
        local cur = part.Parent
        while cur and cur ~= Workspace do
            if cur:IsA("Model") then
                local vehiclesFolder = Workspace:FindFirstChild("Vehicles")
                if vehiclesFolder and cur.Parent == vehiclesFolder then
                    return cur
                end
                local wc = Workspace:FindFirstChild("WorkspaceCom")
                if wc and cur:IsDescendantOf(wc) then
                    return cur
                end
                for _, d in ipairs(cur:GetChildren()) do
                    if d:IsA("VehicleSeat") then
                        return cur
                    end
                end
                local n = cur.Name:lower()
                if n:find("heli") or n:find("car") or n:find("vehicle") or n:find("boat") or n:find("plane") then
                    return cur
                end
            end
            cur = cur.Parent
        end
        return nil
    end

    local function isBuildingDoor(part)
        local vehiclesFolder = Workspace:FindFirstChild("Vehicles")
        if vehiclesFolder and part:IsDescendantOf(vehiclesFolder) then
            return false
        end
        local wc = Workspace:FindFirstChild("WorkspaceCom")
        local helis = wc and wc:FindFirstChild("001_HeliStorage")
        if helis and part:IsDescendantOf(helis) then
            return false
        end

        local n = part.Name:lower()
        if n:find("door") or n:find("porte") or n:find("gate") then
            return true
        end
        if part.Parent and (part.Parent.Name:lower():find("door") or part.Parent.Name:lower():find("gate")) then
            return true
        end
        return false
    end

    local function cleanupGravityVoid()
        if heartbeatConn then heartbeatConn:Disconnect(); heartbeatConn = nil end
        if descendantConn then descendantConn:Disconnect(); descendantConn = nil end

        for part, data in pairs(forcedParts) do
            if typeof(data) == "table" and data.Part and data.Part.Parent then
                pcall(function()
                    if data.Align then data.Align:Destroy() end
                    if data.Torque then data.Torque:Destroy() end
                    if data.Att then data.Att:Destroy() end
                    data.Part.CanCollide = true
                    if data.Model and data.Model.Parent then
                        for _, d in ipairs(data.Model:GetDescendants()) do
                            if d:IsA("BasePart") then
                                d.CanCollide = true
                                pcall(function() d.Massless = false end)
                            elseif d:IsA("VehicleSeat") or d:IsA("Seat") then
                                d.Disabled = false
                            end
                        end
                    end
                end)
            end
        end
        forcedParts = {}
        forcedVehicles = {}

        if blackHoleFolder then
            pcall(function() blackHoleFolder:Destroy() end)
            blackHoleFolder = nil
            blackHoleAnchorPart = nil
            blackHoleAtt1 = nil
        end
    end

    local function applyGravityToPart(v)
        if not blackHoleRunning or not blackHoleAtt1 then return end
        if not v or not v:IsA("BasePart") or v.Anchored then return end
        if isBuildingDoor(v) then return end

        local myChar = LocalPlayer.Character
        if myChar and v:IsDescendantOf(myChar) then return end
        local myBp = LocalPlayer:FindFirstChild("Backpack")
        if myBp and v:IsDescendantOf(myBp) then return end
        if v == blackHoleAnchorPart then return end

        local resp = math.clamp(150 + (blackHolePower / 50), 150, 1000)
        local spinPwr = math.clamp(5000000 + (blackHolePower * 10000), 5000000, 500000000)

        local vehModel = findVehicleModel(v)
        if vehModel then
            if forcedVehicles[vehModel] then return end
            forcedVehicles[vehModel] = true

            pcall(function()
                local root = vehModel.PrimaryPart or vehModel:FindFirstChild("Body") or vehModel:FindFirstChildWhichIsA("VehicleSeat") or vehModel:FindFirstChildWhichIsA("BasePart")
                if not root or root.Anchored then return end

                for _, d in ipairs(vehModel:GetDescendants()) do
                    if d:IsA("BasePart") then
                        d.CanCollide = false
                        pcall(function() d.Massless = true end)
                        for _, x in ipairs(d:GetChildren()) do
                            if x.Name:find("BH_") then x:Destroy() end
                        end
                    elseif d:IsA("VehicleSeat") or d:IsA("Seat") then
                        d.Disabled = true
                        pcall(function() d.HandBrake = false end)
                    end
                end

                local att0 = Instance.new("Attachment")
                att0.Name = "BH_Att"
                att0.Position = Vector3.new(math.random(-4, 4), math.random(-2, 2), math.random(-4, 4))
                att0.Parent = root

                local align = Instance.new("AlignPosition")
                align.Name = "BH_Align"
                align.Mode = Enum.PositionAlignmentMode.TwoAttachment
                align.Attachment0 = att0
                align.Attachment1 = blackHoleAtt1
                align.MaxForce = math.huge
                align.MaxVelocity = math.huge
                align.Responsiveness = resp
                align.ReactionForceEnabled = false
                align.ApplyAtCenterOfMass = true
                align.Parent = root

                local torque = Instance.new("Torque")
                torque.Name = "BH_Torque"
                torque.Attachment0 = att0
                torque.RelativeTo = Enum.ActuatorRelativeTo.World
                torque.Torque = Vector3.new(
                    math.random(-1, 1) * spinPwr,
                    spinPwr,
                    math.random(-1, 1) * spinPwr
                )
                torque.Parent = root

                forcedParts[root] = {
                    Part = root,
                    Model = vehModel,
                    Align = align,
                    Torque = torque,
                    Att = att0
                }
            end)
            return
        end

        if forcedParts[v] then return end

        pcall(function()
            for _, x in ipairs(v:GetChildren()) do
                if x.Name:find("BH_") then x:Destroy() end
            end

            v.CanCollide = false

            local att0 = Instance.new("Attachment")
            att0.Name = "BH_Att"
            att0.Position = Vector3.new(math.random(-3, 3), math.random(-2, 2), math.random(-3, 3))
            att0.Parent = v

            local align = Instance.new("AlignPosition")
            align.Name = "BH_Align"
            align.Mode = Enum.PositionAlignmentMode.TwoAttachment
            align.Attachment0 = att0
            align.Attachment1 = blackHoleAtt1
            align.MaxForce = math.huge
            align.MaxVelocity = math.huge
            align.Responsiveness = resp
            align.ReactionForceEnabled = false
            align.ApplyAtCenterOfMass = true
            align.Parent = v

            local torque = Instance.new("Torque")
            torque.Name = "BH_Torque"
            torque.Attachment0 = att0
            torque.RelativeTo = Enum.ActuatorRelativeTo.World
            torque.Torque = Vector3.new(
                math.random(-1, 1) * spinPwr,
                spinPwr,
                math.random(-1, 1) * spinPwr
            )
            torque.Parent = v

            forcedParts[v] = {
                Part = v,
                Align = align,
                Torque = torque,
                Att = att0
            }
        end)
    end

    local function scanAllUnanchored()
        local count = 0
        local all = Workspace:GetDescendants()
        for i = 1, #all do
            if not blackHoleRunning then break end
            local obj = all[i]
