                                pcall(function() scfRef:InvokeServer(entry.lastCF) end)
                            end
                        end
                    end)
                    senders[scfRef] = entry
                end
                entry.lastCF = cf
                entry.dirty = true
            end

            
            while lightPlayerRunning and lightPlayerSession == mySession do
                if not LocalPlayer.Character or not hum or hum.Health <= 0 then
                    stopLightPlayer("Player died")
                    break
                end

                local curTarget = LocalPlayer
                if targetOption == "Target" and _G.TrollTarget and _G.TrollTarget ~= "---" then
                    curTarget = Players:FindFirstChild(_G.TrollTarget) or LocalPlayer
                end

                local curChar = curTarget.Character
                local curRoot = curChar and curChar:FindFirstChild("HumanoidRootPart")
                local curHum = curChar and curChar:FindFirstChildOfClass("Humanoid")

                if not curRoot or not curHum or curHum.Health <= 0 then
                    task.wait(0.1)
                else
                    local lightPos = curRoot.Position + Vector3.new(0, beamHeight, 0)
                    
                    local targetCF = CFrame.new(lightPos) * CFrame.Angles(math.pi, 0, 0)

                    for _, data in ipairs(activeProps) do
                        if not lightPlayerRunning or lightPlayerSession ~= mySession then break end
                        _0xH_3fb(data.SCF, targetCF)
                    end
                end

                task.wait(0.02)
            end

            sound:Destroy()
        end)
    end

    TrollV2Tab:AddSection({"> Light Player"})

    TrollV2Tab:AddDropdown({
        Name = "Light Target",
        Description = "Choose who receives the divine pillar of light",
        Options = {"Self", "Target"},
        Default = "Self",
        Callback = function(val)
            targetOption = val
        end
    })

    TrollV2Tab:AddSlider({
        Name = "Beam Height",
        Description = "Height above target head (in studs)",
        Min = 8,
        Max = 25,
        Default = 14,
        Increase = 1,
        Callback = function(val)
            beamHeight = tonumber(val) or 14.0
        end
    })

    TrollV2Tab:AddToggle({
        Name = "Light Player",
        Description = "15 pure white stacked spotlights pointing 180 deg downward creating a divine light pillar",
        Default = false,
        Callback = function(state)
            if not _G.BTR_UI_READY then return end
            if state then
                startLightPlayer()
            else
                stopLightPlayer()
            end
        end
    })
end

do
    local Players = game:GetService("Players")
    local Workspace = game:GetService("Workspace")
    local StarterGui = game:GetService("StarterGui")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local LocalPlayer = Players.LocalPlayer

    local function beNotify(title, text, duration)
        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = title or "Black Expansion",
                Text = text or "",
                Duration = duration or 3
            })
        end)
    end

    local RE = ReplicatedStorage:WaitForChild("RE", 5)
    local ToolRemote = RE and RE:WaitForChild("1Too1l", 5)
    local ClearRemote = RE and RE:WaitForChild("1Clea1rTool1s", 5)
    local Telemetry = ReplicatedStorage:FindFirstChild("Remotes") and ReplicatedStorage.Remotes:FindFirstChild("TelemetryClientInteraction")

    local PROP_NAME = "BigMilitaryTent"
    local PROP_CATEGORY = "Building"

    local blackExpRunning = false
    local blackExpSession = 0
    local propCount = 15
    local forwardOffset = 0.40
    local heightOffset = -8.0
    local lateralOffset = 0.0
    local rotSpeed = 5.0
    local selectedTargetName = LocalPlayer.Name

    local function getPlayerList()
        local list = {}
        for _, p in ipairs(Players:GetPlayers()) do
            table.insert(list, p.Name)
        end
        return list
    end

    local function cleanupPropMaker()
        local char = LocalPlayer.Character
        local bp = LocalPlayer:FindFirstChild("Backpack")
        pcall(function()
            local h = char and char:FindFirstChildOfClass("Humanoid")
            if h then h:UnequipTools() end
        end)
        if char then
            local tool = char:FindFirstChild("PropMaker")
            if tool and bp then tool.Parent = bp end
        end
    end

    local function getPropMaker()
        local char = LocalPlayer.Character
        local bp = LocalPlayer:FindFirstChild("Backpack")
        if not char or not bp then return nil end

        local tool = char:FindFirstChild("PropMaker") or bp:FindFirstChild("PropMaker")
        if not tool and ToolRemote then
            pcall(function() ToolRemote:InvokeServer("PickingTools", "PropMaker") end)
            local t0 = tick()
            while tick() - t0 < 1.5 do
                tool = char:FindFirstChild("PropMaker") or bp:FindFirstChild("PropMaker")
                if tool then break end
                task.wait(0.03)
            end
        end

        if tool and tool.Parent ~= char then
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                hum:EquipTool(tool)
                local eqStart = tick()
                while tick() - eqStart < 1 do
                    if tool.Parent == char then break end
                    task.wait(0.03)
                end
            end
        end
        return tool
    end

    local function duplicateProps(firstProp, countNeeded)
        if not firstProp then return false end
        local dupRemote = firstProp:FindFirstChild("DuplicateProp") or firstProp:WaitForChild("DuplicateProp", 1.5)
        if not dupRemote then return false end

        for i = 1, countNeeded do
            pcall(function() dupRemote:InvokeServer() end)
        end
        return true
    end

    local function stopBlackExpansion(reason)
        if not blackExpRunning then return end
        blackExpRunning = false
        blackExpSession = blackExpSession + 1

        if ClearRemote then
            pcall(function() ClearRemote:FireServer("ClearAllProps") end)
        end
        cleanupPropMaker()

        if reason then
            beNotify("Black Expansion", "Stopped: " .. tostring(reason), 3)
        else
            beNotify("Black Expansion", "Deactivated.", 2)
        end
    end

    local function startBlackExpansion()
        if blackExpRunning then
            stopBlackExpansion()
            task.wait(0.2)
        end

        blackExpRunning = true
        blackExpSession = blackExpSession + 1
        local mySession = blackExpSession

        task.spawn(function()
            local targetPlayer = Players:FindFirstChild(selectedTargetName) or LocalPlayer
            local tChar = targetPlayer.Character
            local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
            local tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")

            local myChar = LocalPlayer.Character
            local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
            local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")

            if not myChar or not myHum or not myRoot then
                stopBlackExpansion("Character missing")
                return
            end

            local spawnPos = (tRoot and tRoot.Position or myRoot.Position)

            beNotify("Black Expansion", "Deploying Black Zone on " .. targetPlayer.DisplayName .. "...", 2)

            local propMaker = getPropMaker()
            if not propMaker or not blackExpRunning or blackExpSession ~= mySession then
                stopBlackExpansion("PropMaker unavailable")
                return
            end

            if ClearRemote then
                pcall(function() ClearRemote:FireServer("OpenPropMenu") end)
                task.wait(0.12)
                if Telemetry then
                    pcall(function() Telemetry:FireServer("filterClick", {name = PROP_CATEGORY, itemType = "Props"}) end)
                    task.wait(0.04)
                    pcall(function() Telemetry:FireServer("filterClick", {name = PROP_NAME, itemType = "Props"}) end)
                    task.wait(0.04)
                end
                pcall(function() ClearRemote:FireServer("RequestingPropName", PROP_NAME, PROP_CATEGORY) end)
                task.wait(0.18)
            end

            local toolPropMake = propMaker:FindFirstChild("Tool_PropMake") or propMaker:WaitForChild("Tool_PropMake", 3)
            if not toolPropMake or not blackExpRunning or blackExpSession ~= mySession then
                stopBlackExpansion("Tool_PropMake missing")
                return
            end

            local myPropName = "Prop" .. LocalPlayer.Name
            local wc = Workspace:FindFirstChild("WorkspaceCom")
            if not wc or not blackExpRunning or blackExpSession ~= mySession then
                stopBlackExpansion("WorkspaceCom missing")
                return
            end

            local existingProps = {}
            for _, folder in pairs(wc:GetChildren()) do
                for _, p in pairs(folder:GetChildren()) do
                    if p.Name == myPropName then existingProps[p] = true end
                end
            end

            pcall(function() toolPropMake:FireServer(Workspace.Terrain, spawnPos) end)

            local firstProp = nil
            local t0 = tick()
            while tick() - t0 < 3.5 do
                if not blackExpRunning or blackExpSession ~= mySession or myHum.Health <= 0 then
                    stopBlackExpansion("Interrupted during spawn")
                    return
                end
                for _, folder in pairs(wc:GetChildren()) do
                    for _, p in pairs(folder:GetChildren()) do
                        if p.Name == myPropName and not existingProps[p] then
                            firstProp = p
                            break
                        end
                    end
                    if firstProp then break end
                end
                if firstProp then break end
                task.wait(0.04)
            end

            if not firstProp then
                stopBlackExpansion("Failed to spawn prop")
                return
            end

            if propCount > 1 then
                duplicateProps(firstProp, propCount - 1)
            end

                                                            
            task.spawn(function()
                task.wait(1.0)
                if ToolRemote then
                    pcall(function() ToolRemote:InvokeServer("PickingTools", "PropMaker") end)
                end
                cleanupPropMaker()
            end)

            
            local activeProps = {}
            task.wait(0.25)
            for _, folder in pairs(wc:GetChildren()) do
                for _, p in pairs(folder:GetChildren()) do
                    if p.Name == myPropName then
                        local scf = p:FindFirstChild("SetCurrentCFrame")
                        local cpc = p:FindFirstChild("ChangePropColor")
                        if scf then
                            table.insert(activeProps, { Prop = p, SCF = scf, CPC = cpc })
                            if cpc then
                                pcall(function() cpc:InvokeServer(Color3.fromRGB(0, 0, 0)) end)
                            end
                        end
                    end
                end
            end

            if #activeProps == 0 or not blackExpRunning or blackExpSession ~= mySession then
                stopBlackExpansion("No props found")
                return
            end

            beNotify("Black Expansion", "Black Zone ACTIVE!", 3)

            
            local senders = {}
            local function _0xH_3fb(scfRef, cf)
                local entry = senders[scfRef]
                if not entry then
                    entry = { lastCF = nil, dirty = false }
                    entry.thread = task.spawn(function()
                        while blackExpRunning and blackExpSession == mySession do
                            task.wait(0.025)
                            if not blackExpRunning or blackExpSession ~= mySession then return end
                            if entry.dirty and entry.lastCF then
                                entry.dirty = false
                                pcall(function() scfRef:InvokeServer(entry.lastCF) end)
                            end
                        end
                    end)
                    senders[scfRef] = entry
                end
                entry.lastCF = cf
                entry.dirty = true
            end

            
            local totalTents = #activeProps
            local angleStep = (math.pi * 2) / totalTents
            local currentAngle = 0

            while blackExpRunning and blackExpSession == mySession do
                if not LocalPlayer.Character or not myHum or myHum.Health <= 0 then
                    stopBlackExpansion("Player died")
                    break
                end

                local curTarget = Players:FindFirstChild(selectedTargetName) or LocalPlayer
                local curChar = curTarget.Character
                local curRoot = curChar and curChar:FindFirstChild("HumanoidRootPart")
                local curHum = curChar and curChar:FindFirstChildOfClass("Humanoid")

                if not curRoot or not curHum or curHum.Health <= 0 then
                    task.wait(0.05)
                else
                    currentAngle = currentAngle + (rotSpeed * 0.02)

                    for i, data in ipairs(activeProps) do
                        if not blackExpRunning or blackExpSession ~= mySession then break end
                        local theta = currentAngle + ((i - 1) * angleStep)

                        local tentCF = curRoot.CFrame * CFrame.Angles(0, theta, 0) * CFrame.new(forwardOffset, heightOffset, lateralOffset) * CFrame.Angles(0, math.rad(-90), 0)

                        _0xH_3fb(data.SCF, tentCF)
                    end
                end

                task.wait(0.02)
            end
        end)
    end

    _G.BTR_StartBlackExpansion = function(tName)
        if tName then selectedTargetName = tName end
        startBlackExpansion()
    end
    _G.BTR_StopBlackExpansion = stopBlackExpansion

    TrollV2Tab:AddSection({"> Black Expansion"})

    local beDropdownRef = nil
    beDropdownRef = TrollV2Tab:AddDropdown({
        Name = "Target Player",
        Description = "Choose target to blind with the black screen zone",
        Options = getPlayerList(),
        Default = LocalPlayer.Name,
        Callback = function(val)
            if val and val ~= "" then
                selectedTargetName = val
            end
        end
    })

    TrollV2Tab:AddButton({
        Name = "Refresh Player List",
        Description = "Update online players in target list",
        Callback = function()
            local updated = getPlayerList()
            if beDropdownRef and beDropdownRef.Set then
                pcall(function() beDropdownRef:Set(updated) end)
            end
            beNotify("Black Expansion", "Player list refreshed!", 2)
        end
    })

    TrollV2Tab:AddToggle({
        Name = "Black Expansion",
        Description = "Blind black zone centered on target, best used to completely blind first person view",
        Default = false,
        Callback = function(state)
            if not _G.BTR_UI_READY then return end
            if state then
                startBlackExpansion()
            else
                stopBlackExpansion()
            end
        end
    })
end

do
    local barrelBotActive = false
    local barrelBotSessionId = 0
    local barrelBotLoopConn = nil
    local barrelBotPartsCache = {}
    local barrelBotOriginCF = nil
    local barrelSideOffset = 5.0
    local barrelForwardOffset = 0.0
    local barrelHeightOffset = 0.0
    local barrelFollowSmooth = 0.28
    local barrelBotScale = 1.0

    
    local stalkActive = false
    local selectedStalkTarget = "[Nearest Player]"
    local stalkFollowMode = "Behind"
    local stalkOrbitAngle = 0.0

    
    local currentCustomEmoteTrack = nil
    local currentCustomEmoteId = "82025361932571"

    local selectedBarrelColor = "Scanned Gray"
    local BARREL_COLORS = {
        ["Scanned Gray"]  = Color3.fromRGB(99, 95, 98),
        ["Toxic Green"]   = Color3.fromRGB(50, 255, 60),
        ["Radioactive Red"]= Color3.fromRGB(255, 35, 45),
        ["Cyber Cyan"]    = Color3.fromRGB(0, 220, 255),
        ["Electric Gold"] = Color3.fromRGB(255, 215, 0),
        ["Void Purple"]   = Color3.fromRGB(160, 40, 255),
        ["Pure White"]    = Color3.fromRGB(255, 255, 255),
        ["Obsidian Black"]= Color3.fromRGB(15, 15, 18),
    }

    local function barrelNotify(title, text, dur)
        pcall(function()
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = title,
                Text = text,
                Duration = dur or 3
            })
        end)
    end

    local function getBarrelPropMaker()
        local lp = game:GetService("Players").LocalPlayer
        local char = lp.Character
        local bp = lp:FindFirstChild("Backpack")
        if not char and not bp then return nil end

        local tool = (char and char:FindFirstChild("PropMaker")) or (bp and bp:FindFirstChild("PropMaker"))
        if not tool then
            local toolRE = game:GetService("ReplicatedStorage"):WaitForChild("RE"):WaitForChild("1Too1l")
            pcall(function() toolRE:InvokeServer("PickingTools", "PropMaker") end)
            local t0 = tick()
            while tick() - t0 < 2.5 do
                tool = (char and char:FindFirstChild("PropMaker")) or (bp and bp:FindFirstChild("PropMaker"))
                if tool then break end
                task.wait(0.05)
            end
        end

        if not tool then return nil end

        if char and tool.Parent ~= char then
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                hum:EquipTool(tool)
                task.wait(0.1)
            end
        end
        return tool
    end

    local function spawnSingleNuclearBarrel(targetPos)
        local tool = getBarrelPropMaker()
        if not tool then return nil end

        local clearTools = game:GetService("ReplicatedStorage"):WaitForChild("RE"):WaitForChild("1Clea1rTool1s")
        pcall(function() clearTools:FireServer("RequestingPropName", "NuclearWasteBarrel", "Building") end)
        task.wait(0.3)

        local lp = game:GetService("Players").LocalPlayer
        local char = lp.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum and tool.Parent ~= char then
            hum:EquipTool(tool)
            task.wait(0.1)
        end

        local tpm = tool:FindFirstChild("Tool_PropMake")
        local t0 = tick()
        while not tpm and tick() - t0 < 3.0 do
            tpm = tool:FindFirstChild("Tool_PropMake")
            if not tpm then
                local bp = lp:FindFirstChild("Backpack") and lp.Backpack:FindFirstChild("PropMaker")
                if bp then tpm = bp:FindFirstChild("Tool_PropMake") end
            end
            if not tpm then task.wait(0.1) end
        end

                                                                          
        if not tpm then return nil end

        local wc = workspace:FindFirstChild("WorkspaceCom")
        local myPropName = "Prop" .. lp.Name
        local beforeList = {}
        if wc then
            for _, folder in ipairs(wc:GetChildren()) do
                for _, prop in ipairs(folder:GetChildren()) do
                    if prop.Name == myPropName then
                        beforeList[prop] = true
                    end
                end
            end
        end

        pcall(function() tpm:FireServer(workspace.Terrain, targetPos) end)

        local spawned = nil
        local tDetect = tick()
        while tick() - tDetect < 3.5 do
            if wc then
                for _, folder in ipairs(wc:GetChildren()) do
                    for _, prop in ipairs(folder:GetChildren()) do
                        if prop.Name == myPropName and not beforeList[prop] then
                            spawned = prop
                            break
                        end
                    end
                    if spawned then break end
                end
            end
            if spawned then break end
            task.wait(0.05)
        end

        return spawned
    end

    local function duplicateNuclearBarrel(firstProp, count)
        if not firstProp or count <= 0 then return end
        local dupRemote = firstProp:FindFirstChild("DuplicateProp") or firstProp:WaitForChild("DuplicateProp", 2)
        if not dupRemote then return end
        for i = 1, count do
            pcall(function() dupRemote:InvokeServer() end)
            task.wait(0.05)
        end
    end

    local function scanBarrelProps()
        table.clear(barrelBotPartsCache)
        local wc = workspace:FindFirstChild("WorkspaceCom")
        if not wc then return end
        local lp = game:GetService("Players").LocalPlayer
        local myPropName = "Prop" .. lp.Name

        for _, folder in ipairs(wc:GetChildren()) do
            for _, prop in ipairs(folder:GetChildren()) do
                if prop.Name == myPropName then
                    local scf = prop:FindFirstChild("SetCurrentCFrame") or prop:WaitForChild("SetCurrentCFrame", 0.5)
                    local cpc = prop:FindFirstChild("ChangePropColor") or prop:FindFirstChild("ChangePropColor", true)
                    if scf then
                        table.insert(barrelBotPartsCache, {
                            prop = prop,
                            remote = scf,
                            colorRemote = cpc
                        })
                    end
                end
            end
        end
    end

    local function applyBarrelColor(item, color)
        if not item then return end
        pcall(function()
            for _, p in ipairs(item.prop:GetDescendants()) do
                if p:IsA("BasePart") then
                    p.Color = color
                end
            end
        end)
        if item.colorRemote then
            task.spawn(function()
                pcall(function() item.colorRemote:InvokeServer(color) end)
            end)
        end
    end

    local function applyColorToAllBarrels()
        local col = BARREL_COLORS[selectedBarrelColor] or BARREL_COLORS["Scanned Gray"]
        for _, item in ipairs(barrelBotPartsCache) do
            applyBarrelColor(item, col)
        end
    end

    local function resolveTargetPlayer()
        local Players = game:GetService("Players")
        local lp = Players.LocalPlayer
        if not stalkActive then
            return lp
        end
        if selectedStalkTarget == "[Nearest Player]" then
            local myChar = lp.Character
            local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if not myHrp then return lp end
            local nearestPlr = nil
            local minDist = math.huge
            for _, plr in ipairs(Players:GetPlayers()) do
                if plr ~= lp and plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") then
                    local dist = (plr.Character.HumanoidRootPart.Position - myHrp.Position).Magnitude
                    if dist < minDist then
                        minDist = dist
                        nearestPlr = plr
                    end
                end
            end
            return nearestPlr or lp
        else
            local found = Players:FindFirstChild(selectedStalkTarget)
            if found then return found end
            local lower = string.lower(selectedStalkTarget)
            for _, plr in ipairs(Players:GetPlayers()) do
                if string.find(string.lower(plr.Name), lower, 1, true) or string.find(string.lower(plr.DisplayName), lower, 1, true) then
                    return plr
                end
            end
            return lp
        end
    end

    local function getLimbPart(charModel, index)
        if not charModel then return nil end
        local isR15 = charModel:FindFirstChild("UpperTorso") ~= nil
        if isR15 then
            local rMap = {
                [1]  = "UpperTorso",
                [2]  = "LowerTorso",
                [3]  = "Head",
                [4]  = "LeftUpperArm",
                [5]  = "LeftLowerArm",
                [6]  = "LeftHand",
                [7]  = "RightUpperArm",
                [8]  = "RightLowerArm",
                [9]  = "RightHand",
                [10] = "LeftUpperLeg",
                [11] = "LeftLowerLeg",
                [12] = "LeftFoot",
                [13] = "RightUpperLeg",
                [14] = "RightLowerLeg",
                [15] = "RightFoot",
            }
            return charModel:FindFirstChild(rMap[index] or "UpperTorso")
        else
            local r6Map = {
                [1]  = "Torso",
                [2]  = "Torso",
                [3]  = "Head",
                [4]  = "Left Arm",
                [5]  = "Left Arm",
                [6]  = "Left Arm",
                [7]  = "Right Arm",
                [8]  = "Right Arm",
                [9]  = "Right Arm",
                [10] = "Left Leg",
                [11] = "Left Leg",
                [12] = "Left Leg",
                [13] = "Right Leg",
                [14] = "Right Leg",
                [15] = "Right Leg",
            }
            return charModel:FindFirstChild(r6Map[index] or "Torso")
        end
    end

    local function stopCustomEmote()
        if currentCustomEmoteTrack then
            pcall(function()
                currentCustomEmoteTrack:Stop()
                currentCustomEmoteTrack:Destroy()
            end)
            currentCustomEmoteTrack = nil
            barrelNotify("Custom Emote", "Stopped custom emote.", 2)
        end
    end

    local function playCustomEmote(emoteId)
        if not emoteId or emoteId == "" then return end
        local id = string.match(tostring(emoteId), "%d+")
        if not id then return end

        stopCustomEmote()

        local lp = game:GetService("Players").LocalPlayer
        local char = lp.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hum then return end

        task.spawn(function()
            local animObj = nil
            local success, objects = pcall(function()
                return game:GetObjects("rbxassetid://" .. id)
            end)

            if success and objects and #objects > 0 then
                for _, obj in ipairs(objects) do
                    if obj:IsA("Animation") then
                        animObj = obj
                        break
                    end
                    for _, child in ipairs(obj:GetDescendants()) do
                        if child:IsA("Animation") then
                            animObj = child
                            break
                        end
                    end
                    if animObj then break end
                end
            end

            if not animObj then
                local directAnim = Instance.new("Animation")
                directAnim.AnimationId = "rbxassetid://" .. id
                animObj = directAnim
            end

            if animObj then
                local track = hum:LoadAnimation(animObj)
                track.Priority = Enum.AnimationPriority.Action4
                track.Looped = true
                track:Play()
                currentCustomEmoteTrack = track
                barrelNotify("Custom Emote", "Playing custom emote: " .. id, 2)
            end
        end)
    end

    local function stopNuclearBarrelBot()
        barrelBotActive = false
        barrelBotSessionId = barrelBotSessionId + 1

        if barrelBotLoopConn then
            barrelBotLoopConn:Disconnect()
            barrelBotLoopConn = nil
        end

        pcall(function()
            game:GetService("ReplicatedStorage"):WaitForChild("RE"):WaitForChild("1Clea1rTool1s"):FireServer("ClearAllProps")
        end)

        table.clear(barrelBotPartsCache)
        barrelBotOriginCF = nil
        barrelNotify("Barrel Bot", "Barrel bot deactivated and props cleared.", 2)
    end

    local function startNuclearBarrelBot()
        stopNuclearBarrelBot()
        barrelBotActive = true
        barrelBotSessionId = barrelBotSessionId + 1
        local currentSession = barrelBotSessionId

        task.spawn(function()
            local lp = game:GetService("Players").LocalPlayer
            local char = lp.Character or lp.CharacterAdded:Wait()
            local hrp = char:WaitForChild("HumanoidRootPart")

            barrelNotify("Barrel Bot", "Assembling 15-Prop Nuclear Mimic Bot...", 3)

            local clearTools = game:GetService("ReplicatedStorage"):WaitForChild("RE"):WaitForChild("1Clea1rTool1s")
            local toolRE = game:GetService("ReplicatedStorage"):WaitForChild("RE"):WaitForChild("1Too1l")

            pcall(function() clearTools:FireServer("ClearAllProps") end)
            task.wait(0.4)

            local propTool = getBarrelPropMaker()
            if not propTool then
                barrelNotify("Error", "Could not equip PropMaker.", 3)
                return
            end

            pcall(function() clearTools:FireServer("OpenPropMenu") end)
            task.wait(0.2)

            local spawnPos = hrp.Position + (hrp.CFrame.RightVector * barrelSideOffset)
            local baseProp = spawnSingleNuclearBarrel(spawnPos)

            if not baseProp and currentSession == barrelBotSessionId then
                baseProp = spawnSingleNuclearBarrel(spawnPos)
            end

            if not baseProp or currentSession ~= barrelBotSessionId then
                barrelNotify("Error", "Could not spawn base barrel.", 3)
                return
            end

            duplicateNuclearBarrel(baseProp, 14)
            task.wait(0.8)

                                                                                 
            task.wait(1.0)
            pcall(function() toolRE:InvokeServer("PickingTools", "PropMaker") end)
            pcall(function() clearTools:FireServer("ClosePropMenu") end)

            task.wait(0.4)
            scanBarrelProps()

            applyColorToAllBarrels()

            barrelNotify("Barrel Bot", string.format("Nuclear Bot Ready! (%d/15 props connected)", #barrelBotPartsCache), 3)

            local nextNetTick = 0
            barrelBotLoopConn = game:GetService("RunService").RenderStepped:Connect(function(dt)
                if not barrelBotActive or currentSession ~= barrelBotSessionId then return end

                local targetPlr = resolveTargetPlayer()
                local curChar = targetPlr and targetPlr.Character
                local curHrp = curChar and (curChar:FindFirstChild("HumanoidRootPart") or curChar:FindFirstChild("Torso"))
                local curHum = curChar and curChar:FindFirstChildOfClass("Humanoid")

                
                if not curHrp or not curHum or curHum.Health <= 0 then
                    curChar = lp.Character
                    curHrp = curChar and curChar:FindFirstChild("HumanoidRootPart")
                    curHum = curChar and curChar:FindFirstChildOfClass("Humanoid")
                end

                if not curHrp or not curHum then return end

                local now = tick()
                local _, yaw, _ = curHrp.CFrame:ToEulerAnglesYXZ()
                local flatPlayerCF = CFrame.new(curHrp.Position) * CFrame.Angles(0, yaw, 0)
                
                local isR15 = curChar:FindFirstChild("UpperTorso") ~= nil

                
                local scaleX = isR15 and 1.80 or 1.90
                local scaleY = isR15 and 2.05 or 2.10
                local scaleZ = isR15 and 1.65 or 1.65

                local groundCompensation = (scaleY - 1.0) * 2.65
                local effectiveHeightOffset = barrelHeightOffset + groundCompensation

                local targetOriginFrame = nil
                if stalkActive and targetPlr ~= lp then
                    if stalkFollowMode == "Behind" then
                        targetOriginFrame = flatPlayerCF * CFrame.new(0, effectiveHeightOffset, 5.5)
                    elseif stalkFollowMode == "Face" then
                        targetOriginFrame = flatPlayerCF * CFrame.new(0, effectiveHeightOffset, -5.5) * CFrame.Angles(0, math.pi, 0)
                    elseif stalkFollowMode == "Orbit" then
                        stalkOrbitAngle = stalkOrbitAngle + (dt or 0.016) * 1.6
                        targetOriginFrame = flatPlayerCF * CFrame.Angles(0, stalkOrbitAngle, 0) * CFrame.new(0, effectiveHeightOffset, -6.5) * CFrame.Angles(0, math.pi, 0)
                    elseif stalkFollowMode == "Left" then
                        targetOriginFrame = flatPlayerCF * CFrame.new(-barrelSideOffset, effectiveHeightOffset, -barrelForwardOffset)
                    else
                        targetOriginFrame = flatPlayerCF * CFrame.new(barrelSideOffset, effectiveHeightOffset, -barrelForwardOffset)
                    end
                else
                    targetOriginFrame = flatPlayerCF * CFrame.new(barrelSideOffset, effectiveHeightOffset, -barrelForwardOffset)
                end

                if not barrelBotOriginCF or (targetOriginFrame.Position - barrelBotOriginCF.Position).Magnitude > 35 then
                    barrelBotOriginCF = targetOriginFrame
                else
                    barrelBotOriginCF = barrelBotOriginCF:Lerp(targetOriginFrame, barrelFollowSmooth)
                end

                local shouldNetSend = now >= nextNetTick
                if shouldNetSend then nextNetTick = now + 0.035 end

                local r6Offsets = {
                    [1]  = CFrame.new(0, 0.8, 0),
                    [2]  = CFrame.new(0, -0.9, 0),
                    [3]  = CFrame.new(0, 0.4, 0),
                    [4]  = CFrame.new(0, 1.0, 0),
                    [5]  = CFrame.new(0, -0.8, 0),
                    [6]  = CFrame.new(0, -2.6, 0),
                    [7]  = CFrame.new(0, 1.0, 0),
                    [8]  = CFrame.new(0, -0.8, 0),
                    [9]  = CFrame.new(0, -2.6, 0),
                    [10] = CFrame.new(0, 0.9, 0),
                    [11] = CFrame.new(0, -1.0, 0),
                    [12] = CFrame.new(0, -2.8, 0),
                    [13] = CFrame.new(0, 0.9, 0),
                    [14] = CFrame.new(0, -1.0, 0),
                    [15] = CFrame.new(0, -2.8, 0),
                }

                local r15Offsets = {
                    [1]  = CFrame.new(0, 0, 0),
                    [2]  = CFrame.new(0, 0, 0),
                    [3]  = CFrame.new(0, 0, 0),
                    [4]  = CFrame.new(0, 0.1, 0),
                    [5]  = CFrame.new(0, -0.1, 0),
                    [6]  = CFrame.new(0, -0.6, 0),
                    [7]  = CFrame.new(0, 0.1, 0),
                    [8]  = CFrame.new(0, -0.1, 0),
                    [9]  = CFrame.new(0, -0.6, 0),
                    [10] = CFrame.new(0, 0.1, 0),
                    [11] = CFrame.new(0, -0.2, 0),
                    [12] = CFrame.new(0, -0.6, 0),
                    [13] = CFrame.new(0, 0.1, 0),
                    [14] = CFrame.new(0, -0.2, 0),
                    [15] = CFrame.new(0, -0.6, 0),
                }

                for idx, item in ipairs(barrelBotPartsCache) do
                    if idx > 15 then break end

                    local sourceLimb = getLimbPart(curChar, idx)
                    if sourceLimb then
                        local relCF = curHrp.CFrame:ToObjectSpace(sourceLimb.CFrame)
                        local scaledPos = Vector3.new(
                            relCF.Position.X * scaleX * barrelBotScale,
                            relCF.Position.Y * scaleY * barrelBotScale,
                            relCF.Position.Z * scaleZ * barrelBotScale
                        )

                        
                        local bodyOffset = Vector3.zero
                        if isR15 then
                            if idx == 1 then
                                bodyOffset = Vector3.new(0, 0.3, 0)
                            elseif idx == 2 then
                                bodyOffset = Vector3.new(0, -0.2, 0)
                            elseif idx == 3 then
                                bodyOffset = Vector3.new(0, 0.75, 0)
                            elseif idx >= 4 and idx <= 6 then
                                bodyOffset = Vector3.new(-0.85, 0.15, 0)
                            elseif idx >= 7 and idx <= 9 then
                                bodyOffset = Vector3.new(0.85, 0.15, 0)
                            elseif idx >= 10 and idx <= 12 then
                                bodyOffset = Vector3.new(-0.60, 0, 0)
                            elseif idx >= 13 and idx <= 15 then
                                bodyOffset = Vector3.new(0.60, 0, 0)
                            end
                        else
                            if idx == 1 then
                                bodyOffset = Vector3.new(0, 0.4, 0)
                            elseif idx == 2 then
                                bodyOffset = Vector3.new(0, -0.4, 0)
                            elseif idx == 3 then
                                bodyOffset = Vector3.new(0, 0.8, 0)
                            elseif idx >= 4 and idx <= 6 then
                                bodyOffset = Vector3.new(-1.15, 0.2, 0)
                            elseif idx >= 7 and idx <= 9 then
                                bodyOffset = Vector3.new(1.15, 0.2, 0)
                            elseif idx >= 10 and idx <= 12 then
                                bodyOffset = Vector3.new(-0.85, 0, 0)
                            elseif idx >= 13 and idx <= 15 then
                                bodyOffset = Vector3.new(0.85, 0, 0)
                            end
                        end

                        local limbRot = relCF.Rotation
                        local fineTune = (isR15 and r15Offsets[idx]) or r6Offsets[idx] or CFrame.new()

                        local finalPropCF = barrelBotOriginCF * CFrame.new(scaledPos + bodyOffset) * limbRot * fineTune

                        pcall(function()
                            if item.prop:IsA("Model") then
                                item.prop:PivotTo(finalPropCF)
                            elseif item.prop:IsA("BasePart") then
                                item.prop.CFrame = finalPropCF
                            end
                        end)

                        if shouldNetSend and item.remote then
                            task.spawn(function()
                                pcall(function() item.remote:InvokeServer(finalPropCF) end)
                            end)
                        end
                    end
                end
            end)
        end)
    end

