    local function getDripSoccerBall()
        local players = game:GetService("Players")
        local player = players.LocalPlayer
        local character = player.Character or player.CharacterAdded:Wait()
        local backpack = player:WaitForChild("Backpack")
        local serverBalls = workspace:WaitForChild("WorkspaceCom"):WaitForChild("001_SoccerBalls")

        if not backpack:FindFirstChild("SoccerBall") and not character:FindFirstChild("SoccerBall") then
            game:GetService("ReplicatedStorage").RE:FindFirstChild("1Too1l"):InvokeServer("PickingTools", "SoccerBall")
        end
        repeat task.wait() until backpack:FindFirstChild("SoccerBall") or character:FindFirstChild("SoccerBall")
        if backpack:FindFirstChild("SoccerBall") then
            backpack.SoccerBall.Parent = character
        end
        repeat task.wait() until serverBalls:FindFirstChild("Soccer" .. player.Name)
        if character:FindFirstChild("SoccerBall") then
            character.SoccerBall.Parent = backpack
        end
        return serverBalls:FindFirstChild("Soccer" .. player.Name)
    end

    local function prepareDripBall(ball)
        if not ball then return end
        ball.CanCollide = false
        ball.Massless = true
        ball.CustomPhysicalProperties = PhysicalProperties.new(0.0001, 0, 0)

        local oldBv = ball:FindFirstChildWhichIsA("BodyVelocity")
        if oldBv then
            oldBv:Destroy()
        end

        local bv = Instance.new("BodyVelocity")
        bv.Name = "FlingPower"
        bv.Velocity = Vector3.new(9e8, 9e8, 9e8)
        bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
        bv.P = 9e900
        bv.Parent = ball
        return bv
    end

    local isDripFlinging = false
    local dripAuraRunning = false

    local function stopDripSoccerAura()
        dripAuraRunning = false
        pcall(function()
            local player = game:GetService("Players").LocalPlayer
            local serverBalls = workspace:FindFirstChild("WorkspaceCom") and workspace.WorkspaceCom:FindFirstChild("001_SoccerBalls")
            local ball = serverBalls and serverBalls:FindFirstChild("Soccer" .. player.Name)
            if ball then
                local bv = ball:FindFirstChildWhichIsA("BodyVelocity")
                if bv then bv:Destroy() end
            end
            local char = player.Character
            if char and char:FindFirstChild("SoccerBall") then
                char.SoccerBall.Parent = player.Backpack
            end
        end)
    end

    local function _0xH_411(target)
        local players = game:GetService("Players")
        local player = players.LocalPlayer
        local character = player.Character or player.CharacterAdded:Wait()
        local humanoid = character:WaitForChild("Humanoid")
        local serverBalls = workspace.WorkspaceCom:WaitForChild("001_SoccerBalls")

        if isDripFlinging then return end
        isDripFlinging = true

        local ball = serverBalls:FindFirstChild("Soccer" .. player.Name) or getDripSoccerBall()
        if not ball then
            isDripFlinging = false
            return
        end

        local bv = prepareDripBall(ball)

        if target and target ~= player then
            local tchar = target.Character
            if tchar and tchar:FindFirstChild("HumanoidRootPart") and tchar:FindFirstChild("Humanoid") then
                local troot = tchar.HumanoidRootPart
                local thum = tchar.Humanoid

                workspace.CurrentCamera.CameraSubject = thum
                local startTime = os.time()
                repeat
                    if not isDripFlinging then break end
                    if troot.Velocity.Magnitude > 0 then
                        local pos_x = troot.Position.X + (troot.Velocity.X / 1.5)
                        local pos_y = troot.Position.Y + (troot.Velocity.Y / 1.5)
                        local pos_z = troot.Position.Z + (troot.Velocity.Z / 1.5)
                        local position = Vector3.new(pos_x, pos_y, pos_z)
                        ball.CFrame = CFrame.new(position)
                        ball.Orientation = ball.Orientation + Vector3.new(45, 60, 30)
                    else
                        for _, v in pairs(tchar:GetChildren()) do
                            if v:IsA("BasePart") and v.CanCollide and not v.Anchored then
                                ball.CFrame = v.CFrame
                                task.wait(1/6000)
                            end
                        end
                    end
                    task.wait(1/6000)
                until troot.Velocity.Magnitude > 1000 or thum.Health <= 0 or not tchar:IsDescendantOf(workspace) or target.Parent ~= players or (os.time() - startTime > 8)

                if bv and bv.Parent then bv:Destroy() end
                workspace.CurrentCamera.CameraSubject = humanoid
            end
        end

        isDripFlinging = false

        
        if dripAuraRunning then
            task.spawn(function()
                local newBv = prepareDripBall(ball)
            end)
        end
    end

                                                                           
