                            seat.CanTouch = true
                            myHum:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
                        end)
                        myHrp.CFrame = seat.CFrame + Vector3.new(0, 2, 0)
                        task.wait(0.15)
                        pcall(function() seat:Sit(myHum) end)
                        local waitCount = 0
                        while not myHum.Sit and waitCount < 12 do
                            pcall(function()
                                seat.Disabled = false
                                myHum:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
                                myHrp.CFrame = seat.CFrame + Vector3.new(0, 1, 0)
                                seat:Sit(myHum)
                            end)
                            task.wait(0.1)
                            waitCount = waitCount + 1
                        end
                        if not myHum.Sit then
                            game:GetService("StarterGui"):SetCore("SendNotification", {Title="Vehicle Fling", Text="I can't sit down!", Duration=3})
                            _G.VehicleFlingActive = false
                            _G.VehicleFlingCar = nil
                            if vehicleFlingToggleRef then pcall(function() vehicleFlingToggleRef:Set(false) end) end
                            return
                        end
                    end

                    vehicleFlingRunning5 = true

                    if myHum then
                        pcall(function() myHum:SetStateEnabled(Enum.HumanoidStateType.Seated, true) end)
                    end

                    game:GetService("StarterGui"):SetCore("SendNotification", {Title="FLING ACTIVE", Text="Tractor engaged!", Duration=3})

                    local attackStart = tick()
                    vehicleFlingConnection5 = game:GetService("RunService").Heartbeat:Connect(function(dt)
                        if not vehicleFlingRunning5 or not myVehicle or not myVehicle.Parent then
                            if vehicleFlingConnection5 then vehicleFlingConnection5:Disconnect() end
                            return
                        end
                        if not targetPlayer.Character then
                            task.spawn(function() stopVehicleFling5(false, false) end)
                            return
                        end

                        local tHrp = targetPlayer.Character:FindFirstChild("HumanoidRootPart")
                        local tHum = targetPlayer.Character:FindFirstChildOfClass("Humanoid")
                        local primary = myVehicle.PrimaryPart or getVehiclePart(myVehicle) or seat

                        if not tHrp or not primary then return end

                        local t = tick()
                        local r = 2
                        local ox = math.sin(t * 10) * r
                        local oz = math.cos(t * 10) * r

                        local targetCF = CFrame.new(
                            tHrp.Position + Vector3.new(ox, 0.5, oz),
                            tHrp.Position
                        )

                        pcall(function()
                            if myVehicle.PivotTo then
                                myVehicle:PivotTo(targetCF)
                            elseif myVehicle.SetPrimaryPartCFrame then
                                myVehicle:SetPrimaryPartCFrame(targetCF)
                            end
                            local dir = (tHrp.Position - primary.Position)
                            if dir.Magnitude > 0.1 then dir = dir.Unit end
                            primary.AssemblyLinearVelocity  = dir * 25000 + Vector3.new(0, 12000, 0)
                            primary.AssemblyAngularVelocity = Vector3.zero
                            primary.RotVelocity = Vector3.new(0, 8000, 0)
                        end)

                        local elapsed = tick() - attackStart
                        local isTargetFlinged = (tHrp.Position.Y < -20) or (tHrp.AssemblyLinearVelocity.Magnitude > 150) or (tHum and tHum.Health <= 0) or (tHum and tHum.Sit)
                        if elapsed > 2.5 or isTargetFlinged then
                            vehicleFlingRunning5 = false
                            if vehicleFlingConnection5 then
                                vehicleFlingConnection5:Disconnect()
                                vehicleFlingConnection5 = nil
                            end
                            task.spawn(function()
                                task.wait(0.2)
                                stopVehicleFling5(false, true)
                            end)
                        end
                    end)
                else
                    stopVehicleFling5(false, false)
                end
            end
        })
    end

                                                    

do
    AvatarTab:AddSection({"Copy Avatar System"})

    local CopyAvatarTarget = ""
    local CopyAvatarActive = false
    local CopyColors = false
    local CopyAnimations = true
    local CopyMorph = true
    local CopyIdentity = true

    local copyPlayerDropdown = AvatarTab:AddDropdown({
