                return
            end

            if CopyAvatarActive then
                game:GetService("StarterGui"):SetCore("SendNotification", {Title = "Copy Avatar", Text = "A copy is already in progress...", Duration = 3})
                return
            end

            local Players = game:GetService("Players")
            local RS = game:GetService("ReplicatedStorage")
            local Remotes = RS:FindFirstChild("Remotes") or RS:FindFirstChild("RE")
            if not Remotes then
                game:GetService("StarterGui"):SetCore("SendNotification", {Title = "Copy Avatar", Text = "Brookhaven Remotes not found!", Duration = 3})
                return
            end

            local TPlayer = Players:FindFirstChild(CopyAvatarTarget)
            if not TPlayer or not TPlayer.Character then
                game:GetService("StarterGui"):SetCore("SendNotification", {Title = "Copy Avatar", Text = "Player or character not found!", Duration = 3})
                return
            end

            local LP = Players.LocalPlayer
            local LChar = LP.Character
            if not LChar then
                game:GetService("StarterGui"):SetCore("SendNotification", {Title = "Copy Avatar", Text = "Your character was not found!", Duration = 3})
                return
            end

            local LHumanoid = LChar:FindFirstChildOfClass("Humanoid")
            local THumanoid = TPlayer.Character:FindFirstChildOfClass("Humanoid")
            if not LHumanoid or not THumanoid then
                game:GetService("StarterGui"):SetCore("SendNotification", {Title = "Copy Avatar", Text = "Humanoid not found!", Duration = 3})
                return
            end

            CopyAvatarActive = true
            _G.BTR_IS_COPYING_AVATAR = true
            _G.BTR_COPIED_PLAYERS = _G.BTR_COPIED_PLAYERS or {}
            _G.BTR_COPIED_PLAYERS[TPlayer.UserId] = true
            _G.BTR_LAST_COPY_TIME = os.clock()

            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = "Copy Avatar",
                Text = "Copying avatar from " .. TPlayer.Name .. "...",
                Duration = 2
            })

            task.spawn(function()
                local wearRemote = Remotes:FindFirstChild("Wear")
                local BROOKHAVEN_COOLDOWN = 2.05

                                                                          
                local targetChar = TPlayer.Character
                if not targetChar then
                    CopyAvatarActive = false
                    _G.BTR_IS_COPYING_AVATAR = false
                    return
                end

                local PDesc = nil
                pcall(function() PDesc = THumanoid:GetAppliedDescription() end)

                                                                                                                               
                local targetShirtId = nil
                if PDesc and tonumber(PDesc.Shirt) and tonumber(PDesc.Shirt) > 0 then
                    targetShirtId = tonumber(PDesc.Shirt)
                end

                local targetPantsId = nil
                if PDesc and tonumber(PDesc.Pants) and tonumber(PDesc.Pants) > 0 then
                    targetPantsId = tonumber(PDesc.Pants)
                end

                local targetFaceId = nil
                if PDesc and tonumber(PDesc.Face) and tonumber(PDesc.Face) > 0 then
                    targetFaceId = tonumber(PDesc.Face)
                end

                                                                          
                local accessoriesToWear = {}
                local seenAccs = {}
                local itemColors = {}

                local function addAccId(id)
                    if not id or not tonumber(id) then return end
                    local n = tonumber(id)
                    if n > 0 and not seenAccs[n] then
                        seenAccs[n] = true
                        table.insert(accessoriesToWear, n)
                    end
                end

                                                                          
                if PDesc and PDesc.GetAccessories then
                    pcall(function()
                        for _, v in ipairs(PDesc:GetAccessories(true)) do
                            if v.AssetId then addAccId(v.AssetId) end
                        end
                    end)
                end

                                                                                                               
                local classicProps = {
                    "HairAccessory", "HatAccessory", "FaceAccessory", "NeckAccessory",
                    "ShouldersAccessory", "FrontAccessory", "BackAccessory", "WaistAccessory"
                }
                if PDesc then
                    for _, prop in ipairs(classicProps) do
                        pcall(function()
                            local val = PDesc[prop]
                            if val and type(val) == "string" and val ~= "" then
                                for idStr in val:gmatch("%d+") do
                                    addAccId(idStr)
                                end
                            end
                        end)
                    end
                end

                                                                                                      
                for _, child in ipairs(targetChar:GetChildren()) do
                    if child:IsA("Accessory") then
                        local attrId = child:GetAttribute("AssetId") or child:FindFirstChild("AssetId")
                        local numId = (attrId and tonumber(attrId)) or tonumber(child.Name:match("%d+"))
                        if numId then addAccId(numId) end

                        local handle = child:FindFirstChild("Handle")
                        if handle and CopyColors then
                            local surfApp = handle:FindFirstChild("AccessoryColorSurfaceAppearance")
                            local col = (surfApp and surfApp.Color) or (handle:IsA("BasePart") and handle.Color)
                            if col then
                                itemColors[child.Name] = col
                                if numId then itemColors[numId] = col end
                                local meshId = nil
                                if handle:IsA("MeshPart") and handle.MeshId and handle.MeshId ~= "" then
                                    meshId = handle.MeshId:match("%d+")
                                end
                                local smesh = handle:FindFirstChildOfClass("SpecialMesh")
                                if not meshId and smesh and smesh.MeshId and smesh.MeshId ~= "" then
                                    meshId = smesh.MeshId:match("%d+")
                                end
                                if meshId and tonumber(meshId) then
                                    itemColors[tonumber(meshId)] = col
                                end
                            end
                        end
                    end
                end

                local function isAccWornOnMe(accId)
                    if not accId or tonumber(accId) == 0 then return true end
                    local idNum = tonumber(accId)
                    local myC = LP.Character
                    if myC then
                        for _, c in ipairs(myC:GetChildren()) do
                            if c:IsA("Accessory") then
                                local attrId = c:GetAttribute("AssetId") or c:FindFirstChild("AssetId")
                                local numId = (attrId and tonumber(attrId)) or tonumber(c.Name:match("%d+"))
                                if numId and numId == idNum then return true end
                            end
                        end
                    end
                    local myH = myC and myC:FindFirstChildOfClass("Humanoid")
                    local desc = myH and myH:GetAppliedDescription()
                    if desc and desc.GetAccessories then
                        for _, a in ipairs(desc:GetAccessories(true)) do
                            if a.AssetId and tonumber(a.AssetId) == idNum then
                                return true
                            end
                        end
                    end
                    return false
                end

                                                
                if Remotes:FindFirstChild("ChangeCharacterBody") and PDesc then
                    local argsBody = {
                        [1] = {
                            [1] = tonumber(PDesc.Torso) or 0,
                            [2] = tonumber(PDesc.RightArm) or 0,
                            [3] = tonumber(PDesc.LeftArm) or 0,
                            [4] = tonumber(PDesc.RightLeg) or 0,
                            [5] = tonumber(PDesc.LeftLeg) or 0,
                            [6] = tonumber(PDesc.Head) or 0
                        }
                    }
                    pcall(function() Remotes.ChangeCharacterBody:InvokeServer(unpack(argsBody)) end)
                    task.wait(0.3)
                end

                                          
                local SkinColor = targetChar:FindFirstChild("Body Colors")
                if SkinColor and SkinColor.HeadColor and Remotes:FindFirstChild("ChangeBodyColor") then
                    pcall(function() Remotes.ChangeBodyColor:FireServer(tostring(SkinColor.HeadColor)) end)
                    task.wait(0.2)
                end

                                         
                local Bag = TPlayer:FindFirstChild("PlayersBag")
                if Bag then
                    if Bag:FindFirstChild("RPName") and Bag.RPName.Value ~= "" and Remotes:FindFirstChild("RPNameText") then
                        pcall(function() Remotes.RPNameText:FireServer("RolePlayName", Bag.RPName.Value) end)
                    end
                    if Bag:FindFirstChild("RPBio") and Bag.RPBio.Value ~= "" and Remotes:FindFirstChild("RPNameText") then
                        pcall(function() Remotes.RPNameText:FireServer("RolePlayBio", Bag.RPBio.Value) end)
                    end
                    if Bag:FindFirstChild("RPNameColor") and Remotes:FindFirstChild("RPNameColor") then
                        pcall(function() Remotes.RPNameColor:FireServer("PickingRPNameColor", Bag.RPNameColor.Value) end)
                    end
                    if Bag:FindFirstChild("RPBioColor") and Remotes:FindFirstChild("RPNameColor") then
                        pcall(function() Remotes.RPNameColor:FireServer("PickingRPBioColor", Bag.RPBioColor.Value) end)
                    end
                end

                if not CopyAvatarActive then _G.BTR_IS_COPYING_AVATAR = false return end

                                                                                  
                if wearRemote then
                    if targetShirtId and targetShirtId > 0 then
                        pcall(function() wearRemote:InvokeServer(targetShirtId) end)
                        task.wait(BROOKHAVEN_COOLDOWN)
                    end

                    if not CopyAvatarActive then _G.BTR_IS_COPYING_AVATAR = false return end

                    if targetPantsId and targetPantsId > 0 then
                        pcall(function() wearRemote:InvokeServer(targetPantsId) end)
                        task.wait(BROOKHAVEN_COOLDOWN)
                    end

                    if not CopyAvatarActive then _G.BTR_IS_COPYING_AVATAR = false return end

                    if targetFaceId and targetFaceId > 0 then
                        pcall(function() wearRemote:InvokeServer(targetFaceId) end)
                        task.wait(BROOKHAVEN_COOLDOWN)
                    end

                    if not CopyAvatarActive then _G.BTR_IS_COPYING_AVATAR = false return end

                                                                                       
                    local totalAccs = #accessoriesToWear
                    for idx, accId in ipairs(accessoriesToWear) do
                        if not CopyAvatarActive then break end
                        if not isAccWornOnMe(accId) then
                            game:GetService("StarterGui"):SetCore("SendNotification", {
                                Title = "Copy Avatar",
                                Text = "Equipping accessory " .. idx .. "/" .. totalAccs .. "...",
                                Duration = 2.0
                            })
                            pcall(function() wearRemote:InvokeServer(accId) end)
                            task.wait(BROOKHAVEN_COOLDOWN)
                        end
                    end

                    if not CopyAvatarActive then _G.BTR_IS_COPYING_AVATAR = false return end

                                             
                    if PDesc and tonumber(PDesc.IdleAnimation) and tonumber(PDesc.IdleAnimation) > 0 then
                        pcall(function() wearRemote:InvokeServer(tonumber(PDesc.IdleAnimation)) end)
                        task.wait(BROOKHAVEN_COOLDOWN)
                    end

                    if not CopyAvatarActive then _G.BTR_IS_COPYING_AVATAR = false return end

                                                                                               
                    local maxVerificationPasses = 3
                    local vPass = 0
                    while CopyAvatarActive and vPass < maxVerificationPasses do
                        vPass = vPass + 1
                        local missingAccs = {}
                        for _, accId in ipairs(accessoriesToWear) do
                            if not isAccWornOnMe(accId) then
                                table.insert(missingAccs, accId)
                            end
                        end

                        if #missingAccs == 0 then
                            break
                        end

                        game:GetService("StarterGui"):SetCore("SendNotification", {
                            Title = "Copy Avatar",
                            Text = "Sync verification " .. vPass .. "/3 (" .. #missingAccs .. " items remaining)...",
                            Duration = 2.5
                        })

                        for _, mId in ipairs(missingAccs) do
                            if not CopyAvatarActive then break end
                            pcall(function() wearRemote:InvokeServer(mId) end)
                            task.wait(BROOKHAVEN_COOLDOWN)
                        end
                    end
                end

                if not CopyAvatarActive then _G.BTR_IS_COPYING_AVATAR = false return end

                                                            
                if CopyColors and LP.Character then
                    task.wait(0.3)
                    local changeColorRemote = Remotes:FindFirstChild("ChangeItemColor") or Remotes:FindFirstChild("ChangeAccessoryColor") or Remotes:FindFirstChild("SetAccessoryColor")
                    if changeColorRemote then
                        for _, myAcc in ipairs(LP.Character:GetChildren()) do
                            if myAcc:IsA("Accessory") then
                                local col = itemColors[myAcc.Name]
                                local attrId = myAcc:GetAttribute("AssetId") or tonumber(myAcc.Name:match("%d+"))
                                if not col and attrId and itemColors[tonumber(attrId)] then
                                    col = itemColors[tonumber(attrId)]
                                end
                                local handle = myAcc:FindFirstChild("Handle")
                                if not col and handle then
                                    local meshId = (handle:IsA("MeshPart") and handle.MeshId and handle.MeshId:match("%d+"))
                                    if meshId and itemColors[tonumber(meshId)] then
                                        col = itemColors[tonumber(meshId)]
                                    end
                                end
                                if col and attrId then
                                    pcall(function() changeColorRemote:InvokeServer(tonumber(attrId), col) end)
                                    task.wait(0.05)
                                end
                            end
                        end
                    end
                end
                if CopyAvatarActive then
                    game:GetService("StarterGui"):SetCore("SendNotification", {
                        Title = "Copy Avatar",
                        Text = "Avatar copied successfully!",
                        Duration = 3
                    })
                end

                CopyAvatarActive = false
                _G.BTR_LAST_COPY_TIME = os.clock()
                task.spawn(function()
                    task.wait(1.5)
                    _G.BTR_IS_COPYING_AVATAR = false
                    if _G.BTR_SYNC_ANTI_COPY_BASELINE then
                        _G.BTR_SYNC_ANTI_COPY_BASELINE()
                    end
                end)
            end)
        end
    })

    AvatarTab:AddButton({
        Name = "Stop Copying",
        Callback = function()
            if CopyAvatarActive then
                CopyAvatarActive = false
                _G.BTR_IS_COPYING_AVATAR = false
                _G.BTR_LAST_COPY_TIME = os.clock()
                if _G.BTR_SYNC_ANTI_COPY_BASELINE then
                    _G.BTR_SYNC_ANTI_COPY_BASELINE()
                end
                game:GetService("StarterGui"):SetCore("SendNotification", {Title = "Copy Avatar", Text = "Copy cancelled!", Duration = 3})
            else
                game:GetService("StarterGui"):SetCore("SendNotification", {Title = "Copy Avatar", Text = "No copy currently in progress!", Duration = 3})
            end
        end
    })
    
    AvatarTab:AddSection({"Giant Mode (FE)"})
    
    local bigBodySaved = nil
    local BIG_IDS = { 81881085814072, 79115019295211, 106740492797177, 81153927159685, 88668275797583, 115379341593655 }
    local giantCooldown = false

    AvatarTab:AddToggle({
        Name = "Giant Mode",
        Description = "Applies a giant body to your character server-side (visible to all).",
        Default = false,
        Callback = function(val)
            if val then
                if giantCooldown then return end
                giantCooldown = true
                task.delay(1.0, function() giantCooldown = false end)
            end

            pcall(function()
                local player = game:GetService("Players").LocalPlayer
                local RS = game:GetService("ReplicatedStorage")
                local Remotes = RS:WaitForChild("Remotes", 5)
                if not Remotes then return end
                
                local char = player.Character
                if not char then return end
                local humanoid = char:FindFirstChildOfClass("Humanoid")
                if not humanoid then return end

                if val then
                    if not bigBodySaved then
                        local desc = humanoid:GetAppliedDescription()
                        bigBodySaved = {
                            desc.Torso, desc.RightArm, desc.LeftArm,
                            desc.RightLeg, desc.LeftLeg, desc.Head
                        }
                    end
                    Remotes.ChangeCharacterBody:InvokeServer(unpack({ [1] = BIG_IDS }))
                    game:GetService("StarterGui"):SetCore("SendNotification", { Title = "Giant (FE)", Text = "Giant body applied!", Duration = 3 })
                else
                    if not bigBodySaved then return end
                    local hasCustomParts = false
                    if bigBodySaved then
                        for _, id in ipairs(bigBodySaved) do
                            if tonumber(id) and tonumber(id) > 0 then
                                hasCustomParts = true
                                break
                            end
                        end
                    end

                    if hasCustomParts and Remotes:FindFirstChild("ChangeCharacterBody") then
                        pcall(function()
                            Remotes.ChangeCharacterBody:InvokeServer(unpack({ [1] = bigBodySaved }))
                        end)
                    end

                    local resetRemote = Remotes:FindFirstChild("ResetCharacterAppearance")
                    if resetRemote then
                        pcall(function()
                            resetRemote:FireServer()
                        end)
                    end

                    bigBodySaved = nil
                    game:GetService("StarterGui"):SetCore("SendNotification", { Title = "Giant (FE)", Text = "Normal size restored!", Duration = 3 })
                end
            end)
        end
    })

    
    
    
    AvatarTab:AddSection({"Chakra Armor (FE)"})

    local astralActive = false
    local astralTheme = "Purple"
    local astralScale = 11.0
    local astralIntensity = 1.0
    local astralLoop = nil
    local astralPhysicsLoop = nil
    local astralChest = nil
    local astralTurbines = {}
    local astralSmoothPos = nil
    local astralSmoothSpeed = 18.0
    local astralSenders = {}
    local ASTRAL_RATE = 0.03
    local astralRgbActive = false

    local ASTRAL_THEMES = {
        ["Purple"] = Color3.fromRGB(165, 30, 255),
        ["Blue"]   = Color3.fromRGB(0, 140, 255),
        ["Red"]    = Color3.fromRGB(240, 30, 20),
        ["Cyan"]   = Color3.fromRGB(0, 230, 230),
        ["Green"]  = Color3.fromRGB(30, 240, 80),
        ["Gold"]   = Color3.fromRGB(255, 215, 0),
        ["Black"]  = Color3.fromRGB(20, 15, 30),
        ["White"]  = Color3.fromRGB(255, 255, 255),
    }

    local function _0xH_3fc(scf, cf, prop)
        if not astralActive or not scf then return end
        if prop then
            pcall(function()
                if prop:IsA("Model") then
                    prop:PivotTo(cf)
                elseif prop:IsA("BasePart") then
                    prop.CFrame = cf
                end
            end)
        end

        local entry = astralSenders[scf]
        local now = tick()
        if not entry then
            entry = { lastSent = 0, nextCF = cf, sending = false }
            astralSenders[scf] = entry
        else
            entry.nextCF = cf
        end

        if not entry.sending and (now - entry.lastSent >= ASTRAL_RATE) then
            entry.sending = true
            entry.lastSent = now
            local toSend = entry.nextCF
            entry.nextCF = nil
            task.spawn(function()
                pcall(function() scf:InvokeServer(toSend) end)
                entry.sending = false
                if astralActive and entry.nextCF and (tick() - entry.lastSent >= ASTRAL_RATE) then
                    entry.sending = true
                    entry.lastSent = tick()
                    local nextSend = entry.nextCF
                    entry.nextCF = nil
                    task.spawn(function()
                        pcall(function() scf:InvokeServer(nextSend) end)
                        entry.sending = false
                    end)
                end
            end)
        end
    end

    local function _0xH_3fd(prop, col)
        if not prop then return end
        pcall(function()
            for _, p in ipairs(prop:GetDescendants()) do
                if p:IsA("BasePart") then
                    p.Material = Enum.Material.Neon
                    p.Color = col
                    p.CanCollide = false
                    p.CanTouch = false
                    p.CanQuery = false
                    p.Massless = true
                end
            end
        end)
    end

    local function _0xH_3fe(prop, cpc, col)
        if prop then
            pcall(function()
                for _, p in ipairs(prop:GetDescendants()) do
                    if p:IsA("BasePart") then
                        p.Material = Enum.Material.Neon
                        p.Color = col
                    end
                end
            end)
        end
        if cpc then
            task.spawn(function()
                pcall(function() cpc:InvokeServer(col) end)
            end)
        end
    end

    local function _0xH_3ff(themeName)
        astralTheme = themeName
        if themeName == "Rainbow RGB" then
            astralRgbActive = true
            return
        else
            astralRgbActive = false
        end

        local solidCol = ASTRAL_THEMES[themeName] or Color3.fromRGB(165, 30, 255)
        if astralChest and astralChest.prop then
            _0xH_3fe(astralChest.prop, astralChest.cpc, solidCol)
        end
        for _, entry in ipairs(astralTurbines) do
            if entry.prop then
                _0xH_3fe(entry.prop, entry.cpc, solidCol)
            end
        end
    end

    local function _0xH_400()
        astralActive = false
        if astralLoop then
            astralLoop:Disconnect()
            astralLoop = nil
        end
        if astralPhysicsLoop then
            astralPhysicsLoop:Disconnect()
            astralPhysicsLoop = nil
        end
        astralSenders = {}
        astralChest = nil
        astralTurbines = {}
        astralSmoothPos = nil
