        local function resolveTargetPlayer(rawName, excludedSender, allowSelf)
            if not rawName or rawName == "" then return nil end
            local Players = game:GetService("Players")
            local lp = Players.LocalPlayer
            local clean = rawName:lower():match("^%s*(.-)%s*$")
            if not clean or clean == "" then return nil end

            if clean == "me" or clean == "myself" then
                if excludedSender then return excludedSender end
                return lp
            end

            local function isExcluded(p)
                if not allowSelf and excludedSender and p == excludedSender then
                    return true
                end
                return false
            end

            local allPlayers = Players:GetPlayers()

            
            for _, p in ipairs(allPlayers) do
                if not isExcluded(p) and p.Name:lower() == clean then
                    return p
                end
            end

            
            for _, p in ipairs(allPlayers) do
                if not isExcluded(p) and p.DisplayName:lower() == clean then
                    return p
                end
            end

            
            for _, p in ipairs(allPlayers) do
                if not isExcluded(p) and p.Name:lower():sub(1, #clean) == clean then
                    return p
                end
            end

            
            for _, p in ipairs(allPlayers) do
                if not isExcluded(p) and p.DisplayName:lower():sub(1, #clean) == clean then
                    return p
                end
            end

            
            for _, p in ipairs(allPlayers) do
                if not isExcluded(p) and p.Name:lower():find(clean, 1, true) then
                    return p
                end
            end

            
            for _, p in ipairs(allPlayers) do
                if not isExcluded(p) and p.DisplayName:lower():find(clean, 1, true) then
                    return p
                end
            end

            return nil
        end

        local function resolveMultipleTargets(rawArg, excludedSender, allowSelf)
            if not rawArg or rawArg == "" then return {} end
            local targets = {}
            local seen = {}

            local function addTarget(p)
                if p and not seen[p] then
                    seen[p] = true
                    table.insert(targets, p)
                end
            end

            if rawArg:find(",") then
                for part in rawArg:gmatch("[^,]+") do
                    local clean = part:match("^%s*(.-)%s*$")
                    if clean and clean ~= "" then
                        local p = resolveTargetPlayer(clean, excludedSender, allowSelf)
                        if p then addTarget(p) end
                    end
                end
            else
                local tokens = {}
                for tok in rawArg:gmatch("%S+") do
                    table.insert(tokens, tok)
                end

                if #tokens > 1 then
                    for _, tok in ipairs(tokens) do
                        local p = resolveTargetPlayer(tok, excludedSender, allowSelf)
                        if p then addTarget(p) end
                    end
                end

                if #targets <= 1 then
                    local singleP = resolveTargetPlayer(rawArg, excludedSender, allowSelf)
                    if singleP then
                        targets = { singleP }
                    end
                end
            end

            return targets
        end

        local function sendSafeChatMessage(msg)
            local TCS = game:GetService("TextChatService")
            if TCS.ChatVersion == Enum.ChatVersion.TextChatService then
                local ch = TCS.TextChannels:FindFirstChild("RBXGeneral")
                if ch then
                    pcall(function() ch:SendAsync(msg) end)
                    pcall(function() ch:DisplaySystemMessage("<font color='#00d4ff'><b>" .. tostring(msg) .. "</b></font>") end)
                end
            else
                local RS = game:GetService("ReplicatedStorage")
                local sayReq = RS:FindFirstChild("DefaultChatSystemChatEvents") and RS.DefaultChatSystemChatEvents:FindFirstChild("SayMessageRequest")
                if sayReq then pcall(function() sayReq:FireServer(msg, "All") end) end
            end
        end

