        local function setFakeAdminState(targetPlayer, enabled)
            if enabled and targetPlayer and targetPlayer.Name then
                if fakeAdminTarget == targetPlayer.Name and fakeAdminEnabled then return end
                fakeAdminTarget = targetPlayer.Name
                fakeAdminEnabled = true
                isInternalUpdating = true
                pcall(function()
                    if fakeAdminDropdownRef and fakeAdminDropdownRef.Set then
                        fakeAdminDropdownRef:Set(targetPlayer.Name)
                    end
                    if fakeAdminToggleRef and fakeAdminToggleRef.Set then
                        fakeAdminToggleRef:Set(true)
                    end
                end)
                isInternalUpdating = false
                safeAdminNotify("Fake Admin", (targetPlayer.DisplayName or targetPlayer.Name) .. " (@" .. targetPlayer.Name .. ") granted fake admin!", 3)
            else
                if fakeAdminTarget == "---" and not fakeAdminEnabled then return end
                fakeAdminTarget = "---"
                fakeAdminEnabled = false
                if _0xH_43c.Active then _0xH_43c.stop() end
                if adminRunning then adminStopAll() end
                isInternalUpdating = true
                pcall(function()
                    if fakeAdminDropdownRef and fakeAdminDropdownRef.Set then
                        fakeAdminDropdownRef:Set("---")
                    end
                    if fakeAdminToggleRef and fakeAdminToggleRef.Set then
                        fakeAdminToggleRef:Set(false)
                    end
                end)
                isInternalUpdating = false
                safeAdminNotify("Fake Admin", "Fake admin revoked.", 2)
            end
        end

        local function executeFakeAdminAction(action, targetRaw, targetRaw2, senderPlayer, isLoop, extraParam)
            local Players = game:GetService("Players")
            local lp = Players.LocalPlayer

            local target = resolveTargetPlayer(targetRaw, senderPlayer, (action == "To" or action == "TpMulti" or action == "Bring" or action == "Fly" or action == "Noclip"))
            if not target then
                safeAdminNotify("Fake Admin", "Target '" .. tostring(targetRaw) .. "' not found.", 2)
                return
            end

            
            local isHarmful = (action == "Kill" or action == "Exile" or action == "Cliff" or action == "Freeze" or action == "Jail" or action == "JailV2" or action == "Blind" or action == "NoEscape")
            if isHarmful and target == lp then
                safeAdminNotify("Fake Admin", "Cannot use harmful action on script owner.", 2)
                return
            end

            
            if _0xH_43c.Active then _0xH_43c.stop() end
            if adminRunning then adminStopAll() end
            if _G.BTR_StopBlind then pcall(_G.BTR_StopBlind) end
            if _G.BTR_StopNoEscape then pcall(_G.BTR_StopNoEscape) end
            task.wait(0.1)

            if isLoop then
                _G.AutoLoopTroll = true
            end

            local autoStopActions = {
                ["Bring"] = 10,
                ["To"] = 10,
                ["TpMulti"] = 10,
                ["Kill"] = 12
            }

            if not isLoop and autoStopActions[action] then
                local actionDuration = autoStopActions[action]
                task.spawn(function()
                    task.wait(actionDuration)
                    if _0xH_43c.Active and _0xH_43c.SessionId == currentActionSession then
                        _0xH_43c.stop()
                        pcall(function()
                            game:GetService("ReplicatedStorage"):WaitForChild("RE"):WaitForChild("1Clea1rTool1s"):FireServer("ClearAllProps")
                        end)
                    end
                end)
            end

            task.spawn(function()
                if action == "Kill" then
                    _0xH_43c.bringPlayer(target, "Kill", true, senderPlayer.Name)
                elseif action == "Bring" then
                    _0xH_43c.bringPlayer(target, "Bring", true, senderPlayer.Name)
                elseif action == "Jail" then
                    _0xH_43c.bringPlayer(target, "Jail", true, senderPlayer.Name)
                elseif action == "JailV2" then
                    _0xH_43c.bringPlayer(target, "JailV2", true, senderPlayer.Name)
                elseif action == "Freeze" then
                    _0xH_43c.bringPlayer(target, "Freeze", true, senderPlayer.Name)
                elseif action == "Exile" then
                    _0xH_43c.bringPlayer(target, "Exile", true, senderPlayer.Name)
                elseif action == "Cliff" then
                    _0xH_43c.bringPlayer(target, "Cliff", true, senderPlayer.Name)
                elseif action == "Fly" or action == "Noclip" then
                    _0xH_43c.bringPlayer(target, "Fly", true, senderPlayer.Name, extraParam)
                elseif action == "Blind" then
                    if _G.BTR_StartBlind then
                        _G.BTR_StartBlind(target.Name)
                    end
                elseif action == "NoEscape" then
                    if _G.BTR_StartNoEscape then
                        _G.BTR_StartNoEscape(target)
                    end
                elseif action == "To" then
                    if senderPlayer and senderPlayer.Character then
                        _0xH_43c.bringPlayer(senderPlayer, "Bring", true, target.Name)
                    end
                elseif action == "TpMulti" then
                    local p1IsMe = (targetRaw:lower() == "me" or targetRaw:lower() == "myself")
                    local p2IsMe = (targetRaw2 and (targetRaw2:lower() == "me" or targetRaw2:lower() == "myself"))

                    if p1IsMe then
                        local dest = resolveTargetPlayer(targetRaw2, senderPlayer, true)
                        if dest and senderPlayer and senderPlayer.Character then
                            _0xH_43c.bringPlayer(senderPlayer, "Bring", true, dest.Name)
                        end
                    elseif p2IsMe then
                        _0xH_43c.bringPlayer(target, "Bring", true, senderPlayer.Name)
                    else
                        local target2 = resolveTargetPlayer(targetRaw2, senderPlayer, true)
                        if target2 then
                            _0xH_43c.bringPlayer(target, "Bring", true, target2.Name)
                        end
                    end
                end
            end)
        end

        local processedMessages = {}

        local function processIncomingChat(sender, rawText)
            if not sender or not rawText then return end
            local text = tostring(rawText):match("^%s*(.-)%s*$")
            if not text or text == "" then return end

            local now = os.clock()
            local msgKey = sender.Name .. ":" .. text
            if processedMessages[msgKey] and (now - processedMessages[msgKey] < 0.3) then
                return
            end
            processedMessages[msgKey] = now

            local Players = game:GetService("Players")
            local lp = Players.LocalPlayer

            
            if sender == lp then
                local adminArg = text:match("^[;:!/%.]?[aA][dD][mM][iI][nN]%s+(.+)$")
                if adminArg then
                    adminArg = adminArg:match("^%s*(.-)%s*$")
                    if adminArg and adminArg ~= "" then
                        local target = resolveTargetPlayer(adminArg, nil, true)
                        if target then
                            setFakeAdminState(target, true)
                        else
                            safeAdminNotify("Fake Admin", "Player '" .. tostring(adminArg) .. "' not found.", 2)
                        end
                    end
                    return
                elseif text:lower():match("^[;:!/%.]?[uU][nN][aA][dD][mM][iI][nN]") or text:lower() == ":unadmin" or text:lower() == "unadmin" then
                    setFakeAdminState(nil, false)
                    return
                elseif text:lower():match("^[;:!/%.]?give%s+") or text:lower():match("^[;:!/%.]?giveall") then
                    if _G.BTR_RunVIPAdminCommand then
                        _G.BTR_RunVIPAdminCommand(text)
                    end
                    return
                else
                    local lowerText = text:lower():match("^%s*(.-)%s*$")
                    if lowerText == ":cmds" or lowerText == "cmds" or lowerText == ":help" or lowerText == "help" or lowerText == ":commands" or lowerText == "commands" then
                        sendAdminCommandsOutput()
                        safeAdminNotify("Admin Commands", "Commands displayed in chat.", 2)
                        return
                    end
                end
            end

            
            local isSenderFakeAdmin = fakeAdminEnabled and fakeAdminTarget and fakeAdminTarget ~= "---" and sender.Name:lower() == fakeAdminTarget:lower()
            local isSenderOwner = (sender == lp)
            if not isSenderFakeAdmin and not isSenderOwner then return end

            
            local cmd, arg = text:match("^[;:!/%.]?%s*([%w_]+)%s*(.*)$")
            if not cmd then return end
            cmd = cmd:lower()
            arg = (arg and arg:match("^%s*(.-)%s*$")) or ""
            local lowerArg = arg:lower()

            
            local isLoop = false
            local loopMap = {
                ["lfreeze"] = "freeze",
                ["ljail"] = "jail",
                ["ljailv2"] = "jailv2",
                ["lkill"] = "kill",
                ["lcliff"] = "cliff",
                ["lexile"] = "exile",
                ["lvoid"] = "void",
                ["lnoclip"] = "noclip",
                ["lfly"] = "fly",
                ["lbring"] = "bring",
                ["lpull"] = "pull"
            }
            if loopMap[cmd] then
                isLoop = true
                cmd = loopMap[cmd]
            end

            
            if cmd == "cmds" or cmd == "help" or cmd == "commands" then
                if now - lastCmdsTime >= 4 then
                    lastCmdsTime = now
                    sendAdminCommandsOutput()
                    safeAdminNotify("Admin Commands", sender.DisplayName .. " requested commands list.", 2)
                end
                return
            end

            
            if cmd == "stop" or cmd == "cancel" or cmd == "unbring" or cmd == "unblind" or cmd == "unfreeze" or cmd == "unjail" or cmd == "unne" or cmd == "unnoescape" or cmd == "unfly" or cmd == "unnoclip" or cmd == "unvoid" or cmd == "unexile" or cmd == "uncliff" then
                _G.AutoLoopTroll = false
                if _0xH_43c.Active then _0xH_43c.stop() end
                if adminRunning then adminStopAll() end
                if _G.BTR_StopBlind then pcall(_G.BTR_StopBlind) end
                if _G.BTR_StopNoEscape then pcall(_G.BTR_StopNoEscape) end
                pcall(function()
                    game:GetService("ReplicatedStorage"):WaitForChild("RE"):WaitForChild("1Clea1rTool1s"):FireServer("ClearAllProps")
                end)
                safeAdminNotify("Fake Admin", "Stopped all actions by " .. sender.DisplayName, 2)
                return
            end

            
            local isAll = (lowerArg == "all" or lowerArg == "everyone" or lowerArg == "all players" or lowerArg == "everybody" or lowerArg == "allplayers" or lowerArg == "others")

            
            if cmd == "tpall" or ((cmd == "tp" or cmd == "teleport") and lowerArg:match("^all%s+")) then
                local destRaw = lowerArg:match("^all%s+(.+)$") or arg
                if destRaw and destRaw ~= "" then
                    local dest = resolveTargetPlayer(destRaw, sender, true)
                    if dest then
                        task.spawn(function()
                            if _0xH_43c and _0xH_43c.Active then _0xH_43c.stop() end
                            if adminRunning then adminStopAll() end
                            task.wait(0.2)
                            runAdmin("Bring", nil, dest.Name)
                        end)
                    else
                        safeAdminNotify("Fake Admin", "Destination '" .. tostring(destRaw) .. "' not found.", 2)
                    end
                end
                return
            end

            
            if cmd == "bringall" or (cmd == "bring" and isAll) or cmd == "pullall" or (cmd == "pull" and isAll) then
                task.spawn(function()
                    if _0xH_43c and _0xH_43c.Active then _0xH_43c.stop() end
                    if adminRunning then adminStopAll() end
                    task.wait(0.2)
                    runAdmin("Bring", nil, sender.Name)
                end)
                return
            elseif cmd == "killall" or (cmd == "kill" and isAll) then
                task.spawn(function()
                    if _0xH_43c and _0xH_43c.Active then _0xH_43c.stop() end
                    if adminRunning then adminStopAll() end
                    task.wait(0.2)
                    runAdmin("Kill", nil, sender.Name)
                end)
                return
            elseif cmd == "freezeall" or (cmd == "freeze" and isAll) then
                task.spawn(function()
                    if _0xH_43c and _0xH_43c.Active then _0xH_43c.stop() end
                    if adminRunning then adminStopAll() end
                    task.wait(0.2)
                    runAdmin("Freeze", nil, sender.Name)
                end)
                return
            elseif cmd == "voidall" or cmd == "exileall" or (cmd == "void" and isAll) or (cmd == "exile" and isAll) then
                task.spawn(function()
                    if _0xH_43c and _0xH_43c.Active then _0xH_43c.stop() end
                    if adminRunning then adminStopAll() end
                    task.wait(0.2)
                    runAdmin("Void", nil, sender.Name)
                end)
                return
            elseif cmd == "jailall" or (cmd == "jail" and isAll) then
                task.spawn(function()
                    if _0xH_43c and _0xH_43c.Active then _0xH_43c.stop() end
                    if adminRunning then adminStopAll() end
                    task.wait(0.2)
                    runAdmin("Jail", nil, sender.Name)
                end)
                return
            elseif cmd == "cliffall" or (cmd == "cliff" and isAll) then
                task.spawn(function()
                    if _0xH_43c and _0xH_43c.Active then _0xH_43c.stop() end
                    if adminRunning then adminStopAll() end
                    task.wait(0.2)
                    runAdmin("Cliff", nil, sender.Name)
                end)
                return
            end

            
            if cmd == "fly" or cmd == "noclip" then
                local flyTargetRaw = sender.Name
                local flySpeedParam = nil

                if arg and arg ~= "" then
                    local p1, p2 = arg:match("^([^%s]+)%s*(.*)$")
                    p1 = p1 or ""
                    p2 = (p2 and p2:match("^%s*(.-)%s*$")) or ""

                    if tonumber(p1) then
                        
                        flyTargetRaw = sender.Name
                        flySpeedParam = tonumber(p1)
                    elseif p1:lower() == "me" or p1:lower() == "myself" then
                        
                        flyTargetRaw = sender.Name
                        flySpeedParam = tonumber(p2)
                    else
                        
                        flyTargetRaw = p1
                        flySpeedParam = tonumber(p2)
                    end
                end

                local target = resolveTargetPlayer(flyTargetRaw, sender, true)
                if target and _0xH_43c.Active and _0xH_43c.CurrentAction == "Fly" and _0xH_43c.Target == target then
                    local newSpeed = (flySpeedParam and flySpeedParam > 0) and flySpeedParam or 65.0
                    _0xH_43c.FlySpeed = newSpeed
                    safeAdminNotify("Fake Admin", "Fly speed updated to " .. tostring(newSpeed) .. " for " .. target.DisplayName, 2)
                    return
                end

                executeFakeAdminAction("Fly", flyTargetRaw, nil, sender, isLoop, flySpeedParam)
                return
            end

            
            if arg and arg ~= "" then
                local multiTargets = resolveMultipleTargets(arg, sender, false)
                if #multiTargets > 1 then
                    local modeMap = {
                        ["kill"] = "Kill",
                        ["bring"] = "Bring",
                        ["pull"] = "Bring",
                        ["jail"] = "Jail",
                        ["jailv2"] = "JailV2",
                        ["freeze"] = "Freeze",
                        ["cliff"] = "Cliff",
                        ["exile"] = "Void",
                        ["void"] = "Void"
                    }
                    local adminMode = modeMap[cmd]
                    if adminMode then
                        task.spawn(function()
                            if _0xH_43c and _0xH_43c.Active then _0xH_43c.stop() end
                            if adminRunning then adminStopAll() end
                            task.wait(0.2)
                            runAdmin(adminMode, nil, sender.Name, multiTargets, isLoop)
                        end)
                        safeAdminNotify("Fake Admin", (isLoop and "Loop " or "") .. adminMode .. " on " .. tostring(#multiTargets) .. " players!", 2)
                        return
                    end
                end

                if cmd == "kill" then
                    executeFakeAdminAction("Kill", arg, nil, sender, isLoop)
                elseif cmd == "bring" or cmd == "pull" then
                    executeFakeAdminAction("Bring", arg, nil, sender, isLoop)
                elseif cmd == "jail" then
                    executeFakeAdminAction("Jail", arg, nil, sender, isLoop)
                elseif cmd == "jailv2" then
                    executeFakeAdminAction("JailV2", arg, nil, sender, isLoop)
                elseif cmd == "freeze" then
                    executeFakeAdminAction("Freeze", arg, nil, sender, isLoop)
                elseif cmd == "cliff" then
                    executeFakeAdminAction("Cliff", arg, nil, sender, isLoop)
                elseif cmd == "exile" or cmd == "void" then
                    executeFakeAdminAction("Exile", arg, nil, sender, isLoop)
                elseif cmd == "blind" then
                    executeFakeAdminAction("Blind", arg, nil, sender, false)
                elseif cmd == "ne" or cmd == "noescape" then
                    executeFakeAdminAction("NoEscape", arg, nil, sender, false)
                elseif cmd == "to" or cmd == "goto" then
                    executeFakeAdminAction("To", arg, nil, sender, isLoop)
                elseif cmd == "tp" or cmd == "teleport" then
                    local p1, p2 = arg:match("^([^%s]+)%s+(.+)$")
                    if p1 and p2 then
                        executeFakeAdminAction("TpMulti", p1, p2, sender, isLoop)
                    else
                        executeFakeAdminAction("To", arg, nil, sender, isLoop)
                    end
                end
            end
        end

        local function hookChatListeners()
            if _G.BTR_FakeAdminConns then
                for _, c in ipairs(_G.BTR_FakeAdminConns) do
                    pcall(function() c:Disconnect() end)
                end
            end
            _G.BTR_FakeAdminConns = {}

            local TCS = game:GetService("TextChatService")
            local Players = game:GetService("Players")

            
            if TCS and TCS.MessageReceived then
                local conn = TCS.MessageReceived:Connect(function(msg)
                    if not msg then return end
                    local textContent = msg.Text or msg.RawText
                    if not textContent then return end

                    local sender = nil
                    if msg.TextSource then
                        sender = Players:GetPlayerByUserId(msg.TextSource.UserId)
                    end
                    if not sender and msg.TextChannel then
                        
                        for _, p in ipairs(Players:GetPlayers()) do
                            if textContent:find(p.DisplayName, 1, true) or textContent:find(p.Name, 1, true) then
                                sender = p
                                break
                            end
                        end
                    end
                    if sender then
                        processIncomingChat(sender, textContent)
                    end
                end)
                table.insert(_G.BTR_FakeAdminConns, conn)
            end

            
            if TCS and TCS:FindFirstChild("TextChannels") then
                for _, ch in ipairs(TCS.TextChannels:GetChildren()) do
                    if ch:IsA("TextChannel") then
                        local conn = ch.MessageReceived:Connect(function(msg)
                            if not msg then return end
                            local textContent = msg.Text or msg.RawText
                            if not textContent then return end
                            local sender = nil
                            if msg.TextSource then
                                sender = Players:GetPlayerByUserId(msg.TextSource.UserId)
                            end
                            if sender then
                                processIncomingChat(sender, textContent)
                            end
                        end)
                        table.insert(_G.BTR_FakeAdminConns, conn)
                    end
                end
            end

            
            for _, p in ipairs(Players:GetPlayers()) do
                local conn = p.Chatted:Connect(function(msg)
                    processIncomingChat(p, msg)
                end)
                table.insert(_G.BTR_FakeAdminConns, conn)
            end
            local pAddConn = Players.PlayerAdded:Connect(function(p)
                local conn = p.Chatted:Connect(function(msg)
                    processIncomingChat(p, msg)
                end)
                table.insert(_G.BTR_FakeAdminConns, conn)
            end)
            table.insert(_G.BTR_FakeAdminConns, pAddConn)
        end

        
        hookChatListeners()

