                end

                
                task.delay(1.0, function()
                    pcall(function()
                        local toolRemote = rep:FindFirstChild("RE") and rep.RE:FindFirstChild("1Too1l")
                        if toolRemote then toolRemote:InvokeServer("PickingTools", "PropMaker") end
                        local pmTool = (lp.Character and lp.Character:FindFirstChild("PropMaker")) or (lp.Backpack and lp.Backpack:FindFirstChild("PropMaker"))
                        if pmTool then pmTool:Destroy() end
                        local hum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
                        if hum then hum:UnequipTools() end
                    end)
                end)

                while #bedProps < 10 do table.insert(bedProps, bedProps[#bedProps]) end
                while #bunkerProps < 5 do table.insert(bunkerProps, bunkerProps[#bunkerProps]) end

                local function getPropRemotes(p)
                    if not p then return nil, nil end
                    local scf = p:FindFirstChild("SetCurrentCFrame") or p:FindFirstChild("SetCurrentCFrame", true)
                    local cpc = p:FindFirstChild("ChangePropColor") or p:FindFirstChild("ChangePropColor", true)
                    return scf, cpc
                end

                local bk1Scf, bk1Cpc = getPropRemotes(bunkerProps[1])
                local bk2Scf, bk2Cpc = getPropRemotes(bunkerProps[2])
                local bk3Scf, bk3Cpc = getPropRemotes(bunkerProps[3])
                local bk4Scf, bk4Cpc = getPropRemotes(bunkerProps[4])
                local bk5Scf, bk5Cpc = getPropRemotes(bunkerProps[5])

                local bd1Scf, bd1Cpc = getPropRemotes(bedProps[1])
                local bd2Scf, bd2Cpc = getPropRemotes(bedProps[2])
                local bd3Scf, bd3Cpc = getPropRemotes(bedProps[3])
                local bd4Scf, bd4Cpc = getPropRemotes(bedProps[4])
                local bd5Scf, bd5Cpc = getPropRemotes(bedProps[5])
                local bd6Scf, bd6Cpc = getPropRemotes(bedProps[6])
                local bd7Scf, bd7Cpc = getPropRemotes(bedProps[7])
                local bd8Scf, bd8Cpc = getPropRemotes(bedProps[8])
                local bd9Scf, bd9Cpc = getPropRemotes(bedProps[9])
                local bd10Scf, bd10Cpc = getPropRemotes(bedProps[10])

                titanPartsList = {
                    { name = "UpperTorso",    scf = bk1Scf, prop = bunkerProps[1], cpc = bk1Cpc, offset = CFrame.new(0, -2.5, 0) },
                    { name = "Head",          scf = bd1Scf, prop = bedProps[1],    cpc = bd1Cpc, offset = CFrame.new(0, 1.5, 0) * CFrame.Angles(math.rad(-90), 0, 0) },
                    { name = "LowerTorso",    scf = bd2Scf, prop = bedProps[2],    cpc = bd2Cpc, offset = CFrame.Angles(0, 0, math.rad(90)) },

                    { name = "LeftUpperArm",  scf = bd3Scf, prop = bedProps[3],    cpc = bd3Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
                    { name = "LeftLowerArm",  scf = bk2Scf, prop = bunkerProps[2], cpc = bk2Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
                    { name = "LeftHand",      scf = bd4Scf, prop = bedProps[4],    cpc = bd4Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },

                    { name = "RightUpperArm", scf = bd5Scf, prop = bedProps[5],    cpc = bd5Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
                    { name = "RightLowerArm", scf = bk3Scf, prop = bunkerProps[3], cpc = bk3Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
                    { name = "RightHand",     scf = bd6Scf, prop = bedProps[6],    cpc = bd6Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },

                    { name = "LeftUpperLeg",  scf = bd7Scf, prop = bedProps[7],    cpc = bd7Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
                    { name = "LeftLowerLeg",  scf = bk4Scf, prop = bunkerProps[4], cpc = bk4Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
                    { name = "LeftFoot",      scf = bd8Scf, prop = bedProps[8],    cpc = bd8Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },

                    { name = "RightUpperLeg", scf = bd9Scf, prop = bedProps[9],    cpc = bd9Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
                    { name = "RightLowerLeg", scf = bk5Scf, prop = bunkerProps[5], cpc = bk5Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
                    { name = "RightFoot",     scf = bd10Scf, prop = bedProps[10],  cpc = bd10Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
                }

                applyWhiteTheme()
                task.delay(0.5, applyWhiteTheme)

                local pChar = pilotPlayer and pilotPlayer.Character
                local pHrp = pChar and pChar:FindFirstChild("HumanoidRootPart")
                local myChar = lp.Character
                local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")

                titanWorldPos = bedPos
                local facingVec = pHrp and pHrp.CFrame.LookVector or (myHrp and myHrp.CFrame.LookVector or Vector3.new(0, 0, -1))
                titanHeading = math.deg(math.atan2(-facingVec.X, -facingVec.Z))

                titanPhysicsLoop = rs.Stepped:Connect(function()
                    if not titanActive then return end
                    for _, entry in ipairs(titanPartsList) do
                        if entry.prop then
                            pcall(function()
                                for _, p in ipairs(entry.prop:GetDescendants()) do
                                    if p:IsA("BasePart") then
                                        p.CanCollide = false
                                        p.CanTouch = false
                                        p.CanQuery = false
                                        p.Massless = true
                                    end
                                end
                            end)
                        end
                    end
                end)

                local rayParams = RaycastParams.new()
                rayParams.FilterType = Enum.RaycastFilterType.Exclude

                local lastTick = tick()
                local spawnStartTick = tick()
                local riseDuration = 1.0

                local smoothedLowestFootY = nil
                local lastCenterY = nil
                local currentWalkSpeed = 0
                local lastMoveDir = nil

                titanLoop = rs.RenderStepped:Connect(function()
                    if not titanActive then return end
                    local now = tick()
                    local dt = math.clamp(now - lastTick, 0.001, 0.1)
                    lastTick = now

                    local activePilot = currentPilot or pilotPlayer
                    if activePilot and activePilot ~= lp then
                        if not activePilot.Parent or not activePilot:IsDescendantOf(plrs) then
                            notify("Titan Controller", (activePilot.DisplayName or "Pilot") .. " left the game. Dismantling Titan...", 3)
                            stopTitan()
                            return
                        end
                    end

                    
                    if cockpitBed and cockpitBed.Parent then
                        for _, desc in ipairs(cockpitBed:GetDescendants()) do
                            if desc:IsA("Seat") or desc:IsA("VehicleSeat") then
                                local occ = desc.Occupant
                                if occ and occ:IsA("Humanoid") and occ.Parent then
                                    local p = plrs:GetPlayerFromCharacter(occ.Parent)
                                    if p and p ~= activePilot then
                                        occ.Sit = false
                                        notify("Titan Controller", (p.DisplayName or "Player") .. " ejected from cockpit!", 2)
                                    end
                                end
                            end
                        end
                    end

                    local pCharNow = activePilot and activePilot.Character
                    local pHum = pCharNow and pCharNow:FindFirstChildOfClass("Humanoid")

                    local moveDir = Vector3.zero
                    local _0xH_434 = false
                    local rawMag = 0

                    local JOYSTICK_DEADZONE = 0.22
                    local EMOTE_CANCEL_DEADZONE = 0.35

                    
                    local isPilotSeated = pHum and (pHum.Sit == true or (pHum.SeatPart and pHum.SeatPart:IsDescendantOf(cockpitBed)))
                    if isPilotSeated then
                        rawMag = pHum.MoveDirection.Magnitude
                        if rawMag > JOYSTICK_DEADZONE then
                            moveDir = pHum.MoveDirection
                            _0xH_434 = true
                        end
                    end

                    titanIsMoving = _0xH_434

                    if _0xH_434 then
                        if rawMag > EMOTE_CANCEL_DEADZONE then
                            if currentEmoteTrack then
                                pcall(function() currentEmoteTrack:Stop(0.15) end)
                                currentEmoteTrack = nil
                                currentEmoteIndex = nil
                            end
                        end
                        if not currentEmoteTrack then
                            if ghostIdleTrack and ghostIdleTrack.IsPlaying then
                                ghostIdleTrack:Stop(0.15)
                            end
                            if ghostRunTrack and not ghostRunTrack.IsPlaying then
                                ghostRunTrack:Play(0.15)
                                ghostRunTrack:AdjustSpeed(titanConfig.animSpeed)
                            end
                        end
                    else
                        if ghostRunTrack and ghostRunTrack.IsPlaying then
                            ghostRunTrack:Stop(0.15)
                        end
                        if currentEmoteTrack then
                            if not currentEmoteTrack.IsPlaying then
                                pcall(function() currentEmoteTrack:Play(0.1) end)
                            end
                            if ghostIdleTrack and ghostIdleTrack.IsPlaying then
                                ghostIdleTrack:Stop(0.1)
                            end
                        else
                            if ghostIdleTrack and not ghostIdleTrack.IsPlaying then
                                ghostIdleTrack:Play(0.15)
                            end
                        end
                    end

                    local targetSpeed = 0
                    if _0xH_434 then
                        local speedScale = math.clamp((rawMag - JOYSTICK_DEADZONE) / (1.0 - JOYSTICK_DEADZONE), 0.35, 1.0)
                        targetSpeed = titanConfig.walkSpeed * speedScale
                    end

                    local accelRate = _0xH_434 and 7.0 or 12.0
                    currentWalkSpeed = currentWalkSpeed + (targetSpeed - currentWalkSpeed) * math.clamp(dt * accelRate, 0, 1)

                    if currentWalkSpeed > 0.3 then
                        local forwardVec = (_0xH_434 and moveDir.Unit) or lastMoveDir or Vector3.new(0, 0, -1)
                        if _0xH_434 then lastMoveDir = moveDir.Unit end

                        local targetAngle = math.deg(math.atan2(-forwardVec.X, -forwardVec.Z))
                        local diff = (targetAngle - titanHeading + 180) % 360 - 180
                        titanHeading = titanHeading + (diff * math.clamp(dt * titanConfig.turnSpeed, 0, 1))

                        local step = forwardVec * (currentWalkSpeed * dt)
                        titanWorldPos = titanWorldPos + Vector3.new(step.X, 0, step.Z)
                    end

                    local rayFilter = {ghostRig, workspace:FindFirstChild("WorkspaceCom")}
                    for _, plr in ipairs(plrs:GetPlayers()) do
                        if plr.Character then table.insert(rayFilter, plr.Character) end
                    end
                    rayParams.FilterDescendantsInstances = rayFilter

                    local rayOrigin = Vector3.new(titanWorldPos.X, titanWorldPos.Y + 15, titanWorldPos.Z)
                    local ray = workspace:Raycast(rayOrigin, Vector3.new(0, -60, 0), rayParams)
                    local groundY = (ray and ray.Position) and ray.Position.Y or titanWorldPos.Y

                    local ghostRoot = ghostRig and ghostRig:FindFirstChild("HumanoidRootPart")
                    local ghostRootCF = ghostRoot and ghostRoot.CFrame or CFrame.new()

                    local leftFootLimb = getGhostLimb(ghostRig, "LeftFoot")
                    local rightFootLimb = getGhostLimb(ghostRig, "RightFoot")
                    local lowestFootRelY = -2.45 * titanConfig.size

                    if leftFootLimb and rightFootLimb then
                        local lRel = ghostRootCF:ToObjectSpace(leftFootLimb.CFrame)
                        local rRel = ghostRootCF:ToObjectSpace(rightFootLimb.CFrame)
                        local lY = lRel.Position.Y * titanConfig.size + titanConfig.legOffsetY
                        local rY = rRel.Position.Y * titanConfig.size + titanConfig.legOffsetY
                        lowestFootRelY = math.min(lY, rY)

                        if currentEmoteTrack and currentEmoteTrack.IsPlaying then
                            local pelvisLimb = getGhostLimb(ghostRig, "LowerTorso")
                            if pelvisLimb then
                                local pRel = ghostRootCF:ToObjectSpace(pelvisLimb.CFrame)
                                local pY = pRel.Position.Y * titanConfig.size + titanConfig.pelvisOffsetY
                                lowestFootRelY = math.min(lowestFootRelY, pY)
                            end
                        end
                    end

                    
                    if not smoothedLowestFootY then
                        smoothedLowestFootY = lowestFootRelY
                    else
                        smoothedLowestFootY = smoothedLowestFootY + (lowestFootRelY - smoothedLowestFootY) * math.clamp(dt * 8, 0, 1)
                    end

                    local bedHalfThickness = 0.8
                    local targetFinalCenterY = groundY - smoothedLowestFootY - bedHalfThickness + titanConfig.heightOffset
                    if not lastCenterY then
                        lastCenterY = targetFinalCenterY
                    else
                        lastCenterY = lastCenterY + (targetFinalCenterY - lastCenterY) * math.clamp(dt * 12, 0, 1)
                    end

                    local elapsed = now - spawnStartTick
                    local riseAlpha = math.clamp(elapsed / riseDuration, 0, 1)
                    local ease = 1 - math.pow(1 - riseAlpha, 3)
                    local activeCenterY = groundY + ((lastCenterY - groundY) * ease)

                    local targetCenterCF = CFrame.new(titanWorldPos.X, activeCenterY, titanWorldPos.Z) * CFrame.Angles(0, math.rad(titanHeading), 0)
                    if not currentGigOrigin then
                        currentGigOrigin = targetCenterCF
                    else
                        currentGigOrigin = currentGigOrigin:Lerp(targetCenterCF, math.clamp(dt * 18, 0, 1))
                    end
                    local centerCF = currentGigOrigin

                    local normX, normY, normZ = 1.0, 1.0, 1.0
                    local refHum = pHum or (ghostRig and ghostRig:FindFirstChildOfClass("Humanoid"))
                    if refHum then
                        local bhs = refHum:FindFirstChild("BodyHeightScale")
                        local bws = refHum:FindFirstChild("BodyWidthScale")
                        local bds = refHum:FindFirstChild("BodyDepthScale")
                        local curH = (bhs and bhs.Value) or 1.0
                        local curW = (bws and bws.Value) or 1.0
                        local curD = (bds and bds.Value) or 1.0
                        if curH > 0.01 then normY = curH / 1.0499999523162842 end
                        if curW > 0.01 then normX = curW / 0.7000001072883606 end
                        if curD > 0.01 then normZ = curD / 0.8500000834465027 end
                    end

                    for _, entry in ipairs(titanPartsList) do
                        if entry.scf then
                            local limbPart = getGhostLimb(ghostRig, entry.name)
                            if limbPart then
                                local rel = ghostRootCF:ToObjectSpace(limbPart.CFrame)
                                local unscaledX = rel.Position.X / normX
                                local unscaledY = rel.Position.Y / normY
                                local unscaledZ = rel.Position.Z / normZ

                                local xMult = 1.0
                                if entry.name:find("Arm") or entry.name:find("Hand") then
                                    xMult = titanConfig.armWidth
                                elseif entry.name:find("Leg") or entry.name:find("Foot") then
                                    xMult = titanConfig.legWidth
                                end
                                local scaledPos = Vector3.new(
                                    unscaledX * titanConfig.size * xMult,
                                    unscaledY * titanConfig.size,
                                    unscaledZ * titanConfig.size
                                )
                                if entry.name:find("LowerArm") then
                                    scaledPos = scaledPos + Vector3.new(0, -titanConfig.armSpacing, 0)
                                elseif entry.name:find("Hand") then
                                    scaledPos = scaledPos + Vector3.new(0, -titanConfig.armSpacing * 2, 0)
                                end
                                if entry.name:find("Leg") or entry.name:find("Foot") then
                                    scaledPos = scaledPos + Vector3.new(0, titanConfig.legOffsetY, 0)
                                    if entry.name:find("LowerLeg") then
                                        scaledPos = scaledPos + Vector3.new(0, titanConfig.legSpacing, 0)
                                    elseif entry.name:find("UpperLeg") then
                                        scaledPos = scaledPos + Vector3.new(0, titanConfig.legSpacing * 2, 0)
                                    end
                                end
                                local relRot = rel - rel.Position
                                local extraOffset = entry.offset or CFrame.new()
                                if entry.name == "UpperTorso" then
                                    extraOffset = CFrame.new(titanConfig.torsoOffsetX, titanConfig.torsoOffsetY, titanConfig.torsoOffsetZ)
                                        * CFrame.Angles(math.rad(titanConfig.torsoRotX), math.rad(titanConfig.torsoRotY), math.rad(titanConfig.torsoRotZ))
                                elseif entry.name == "LowerTorso" then
                                    extraOffset = (entry.offset or CFrame.new())
                                        * CFrame.new(titanConfig.pelvisOffsetX, titanConfig.pelvisOffsetY, titanConfig.pelvisOffsetZ)
                                        * CFrame.Angles(math.rad(titanConfig.pelvisRotX), math.rad(titanConfig.pelvisRotY), math.rad(titanConfig.pelvisRotZ))
                                end
                                local targetCF = centerCF * CFrame.new(scaledPos) * relRot * extraOffset
                                local isCockpit = (entry.prop == cockpitBed) or (entry.name == "Head")
                                sendCF(entry.scf, targetCF, entry.prop, isCockpit)
                            end
                        end
                    end
                end)

                notify("Gigantic Titan", "Robot 6 assembled in Pure White! 15/15 Props firmly grounded.", 4)
            end

            local function deployPilotSeatTrap(targetPlr)
                if not targetPlr then
                    notify("Titan Trap", "Please select a Target Pilot in dropdown first!", 3)
                    if titanToggleRef and titanToggleRef.Set then pcall(function() titanToggleRef:Set(false) end) end
                    return
                end

                if titanActive or isWaitingForPilot then
                    stopTitan()
                    task.wait(0.4)
                end

                local char = lp.Character or lp.CharacterAdded:Wait()
                local hrp = char:WaitForChild("HumanoidRootPart")

                local clearTools = rep:WaitForChild("RE"):WaitForChild("1Clea1rTool1s")
                pcall(function() clearTools:FireServer("ClearAllProps") end)
                task.wait(0.4)

                pcall(function() clearTools:FireServer("OpenPropMenu") end)
                task.wait(0.2)

                local targetChar = targetPlr and targetPlr.Character
                local targetHrp = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
                local spawnPos = targetHrp and (targetHrp.Position + (targetHrp.CFrame.LookVector * 4.5)) or (hrp.Position + (hrp.CFrame.LookVector * 8))

                notify("Titan Trap", "Deploying Cockpit Bed in front of " .. targetPlr.DisplayName .. "...", 3)
                
                local existingProps = {}
                local wc = workspace:FindFirstChild("WorkspaceCom")
                if wc then
                    for _, folder in pairs(wc:GetChildren()) do
                        for _, prop in pairs(folder:GetChildren()) do
                            if prop.Name == myPropName or prop.Name:find(lp.Name) then
                                existingProps[prop] = true
                            end
                        end
                    end
                end

                local firstBed = spawnSingleProp("FuturisticLargeBed", "Furniture", spawnPos, existingProps)
                if not firstBed then firstBed = spawnSingleProp("FuturisticLargeBed", "Furniture", spawnPos, existingProps) end
                if not firstBed then
                    notify("Titan Trap", "Failed to deploy cockpit prop!", 3)
                    if titanToggleRef and titanToggleRef.Set then pcall(function() titanToggleRef:Set(false) end) end
                    return
                end

                
                task.delay(1.0, function()
                    pcall(function()
                        local toolRemote = rep:FindFirstChild("RE") and rep.RE:FindFirstChild("1Too1l")
                        if toolRemote then toolRemote:InvokeServer("PickingTools", "PropMaker") end
                        local pmTool = (lp.Character and lp.Character:FindFirstChild("PropMaker")) or (lp.Backpack and lp.Backpack:FindFirstChild("PropMaker"))
                        if pmTool then pmTool:Destroy() end
                        local hum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
                        if hum then hum:UnequipTools() end
                    end)
                end)

                pcall(function()
                    local cpc = firstBed:FindFirstChild("ChangePropColor") or firstBed:FindFirstChild("ChangePropColor", true)
                    if cpc then cpc:InvokeServer(Color3.fromRGB(255, 255, 255)) end
                    for _, p in ipairs(firstBed:GetDescendants()) do
                        if p:IsA("BasePart") then p.Color = Color3.fromRGB(255, 255, 255) end
                    end
                end)

                pilotBaitProp = firstBed
                isWaitingForPilot = true
                notify("Titan Trap", "Bed deployed! Waiting for " .. targetPlr.DisplayName .. " to sit...", 5)

                task.spawn(function()
                    local timeout = tick() + 120
                    while isWaitingForPilot and tick() < timeout do
                        if not pilotBaitProp or not pilotBaitProp.Parent then break end
                        if targetPlr and (not targetPlr.Parent or not targetPlr:IsDescendantOf(plrs)) then
                            notify("Titan Trap", "Target player left the game. Cancelling...", 3)
                            stopTitan()
                            return
                        end

                        local foundPilot = nil
                        for _, desc in ipairs(pilotBaitProp:GetDescendants()) do
                            if desc:IsA("Seat") or desc:IsA("VehicleSeat") then
                                local occ = desc.Occupant
                                if occ and occ:IsA("Humanoid") and occ.Parent then
                                    local p = plrs:GetPlayerFromCharacter(occ.Parent)
                                    if p then
                                        if p == targetPlr then
                                            foundPilot = p
                                            break
                                        else
                                            
                                            occ.Sit = false
                                            notify("Titan Trap", (p.DisplayName or "Player") .. " ejected! Only " .. targetPlr.DisplayName .. " can pilot!", 2)
                                        end
                                    end
                                end
                            end
                        end

                        if foundPilot then
                            isWaitingForPilot = false
                            currentPilot = foundPilot
                            notify("Gigantic Titan", foundPilot.DisplayName .. " seated in cockpit! Forging Robot 6...", 4)
                            task.spawn(function()
                                assembleTitanAroundPilot(pilotBaitProp, foundPilot)
                            end)
                            return
                        end
                        task.wait(0.1)
                    end

                    if isWaitingForPilot then
                        notify("Titan Trap", "Boarding timeout or cancelled.", 3)
                        isWaitingForPilot = false
                        if titanToggleRef and titanToggleRef.Set then pcall(function() titanToggleRef:Set(false) end) end
                    end
                end)
            end

            
            local function handleChatCommand(senderPlayer, message)
                if not titanActive then return end
                if not senderPlayer or not message then return end

                local senderUserId = senderPlayer.UserId
                local pilotUserId = currentPilot and currentPilot.UserId
                local localUserId = lp and lp.UserId

                local isAllowed = (senderUserId == localUserId) or (pilotUserId and senderUserId == pilotUserId)
                if not isAllowed then return end

                local cleanMsg = message:lower():gsub("^%s+", ""):gsub("%s+$", "")
                local emoteNumStr = cleanMsg:match("[:/]?[e%s]*emote%s*(%d+)")
                    or cleanMsg:match("^:?(%d+)$")

                if emoteNumStr then
                    local num = tonumber(emoteNumStr)
                    if num and num >= 1 and num <= 5 then
                        playTitanEmote(num)
                        return
                    elseif num == 0 then
                        stopTitanEmote()
                        return
                    end
                end

                if cleanMsg:find("stop") and (cleanMsg:find("emote") or cleanMsg:find("^[:/!]?stop") or cleanMsg == "stop") then
                    stopTitanEmote()
                end
            end

            pcall(function()
                local TextChatService = game:GetService("TextChatService")
                TextChatService.MessageReceived:Connect(function(textChatMessage)
                    local sender = nil
                    if textChatMessage.TextSource then
                        sender = plrs:GetPlayerByUserId(textChatMessage.TextSource.UserId)
                    end
                    if sender then handleChatCommand(sender, textChatMessage.Text) end
                end)
            end)

            local function hookPlayerChat(p)
                p.Chatted:Connect(function(msg) handleChatCommand(p, msg) end)
            end
            for _, p in ipairs(plrs:GetPlayers()) do hookPlayerChat(p) end
            plrs.PlayerAdded:Connect(hookPlayerChat)

            plrs.PlayerRemoving:Connect(function(leavingPlr)
                local isTargetPilot = (currentPilot and leavingPlr.UserId == currentPilot.UserId)
                if isTargetPilot then
                    notify("Titan Controller", (leavingPlr.DisplayName or "Pilot") .. " left the game. Dismantling Titan...", 3)
                    stopTitan()
                end
            end)

            
            
            
            targetPilotDropdownRef = AdminTab:AddDropdown({
                Name = "Target Pilot",
                Description = "Select player who will pilot the Titan (or '---')",
                Options = getPilotPlayersList(),
                Default = "---",
                Callback = function(val)
                    selectedPilotName = val
                    if val ~= "---" then
                        currentPilot = plrs:FindFirstChild(val)
                        if currentPilot then
                            notify("Titan Controller", "Selected target pilot: " .. currentPilot.DisplayName, 3)
                        end
                    else
                        currentPilot = nil
                    end
                end
            })

            AdminTab:AddButton({
                Name = "Refresh Pilot List",
                Description = "Refreshes player names in target pilot dropdown",
                Callback = function()
                    local updated = getPilotPlayersList()
                    if targetPilotDropdownRef and targetPilotDropdownRef.Set then
                        pcall(function() targetPilotDropdownRef:Set(updated) end)
                    end
                    notify("Titan Controller", "Pilot list refreshed!", 2)
                end
            })

            
            titanToggleRef = AdminTab:AddToggle({
                Name = "Deploy Cockpit (Build on Sit)",
                Description = "Spawns cockpit bed. When target sits, Titan builds & activates automatically!",
                Default = false,
                Callback = function(val)
                    if val then
                        local target = currentPilot
                        if not target and selectedPilotName ~= "---" then
                            target = plrs:FindFirstChild(selectedPilotName)
                        end
                        if not target then
                            notify("Titan Controller", "Please select a Target Pilot in dropdown first!", 3)
                            if titanToggleRef and titanToggleRef.Set then
                                pcall(function() titanToggleRef:Set(false) end)
                            end
                            return
                        end
                        task.spawn(function()
                            deployPilotSeatTrap(target)
                        end)
                    else
                        if titanActive or isWaitingForPilot then
                            stopTitan()
                        end
                    end
                end
            })

            
            forceEmoteDropdownRef = AdminTab:AddDropdown({
                Name = "Force Titan Emote",
                Description = "Select emote to immediately force on Titan (or Stop)",
                Options = {
                    "Stop Emote",
                    "1: Cute Sit",
                    "2: Dia Delicia Dance",
                    "3: Dance 3",
                    "4: Best Dance",
                    "5: Low Cortisol Dance"
                },
                Default = "Stop Emote",
                Callback = function(val)
                    if val == "Stop Emote" then
                        stopTitanEmote()
                    else
                        local num = tonumber(val:match("^(%d+)"))
                        if num then
                            playTitanEmote(num)
                        end
                    end
                end
            })

            AdminTab:AddButton({
                Name = "Stop Titan / Clean Props",
                Description = "Emergency stop and clean all props",
                Callback = function()
                    stopTitan()
                end
            })
        end)()

    end

    
    TrollTab:AddSection({"> Catch Method & Spam Options"})

    _G.BringMethod = _G.BringMethod or "Smart"
    TrollTab:AddDropdown({
        Name = "Catch Method",
        Description = "Smart (Lead), Basic (Direct), Vortex Quasar, Hyper-Magnet",
        Options = {"Smart", "Basic", "Vortex Quasar", "Hyper-Magnet"},
        Default = _G.BringMethod or "Smart",
        Callback = function(value)
            _G.BringMethod = value
            if _G.saveBTRConfig then _G.saveBTRConfig() end
        end
    })

    TrollTab:AddSlider({
        Name = "Prop Count (Spam)",
        Description = "More props = faster catch!",
        Min = 1,
        Max = 15,
        Default = 1,
        Suffix = " props",
        Callback = function(Value)
            bringToiletCount = Value
            _G.BringToiletCount = Value
        end
    })

MorphFETab:AddSection({
    "> Goku (FE)"
})

do
    
    local function _notif(t, m)
        pcall(function()
            game:GetService("StarterGui"):SetCore("SendNotification", {Title = t, Text = m, Duration = 3})
        end)
    end

    
    local function _wearOutfit(outfitIds, name)
        task.spawn(function()
            local RS = game:GetService("ReplicatedStorage")
            local Remotes = RS:FindFirstChild("Remotes")
            local wearRemote = Remotes and Remotes:FindFirstChild("Wear")
            if not wearRemote then
                _notif(name, "Wear remote not found!")
                return
            end
            _notif(name, "Applying outfit... (~" .. math.ceil(#outfitIds * 2.1) .. "s)")
            for i, id in ipairs(outfitIds) do
                pcall(function() wearRemote:InvokeServer(id) end)
                if i < #outfitIds then task.wait(2.1) end 
            end
            _notif(name, "Outfit applied!")
        end)
    end

    
    local function _overrideAnims(ids)
        task.spawn(function()
            local p = game:GetService("Players").LocalPlayer
            local char = p.Character or p.CharacterAdded:Wait()
            local hum = char:WaitForChild("Humanoid")
            local animate = char:WaitForChild("Animate")
            task.wait(0.5)
            pcall(function()
                local i1 = animate.idle:FindFirstChild("Animation1")
                local i2 = animate.idle:FindFirstChild("Animation2")
                local rn = animate.run:FindFirstChild("RunAnim")
                if i1 then i1.AnimationId = "rbxassetid://" .. tostring(ids.idle) end
                if i2 then i2.AnimationId = "rbxassetid://" .. tostring(ids.idle) end
                if rn  then rn.AnimationId  = "rbxassetid://" .. tostring(ids.run)  end
            end)
            animate.Enabled = false
            task.wait(0.05)
            animate.Enabled = true
        end)
    end

                                                                         
    local function _loadEmoteAsPureAnimation(hum, emoteId)
        local anim = Instance.new("Animation")
        pcall(function()
            local objects = game:GetObjects("rbxassetid://" .. tostring(emoteId))
            if objects and objects[1] and objects[1]:IsA("Animation") then
                anim.AnimationId = objects[1].AnimationId
            end
        end)
        if anim.AnimationId == "" then
            anim.AnimationId = "rbxassetid://" .. tostring(emoteId)
        end
        local track = hum:LoadAnimation(anim)
        track.Priority = Enum.AnimationPriority.Action4
        return track
    end

    do
        local _gokuActive   = false
        local _gokuConns    = {}
        local _ssjConns     = {}

        
        local GOKU_OUTFIT = { 15093053680, 16838399997, 13918623613, 136320123090473 }
        local GOKU_HEAD_ID = 136320123090473  
        local SSJ_HEAD_ID  = 18332240211

        
        local A_IDLE         = 72492959889389
        local A_RUN          = 18537384940
        local A_TP_EMOTE     = "133631846764964"
        local A_SSJ_TRANSFORM= 115344615095212   
        local A_KI_CHARGE    = 70769545504969    
        local A_FLY_SPRINT   = 128582748149019   
        local A_SSJ_SFX      = 18704549552       

        
        local function _lp()  return game:GetService("Players").LocalPlayer end
        local function _char() local p=_lp() return p and p.Character end
        local function _hrp()  local c=_char() return c and c:FindFirstChild("HumanoidRootPart") end
        local function _hum()  local c=_char() return c and c:FindFirstChildOfClass("Humanoid") end
        local function _notif(t, m) pcall(function()
            game:GetService("StarterGui"):SetCore("SendNotification",{Title=t,Text=m,Duration=3})
        end) end

        
        local _flying      = false
        local _sprinting   = false
        local _flightSpeed = 55
        local _sprintSpeed = 130
        local _moveState   = {fwd=0,bck=0,lft=0,rgt=0,up=0,dn=0}
        local _vel         = Vector3.new(0,0,0)
        local _currentCF   = nil
        local _flightConns = {}
        local _animTrack   = nil
        local _origGrav    = workspace.Gravity
        local _sprintGui   = nil

        
        local _ssj         = false
        local _ssjExpSfx   = nil

        
        local _kiCharging  = false
        local _kiTrack     = nil

        
        local _origWalk    = 16
        local _origJump    = 7.2

        
        local _tpGui = nil
        local _tping = false

        
        local _origAnims   = {}
        local _animsLoaded = false

        
        local function _stopAllAnims()
            local hum = _hum()
            if not hum then return end
            for _, t in ipairs(hum:GetPlayingAnimationTracks()) do
                pcall(function() t:Stop(0) end)
            end
        end

        local function _playAnim(id, startT, speed, loop)
            local hum = _hum()
            if not hum then return end
            if _animTrack then pcall(function() _animTrack:Stop(0.1) end) _animTrack = nil end
            local a = Instance.new("Animation")
            a.AnimationId = "rbxassetid://" .. tostring(id)
            _animTrack = hum:LoadAnimation(a)
            _animTrack.Looped = loop or false
            _animTrack:Play()
            _animTrack.TimePosition = startT or 0
            _animTrack:AdjustSpeed(speed or 1)
        end

        local function _loadCustomAnims()
            local char = _char(); local hum = _hum()
            if not char or not hum then return end
            local animate = char:FindFirstChild("Animate")
            if not animate then return end
            _stopAllAnims()
            pcall(function()
                local i1 = animate.idle:FindFirstChild("Animation1")
                local i2 = animate.idle:FindFirstChild("Animation2")
                local rn = animate.run:FindFirstChild("RunAnim")
                if i1 then _origAnims.Idle1=i1.AnimationId; i1.AnimationId="rbxassetid://"..A_IDLE end
                if i2 then _origAnims.Idle2=i2.AnimationId; i2.AnimationId="rbxassetid://"..A_IDLE end
                if rn  then _origAnims.Run =rn.AnimationId;  rn.AnimationId ="rbxassetid://"..A_RUN  end
            end)
            animate.Enabled=false; task.wait(0.05); animate.Enabled=true
            _animsLoaded = true
        end

        local function _restoreAnims()
            if not _animsLoaded then return end
            local char = _char()
            if not char then return end
            local animate = char:FindFirstChild("Animate")
            if not animate then return end
            pcall(function()
                if _origAnims.Idle1 then animate.idle.Animation1.AnimationId=_origAnims.Idle1 end
                if _origAnims.Idle2 then animate.idle.Animation2.AnimationId=_origAnims.Idle2 end
                if _origAnims.Run   then animate.run.RunAnim.AnimationId     =_origAnims.Run   end
            end)
            animate.Enabled=false; task.wait(0.05); animate.Enabled=true
            _animsLoaded = false
        end

        
        local function _stopFlight()
            if not _flying then return end
            _flying = false
            _sprinting = false
            for _, c in ipairs(_flightConns) do pcall(function() if c.Connected then c:Disconnect() end end) end
            _flightConns = {}
            _moveState = {fwd=0,bck=0,lft=0,rgt=0,up=0,dn=0}
            workspace.Gravity = _origGrav
            local hum = _hum(); local hrp = _hrp()
            if hum then hum.PlatformStand = false end
            if _animTrack then pcall(function() _animTrack:Stop(0.1) end) _animTrack = nil end
            if hrp then
                if hrp:FindFirstChild("GokuGyro") then hrp.GokuGyro:Destroy() end
                if hrp:FindFirstChild("GokuVel")  then hrp.GokuVel:Destroy()  end
            end
            
            if _sprintGui then pcall(function() _sprintGui:Destroy() end) _sprintGui=nil end
            local animate = _char() and _char():FindFirstChild("Animate")
            if animate then animate.Disabled = false end
        end

        local function _setSprint(on)
            if not _flying then return end
            if on == _sprinting then return end
            _sprinting = on
            if on then
                _playAnim(A_FLY_SPRINT, 15, 1, true)
            else
                
                local fwd = _moveState.fwd - _moveState.bck
                if fwd > 0 then _playAnim(106345021112927,15,1,true)
                elseif fwd < 0 then _playAnim(132783162476851,4,1,true)
                else _playAnim(113420763488155,4,1,true) end
            end
        end

        local function _startFlight()
            if not _gokuActive or _flying then return end
            local hrp=_hrp(); local hum=_hum()
            if not hrp or not hum then return end
            _flying = true
            _sprinting = false
            _origGrav = workspace.Gravity
            workspace.Gravity = 192.2
            hum.PlatformStand = true
            _playAnim(113420763488155, 4, 1, true)

            local gyro = Instance.new("BodyGyro")
            gyro.Name="GokuGyro"; gyro.Parent=hrp
            gyro.P=90000; gyro.MaxTorque=Vector3.new(9e9,9e9,9e9); gyro.CFrame=hrp.CFrame
            local bv = Instance.new("BodyVelocity")
            bv.Name="GokuVel"; bv.Parent=hrp
            bv.MaxForce=Vector3.new(9e9,9e9,9e9); bv.Velocity=Vector3.new(0,0,0)
            _vel = Vector3.new(0,0,0)

            local RS  = game:GetService("RunService")
            local UIS = game:GetService("UserInputService")

            
            local lp2 = _lp()
            local isMobile = UIS.TouchEnabled and not UIS.KeyboardEnabled
            if isMobile then
                _sprintGui = Instance.new("ScreenGui")
                _sprintGui.Name="GokuSprintGui"; _sprintGui.ResetOnSpawn=false
                _sprintGui.ZIndexBehavior=Enum.ZIndexBehavior.Sibling
                _sprintGui.Parent=lp2.PlayerGui
                local sprintBtn = Instance.new("TextButton")
                sprintBtn.Size=UDim2.new(0,90,0,90); sprintBtn.Position=UDim2.new(0.88,0,0.72,0)
                sprintBtn.BackgroundColor3=Color3.fromRGB(255,200,0)
                sprintBtn.BackgroundTransparency=0.35
                sprintBtn.Text="SPRINT"; sprintBtn.TextColor3=Color3.fromRGB(255,255,255)
                sprintBtn.Font=Enum.Font.GothamBold; sprintBtn.TextSize=14
                sprintBtn.BorderSizePixel=0; sprintBtn.ZIndex=5
                sprintBtn.Parent=_sprintGui
                Instance.new("UICorner",sprintBtn).CornerRadius=UDim.new(1,0)
                local sprintStroke=Instance.new("UIStroke",sprintBtn)
                sprintStroke.Color=Color3.fromRGB(255,255,255); sprintStroke.Thickness=2
                sprintBtn.MouseButton1Down:Connect(function() _setSprint(true) end)
                sprintBtn.MouseButton1Up:Connect(function() _setSprint(false) end)
            end

            local upd = RS.RenderStepped:Connect(function()
                if not _gokuActive or not _flying then return end
                local h = _hrp(); if not h then return end
                local cam = workspace.CurrentCamera
                local fwd  = _moveState.fwd - _moveState.bck
                local side = _moveState.rgt - _moveState.lft
                local dir  = Vector3.new(0,0,0)
                if fwd  ~= 0 then dir = dir + cam.CFrame.LookVector  * fwd  end
                if side ~= 0 then dir = dir + cam.CFrame.RightVector * side end
                if dir.Magnitude > 0 then dir = dir.Unit end
                local vert = 0
                if _moveState.up > 0 then vert = 1 elseif _moveState.dn > 0 then vert = -1 end
                local spd = _sprinting and _sprintSpeed or _flightSpeed
                local desired = Vector3.new(0,0,0)
                if dir.Magnitude > 0 then desired = desired + dir * spd end
                if vert ~= 0 then desired = desired + Vector3.new(0, vert * spd * 0.6, 0) end
                if desired.Magnitude > 0.1 then
                    _vel = _vel:Lerp(desired, _sprinting and 0.2 or 0.15)
                    local dCF = cam.CFrame
                    if fwd > 0 then dCF = cam.CFrame * CFrame.Angles(0,0,0)
                    elseif fwd < 0 then dCF = cam.CFrame * CFrame.Angles(math.rad(30),0,0) end
                    if _currentCF then _currentCF=_currentCF:Lerp(dCF,0.25) else _currentCF=dCF end
                    gyro.CFrame = _currentCF
                else
                    _vel = _vel:Lerp(Vector3.new(0,0,0), 0.3)
                end
                bv.Velocity = _vel
            end)
            table.insert(_flightConns, upd); table.insert(_gokuConns, upd)

            local ib = UIS.InputBegan:Connect(function(input, gp)
                if gp or not _flying then return end
                local k = input.KeyCode
                if     k==Enum.KeyCode.W           then _moveState.fwd=1
                    if not _sprinting then _playAnim(106345021112927,15,1,true) end
                elseif k==Enum.KeyCode.S           then _moveState.bck=1; _playAnim(132783162476851,4,1,true)
                elseif k==Enum.KeyCode.A           then _moveState.lft=1
                elseif k==Enum.KeyCode.D           then _moveState.rgt=1
                elseif k==Enum.KeyCode.Space       then _moveState.up=1
                elseif k==Enum.KeyCode.LeftControl then _moveState.dn=1
                elseif k==Enum.KeyCode.LeftShift   then _setSprint(true)
                end
            end)
            local ie = UIS.InputEnded:Connect(function(input, gp)
                if not _flying then return end
                local k = input.KeyCode
                if     k==Enum.KeyCode.W           then _moveState.fwd=0
                    if not _sprinting then _playAnim(113420763488155,4,1,true) end
                elseif k==Enum.KeyCode.S           then _moveState.bck=0
                    if not _sprinting then _playAnim(113420763488155,4,1,true) end
                elseif k==Enum.KeyCode.A           then _moveState.lft=0
                elseif k==Enum.KeyCode.D           then _moveState.rgt=0
                elseif k==Enum.KeyCode.Space       then _moveState.up=0
                elseif k==Enum.KeyCode.LeftControl then _moveState.dn=0
                elseif k==Enum.KeyCode.LeftShift   then _setSprint(false)
                end
            end)
            table.insert(_flightConns, ib); table.insert(_gokuConns, ib)
            table.insert(_flightConns, ie); table.insert(_gokuConns, ie)
        end

        
        local function _activateSSJ()
            if not _gokuActive or _ssj then
                _notif("Goku (FE)", "Already Super Saiyan!") return
            end
            local char=_char(); local hrp=_hrp(); local hum=_hum()
            if not char or not hrp or not hum then return end

            _ssj = true
            _origWalk = hum.WalkSpeed; _origJump = hum.JumpHeight
            hum.WalkSpeed=0; hum.JumpHeight=0
            _stopAllAnims()

            
            local SSJ_ENERGY_EMOTE = 73708713364616
            local ssjEmoteTrack    = nil
            local ssjEDesc = hum:FindFirstChildOfClass("HumanoidDescription")
            if ssjEDesc then
                pcall(function()
                    local el = ssjEDesc:GetEmotes()
                    if not el["GokuSSJEmote"] then
                        ssjEDesc:AddEmote("GokuSSJEmote", SSJ_ENERGY_EMOTE)
                    end
                end)
                pcall(function()
                    local ok, tr = pcall(function()
                        return hum:PlayEmoteAndGetAnimTrackById(SSJ_ENERGY_EMOTE)
                    end)
                    if ok and tr then
                        ssjEmoteTrack = tr
                        ssjEmoteTrack.Priority = Enum.AnimationPriority.Action4
                    end
                end)
            end

            
            local TW  = game:GetService("TweenService")
            local cam = workspace.CurrentCamera
            local origCT = cam.CameraType
            cam.CameraType = Enum.CameraType.Scriptable
            TW:Create(cam, TweenInfo.new(1.2,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),
                {CFrame = CFrame.lookAt(
                    hrp.Position + hrp.CFrame.LookVector*16 + Vector3.new(0,4,0),
                    hrp.Position)}):Play()

            
            local ao = Instance.new("Animation")
            ao.AnimationId = "rbxassetid://"..tostring(A_SSJ_TRANSFORM)
            local transTrack = hum:LoadAnimation(ao)
            transTrack.Looped = false; transTrack:Play()
            task.wait(0.6)

            
            local lp2 = game:GetService("Players").LocalPlayer

            
            local flashGui = Instance.new("ScreenGui")
            flashGui.Name="SSJFlash"; flashGui.IgnoreGuiInset=true
            flashGui.ZIndexBehavior=Enum.ZIndexBehavior.Sibling
            flashGui.ResetOnSpawn=false; flashGui.Parent=lp2.PlayerGui
            local flashF = Instance.new("Frame")
            flashF.Size=UDim2.new(1,0,1,0)
            flashF.BackgroundColor3=Color3.fromRGB(255,220,0)
            flashF.BackgroundTransparency=1; flashF.BorderSizePixel=0
            flashF.ZIndex=100; flashF.Parent=flashGui

            
            local blast = Instance.new("Part")
            blast.Name="SSJBlast"; blast.Shape=Enum.PartType.Ball
            blast.Material=Enum.Material.Neon
            blast.BrickColor=BrickColor.new("Bright yellow")
            blast.CanCollide=false; blast.Anchored=true
            blast.Size=Vector3.new(1,1,1); blast.Transparency=0.05
            blast.Position=hrp.Position+Vector3.new(0,1,0); blast.Parent=workspace
            local blastLight=Instance.new("PointLight")
            blastLight.Brightness=60; blastLight.Range=90
            blastLight.Color=Color3.fromRGB(255,220,0); blastLight.Parent=blast

            
            local ring = Instance.new("Part")
            ring.Name="SSJRing"; ring.Material=Enum.Material.Neon
            ring.BrickColor=BrickColor.new("Bright yellow")
            ring.CanCollide=false; ring.Anchored=true
            ring.Size=Vector3.new(0.4,1,1); ring.Transparency=0.05
            ring.CFrame=CFrame.new(hrp.Position+Vector3.new(0,0.5,0))*CFrame.Angles(0,0,math.pi/2)
            ring.Parent=workspace

            
            for i=1,6 do
                local pe=Instance.new("ParticleEmitter")
                pe.Texture="rbxassetid://242563111"
                pe.Lifetime=NumberRange.new(0.3,1.2)
                pe.Rate=200; pe.Speed=NumberRange.new(40,90)
                pe.Size=NumberSequence.new({
                    NumberSequenceKeypoint.new(0,3),
                    NumberSequenceKeypoint.new(0.4,4),
                    NumberSequenceKeypoint.new(1,0)
                })
                pe.Color=ColorSequence.new({
                    ColorSequenceKeypoint.new(0,Color3.fromRGB(255,235,0)),
                    ColorSequenceKeypoint.new(1,Color3.fromRGB(255,255,200))
                })
                pe.Parent=blast
            end

            
            _ssjExpSfx=Instance.new("Sound")
            _ssjExpSfx.SoundId="rbxassetid://"..tostring(A_SSJ_SFX)
            _ssjExpSfx.Volume=1.4; _ssjExpSfx.Parent=hrp; _ssjExpSfx:Play()

            
            TW:Create(blast,TweenInfo.new(0.45,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),
                {Size=Vector3.new(14,14,14),Transparency=0.72}):Play()
            TW:Create(ring,TweenInfo.new(0.5,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),
                {Size=Vector3.new(0.15,18,18),Transparency=0.88}):Play()
            TW:Create(flashF,TweenInfo.new(0.12),{BackgroundTransparency=0.2}):Play()

            task.wait(0.12)
            
            TW:Create(flashF,TweenInfo.new(0.55,Enum.EasingStyle.Quad),{BackgroundTransparency=1}):Play()
            TW:Create(blastLight,TweenInfo.new(0.8),{Brightness=5,Range=20}):Play()

            task.wait(1.08)  
            pcall(function() blast:Destroy() end)
            pcall(function() ring:Destroy() end)
            pcall(function() flashGui:Destroy() end)
            pcall(function() _ssjExpSfx:Stop(); _ssjExpSfx:Destroy() end); _ssjExpSfx=nil

            
            if ssjEmoteTrack then
                pcall(function() ssjEmoteTrack:Stop(0) end)
                ssjEmoteTrack = nil
            end
            local hum3 = _hum()
            if hum3 then
                pcall(function() hum3:Move(Vector3.new(1,0,0), false) end)
                task.wait(0.05)
                pcall(function() hum3:Move(Vector3.new(0,0,0), false) end)
            end

            cam.CameraType = origCT

            
            do
                local RS2b  = game:GetService("ReplicatedStorage")
                local Rem2  = RS2b:FindFirstChild("Remotes") or RS2b:FindFirstChild("RE")
                local wR    = Rem2 and Rem2:FindFirstChild("Wear")
                if wR then
                    pcall(function() wR:InvokeServer(GOKU_HEAD_ID) end)
                    task.wait(0.15)
                    pcall(function() wR:InvokeServer(SSJ_HEAD_ID)  end)
                end
            end

            
            local hl = Instance.new("Highlight"); hl.Name="SSJHighlight"; hl.Adornee=char
            hl.FillColor=Color3.fromRGB(255,220,0); hl.OutlineColor=Color3.fromRGB(255,255,150)
            hl.FillTransparency=0.88; hl.OutlineTransparency=0.2; hl.Parent=char

            
            local kl=Instance.new("PointLight"); kl.Name="SSJLight"
            kl.Color=Color3.fromRGB(255,220,0); kl.Brightness=1.5; kl.Range=12; kl.Parent=hrp

            
            local sparks = Instance.new("ParticleEmitter"); sparks.Name="SSJSparks"
            sparks.Texture="rbxassetid://242563111"
            sparks.Lifetime=NumberRange.new(0.1,0.4)
            sparks.Rate=25; sparks.Speed=NumberRange.new(2,8)
            sparks.Size=NumberSequence.new({NumberSequenceKeypoint.new(0,0.4),NumberSequenceKeypoint.new(1,0)})
            sparks.Color=ColorSequence.new(Color3.fromRGB(255,240,100))
            sparks.Parent=hrp

            
            hum.WalkSpeed = 120
            hum.JumpHeight = 45

            local an=char:FindFirstChild("Animate")
            if an then an.Disabled=true; task.wait(0.1); an.Disabled=false end

            _notif("Goku (FE)", "Super Saiyan! Irreversible - Remove Goku to reset.")
        end

        
        local function _startKiCharge()
            if not _gokuActive or _kiCharging then return end
            local hum  = _hum(); if not hum then return end
            local desc = hum:FindFirstChildOfClass("HumanoidDescription")
            if not desc then return end
            _kiCharging = true

            local emoteId   = A_KI_CHARGE
            local emoteName = "GokuKi"

            
            pcall(function()
                local list = desc:GetEmotes()
                if not list[emoteName] then desc:AddEmote(emoteName, emoteId) end
            end)

            
            task.spawn(function()
                while _kiCharging do
                    local hum2 = _hum()
                    if hum2 then
                        pcall(function()
                            local ok, track = pcall(function()
                                return hum2:PlayEmoteAndGetAnimTrackById(emoteId)
                            end)
                            if ok and track then
                                _kiTrack = track
                                _kiTrack.Priority = Enum.AnimationPriority.Action4
                                
                                track.Stopped:Wait()
                            end
                        end)
                    end
