                cl.Color=Color3.fromRGB(100,180,255); cl.Brightness=3; cl.Range=14; cl.Parent=hrp2
            end
        end

        local function _stopKiCharge()
            if not _kiCharging then return end
            _kiCharging = false  
            
            if _kiTrack then
                pcall(function() _kiTrack:Stop(0) end)
                _kiTrack = nil
            end
            local hum2  = _hum()
            local char2 = _char()
            
            if hum2 then
                local desc2 = hum2:FindFirstChildOfClass("HumanoidDescription")
                if desc2 then pcall(function() desc2:RemoveEmote("GokuKi") end) end
            end
            
            if char2 then
                local an = char2:FindFirstChild("Animate")
                if an then
                    an.Disabled = true
                    task.wait(0.05)
                    an.Disabled = false
                end
            end
            
            if hum2 then
                pcall(function() hum2:Move(Vector3.new(1,0,0), false) end)
                task.wait(0.05)
                pcall(function() hum2:Move(Vector3.new(0,0,0), false) end)
            end
            local hrp2 = _hrp()
            if hrp2 and hrp2:FindFirstChild("KiChargeLight") then hrp2.KiChargeLight:Destroy() end
        end

        
