                        local function tweenUI(obj,props,t,style,dir)
                            style=style or Enum.EasingStyle.Quad; dir=dir or Enum.EasingDirection.Out
                            TW:Create(obj,TweenInfo.new(t,style,dir),props):Play()
                        end

                        cam.CameraType=Enum.CameraType.Scriptable
                        local cPos=hrp.Position; local cLook=hrp.CFrame.LookVector; local cRight=hrp.CFrame.RightVector

                        tweenUI(barTop2,{Position=UDim2.new(0,0,0,0)},        0.35,Enum.EasingStyle.Quint)
                        tweenUI(barBot2,{Position=UDim2.new(0,0,1-BAR_H2,0)}, 0.35,Enum.EasingStyle.Quint)

                        if _ssj then
                            tweenUI(barTop2,{BackgroundColor3=Color3.fromRGB(55,40,0)},0.5)
                            tweenUI(barBot2,{BackgroundColor3=Color3.fromRGB(55,40,0)},0.5)
                            cam.CFrame=CFrame.lookAt(cPos+cLook*4+Vector3.new(0,-2,0),cPos+Vector3.new(0,3,0))
                            task.wait(0.45)
                            local startAngle=math.atan2(-cLook.Z,cLook.X)+math.pi
                            orbitCam(cPos,6.5,startAngle,startAngle+math.pi*2,3.5,2.0,eExpoOut)
                            local ssj_zoomEnd=CFrame.lookAt(cPos+cLook*2.5+cRight*0.3+Vector3.new(0,2.8,0),cPos+Vector3.new(0,2.4,0))
                            moveCam(cam.CFrame,ssj_zoomEnd,0.4,eExpoIn)
                            tweenUI(auraFrame,{BackgroundTransparency=0.4},0.12); task.wait(0.12)
                            tweenUI(auraFrame,{BackgroundTransparency=0.2},0.12); task.wait(0.12)
                            tweenUI(auraFrame,{BackgroundTransparency=0.05},0.12); task.wait(0.12)
                            tweenUI(auraFrame,{BackgroundTransparency=1},0.08)
                            tweenUI(whiteFlash,{BackgroundTransparency=0},0.15); task.wait(0.15)
                            tweenUI(blackCover,{BackgroundTransparency=0},0.08); task.wait(0.08)
                            tweenUI(whiteFlash,{BackgroundTransparency=1},0.1)
                            tweenUI(nameLabel,{TextTransparency=0},0.25)
                        else
                            local n_p1s=CFrame.lookAt(cPos-cLook*9-cRight*4.5+Vector3.new(0,5,0),cPos+Vector3.new(0,2,0))
                            local n_p1e=CFrame.lookAt(cPos-cLook*6-cRight*0.5+Vector3.new(0,4,0),cPos+Vector3.new(0,2,0))
                            cam.CFrame=n_p1s; moveCam(n_p1s,n_p1e,1.2,eSineOut)
                            local n_p2e=CFrame.lookAt(cPos+cRight*4.5-cLook*2.5+Vector3.new(0,2.5,0),cPos+Vector3.new(0,1.5,0))
                            tweenUI(auraFrame,{BackgroundTransparency=0.85},0.3); moveCam(n_p1e,n_p2e,0.7,eSineOut)
                            local n_p3e=CFrame.lookAt(cPos+cLook*2.2+cRight*0.5+Vector3.new(0,2.6,0),cPos+Vector3.new(0,2.2,0))
                            tweenUI(auraFrame,{BackgroundTransparency=0.6},0.3); moveCam(n_p2e,n_p3e,0.45,eExpoIn)
                            task.wait(0.06)
                            local n_p4s=CFrame.lookAt(cPos+Vector3.new(0,-1.5,0)-cLook*3.5,cPos+Vector3.new(0,2.5,0))
                            local n_p4e=CFrame.lookAt(cPos+Vector3.new(0,1.2,0)-cLook*3.5,cPos+Vector3.new(0,2.2,0))
                            moveCam(n_p4s,n_p4e,0.6,eSineOut)
                            tweenUI(auraFrame,{BackgroundTransparency=1},0.15)
                            tweenUI(whiteFlash,{BackgroundTransparency=0.45},0.3); task.wait(0.3)
                            tweenUI(whiteFlash,{BackgroundTransparency=0},0.12); task.wait(0.12)
                            tweenUI(blackCover,{BackgroundTransparency=0},0.08); task.wait(0.08)
                            tweenUI(whiteFlash,{BackgroundTransparency=1},0.1)
                            tweenUI(nameLabel,{TextTransparency=0},0.2)
                        end

                        local savedCF=hrp.CFrame
                        for _,part in ipairs(char:GetDescendants()) do
                            if part:IsA("BasePart") or part:IsA("Decal") then part.Transparency=1 end
                        end
                        hrp.CFrame=CFrame.new(0,10000,0); task.wait(0.55)

                        local tc=p.Character
                        if tc and tc:FindFirstChild("HumanoidRootPart") then
                            hrp.CFrame=tc.HumanoidRootPart.CFrame*CFrame.new(0,0,-5)
                        else hrp.CFrame=savedCF end

                        for _,part in ipairs(char:GetDescendants()) do
                            if part:IsA("BasePart") and part~=hrp then part.Transparency=0
                            elseif part:IsA("Decal") then part.Transparency=0 end
                        end
                        tt:Stop(); tt=nil
                        tweenUI(nameLabel,{TextTransparency=1},0.2)

                        local newPos=hrp.Position; local newLook=hrp.CFrame.LookVector
                        cam.CFrame=CFrame.lookAt(newPos+Vector3.new(0,18,0)-newLook*6,newPos+Vector3.new(0,1,0))
                        tweenUI(blackCover,{BackgroundTransparency=1},0.35,Enum.EasingStyle.Quad)
                        if _ssj then tweenUI(auraFrame,{BackgroundTransparency=0.88},0.2) end
                        local arrMid=CFrame.lookAt(newPos-newLook*10+Vector3.new(0,8,0),newPos+Vector3.new(0,2,0))
                        moveCam(cam.CFrame,arrMid,0.85,eSineOut)
