                        tweenUI(barBot2,{Position=UDim2.new(0,0,1,0)},      0.35,Enum.EasingStyle.Quint,Enum.EasingDirection.In)
                        task.wait(0.35)
                        cam.CameraType=origCT
                        pcall(function() cGui:Destroy() end); cGui=nil
                        _restoreAllGuis()
                    end)
                    if _tping then _safeCleanup() end
                end)
            end)
        end

        
        local function _removeGokuTools()
            local lp=_lp(); local bp=lp and lp:FindFirstChild("Backpack"); local char=_char()
            for _, n in ipairs({"GokuFly","GokuTP","GokuSSJ","GokuKi"}) do
                if bp   and bp:FindFirstChild(n)   then bp[n]:Destroy()   end
                if char and char:FindFirstChild(n) then char[n]:Destroy() end
            end
        end

        local function _createGokuTools()
            local lp=_lp(); local bp=lp:WaitForChild("Backpack",5)
            if not bp then return end

            local fly=Instance.new("Tool"); fly.Name="GokuFly"
            fly.TextureId="rbxassetid://138393727967636"; fly.RequiresHandle=false; fly.Parent=bp
            fly.Equipped:Connect(function() if _flying then _stopFlight() else _startFlight() end end)

            local tp=Instance.new("Tool"); tp.Name="GokuTP"
            tp.TextureId="rbxassetid://77738072756366"; tp.RequiresHandle=false; tp.Parent=bp
            tp.Equipped:Connect(function() _createTpGui() end)
            tp.Unequipped:Connect(function() if _tpGui then _tpGui:Destroy() _tpGui=nil end end)

            
            local ssj=Instance.new("Tool"); ssj.Name="GokuSSJ"
            ssj.TextureId="rbxassetid://81438887708519"; ssj.RequiresHandle=false; ssj.Parent=bp
            ssj.Equipped:Connect(function() task.spawn(_activateSSJ) end)

            
            local ki=Instance.new("Tool"); ki.Name="GokuKi"
            ki.TextureId="rbxassetid://6975831171"; ki.RequiresHandle=false; ki.Parent=bp
            ki.Equipped:Connect(function() _startKiCharge() end)
            ki.Unequipped:Connect(function() _stopKiCharge() end)
        end

        
        local function _cleanupGoku()
            _gokuActive=false
            _stopFlight(); _stopKiCharge(); _restoreAnims(); _removeGokuTools()
            if _tpGui then pcall(function() _tpGui:Destroy() end) _tpGui=nil end
            if _sprintGui then pcall(function() _sprintGui:Destroy() end) _sprintGui=nil end
            
            local char2=_char()
            if char2 then
                if char2:FindFirstChild("SSJHighlight") then char2.SSJHighlight:Destroy() end
            end
            local hrp2=_hrp()
            if hrp2 then
                if hrp2:FindFirstChild("SSJLight")    then hrp2.SSJLight:Destroy()    end
                if hrp2:FindFirstChild("SSJSparks")   then hrp2.SSJSparks:Destroy()   end
                if hrp2:FindFirstChild("KiChargeLight") then hrp2.KiChargeLight:Destroy() end
            end
            for _, c in ipairs(_gokuConns) do pcall(function() if c.Connected then c:Disconnect() end end) end
            _gokuConns={}
            _ssj=false; _kiCharging=false; _sprinting=false
            workspace.Gravity=_origGrav
            local hum=_hum()
            if hum then hum.WalkSpeed=16; hum.JumpHeight=7.2; hum.PlatformStand=false end
            _notif("Goku (FE)", "Goku mode removed.")
        end

        local function _startGoku()
            
            local char=_char(); if not char then _notif("Goku (FE)","Character not found.") return end

            
            
            local RS=game:GetService("ReplicatedStorage")
            local Remotes=RS:WaitForChild("Remotes",5)
            local wearRemote = Remotes and Remotes:FindFirstChild("Wear")
            if wearRemote then
                _notif("Goku (FE)", "Applying outfit... ("..#GOKU_OUTFIT.." items, ~"..math.ceil(#GOKU_OUTFIT*2.1).."s)")
                for i, id in ipairs(GOKU_OUTFIT) do
                    pcall(function() wearRemote:InvokeServer(id) end)
                    if i < #GOKU_OUTFIT then task.wait(2.1) end 
                end
                task.wait(0.5) 
            else
                _notif("Goku (FE)", "Wear remote not found - tools only.")
            end

            _gokuActive=true

            
            _createGokuTools()

            
            _loadCustomAnims()

            _notif("Goku (FE)", "Goku activated! Tools: Fly / TP / Super Saiyan / Ki Charge")
        end

