    MorphFETab:AddButton({
        Name = "Transform Into Faker",
        Description = "Faker outfit + retro glitch animations",
        Callback = function()
            _wearOutfit({89163989490061, 91151766440767, 14604029285}, "Faker (FE)")
            task.spawn(function()
                local p = game:GetService("Players").LocalPlayer
                local char = p.Character or p.CharacterAdded:Wait()
                local hum = char:WaitForChild("Humanoid")

                local function playRetroTrack(track)
                    if not track then return end
                    if track.IsPlaying then track:Stop() end
                    track:Play()
                    track:AdjustSpeed(3)
                    task.spawn(function()
                        while track.IsPlaying do
                            task.wait(0.1 + math.random() * 0.1)
                            if track.IsPlaying then
                                track:AdjustSpeed(0)
                                task.wait(0.15)
                                track:AdjustSpeed(3)
                            end
                        end
                    end)
                end

                local animator = hum:FindFirstChildOfClass("Animator")
                if not animator then
                    animator = Instance.new("Animator")
                    animator.Parent = hum
                end

                hum.WalkSpeed = 34
                hum.UseJumpPower = true
                hum.JumpPower = 75
                hum.JumpHeight = 7.2

                local function load(id)
                    local a = Instance.new("Animation")
                    a.AnimationId = id
                    return animator:LoadAnimation(a)
                end

                local walkTrack = load("rbxassetid://107806791584829")
                walkTrack.Looped = true
                walkTrack.Priority = Enum.AnimationPriority.Movement
                local idleTrack = load("rbxassetid://120873587634730")
                idleTrack.Looped = true
                idleTrack.Priority = Enum.AnimationPriority.Idle
                local jumpTrack = load("rbxassetid://139390570947836")
                jumpTrack.Looped = true
                jumpTrack.Priority = Enum.AnimationPriority.Action

                hum.Running:Connect(function(speedVal)
                    if hum:GetState() ~= Enum.HumanoidStateType.Jumping then
                        if speedVal > 0 then
                            if idleTrack.IsPlaying then idleTrack:Stop() end
                            if not walkTrack.IsPlaying then walkTrack:Play() end
                        else
                            if walkTrack.IsPlaying then walkTrack:Stop() end
                            if not idleTrack.IsPlaying then playRetroTrack(idleTrack) end
                        end
                    end
                end)
                hum.Jumping:Connect(function(isActive)
                    if isActive then
                        if walkTrack.IsPlaying then walkTrack:Stop() end
                        if idleTrack.IsPlaying then idleTrack:Stop() end
                        jumpTrack:Play()
                    end
                end)
                hum.StateChanged:Connect(function(_, new)
                    if new == Enum.HumanoidStateType.Landed then
                        if jumpTrack.IsPlaying then jumpTrack:Stop() end
                        if hum.MoveDirection and hum.MoveDirection.Magnitude > 0 then
                            if not walkTrack.IsPlaying then walkTrack:Play() end
                        else
                            if not idleTrack.IsPlaying then playRetroTrack(idleTrack) end
                        end
                    end
                end)

                if not idleTrack.IsPlaying then playRetroTrack(idleTrack) end
                _notif("Faker (FE)", "Faker activated!")
            end)
        end
    })

    
