                end)
                return s
            end

            local function cameraImpulse(power)
                local cam = Workspace.CurrentCamera
                if not cam then return end
                task.spawn(function()
                    for _ = 1, 3 do
                        local shake = Vector3.new(
                            (math.random() - 0.5) * power,
                            (math.random() - 0.5) * power,
                            (math.random() - 0.5) * power
                        )
                        cam.CFrame = cam.CFrame * CFrame.Angles(shake.X, shake.Y, shake.Z)
                        RunService.RenderStepped:Wait()
                    end
                end)
            end

                                                                           
                                                                     
                                                                           
