                        end
                    end
                end

                                                                                                   
                if currentState == STATE.WALL_CLING or currentState == STATE.WALL_CLIMB then
                    local normal = currentWallNormal or Vector3.new(0, 0, 1)

                    local isUp = UserInputService:IsKeyDown(Enum.KeyCode.W) or UserInputService:IsKeyDown(Enum.KeyCode.Z)
                    local isDown = UserInputService:IsKeyDown(Enum.KeyCode.S)
                    local isLeft = UserInputService:IsKeyDown(Enum.KeyCode.A) or UserInputService:IsKeyDown(Enum.KeyCode.Q)
                    local isRight = UserInputService:IsKeyDown(Enum.KeyCode.D)

                                                              
                    if hum.MoveDirection.Magnitude > 0.15 then
                        local camCF = Workspace.CurrentCamera.CFrame
                        local localMove = camCF:VectorToObjectSpace(hum.MoveDirection)
                        if localMove.Z < -0.3 then isUp = true end
                        if localMove.Z > 0.3 then isDown = true end
                        if localMove.X < -0.3 then isLeft = true end
                        if localMove.X > 0.3 then isRight = true end
                    end

                    local climbSpeed = 22
                    local crawlVelocity = Vector3.new(0, 0, 0)

                    if isUp and not isDown then
                        crawlVelocity = crawlVelocity + Vector3.new(0, climbSpeed, 0)
                    elseif isDown and not isUp then
                        crawlVelocity = crawlVelocity - Vector3.new(0, climbSpeed, 0)
                    end

                    local wallTangent = Vector3.new(0, 1, 0):Cross(normal)
                    if wallTangent.Magnitude > 0.01 then
                        wallTangent = wallTangent.Unit
                    else
                        wallTangent = Vector3.new(1, 0, 0)
                    end

                    if isRight and not isLeft then
                        crawlVelocity = crawlVelocity + (wallTangent * climbSpeed)
                    elseif isLeft and not isRight then
                        crawlVelocity = crawlVelocity - (wallTangent * climbSpeed)
                    end

                    local _0xH_434 = isUp or isDown or isLeft or isRight

                    if _0xH_434 then
