local function getSafeGuiParent()
    local target = nil
    pcall(function()
        if typeof(gethui) == "function" then
            target = gethui()
        end
    end)
    if not target then
        pcall(function()
            target = CoreGui
        end)
    end
    if not target then
        target = lp:WaitForChild("PlayerGui")
    end
    return target
end

