local function playSound(soundId, pitch, volume)
    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return end

    local s = Instance.new("Sound")
    s.SoundId = soundId
    s.Volume = volume or 1.5
    s.PlaybackSpeed = pitch or 1.0
    s.Parent = hrp
    s:Play()
    s.Ended:Connect(function()
        s:Destroy()
    end)
end

                         
local function cameraImpulse(power)
    local cam = Workspace.CurrentCamera
    if not cam then return end
    task.spawn(function()
        for _ = 1, 3 do
            local shake = Vector3.new(
                (math.random() - 0.5) * power,
                (math.random() - 0.5) * power,
                (math.random() - 0.5) * power
            )
            cam.CFrame = cam.CFrame * CFrame.Angles(shake.X, shake.Y, shake.Z)
            RunService.RenderStepped:Wait()
        end
    end)
end

                                                 
local function spawnSonicBoomRing(position, direction, customColor)
    task.spawn(function()
        local ring = Instance.new("Part")
        ring.Name = "SonicBoomWave"
        ring.Shape = Enum.PartType.Cylinder
        ring.Size = Vector3.new(0.6, 6, 6)
        ring.CFrame = CFrame.lookAt(position, position + direction) * CFrame.Angles(0, math.rad(90), 0)
        ring.Material = Enum.Material.Neon
        ring.Color = customColor or Color3.fromRGB(255, 230, 80)
        ring.Transparency = 0.2
        ring.Anchored = true
        ring.CanCollide = false
        ring.CastShadow = false
        ring.Parent = Workspace

        local tw = TweenService:Create(ring, TweenInfo.new(0.32, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Size = Vector3.new(0.2, 34, 34),
            Transparency = 1
        })
        tw:Play()
        tw.Completed:Connect(function()
            ring:Destroy()
        end)
    end)
end

               
local function cleanOldTool()
    local bp = lp:FindFirstChild("Backpack")
    if bp then
        local old = bp:FindFirstChild("Super Sonic")
        if old then old:Destroy() end
    end
    local char = lp.Character
    if char then
        local old = char:FindFirstChild("Super Sonic")
        if old then old:Destroy() end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            for _, trk in ipairs(hum:GetPlayingAnimationTracks()) do
                if trk.Priority == Enum.AnimationPriority.Action4 then
                    pcall(function() trk:Stop(0) trk:Destroy() end)
                end
            end
        end
    end
end
