local function disableToolAnimation(char)
    local animate = char and char:FindFirstChild("Animate")
    if animate then
        pcall(function()
            local tn = animate:FindFirstChild("toolnone")
            if tn and tn:FindFirstChild("ToolNoneAnim") then
                tn.ToolNoneAnim.AnimationId = "rbxassetid://0"
            end
        end)
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            for _, trk in ipairs(hum:GetPlayingAnimationTracks()) do
                pcall(function()
                    if trk.Name:lower():find("tool") then
                        trk:Stop(0)
                    end
                end)
            end
        end
    end
end

                                          
