    local function cacheAndReturn(obj, url)
        if obj then
            cachedAnimAssets[assetId] = { Object = obj, Url = url }
        end
        return obj, url
    end

    local objs = nil
    pcall(function()
        if typeof(getobjects) == "function" then
            objs = getobjects("rbxassetid://" .. tostring(assetId))
        end
    end)
    if not objs or typeof(objs) ~= "table" or #objs == 0 then
        pcall(function()
            local ins = game:GetService("InsertService"):LoadLocalAsset("rbxassetid://" .. tostring(assetId))
            if ins then
