local function setSonicExeAction(actionName, duration)
    if not exeAnimDummies[actionName] and not exeLoadedTracks[actionName] then
        actionName = "Idle"
    end
    exeCurrentAction = actionName

    if activeExeTrackName ~= actionName then
        local prevTrack = activeExeTrackName and exeLoadedTracks[activeExeTrackName]
        local nextTrack = exeLoadedTracks[actionName] or exeLoadedTracks["Idle"]
        if prevTrack and prevTrack ~= nextTrack then
            pcall(function() prevTrack:Stop(0.18) end)
        end
        if nextTrack then
            pcall(function()
                nextTrack.Priority = Enum.AnimationPriority.Action4
                nextTrack:Play(0.18)
            end)
        end
        activeExeTrackName = actionName
    end

    if duration and duration > 0 then
        task.delay(duration, function()
            if inBrokenReality and sonicExeModel and exeCurrentAction == actionName then
                setSonicExeAction(exeInPursuit and "Run" or "Idle")
            end
        end)
    end
end

                                                                                   
                                                               
local function isObstructingClothing(item)
    if not item then return false end
    if item:IsA("Shirt") or item:IsA("Pants") or item:IsA("ShirtGraphic") then
        return true
    end

    if item:IsA("Accessory") then
        local name = string.lower(item.Name)
        if string.find(name, "hair") or string.find(name, "quill") or string.find(name, "sonic") or string.find(name, "head") then
            return false
        end

        local accType = item.AccessoryType
        if accType == Enum.AccessoryType.Hair or accType == Enum.AccessoryType.Hat or accType == Enum.AccessoryType.Face then
            return false
        end

        if accType == Enum.AccessoryType.Jacket or
           accType == Enum.AccessoryType.Sweater or
           accType == Enum.AccessoryType.Pants or
           accType == Enum.AccessoryType.Dress or
           accType == Enum.AccessoryType.Shorts or
           accType == Enum.AccessoryType.TShirt or
           accType == Enum.AccessoryType.Shirt then
            return true
        end

        local handle = item:FindFirstChild("Handle")
        if handle and handle:FindFirstChildOfClass("WrapLayer") then
            return true
        end
    end

    return false
end

                                                                 
local function stripObstructingClothing(char)
    if not char then return end
    for _, item in ipairs(char:GetChildren()) do
        if isObstructingClothing(item) then
            pcall(function() item:Destroy() end)
        end
    end
end

                                                                  
local function ensureSonicQuills(char, hairId)
    hairId = hairId or 97038612914194
    if not char then return end
    local head = char:FindFirstChild("Head")
    if not head then return end

    local existing = char:FindFirstChild("SonicQuills")
    if existing then
        local handle = existing:FindFirstChild("Handle")
        if handle and (handle:FindFirstChildOfClass("Weld") or handle:FindFirstChildOfClass("WeldConstraint")) then
            return
        end
        pcall(function() existing:Destroy() end)
    end

    pcall(function()
        local objs = game:GetObjects("rbxassetid://" .. tostring(hairId))
        if objs and objs[1] then
            local acc = objs[1]
            acc.Name = "SonicQuills"
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                hum:AddAccessory(acc)
            else
                acc.Parent = char
                local handle = acc:FindFirstChild("Handle")
                if handle then
                    handle.CFrame = head.CFrame
                    local w = Instance.new("WeldConstraint", handle)
                    w.Part0 = head
                    w.Part1 = handle
                end
            end
        end
    end)
end

local function monitorCharacterClothing(char, targetBundle)
    if not char then return end
    stripObstructingClothing(char)
    local conn = char.ChildAdded:Connect(function(child)
        task.wait(0.05)
        if isObstructingClothing(child) then
            pcall(function() child:Destroy() end)
        end
        local hairId = (targetBundle and targetBundle.Hair) or 97038612914194
        if not char:FindFirstChild("SonicQuills") then
            ensureSonicQuills(char, hairId)
        end
    end)
    table.insert(scriptConnections, conn)
end

                                                                             
local function applySonicBundle(targetBundle)
    targetBundle = targetBundle or SUPER_SONIC_BUNDLE
    local skinName = (targetBundle == SONIC_HEDGEHOG_BUNDLE) and "Sonic" or "Super Sonic"
    local hairAssetId = 97038612914194

    task.spawn(function()
        local remotes = ReplicatedStorage:FindFirstChild("Remotes") or ReplicatedStorage:FindFirstChild("RE") or ReplicatedStorage
        local wearBundleRemote = (remotes and remotes:FindFirstChild("WearBundle")) or (ReplicatedStorage:FindFirstChild("Remotes") and ReplicatedStorage.Remotes:FindFirstChild("WearBundle"))
        local changeBodyRemote = (remotes and remotes:FindFirstChild("ChangeCharacterBody")) or (ReplicatedStorage:FindFirstChild("Remotes") and ReplicatedStorage.Remotes:FindFirstChild("ChangeCharacterBody"))
        local wearRemote = (remotes and remotes:FindFirstChild("Wear")) or (ReplicatedStorage:FindFirstChild("Remotes") and ReplicatedStorage.Remotes:FindFirstChild("Wear"))

        local char = lp.Character
        if char then
            monitorCharacterClothing(char, targetBundle)
            ensureSonicQuills(char, hairAssetId)
        end

        notify(skinName, "Morphing into " .. skinName .. "...", 3)

                                                                               
        if wearBundleRemote then
            pcall(function()
                wearBundleRemote:InvokeServer(targetBundle.BundleId)
            end)
        end
        if changeBodyRemote then
            pcall(function()
                local argsBody = {
                    [1] = {
                        [1] = targetBundle.Torso,
                        [2] = targetBundle.RightArm,
                        [3] = targetBundle.LeftArm,
                        [4] = targetBundle.RightLeg,
                        [5] = targetBundle.LeftLeg,
                        [6] = targetBundle.Head
                    }
                }
                changeBodyRemote:InvokeServer(unpack(argsBody))
            end)
        end
        task.wait(0.9)

                                                                                    
        if wearRemote then
            pcall(function()
                wearRemote:InvokeServer(hairAssetId)
            end)
            task.wait(0.7)
        end

                                                       
        if lp.Character then
            ensureSonicQuills(lp.Character, hairAssetId)
            stripObstructingClothing(lp.Character)
        end

                                                   
        if wearBundleRemote and SONIC_ANIMS.Bundle then
            pcall(function()
                wearBundleRemote:InvokeServer(SONIC_ANIMS.Bundle)
            end)
            task.wait(0.7)
        end

        if lp.Character then
            _0xH_41a(lp.Character)
            disableToolAnimation(lp.Character)
            stripObstructingClothing(lp.Character)
            ensureSonicQuills(lp.Character, hairAssetId)
        end

        notify(skinName, skinName .. " Body Ready!", 3)
    end)

                                               
    local c = lp.Character
    if c then
        ensureSonicQuills(c, hairAssetId)
    end
end

                                                               
                                                       
                                                               
local lastVehicleHits = {}

local function enableClientSimulationMax()
    pcall(function()
        lp.ReplicationFocus = Workspace
        if setscriptable then
            setscriptable(lp, "SimulationRadius", true)
            setscriptable(lp, "MaximumSimulationRadius", true)
        end
        if sethiddenproperty then
            sethiddenproperty(lp, "MaximumSimulationRadius", math.huge)
            sethiddenproperty(lp, "SimulationRadius", math.huge)
        end
    end)
end

local function getNearbyVehicles(radius)
    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return {} end

    local myPos = hrp.Position
    local found = {}
    local seen = {}

    local function checkModel(model)
        if not model or not model:IsA("Model") or seen[model] then return end
        if char and model:IsDescendantOf(char) then return end

        local seat = model:FindFirstChildWhichIsA("VehicleSeat", true)
        if not seat then return end

        local primary = model.PrimaryPart or (seat.Parent and seat.Parent:FindFirstChildWhichIsA("BasePart")) or seat
        if not primary then return end

        local dist = (primary.Position - myPos).Magnitude
        if not radius or dist <= radius then
            seen[model] = true
            table.insert(found, {
                Model = model,
                Seat = seat,
                Primary = primary,
                Distance = dist
            })
        end
    end

    local vehiclesFolder = Workspace:FindFirstChild("Vehicles")
    if vehiclesFolder then
        for _, veh in ipairs(vehiclesFolder:GetChildren()) do
            checkModel(veh)
        end
    end

    for _, obj in ipairs(Workspace:GetChildren()) do
        if obj:IsA("Model") and obj ~= char then
            checkModel(obj)
        end
    end

    local wc = Workspace:FindFirstChild("WorkspaceCom")
    local helis = wc and wc:FindFirstChild("001_HeliStorage")
    if helis then
        for _, h in ipairs(helis:GetChildren()) do
            checkModel(h)
        end
    end

    return found
end

local function applyKineticCarImpact(vData, flightSpeed, moveDir)
    local primary = vData.Primary
    local model = vData.Model
    local seat = vData.Seat
    if not primary or not primary.Parent then return end

    local now = tick()
    if lastVehicleHits[primary] and (now - lastVehicleHits[primary]) < 0.6 then
        return
    end
    lastVehicleHits[primary] = now

    enableClientSimulationMax()

    local speedRatio = math.clamp((flightSpeed - CONFIG.FLIGHT_MIN_SPEED) / (CONFIG.FLIGHT_MAX_SPEED - CONFIG.FLIGHT_MIN_SPEED), 0, 1)
    local blastPower = 180 + (speedRatio * 240)
    local upwardKick = 85 + (speedRatio * 110)
    local blastVelocity = (moveDir * blastPower) + Vector3.new(0, upwardKick, 0)

    pcall(function()
                                                            
        if model then
            for _, part in ipairs(model:GetDescendants()) do
                if part:IsA("BasePart") and not part.Anchored then
                    part.AssemblyLinearVelocity = blastVelocity
                end
            end
        else
            primary.AssemblyLinearVelocity = blastVelocity
        end

                                                                                                 
        if seat and seat.Occupant and seat.Occupant.Parent then
            local occHrp = seat.Occupant.Parent:FindFirstChild("HumanoidRootPart")
            if occHrp then
                occHrp.AssemblyLinearVelocity = blastVelocity
            end
        end

        local bv = Instance.new("BodyVelocity")
        bv.Name = "SonicBlastCar"
        bv.MaxForce = Vector3.new(8e6, 8e6, 8e6)
        bv.Velocity = blastVelocity
        bv.Parent = primary

        local spinForce = 15 + (speedRatio * 25)
        primary.AssemblyAngularVelocity = Vector3.new(math.random(-spinForce, spinForce), math.random(-spinForce, spinForce), math.random(-spinForce, spinForce))

        task.delay(0.32, function()
            pcall(function()
                if bv and bv.Parent then bv:Destroy() end
            end)
        end)
    end)

    playSound(SFX.CarImpact, 0.9 + (speedRatio * 0.4), 2.2)
    cameraImpulse(0.08 + (speedRatio * 0.12))
    spawnSonicBoomRing(primary.Position, moveDir)
end

                                                               
                                                            
                                                               
local currentLockedTarget = nil

local function getPlayerNamesMap()
    local map = {}
    for _, p in ipairs(Players:GetPlayers()) do
        map[p.Name:lower()] = true
        map[p.DisplayName:lower()] = true
    end
    return map
end

local function scanUnoccupiedOwnerVehicles()
    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return nil end

    local cam = Workspace.CurrentCamera
    local lookDir = cam and cam.CFrame.LookVector or hrp.CFrame.LookVector

    local vehiclesFolder = Workspace:FindFirstChild("Vehicles")
    if not vehiclesFolder then return nil end

    local playerMap = getPlayerNamesMap()
    local bestTarget = nil
    local bestScore = -math.huge

    for _, model in ipairs(vehiclesFolder:GetChildren()) do
        if model:IsA("Model") and model ~= char then
            local lowerName = model.Name:lower()

            local hasOwner = false
            for pName, _ in pairs(playerMap) do
                if lowerName:find(pName, 1, true) then
                    hasOwner = true
                    break
                end
            end
            if not hasOwner and (lowerName:find("car") or lowerName:find("vehicle")) and not lowerName:find("brookhaven") then
                hasOwner = true
            end

            if hasOwner then
                local seat = model:FindFirstChildWhichIsA("VehicleSeat", true) or model:FindFirstChildWhichIsA("Seat", true)
                if seat and seat.Occupant == nil then
                    local primary = model.PrimaryPart or (seat.Parent and seat.Parent:FindFirstChildWhichIsA("BasePart")) or seat
                    if primary and primary.Position.Y > -50 then
                        local toTarget = primary.Position - hrp.Position
                        local dist = toTarget.Magnitude
                        if dist <= CONFIG.LOCK_ON_MAX_DIST and dist > 4 then
                            local dir = toTarget.Unit
                            local dot = lookDir:Dot(dir)
                            if dot > 0.40 then
                                local score = (dot * 85) - dist
                                if score > bestScore then
                                    bestScore = score
                                    bestTarget = {
                                        Model = model,
                                        Primary = primary,
                                        Seat = seat,
                                        Distance = dist
                                    }
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    return bestTarget
end

                                                               
                                       
                                                               
