updateBossHpUI = function(currentHp, maxHp, isEnraged)
    local ratio = math.clamp(currentHp / maxHp, 0, 1)
    bossHpFill.Size = UDim2.new(ratio, 0, 1, 0)
    task.delay(0.22, function()
        if bossHpLagFill and bossHpLagFill.Parent then
            TweenService:Create(bossHpLagFill, TweenInfo.new(0.45, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Size = UDim2.new(ratio, 0, 1, 0)
            }):Play()
        end
    end)

    if isEnraged or ratio <= 0.5 then
        bossTitle.Text = string.format("SONIC.EXE [ENRAGED] [%d / %d]", math.max(0, math.floor(currentHp)), maxHp)
        bossPhaseLabel.Text = "PHASE 2"
        bossPhaseLabel.TextColor3 = Color3.fromRGB(255, 30, 30)
        bossHpFill.BackgroundColor3 = Color3.fromRGB(180, 0, 0)
        bbStroke.Color = Color3.fromRGB(255, 30, 30)
    else
        bossTitle.Text = string.format("SONIC.EXE [%d / %d]", math.max(0, math.floor(currentHp)), maxHp)
        bossPhaseLabel.Text = "PHASE 1"
        bossPhaseLabel.TextColor3 = Color3.fromRGB(255, 160, 160)
        bossHpFill.BackgroundColor3 = Color3.fromRGB(225, 25, 25)
        bbStroke.Color = Color3.fromRGB(200, 20, 20)
    end
end

                                                             
