updateVignetteEffect = function(intensity, isBroken)
    if intensity <= 0.05 and not isBroken then
        vignetteFrame.Visible = false
        return
    end
    vignetteFrame.Visible = true
    if isBroken then
        vignetteStroke.Color = Color3.fromRGB(110, 10, 10)                      
        vignetteStroke.Thickness = 28
        vignetteStroke.Transparency = 0.2
    else
        vignetteStroke.Color = Color3.fromRGB(255, 215, 0)
        vignetteStroke.Thickness = math.floor(intensity * 20)
        vignetteStroke.Transparency = math.clamp(1.0 - (intensity * 0.75), 0.25, 1)
    end
end

                                    
