getDimensionCooldownRemaining = function()
    local stamp = _G.SonicExe_CooldownTimestamp or _G.SonicExe_DefeatedTimestamp
    if not stamp then return 0 end
    local elapsed = tick() - stamp
    local remain = CONFIG.DEFEAT_LOCKOUT_TIME - elapsed
    if remain <= 0 then
        _G.SonicExe_CooldownTimestamp = nil
        _G.SonicExe_DefeatedTimestamp = nil
        return 0
    end
    return remain
end

updateBoostUI = function(speed, overloadRatio, isBroken)
    boostHud.Visible = true
    if isBroken then
        local ratio = math.clamp((speed - CONFIG.FLIGHT_MIN_SPEED) / (CONFIG.BROKEN_REALITY_SPEED - CONFIG.FLIGHT_MIN_SPEED), 0, 1)
        boostBarFill.Size = UDim2.new(math.max(0.08, ratio), 0, 1, 0)
        boostBarFill.BackgroundColor3 = Color3.fromRGB(220, 30, 30)
        boostTitle.TextColor3 = Color3.fromRGB(255, 120, 120)
        local machLevel = string.format("MACH %.1f", 1.0 + (ratio * 3.5))
        boostTitle.Text = string.format("%s [VOID]: %d STUDS/S", machLevel, math.floor(speed))
        bStroke.Color = Color3.fromRGB(220, 30, 30)
        return
    end

    local cdRemain = getDimensionCooldownRemaining()
    if cdRemain > 0 then
        local mins = math.floor(cdRemain / 60)
        local secs = math.floor(cdRemain % 60)
        local progress = math.clamp(1 - (cdRemain / CONFIG.DEFEAT_LOCKOUT_TIME), 0.04, 1)
        boostBarFill.Size = UDim2.new(progress, 0, 1, 0)
        boostTitle.Text = string.format("COOLDOWN: %02d:%02d", mins, secs)
        boostTitle.TextColor3 = Color3.fromRGB(255, 130, 130)
        boostBarFill.BackgroundColor3 = Color3.fromRGB(175, 45, 45)
        bStroke.Color = Color3.fromRGB(195, 50, 50)
        return
    end

    bStroke.Color = Color3.fromRGB(255, 215, 0)
    local ratio = math.clamp((speed - CONFIG.FLIGHT_MIN_SPEED) / (CONFIG.FLIGHT_MAX_SPEED - CONFIG.FLIGHT_MIN_SPEED), 0, 1)

    if overloadRatio > 0 then
        local crackPercent = math.min(100, math.floor(overloadRatio * 100))
        boostBarFill.Size = UDim2.new(math.clamp(overloadRatio, 0.05, 1), 0, 1, 0)
        boostTitle.Text = string.format("OVERLOAD: %d%%", crackPercent)
        boostTitle.TextColor3 = Color3.fromRGB(255, 50, 50)
        boostBarFill.BackgroundColor3 = Color3.fromRGB(255, 45, 45)
    elseif ratio >= 0.78 then
        boostBarFill.Size = UDim2.new(ratio, 0, 1, 0)
        local machLevel = string.format("MACH %.1f", 1.0 + (ratio * 2.8))
        boostTitle.Text = string.format("%s: %d STUDS/S", machLevel, math.floor(speed))
        boostTitle.TextColor3 = Color3.fromRGB(255, 120, 120)
        boostBarFill.BackgroundColor3 = Color3.fromRGB(255, 90, 90)
    else
        boostBarFill.Size = UDim2.new(ratio, 0, 1, 0)
        local machLevel = string.format("MACH %.1f", 1.0 + (ratio * 2.8))
        boostTitle.Text = string.format("%s: %d STUDS/S", machLevel, math.floor(speed))
        boostTitle.TextColor3 = Color3.fromRGB(255, 235, 90)
        boostBarFill.BackgroundColor3 = Color3.fromRGB(255, 215, 0)
    end
end

