local function addKeyBadge(keyText, actionText, onClick, order)
    local isClickable = onClick ~= nil
    local badge = isClickable and Instance.new("TextButton") or Instance.new("Frame")
    badge.Name = keyText:gsub("[%s/()]+", "") .. "Badge"
    badge.Size = UDim2.new(0, 0, 0, 26)
    badge.AutomaticSize = Enum.AutomaticSize.X
    badge.BackgroundTransparency = 1
    badge.BorderSizePixel = 0
    badge.LayoutOrder = order or 1
    if isClickable then
        badge.Text = ""
        badge.AutoButtonColor = false
        badge.Activated:Connect(onClick)
    end
    badge.Parent = desktopFrame

    local bLayout = Instance.new("UIListLayout", badge)
    bLayout.FillDirection = Enum.FillDirection.Horizontal
    bLayout.VerticalAlignment = Enum.VerticalAlignment.Center
    bLayout.Padding = UDim.new(0, 4)

    local keyBox = isClickable and Instance.new("TextButton") or Instance.new("Frame")
    keyBox.Size = UDim2.new(0, 0, 0, 22)
    keyBox.AutomaticSize = Enum.AutomaticSize.X
    keyBox.BackgroundColor3 = onClick and Color3.fromRGB(35, 45, 25) or Color3.fromRGB(32, 32, 16)
    keyBox.BorderSizePixel = 0
    if isClickable then
        keyBox.Text = ""
        keyBox.AutoButtonColor = false
        keyBox.Activated:Connect(onClick)
    end
    keyBox.Parent = badge
    Instance.new("UICorner", keyBox).CornerRadius = UDim.new(0, 4)

    local keyStroke = Instance.new("UIStroke", keyBox)
    keyStroke.Color = onClick and Color3.fromRGB(0, 220, 255) or Color3.fromRGB(255, 215, 0)
    keyStroke.Thickness = 1

    local keyPadding = Instance.new("UIPadding", keyBox)
    keyPadding.PaddingLeft = UDim.new(0, 6)
    keyPadding.PaddingRight = UDim.new(0, 6)

    local kText = Instance.new("TextLabel")
    kText.Size = UDim2.new(0, 0, 1, 0)
    kText.AutomaticSize = Enum.AutomaticSize.X
    kText.BackgroundTransparency = 1
    kText.Text = keyText
    kText.TextColor3 = onClick and Color3.fromRGB(0, 240, 255) or Color3.fromRGB(255, 235, 90)
    kText.Font = Enum.Font.GothamBold
    kText.TextSize = 11
    kText.Parent = keyBox

    local aText = Instance.new("TextLabel")
    aText.Size = UDim2.new(0, 0, 1, 0)
    aText.AutomaticSize = Enum.AutomaticSize.X
    aText.BackgroundTransparency = 1
    aText.Text = actionText
    aText.TextColor3 = Color3.fromRGB(240, 240, 220)
    aText.Font = Enum.Font.GothamMedium
    aText.TextSize = 11
    aText.Parent = badge

    return {
        badge = badge,
        keyText = kText,
        actionText = aText,
        keyBox = keyBox,
        stroke = keyStroke
    }
end

