canUseSkill = function(key)
    local s = skillCooldowns[key]
    if not s then return true end
    return (tick() - s.lastUsed) >= s.cd
end

triggerSkillCooldown = function(key)
    local s = skillCooldowns[key]
    if s then
        s.lastUsed = tick()
    end
end

