local function adjustCombatDockScale()
    local cam = Workspace.CurrentCamera
    local vp = cam and cam.ViewportSize or Vector2.new(1920, 1080)
    if vp.X < 900 or (UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled) then
        dockScale.Scale = math.clamp(vp.X / 880, 0.58, 0.88)
        combatDock.Position = UDim2.new(0.40, 0, 0.94, 0)
    else
        dockScale.Scale = 1.0
        combatDock.Position = UDim2.new(0.5, 0, 0.895, 0)
    end
end
