local hotbarCards = {}

local function createHotbarCard(keyName, titleText, subText, onTrigger)
    local card = Instance.new("Frame")
    card.Name = keyName .. "_Card"
    card.Size = UDim2.new(0, 92, 0, 52)
    card.BackgroundColor3 = Color3.fromRGB(22, 22, 30)
    card.BorderSizePixel = 0
    card.Parent = combatDock
    Instance.new("UICorner", card).CornerRadius = UDim.new(0, 6)

    local cStroke = Instance.new("UIStroke", card)
    cStroke.Color = Color3.fromRGB(255, 215, 0)
    cStroke.Thickness = 1.2

    local keyBox = Instance.new("Frame")
    keyBox.Size = UDim2.new(0, 32, 0, 16)
    keyBox.Position = UDim2.new(0, 4, 0, 4)
    keyBox.BackgroundColor3 = Color3.fromRGB(36, 36, 20)
    keyBox.BorderSizePixel = 0
    keyBox.Parent = card
    Instance.new("UICorner", keyBox).CornerRadius = UDim.new(0, 4)

    local kLabel = Instance.new("TextLabel")
    kLabel.Size = UDim2.new(1, 0, 1, 0)
    kLabel.BackgroundTransparency = 1
    kLabel.Font = Enum.Font.GothamBlack
    kLabel.TextSize = 10
    kLabel.TextColor3 = Color3.fromRGB(255, 235, 90)
    kLabel.Text = keyName
    kLabel.Parent = keyBox

    local tLabel = Instance.new("TextLabel")
    tLabel.Size = UDim2.new(1, -40, 0, 16)
    tLabel.Position = UDim2.new(0, 38, 0, 4)
    tLabel.BackgroundTransparency = 1
    tLabel.Font = Enum.Font.GothamBold
    tLabel.TextSize = 10
    tLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
    tLabel.TextXAlignment = Enum.TextXAlignment.Left
    tLabel.Text = titleText
    tLabel.Parent = card

    local sLabel = Instance.new("TextLabel")
    sLabel.Size = UDim2.new(1, -8, 0, 14)
    sLabel.Position = UDim2.new(0, 6, 0, 21)
    sLabel.BackgroundTransparency = 1
    sLabel.Font = Enum.Font.GothamMedium
    sLabel.TextSize = 9
    sLabel.TextColor3 = Color3.fromRGB(180, 180, 195)
    sLabel.TextXAlignment = Enum.TextXAlignment.Left
    sLabel.Text = subText
    sLabel.Parent = card

    local cdOverlay = Instance.new("Frame")
    cdOverlay.Name = "CdOverlay"
    cdOverlay.Size = UDim2.new(1, 0, 1, 0)
    cdOverlay.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    cdOverlay.BackgroundTransparency = 0.55
    cdOverlay.BorderSizePixel = 0
    cdOverlay.Visible = false
    cdOverlay.ZIndex = 8
    cdOverlay.Parent = card
    Instance.new("UICorner", cdOverlay).CornerRadius = UDim.new(0, 6)

    local cdLabel = Instance.new("TextLabel")
    cdLabel.Name = "CdLabel"
    cdLabel.Size = UDim2.new(1, -8, 0, 14)
    cdLabel.Position = UDim2.new(0, 4, 1, -16)
    cdLabel.BackgroundTransparency = 1
    cdLabel.Font = Enum.Font.GothamBlack
    cdLabel.TextSize = 10
    cdLabel.TextColor3 = Color3.fromRGB(255, 235, 90)
    cdLabel.TextXAlignment = Enum.TextXAlignment.Right
    cdLabel.Text = "READY"
    cdLabel.ZIndex = 9
    cdLabel.Parent = card

    local btn = Instance.new("TextButton")
    btn.Size = UDim2.new(1, 0, 1, 0)
    btn.BackgroundTransparency = 1
    btn.Text = ""
    btn.ZIndex = 10
    btn.Parent = card

    local lastCardTrigger = 0
    local function fireCard()
        local now = tick()
        if now - lastCardTrigger < 0.08 then return end
        lastCardTrigger = now
        if onTrigger then onTrigger() end
    end
    btn.MouseButton1Click:Connect(fireCard)
    btn.Activated:Connect(fireCard)

    btn.MouseEnter:Connect(function()
        cStroke.Color = Color3.fromRGB(255, 255, 255)
        cStroke.Thickness = 1.8
    end)
    btn.MouseLeave:Connect(function()
        cStroke.Color = Color3.fromRGB(255, 215, 0)
        cStroke.Thickness = 1.2
    end)

    local cardData = {
        frame = card,
        stroke = cStroke,
        keyBox = keyBox,
        kLabel = kLabel,
        tLabel = tLabel,
        sLabel = sLabel,
        cdOverlay = cdOverlay,
        cdLabel = cdLabel,
        btn = btn
    }
    hotbarCards[keyName] = cardData
    return cardData
end

