showBossAttackWarning = function(attackName, dodgeHint)
    if not inBrokenReality or not warningBanner then return end
    warningTopLabel.Text = "⚠ BOSS ATTACK TELEGRAPH ⚠"
    warningTopLabel.TextColor3 = Color3.fromRGB(255, 60, 60)
    warningText.Text = string.format("%s  ➤  %s", attackName:upper(), dodgeHint:upper())
    warningText.TextColor3 = Color3.fromRGB(255, 235, 100)
    warningBanner.Visible = true
    warningBanner.BackgroundTransparency = 0.08
    warningStroke.Color = Color3.fromRGB(255, 45, 45)
    playSound(SFX.LockPing, 1.6, 1.8)

    local pulseTw = TweenService:Create(warningStroke, TweenInfo.new(0.2, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, 5, true), {
        Color = Color3.fromRGB(255, 220, 220)
    })
    pulseTw:Play()

    task.delay(2.6, function()
        if warningBanner and warningBanner.Parent then
            local tw = TweenService:Create(warningBanner, TweenInfo.new(0.3), { BackgroundTransparency = 1 })
            tw:Play()
            tw.Completed:Connect(function()
                if warningBanner then warningBanner.Visible = false end
            end)
        end
    end)
end

showBossStaggerAlert = function()
    if not inBrokenReality or not warningBanner then return end
    warningTopLabel.Text = "★ BOSS STAGGERED! ★"
