showDamagePopup = function(position, text, isCrit, isPlayer)
    task.spawn(function()
        local part = Instance.new("Part")
        part.Size = Vector3.new(0.1, 0.1, 0.1)
        part.Transparency = 1
        part.CanCollide = false
        part.Anchored = true
        part.CFrame = CFrame.new(position)
        part.Parent = Workspace

        local bb = Instance.new("BillboardGui")
        bb.Size = UDim2.new(0, 160, 0, 36)
        bb.AlwaysOnTop = true
        bb.Parent = part

        local lbl = Instance.new("TextLabel")
        lbl.Size = UDim2.new(1, 0, 1, 0)
        lbl.BackgroundTransparency = 1
        lbl.Font = Enum.Font.GothamBlack
        lbl.TextSize = isCrit and 24 or 18
        lbl.Text = text
        lbl.TextColor3 = isPlayer and Color3.fromRGB(255, 55, 55) or (isCrit and Color3.fromRGB(255, 235, 50) or Color3.fromRGB(255, 180, 50))
        lbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        lbl.TextStrokeTransparency = 0
        lbl.Parent = bb

        local riseTween = TweenService:Create(part, TweenInfo.new(0.65, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            CFrame = part.CFrame + Vector3.new(0, 4.5, 0)
        })
        local fadeTween = TweenService:Create(lbl, TweenInfo.new(0.65, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
            TextTransparency = 1,
            TextStrokeTransparency = 1
        })
        riseTween:Play()
        fadeTween:Play()

        task.delay(0.7, function()
            part:Destroy()
        end)
    end)
end

