local sonicHighlight = nil
local sonicTrail = nil

local function setupSonicVisualEffects(char)
    if not char then return end
    if sonicHighlight then pcall(function() sonicHighlight:Destroy() end) end
    if sonicTrail then pcall(function() sonicTrail:Destroy() end) end

    local hl = Instance.new("Highlight")
    hl.Name = "SuperSonic_Highlight"
    hl.Adornee = char
    hl.FillColor = Color3.fromRGB(255, 220, 50)
    hl.FillTransparency = 0.88
    hl.OutlineColor = Color3.fromRGB(255, 235, 80)
    hl.OutlineTransparency = 0.35
    hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    hl.Enabled = (isToolEquipped or inBrokenReality) == true
    hl.Parent = char
    sonicHighlight = hl
    _G.SuperSonic_Highlight = hl

    local hrp = char:FindFirstChild("HumanoidRootPart")
    if hrp then
        local trailAtt0 = Instance.new("Attachment", hrp)
        trailAtt0.Position = Vector3.new(0, 1.2, 0)

        local trailAtt1 = Instance.new("Attachment", hrp)
        trailAtt1.Position = Vector3.new(0, -1.2, 0)

        local tr = Instance.new("Trail")
        tr.Name = "SuperSonic_GoldTrail"
        tr.Attachment0 = trailAtt0
        tr.Attachment1 = trailAtt1
        tr.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 245, 120)),
            ColorSequenceKeypoint.new(0.6, Color3.fromRGB(255, 215, 0)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(200, 160, 20))
        })
        tr.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.25),
            NumberSequenceKeypoint.new(0.7, 0.65),
            NumberSequenceKeypoint.new(1, 1)
        })
        tr.Lifetime = 0.35
        tr.LightEmission = 1
        tr.Enabled = false
        tr.Parent = hrp
        sonicTrail = tr
        _G.SuperSonic_Trail = tr
    end
end

local function setAuraFlightIntensity(active, intensity, isBroken)
    if not isToolEquipped and not isBroken then
        if sonicHighlight then sonicHighlight.Enabled = false end
        if sonicTrail then sonicTrail.Enabled = false end
        return
    end

    if sonicHighlight then
        sonicHighlight.Enabled = true
        if isBroken then
            sonicHighlight.FillColor = Color3.fromRGB(255, 235, 60)
            sonicHighlight.OutlineColor = Color3.fromRGB(255, 255, 255)
            sonicHighlight.FillTransparency = 0.2
            sonicHighlight.OutlineTransparency = 0.0
        elseif active then
            sonicHighlight.FillColor = Color3.fromRGB(255, 220, 50)
            sonicHighlight.OutlineColor = Color3.fromRGB(255, 235, 80)
            sonicHighlight.FillTransparency = math.clamp(0.85 - (intensity * 0.30), 0.50, 0.85)
            sonicHighlight.OutlineTransparency = math.clamp(0.35 - (intensity * 0.30), 0.05, 0.35)
        else
            sonicHighlight.FillColor = Color3.fromRGB(255, 220, 50)
            sonicHighlight.OutlineColor = Color3.fromRGB(255, 235, 80)
            sonicHighlight.FillTransparency = 0.88
            sonicHighlight.OutlineTransparency = 0.35
        end
    end
    if sonicTrail then
        sonicTrail.Enabled = (isToolEquipped or isBroken) and active and (intensity > 0.08 or isBroken)
        if isBroken then
            sonicTrail.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),
                ColorSequenceKeypoint.new(0.5, Color3.fromRGB(255, 220, 50)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(200, 160, 0))
            })
            sonicTrail.Lifetime = 0.75
        else
            sonicTrail.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 245, 120)),
                ColorSequenceKeypoint.new(0.6, Color3.fromRGB(255, 215, 0)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(200, 160, 20))
            })
            if active then
                sonicTrail.Lifetime = 0.25 + (intensity * 0.35)
            end
        end
    end
end

                                                               
                                                        
                                                               
