local function hideAllOtherPlayers()
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= lp and p.Character then
            for _, d in ipairs(p.Character:GetDescendants()) do
                if d:IsA("BasePart") then
                    pcall(function() d.LocalTransparencyModifier = 1 end)
                end
            end
        end
    end
end

                                                                            
local savedLighting = nil
local function applyHorrorLighting()
    if not savedLighting then
        savedLighting = {
            ClockTime = Lighting.ClockTime,
            Brightness = Lighting.Brightness,
            OutdoorAmbient = Lighting.OutdoorAmbient,
            FogColor = Lighting.FogColor,
            FogStart = Lighting.FogStart,
            FogEnd = Lighting.FogEnd,
            ExposureCompensation = Lighting.ExposureCompensation
        }
    end

    pcall(function()
        Lighting.ClockTime = 14
        Lighting.Brightness = 1.6
        Lighting.OutdoorAmbient = Color3.fromRGB(120, 120, 120)
        Lighting.FogColor = Color3.fromRGB(140, 140, 140)
        Lighting.FogStart = 500
        Lighting.FogEnd = 100000
        Lighting.ExposureCompensation = 0.1
    end)
end

local function restoreHorrorLighting()
    if savedLighting then
        pcall(function()
            Lighting.ClockTime = savedLighting.ClockTime
            Lighting.Brightness = savedLighting.Brightness
            Lighting.OutdoorAmbient = savedLighting.OutdoorAmbient
            Lighting.FogColor = savedLighting.FogColor
            Lighting.FogStart = savedLighting.FogStart
            Lighting.FogEnd = savedLighting.FogEnd
            Lighting.ExposureCompensation = savedLighting.ExposureCompensation
        end)
        savedLighting = nil
    end
end
_G.SuperSonic_RestoreLighting = restoreHorrorLighting

                                                                                     
local brokenHoverPos = nil
local brokenHoverGyro = nil
local brokenIdleTrack = nil

local function enableSuperSonicLevitation(hrp, hum)
    if not hrp or not hum then return end
    local char = hrp.Parent

                                                                                                
    pcall(function()
        local animScript = char and char:FindFirstChild("Animate")
        if animScript then
            animScript.Enabled = false
        end

        hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, false)
        hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
        hum:SetStateEnabled(Enum.HumanoidStateType.GettingUp, false)
        hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)

        local animator = hum:FindFirstChildOfClass("Animator")
        if animator then
            for _, tr in ipairs(animator:GetPlayingAnimationTracks()) do
                tr:Stop(0)
            end
        end

        if not brokenIdleTrack then
            brokenIdleTrack = playSonicEmoteTrack(hum, SONIC_ANIMS.Idle, true)
        end
        if brokenIdleTrack then
            brokenIdleTrack:Play(0.1)
            brokenIdleTrack.Priority = Enum.AnimationPriority.Action4
        end
    end)

    if not brokenHoverPos or not brokenHoverPos.Parent then
        brokenHoverPos = Instance.new("BodyPosition")
        brokenHoverPos.Name = "BrokenLevitationPos"
        brokenHoverPos.MaxForce = Vector3.new(1e9, 1e9, 1e9)
        brokenHoverPos.P = 35000
        brokenHoverPos.D = 1500
        brokenHoverPos.Position = hrp.Position
        brokenHoverPos.Parent = hrp
    end

    if not brokenHoverGyro or not brokenHoverGyro.Parent then
        brokenHoverGyro = Instance.new("BodyGyro")
        brokenHoverGyro.Name = "BrokenLevitationGyro"
        brokenHoverGyro.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
        brokenHoverGyro.P = 30000
        brokenHoverGyro.D = 1200
        brokenHoverGyro.CFrame = hrp.CFrame
        brokenHoverGyro.Parent = hrp
    end
end

local function disableSuperSonicLevitation(hum)
    if brokenHoverPos then
        pcall(function() brokenHoverPos:Destroy() end)
        brokenHoverPos = nil
    end
    if brokenHoverGyro then
        pcall(function() brokenHoverGyro:Destroy() end)
        brokenHoverGyro = nil
    end
    if brokenIdleTrack then
        pcall(function() brokenIdleTrack:Stop(0.2) end)
        brokenIdleTrack = nil
    end
    if hum then
        pcall(function()
            local char = hum.Parent
            local animScript = char and char:FindFirstChild("Animate")
            if animScript then
                animScript.Enabled = true
            end

            hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true)
            hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
            hum:SetStateEnabled(Enum.HumanoidStateType.GettingUp, true)
            hum.PlatformStand = false
        end)
    end
end

                                                                              
