    tag.Name = "ExeTag"
    tag.Size = UDim2.new(0, 240, 0, 48)
    tag.StudsOffset = Vector3.new(0, 4.2, 0)
    tag.AlwaysOnTop = true
    tag.Adornee = head or hrp
    tag.Parent = head or hrp

    local tagText = Instance.new("TextLabel")
    tagText.Size = UDim2.new(1, 0, 1, 0)
    tagText.BackgroundTransparency = 1
    tagText.Font = Enum.Font.GothamBlack
    tagText.TextSize = 18
    tagText.TextColor3 = Color3.fromRGB(255, 30, 30)
    tagText.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    tagText.TextStrokeTransparency = 0
    tagText.Text = "SONIC.EXE"
    tagText.Parent = tag

    local beaconLight = Instance.new("PointLight")
    beaconLight.Name = "ExeBeacon"
    beaconLight.Color = Color3.fromRGB(255, 10, 10)
    beaconLight.Range = 45
    beaconLight.Brightness = 8
    beaconLight.Parent = torso

    exe.Parent = Workspace
    sonicExeModel = exe
    _G.SuperSonic_ExeModel = exe
    sonicExeHp = CONFIG.EXE_MAX_HP

    return exe
end

local isBossStaggered = false
local bossStaggerEndTime = 0
local isBossRecovering = false

                                     
local function damageSonicExe(dmg, attackType)
    if not sonicExeModel or sonicExeHp <= 0 then return end

    local actualDmg = dmg
    local isStaggerTrigger = false

                                                           
    if isBossRecovering and (attackType == "Dropkick" or attackType == "Homing") and not isBossStaggered then
        isBossStaggered = true
        bossStaggerEndTime = tick() + 2.2
        isBossRecovering = false
        isStaggerTrigger = true
        if showBossStaggerAlert then showBossStaggerAlert() end
    end

    if isBossStaggered then
        actualDmg = math.floor(dmg * 1.5)
    elseif not isBossRecovering then
        actualDmg = math.floor(dmg * 0.7)
    end

    sonicExeHp = math.max(0, sonicExeHp - actualDmg)

    if registerComboHit then registerComboHit() end
    local isCrit = isStaggerTrigger or isBossStaggered or (actualDmg >= 180)
    local exeHrp = sonicExeModel:FindFirstChild("HumanoidRootPart")
    if exeHrp and showDamagePopup then
        local offset = Vector3.new(math.random(-15, 15) / 10, 3.2 + math.random(0, 12) / 10, math.random(-15, 15) / 10)
        local tag = isStaggerTrigger and " ★STAGGER!★" or (isBossStaggered and " CRIT!" or "")
        showDamagePopup(exeHrp.Position + offset, string.format("-%d%s", actualDmg, tag), isCrit, false)
    end

    local isEnraged = (sonicExeHp <= (CONFIG.EXE_MAX_HP * 0.5))
    if isEnraged and exePhase == 1 then
        exePhase = 2
        setSonicExeAction("Roar", 2.2)
        playSound(SFX.ExeScream, 0.85, 3.2)
        cameraImpulse(0.25)
        local eHrp = sonicExeModel and sonicExeModel:FindFirstChild("HumanoidRootPart")
        if eHrp then
            spawnSonicBoomRing(eHrp.Position, Vector3.new(0, 1, 0), Color3.fromRGB(255, 0, 0))
            spawnExeAfterimage(eHrp.CFrame)
        end
        if showBossAttackWarning then
            showBossAttackWarning("BLOOD MOON ENRAGED (+30% BUFF)", "Sonic.exe enters Berserk Frenzy! Dodge carefully!")
        end
        notify("Super Sonic", "Sonic.exe enters BERSERK FRENZY (+30% ATK/SPD)!", 3)
    end

    updateBossHpUI(sonicExeHp, CONFIG.EXE_MAX_HP, isEnraged)

    cameraImpulse(0.06)
    playSound(SFX.CarImpact, 1.25, 2.0)

    local hl = sonicExeModel:FindFirstChildOfClass("Highlight")
    if hl then
        hl.FillColor = isBossStaggered and Color3.fromRGB(255, 215, 0) or Color3.fromRGB(255, 255, 255)
        task.delay(0.1, function()
            if hl and hl.Parent then
                if isBossStaggered then
                    hl.FillColor = Color3.fromRGB(255, 200, 50)
                else
                    hl.FillColor = isEnraged and Color3.fromRGB(120, 0, 0) or Color3.fromRGB(60, 0, 0)
                end
            end
        end)
    end

    if sonicExeHp <= 0 then
        _G.SonicExe_DefeatedTimestamp = tick()

        playSound(SFX.ExeScream, 0.7, 3.0)
        playSound(SFX.SonicBoom, 0.65, 3.0)
        cameraImpulse(0.3)

        local hrp = sonicExeModel:FindFirstChild("HumanoidRootPart")
        if hrp then
            spawnSonicBoomRing(hrp.Position, Vector3.new(0, 1, 0), Color3.fromRGB(255, 0, 0))
            spawnSonicBoomRing(hrp.Position, Vector3.new(1, 0, 0), Color3.fromRGB(255, 220, 50))
        end

        task.spawn(function()
            if sonicExeModel then
                for _, p in ipairs(sonicExeModel:GetDescendants()) do
                    if p:IsA("BasePart") then
                        TweenService:Create(p, TweenInfo.new(1.2), { Transparency = 1 }):Play()
                    end
                end
            end
            task.wait(1.2)
            if sonicExeModel then
                sonicExeModel:Destroy()
                sonicExeModel = nil
                _G.SuperSonic_ExeModel = nil
            end
        end)

        notify("Super Sonic", "Sonic.exe defeated. Cooldown: 15m.", 5)
        task.wait(2.2)
        exitBrokenReality()
    end
end

                                            
local function damagePlayer(dmg, attackName)
    if not inBrokenReality or isPlayerDefeated then return end
    local char = lp.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hum or hum.Health <= 0 then return end

    playerHp = math.max(0, playerHp - dmg)
    updatePlayerHpUI(playerHp, CONFIG.PLAYER_MAX_HP)

    if hrp and showDamagePopup then
        showDamagePopup(hrp.Position + Vector3.new(0, 3.5, 0), string.format("-%d", dmg), false, true)
    end

    cameraImpulse(0.12)
    playSound(SFX.CarImpact, 0.85, 2.5)

    task.spawn(function()
        local redFlash = Instance.new("Frame")
        redFlash.Size = UDim2.new(1, 0, 1, 0)
        redFlash.BackgroundColor3 = Color3.fromRGB(255, 0, 0)
        redFlash.BackgroundTransparency = 0.65
        redFlash.BorderSizePixel = 0
        redFlash.ZIndex = 48
        redFlash.Parent = screenGui
        local tw = TweenService:Create(redFlash, TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { BackgroundTransparency = 1 })
        tw:Play()
        tw.Completed:Connect(function() redFlash:Destroy() end)
    end)

    if hrp and sonicExeModel and sonicExeModel:FindFirstChild("HumanoidRootPart") then
        local pushDir = (hrp.Position - sonicExeModel.HumanoidRootPart.Position).Unit
        hrp.AssemblyLinearVelocity = (pushDir * 65) + Vector3.new(0, 18, 0)
    end

    if playerHp <= 0 and not isPlayerDefeated then
        isPlayerDefeated = true
        playSound(SFX.ExeLaugh, 0.6, 3.5)
        playSound(SFX.ExeScream, 0.7, 3.0)
        cameraImpulse(0.35)

        blackoutFrame.Visible = true
        blackoutFrame.BackgroundTransparency = 0
        exeJumpscareFace.Visible = true
        exeDialogueLabel.Visible = true
        exeDialogueLabel.Text = "\"YOU'RE TOO SLOW.\""
        exeDialogueLabel.TextColor3 = Color3.fromRGB(255, 10, 10)

        task.wait(2.8)

        blackoutFrame.Visible = false
        exeJumpscareFace.Visible = false
        exeDialogueLabel.Visible = false
        exitBrokenReality()
        notify("Super Sonic", "You died.", 4)
    end
end

                                                               
                                                         
                                                               
