local function spawnExeAfterimage(cf)
    task.spawn(function()
        local ghost = Instance.new("Part")
        ghost.Size = Vector3.new(2.8, 5.2, 2.2)
        ghost.CFrame = cf
        ghost.Material = Enum.Material.Neon
        ghost.Color = Color3.fromRGB(220, 20, 20)
        ghost.Transparency = 0.35
        ghost.CanCollide = false
        ghost.Anchored = true
        ghost.Parent = Workspace
        local m = Instance.new("SpecialMesh", ghost)
        m.MeshType = Enum.MeshType.Sphere
        TweenService:Create(ghost, TweenInfo.new(0.38, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Transparency = 1,
            Size = Vector3.new(4.2, 7.5, 3.8)
        }):Play()
        task.delay(0.38, function() ghost:Destroy() end)
    end)
end

                                                               
                                             
                                                               
local function startExeCombatAI()
    if exeAiLoopConn then exeAiLoopConn:Disconnect() end

    local attackTypes = { "PhantomClaws", "AbyssalCataclysm", "AbyssalVortex", "VoidSingularity" }
    local currentAttackIndex = 1
    exeInPursuit = false
    isBossStaggered = false
    isBossRecovering = false

    exeAiLoopConn = RunService.Heartbeat:Connect(function(dt)
        if not inBrokenReality or not sonicExeModel or sonicExeHp <= 0 or isPlayerDefeated then return end
        local char = lp.Character
        local myHrp = char and char:FindFirstChild("HumanoidRootPart")
        local exeHrp = sonicExeModel:FindFirstChild("HumanoidRootPart")
        if not myHrp or not exeHrp then return end

        local bv = exeHrp:FindFirstChild("ExeHoverVel")
        local bg = exeHrp:FindFirstChild("ExeHoverGyro")

        local toPlayer = myHrp.Position - exeHrp.Position
        local dist = toPlayer.Magnitude
        local dir = toPlayer.Unit

        local floatOffset = math.sin(tick() * 3.8) * 1.5

        if bg then
            bg.CFrame = CFrame.lookAt(exeHrp.Position, myHrp.Position)
        end

                                                                        
                                                             
                                                                        
        if skyRiftModel and skyRiftModel.PrimaryPart then
            local riftPos = skyRiftModel.PrimaryPart.Position
            local toRift = riftPos - myHrp.Position
            local distToRift = toRift.Magnitude

                                                         
            if riftBeaconBillboard then
                local lbl = riftBeaconBillboard:FindFirstChild("RiftLabel")
                if lbl then
                    lbl.Text = string.format("DIMENSIONAL RIFT [%dm]", math.floor(distToRift))
                end
            end

                                                                   
            local isFleeing = isFlying and (distToRift < 650) and (myHrp.Position.Y > 200)
            if isFleeing and not isPlayerDefeated then
                if not exeInPursuit then
                    exeInPursuit = true
                    setSonicExeAction("Run")
                    playSound(SFX.ExeScream, 1.0, 3.2)
                    cameraImpulse(0.2)
                    if showBossAttackWarning then
                        showBossAttackWarning("FURIOUS PURSUIT", "Sonic.exe is hunting you down! FONCE!")
                    end
                end

                                                                    
                local chaseDir = (myHrp.Position - exeHrp.Position).Unit
                local chaseSpeed = (exePhase == 2) and 455 or 377
                if bv then
                    bv.Velocity = chaseDir * chaseSpeed
                end

                                                                          
                local distToExe = (myHrp.Position - exeHrp.Position).Magnitude
                if distToExe <= 18 and not exeAttackCooldown then
                    exeAttackCooldown = true
                    playSound(SFX.SonicBoom, 0.8, 2.5)
                    cameraImpulse(0.26)
                    damagePlayer(325, "Abyssal Intercept")
                    myHrp.AssemblyLinearVelocity = Vector3.new(0, -210, 0) + (chaseDir * 55)
                    if showBossAttackWarning then
                        showBossAttackWarning("INTERCEPTED!", "Too slow! He slammed you down!")
                    end
                    task.wait(1.2)
                    exeAttackCooldown = false
                end
            else
                if exeInPursuit then
                    exeInPursuit = false
                    setSonicExeAction("Idle")
                end
            end

                                          
            if distToRift <= 48 and not isPlayerDefeated then
                local currentSpeed = myHrp.AssemblyLinearVelocity.Magnitude
                local isMachSpeed = (currentFlightSpeed >= (CONFIG.FLIGHT_MIN_SPEED * 1.5)) or (currentSpeed >= 160)

                if isMachSpeed then
                                                  
                    isPlayerDefeated = true
                    notify("Super Sonic", "Breaching Dimensional Rift...", 3)
                    task.spawn(function()
                        playSound(SFX.SonicBoom, 0.65, 3.5)
                        playSound(SFX.TimeCollapse, 1.25, 3.0)
                        cameraImpulse(0.35)

                        if flashFrame then
                            flashFrame.Visible = true
                            flashFrame.BackgroundTransparency = 0
                        end

                        if camera then camera.FieldOfView = 120 end
                        task.wait(0.45)

                        destroySkyDimensionalRift()
                        exitBrokenReality()

                        if camera then camera.FieldOfView = 70 end
                        if flashFrame then
                            TweenService:Create(flashFrame, TweenInfo.new(1.0), { BackgroundTransparency = 1 }):Play()
                        end

                        notify("Super Sonic", "Escaped through the Dimensional Rift! Lockout: 15m.", 5)
                    end)
                    return
                else
                                                                    
                    if (tick() - lastRiftRepelTime) > 2.0 then
                        lastRiftRepelTime = tick()
                        playSound(SFX.CarImpact, 0.9, 2.5)
                        cameraImpulse(0.18)
                        myHrp.AssemblyLinearVelocity = (myHrp.Position - riftPos).Unit * 160 + Vector3.new(0, -45, 0)
                        if showBossAttackWarning then
                            showBossAttackWarning("THRUST TOO WEAK!", "You must FONCER at Mach Speed (Hold C) to escape!")
                        end
                    end
                end
            end
        end

                                                                                 
        if not exeInPursuit then
                                        
            if isBossStaggered then
                setSonicExeAction("Fall")
                if tick() < bossStaggerEndTime then
                    if bv then bv.Velocity = Vector3.zero end
                    return
                else
                    isBossStaggered = false
                    isBossRecovering = false
                    setSonicExeAction("Idle")
                    local hl = sonicExeModel:FindFirstChildOfClass("Highlight")
                    if hl then
                        hl.FillColor = (exePhase == 2) and Color3.fromRGB(120, 0, 0) or Color3.fromRGB(60, 0, 0)
                    end
                end
            end

                                                                                                         
            local strafeWobble = math.sin(tick() * 1.8) * 42
            local strafeDir = Vector3.new(-dir.Z, 0, dir.X).Unit
            local floatY = math.sin(tick() * 3.5) * 3.5

            if dist < 20 then
                                                          
                if bv then
                    bv.Velocity = (-dir * 72) + (strafeDir * strafeWobble) + Vector3.new(0, floatY, 0)
                end
                setSonicExeAction("Run")
            elseif dist > 45 then
                                            
                if bv then
                    bv.Velocity = (dir * 91) + (strafeDir * (strafeWobble * 0.5)) + Vector3.new(0, floatY, 0)
                end
                setSonicExeAction("Run")
            else
                                                               
                if bv then
                    bv.Velocity = (strafeDir * strafeWobble) + Vector3.new(0, floatY, 0)
                end
                setSonicExeAction("Idle")
            end

            if not exeAttackCooldown then
                exeAttackCooldown = true
                local chosenAttack = attackTypes[currentAttackIndex]
                currentAttackIndex = (currentAttackIndex % #attackTypes) + 1

                                                                                   
                                                                                              
                                                                                   
                    if chosenAttack == "PhantomClaws" then
                        setSonicExeAction("Slash", 1.4)
                        if showBossAttackWarning then
                            showBossAttackWarning("Phantom Claws (+30% ATK)", "Dodge behind him: Press Q")
                        end
                        task.spawn(function()
                                                     
                            playSound(SFX.LockPing, 1.6, 2.0)
                            local windupHl = sonicExeModel:FindFirstChildOfClass("Highlight")
                            if windupHl then windupHl.FillColor = Color3.fromRGB(255, 30, 30) end
                            task.wait(0.65)

                            spawnExeAfterimage(exeHrp.CFrame)
                            playSound(SFX.Teleport, 1.2, 1.8)
                            cameraImpulse(0.12)

                            local behindPos = myHrp.Position - (myHrp.CFrame.LookVector * 7.5) + Vector3.new(0, 2.5, 0)
                            exeHrp.CFrame = CFrame.lookAt(behindPos, myHrp.Position)
                            spawnSonicBoomRing(behindPos, myHrp.CFrame.LookVector, Color3.fromRGB(220, 20, 20))
                            spawnExeAfterimage(exeHrp.CFrame)

                            task.wait(0.15)
                            playSound(SFX.ExeLaugh, 1.1, 2.2)

                                                                                   
                            for s = -1.5, 1.5, 1.0 do
                                local slash = Instance.new("Part")
                                slash.Size = Vector3.new(0.25, 9, 4.5)
                                slash.CFrame = behindPos * CFrame.new(s * 2.2, 0, -3.2) * CFrame.Angles(math.rad(s * 22), math.rad(90), math.rad(-15))
                                slash.Material = Enum.Material.Neon
                                slash.Color = Color3.fromRGB(255, 15, 15)
                                slash.Transparency = 0.05
                                slash.CanCollide = false
                                slash.Anchored = true
                                slash.Parent = Workspace
                                Instance.new("SpecialMesh", slash).MeshType = Enum.MeshType.Sphere

                                TweenService:Create(slash, TweenInfo.new(0.35, Enum.EasingStyle.Quad), {
                                    Transparency = 1,
                                    Size = Vector3.new(0.1, 15, 7)
                                }):Play()
                                task.delay(0.35, function() slash:Destroy() end)
                            end

                            if bv then bv.Velocity = (myHrp.Position - exeHrp.Position).Unit * 254 end
                            task.wait(0.20)
                            damagePlayer(260, "Phantom Claws")

                                                                       
                            if exePhase == 2 and inBrokenReality and sonicExeModel then
                                task.wait(0.12)
                                spawnExeAfterimage(exeHrp.CFrame)
                                local sidePos = myHrp.Position + (myHrp.CFrame.RightVector * 8) + Vector3.new(0, 1.5, 0)
                                exeHrp.CFrame = CFrame.lookAt(sidePos, myHrp.Position)
                                spawnExeAfterimage(exeHrp.CFrame)
                                playSound(SFX.HitSlash, 1.3, 2.0)
                                damagePlayer(85, "Phantom Cross Slash")
                            end

                            task.wait(0.15)
                            if bv then bv.Velocity = Vector3.zero end

                                                                       
                            isBossRecovering = true
                            task.wait(1.1)
                            isBossRecovering = false

                            task.wait(exePhase == 2 and 0.35 or 0.75)
                            exeAttackCooldown = false
                        end)

                                                                                   
                                                                                            
                                                                                   
                    elseif chosenAttack == "AbyssalCataclysm" then
                        setSonicExeAction("Roar", 1.8)
                        if showBossAttackWarning then
                            showBossAttackWarning("Abyssal Cataclysm (+30% ATK)", "Take to the skies: Fly with C")
                        end
                        task.spawn(function()
                            playSound(SFX.TimeCollapse, 1.1, 2.2)
                            cameraImpulse(0.12)

                            local pPos = myHrp.Position
                            local points = {
                                pPos + Vector3.new(12, 0, 12),
                                pPos + Vector3.new(-12, 0, 12),
                                pPos + Vector3.new(12, 0, -12),
                                pPos + Vector3.new(-12, 0, -12),
                                pPos + Vector3.new(0, 0, 14),
                                pPos + Vector3.new(0, 0, 0)
                            }

                            local indicators = {}
                            for _, pt in ipairs(points) do
                                local ind = Instance.new("Part")
                                ind.Size = Vector3.new(8, 0.2, 8)
                                ind.CFrame = CFrame.new(pt.X, pt.Y - 2.8, pt.Z)
                                ind.Material = Enum.Material.Neon
                                ind.Color = Color3.fromRGB(255, 30, 30)
                                ind.Transparency = 0.35
                                ind.CanCollide = false
                                ind.Anchored = true
                                ind.Parent = Workspace
                                table.insert(indicators, ind)
                            end

                            task.wait(1.0)

                            for _, ind in ipairs(indicators) do
                                local pos = ind.Position
                                ind:Destroy()

                                local spike = Instance.new("WedgePart")
                                spike.Size = Vector3.new(4, 28, 4)
                                spike.CFrame = CFrame.new(pos.X, pos.Y + 12, pos.Z) * CFrame.Angles(math.rad(math.random(-15, 15)), math.rad(math.random(0, 360)), math.rad(math.random(-15, 15)))
                                spike.Material = Enum.Material.Slate
                                spike.Color = Color3.fromRGB(25, 8, 8)
                                spike.CanCollide = false
                                spike.Anchored = true
                                spike.Parent = Workspace

                                local spikeHighlight = Instance.new("Highlight", spike)
                                spikeHighlight.FillColor = Color3.fromRGB(180, 0, 0)
                                spikeHighlight.OutlineColor = Color3.fromRGB(255, 60, 60)
                                spikeHighlight.FillTransparency = 0.75

                                local firePillar = Instance.new("ParticleEmitter")
                                firePillar.Color = ColorSequence.new({
                                    ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 40, 20)),
                                    ColorSequenceKeypoint.new(0.5, Color3.fromRGB(180, 10, 10)),
                                    ColorSequenceKeypoint.new(1, Color3.fromRGB(20, 0, 0))
                                })
                                firePillar.Size = NumberSequence.new({
                                    NumberSequenceKeypoint.new(0, 3),
                                    NumberSequenceKeypoint.new(1, 7)
                                })
                                firePillar.Speed = NumberRange.new(50, 85)
                                firePillar.EmissionDirection = Enum.NormalId.Top
                                firePillar.Lifetime = NumberRange.new(0.6, 0.9)
                                firePillar.Rate = 120
                                firePillar.LightEmission = 1
                                firePillar.Parent = spike

                                local skyAtt = Instance.new("Attachment", Workspace.Terrain)
                                skyAtt.WorldPosition = pos + Vector3.new(math.random(-10, 10), 140, math.random(-10, 10))
                                local groundAtt = Instance.new("Attachment", spike)
                                groundAtt.Position = Vector3.new(0, 12, 0)

                                local bolt = Instance.new("Beam")
                                bolt.Attachment0 = skyAtt
                                bolt.Attachment1 = groundAtt
                                bolt.Color = ColorSequence.new(Color3.fromRGB(255, 60, 60))
                                bolt.Width0 = 1.8
                                bolt.Width1 = 0.6
                                bolt.Segments = 14
                                bolt.TextureSpeed = 4.0
                                bolt.LightEmission = 1
                                bolt.Parent = spike

                                spawnSonicBoomRing(pos, Vector3.new(0, 1, 0), Color3.fromRGB(255, 20, 20))

                                task.delay(0.75, function()
                                    TweenService:Create(spike, TweenInfo.new(0.3), { Transparency = 1 }):Play()
                                    task.delay(0.3, function()
                                        spike:Destroy()
                                        skyAtt:Destroy()
                                    end)
                                end)
                            end

                            playSound(SFX.SonicBoom, 0.85, 2.4)
                            cameraImpulse(0.18)

                                                                        
                            if myHrp.Position.Y < (pPos.Y + 24) then
                                damagePlayer(338, "Abyssal Cataclysm")
                            end

                                                                       
                            isBossRecovering = true
                            task.wait(1.4)
                            isBossRecovering = false

                            task.wait(exePhase == 2 and 0.55 or 1.0)
                            exeAttackCooldown = false
                        end)

                                                                                   
                                                                         
                                                                                   
                    elseif chosenAttack == "AbyssalVortex" then
                        setSonicExeAction("SpinDash", 1.8)
                        if showBossAttackWarning then
                            showBossAttackWarning("Abyssal Vortex (+30% PULL)", "Hold C & Thrust Away")
                        end
                        task.spawn(function()
                            playSound(SFX.MachWhoosh, 0.7, 2.4)
                            cameraImpulse(0.10)

                            local startTime = tick()
                            while (tick() - startTime) < 1.4 and inBrokenReality and sonicExeModel and not isPlayerDefeated and not isBossStaggered do
                                local pullDir = (exeHrp.Position - myHrp.Position).Unit
                                myHrp.AssemblyLinearVelocity = pullDir * 72
                                RunService.Heartbeat:Wait()
                            end

                            if not isBossStaggered then
                                damagePlayer(156, "Abyssal Vortex")
                            end

                                                                       
                            isBossRecovering = true
                            task.wait(1.2)
                            isBossRecovering = false

                            task.wait(exePhase == 2 and 0.4 or 0.8)
                            exeAttackCooldown = false
                        end)

                                                                                   
                                                                                          
                                                                                   
                    elseif chosenAttack == "VoidSingularity" then
                        setSonicExeAction("Attack", 1.5)
                        if showBossAttackWarning then
                            showBossAttackWarning("Void Singularity (+30% BLAST)", "Counter with Chaos Spears: E")
                        end
                        task.spawn(function()
                            playSound(SFX.EnergyCharge, 1.1, 2.2)
                            task.wait(0.7)

                            playSound(SFX.ChaosBlast, 1.1, 2.6)
                            cameraImpulse(0.16)

                            local blast = Instance.new("Part")
                            blast.Name = "VoidSingularityCore"
                            blast.Shape = Enum.PartType.Ball
                            blast.Size = Vector3.new(5.8, 5.8, 5.8)
                            blast.Material = Enum.Material.Glass
                            blast.Color = Color3.fromRGB(5, 0, 5)
                            blast.CanCollide = false
                            blast.CFrame = exeHrp.CFrame * CFrame.new(0, 0, -4.5)
                            blast.Parent = Workspace

                            local blastHl = Instance.new("Highlight", blast)
                            blastHl.FillColor = Color3.fromRGB(0, 0, 0)
                            blastHl.OutlineColor = Color3.fromRGB(255, 30, 30)
                            blastHl.OutlineTransparency = 0

                            local plasma = Instance.new("ParticleEmitter")
                            plasma.Color = ColorSequence.new({
                                ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 40, 40)),
                                ColorSequenceKeypoint.new(0.5, Color3.fromRGB(160, 10, 10)),
                                ColorSequenceKeypoint.new(1, Color3.fromRGB(10, 0, 0))
                            })
                            plasma.Size = NumberSequence.new({
                                NumberSequenceKeypoint.new(0, 2.8),
                                NumberSequenceKeypoint.new(1, 0.4)
                            })
                            plasma.Speed = NumberRange.new(10, 20)
                            plasma.Rate = 95
                            plasma.LightEmission = 1
                            plasma.Parent = blast

                            local blastVel = Instance.new("BodyVelocity")
                            blastVel.MaxForce = Vector3.new(1e7, 1e7, 1e7)
                            local blastDir = (myHrp.Position - exeHrp.Position).Unit
                            blastVel.Velocity = blastDir * 254
                            blastVel.Parent = blast

                            spawnSonicBoomRing(blast.Position, blastDir, Color3.fromRGB(255, 20, 20))

                            task.delay(0.25, function()
                                damagePlayer(390, "Void Singularity")
                            end)

                            task.delay(0.85, function()
                                if blast and blast.Parent then
                                    for _ = 1, 12 do
                                        local shard = Instance.new("Part")
                                        shard.Size = Vector3.new(0.45, 0.45, 3.6)
                                        shard.Material = Enum.Material.Neon
                                        shard.Color = Color3.fromRGB(255, 30, 30)
                                        shard.CanCollide = false
                                        shard.CFrame = blast.CFrame * CFrame.Angles(math.rad(math.random(0, 360)), math.rad(math.random(0, 360)), 0)
                                        shard.Parent = Workspace
                                        local sv = Instance.new("BodyVelocity", shard)
                                        sv.MaxForce = Vector3.new(1e6, 1e6, 1e6)
                                        sv.Velocity = (shard.CFrame.LookVector * 165)
                                        task.delay(0.35, function() shard:Destroy() end)
                                    end
                                    blast:Destroy()
                                end
                            end)

                                                                       
                            isBossRecovering = true
                            task.wait(1.4)
                            isBossRecovering = false

                            task.wait(exePhase == 2 and 0.5 or 1.0)
                            exeAttackCooldown = false
                        end)
                    end
                end
            end
        end)
    table.insert(scriptConnections, exeAiLoopConn)
end

                                                                              
enterBrokenReality = function()
    if inBrokenReality or isEnteringBreach then return end

                                                   
    local cdRemain = getDimensionCooldownRemaining()
    if cdRemain > 0 then
        isEnteringBreach = false
        local mins = math.floor(cdRemain / 60)
        local secs = math.floor(cdRemain % 60)
        notify("Super Sonic", string.format("Dimension on cooldown: %dm %02ds left.", mins, secs), 3)
        return
    end

    isEnteringBreach = true

                                                                                             
    if stopFlightBoost then
        stopFlightBoost()
    else
        isHoldingC = false
        isFlying = false
        maxSpeedHoldTime = 0
        if flightBodyVel then flightBodyVel:Destroy(); flightBodyVel = nil end
        if flightBodyGyro then flightBodyGyro:Destroy(); flightBodyGyro = nil end
        if activeFlightTrack then activeFlightTrack:Stop(0.2) end
        if windSound then windSound:Stop() end
    end

    inBrokenReality = true
    exePhase = 1
    initSonicExeDummies()

    hideBoostUI()

                                                   
    screenGui.Enabled = true

                                                                                     
    blackoutFrame.Visible = true
    blackoutFrame.BackgroundTransparency = 0
    exeJumpscareFace.Visible = true
    exeDialogueLabel.Visible = true

    playSound(SFX.ExeLaugh, 0.65, 3.5)
    playSound(SFX.ExeScream, 0.78, 2.5)
    playSound(SFX.TimeCollapse, 0.9, 2.2)
    cameraImpulse(0.25)

                                                                                                                     
    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hrp and hum then
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
        for _, child in ipairs(hrp:GetChildren()) do
            if child:IsA("BodyVelocity") or child:IsA("BodyGyro") or child:IsA("BodyPosition") or child:IsA("LinearVelocity") or child:IsA("AlignPosition") then
                child:Destroy()
            end
        end

        local spawnCF = CFrame.lookAt(Vector3.new(8, 8.0, -1), Vector3.new(8, 8.0, 32))
        hrp.CFrame = spawnCF

                                                                                                              
        local freezePos = Instance.new("BodyPosition")
        freezePos.Name = "BreachFreezePos"
        freezePos.MaxForce = Vector3.new(1e9, 1e9, 1e9)
        freezePos.P = 50000
        freezePos.D = 1200
        freezePos.Position = spawnCF.Position
        freezePos.Parent = hrp

        local freezeGyro = Instance.new("BodyGyro")
        freezeGyro.Name = "BreachFreezeGyro"
        freezeGyro.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
        freezeGyro.P = 50000
        freezeGyro.D = 1200
        freezeGyro.CFrame = spawnCF
        freezeGyro.Parent = hrp

        pcall(function()
            local animScript = char:FindFirstChild("Animate")
            if animScript then
                animScript.Enabled = false
            end

            hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, false)
            hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
            hum:SetStateEnabled(Enum.HumanoidStateType.GettingUp, false)
            hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)

                                                       
            local animator = hum:FindFirstChildOfClass("Animator")
            if animator then
                for _, tr in ipairs(animator:GetPlayingAnimationTracks()) do
                    local tName = tr.Name:lower()
                    local tId = tr.Animation and tr.Animation.AnimationId or ""
                    if tName:find("fall") or tName:find("jump") or tId:find("138697500647123") or tId:find("98786488575258") then
                        tr:Stop(0)
                    end
                end
            end

                                                                     
            local idleTrack = playSonicEmoteTrack(hum, SONIC_ANIMS.Idle, true)
            if idleTrack then
                idleTrack:Play(0.1)
                idleTrack.Priority = Enum.AnimationPriority.Action4
            end
        end)
    end

                                                                                  
    local exeSpawnPos = Vector3.new(8, 8.0, 32)
    spawnSonicExe(exeSpawnPos)
    startExeCombatAI()

                                                                                  
    task.wait(2.2)

                                                   
    if hrp and hum then
        local fp = hrp:FindFirstChild("BreachFreezePos")
        if fp then fp:Destroy() end
        local fg = hrp:FindFirstChild("BreachFreezeGyro")
        if fg then fg:Destroy() end
        enableSuperSonicLevitation(hrp, hum)
    end
    isEnteringBreach = false

                                                     
    flashFrame.Visible = true
    flashFrame.BackgroundTransparency = 0
    blackoutFrame.Visible = false
    exeJumpscareFace.Visible = false
    exeDialogueLabel.Visible = false

    TweenService:Create(flashFrame, TweenInfo.new(0.65, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
        BackgroundTransparency = 1
    }):Play()

                                                                                            
    applyHorrorLighting()

    if not dimensionColorCorrection then
        dimensionColorCorrection = Instance.new("ColorCorrectionEffect")
        dimensionColorCorrection.Name = "SuperSonic_DimensionCC"
        dimensionColorCorrection.Saturation = -1.0                         
        dimensionColorCorrection.Contrast = 0.35
        dimensionColorCorrection.TintColor = Color3.fromRGB(225, 225, 225)
        dimensionColorCorrection.Parent = Lighting
        _G.SuperSonic_DimensionCC = dimensionColorCorrection
    end

                                                          
    bossBarFrame.Visible = true
    updateBossHpUI(CONFIG.EXE_MAX_HP, CONFIG.EXE_MAX_HP, false)
    playerHp = CONFIG.PLAYER_MAX_HP
    isPlayerDefeated = false
    isExeLockedOn = false
    playerBarFrame.Visible = true
    updatePlayerHpUI(playerHp, CONFIG.PLAYER_MAX_HP)
    setHudBadgesMode(true)

                          
    local bAudio = getOrCreateBrokenAudio(hrp)
    bAudio.Volume = 1.4
    bAudio:Play()

    if windSound then
        windSound:Stop()
    end

    updateVignetteEffect(1, true)
    setAuraFlightIntensity(true, 1, true)
    spawnSkyDimensionalRift()
    notify("Super Sonic", "Defeat Sonic.exe or reach the Dimensional Rift in the sky!", 4)
end

exitBrokenReality = function()
    if not inBrokenReality then return end
    inBrokenReality = false
    isEnteringBreach = false
    exePhase = 1

    cleanSonicExeDummies()

                                               
    destroySkyDimensionalRift()

                                                                                 
    _G.SonicExe_CooldownTimestamp = tick()
    _G.SonicExe_DefeatedTimestamp = tick()
    notify("Super Sonic", "Returned. Cooldown: 15m.", 4)

    local char = lp.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    disableSuperSonicLevitation(hum)

    if exeAiLoopConn then
        exeAiLoopConn:Disconnect()
        exeAiLoopConn = nil
    end

    if sonicExeModel then
        sonicExeModel:Destroy()
        sonicExeModel = nil
        _G.SuperSonic_ExeModel = nil
    end

    bossBarFrame.Visible = false
    playerBarFrame.Visible = false
    isExeLockedOn = false
    if lockBillboard and lockBillboard.Adornee == (sonicExeModel and sonicExeModel:FindFirstChild("HumanoidRootPart")) then
        lockBillboard.Enabled = false
        lockBillboard.Adornee = nil
    end
    setHudBadgesMode(false)
    restoreHiddenPlayers()
    restoreHorrorLighting()

    if dimensionColorCorrection then
        local tw = TweenService:Create(dimensionColorCorrection, TweenInfo.new(0.7), {
            Saturation = 0,
            Contrast = 0,
            TintColor = Color3.fromRGB(255, 255, 255)
        })
        tw:Play()
        tw.Completed:Connect(function()
            if dimensionColorCorrection then
                dimensionColorCorrection:Destroy()
                dimensionColorCorrection = nil
                _G.SuperSonic_DimensionCC = nil
            end
        end)
    end

    if brokenRealityAudio then
        local aTw = TweenService:Create(brokenRealityAudio, TweenInfo.new(0.5), { Volume = 0 })
        aTw:Play()
        aTw.Completed:Connect(function()
            if brokenRealityAudio then brokenRealityAudio:Stop() end
        end)
    end

    updateVignetteEffect(0, false)
    setAuraFlightIntensity(false, 0, false)
end

                                                               
                                         
                                                               
local combatCooldown = false

                                           
toggleExeLockOn = function()
    if not inBrokenReality or not sonicExeModel then return end
    isExeLockedOn = not isExeLockedOn

    local exeHrp = sonicExeModel:FindFirstChild("HumanoidRootPart")
    if isExeLockedOn and exeHrp then
        playSound(SFX.LockPing, 1.6, 2.0)
        lockBillboard.Adornee = exeHrp
        lockBillboard.Enabled = true
        animateLockSnap()
        notify("Super Sonic", "Locked On [Sonic.exe]", 2)
    else
        lockBillboard.Enabled = false
        lockBillboard.Adornee = nil
        notify("Super Sonic", "Unlocked", 1.5)
    end
end

                                          
triggerChaosStrike = function()
    if not inBrokenReality or not sonicExeModel or not canUseSkill("M1") or isHomingAttacking then return end
    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local exeHrp = sonicExeModel:FindFirstChild("HumanoidRootPart")
    if not hrp or not exeHrp then return end

    triggerSkillCooldown("M1")

    local dist = (exeHrp.Position - hrp.Position).Magnitude
    if dist > 44 and not isExeLockedOn then
                                                           
        local cam = Workspace.CurrentCamera
        local dashDir = (cam and cam.CFrame.LookVector or hrp.CFrame.LookVector)
        dashDir = Vector3.new(dashDir.X, 0, dashDir.Z).Unit
        if dashDir.Magnitude < 0.1 then dashDir = hrp.CFrame.LookVector end

        playSound(SFX.Teleport, 1.5, 2.0)
        playSound(SFX.SonicBoom, 1.4, 1.8)
        spawnSonicBoomRing(hrp.Position, dashDir, Color3.fromRGB(255, 235, 70))
        cameraImpulse(0.04)

        local targetPos = hrp.Position + (dashDir * 35)
        hrp.CFrame = CFrame.lookAt(targetPos, targetPos + dashDir)

                                                                         
        dist = (exeHrp.Position - hrp.Position).Magnitude
        if dist > 44 then return end
    end

                          
    task.spawn(function()
        if dist > 44 then
            playSound(SFX.Teleport, 1.4, 2.2)
            spawnSonicBoomRing(hrp.Position, hrp.CFrame.LookVector, Color3.fromRGB(255, 235, 70))
        end
        hrp.CFrame = CFrame.lookAt(exeHrp.Position - (exeHrp.CFrame.LookVector * 4.5), exeHrp.Position)

        for i = 1, 4 do
            if not sonicExeModel or sonicExeHp <= 0 then break end
            playSound(SFX.HitSlash, 1.2 + (i * 0.08), 1.9)
            cameraImpulse(0.04)

            local sideOffset = (i % 2 == 0) and Vector3.new(1.2, 0, 0) or Vector3.new(-1.2, 0, 0)
            spawnSonicBoomRing(exeHrp.Position + sideOffset, hrp.CFrame.LookVector, Color3.fromRGB(255, 230, 70))
            damageSonicExe(75, "M1")

            task.wait(0.08)
        end
    end)
end

                                                   
triggerLightSpeedBlink = function()
    if not inBrokenReality or not sonicExeModel or not canUseSkill("Q") then return end
    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local exeHrp = sonicExeModel:FindFirstChild("HumanoidRootPart")
    if not hrp or not exeHrp then return end

    triggerSkillCooldown("Q")

    task.spawn(function()
        playSound(SFX.Teleport, 1.4, 2.2)
        spawnSonicBoomRing(hrp.Position, hrp.CFrame.LookVector, Color3.fromRGB(255, 245, 100))

        local abovePos = exeHrp.Position + Vector3.new(0, 14, 0)
        hrp.CFrame = CFrame.lookAt(abovePos, exeHrp.Position)
        cameraImpulse(0.06)

        task.wait(0.12)

        playSound(SFX.SonicBoom, 1.3, 2.2)
        local kickBeam = Instance.new("Part")
        kickBeam.Size = Vector3.new(0.8, 14, 0.8)
        kickBeam.Material = Enum.Material.Neon
        kickBeam.Color = Color3.fromRGB(255, 235, 70)
        kickBeam.CanCollide = false
        kickBeam.CastShadow = false
        kickBeam.CFrame = CFrame.new((abovePos + exeHrp.Position) * 0.5)
        kickBeam.Parent = Workspace

        TweenService:Create(kickBeam, TweenInfo.new(0.2), { Transparency = 1 }):Play()
        task.delay(0.2, function() kickBeam:Destroy() end)

        hrp.CFrame = CFrame.lookAt(exeHrp.Position + (hrp.CFrame.LookVector * 3), exeHrp.Position)
        spawnSonicBoomRing(exeHrp.Position, Vector3.new(0, -1, 0), Color3.fromRGB(255, 255, 255))
        damageSonicExe(380, "Dropkick")
    end)
end

                                               
triggerChaosSpears = function()
    if not inBrokenReality or not sonicExeModel or not canUseSkill("E") then return end
    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local exeHrp = sonicExeModel:FindFirstChild("HumanoidRootPart")
    if not hrp or not exeHrp then return end

    triggerSkillCooldown("E")

    task.spawn(function()
        playSound(SFX.BoostStart, 1.5, 2.0)
        cameraImpulse(0.04)

        for i = 1, 6 do
            task.spawn(function()
                local spear = Instance.new("Part")
                spear.Size = Vector3.new(0.5, 0.5, 3.4)
                spear.Material = Enum.Material.Neon
                spear.Color = Color3.fromRGB(255, 235, 70)
                spear.CanCollide = false
                spear.CastShadow = false

                local angle = (i / 6) * math.pi * 2
                local radius = 3.5
                local offset = Vector3.new(math.cos(angle) * radius, 1.5 + math.sin(angle) * 1.5, 0)
                spear.CFrame = hrp.CFrame * CFrame.new(offset)
                spear.Parent = Workspace

                local tw = TweenService:Create(spear, TweenInfo.new(0.26, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
                    CFrame = CFrame.lookAt(exeHrp.Position, exeHrp.Position + hrp.CFrame.LookVector)
                })
                tw:Play()
                tw.Completed:Connect(function()
                    spawnSonicBoomRing(spear.Position, spear.CFrame.LookVector, Color3.fromRGB(255, 220, 60))
                    spear:Destroy()
                    damageSonicExe(75, "Spear")
                end)
            end)
            task.wait(0.06)
        end
    end)
end

                                      
triggerChaosBlast = function()
    if not inBrokenReality or not sonicExeModel or not canUseSkill("F") then return end
    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local exeHrp = sonicExeModel:FindFirstChild("HumanoidRootPart")
    if not hrp or not exeHrp then return end

    triggerSkillCooldown("F")

    task.spawn(function()
        playSound(SFX.EnergyCharge, 1.0, 2.5)
        cameraImpulse(0.05)

        local chargeSphere = Instance.new("Part")
        chargeSphere.Name = "ChaosBlastCharge"
        chargeSphere.Shape = Enum.PartType.Ball
        chargeSphere.Size = Vector3.new(2, 2, 2)
        chargeSphere.Material = Enum.Material.Neon
        chargeSphere.Color = Color3.fromRGB(255, 230, 60)
        chargeSphere.Transparency = 0.35
        chargeSphere.CanCollide = false
        chargeSphere.CastShadow = false
        chargeSphere.CFrame = hrp.CFrame
        chargeSphere.Parent = Workspace

        local chargeLight = Instance.new("PointLight")
        chargeLight.Color = Color3.fromRGB(255, 220, 50)
        chargeLight.Range = 25
        chargeLight.Brightness = 5
        chargeLight.Parent = chargeSphere

        local chargeTween = TweenService:Create(chargeSphere, TweenInfo.new(1.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Size = Vector3.new(16, 16, 16),
            Transparency = 0.1
        })
        chargeTween:Play()

        for _ = 1, 11 do
            cameraImpulse(0.03)
            task.wait(0.1)
        end

        playSound(SFX.ChaosBlast, 0.85, 3.0)
        playSound(SFX.SonicBoom, 0.8, 3.0)
        cameraImpulse(0.35)

        local blastWave = Instance.new("Part")
        blastWave.Name = "ChaosBlastWave"
        blastWave.Shape = Enum.PartType.Ball
        blastWave.Size = Vector3.new(12, 12, 12)
        blastWave.Material = Enum.Material.Neon
        blastWave.Color = Color3.fromRGB(255, 245, 120)
        blastWave.Transparency = 0.1
        blastWave.CanCollide = false
        blastWave.CastShadow = false
        blastWave.CFrame = hrp.CFrame
        blastWave.Parent = Workspace

        chargeSphere:Destroy()

        local blastTween = TweenService:Create(blastWave, TweenInfo.new(0.55, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Size = Vector3.new(85, 85, 85),
            Transparency = 1
        })
        blastTween:Play()
        blastTween.Completed:Connect(function()
            blastWave:Destroy()
        end)

        spawnSonicBoomRing(hrp.Position, Vector3.new(0, 1, 0), Color3.fromRGB(255, 255, 255))
        spawnSonicBoomRing(hrp.Position, Vector3.new(1, 0, 0), Color3.fromRGB(255, 220, 50))

        local distToBoss = (exeHrp.Position - hrp.Position).Magnitude
        if distToBoss <= 95 then
            damageSonicExe(850, "Blast")
            local exeBv = exeHrp:FindFirstChild("ExeHoverVel")
            if exeBv then
                local knockDir = (exeHrp.Position - hrp.Position).Unit + Vector3.new(0, 0.6, 0)
                exeBv.Velocity = knockDir.Unit * 180
                task.delay(0.4, function()
                    if exeBv and exeBv.Parent then exeBv.Velocity = Vector3.zero end
                end)
            end
        end
    end)
end

                                                               
                                             
                                                               
isToolEquipped = false
isHoldingC = false
isFlying = false
currentFlightSpeed = CONFIG.FLIGHT_MIN_SPEED
activeFlightTrack = nil
flightBodyVel = nil
flightBodyGyro = nil
lastBoomSpeed = 0
maxSpeedHoldTime = 0
lastRiftSealedNotice = 0

                                                                             
local function getGroundAltitudeOffset(hrp, char)
    local rayParams = RaycastParams.new()
    rayParams.FilterDescendantsInstances = { char }
    rayParams.FilterType = Enum.RaycastFilterType.Exclude

    local groundHit = Workspace:Raycast(hrp.Position, Vector3.new(0, -60, 0), rayParams)
    if groundHit then
        local currentElevation = (hrp.Position.Y - groundHit.Position.Y)
        local diff = CONFIG.DEFAULT_HOVER_HEIGHT - currentElevation
        if diff > 0 then
            return math.clamp(diff * 4.2, 0, 45)
        end
    end
    return 0
end

startFlightBoost = function()
    if not isToolEquipped and not inBrokenReality then return end
    if isHoldingC then return end
    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hrp or not hum or hum.Health <= 0 then return end

    isHoldingC = true
    isFlying = true
    currentFlightSpeed = inBrokenReality and CONFIG.BROKEN_REALITY_SPEED or CONFIG.FLIGHT_MIN_SPEED
    lastBoomSpeed = currentFlightSpeed
    maxSpeedHoldTime = 0

    hum.PlatformStand = true

    if inBrokenReality then
        if brokenHoverPos then
            brokenHoverPos.MaxForce = Vector3.zero
        end
        if brokenHoverGyro then
            brokenHoverGyro.MaxTorque = Vector3.zero
        end
        local wLoop = getOrCreateWindSound(hrp)
        wLoop.Volume = 0.8
        wLoop.PlaybackSpeed = 1.2
        wLoop:Play()
    else
        local rayParams = RaycastParams.new()
        rayParams.FilterDescendantsInstances = { char }
        rayParams.FilterType = Enum.RaycastFilterType.Exclude
        local groundCheck = Workspace:Raycast(hrp.Position, Vector3.new(0, -15, 0), rayParams)
        if groundCheck then
            local targetY = groundCheck.Position.Y + CONFIG.DEFAULT_HOVER_HEIGHT
            if hrp.Position.Y < targetY then
                hrp.CFrame = CFrame.new(hrp.Position.X, targetY, hrp.Position.Z) * hrp.CFrame.Rotation
            end
        end

        local wLoop = getOrCreateWindSound(hrp)
        wLoop.Volume = 0.6
        wLoop.PlaybackSpeed = 1.0
        wLoop:Play()
    end

    if not activeFlightTrack then
        activeFlightTrack = playSonicEmoteTrack(hum, SONIC_ANIMS.Run, true)
    end
    if activeFlightTrack then
        activeFlightTrack:Play(0.15)
    end

    if not flightBodyVel then
        flightBodyVel = Instance.new("BodyVelocity")
        flightBodyVel.Name = "SonicFlightVel"
        flightBodyVel.MaxForce = Vector3.new(1e7, 1e7, 1e7)
        flightBodyVel.Parent = hrp
    end

    if not flightBodyGyro then
        flightBodyGyro = Instance.new("BodyGyro")
        flightBodyGyro.Name = "SonicFlightGyro"
        flightBodyGyro.MaxTorque = Vector3.new(1e7, 1e7, 1e7)
        flightBodyGyro.P = 22000
        flightBodyGyro.D = 350
        flightBodyGyro.Parent = hrp
    end

    playSound(SFX.BoostStart, 1.15, 1.8)
    cameraImpulse(0.05)
    spawnSonicBoomRing(hrp.Position, camera and camera.CFrame.LookVector or hrp.CFrame.LookVector)
end

stopFlightBoost = function()
    isHoldingC = false
    isFlying = false
    maxSpeedHoldTime = 0

    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")

    if flightBodyVel then
        flightBodyVel:Destroy()
        flightBodyVel = nil
    end

    if flightBodyGyro then
        flightBodyGyro:Destroy()
        flightBodyGyro = nil
    end

    if activeFlightTrack then
        activeFlightTrack:Stop(0.25)
    end

    if inBrokenReality and hrp then
        if brokenHoverPos then
            brokenHoverPos.Position = hrp.Position
            brokenHoverPos.MaxForce = Vector3.new(1e9, 1e9, 1e9)
        end
        if brokenHoverGyro then
            brokenHoverGyro.CFrame = hrp.CFrame
            brokenHoverGyro.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
        end
        if hum then
            playSonicEmoteTrack(hum, SONIC_ANIMS.Idle, true)
        end
    end

    if hum then
        hum.PlatformStand = false
        hum.WalkSpeed = CONFIG.BASE_WALKSPEED
    end

    if windSound then
        local tw = TweenService:Create(windSound, TweenInfo.new(0.3), { Volume = 0 })
        tw:Play()
        tw.Completed:Connect(function()
            if not isFlying and windSound then windSound:Stop() end
        end)
    end

    if camera then
        TweenService:Create(camera, TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            FieldOfView = CONFIG.NORMAL_FOV
        }):Play()
    end

    hideBoostUI()
    if not inBrokenReality then
        updateVignetteEffect(0, false)
        setAuraFlightIntensity(false, 0, false)
    end
end

                                                               
                                                                     
                                                               
isHomingAttacking = false
local homingCooldown = false

triggerHomingAttack = function()
    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hrp or not hum or hum.Health <= 0 then return end

                                                          
    if inBrokenReality and sonicExeModel and sonicExeHp > 0 then
        local exeHrp = sonicExeModel:FindFirstChild("HumanoidRootPart")
        if not exeHrp or not canUseSkill("R") or isHomingAttacking then return end

        triggerSkillCooldown("R")
        isHomingAttacking = true

        local spinTrack = playSonicEmoteTrack(hum, SONIC_ANIMS.SpinDash, true)
        if spinTrack then spinTrack:Play(0.08) spinTrack:AdjustSpeed(2.4) end

        playSound(SFX.BoostStart, 1.45, 2.2)
        cameraImpulse(0.04)

        task.spawn(function()
            local homingVel = Instance.new("BodyVelocity")
            homingVel.Name = "SonicHomingVel"
            homingVel.MaxForce = Vector3.new(1e7, 1e7, 1e7)
            homingVel.Parent = hrp

            local startDist = (exeHrp.Position - hrp.Position).Magnitude
            local maxDuration = math.clamp((startDist / CONFIG.HOMING_ATTACK_SPEED) + 0.65, 1.2, 4.5)
            local startTime = tick()
            while (tick() - startTime) < maxDuration and sonicExeModel do
                local toExe = exeHrp.Position - hrp.Position
                if toExe.Magnitude <= 9 then break end
                homingVel.Velocity = toExe.Unit * CONFIG.HOMING_ATTACK_SPEED
                hrp.CFrame = CFrame.lookAt(hrp.Position, exeHrp.Position)
                RunService.Heartbeat:Wait()
            end

            damageSonicExe(420, "Homing")
            homingVel.Velocity = Vector3.new(0, 95, 0) - (hrp.CFrame.LookVector * 30)
            task.wait(0.24)

            if homingVel and homingVel.Parent then homingVel:Destroy() end
            if spinTrack then spinTrack:Stop(0.2) end

            isHomingAttacking = false
            task.wait(0.5)
            homingCooldown = false
        end)
        return
    end

                                                
    if not currentLockedTarget or not currentLockedTarget.Primary or not currentLockedTarget.Primary.Parent then
        return
    end

    if not isToolEquipped or isHomingAttacking or homingCooldown then return end
    local target = currentLockedTarget

    isHomingAttacking = true
    homingCooldown = true

    if isFlying and flightBodyVel then
        flightBodyVel.Velocity = Vector3.zero
    end

    local spinTrack = playSonicEmoteTrack(hum, SONIC_ANIMS.SpinDash, true)
    if spinTrack then
        spinTrack:Play(0.08)
        spinTrack:AdjustSpeed(2.4)
    end

    playSound(SFX.BoostStart, 1.45, 2.2)
    cameraImpulse(0.04)

    task.spawn(function()
        local homingVel = Instance.new("BodyVelocity")
        homingVel.Name = "SonicHomingVel"
        homingVel.MaxForce = Vector3.new(1e7, 1e7, 1e7)
        homingVel.Velocity = Vector3.new(0, 18, 0)
        homingVel.Parent = hrp

        task.wait(0.08)

        local startTime = tick()
        local targetHit = false
        local homingSpeed = CONFIG.HOMING_ATTACK_SPEED

        while (tick() - startTime) < 1.1 and isToolEquipped and target.Primary and target.Primary.Parent do
            local toTarget = target.Primary.Position - hrp.Position
            local dist = toTarget.Magnitude
            if dist <= 9.0 then
                targetHit = true
                break
            end
            local dir = toTarget.Unit
            homingVel.Velocity = dir * homingSpeed
            hrp.CFrame = CFrame.lookAt(hrp.Position, target.Primary.Position)
            RunService.Heartbeat:Wait()
        end

        if targetHit and target.Primary and target.Primary.Parent then
            enableClientSimulationMax()
            local blastDir = (target.Primary.Position - hrp.Position).Unit + Vector3.new(0, 0.45, 0)
            local blastVel = (blastDir * 440) + Vector3.new(0, 140, 0)

            pcall(function()
                target.Primary.AssemblyLinearVelocity = blastVel

                local bv = Instance.new("BodyVelocity")
                bv.Name = "SonicHomingCarBlast"
                bv.MaxForce = Vector3.new(1e8, 1e8, 1e8)
                bv.Velocity = blastVel
                bv.Parent = target.Primary

                local bav = Instance.new("BodyAngularVelocity")
                bav.Name = "SonicHomingCarSpin"
                bav.MaxTorque = Vector3.new(1e8, 1e8, 1e8)
                bav.AngularVelocity = Vector3.new(math.random(-280, 280), 380, math.random(-280, 280))
                bav.Parent = target.Primary

                task.delay(0.45, function()
                    if bv and bv.Parent then bv:Destroy() end
                    if bav and bav.Parent then bav:Destroy() end
                end)
            end)

            playSound(SFX.CarImpact, 1.15, 2.5)
            cameraImpulse(0.16)
            spawnSonicBoomRing(target.Primary.Position, blastDir)

            homingVel.Velocity = Vector3.new(0, 95, 0) - (hrp.CFrame.LookVector * 32)
            task.wait(0.24)
        end

        if homingVel and homingVel.Parent then homingVel:Destroy() end

        if spinTrack then spinTrack:Stop(0.2) end

        isHomingAttacking = false

        task.wait(0.35)
        homingCooldown = false
    end)
end

                                                               
                                                      
                                                               
