local hbConn = RunService.Heartbeat:Connect(function(dt)
    if not isToolEquipped and not inBrokenReality then return end

    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hrp or not hum or hum.Health <= 0 then
        if isFlying and stopFlightBoost then stopFlightBoost() end
        if inBrokenReality and exitBrokenReality then exitBrokenReality() end
        return
    end

                                                                                             
    if inBrokenReality then
        hideAllOtherPlayers()
        pcall(function()
            local animScript = char:FindFirstChild("Animate")
            if animScript and animScript.Enabled then
                animScript.Enabled = false
            end
            hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, false)
            hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
            hum:SetStateEnabled(Enum.HumanoidStateType.GettingUp, false)

            local animator = hum:FindFirstChildOfClass("Animator")
            if animator then
                for _, tr in ipairs(animator:GetPlayingAnimationTracks()) do
                    local tName = tr.Name:lower()
                    local tId = tr.Animation and tr.Animation.AnimationId or ""
                    if tName:find("fall") or tName:find("jump") or tId:find("138697500647123") or tId:find("98786488575258") then
                        tr:Stop(0)
                    end
                end
            end
        end)

        if brokenHoverPos and hrp and not isFlying then
            pcall(function()
                local animScript = char:FindFirstChild("Animate")
                if animScript and animScript.Enabled then
                    animScript.Enabled = false
                end
            end)

            local rayParams = RaycastParams.new()
            rayParams.FilterDescendantsInstances = { char, sonicExeModel }
            rayParams.FilterType = Enum.RaycastFilterType.Exclude

            local groundRay = Workspace:Raycast(hrp.Position, Vector3.new(0, -400, 0), rayParams)
            local groundY = (groundRay and groundRay.Position.Y) or 4.0
            local targetHoverY = groundY + 7.5

            local cam = Workspace.CurrentCamera
            local camCF = cam and cam.CFrame or hrp.CFrame
            local moveDir = Vector3.zero

            if UserInputService:IsKeyDown(Enum.KeyCode.W) then
                moveDir = moveDir + camCF.LookVector
            end
            if UserInputService:IsKeyDown(Enum.KeyCode.S) then
                moveDir = moveDir - camCF.LookVector
            end
            if UserInputService:IsKeyDown(Enum.KeyCode.D) then
                moveDir = moveDir + camCF.RightVector
            end
            if UserInputService:IsKeyDown(Enum.KeyCode.A) then
                moveDir = moveDir - camCF.RightVector
            end

            local vertOffset = 0
            if UserInputService:IsKeyDown(Enum.KeyCode.Space) then
                vertOffset = 55 * dt
            elseif UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then
                vertOffset = -55 * dt
            end

            local horizDir = Vector3.new(moveDir.X, 0, moveDir.Z)
            if horizDir.Magnitude > 0.05 then
                horizDir = horizDir.Unit
            end

            local levitationSpeed = 135
            local curPos = brokenHoverPos.Position
            local nextX = curPos.X + (horizDir.X * levitationSpeed * dt)
            local nextZ = curPos.Z + (horizDir.Z * levitationSpeed * dt)
            local nextY = curPos.Y + vertOffset

            if vertOffset == 0 and curPos.Y < targetHoverY then
                nextY = curPos.Y + ((targetHoverY - curPos.Y) * math.clamp(dt * 7, 0, 1))
            end
            nextY = math.max(groundY + 3.0, nextY)

            brokenHoverPos.Position = Vector3.new(nextX, nextY, nextZ)

            if brokenHoverGyro then
                if horizDir.Magnitude > 0.05 then
                    brokenHoverGyro.CFrame = CFrame.lookAt(hrp.Position, hrp.Position + horizDir)
                elseif isExeLockedOn and sonicExeModel and sonicExeModel:FindFirstChild("HumanoidRootPart") then
                    local exePos = sonicExeModel.HumanoidRootPart.Position
                    brokenHoverGyro.CFrame = CFrame.lookAt(hrp.Position, Vector3.new(exePos.X, hrp.Position.Y, exePos.Z))
                elseif cam then
                    local lookFlat = Vector3.new(cam.CFrame.LookVector.X, 0, cam.CFrame.LookVector.Z)
                    if lookFlat.Magnitude > 0.01 then
                        brokenHoverGyro.CFrame = CFrame.lookAt(hrp.Position, hrp.Position + lookFlat.Unit)
                    end
                end
            end

            if isExeLockedOn and sonicExeModel and sonicExeModel:FindFirstChild("HumanoidRootPart") then
                lockBillboard.Adornee = sonicExeModel.HumanoidRootPart
                lockBillboard.Enabled = true
                innerRing.Rotation = (innerRing.Rotation + (260 * dt)) % 360
            else
                lockBillboard.Enabled = false
            end

                                                                  
            for key, card in pairs(hotbarCards) do
                local s = skillCooldowns[key]
                if s then
                    local elapsed = tick() - s.lastUsed
                    if elapsed < s.cd then
                        local remain = s.cd - elapsed
                        card.cdOverlay.Visible = true
                        card.cdLabel.Text = string.format("%.1fs", remain)
                        card.cdLabel.TextColor3 = Color3.fromRGB(255, 120, 120)
                        card.stroke.Color = Color3.fromRGB(90, 80, 70)
                    else
                        card.cdOverlay.Visible = false
                        card.cdLabel.Text = "READY"
                        card.cdLabel.TextColor3 = Color3.fromRGB(255, 235, 90)
                        card.stroke.Color = Color3.fromRGB(255, 215, 0)
                    end
                elseif key == "X" then
                    if isExeLockedOn then
                        card.cdLabel.Text = "LOCKED"
                        card.cdLabel.TextColor3 = Color3.fromRGB(255, 50, 50)
                        card.stroke.Color = Color3.fromRGB(255, 40, 40)
                        card.keyBox.BackgroundColor3 = Color3.fromRGB(60, 15, 15)
                    else
                        card.cdLabel.Text = "FREE CAM"
                        card.cdLabel.TextColor3 = Color3.fromRGB(200, 200, 200)
                        card.stroke.Color = Color3.fromRGB(90, 90, 110)
                        card.keyBox.BackgroundColor3 = Color3.fromRGB(25, 25, 32)
                    end
                end
            end

                                    
            if currentComboHits > 0 and (tick() - lastComboHitTime) > 3.0 then
                currentComboHits = 0
                if comboFrame then comboFrame.Visible = false end
            end
        end
    end

                                                        
    if not isHomingAttacking and not inBrokenReality then
        currentLockedTarget = scanUnoccupiedOwnerVehicles()
        if currentLockedTarget and currentLockedTarget.Primary then
            lockBillboard.Adornee = currentLockedTarget.Primary
            lockBillboard.Enabled = true
            innerRing.Rotation = (innerRing.Rotation + (220 * dt)) % 360

            if not lastTargetFound or lastTargetFound ~= currentLockedTarget.Model then
                lastTargetFound = currentLockedTarget.Model
                playSound(SFX.LockPing, 1.5, 1.4)
                animateLockSnap()
            end

            if rBadge and rBadge.actionText then
                rBadge.actionText.Text = "Homing Attack [LOCKED]"
                rBadge.actionText.TextColor3 = Color3.fromRGB(255, 60, 60)
                rBadge.keyBox.BackgroundColor3 = Color3.fromRGB(48, 20, 20)
                rBadge.stroke.Color = Color3.fromRGB(255, 50, 50)
            end
        else
            lockBillboard.Enabled = false
            lockBillboard.Adornee = nil
            lastTargetFound = nil
            if rBadge and rBadge.actionText then
                rBadge.actionText.Text = "Homing (No Target)"
                rBadge.actionText.TextColor3 = Color3.fromRGB(150, 150, 140)
                rBadge.keyBox.BackgroundColor3 = Color3.fromRGB(24, 24, 18)
                rBadge.stroke.Color = Color3.fromRGB(70, 70, 40)
            end
        end
    else
        lockBillboard.Enabled = false
    end

                                                     
    if isHoldingC and isFlying and not isHomingAttacking then
        local maxSpd = inBrokenReality and CONFIG.BROKEN_REALITY_SPEED or CONFIG.FLIGHT_MAX_SPEED
        currentFlightSpeed = math.clamp(currentFlightSpeed + (CONFIG.ACCELERATION_RATE * dt), CONFIG.FLIGHT_MIN_SPEED, maxSpd)

        local cam = Workspace.CurrentCamera
        local camCF = cam and cam.CFrame or hrp.CFrame
        local lookDir = camCF.LookVector

        local moveDir = lookDir
        if UserInputService:IsKeyDown(Enum.KeyCode.S) then
            moveDir = -lookDir
        end

        local altitudeCorrection = inBrokenReality and 0 or getGroundAltitudeOffset(hrp, char)
        local targetVelocity = (moveDir * currentFlightSpeed) + Vector3.new(0, altitudeCorrection, 0)

        if not inBrokenReality then
            local rayParams = RaycastParams.new()
            rayParams.FilterDescendantsInstances = { char }
            rayParams.FilterType = Enum.RaycastFilterType.Exclude

            local forwardCheck = Workspace:Raycast(hrp.Position, moveDir * 18, rayParams)
            if forwardCheck and forwardCheck.Instance and forwardCheck.Instance.CanCollide then
                local norm = forwardCheck.Normal
                if math.abs(norm.Y) < 0.7 then
                    targetVelocity = targetVelocity - (norm * (targetVelocity:Dot(norm))) + Vector3.new(0, 15, 0)
                end
            end
        end

        if flightBodyVel then
            flightBodyVel.Velocity = targetVelocity
        end

        if flightBodyGyro then
            flightBodyGyro.CFrame = CFrame.lookAt(hrp.Position, hrp.Position + moveDir)
        end

        if inBrokenReality and brokenHoverPos then
            brokenHoverPos.Position = hrp.Position
        end

                                                                        
        local cdRemain = getDimensionCooldownRemaining()
        local overloadRatio = 0

        if currentFlightSpeed >= (CONFIG.FLIGHT_MAX_SPEED * 0.85) and not inBrokenReality then
            if cdRemain > 0 then
                                                                
                maxSpeedHoldTime = 0
                overloadRatio = 0
                if (tick() - lastRiftSealedNotice) >= 6.0 then
                    lastRiftSealedNotice = tick()
                    local mins = math.floor(cdRemain / 60)
                    local secs = math.floor(cdRemain % 60)
                    notify("Super Sonic", string.format("Cooldown: %dm %02ds left.", mins, secs), 3)
                    playSound(SFX.LockPing, 0.85, 1.4)
                end
            else
                maxSpeedHoldTime = maxSpeedHoldTime + dt
                overloadRatio = math.clamp(maxSpeedHoldTime / CONFIG.OVERLOAD_HOLD_REQUIRED, 0, 1)

                cameraImpulse(0.015 + (overloadRatio * 0.05))

                if overloadRatio > 0.40 then
                    updateVignetteEffect(overloadRatio, false)
                end

                if (overloadRatio >= 0.98 or maxSpeedHoldTime >= (CONFIG.OVERLOAD_HOLD_REQUIRED * 0.98)) and not isEnteringBreach then
                    task.spawn(enterBrokenReality)
                end
            end
        else
            maxSpeedHoldTime = math.max(0, maxSpeedHoldTime - (dt * 0.4))
        end

                                                                          
        if cBadge and cBadge.actionText and not inBrokenReality then
            if cdRemain > 0 then
                local mins = math.floor(cdRemain / 60)
                local secs = math.floor(cdRemain % 60)
                cBadge.actionText.Text = string.format("Flight (Cooldown: %dm %02ds)", mins, secs)
                cBadge.actionText.TextColor3 = Color3.fromRGB(255, 140, 140)
            else
                cBadge.actionText.Text = "Flight (Hold at Max to Breach)"
                cBadge.actionText.TextColor3 = Color3.fromRGB(240, 240, 240)
            end
        end

        local speedRatio = math.clamp((currentFlightSpeed - CONFIG.FLIGHT_MIN_SPEED) / (CONFIG.FLIGHT_MAX_SPEED - CONFIG.FLIGHT_MIN_SPEED), 0, 1)

                                      
        if cam then
            local targetFov = inBrokenReality and (CONFIG.MAX_FOV + 8) or (CONFIG.NORMAL_FOV + (speedRatio * (CONFIG.MAX_FOV - CONFIG.NORMAL_FOV)))
            cam.FieldOfView = targetFov
            if speedRatio > 0.45 and not inBrokenReality then
                cameraImpulse(0.015 * speedRatio)
            end
        end

                             
        if windSound and windSound.IsPlaying and not inBrokenReality then
            windSound.Volume = 0.5 + (speedRatio * 1.5)
            windSound.PlaybackSpeed = 0.95 + (speedRatio * 0.75)
        end

                                        
        if currentFlightSpeed - lastBoomSpeed >= 110 then
            lastBoomSpeed = currentFlightSpeed
            playSound(SFX.SonicBoom, 1.1 + (speedRatio * 0.3), 2.0)
            spawnSonicBoomRing(hrp.Position, moveDir, inBrokenReality and Color3.fromRGB(220, 20, 20) or Color3.fromRGB(255, 230, 80))
            cameraImpulse(0.08)
        end

                        
        updateBoostUI(currentFlightSpeed, overloadRatio, inBrokenReality)
        if not inBrokenReality and overloadRatio <= 0.45 then
            updateVignetteEffect(speedRatio, false)
        end
        setAuraFlightIntensity(true, speedRatio, inBrokenReality)

                                             
        local vehicles = getNearbyVehicles(CONFIG.VEHICLE_SCAN_RADIUS)
        for _, vData in ipairs(vehicles) do
            applyKineticCarImpact(vData, currentFlightSpeed, moveDir)
        end
    end
end)
