local function createSuperSonicTool()
    cleanOldTool()

    local tool = Instance.new("Tool")
    tool.Name = "Super Sonic"
    tool.RequiresHandle = false
    tool.CanBeDropped = false

    local eqConn = tool.Equipped:Connect(function()
        isToolEquipped = true
        screenGui.Enabled = true
        if UserInputService.TouchEnabled then
            mobileFrame.Visible = true
        end
        if UserInputService.KeyboardEnabled then
            desktopFrame.Visible = true
        end
        local c = lp.Character
        if c then
            disableToolAnimation(c)
            setupSonicVisualEffects(c)
        end
        if sonicHighlight then
            sonicHighlight.Enabled = true
        end
        local hum = c and c:FindFirstChildOfClass("Humanoid")
        if hum then
            hum.WalkSpeed = CONFIG.BASE_WALKSPEED
        end
    end)
    table.insert(scriptConnections, eqConn)

    local actConn = tool.Activated:Connect(function()
        if inBrokenReality and triggerChaosStrike then
            triggerChaosStrike()
        end
    end)
    table.insert(scriptConnections, actConn)

    local unEqConn = tool.Unequipped:Connect(function()
        if inBrokenReality then
            isToolEquipped = true
            screenGui.Enabled = true
            task.spawn(function()
                local c = lp.Character
                local h = c and c:FindFirstChildOfClass("Humanoid")
                if h and tool and tool.Parent ~= c then
                    pcall(function() h:EquipTool(tool) end)
                end
            end)
            return
        end

        isToolEquipped = false
        screenGui.Enabled = false
        mobileFrame.Visible = false
        desktopFrame.Visible = false
        lockBillboard.Enabled = false
        if sonicHighlight then
            sonicHighlight.Enabled = false
        end
        if sonicTrail then
            sonicTrail.Enabled = false
        end
        if isFlying and stopFlightBoost then
            stopFlightBoost()
        end
    end)
    table.insert(scriptConnections, unEqConn)

    local bp = lp:FindFirstChild("Backpack") or lp:WaitForChild("Backpack", 3)
    if bp then
        tool.Parent = bp
    end

    task.spawn(function()
        local c = lp.Character or lp.CharacterAdded:Wait()
        local h = c and (c:FindFirstChildOfClass("Humanoid") or c:WaitForChild("Humanoid", 3))
        if h and tool and tool.Parent then
            pcall(function() h:EquipTool(tool) end)
        end
    end)

    return tool
end

                                                               
                                                                    
                                                               
local inputBeganConn = UserInputService.InputBegan:Connect(function(input, gameProcessed)
    if UserInputService:GetFocusedTextBox() then return end
    if not isToolEquipped and not inBrokenReality then return end

    if input.KeyCode == Enum.KeyCode.C then
        startFlightBoost()
    elseif input.KeyCode == Enum.KeyCode.R then
        triggerHomingAttack()
    elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
        if inBrokenReality and triggerChaosStrike then
            triggerChaosStrike()
        end
    elseif input.KeyCode == Enum.KeyCode.Q then
        if inBrokenReality and triggerLightSpeedBlink then
            triggerLightSpeedBlink()
        end
    elseif input.KeyCode == Enum.KeyCode.E then
        if inBrokenReality and triggerChaosSpears then
            triggerChaosSpears()
        end
    elseif input.KeyCode == Enum.KeyCode.F then
        if inBrokenReality and triggerChaosBlast then
            triggerChaosBlast()
        end
    elseif input.KeyCode == Enum.KeyCode.X then
        if inBrokenReality and toggleExeLockOn then
            toggleExeLockOn()
        end
    elseif input.KeyCode == Enum.KeyCode.M or input.KeyCode == Enum.KeyCode.Semicolon or input.KeyCode == Enum.KeyCode.Comma then
        if mobileFrame then
            mobileFrame.Visible = not mobileFrame.Visible
            notify("Super Sonic", "Mobile Touch Controls: " .. (mobileFrame.Visible and "VISIBLE" or "HIDDEN"), 2)
        end
    end
end)
