local function cleanOldTool()
    local bp = lp:FindFirstChild("Backpack")
    if bp then
        local old = bp:FindFirstChild("Hulk Smash")
        if old then old:Destroy() end
    end
    local char = lp.Character
    if char then
        local old = char:FindFirstChild("Hulk Smash")
        if old then old:Destroy() end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            for _, trk in ipairs(hum:GetPlayingAnimationTracks()) do
                if trk.Priority == Enum.AnimationPriority.Action4 then
                    pcall(function() trk:Stop(0) trk:Destroy() end)
                end
            end
        end
    end
    pcall(function()
        local function cleanMoversIn(parent)
            if not parent then return end
            for _, obj in ipairs(parent:GetChildren()) do
                for _, child in ipairs(obj:GetChildren()) do
                    if child.Name:find("HulkVoid_") or child.Name:find("HulkSmash") then
                        child:Destroy()
                    end
                end
            end
        end
        cleanMoversIn(Workspace:FindFirstChild("Vehicles"))
        cleanMoversIn(Workspace)
    end)
end
