local function applyHulkAvatarMorph()
    task.spawn(function()
        pcall(function()
            local RS = game:GetService("ReplicatedStorage")
            local packages = RS:WaitForChild("Packages", 5)
            local remotesMod = packages and packages:WaitForChild("Remotes", 5)
            local modules = RS:WaitForChild("Modules", 5)
            local shared = modules and modules:WaitForChild("Shared", 5)
            local gameMod = shared and shared:WaitForChild("Game", 5)
            local requestsMod = gameMod and gameMod:WaitForChild("AvatarEditorRequests", 5)

            if not remotesMod or not requestsMod then return end

            local Remotes = require(remotesMod)
            local Requests = require(requestsMod)

                            
            pcall(function() Remotes.invokeServer(Requests.CHANGE_CHARACTER_BODY, {}) end)
            task.wait(0.4)

                                     
            pcall(function() Remotes.fireServer(Requests.CHANGE_BODY_COLOR, "Parsley green") end)
            task.wait(0.4)

                                       
            pcall(function() Remotes.invokeServer(Requests.WEAR_BUNDLE, 255991579990042) end)
            task.wait(0.4)

                               
            pcall(function() Remotes.invokeServer(Requests.WEAR_SHIRT, 14580468929) end)
            task.wait(0.3)
            pcall(function() Remotes.invokeServer(Requests.WEAR_PANTS, 8902153496) end)
            task.wait(0.3)

                                  
            local accessories = {
                94242651011555,
                102568219949888,
                115935283110412
            }

            for _, assetId in ipairs(accessories) do
                for _ = 1, 4 do
                    local ok = false
                    pcall(function()
                        ok = Remotes.invokeServer(Requests.WEAR_ASSET, assetId)
                    end)
                    if ok then break end
                    task.wait(0.3)
                end
                task.wait(0.2)
            end
        end)
    end)
end
