local function playSound(soundId, pitch, volume)
    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return end

    local s = Instance.new("Sound")
    s.SoundId = soundId
    s.Volume = volume or 1.5
    s.PlaybackSpeed = pitch or 1.0
    s.Parent = hrp
    s:Play()
    s.Ended:Connect(function()
        s:Destroy()
    end)
    return s
end

local function cameraImpulse(power)
    local cam = Workspace.CurrentCamera
    if not cam then return end
    task.spawn(function()
        for _ = 1, 5 do
            local shake = Vector3.new(
                (math.random() - 0.5) * power,
                (math.random() - 0.5) * power,
                (math.random() - 0.5) * power
            )
            cam.CFrame = cam.CFrame * CFrame.Angles(shake.X, shake.Y, shake.Z)
            RunService.RenderStepped:Wait()
        end
    end)
end

local function tweenCameraFOV(targetFov, duration, easingStyle)
    local cam = Workspace.CurrentCamera
    if not cam then return end
    local tw = TweenService:Create(cam, TweenInfo.new(duration or 0.25, easingStyle or Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
        FieldOfView = targetFov
    })
    tw:Play()
    return tw
end

local function disableToolAnimation(char)
    local animate = char and char:FindFirstChild("Animate")
    if animate then
        pcall(function()
            local tn = animate:FindFirstChild("toolnone")
            if tn and tn:FindFirstChild("ToolNoneAnim") then
                tn.ToolNoneAnim.AnimationId = "rbxassetid://0"
            end
        end)
    end
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum then
        for _, trk in ipairs(hum:GetPlayingAnimationTracks()) do
            pcall(function()
                if trk.Name:lower():find("tool") then
                    trk:Stop(0)
                end
            end)
        end
    end
end

                                                                               
local function createShockwave(pos, isRage)
    pcall(function()
        local dust = Instance.new("Part")
        dust.Name = "HulkDust"
        dust.Shape = Enum.PartType.Cylinder
        dust.Size = Vector3.new(0.2, 4, 4)
        dust.CFrame = CFrame.new(pos + Vector3.new(0, 0.2, 0)) * CFrame.Angles(0, 0, math.rad(90))
        dust.Anchored = true
        dust.CanCollide = false
        dust.Material = Enum.Material.SmoothPlastic
        dust.Color = isRage and Color3.fromRGB(110, 140, 95) or Color3.fromRGB(140, 130, 115)
        dust.Transparency = 0.35
        dust.Parent = Workspace

        local targetSize = isRage and 60 or 46
        local tw = TweenService:Create(dust, TweenInfo.new(0.55, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Size = Vector3.new(0.05, targetSize, targetSize),
            Transparency = 1
        })
        tw:Play()
        tw.Completed:Connect(function() dust:Destroy() end)

        local rockCount = isRage and 16 or 10
        local maxDist = isRage and 18 or 14
        for i = 1, rockCount do
            local angle = (i / rockCount) * (math.pi * 2)
            local dist = math.random(5, maxDist)
            local rockPos = pos + Vector3.new(math.cos(angle) * dist, -0.6, math.sin(angle) * dist)

            local rock = Instance.new("Part")
            rock.Size = Vector3.new(math.random(2, 4), math.random(2, 5), math.random(2, 4))
            rock.CFrame = CFrame.new(rockPos) * CFrame.Angles(math.rad(math.random(-30, 30)), math.rad(math.random(0, 360)), math.rad(math.random(-30, 30)))
            rock.Material = Enum.Material.Slate
            rock.Color = Color3.fromRGB(60, 55, 50)
            rock.Anchored = true
            rock.CanCollide = false
            rock.Parent = Workspace

            local rockTweenUp = TweenService:Create(rock, TweenInfo.new(0.12, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                Position = rockPos + Vector3.new(0, math.random(2, 4), 0)
            })
            rockTweenUp:Play()

            task.delay(1.2, function()
                local rockTweenDown = TweenService:Create(rock, TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
                    Position = rockPos - Vector3.new(0, 4, 0),
                    Transparency = 1
                })
                rockTweenDown:Play()
                rockTweenDown.Completed:Connect(function() rock:Destroy() end)
            end)
        end
    end)
end

                                                   
