local function stopUnwantedTracks(hum)
    if not hum then return end
    for _, t in ipairs(hum:GetPlayingAnimationTracks()) do
        pcall(function()
            local name = t.Name:lower()
            if name:find("jump") or name:find("fall") or name:find("walk") or name:find("run") or name:find("idle") or name:find("tool") then
                t:Stop(0)
            end
        end)
    end
end

