local function launchVehiclePhysical(vData, blastVel, spinPower)
    local primary = vData.Primary
    local model = vData.Model
    local seat = vData.Seat
    if not primary or not primary.Parent then return end

    pcall(function()
        enableClientSimulationMax()

                                                                     
        if model then
            for _, part in ipairs(model:GetDescendants()) do
                if part:IsA("BasePart") and not part.Anchored then
                    part.AssemblyLinearVelocity = blastVel
                end
            end
        else
            primary.AssemblyLinearVelocity = blastVel
        end

                                                                                           
        if seat and seat.Occupant and seat.Occupant.Parent then
            local occHrp = seat.Occupant.Parent:FindFirstChild("HumanoidRootPart")
            if occHrp then
                occHrp.AssemblyLinearVelocity = blastVel
            end
        end

                                         
        local bv = Instance.new("BodyVelocity")
        bv.Name = "HulkVehicleBlast"
        bv.MaxForce = Vector3.new(1e7, 1e7, 1e7)
        bv.Velocity = blastVel
        bv.Parent = primary

        local spin = spinPower or 22
        primary.AssemblyAngularVelocity = Vector3.new(math.random(-spin, spin), math.random(-spin, spin), math.random(-spin, spin))

        task.delay(0.32, function()
            pcall(function()
                if bv and bv.Parent then bv:Destroy() end
            end)
        end)
    end)
end

                                                                                         
local function applyAdaptiveVoidToVehicle(primary, seat, vModel)
    if not isRageMode or not primary or not primary.Parent then return end
    if voidAttractedVehicles[primary] then return end
    voidAttractedVehicles[primary] = true

    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local myPos = hrp and hrp.Position or primary.Position
    local awayDir = (primary.Position - myPos)
    local horiz = Vector3.new(awayDir.X, 0, awayDir.Z)
    local launchDir = horiz.Magnitude > 0.1 and horiz.Unit or Vector3.new(0, 0, 1)

    local blastVel = (launchDir * 180) + Vector3.new(0, 190, 0)
    launchVehiclePhysical({ Primary = primary, Model = vModel, Seat = seat }, blastVel, 25)

    task.delay(1.5, function()
        voidAttractedVehicles[primary] = nil
    end)
end

                                                                             
local function adaptiveVehicleSmashImpact(impactPos, chargePercent, isRage)
    enableClientSimulationMax()
    local hitRadius = isRage and 95 or 75
    local vehicles = getNearbyVehicles(hitRadius)
    if #vehicles == 0 then return end

    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")

    for _, vData in ipairs(vehicles) do
        local primary = vData.Primary
        if primary and primary.Parent then
            local awayDir = (primary.Position - impactPos)
            local horiz = Vector3.new(awayDir.X, 0, awayDir.Z)
            local launchDir
            if horiz.Magnitude > 0.1 then
                launchDir = horiz.Unit
            else
                launchDir = hrp and hrp.CFrame.LookVector or Vector3.new(0, 0, 1)
            end

            local mult = isRage and 1.35 or 1.0
            local fwdPower = (140 + (chargePercent * 160)) * mult
            local upPower  = (110 + (chargePercent * 140)) * mult
            local blastVel = (launchDir * fwdPower) + Vector3.new(0, upPower, 0)

            launchVehiclePhysical(vData, blastVel, isRage and 35 or 20)
        end
    end
end

                                                        
local function createRoarSonicWave(pos, forward)
    pcall(function()
        for i = 1, 3 do
            task.delay((i - 1) * 0.08, function()
                local ring = Instance.new("Part")
                ring.Name = "HulkRoarWave"
                ring.Shape = Enum.PartType.Cylinder
                ring.Size = Vector3.new(0.2, 3, 3)
                ring.CFrame = CFrame.lookAt(pos + (forward * (i * 3.5)), pos + (forward * (i * 3.5)) + forward) * CFrame.Angles(0, math.rad(90), 0)
                ring.Anchored = true
                ring.CanCollide = false
                ring.Material = Enum.Material.SmoothPlastic
                ring.Color = Color3.fromRGB(150, 255, 120)
                ring.Transparency = 0.35
                ring.Parent = Workspace

                local targetDist = 28 + (i * 12)
                local tw = TweenService:Create(ring, TweenInfo.new(0.38, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    Size = Vector3.new(0.05, 32 + (i * 10), 32 + (i * 10)),
                    CFrame = ring.CFrame + (forward * targetDist),
                    Transparency = 1
                })
                tw:Play()
                tw.Completed:Connect(function() ring:Destroy() end)
            end)
        end
    end)
end

                                                                                              
local function pushVehiclesWithSonicRoar(roarOrigin, roarDirection, maxRange, maxConeAngle)
    enableClientSimulationMax()
    local nearby = getNearbyVehicles(maxRange or 85)
    if #nearby == 0 then return end

    local forward = Vector3.new(roarDirection.X, 0, roarDirection.Z).Unit
    local coneCos = math.cos(math.rad(maxConeAngle or 75))

    for _, vData in ipairs(nearby) do
        local primary = vData.Primary
        if primary and primary.Parent then
            pcall(function()
                local toVeh = primary.Position - roarOrigin
                local dist = toVeh.Magnitude
                if dist <= 2 then dist = 2 end

                local flatDir = Vector3.new(toVeh.X, 0, toVeh.Z)
                local flatUnit = flatDir.Magnitude > 0.05 and flatDir.Unit or forward

                local dot = forward:Dot(flatUnit)
                if dot >= coneCos then
                                                                                          
                    local pushDir = (forward * 0.78 + flatUnit * 0.35 + Vector3.new(0, 0.14, 0)).Unit

                                                                                                           
                    local falloff = math.clamp(1 - (dist / (maxRange or 85)), 0.18, 1.0)
                    local pushForce = 75 + (falloff * 90)

                    local pushVelocity = (pushDir * pushForce) + Vector3.new(0, 12 * falloff, 0)
                    primary.AssemblyLinearVelocity = pushVelocity

                    local bv = Instance.new("BodyVelocity")
                    bv.Name = "HulkRoarSonicPush"
                    bv.MaxForce = Vector3.new(1e8, 1e7, 1e8)
                    bv.Velocity = pushVelocity
                    bv.Parent = primary

                    local bav = Instance.new("BodyAngularVelocity")
                    bav.Name = "HulkRoarSonicTilt"
                    bav.MaxTorque = Vector3.new(4e6, 4e6, 4e6)
                    local torqueDir = forward:Cross(Vector3.new(0, 1, 0))
                    bav.AngularVelocity = (torqueDir * (math.random(-5, 5) * falloff)) + Vector3.new(0, math.random(-4, 4), 0)
                    bav.Parent = primary

                    task.delay(0.32, function()
                        pcall(function()
                            if bv and bv.Parent then bv:Destroy() end
                            if bav and bav.Parent then bav:Destroy() end
                        end)
                    end)
                end
            end)
        end
    end
end

                                                               
                                
                                                               
local isToolEquipped = false
local isRageMode = false
local isRoaring = false
local rageEndTime = 0
local rageCooldownEndTime = 0
local roarTrack = nil
local rageHighlight = nil

local function toggleRageAura(enable)
    local char = lp.Character
    if not char then return end

    if enable then
                                                                   
        pcall(function()
            if not rageHighlight or not rageHighlight.Parent then
                rageHighlight = Instance.new("Highlight")
                rageHighlight.Name = "HulkRageAura"
                rageHighlight.OutlineColor = Color3.fromRGB(80, 220, 60)
                rageHighlight.FillColor = Color3.fromRGB(20, 80, 30)
                rageHighlight.FillTransparency = 0.88
                rageHighlight.OutlineTransparency = 0.35
                rageHighlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                rageHighlight.Parent = char
            end
            rageHighlight.Enabled = true
            _G.Hulk_Highlight = rageHighlight
        end)

        rageTimerHUD.Visible = true
    else
        if rageHighlight then
            pcall(function() rageHighlight.Enabled = false end)
        end
        rageTimerHUD.Visible = false
    end
end

                                                               
                                                                  
                                                               
local isWallClinging = false
local currentWallNormal = Vector3.new(0, 0, 1)
local currentWallPos = Vector3.new(0, 0, 0)
local wallBodyVel = nil
local lastWallClimbStep = 0

local function detachFromWall()
    if not isWallClinging then return end
    isWallClinging = false
    if wallBodyVel then
        wallBodyVel:Destroy()
        wallBodyVel = nil
    end
    local char = lp.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum then
        hum.PlatformStand = false
        hum:ChangeState(Enum.HumanoidStateType.Freefall)
    end
end

local function wallReboundLaunch()
    if not isWallClinging then return end
    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hrp or not hum then detachFromWall() return end

    local reboundNormal = currentWallNormal
    local reboundPos = currentWallPos

    detachFromWall()

    playSound(SFX.Jump, 0.85, 2.0)
    createWallImpactVFX(reboundPos, reboundNormal)
    cameraImpulse(0.12)
    tweenCameraFOV(88, 0.18, Enum.EasingStyle.Sine)
    task.delay(0.22, function() tweenCameraFOV(70, 0.4, Enum.EasingStyle.Quad) end)

    local mult = isRageMode and CONFIG.RAGE_MULT or 1.0
    local leapVelocity = (reboundNormal * (165 * mult)) + Vector3.new(0, 160 * mult, 0)
    hrp.AssemblyLinearVelocity = leapVelocity

    local reboundVel = Instance.new("BodyVelocity")
    reboundVel.Name = "HulkWallRebound"
    reboundVel.MaxForce = Vector3.new(900000, 900000, 900000)
    reboundVel.Velocity = leapVelocity
    reboundVel.Parent = hrp

    task.delay(0.28, function()
        if reboundVel and reboundVel.Parent then
            reboundVel:Destroy()
        end
    end)
end

                                                               
                                                         
                                                               
local isCharging = false
local isChargingAirLeap = false
local chargeStartTime = 0
local smashTrack = nil
local chargeConn = nil
local airborneStartTime = 0
local hasAirLeaped = false
local currentLaunchId = 0

local function getGroundDistance()
    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return 0 end
    local rayParams = RaycastParams.new()
    rayParams.FilterDescendantsInstances = { char }
    rayParams.FilterType = Enum.RaycastFilterType.Exclude
    local hit = Workspace:Raycast(hrp.Position, Vector3.new(0, -120, 0), rayParams)
    if hit then
        return (hrp.Position.Y - hit.Position.Y)
    end
    return 999
end

local function startSmashCharge()
    if not isToolEquipped or isCharging then return end
    if isWallClinging then detachFromWall() end

    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local cam = Workspace.CurrentCamera
    if not hrp or not hum or not cam then return end

    local isMidAir = (hum.FloorMaterial == Enum.Material.Air)
    if isMidAir then
        if hasAirLeaped then
            return
        end

        if airborneStartTime == 0 then
            airborneStartTime = tick()
        end

        local timeInAir = tick() - airborneStartTime
        if timeInAir > CONFIG.AIR_LEAP_WINDOW then
            return
        end
        isChargingAirLeap = true
    else
        isChargingAirLeap = false
    end

    isCharging = true
    chargeStartTime = tick()

    disableToolAnimation(char)
    stopUnwantedTracks(hum)

    hum.WalkSpeed = 0
    hum.JumpPower = 0

    local camLook = cam.CFrame.LookVector
    local flatCam = Vector3.new(camLook.X, 0, camLook.Z).Unit
    hrp.CFrame = CFrame.lookAt(hrp.Position, hrp.Position + flatCam)

    if not smashTrack or not smashTrack.Parent or not smashTrack.Parent.Parent then
        if smashTrack then pcall(function() smashTrack:Stop(0) smashTrack:Destroy() end) end
        smashTrack = playHulkEmoteTrack(hum, HULK_EMOTES.Smash, false)
    end
    if smashTrack then
        smashTrack.Priority = Enum.AnimationPriority.Action4
        smashTrack.Looped = false
        smashTrack.TimePosition = 0
        smashTrack:Play(0.04, 1, 1.25)
    end

    if chargeConn then chargeConn:Disconnect() end
    chargeConn = RunService.RenderStepped:Connect(function()
        if not isCharging then return end
        local elapsed = tick() - chargeStartTime
        local maxChargeTime = isChargingAirLeap and 1.6 or 2.0
        local percent = math.clamp(elapsed / maxChargeTime, 0.05, 1.0)

        updateChargeUI(percent, isRageMode, isChargingAirLeap)
        updateSpeedLines(percent * 0.9)
        cameraImpulse(percent * 0.02)

        if smashTrack then
            if not smashTrack.IsPlaying then
                smashTrack:Play(0, 1, 0)
                smashTrack.TimePosition = CONFIG.POSE_PAUSE_TIME
            elseif smashTrack.TimePosition >= CONFIG.POSE_PAUSE_TIME then
                smashTrack.TimePosition = CONFIG.POSE_PAUSE_TIME
                smashTrack:AdjustSpeed(0)
            end
        end
    end)
end

local function releaseSmashLaunch()
    if not isCharging then return end
    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local cam = Workspace.CurrentCamera
    if not hrp or not hum or not cam then
        isCharging = false
        isChargingAirLeap = false
        if chargeConn then chargeConn:Disconnect() end
        hideChargeUI()
        updateSpeedLines(0)
        return
    end

    local elapsed = tick() - chargeStartTime
    local maxChargeTime = isChargingAirLeap and 1.6 or 2.0
    local chargePercent = math.clamp(elapsed / maxChargeTime, 0.05, 1.0)
    local wasAirLeap = isChargingAirLeap

    isCharging = false
    isChargingAirLeap = false
    if chargeConn then chargeConn:Disconnect() end
    hideChargeUI()
    updateSpeedLines(0)

    if hum then
        hum.PlatformStand = false
        hum.WalkSpeed = isRageMode and CONFIG.RUN_SPEED_RAGE or CONFIG.RUN_SPEED_NORM
        hum.JumpPower = 50
        pcall(function()
            hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true)
            hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
            hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
            hum:ChangeState(Enum.HumanoidStateType.Freefall)
        end)
    end

    local camLook = cam.CFrame.LookVector
    local flatCam = Vector3.new(camLook.X, 0, camLook.Z).Unit
    local mult = isRageMode and 1.25 or 1.0

                                                                             
    local forwardForce, upwardForce
    if wasAirLeap then
        hasAirLeaped = true
        forwardForce = (50 + (chargePercent * 110)) * mult
        upwardForce  = (85 + (chargePercent * 190)) * mult
    else
        forwardForce = (55 + (chargePercent * 125)) * mult
        upwardForce  = (90 + (chargePercent * 210)) * mult
    end

    local launchVelocity = (flatCam * forwardForce) + Vector3.new(0, upwardForce, 0)
    hrp.AssemblyLinearVelocity = launchVelocity

    local bodyVel = Instance.new("BodyVelocity")
    bodyVel.Name = "HulkSmashVelocity"
    bodyVel.MaxForce = Vector3.new(650000, 650000, 650000)
    bodyVel.Velocity = launchVelocity
    bodyVel.Parent = hrp

    task.delay(0.28, function()
        if bodyVel and bodyVel.Parent then
            bodyVel:Destroy()
        end
    end)

                                   
    playSound(SFX.Jump, wasAirLeap and 0.95 or 0.82, 2.4)
    if wasAirLeap then
        createAirBlast(hrp.Position - Vector3.new(0, 2.0, 0), isRageMode)
    else
        createLaunchBlast(hrp.Position - Vector3.new(0, 2.8, 0))
    end
    cameraImpulse(0.06 + (0.16 * chargePercent))

                       
    local targetFov = 70 + (chargePercent * 28)
    tweenCameraFOV(targetFov, 0.16, Enum.EasingStyle.Sine)

                                                             
    if smashTrack then
        smashTrack.TimePosition = CONFIG.POSE_PAUSE_TIME
        smashTrack:AdjustSpeed(0)
    end

                                                  
    currentLaunchId = currentLaunchId + 1
    local thisLaunchId = currentLaunchId
    if activeLandConn then
        pcall(function() activeLandConn:Disconnect() end)
        activeLandConn = nil
    end

                                                          
    local hasLeftGround = false
    task.delay(0.25, function()
        hasLeftGround = true
    end)

    local function executeLanding(impactPos)
        if currentLaunchId ~= thisLaunchId then return end
        if activeLandConn then
            pcall(function() activeLandConn:Disconnect() end)
            activeLandConn = nil
        end

        hasAirLeaped = false
        airborneStartTime = 0

                                                                     
        if hum then
            hum.WalkSpeed = isRageMode and CONFIG.RUN_SPEED_RAGE or CONFIG.RUN_SPEED_NORM
        end

                                  
        tweenCameraFOV(60, 0.08, Enum.EasingStyle.Quad)
        task.delay(0.14, function()
            tweenCameraFOV(70, 0.40, Enum.EasingStyle.Back)
        end)

                                                                      
        if smashTrack then
            pcall(function() smashTrack:Stop(0.1) smashTrack:Destroy() end)
            smashTrack = nil
        end

        local slamTrack = playHulkEmoteTrack(hum, HULK_EMOTES.Smash, false)
        if slamTrack then
            slamTrack.Priority = Enum.AnimationPriority.Action4
            slamTrack.Looped = false
            slamTrack:Play(0.02, 1, CONFIG.SLAM_SPEED)
            slamTrack.TimePosition = CONFIG.POSE_PAUSE_TIME
            local finishTime = math.max(0.1, (slamTrack.Length - CONFIG.POSE_PAUSE_TIME) / CONFIG.SLAM_SPEED)
            task.delay(finishTime + 0.12, function()
                if slamTrack then
                    pcall(function() slamTrack:Stop(0.2) slamTrack:Destroy() end)
                    slamTrack = nil
                end
            end)
        end

        playSound(SFX.Impact, 0.82, 2.5)
        createShockwave(impactPos or hrp.Position, isRageMode)
        cameraImpulse(0.20 * chargePercent)
        adaptiveVehicleSmashImpact(impactPos or hrp.Position, chargePercent, isRageMode)
    end

                                                                                
    activeLandConn = RunService.Heartbeat:Connect(function()
        if not hrp or not hum then
            if activeLandConn then pcall(function() activeLandConn:Disconnect() end) activeLandConn = nil end
            return
        end
        if hasLeftGround and hum.FloorMaterial ~= Enum.Material.Air and hrp.AssemblyLinearVelocity.Y < -8 then
            executeLanding(hrp.Position)
        end
    end)

    task.spawn(function()
        task.wait(0.40)
        for _ = 1, 100 do
            task.wait(0.04)
            if currentLaunchId ~= thisLaunchId or not activeLandConn then break end
            if hasLeftGround and hum.FloorMaterial ~= Enum.Material.Air and hrp.AssemblyLinearVelocity.Y < 1 then
                executeLanding(hrp.Position)
                break
            end
        end
        if currentLaunchId == thisLaunchId and activeLandConn and smashTrack then
            pcall(function() smashTrack:Stop(0.2) end)
            smashTrack = nil
            tweenCameraFOV(70, 0.3)
        end
    end)
end

                                                               
                                             
                                                               
local lastRoarTime = 0

local function triggerHulkRoar()
    if not isToolEquipped then return end
    if isRoaring or isCharging then return end
    if isWallClinging then detachFromWall() end

    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hrp or not hum then return end

    local now = tick()
    local isCooldownRoar = (now < rageCooldownEndTime or isRageMode)

                                                                                                                 
    if isCooldownRoar then
        if now - lastRoarTime < 1.8 then
            return
        end
    end

    lastRoarTime = now
    isRoaring = true
    hum.WalkSpeed = 0

    if smashTrack then
        pcall(function() smashTrack:Stop(0.1) end)
        smashTrack = nil
    end

    stopUnwantedTracks(hum)
    disableToolAnimation(char)

    if not isCooldownRoar then
                                     
        isRageMode = true
        rageEndTime = tick() + CONFIG.RAGE_DURATION
        toggleRageAura(true)
        updateRageTimerDisplay(CONFIG.RAGE_DURATION, CONFIG.RAGE_DURATION)
    end

                      
    task.spawn(function()
        pcall(function()
            if roarTrack then pcall(function() roarTrack:Stop(0) roarTrack:Destroy() end) end
            roarTrack = playHulkEmoteTrack(hum, HULK_EMOTES.Roar, false)
            if roarTrack then
                roarTrack.Priority = Enum.AnimationPriority.Action4
                roarTrack.Looped = false
                roarTrack:Play(0.08, 1, 1.1)
            end
        end)
    end)

    playSound(SFX.Roar, isCooldownRoar and 0.95 or 0.88, 3.0)
    cameraImpulse(isCooldownRoar and 0.09 or 0.13)
    createLaunchBlast(hrp.Position - Vector3.new(0, 2.8, 0))

                                                                         
    local forward = hrp.CFrame.LookVector
    createRoarSonicWave(hrp.Position + Vector3.new(0, 1.5, 0), forward)
    pushVehiclesWithSonicRoar(hrp.Position, forward, 90, 75)

                                    
    task.delay(0.8, function()
        isRoaring = false
        if hum then
            hum.WalkSpeed = isRageMode and CONFIG.RUN_SPEED_RAGE or CONFIG.RUN_SPEED_NORM
        end
    end)

    task.delay(1.6, function()
        if roarTrack then
            pcall(function() roarTrack:Stop(0.2) end)
            roarTrack = nil
        end
    end)
end

                                                               
                                                                         
                                                               
local lastFootstepTime = 0

local hbConn = RunService.Heartbeat:Connect(function()
    local char = lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hrp or not hum then return end

                                                                          
    if isRageMode then
        local remaining = rageEndTime - tick()
        if remaining > 0 then
            updateRageTimerDisplay(remaining, CONFIG.RAGE_DURATION)
            pcall(function()
                rtStroke.Transparency = 0.2 + (math.sin(tick() * 4) * 0.15)
            end)

                                                                  
            local now = tick()
            if now - lastVoidScan > 0.45 then
                lastVoidScan = now
                local nearbyVehicles = getNearbyVehicles(75)
                for _, vehData in ipairs(nearbyVehicles) do
                    applyAdaptiveVoidToVehicle(vehData.Primary, vehData.Seat)
                end
            end
        else
                                 
            isRageMode = false
            toggleRageAura(false)
            cleanupVoidGravity()
            rageCooldownEndTime = tick() + CONFIG.RAGE_COOLDOWN
            hum.WalkSpeed = CONFIG.RUN_SPEED_NORM
            rageTimerHUD.Visible = false
            notify("Hulk Rage", "Rage Ended (Cooldown: " .. CONFIG.RAGE_COOLDOWN .. "s)", 2.5)
        end
    end

                                                                                             
    if not isToolEquipped then return end

                                                                              
    local isCurrentlyAirborne = (hum.FloorMaterial == Enum.Material.Air)
    if isCurrentlyAirborne then
        if airborneStartTime == 0 then
            airborneStartTime = tick()
        end
    else
        airborneStartTime = 0
        hasAirLeaped = false
    end

    if airBadge and airBadge.actionText then
        if not isCurrentlyAirborne then
            airBadge.actionText.Text = "Mid-Air Leap"
            airBadge.actionText.TextColor3 = Color3.fromRGB(160, 180, 160)
            airBadge.keyBox.BackgroundColor3 = Color3.fromRGB(22, 35, 22)
            airBadge.stroke.Color = Color3.fromRGB(60, 120, 50)
        else
            local elapsedAir = tick() - airborneStartTime
            local remainingAir = math.max(0, CONFIG.AIR_LEAP_WINDOW - elapsedAir)
            if hasAirLeaped then
                airBadge.actionText.Text = "Air Leap (Used)"
                airBadge.actionText.TextColor3 = Color3.fromRGB(230, 100, 100)
                airBadge.keyBox.BackgroundColor3 = Color3.fromRGB(45, 20, 20)
                airBadge.stroke.Color = Color3.fromRGB(140, 50, 50)
            elseif remainingAir > 0 then
                airBadge.actionText.Text = string.format("Air Leap (%.1fs)", remainingAir)
                airBadge.actionText.TextColor3 = Color3.fromRGB(90, 255, 120)
                airBadge.keyBox.BackgroundColor3 = Color3.fromRGB(25, 55, 25)
                airBadge.stroke.Color = Color3.fromRGB(80, 220, 60)
            else
                airBadge.actionText.Text = "Air Leap (Locked)"
                airBadge.actionText.TextColor3 = Color3.fromRGB(190, 140, 80)
                airBadge.keyBox.BackgroundColor3 = Color3.fromRGB(40, 30, 18)
                airBadge.stroke.Color = Color3.fromRGB(130, 90, 40)
            end
        end
    end

                                                                            
    if isRageMode and hum.MoveDirection.Magnitude > 0.1 and not isCharging and not isWallClinging then
        if tick() - lastFootstepTime > 0.28 then
            lastFootstepTime = tick()
            cameraImpulse(0.02)
            pcall(function()
                local puff = Instance.new("Part")
                puff.Size = Vector3.new(1.4, 0.2, 1.4)
                puff.CFrame = CFrame.new(hrp.Position - Vector3.new(0, 2.8, 0))
                puff.Material = Enum.Material.SmoothPlastic
                puff.Color = Color3.fromRGB(140, 130, 115)
                puff.Transparency = 0.5
                puff.Anchored = true
                puff.CanCollide = false
                puff.Parent = Workspace
                local pTw = TweenService:Create(puff, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    Size = Vector3.new(4, 0.1, 4),
                    Transparency = 1
                })
                pTw:Play()
                pTw.Completed:Connect(function() puff:Destroy() end)
            end)
        end
    end

                                                                      
    if not isCharging and not isRoaring then
        if not isWallClinging and hum.FloorMaterial == Enum.Material.Air then
            local moveDir = hum.MoveDirection
            local checkDir = moveDir.Magnitude > 0.1 and moveDir.Unit or hrp.CFrame.LookVector

            local rayParams = RaycastParams.new()
            rayParams.FilterDescendantsInstances = { char }
            rayParams.FilterType = Enum.RaycastFilterType.Exclude

            local wallHit = Workspace:Raycast(hrp.Position, checkDir * 6.5, rayParams)
            if not wallHit then
                wallHit = Workspace:Raycast(hrp.Position + Vector3.new(0, 1.8, 0), checkDir * 6.5, rayParams)
            end
            if not wallHit then
                wallHit = Workspace:Raycast(hrp.Position - Vector3.new(0, 1.5, 0), checkDir * 6.5, rayParams)
            end
            if not wallHit and moveDir.Magnitude > 0.1 then
                wallHit = Workspace:Raycast(hrp.Position, hrp.CFrame.LookVector * 6.0, rayParams)
            end

            if wallHit and wallHit.Instance and wallHit.Instance.CanCollide and math.abs(wallHit.Normal.Y) < 0.40 then
                isWallClinging = true
                currentWallNormal = wallHit.Normal
                currentWallPos = wallHit.Position

                playSound(SFX.WallImpact, 1.15, 2.0)
                createWallImpactVFX(currentWallPos, currentWallNormal)
                cameraImpulse(0.08)

                hum.PlatformStand = true
                hrp.CFrame = CFrame.lookAt(hrp.Position, hrp.Position - currentWallNormal)

                if not wallBodyVel then
                    wallBodyVel = Instance.new("BodyVelocity")
                    wallBodyVel.Name = "HulkWallClingVel"
                    wallBodyVel.MaxForce = Vector3.new(1e7, 1e7, 1e7)
                    wallBodyVel.Parent = hrp
                end
                wallBodyVel.Velocity = -currentWallNormal * 1.5
            end
        end

                                                               
        if isWallClinging and wallBodyVel then
            if hum.FloorMaterial ~= Enum.Material.Air then
                detachFromWall()
                return
            end

            local isUp = UserInputService:IsKeyDown(Enum.KeyCode.Z) or UserInputService:IsKeyDown(Enum.KeyCode.W)
            local isDown = UserInputService:IsKeyDown(Enum.KeyCode.S)

            if hum.MoveDirection.Magnitude > 0.15 then
                local camCF = Workspace.CurrentCamera.CFrame
                local localMove = camCF:VectorToObjectSpace(hum.MoveDirection)
                if localMove.Z < -0.3 then isUp = true end
                if localMove.Z > 0.3 then isDown = true end
            end

            if isUp and not isDown then
                local climbSpd = isRageMode and (CONFIG.WALL_CLIMB_SPD * 1.35) or CONFIG.WALL_CLIMB_SPD
                wallBodyVel.Velocity = Vector3.new(0, climbSpd, 0) - (currentWallNormal * 2.5)
                hum.PlatformStand = true
                if tick() - lastWallClimbStep > 0.28 then
                    lastWallClimbStep = tick()
                    createWallImpactVFX(hrp.Position + (hrp.CFrame.LookVector * 1.5), currentWallNormal)
                    playSound(SFX.Impact, 1.3, 1.4)
                    cameraImpulse(0.03)
                end

                                                                 
                local rayParams = RaycastParams.new()
                rayParams.FilterDescendantsInstances = { char }
                rayParams.FilterType = Enum.RaycastFilterType.Exclude

                local wallAhead = Workspace:Raycast(hrp.Position + Vector3.new(0, 2.5, 0), -currentWallNormal * 4.5, rayParams)
                if not wallAhead then
                    local vaultVel = Vector3.new(0, 38, 0) - (currentWallNormal * 26)
                    detachFromWall()
                    hrp.AssemblyLinearVelocity = vaultVel
                end
            elseif isDown and not isUp then
                wallBodyVel.Velocity = Vector3.new(0, -25, 0) - (currentWallNormal * 2.5)
                hum.PlatformStand = true
            else
                wallBodyVel.Velocity = -currentWallNormal * 1.5
                hum.PlatformStand = true
            end
        end
    end
end)
table.insert(scriptConnections, hbConn)

                                                               
                            
                                                               
local function createHulkTool()
    cleanOldTool()

    local tool = Instance.new("Tool")
    tool.Name = "Hulk Smash"
    tool.RequiresHandle = false
    tool.CanBeDropped = false

    local eqConn = tool.Equipped:Connect(function()
        isToolEquipped = true
        screenGui.Enabled = true
        if UserInputService.TouchEnabled then
            mobileFrame.Visible = true
        end
        if UserInputService.KeyboardEnabled then
            desktopFrame.Visible = true
        end
        local c = lp.Character
        if c then
            disableToolAnimation(c)
        end
        local hum = c and c:FindFirstChildOfClass("Humanoid")
        if hum then
            hum.WalkSpeed = isRageMode and CONFIG.RUN_SPEED_RAGE or CONFIG.RUN_SPEED_NORM
        end
    end)
    table.insert(scriptConnections, eqConn)

    local unEqConn = tool.Unequipped:Connect(function()
        isToolEquipped = false
        screenGui.Enabled = false
        mobileFrame.Visible = false
        desktopFrame.Visible = false
        if isCharging then
            isCharging = false
            isChargingAirLeap = false
            if chargeConn then chargeConn:Disconnect() end
            hideChargeUI()
            updateSpeedLines(0)
            local c = lp.Character
            local hrp = c and c:FindFirstChild("HumanoidRootPart")
            local hum = c and c:FindFirstChildOfClass("Humanoid")
            if hrp then hrp.Anchored = false end
            if hum then hum.WalkSpeed = isRageMode and CONFIG.RUN_SPEED_RAGE or CONFIG.RUN_SPEED_NORM end
        end
        hasAirLeaped = false
        airborneStartTime = 0
        if isWallClinging then
            detachFromWall()
        end
    end)
    table.insert(scriptConnections, unEqConn)

    local ancConn = tool.AncestryChanged:Connect(function(_, parent)
        if not parent or (parent ~= lp.Character and parent ~= lp:FindFirstChild("Backpack")) then
            if _G.Hulk_MasterCleanup then pcall(_G.Hulk_MasterCleanup) end
            if screenGui then pcall(function() screenGui:Destroy() end) end
        end
    end)
    table.insert(scriptConnections, ancConn)

    local desConn = tool.Destroying:Connect(function()
        if _G.Hulk_MasterCleanup then pcall(_G.Hulk_MasterCleanup) end
        if screenGui then pcall(function() screenGui:Destroy() end) end
    end)
    table.insert(scriptConnections, desConn)

    local bp = lp:WaitForChild("Backpack")
    tool.Parent = bp

    task.spawn(function()
        local c = lp.Character or lp.CharacterAdded:Wait()
        local h = c:WaitForChild("Humanoid", 3)
        if h then
            h:EquipTool(tool)
        end
    end)

    return tool
end

                                                               
                                                                     
                                                               
