        local function styleButton(btn, label, hot)
            btn.Text = label
            btn.TextColor3 = Color3.fromRGB(245, 250, 255)
            btn.Font = Enum.Font.GothamBold
            btn.TextSize = 11
            btn.BackgroundColor3 = hot and Color3.fromRGB(22, 65, 92) or Color3.fromRGB(23, 30, 42)
            btn.AutoButtonColor = true
            local c = Instance.new("UICorner")
            c.CornerRadius = UDim.new(0, 9)
            c.Parent = btn
            local st = Instance.new("UIStroke")
            st.Color = hot and Color3.fromRGB(0, 210, 255) or Color3.fromRGB(95, 120, 145)
            st.Transparency = 0.35
            st.Thickness = 1
            st.Parent = btn
        end

        local function makeHold(name, label, pos, size2, onDown, onUp)
            local b = Instance.new("TextButton")
            b.Name = name
            b.Position = pos
            b.Size = size2
            b.Text = label
            b.Parent = frame
            styleButton(b, label, false)
            b.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    if onDown then onDown() end
                end
            end)
            b.InputEnded:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    if onUp then onUp() end
                end
            end)
            return b
        end

        local function makeAction(name, label, pos, callback, hot)
            local b = Instance.new("TextButton")
            b.Name = name
            b.Position = pos
            b.Size = UDim2.new(0, 92, 0, 34)
            b.Parent = frame
            styleButton(b, label, hot)
            b.Activated:Connect(callback)
            return b
        end

        -- Movement intentionally uses Roblox's own humanoid joystick/MoveDirection,
        -- matching the original Leviathan control model. No replacement D-pad is added.

        makeAction("Wake", "WAKE UP", UDim2.new(0, 10, 0, 168), function()
            if not robotActive then return end
            if robotState == "rising" or robotState == "walk" or robotState == "attack" then return end
            robotState = "rising"
            robotStateTimer = 0
            robotRisingProgress = 0
            robotMode = "manual"
            rNotif("MECHA ROBOT", "Titan Awakening... WAKE UP!", 4)
        end, true)

        makeAction("Idle", "IDLE", UDim2.new(0, 110, 0, 168), function()
            if not robotActive then return end
            robotMode = "manual"
            robotState = "idle"
            robotStateTimer = 0
        end)

        makeAction("FollowMe", "FOLLOW ME", UDim2.new(0, 210, 0, 168), function()
            if not robotActive then return end
            robotFollowName = game:GetService("Players").LocalPlayer.Name
            robotTarget = robotFollowName
            robotMode = "follow"
            robotState = "walk"
            robotWaypoint = nil
            robotStateTimer = 0
        end)

        makeAction("Hunt", "HUNT", UDim2.new(0, 10, 0, 208), function()
            if not robotActive then return end
            if robotFollowName == "---" or robotFollowName == "" then
                rNotif("Mecha Robot", "Select a target first in Build!", 3)
                return
            end
            robotMode = "follow"
            robotState = "walk"
            robotWaypoint = nil
            robotStateTimer = 0
        end)

        makeAction("Patrol", "PATROL", UDim2.new(0, 110, 0, 208), function()
            if not robotActive then return end
            robotMode = "free"
            robotState = "walk"
            robotWaypoint = nil
            robotStateTimer = 0
        end)

        makeAction("Attack", "ATTACK", UDim2.new(0, 210, 0, 208), function()
            if not robotActive then return end
            if not canDo("attack", 4) then rNotif("Mecha Robot", "Cooldown...", 2) return end
            robotMode = "manual"
            robotState = "attack"
            robotStateTimer = 0
        end, true)

        makeAction("Stomp", "STOMP", UDim2.new(0, 10, 0, 248), function()
            if not robotActive then return end
            if not canDo("stomp", 3) then rNotif("Mecha Robot", "Cooldown...", 2) return end
            robotMode = "manual"
            robotState = "stomp"
            robotStateTimer = 0
        end)

        makeAction("Roar", "ROAR", UDim2.new(0, 110, 0, 248), function()
            if not robotActive then return end
            if not canDo("roar", 5) then rNotif("Mecha Robot", "Cooldown...", 2) return end
            robotMode = "manual"
            robotState = "roar"
            robotStateTimer = 0
        end)

        makeAction("Dismount", "EXIT", UDim2.new(0, 210, 0, 248), function()
            local hum = game:GetService("Players").LocalPlayer.Character and game:GetService("Players").LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
            if hum then hum.Sit = false end
        end)

        makeAction("Kneel", "KNEEL", UDim2.new(0, 10, 0, 288), function()
            if not robotActive then return end
            robotMode = "manual"
            robotState = "kneel"
            robotStateTimer = 0
        end)

        makeAction("Shield", "SHIELD", UDim2.new(0, 110, 0, 288), function()
            if not robotActive then return end
            if robotFollowName == "---" or robotFollowName == "" then
                rNotif("Mecha Robot", "Select a target or yourself in Build!", 3)
                return
            end
            robotMode = "shield"
            robotState = "shield"
            robotStateTimer = 0
        end)

        makeAction("StopShield", "STOP SHIELD", UDim2.new(0, 210, 0, 288), function()
            if not robotActive then return end
            robotMode = "manual"
            robotState = "idle"
            robotStateTimer = 0
        end)

        pcall(function() sg.Parent = parent end)
    end

    local function startRobotLoop()
        if robotLoop then robotLoop:Disconnect() end
        robotAnimT = 0
        robotRisingProgress = 0

        robotLoop = game:GetService("RunService").Heartbeat:Connect(function(dt)
            if not robotActive then return end
            robotAnimT = robotAnimT + dt
            robotStateTimer = robotStateTimer + dt

            local uis = game:GetService("UserInputService")
            local lp = game:GetService("Players").LocalPlayer
            local myHum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
            local isRiding = false

            if robotDriverSeat and myHum and robotDriverSeat.Occupant == myHum then
                isRiding = true
            end

            if isRiding then
                setupRobotPilotHUD()
                local moveDir = Vector3.new(0, 0, 0)
                local turnSpeed = 2.4
                if myHum and myHum.MoveDirection.Magnitude > 0.05 then
                    local md = myHum.MoveDirection
                    local targetAngle = math.atan2(md.X, md.Z)
                    local diffAngle = (targetAngle - robotAngle + math.pi) % (2 * math.pi) - math.pi
                    robotAngle = robotAngle + math.clamp(diffAngle, -turnSpeed * 1.5, turnSpeed * 1.5) * dt
                    moveDir = Vector3.new(math.sin(robotAngle), 0, math.cos(robotAngle))
                end

                if moveDir.Magnitude > 0 then
                    robotAnchor = robotAnchor + moveDir.Unit * robotSpeed * dt
                    if robotState ~= "attack" and robotState ~= "stomp" and robotState ~= "roar" and robotState ~= "rising" then
                        robotState = "walk"
                    end
                else
                    if robotState == "walk" then
                        robotState = "idle"
                    end
                end

                if robotHudStatus then
                    if robotState == "rising" then
                        robotHudStatus.Text = "STATUS: AWAKENING"
                    elseif robotState == "attack" then
                        robotHudStatus.Text = "STATUS: ANNIHILATION"
                    elseif robotState == "stomp" then
                        robotHudStatus.Text = "STATUS: EARTHSHAKER"
                    elseif robotState == "roar" then
                        robotHudStatus.Text = "STATUS: OVERDRIVE ROAR"
                    elseif moveDir.Magnitude > 0 then
                        robotHudStatus.Text = "STATUS: WALKING / PILOTED"
                    else
                        robotHudStatus.Text = "STATUS: READY"
                    end
                end

            elseif robotState == "attack" then
                local fwd = Vector3.new(math.sin(robotAngle), 0, math.cos(robotAngle))
                robotAnchor = robotAnchor + fwd * 45 * dt

                if robotTarget and robotTarget ~= "---" then
                    local targetPlayer = game:GetService("Players"):FindFirstChild(robotTarget)
                    local targetChar = targetPlayer and targetPlayer.Character or workspace:FindFirstChild(robotTarget)
                    local hrp = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        local dir = (hrp.Position - robotAnchor)
                        dir = Vector3.new(dir.X, 0, dir.Z)
                        if dir.Magnitude > 0 then
                            local targetAngle = math.atan2(dir.X, dir.Z)
                            local angleDiff = (targetAngle - robotAngle + math.pi) % (2 * math.pi) - math.pi
                            robotAngle = robotAngle + math.clamp(angleDiff, -6, 6) * dt
                        end
                    end
                end

            elseif robotState == "walk" then
                if robotMode == "follow" and robotFollowName ~= "" and robotFollowName ~= "---" then
                    local tp = game:GetService("Players"):FindFirstChild(robotFollowName)
                    local hrp = tp and tp.Character and tp.Character:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        local toTarget = hrp.Position - robotAnchor
                        toTarget = Vector3.new(toTarget.X, 0, toTarget.Z)
                        if toTarget.Magnitude > 7 then
                            local targetAngle = math.atan2(toTarget.X, toTarget.Z)
                            local angleDiff = (targetAngle - robotAngle + math.pi) % (2 * math.pi) - math.pi
                            robotAngle = robotAngle + math.clamp(angleDiff, -3.0, 3.0) * dt
                            local dist = toTarget.Magnitude
                            local adaptSpeed = math.clamp(dist * 0.7, robotSpeed, 65)
                            local fwdF = Vector3.new(math.sin(robotAngle), 0, math.cos(robotAngle))
                            robotAnchor = robotAnchor + fwdF * adaptSpeed * dt
                        else
                            robotState = "idle"
                        end
                    end

                elseif robotMode == "free" then
                    if not robotWaypoint then
                        local rAngle = math.random() * 2 * math.pi
                        local rDist  = math.random(40, 120)
                        local nx = math.clamp(robotAnchor.X + math.cos(rAngle) * rDist, -350, 350)
                        local nz = math.clamp(robotAnchor.Z + math.sin(rAngle) * rDist, -350, 350)
                        robotWaypoint = Vector3.new(nx, robotAnchor.Y, nz)
                    end

                    local toWp = robotWaypoint - robotAnchor
                    toWp = Vector3.new(toWp.X, 0, toWp.Z)

                    if toWp.Magnitude < 8 then
                        robotWaypoint = nil
                        robotState = "idle"
                        task.delay(math.random(2, 6), function()
                            if not robotActive or robotMode ~= "free" then return end
                            if robotState == "idle" then robotState = "walk" end
                        end)
                    else
                        local targetAngle = math.atan2(toWp.X, toWp.Z)
                        local angleDiff = (targetAngle - robotAngle + math.pi) % (2 * math.pi) - math.pi
                        local turnRate = math.clamp(math.abs(angleDiff) * 3, 1.8, 5.0)
                        robotAngle = robotAngle + math.clamp(angleDiff, -turnRate, turnRate) * dt
                        local fwdF = Vector3.new(math.sin(robotAngle), 0, math.cos(robotAngle))
                        robotAnchor = robotAnchor + fwdF * robotSpeed * dt
                    end
                else
                    local fwd = Vector3.new(math.sin(robotAngle), 0, math.cos(robotAngle))
                    robotAnchor = robotAnchor + fwd * robotSpeed * dt
                end
            end

            if robotPilotGui then
                robotPilotGui.Enabled = robotActive
                if robotHudFrame then robotHudFrame.Visible = isRiding end
                if not isRiding then
                    robotUIForward = false
                    robotUIBackward = false
                    robotUILeft = false
                    robotUIRight = false
                end
            end

            if robotState == "rising" then
                robotRisingProgress = math.min(robotRisingProgress + dt * 0.25, 1)
                if robotRisingProgress >= 1 then
                    robotState = "idle"
                    robotStateTimer = 0
                    rNotif("MECHA ROBOT", "TITAN SYSTEMS 100% ONLINE!", 5)
                end
            end

            if robotState == "attack" and robotStateTimer > 3.5 then
                robotState = "idle" robotStateTimer = 0
            end
            if robotState == "stomp" and robotStateTimer > 2.2 then
                robotState = "idle" robotStateTimer = 0
            end
            if robotState == "roar" and robotStateTimer > 4.5 then
                robotState = "idle" robotStateTimer = 0
            end

            local ignoreList = { workspace:FindFirstChild("WorkspaceCom") }
            for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
                if p.Character then table.insert(ignoreList, p.Character) end
            end
            local rayParams = RaycastParams.new()
            rayParams.FilterType = Enum.RaycastFilterType.Exclude
            rayParams.FilterDescendantsInstances = ignoreList

            local rayOrigin = Vector3.new(robotAnchor.X, robotAnchor.Y + 8, robotAnchor.Z)
            local rayResult = workspace:Raycast(rayOrigin, Vector3.new(0, -40, 0), rayParams)
            if rayResult then
                local targetY = rayResult.Position.Y
                local diffY = targetY - robotAnchor.Y
                diffY = math.clamp(diffY, -25 * dt, 14 * dt)
                robotAnchor = Vector3.new(robotAnchor.X, robotAnchor.Y + diffY, robotAnchor.Z)
            end

            for partIndex, layout in ipairs(ROBOT_LAYOUT) do
                local w = robotWorkers[layout.key]
                if w then
                    w.targetCF = _0xH_3ee(layout, robotAnimT, robotState, robotRisingProgress, partIndex)
                    w.targetColor = getPartColor(layout, partIndex, robotAnimT, robotState, robotColorMode)
                end
            end
        end)
    end

    local function spawnRobot()
        local lp = game:GetService("Players").LocalPlayer
        local char = lp.Character or lp.CharacterAdded:Wait()
        local myRoot = char:WaitForChild("HumanoidRootPart")

        rNotif("MECHA ROBOT", "Summoning Titan Mecha... (15 parts, ~13s)", 5)

        local RE         = game:GetService("ReplicatedStorage"):WaitForChild("RE")
        local clearTools = RE:WaitForChild("1Clea1rTool1s")
        local toolRE     = RE:WaitForChild("1Too1l")
        local myPropName = "Prop" .. lp.Name
        local wc         = workspace:WaitForChild("WorkspaceCom")
        local Telemetry  = game:GetService("ReplicatedStorage"):WaitForChild("Remotes"):WaitForChild("TelemetryClientInteraction")
        local defaultColor = Color3.fromRGB(0, 160, 255)

        pcall(function() clearTools:FireServer("ClearAllProps") end)
        task.wait(0.3)

        local propsTool = _0xH_3f2()
        if not propsTool then return end

        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum and propsTool.Parent ~= char then
            hum:EquipTool(propsTool)
            task.wait(0.2)
        end

        local toolPropMake = propsTool:FindFirstChild("Tool_PropMake") or propsTool:WaitForChild("Tool_PropMake", 3)
        if not toolPropMake then
            local bpTool = lp.Backpack:FindFirstChild("PropMaker")
            if bpTool then toolPropMake = bpTool:FindFirstChild("Tool_PropMake") end
        end
        if not toolPropMake then return end

        ROBOT_GROUND_Y = myRoot.Position.Y
        robotAnchor    = myRoot.Position + (myRoot.CFrame.LookVector * 15)
        robotAnchor    = Vector3.new(robotAnchor.X, ROBOT_GROUND_Y, robotAnchor.Z)

        robotWorkers = {}
        robotDriverSeat = nil

        local assignedProps = {}

        for idx, layout in ipairs(ROBOT_LAYOUT) do
            if not robotActive then break end

            local playerPos = (lp.Character and lp.Character:FindFirstChild("HumanoidRootPart") and lp.Character.HumanoidRootPart.Position) or myRoot.Position
            local spawnPos = playerPos + Vector3.new(math.cos(idx) * 4, 2, math.sin(idx) * 4)

            
            local currentHum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
            if currentHum and propsTool.Parent ~= lp.Character then
                currentHum:EquipTool(propsTool)
                task.wait(0.1)
            end

            local tpm = propsTool:FindFirstChild("Tool_PropMake")
            if not tpm then
                local bp = lp.Backpack:FindFirstChild("PropMaker")
                if bp then tpm = bp:FindFirstChild("Tool_PropMake") end
            end
            if not tpm then return end

            pcall(function() Telemetry:FireServer("filterClick", {name = layout.cat, itemType = "Props"}) end)
            task.wait(0.05)
            pcall(function() Telemetry:FireServer("filterClick", {name = layout.prop, itemType = "Props"}) end)
            task.wait(0.05)
            pcall(function() clearTools:FireServer("RequestingPropName", layout.prop, layout.cat) end)
            task.wait(0.1)

            
            pcall(function() tpm:FireServer(workspace.Terrain, spawnPos) end)
            task.wait(0.85)

            if not robotActive then break end

            local foundProp = nil
            local scf = nil
            local cpc = nil

            for _, folder in pairs(wc:GetChildren()) do
                if foundProp then break end
                for _, prop in pairs(folder:GetChildren()) do
                    if prop.Name == myPropName and not assignedProps[prop] then
                        local propScf = prop:FindFirstChild("SetCurrentCFrame") or prop:FindFirstChild("SetCurrentCFrame", true) or prop:FindFirstChildWhichIsA("RemoteFunction", true)
                        if propScf then
                            foundProp = prop
                            scf = propScf
                            cpc = prop:FindFirstChild("ChangePropColor") or prop:FindFirstChild("ChangePropColor", true)
                            assignedProps[prop] = true
                            break
                        end
                    end
                end
            end

            if layout.key == "core" and foundProp then
                local seat = foundProp:FindFirstChildWhichIsA("Seat", true)
                if seat then robotDriverSeat = seat end
            end

            local initialCF = _0xH_3ee(layout, 0, "dormant", 0, idx)
            local w = {
                key = layout.key, scf = scf, cpc = cpc,
                targetCF = initialCF, targetColor = defaultColor,
                lastSentCF = nil, lastSentColor = nil,
                lastSendTimeCF = 0, lastSendTimeColor = 0
            }
            robotWorkers[layout.key] = w
            if scf then pcall(function() scf:InvokeServer(initialCF) end) end
            if cpc then pcall(function() cpc:InvokeServer(defaultColor) end) end
            startWorkers(w)
        end

                                                            
        task.wait(1.0)
        pcall(function() toolRE:InvokeServer("PickingTools", "PropMaker") end)
        pcall(function() clearTools:FireServer("ClosePropMenu") end)

        local count = 0
        for _, w in pairs(robotWorkers) do if w.scf then count = count + 1 end end
        rNotif("MECHA ROBOT", "Titan online! " .. count .. "/15 parts assembled. Say 'wake up' to activate!", 6)
    end

    local function setupChatListener()
        if robotChatConn then
            if type(robotChatConn) == "table" then
                for _, c in pairs(robotChatConn) do pcall(function() c:Disconnect() end) end
            else pcall(function() robotChatConn:Disconnect() end) end
        end
        robotChatConn = {}

        local function onChat(player, message)
            if not robotActive or not player or not message then return end
            local isWhitelisted = (player == game:GetService("Players").LocalPlayer)
            if not isWhitelisted then return end

            local text = message:lower():match("^%s*(.-)%s*$")
            if string.find(text, "wake up") or string.find(text, "arise") or string.find(text, "reveil") then
                if robotState == "rising" or robotState == "walk" or robotState == "attack" then return end
                robotState = "rising"
                robotStateTimer = 0
                robotRisingProgress = 0
                rNotif("MECHA ROBOT", "Titan Awakening... WAKE UP!", 6)
            end
        end

        pcall(function()
            local TCS = game:GetService("TextChatService")
            if TCS and TCS.MessageReceived then
                table.insert(robotChatConn, TCS.MessageReceived:Connect(function(msg)
                    if msg and msg.TextSource then
                        local p = game:GetService("Players"):GetPlayerByUserId(msg.TextSource.UserId)
                        if p then onChat(p, msg.Text) end
                    end
                end))
            end
        end)

        for _, p in pairs(game:GetService("Players"):GetPlayers()) do
            table.insert(robotChatConn, p.Chatted:Connect(function(msg) onChat(p, msg) end))
        end
        table.insert(robotChatConn, game:GetService("Players").PlayerAdded:Connect(function(p)
            table.insert(robotChatConn, p.Chatted:Connect(function(msg) onChat(p, msg) end))
        end))
    end

    _G.BTR_LOAD_PROGRESS = 0.65
_G.BTR_LOAD_STATUS = "Loading Build & Titan frameworks..."

BuildTab:AddSection({"> Mecha Titan"})

    local robotToggle = BuildTab:AddToggle({
        Name = "Spawn Mecha Robot",
        Description = "Summon a giant 15-prop mecha titan. Say 'wake up' to activate it!",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            if not val and not robotActive then return end
            robotActive = val
            if val then
                robotState = "dormant"
                robotRisingProgress = 0
                setupChatListener()
                task.spawn(function()
                    spawnRobot()
                    startRobotLoop()
                end)
            else
                if robotChatConn then
                    if type(robotChatConn) == "table" then
                        for _, c in pairs(robotChatConn) do pcall(function() c:Disconnect() end) end
                    else pcall(function() robotChatConn:Disconnect() end) end
                    robotChatConn = nil
                end
                if robotLoop then
                    robotLoop:Disconnect()
                    robotLoop = nil
                end
                robotState = "idle"
                robotWorkers = {}
                robotDriverSeat = nil
                removeRobotPilotHUD()
                local RE = game:GetService("ReplicatedStorage"):FindFirstChild("RE")
                if RE then
                    local clearTools = RE:FindFirstChild("1Clea1rTool1s")
                    if clearTools then
                        pcall(function() clearTools:FireServer("ClearAllProps") end)
                    end
                end
                task.wait(0.1)
                _0xH_3f1()
                rNotif("Mecha Robot", "The mecha returns to the vault.", 3)
            end
        end
    })

