    local function spawnUnicorn()
        local lp = game:GetService("Players").LocalPlayer
        local RE = game:GetService("ReplicatedStorage"):WaitForChild("RE")
        local clearTools  = RE:WaitForChild("1Clea1rTool1s")
        local toolRemote  = RE:WaitForChild("1Too1l")
        local Telemetry   = game:GetService("ReplicatedStorage"):WaitForChild("Remotes"):WaitForChild("TelemetryClientInteraction")

        pcall(function() clearTools:FireServer("ClearAllProps") end)
        task.wait(0.3)
        local propsTool = _0xH_3f2()
        if not propsTool then uNotif("Error: PropMaker not found!", 4) return end

        
        local hum = lp.Character and lp.Character:FindFirstChild("Humanoid")
        if hum and propsTool.Parent ~= lp.Character then
            hum:EquipTool(propsTool)
            task.wait(0.2)
        end

        local toolPropMake = propsTool:FindFirstChild("Tool_PropMake") or propsTool:WaitForChild("Tool_PropMake", 3)
            if not toolPropMake then return end

        unicornParts = {}
        uNotif("Summoning the unicorn... ("..#blueprint.." parts, ~"..#blueprint.."s)", 5)

        for idx, bp in ipairs(blueprint) do
            if not unicornActive then break end

            local spawnPos = (lp.Character and lp.Character:FindFirstChild("HumanoidRootPart") and lp.Character.HumanoidRootPart.Position) or Vector3.new(0,5,0)
            local offsetSpawn = Vector3.new(math.cos(idx)*4, 3, math.sin(idx)*4)

            
            pcall(function() Telemetry:FireServer("filterClick", {name=bp.cat,  itemType="Props"}) end)
            task.wait(0.05)
            pcall(function() Telemetry:FireServer("filterClick", {name=bp.prop, itemType="Props"}) end)
            task.wait(0.05)
            pcall(function() if bp.prop == "FloorCushion" then clearTools:FireServer("RequestingPropFeatureName", bp.prop, bp.cat) else clearTools:FireServer("RequestingPropName", bp.prop, bp.cat) end end)
            task.wait(0.1)

            
            pcall(function() toolPropMake:FireServer(workspace.Terrain, spawnPos + offsetSpawn) end)
            task.wait(0.85)

            if not unicornActive then break end

            
            local myPropName = "Prop" .. lp.Name
            local found = false
            for _, folder in pairs(workspace:WaitForChild("WorkspaceCom"):GetChildren()) do
                if found then break end
                for _, prop in pairs(folder:GetChildren()) do
                    if prop.Name == myPropName then
                        local scf = prop:FindFirstChild("SetCurrentCFrame")
                        local cpc = prop:FindFirstChild("ChangePropColor")
                        if scf then
                            local alreadyHave = false
                            for _, p in ipairs(unicornParts) do
                                if p.scf == scf then alreadyHave = true break end
                            end
                            if not alreadyHave then
                                
                                if cpc and bp.color then
                                    pcall(function() cpc:InvokeServer(bp.color) end)
                                end
                                table.insert(unicornParts, {key=bp.key, scf=scf, cpc=cpc, blueprint=bp, propModel=prop})
                                found = true
                                break
                            end
                        end
                    end
                end
            end
        end

        for _, _p in ipairs(unicornParts) do uStream:add(_p.scf, _p.cpc) end
        uStream:start()
        _0xH_3f1()
                uNotif("Unicorn ready! It is waiting for you on the ground. Climb on!", 5)
    end

