    local function isDriverSitting()
        local h = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
        if not h then return false end
        for _, p in ipairs(unicornParts) do
            if p.key == "selle" and p.propModel then
                for _, child in pairs(p.propModel:GetDescendants()) do
                    if child:IsA("Seat") and child.Occupant == h then
                        return true
                    end
                end
            end
        end
        return false
    end
    
    local function isAnyoneSitting()
        for _, p in ipairs(unicornParts) do
            if (p.key == "selle" or p.key == "passagers") and p.propModel then
                for _, child in pairs(p.propModel:GetDescendants()) do
                    if child:IsA("Seat") and child.Occupant ~= nil then
                        return true
                    end
                end
            end
        end
        return false
    end
    
    local function _0xH_41d(bpKey, t2)
        
        if bpKey:sub(1,5) == "patte" then
            if bpKey:sub(7,8) == "av" then
                return CFrame.Angles(math.rad(70), 0, 0)
            else
                return CFrame.Angles(math.rad(-70), 0, 0)
            end
        elseif bpKey:sub(1,4) == "aile" then
            return CFrame.Angles(0, 0, 0)
        elseif bpKey:sub(1,3) == "cou" or bpKey == "tete" or bpKey == "corne" or bpKey == "oeil" then
            return CFrame.new(0, math.sin(t2*2)*0.2 - 2, 0)
        else
            return CFrame.new(0, math.sin(t2*2)*0.2 - 3, 0)
        end
    end

    
    
    
    local function startUnicornLoop()
        local lp  = game:GetService("Players").LocalPlayer
        local RS  = game:GetService("RunService")
        local t   = 0
        local _0xH_436 = 0
        local lastUpdate = 0
        
        local rideState = "resting"
        local waitStartTime = 0
        local flightTime = 0
        local flightDistance = 0
        local returnStartCF = nil
        
        local myRoot = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
        local spawnOrigin = myRoot and myRoot.CFrame or CFrame.new(0,5,0)
        spawnOrigin = CFrame.new(spawnOrigin.Position) * CFrame.Angles(0, math.rad(90), 0)
        local orbitCenter = spawnOrigin.Position

        
        local currentVelocity = 0
        local unicornWorldPos = spawnOrigin.Position
        local currentYaw = 0
        local unicornTargetWp = nil
        local currentPitch = 0
        local currentBank = 0
        local uis = game:GetService("UserInputService")
        local ws = game:GetService("Workspace")

        unicornLoop = RS.RenderStepped:Connect(function(dt)
            if not unicornActive then return end
            local _uNow = tick(); if _uNow - lastUpdate < (1/24) then return end; lastUpdate = _uNow 

            t = t + dt
            local unicornCF
            local useFolded = false

            unicornCF = spawnOrigin * CFrame.new(0, 1, 0)

            if rideState == "resting" then
                useFolded = true
                
                if isDriverSitting() then
                    setupUnicornGUI()
                    rideState = "manual_ground"
                    waitStartTime = tick()
                    uNotif("Unicorn tamed! WASD to walk, SHIFT to run, SPACE to take off.", 6)
                    
                    local _, yaw, _ = spawnOrigin:ToEulerAnglesYXZ()
                    currentYaw = yaw
                    currentPitch = 0
                    currentBank = 0
                    currentVelocity = 0
                    unicornWorldPos = unicornCF.Position
                elseif unicornForceTakeoff then
                    unicornForceTakeoff = false
                    rideState = "auto_flight"
                    flightTime = 0
                    flightDistance = 0
                    uNotif("Auto-ride started! Enjoy the view.", 5)
                elseif isAnyoneSitting() then
                    rideState = "waiting"
                    uNotif("Passenger seated! Climb on the throne to drive or click 'Take Off'.", 5)
                end

            elseif rideState == "waiting" then
                useFolded = false 
                
                if isDriverSitting() then
                    setupUnicornGUI()
                    rideState = "manual_ground"
                    waitStartTime = tick()
                    uNotif("Unicorn tamed! WASD to walk, SHIFT to run, SPACE to take off.", 6)
                    
                    local _, yaw, _ = spawnOrigin:ToEulerAnglesYXZ()
                    currentYaw = yaw
                    currentPitch = 0
                    currentBank = 0
                    currentVelocity = 0
                    unicornWorldPos = unicornCF.Position
                elseif unicornForceTakeoff then
