    local function getLeviathanPartColor(layout, partIndex, t, state, colorMode)
        local pulse = (math.sin(t * 6) + 1) * 0.5
        local _0xH_42c  = (math.sin(t * 4 + partIndex * 0.45) + 1) * 0.5

        if state == "roar" then
            if layout.key == "breath" then
                return Color3.fromRGB(255, 120, 20)
            end
            return Color3.fromRGB(math.floor(20 + pulse * 30), math.floor(160 + pulse * 90), 255)
        elseif state == "strike" then
            if layout.key == "jaw_lower" or layout.key == "head_upper" then
                return Color3.fromRGB(220, 30, 40)
            end
        elseif state == "sprint" then
            if layout.key == "tail_fluke" or layout.key == "head_crown" or layout.key == "breath" then
                local speedPulse = (math.sin(t * 16) + 1) * 0.5
                return Color3.fromRGB(0, math.floor(220 + speedPulse * 35), 255)
            end
        elseif state == "breach" then
            local p = math.clamp(stateTimer / 6.0, 0, 1)
            if p < 0.50 then
                local waveP = (math.sin(t * 16 + partIndex * 0.7) + 1) * 0.5
                if layout.key == "breath" then
                    return Color3.fromRGB(0, 180, 255)
                end
                return Color3.fromRGB(math.floor(5 + waveP * 15), math.floor(60 + waveP * 100), math.floor(140 + waveP * 90))
            elseif p < 0.78 then
                if layout.key == "breath" then
                    return Color3.fromRGB(255, 160, 40)
                elseif layout.key == "head_crown" or layout.key == "head_upper" or layout.key == "neck_arch" then
                    return Color3.fromRGB(210, 250, 255)
                else
                    local breachWave = (math.sin(t * 22 + partIndex * 0.5) + 1) * 0.5
                    return Color3.fromRGB(math.floor(20 + breachWave * 30), math.floor(200 + breachWave * 55), 255)
                end
            else
                local splashH = (p - 0.78) / 0.22
                return Color3.fromRGB(0, math.floor(180 + (1 - splashH) * 60), math.floor(220 + (1 - splashH) * 35))
            end
        end

        if colorMode == "Abyssal Cyan" then
            if layout.key == "head_crown" or layout.key == "neck_arch" or layout.key == "tail_fluke" then
                return Color3.new(0.05 + _0xH_42c * 0.1, 0.45 + _0xH_42c * 0.35, 0.75 + _0xH_42c * 0.2)
            elseif layout.key == "breath" then
                return Color3.fromRGB(0, math.floor(220 + pulse * 35), 255)
            else
                return Color3.new(0.02 + _0xH_42c * 0.05, 0.25 + _0xH_42c * 0.2, 0.45 + _0xH_42c * 0.25)
            end
        elseif colorMode == "Magma Titan" then
            if layout.key == "breath" or layout.key == "head_crown" then
                return Color3.fromRGB(255, math.floor(70 + pulse * 60), 0)
            elseif layout.key == "jaw_lower" or layout.key == "tail_fluke" then
                return Color3.fromRGB(220, math.floor(30 + _0xH_42c * 40), 10)
            else
                return Color3.fromRGB(math.floor(40 + _0xH_42c * 25), 10, 10)
            end
        elseif colorMode == "Shadow Void" then
            if layout.key == "breath" then
                return Color3.fromRGB(180, 0, 255)
            elseif layout.key == "head_crown" or layout.key == "tail_fluke" then
                return Color3.fromRGB(100, 0, 180)
            else
                return Color3.fromRGB(math.floor(12 + _0xH_42c * 10), math.floor(12 + _0xH_42c * 10), math.floor(20 + _0xH_42c * 15))
            end
        elseif colorMode == "Rainbow Overdrive" then
            local hue = (t * 0.25 + partIndex * 0.065) % 1
            return Color3.fromHSV(hue, 0.85, 0.95)
        elseif colorMode == "Toxic Emerald" then
            if layout.key == "breath" then
                return Color3.fromRGB(80, 255, 40)
            elseif layout.key == "head_crown" or layout.key == "tail_fluke" then
                return Color3.fromRGB(40, 220, 80)
            else
                return Color3.fromRGB(10, math.floor(45 + _0xH_42c * 40), 20)
            end
        end
        return Color3.fromRGB(10, 80, 140)
    end

    
    
    
    
    local function _0xH_3ec(layout, t, state, stateTimer, anchor, angle, slitherW, turnBank)
        local rootCF = CFrame.new(anchor) * CFrame.Angles(0, angle, 0)
        local w = slitherW or 0.0

        local rOff = layout.off
        local sOff = layout.slitherOff or rOff
        local basePos = rOff:Lerp(sOff, w)

        local rRot = layout.rot or CFrame.new()
        local sRot = layout.slitherRot or rRot
        local baseRot = rRot:Lerp(sRot, w)

        local animOff = Vector3.new(0, 0, 0)
        local animRot = CFrame.new()

        local key = layout.key
        local k = layout.spineIndex or 0

        if state == "sprint" or state == "walk" then
            local _0xH_433 = (state == "sprint")
            local freq = _0xH_433 and 6.6 or 3.8
            local lambdaZ = 0.082
            local segZ = basePos.Z
            local _0xH_424 = t * freq - lambdaZ * (segZ + 16.5)

            
            local curAmp = 0.55
            if segZ <= -12.5 then
                curAmp = 0.55 
            elseif segZ <= 0.0 then
                curAmp = 0.55 + 1.95 * ((segZ + 12.5) / 12.5) 
            elseif segZ <= 14.0 then
                curAmp = 2.5 + 2.0 * (segZ / 14.0) 
            else
                curAmp = 4.5 + 1.7 * ((segZ - 14.0) / 14.0) 
            end

            if not _0xH_433 then
                curAmp = curAmp * 0.65
            end

            
            local waveX = math.sin(_0xH_424) * curAmp

            
            local waveY = math.cos(_0xH_424 * 2) * (_0xH_433 and 0.42 or 0.22)

            
            local slope = curAmp * lambdaZ * math.cos(_0xH_424)
            local waveZ = -(slope * slope) * 1.15 + math.cos(_0xH_424 * 2) * (_0xH_433 and 0.35 or 0.15)

            
            local waveYaw = math.atan(slope) * 1.15

            
            local bankLean = turnBank or 0
            local waveRoll = math.sin(_0xH_424) * math.rad(6.5) + bankLean

            
            local wavePitch = math.sin(_0xH_424 * 2) * math.rad(2.5)

            animOff = Vector3.new(waveX, waveY, waveZ)
            animRot = CFrame.Angles(wavePitch, waveYaw, waveRoll)

            if key == "jaw_lower" then
                local sprintJaw = _0xH_433 and math.rad(18 + math.sin(_0xH_424 * 2) * 8) or math.rad(6)
                animRot = animRot * CFrame.Angles(sprintJaw, 0, 0)
            end

        elseif state == "idle" then
            local breatheSpeed = 1.8
            local swaySpeed = 1.1

            if k >= 1 and k <= 7 then
                local prog = k / 7
                local bY = math.sin(t * breatheSpeed - prog * 0.8) * (0.2 + prog * 0.5)
                local sX = math.sin(t * swaySpeed - prog * 1.1) * (0.3 + prog * 0.8)
                local pPitch = math.cos(t * breatheSpeed - prog * 0.8) * math.rad(1.5 + prog * 2)
                local pYaw = math.cos(t * swaySpeed - prog * 1.1) * math.rad(2 + prog * 3)
                animOff = Vector3.new(sX, bY, 0)
                animRot = CFrame.Angles(pPitch, pYaw, 0)

            elseif key == "throne" then
                local bY = math.sin(t * breatheSpeed - 0.8) * 0.7
                local sX = math.sin(t * swaySpeed - 1.1) * 1.1
                local pPitch = math.cos(t * breatheSpeed - 0.8) * math.rad(3.5)
                local pYaw = math.cos(t * swaySpeed - 1.1) * math.rad(5)
                animOff = Vector3.new(sX, bY, 0)
                animRot = CFrame.Angles(pPitch, pYaw, 0)

            elseif key == "head_upper" or key == "head_crown" or key == "breath" then
                local bY = math.sin(t * breatheSpeed - 1.0) * 0.75
                local sX = math.sin(t * swaySpeed - 1.3) * 1.2
                local headNod = math.cos(t * breatheSpeed) * math.rad(3)
                local headScan = math.sin(t * 0.8) * math.rad(4.5)
                animOff = Vector3.new(sX, bY, 0)
                animRot = CFrame.Angles(headNod, headScan, 0)

            elseif key == "jaw_lower" then
                local bY = math.sin(t * breatheSpeed - 1.0) * 0.75
                local sX = math.sin(t * swaySpeed - 1.3) * 1.2
                local jawCycle = (math.sin(t * breatheSpeed) + 1) * 0.5
                local jawAngle = math.rad(3 + jawCycle * 9)
                animOff = Vector3.new(sX, bY - jawCycle * 0.6, 0)
                animRot = CFrame.Angles(jawAngle, math.sin(t * 0.8) * math.rad(4.5), 0)

            elseif key == "tail_stem" then
                local _0xH_42c = math.sin(t * 2.2 - 0.8) * 1.0
                animOff = Vector3.new(_0xH_42c, 0, 0)
                animRot = CFrame.Angles(0, math.cos(t * 2.2 - 0.8) * math.rad(7), 0)

            elseif key == "tail_mid" then
                local _0xH_42c = math.sin(t * 2.2 - 1.6) * 1.8
                animOff = Vector3.new(_0xH_42c, 0, 0)
                animRot = CFrame.Angles(0, math.cos(t * 2.2 - 1.6) * math.rad(14), 0)

            elseif key == "tail_fluke" then
                local _0xH_42c = math.sin(t * 2.2 - 2.4) * 2.6
                animOff = Vector3.new(_0xH_42c, 0, 0)
                animRot = CFrame.Angles(0, math.cos(t * 2.2 - 2.4) * math.rad(22), 0)
            end

        elseif state == "roar" then
            local p = math.clamp(stateTimer / 3.5, 0, 1)
            local env = math.sin(p * math.pi)

            if k >= 1 and k <= 7 then
                local prog = k / 7
                local lift = env * prog * 4.0
                local leanBack = env * prog * 3.5
                local pitchBack = -math.rad(env * prog * 16)
                animOff = Vector3.new(0, lift, leanBack)
                animRot = CFrame.Angles(pitchBack, 0, 0)

            elseif key == "throne" then
                local lift = env * 4.0
                local leanBack = env * 3.5
                local pitchBack = -math.rad(env * 16)
                animOff = Vector3.new(0, lift, leanBack)
                animRot = CFrame.Angles(pitchBack, 0, 0)

            elseif key == "head_upper" or key == "head_crown" or key == "breath" then
                local lift = env * 5.0
                local leanBack = env * 4.5
                local pitchBack = -math.rad(env * 32)
                animOff = Vector3.new(0, lift, leanBack)
                animRot = CFrame.Angles(pitchBack, 0, 0)

            elseif key == "jaw_lower" then
                local lift = env * 2.5
                local leanBack = env * 4.0
                local jawOpen = math.rad(env * 42)
                animOff = Vector3.new(0, lift - env * 1.5, leanBack)
                animRot = CFrame.Angles(jawOpen, 0, 0)

            elseif key == "tail_stem" or key == "tail_mid" or key == "tail_fluke" then
                local tK = (key == "tail_stem" and 1) or (key == "tail_mid" and 2) or 3
                animOff = Vector3.new(0, 0, -env * tK * 0.8)
                animRot = CFrame.Angles(math.rad(env * 10), 0, 0)
            end

        elseif state == "strike" then
            local p = math.clamp(stateTimer / 2.2, 0, 1)
            if p < 0.28 then
                local prep = math.sin((p / 0.28) * (math.pi / 2))
                if k >= 4 or key == "head_upper" or key == "jaw_lower" or key == "head_crown" or key == "breath" or key == "throne" then
                    animOff = Vector3.new(0, prep * 2.0, prep * 3.0)
                    animRot = CFrame.Angles(-math.rad(prep * 14), 0, 0)
                end
            elseif p < 0.65 then
                local snapFrac = (p - 0.28) / 0.37
                local snap = math.sin(snapFrac * math.pi)

                if k >= 4 then
                    local prog = (k - 3) / 4
                    local lungeY = -snap * prog * 8.0
                    local lungeZ = -snap * prog * 6.0
                    animOff = Vector3.new(0, lungeY, lungeZ)
                    animRot = CFrame.Angles(math.rad(snap * 18), 0, 0)

                elseif key == "head_upper" or key == "head_crown" or key == "breath" or key == "throne" then
                    local lungeY = -snap * 14.0
                    local lungeZ = -snap * 10.0
                    animOff = Vector3.new(0, lungeY, lungeZ)
                    animRot = CFrame.Angles(math.rad(snap * 26), 0, 0)

                elseif key == "jaw_lower" then
                    local lungeY = -snap * 16.0
                    local lungeZ = -snap * 10.0
                    local jawAngle = (snapFrac > 0.5) and -math.rad(10) or math.rad(34)
                    animOff = Vector3.new(0, lungeY, lungeZ)
                    animRot = CFrame.Angles(math.rad(snap * 26) + jawAngle, 0, 0)
                end
            else
                local rec = 1 - (p - 0.65) / 0.35
                if k >= 4 or key == "head_upper" or key == "jaw_lower" or key == "head_crown" or key == "breath" or key == "throne" then
                    animOff = Vector3.new(0, -rec * 2.0, -rec * 2.0)
                end
            end

        elseif state == "kneel" then
            local p = math.clamp(stateTimer * 1.5, 0, 1)
            local kneelP = p * p * (3 - 2 * p)

            if k >= 3 then
                local prog = (k - 2) / 5
                local bowY = -kneelP * prog * 20.0
                local bowZ = -kneelP * prog * 3.0
                animOff = Vector3.new(0, bowY, bowZ)
                animRot = CFrame.Angles(math.rad(kneelP * prog * 25), 0, 0)

            elseif key == "head_upper" or key == "jaw_lower" or key == "head_crown" or key == "breath" then
                local bowY = -kneelP * 21.5
                animOff = Vector3.new(0, bowY, -kneelP * 4.0)
                animRot = CFrame.Angles(math.rad(kneelP * 30), 0, 0)

            elseif key == "throne" then
                local bowY = -kneelP * 22.0
                animOff = Vector3.new(0, bowY, -kneelP * 3.5)
                animRot = CFrame.Angles(math.rad(kneelP * 15), 0, 0)
            end

        elseif state == "breach" then
            local p = math.clamp(stateTimer / 6.0, 0, 1)
            local bSubY = 0
            local bPitch = 0
            local bJawAngle = 0
            local bShake = 0

            if p < 0.32 then
                local f = p / 0.32
                bSubY = -38 * math.sin(f * (math.pi / 2))
                bPitch = -math.rad(50 * math.sin(f * (math.pi / 2)))
                bJawAngle = math.rad(30 * math.sin(f * math.pi))

            elseif p < 0.50 then
                local f = (p - 0.32) / 0.18
                bSubY = -38 - 4 * math.sin(f * math.pi)
                bPitch = math.rad(-50 + 105 * f)
                bJawAngle = math.rad(15 + 20 * f)

            elseif p < 0.78 then
                local f = (p - 0.50) / 0.28
                bSubY = -38 + 86 * math.sin(f * (math.pi / 2))
                bPitch = math.rad(55 - 25 * f)
                bJawAngle = math.rad(35 + 30 * math.sin(f * math.pi))
                bShake = math.sin(t * 45) * (0.35 * math.sin(f * math.pi))

            else
                local f = (p - 0.78) / 0.22
                local h = 1 - (f * f * (3 - 2 * f))
                bSubY = 48 * h
                bPitch = math.rad(30 * h - 15 * math.sin(f * math.pi))
                bJawAngle = math.rad(8 + 15 * h)
            end

            local shakeOff = (bShake > 0) and Vector3.new(bShake, bShake, bShake) or Vector3.new(0, 0, 0)
            animOff = Vector3.new(0, bSubY, 0) + shakeOff
            animRot = CFrame.Angles(bPitch, 0, 0)

            if key == "jaw_lower" then
                animRot = animRot * CFrame.Angles(bJawAngle, 0, 0)
            end
        end

        return rootCF * CFrame.new(basePos + animOff) * baseRot * animRot
    end

    
    
    
    local function setupPilotHUD()
        if pilotGui then pcall(function() pilotGui:Destroy() end) pilotGui = nil end

        local parent = (gethui and gethui()) or game:GetService("CoreGui") or lp:FindFirstChildOfClass("PlayerGui")
        pilotGui = Instance.new("ScreenGui")
        pilotGui.Name = "BTR_LeviathanHUD"
        pilotGui.ResetOnSpawn = false
        pilotGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling

        local frame = Instance.new("Frame")
        frame.Name = "MainFrame"
        frame.AnchorPoint = Vector2.new(0.5, 1)
        frame.Position = UDim2.new(0.5, 0, 1, -15)
        frame.Size = UDim2.new(0, 530, 0, 86)
        frame.BackgroundColor3 = Color3.fromRGB(12, 16, 24)
        frame.BackgroundTransparency = 0.15
        frame.Visible = false
        frame.Parent = pilotGui
        hudFrame = frame

        local corner = Instance.new("UICorner")
