        stroke.Transparency = 0.35
        stroke.Parent = frame

        local header = Instance.new("Frame")
        header.Name = "Header"
        header.Size = UDim2.new(1, 0, 0, 24)
        header.BackgroundTransparency = 1
        header.Parent = frame

        local titleLabel = Instance.new("TextLabel")
        titleLabel.Size = UDim2.new(0.48, 0, 1, 0)
        titleLabel.Position = UDim2.new(0, 12, 0, 0)
        titleLabel.BackgroundTransparency = 1
        titleLabel.Text = "LEVIATHAN PILOT CONTROLS"
        titleLabel.TextColor3 = Color3.fromRGB(0, 215, 255)
        titleLabel.Font = Enum.Font.GothamBold
        titleLabel.TextSize = 11
        titleLabel.TextXAlignment = Enum.TextXAlignment.Left
        titleLabel.Parent = header

        hudStatusLabel = Instance.new("TextLabel")
        hudStatusLabel.Size = UDim2.new(0.48, 0, 1, 0)
        hudStatusLabel.Position = UDim2.new(0.5, -12, 0, 0)
        hudStatusLabel.BackgroundTransparency = 1
        hudStatusLabel.Text = "STATUS: HOVERING"
        hudStatusLabel.TextColor3 = Color3.fromRGB(180, 220, 255)
        hudStatusLabel.Font = Enum.Font.GothamSemibold
        hudStatusLabel.TextSize = 10
        hudStatusLabel.TextXAlignment = Enum.TextXAlignment.Right
        hudStatusLabel.Parent = header

        local btnContainer = Instance.new("Frame")
        btnContainer.Name = "ButtonContainer"
        btnContainer.Position = UDim2.new(0, 8, 0, 26)
        btnContainer.Size = UDim2.new(1, -16, 0, 52)
        btnContainer.BackgroundTransparency = 1
        btnContainer.Parent = frame

        local listLayout = Instance.new("UIListLayout")
        listLayout.FillDirection = Enum.FillDirection.Horizontal
        listLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
        listLayout.VerticalAlignment = Enum.VerticalAlignment.Center
        listLayout.Padding = UDim.new(0, 6)
        listLayout.Parent = btnContainer

        local function makeBtn(name, keyText, actText, bgColor, width, strokeColor, onClick, onDown, onUp)
            local btn = Instance.new("TextButton")
            btn.Name = name
            btn.Size = UDim2.new(0, width or 64, 0, 46)
            btn.BackgroundColor3 = bgColor
            btn.AutoButtonColor = true
            btn.Text = ""
            btn.Parent = btnContainer

            local bCorner = Instance.new("UICorner")
            bCorner.CornerRadius = UDim.new(0, 8)
            bCorner.Parent = btn

            local bStroke = Instance.new("UIStroke")
            bStroke.Color = strokeColor or Color3.fromRGB(255, 255, 255)
            bStroke.Transparency = strokeColor and 0.25 or 0.8
            bStroke.Thickness = strokeColor and 1.5 or 1
            bStroke.Parent = btn

            local kLbl = Instance.new("TextLabel")
            kLbl.Size = UDim2.new(1, 0, 0.45, 0)
            kLbl.BackgroundTransparency = 1
            kLbl.Text = keyText
            kLbl.TextColor3 = strokeColor or Color3.fromRGB(0, 220, 255)
            kLbl.Font = Enum.Font.GothamBold
            kLbl.TextSize = 11
            kLbl.Parent = btn

            local aLbl = Instance.new("TextLabel")
            aLbl.Size = UDim2.new(1, 0, 0.5, 0)
            aLbl.Position = UDim2.new(0, 0, 0.45, 0)
            aLbl.BackgroundTransparency = 1
            aLbl.Text = actText
            aLbl.TextColor3 = Color3.fromRGB(240, 240, 240)
            aLbl.Font = Enum.Font.GothamMedium
            aLbl.TextSize = 10
            aLbl.Parent = btn

            if onClick then
                btn.Activated:Connect(onClick)
            end
            if onDown then
                btn.MouseButton1Down:Connect(onDown)
                btn.InputBegan:Connect(function(inp)
                    if inp.UserInputType == Enum.UserInputType.Touch then onDown() end
                end)
            end
            if onUp then
                btn.MouseButton1Up:Connect(onUp)
                btn.InputEnded:Connect(function(inp)
                    if inp.UserInputType == Enum.UserInputType.Touch then onUp() end
                end)
            end

            return btn
        end

        makeBtn("AscendBtn", "[Space]", "Ascend", Color3.fromRGB(18, 45, 65), 62, nil, nil,
            function() isAscendingHeld = true end,
            function() isAscendingHeld = false end
        )

        makeBtn("DiveBtn", "[Ctrl]", "Dive", Color3.fromRGB(25, 30, 55), 62, nil, nil,
            function() isDescendingHeld = true end,
            function() isDescendingHeld = false end
        )

        makeBtn("SprintBtn", "[Shift]", "Sprint", Color3.fromRGB(12, 55, 60), 62, nil,
            function()
                isSprintToggled = not isSprintToggled
                lNotif(isSprintToggled and "Serpentine Slither Sprint: ON!" or "Cruising slither restored.", 2)
            end
        )

        makeBtn("BreachBtn", "[R]", "Breach", Color3.fromRGB(8, 70, 115), 78, Color3.fromRGB(0, 240, 255),
            function()
                triggerBreach()
            end
        )

        makeBtn("RoarBtn", "[E]", "Roar", Color3.fromRGB(55, 32, 15), 62, nil,
            function()
                if canDo("roar", 4) then
                    leviathanState = "roar"
                    leviathanStateTimer = 0
                    lNotif("ABYSSAL ROAR!", 2)
                end
            end
        )

        makeBtn("StrikeBtn", "[F]", "Strike", Color3.fromRGB(58, 20, 22), 62, nil,
            function()
                if canDo("strike", 3) then
                    leviathanState = "strike"
                    leviathanStateTimer = 0
                    lNotif("TITANIC STRIKE!", 2)
                end
            end
        )

        makeBtn("DismountBtn", "[Q]", "Exit", Color3.fromRGB(45, 20, 26), 56, nil,
            function()
                local hum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
                if hum then hum.Sit = false end
            end
        )

        pcall(function() pilotGui.Parent = parent end)

        local UIS = game:GetService("UserInputService")
        if inputConn then pcall(function() inputConn:Disconnect() end) inputConn = nil end
        inputConn = UIS.InputBegan:Connect(function(input, gpe)
            if gpe or not leviathanActive then return end
            local myHum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
            local isRiding = (leviathanDriverSeat and myHum and leviathanDriverSeat.Occupant == myHum) or (myHum and myHum.Sit)
            if not isRiding then return end

            if input.KeyCode == Enum.KeyCode.E then
                if canDo("roar", 4) then
                    leviathanState = "roar"
                    leviathanStateTimer = 0
                    lNotif("ABYSSAL ROAR!", 2)
                end
            elseif input.KeyCode == Enum.KeyCode.F then
                if canDo("strike", 3) then
                    leviathanState = "strike"
                    leviathanStateTimer = 0
                    lNotif("TITANIC STRIKE!", 2)
                end
            elseif input.KeyCode == Enum.KeyCode.R then
                triggerBreach()
            elseif input.KeyCode == Enum.KeyCode.LeftShift then
                isSprintToggled = not isSprintToggled
                lNotif(isSprintToggled and "Serpentine Slither Sprint: ON (68 studs/s)!" or "Cruising slither restored (30 studs/s).", 1.5)
            elseif input.KeyCode == Enum.KeyCode.Q then
                if myHum and myHum.Sit == true then myHum.Sit = false end
            end
        end)
    end

    
    local function startLeviathanWorkers(w)
        if w.scf then
            task.spawn(function()
                while leviathanActive and w.scf do
                    local now = tick()
                    if w.targetCF then
                        local cf = w.targetCF
                        local sendCF = false
                        if not w.lastSentCF then
                            sendCF = true
                        else
                            local posDiff = (cf.Position - w.lastSentCF.Position).Magnitude
                            local rotDiff = math.abs(cf.LookVector.X - w.lastSentCF.LookVector.X)
                                          + math.abs(cf.LookVector.Y - w.lastSentCF.LookVector.Y)
                                          + math.abs(cf.LookVector.Z - w.lastSentCF.LookVector.Z)
                            if posDiff > 0.06 or rotDiff > 0.04 or (now - w.lastSendTimeCF > 0.12) then
                                sendCF = true
                            end
                        end
                        if sendCF then
                            w.lastSentCF = cf
                            w.lastSendTimeCF = now
                            pcall(function() w.scf:InvokeServer(cf) end)
                        end
                    end
                    task.wait(0.03)
                end
            end)
        end

        if w.cpc then
            task.spawn(function()
                while leviathanActive and w.cpc do
                    local now = tick()
                    if w.targetColor then
                        local col = w.targetColor
                        local sendCol = false
                        if not w.lastSentColor then
                            sendCol = true
                        else
                            local diff = math.abs(col.R - w.lastSentColor.R) + math.abs(col.G - w.lastSentColor.G) + math.abs(col.B - w.lastSentColor.B)
                            if diff > 0.04 or (now - w.lastSendTimeCol > 0.35) then
                                sendCol = true
                            end
                        end
                        if sendCol then
                            w.lastSentColor = col
                            w.lastSendTimeCol = now
                            pcall(function() w.cpc:InvokeServer(col) end)
                        end
                    end
                    task.wait(0.05)
                end
            end)
        end
    end

    
    local function spawnLeviathan()
        local char = lp.Character or lp.CharacterAdded:Wait()
        local hrp = char:WaitForChild("HumanoidRootPart")

        lNotif("Summoning the 30-Stud Abyssal Leviathan...", 4)

        local RE = game:GetService("ReplicatedStorage"):WaitForChild("RE")
        local clearTools = RE:WaitForChild("1Clea1rTool1s")
        local myPropName = "Prop" .. lp.Name

        pcall(function() clearTools:FireServer("ClearAllProps") end)
        task.wait(0.5)

        local propsTool = _0xH_3f2()
        if not propsTool then
            lNotif("Error: PropMaker not found!", 4)
            return
        end

        local humanoid = char:FindFirstChildOfClass("Humanoid")
        if humanoid then humanoid:EquipTool(propsTool) end
        task.wait(0.4)

        local toolPropMake = propsTool:FindFirstChild("Tool_PropMake") or propsTool:WaitForChild("Tool_PropMake", 3)
        if not toolPropMake then return end

        pcall(function() clearTools:FireServer("OpenPropMenu") end)
        task.wait(0.2)

        leviathanAnchor = hrp.Position + (hrp.CFrame.LookVector * 18) + Vector3.new(0, 2, 0)
        leviathanAngle = math.atan2(-hrp.CFrame.LookVector.X, -hrp.CFrame.LookVector.Z)
        leviathanWorkers = {}
        leviathanDriverSeat = nil
        leviathanAnimT = 0
        leviathanState = "idle"
        leviathanMode = "manual"
        leviathanSlitherWeight = 0

        local knownScf = {}
        for _, folder in pairs(workspace:WaitForChild("WorkspaceCom"):GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName then
                    local scf = prop:FindFirstChild("SetCurrentCFrame")
                    if scf then knownScf[scf] = true end
                end
            end
        end

        local hitInst = workspace.Terrain
        local Telemetry = game:GetService("ReplicatedStorage"):WaitForChild("Remotes"):WaitForChild("TelemetryClientInteraction")

        for i, layout in ipairs(LEVIATHAN_LAYOUT) do
            if not leviathanActive then break end

            local targetCF = _0xH_3ec(layout, 0, "idle", 0, leviathanAnchor, leviathanAngle, 0)
            local defaultColor = getLeviathanPartColor(layout, i, 0, "idle", leviathanColorMode)

            pcall(function() Telemetry:FireServer("filterClick", {name=layout.cat,  itemType="Props"}) end)
            task.wait(0.04)
            pcall(function() Telemetry:FireServer("filterClick", {name=layout.prop, itemType="Props"}) end)
            task.wait(0.04)
            pcall(function() clearTools:FireServer("RequestingPropName", layout.prop, layout.cat) end)
            task.wait(0.18)

            pcall(function() toolPropMake:FireServer(hitInst, leviathanAnchor) end)
            task.wait(0.55)

            local foundProp, foundScf, foundCpc, foundSeat = nil, nil, nil, nil
            for _, folder in pairs(workspace:WaitForChild("WorkspaceCom"):GetChildren()) do
                for _, prop in pairs(folder:GetChildren()) do
                    if prop.Name == myPropName then
                        local scf = prop:FindFirstChild("SetCurrentCFrame")
                        local cpc = prop:FindFirstChild("ChangePropColor")
                        if scf and not knownScf[scf] then
                            foundProp = prop
                            foundScf = scf
                            foundCpc = cpc
                            knownScf[scf] = true
                            if layout.key == "throne" then
                                foundSeat = prop:FindFirstChildWhichIsA("Seat", true) or prop:FindFirstChildWhichIsA("VehicleSeat", true)
                            end
                            break
                        end
                    end
                end
                if foundScf then break end
            end

            if foundSeat then
                leviathanDriverSeat = foundSeat
            end

            local w = {
                key = layout.key,
                layout = layout,
                prop = foundProp,
                scf = foundScf,
                cpc = foundCpc,
                partIndex = i,
                targetCF = targetCF,
                lastSentCF = nil,
                lastSendTimeCF = 0,
                targetColor = defaultColor,
                lastSentColor = nil,
                lastSendTimeCol = 0
            }

            leviathanWorkers[layout.key] = w

            if foundScf then
                pcall(function() foundScf:InvokeServer(targetCF) end)
            end
            if foundCpc then
                pcall(function() foundCpc:InvokeServer(defaultColor) end)
            end

            startLeviathanWorkers(w)
        end

        task.wait(1)
        pcall(function()
            game:GetService("ReplicatedStorage"):WaitForChild("RE"):WaitForChild("1Too1l"):InvokeServer("PickingTools", "PropMaker")
        end)
        pcall(function() clearTools:FireServer("ClosePropMenu") end)

        pcall(function()
            local b = lp:FindFirstChildOfClass("Backpack")
            if b then
                for _, t in pairs(b:GetChildren()) do
                    if t:IsA("Tool") and t.Name == "PropMaker" then t:Destroy() end
                end
            end
            if char then
                for _, t in pairs(char:GetChildren()) do
                    if t:IsA("Tool") and t.Name == "PropMaker" then t:Destroy() end
                end
            end
        end)

        setupPilotHUD()
        lNotif("30-Stud Leviathan Titan Assembled and Online!", 5)
    end

    local function startLeviathanLoop()
        local RS = game:GetService("RunService")
        local UIS = game:GetService("UserInputService")
        local rayParams = RaycastParams.new()
        rayParams.FilterType = Enum.RaycastFilterType.Exclude

        leviathanLoop = RS.Heartbeat:Connect(function(dt)
            if not leviathanActive then return end

            leviathanAnimT = leviathanAnimT + dt
            leviathanStateTimer = leviathanStateTimer + dt

            local myHum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
            local isRiding = (leviathanDriverSeat and myHum and leviathanDriverSeat.Occupant == myHum) or (myHum and myHum.Sit)

            if leviathanState == "roar" and leviathanStateTimer > 3.5 then
                leviathanState = "idle"
                leviathanStateTimer = 0
            elseif leviathanState == "strike" and leviathanStateTimer > 2.2 then
                leviathanState = "idle"
                leviathanStateTimer = 0
            elseif leviathanState == "breach" then
                if leviathanStateTimer >= 3.0 and not leviathanBreachedNotif then
                    leviathanBreachedNotif = true
                    lNotif("TITANIC ABYSSAL BREACH! ERUPTING INTO THE HEAVENS!", 3)
                end
                if leviathanStateTimer > 6.0 then
                    leviathanState = "idle"
                    leviathanStateTimer = 0
                    leviathanBreachedNotif = false
                    lNotif("The Leviathan levels off gracefully.", 2)
                end
            end

            
            local targetSlither = (leviathanState == "sprint" or leviathanState == "walk") and 1.0 or 0.0
            leviathanSlitherWeight = leviathanSlitherWeight + (targetSlither - leviathanSlitherWeight) * math.clamp(dt * 3.5, 0, 1)

            local ignores = {workspace:FindFirstChild("WorkspaceCom")}
            for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
                if p.Character then table.insert(ignores, p.Character) end
            end
            rayParams.FilterDescendantsInstances = ignores
            local hit = workspace:Raycast(leviathanAnchor + Vector3.new(0, 10, 0), Vector3.new(0, -40, 0), rayParams)
            local groundY = hit and hit.Position.Y or leviathanAnchor.Y

            if isRiding then
                if hudFrame and not hudFrame.Visible then
                    hudFrame.Visible = true
                end

                local turnSpeed = 2.6
                local moveDir = Vector3.new(0, 0, 0)
                local vertDir = 0

                if UIS:IsKeyDown(Enum.KeyCode.Space) or isAscendingHeld then
                    vertDir = vertDir + 1
                end
                if UIS:IsKeyDown(Enum.KeyCode.LeftControl) or UIS:IsKeyDown(Enum.KeyCode.C) or isDescendingHeld then
                    vertDir = vertDir - 1
                end

                local isSprinting = UIS:IsKeyDown(Enum.KeyCode.LeftShift) or isSprintToggled
                local curSpeed = isSprinting and 68 or 30

                if UIS:IsKeyDown(Enum.KeyCode.A) then
                    leviathanAngle = leviathanAngle + turnSpeed * dt
                end
                if UIS:IsKeyDown(Enum.KeyCode.D) then
                    leviathanAngle = leviathanAngle - turnSpeed * dt
                end

                if myHum and myHum.MoveDirection.Magnitude > 0.05 then
                    local md = myHum.MoveDirection
                    local targetYaw = math.atan2(-md.X, -md.Z)
                    local diffAngle = (targetYaw - leviathanAngle + math.pi) % (2 * math.pi) - math.pi
                    leviathanAngle = leviathanAngle + math.clamp(diffAngle, -turnSpeed * 1.5, turnSpeed * 1.5) * dt
                    moveDir = moveDir + (CFrame.Angles(0, leviathanAngle, 0)).LookVector
                end

                local _0xH_431 = CFrame.Angles(0, leviathanAngle, 0)
                local fwd = _0xH_431.LookVector
                if UIS:IsKeyDown(Enum.KeyCode.W) then
                    moveDir = moveDir + fwd
                end
                if UIS:IsKeyDown(Enum.KeyCode.S) then
                    moveDir = moveDir - fwd * 0.5
                end

                if leviathanState == "breach" then
                    local p = math.clamp(leviathanStateTimer / 6.0, 0, 1)
                    local breachFwdSpeed = 40
                    if p < 0.32 then
                        breachFwdSpeed = 38
                    elseif p < 0.50 then
                        breachFwdSpeed = 62
                    elseif p < 0.78 then
                        breachFwdSpeed = 46
                    else
                        breachFwdSpeed = 24
                    end
                    leviathanAnchor = leviathanAnchor + (_0xH_431.LookVector * breachFwdSpeed * dt)
                end

                if moveDir.Magnitude > 0 then
                    leviathanAnchor = leviathanAnchor + moveDir.Unit * curSpeed * dt
                    if leviathanState ~= "roar" and leviathanState ~= "strike" and leviathanState ~= "kneel" and leviathanState ~= "breach" then
                        if isSprinting then
                            leviathanState = "sprint"
                        else
                            leviathanState = "walk"
                        end
                    end
                else
                    if isSprinting and (leviathanState == "walk" or leviathanState == "idle") then
                        leviathanState = "idle"
                    elseif leviathanState == "walk" or leviathanState == "sprint" then
                        leviathanState = "idle"
                    end
                end

                local vertSpeed = isSprinting and 32 or 22
                if vertDir ~= 0 then
                    leviathanAnchor = leviathanAnchor + Vector3.new(0, vertDir * vertSpeed * dt, 0)
                else
                    local diffY = groundY - leviathanAnchor.Y
                    if diffY > 0 then
                        leviathanAnchor = Vector3.new(leviathanAnchor.X, leviathanAnchor.Y + math.clamp(diffY, 0, 25 * dt), leviathanAnchor.Z)
                    end
                end

                if hudStatusLabel then
                    if leviathanState == "breach" then
                        local p = math.clamp(leviathanStateTimer / 6.0, 0, 1)
                        if p < 0.32 then
                            hudStatusLabel.Text = "STATUS: ABYSSAL PLUNGE (DIVING)"
                            hudStatusLabel.TextColor3 = Color3.fromRGB(130, 80, 255)
                        elseif p < 0.50 then
                            hudStatusLabel.Text = "STATUS: SUBTERRANEAN SURGE"
                            hudStatusLabel.TextColor3 = Color3.fromRGB(0, 200, 255)
                        elseif p < 0.78 then
                            hudStatusLabel.Text = "STATUS: CELESTIAL BREACH (ERUPTING!)"
                            hudStatusLabel.TextColor3 = Color3.fromRGB(255, 220, 50)
                        else
                            hudStatusLabel.Text = "STATUS: APEX CREST & SPLASHDOWN"
                            hudStatusLabel.TextColor3 = Color3.fromRGB(0, 255, 200)
                        end
                    elseif isSprinting and moveDir.Magnitude > 0 then
                        hudStatusLabel.Text = "STATUS: SERPENT SPRINT (68 STUDS/S)"
                        hudStatusLabel.TextColor3 = Color3.fromRGB(0, 255, 230)
                    elseif isSprinting and moveDir.Magnitude == 0 then
                        hudStatusLabel.Text = "STATUS: SPRINT READY (PRESS W)"
                        hudStatusLabel.TextColor3 = Color3.fromRGB(0, 230, 255)
                    elseif vertDir > 0 then
                        hudStatusLabel.Text = "STATUS: ASCENDING (FLYING)"
                        hudStatusLabel.TextColor3 = Color3.fromRGB(80, 200, 255)
                    elseif vertDir < 0 then
                        hudStatusLabel.Text = "STATUS: DIVING (SUBMERGING)"
                        hudStatusLabel.TextColor3 = Color3.fromRGB(150, 100, 255)
                    elseif moveDir.Magnitude > 0 then
                        hudStatusLabel.Text = "STATUS: CRUISING SLITHER (30 STUDS/S)"
                        hudStatusLabel.TextColor3 = Color3.fromRGB(100, 255, 120)
                    else
                        hudStatusLabel.Text = "STATUS: HOVERING"
                        hudStatusLabel.TextColor3 = Color3.fromRGB(200, 220, 255)
                    end
                end

            else
                if hudFrame and hudFrame.Visible then
                    hudFrame.Visible = false
                    isAscendingHeld = false
                    isDescendingHeld = false
                    isSprintToggled = false
                end

                if leviathanMode == "follow" then
                    local targetChar = nil
                    if leviathanFollowName == lp.Name then
                        targetChar = lp.Character
                    else
                        local targetPlr = game:GetService("Players"):FindFirstChild(leviathanFollowName)
                        targetChar = targetPlr and targetPlr.Character
                    end

                    local targetHrp = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
                    if targetHrp then
                        local toTarget = (targetHrp.Position - leviathanAnchor)
                        local dist = Vector3.new(toTarget.X, 0, toTarget.Z).Magnitude
                        if dist > 14 then
                            local dir = Vector3.new(toTarget.X, 0, toTarget.Z).Unit
                            local isFast = (dist > 32)
                            local fSpeed = isFast and 68 or 30
                            leviathanAnchor = leviathanAnchor + (dir * fSpeed * dt)
                            leviathanAngle = math.atan2(-dir.X, -dir.Z)
                            leviathanState = isFast and "sprint" or "walk"
                        else
                            leviathanState = "idle"
                        end
                    else
                        leviathanState = "idle"
                    end

                    local diffY = math.clamp(groundY - leviathanAnchor.Y, -25 * dt, 15 * dt)
                    leviathanAnchor = Vector3.new(leviathanAnchor.X, leviathanAnchor.Y + diffY, leviathanAnchor.Z)

                elseif leviathanMode == "free" then
                    if not leviathanWaypoint or (Vector3.new(leviathanWaypoint.X - leviathanAnchor.X, 0, leviathanWaypoint.Z - leviathanAnchor.Z).Magnitude < 8) then
                        local randomOff = Vector3.new(math.random(-100, 100), 0, math.random(-100, 100))
                        leviathanWaypoint = leviathanAnchor + randomOff
                    end
                    local toWp = leviathanWaypoint - leviathanAnchor
                    local dir = Vector3.new(toWp.X, 0, toWp.Z).Unit
                    leviathanAnchor = leviathanAnchor + (dir * 30 * dt)
                    leviathanAngle = math.atan2(-dir.X, -dir.Z)
                    leviathanState = "walk"

                    local diffY = math.clamp(groundY - leviathanAnchor.Y, -25 * dt, 15 * dt)
                    leviathanAnchor = Vector3.new(leviathanAnchor.X, leviathanAnchor.Y + diffY, leviathanAnchor.Z)
                else
                    local diffY = math.clamp(groundY - leviathanAnchor.Y, -25 * dt, 15 * dt)
                    leviathanAnchor = Vector3.new(leviathanAnchor.X, leviathanAnchor.Y + diffY, leviathanAnchor.Z)
                end
            end

            
            local targetBank = 0
            if isRiding then
                if UIS:IsKeyDown(Enum.KeyCode.A) then
                    targetBank = targetBank + math.rad(14)
                end
                if UIS:IsKeyDown(Enum.KeyCode.D) then
                    targetBank = targetBank - math.rad(14)
                end
                if myHum and myHum.MoveDirection.Magnitude > 0.05 then
                    local md = myHum.MoveDirection
                    local targetYaw = math.atan2(-md.X, -md.Z)
                    local diffAngle = (targetYaw - leviathanAngle + math.pi) % (2 * math.pi) - math.pi
                    targetBank = targetBank + math.clamp(diffAngle * 0.8, -math.rad(16), math.rad(16))
                end
            end
            leviathanTurnBank = leviathanTurnBank + (targetBank - leviathanTurnBank) * math.clamp(dt * 5.0, 0, 1)

            
            for _, w in pairs(leviathanWorkers) do
                w.targetCF = _0xH_3ec(w.layout, leviathanAnimT, leviathanState, leviathanStateTimer, leviathanAnchor, leviathanAngle, leviathanSlitherWeight, leviathanTurnBank)
                w.targetColor = getLeviathanPartColor(w.layout, w.partIndex, leviathanAnimT, leviathanState, leviathanColorMode)
            end
        end)
    end

    
    
    
    BuildTab:AddSection({"> Giant Leviathan"})

    local leviathanToggle = BuildTab:AddToggle({
        Name = "Spawn Leviathan",
        Description = "Summon a giant 15-prop serpent titan",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            if not val and not leviathanActive then return end
            leviathanActive = val
            if val then
                task.spawn(function()
                    spawnLeviathan()
                    if leviathanActive then startLeviathanLoop() end
                end)
            else
                if leviathanLoop then leviathanLoop:Disconnect() leviathanLoop = nil end
                pcall(function()
                    local hum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
                    if hum then hum.Sit = false end
                end)
                pcall(function()
                    game:GetService("ReplicatedStorage"):WaitForChild("RE"):WaitForChild("1Clea1rTool1s"):FireServer("ClearAllProps")
                end)
                leviathanWorkers = {}
                leviathanDriverSeat = nil
                if pilotGui then pcall(function() pilotGui:Destroy() end) pilotGui = nil hudFrame = nil end
                if inputConn then pcall(function() inputConn:Disconnect() end) inputConn = nil end
                lNotif("Leviathan dismissed.", 2)
            end
        end
    })

    BuildTab:AddDropdown({
        Name = "Leviathan Color",
        Description = "Choose the dynamic real-time color scheme",
        Options = {"Cyan", "Magma", "Shadow", "Rainbow", "Emerald"},
        Default = "Cyan",
        Callback = function(choice)
            leviathanColorMode = choice
            lNotif("Color: " .. choice, 2)
        end
    })

    BuildTab:AddDropdown({
        Name = "Target",
        Description = "Select the leviathan's target",
        Options = (function()
            local names = {"---"}
            for _, p in pairs(game:GetService("Players").LocalPlayer and game:GetService("Players"):GetPlayers() or {}) do
                if p ~= game:GetService("Players").LocalPlayer then
                    table.insert(names, p.Name)
                end
            end
            return names
        end)(),
        Default = "---",
        Callback = function(choice)
            leviathanFollowName = choice
            leviathanTarget = choice
        end
    })

    BuildTab:AddButton({
        Name = "Stand (Idle)",
        Description = "Leviathan stands in towering stance",
        Callback = function()
            if not leviathanActive then lNotif("Spawn the Leviathan first!", 2) return end
            leviathanMode = "manual"
            leviathanState = "idle"
            leviathanStateTimer = 0
            lNotif("Leviathan is idle.", 2)
        end
    })

    BuildTab:AddButton({
        Name = "Hunt Target",
        Description = "Leviathan hunts the selected target",
        Callback = function()
            if not leviathanActive then lNotif("Spawn the Leviathan first!", 2) return end
            if leviathanFollowName == "---" or leviathanFollowName == "" then
                lNotif("Select a target first!", 2) return
            end
            leviathanMode = "follow"
            leviathanState = "walk"
            leviathanStateTimer = 0
            lNotif("Hunting target...", 2)
        end
    })

    BuildTab:AddButton({
        Name = "Follow Me",
        Description = "Leviathan follows you like an armored guardian",
        Callback = function()
            if not leviathanActive then lNotif("Spawn the Leviathan first!", 2) return end
            leviathanFollowName = lp.Name
            leviathanTarget = leviathanFollowName
            leviathanMode = "follow"
            leviathanState = "walk"
            leviathanStateTimer = 0
            lNotif("Leviathan is following you!", 2)
        end
    })

    BuildTab:AddButton({
        Name = "Patrol (Free)",
        Description = "Leviathan patrols the Brookhaven map freely",
        Callback = function()
            if not leviathanActive then lNotif("Spawn the Leviathan first!", 2) return end
            leviathanMode = "free"
            leviathanState = "walk"
            leviathanWaypoint = nil
            leviathanStateTimer = 0
            lNotif("The leviathan is on free patrol.", 2)
        end
    })

    BuildTab:AddButton({
        Name = "Strike",
        Description = "Strikes downward with a snapping bite",
        Callback = function()
            if not leviathanActive then lNotif("Spawn the Leviathan first!", 2) return end
            if not canDo("strike", 3) then lNotif("Cooldown...", 2) return end
            leviathanMode = "manual"
            leviathanState = "strike"
            leviathanStateTimer = 0
            lNotif("TITANIC STRIKE!", 2)
        end
    })

    BuildTab:AddButton({
        Name = "Roar",
        Description = "Unleashes a massive roar with fire breath",
        Callback = function()
            if not leviathanActive then lNotif("Spawn the Leviathan first!", 2) return end
            if not canDo("roar", 4) then lNotif("Cooldown...", 2) return end
            leviathanMode = "manual"
            leviathanState = "roar"
            leviathanStateTimer = 0
            lNotif("TITANIC ROAR!", 2)
        end
    })

    BuildTab:AddButton({
        Name = "Breach (Dive)",
        Description = "Dives underground and erupts into the sky",
        Callback = function()
            if not leviathanActive then lNotif("Spawn the Leviathan first!", 2) return end
            triggerBreach()
        end
    })

    BuildTab:AddButton({
        Name = "Mount Throne",
        Description = "Mounts or dismounts the pilot throne at the apex",
        Callback = function()
            if not leviathanActive then lNotif("Spawn the Leviathan first!", 2) return end
            local char = lp.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if not hum or not hrp then return end

            if hum.Sit then
                hum.Sit = false
                lNotif("Dismounted from throne.", 2)
                return
            end

            if leviathanDriverSeat then
                hrp.CFrame = leviathanDriverSeat.CFrame + Vector3.new(0, 1.5, 0)
                task.wait(0.1)
                pcall(function() leviathanDriverSeat:Sit(hum) end)
                lNotif("Mounted throne! Pilot HUD active.", 2)
            else
                local throneW = leviathanWorkers["throne"]
                if throneW and throneW.targetCF then
                    hrp.CFrame = throneW.targetCF + Vector3.new(0, 2, 0)
                    lNotif("Mounted throne.", 2)
                end
            end
        end
    })

end 

do
                                                                                      
    local lp = game:GetService("Players").LocalPlayer
    local RunService = game:GetService("RunService")
    local TweenService = game:GetService("TweenService")
    local Streamer = PropStreamer.new(0.066)

    local coasterActive = false
    local coasterLoop = nil
    local coasterT = 0
    local coasterSeats = {}

    local wheelActive = false
    local wheelLoop = nil
    local wheelAngle = 0
    local wheelCabins = {}

    local slingActive = false
    local slingLoop = nil
    local slingState = "IDLE"
    local slingHeight = 0
    local slingVel = 0
    local slingPods = {}

    local function aNotif(title, text)
        pcall(function()
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = title,
                Text = text,
                Duration = 3
            })
        end)
    end

    BuildTab:AddSection({"Attraction: Roller Coaster"})

    BuildTab:AddToggle({
        Name = "Spawn Hyper-Drive Drop Coaster",
        Description = "Supersonic 80-stud sky-drop coaster with loopings and multi-passenger cars",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            coasterActive = val
            if val then
                aNotif("Hyper-Drive Coaster", "Summoning coaster train... Board the cars!")
                task.spawn(function()
                    local myChar = lp.Character
                    local root = myChar and myChar:FindFirstChild("HumanoidRootPart")
                    local basePos = (root and root.Position) or Vector3.new(0, 5, 0)

                                                                                        
                    coasterSeats = {}
                    local RE = game:GetService("ReplicatedStorage"):FindFirstChild("RE")
                    local clearTools = RE and RE:FindFirstChild("1Clea1rTool1s")
                    if clearTools then pcall(function() clearTools:FireServer("RequestingPropName", "FurnitureBleachers", "Furniture") end) end
                    task.wait(0.2)

                    local wc = workspace:FindFirstChild("WorkspaceCom")
                    if wc then
                        for _, f in pairs(wc:GetChildren()) do
                            for _, p in pairs(f:GetChildren()) do
                                if p.Name == "Prop" .. lp.Name and p:FindFirstChild("SetCurrentCFrame") then
                                    table.insert(coasterSeats, p:FindFirstChild("SetCurrentCFrame"))
                                    if #coasterSeats >= 6 then break end
                                end
                            end
                        end
                    end

                    coasterT = 0
                    if coasterLoop then coasterLoop:Disconnect() end
                    coasterLoop = RunService.Heartbeat:Connect(function(dt)
                        if not coasterActive then return end
                        coasterT = coasterT + (dt * 1.8)
                        
                                                                                                                     
                        local trackLen = 20
                        local progress = coasterT % trackLen
                        
                        for idx, scf in ipairs(coasterSeats) do
                            local carOffset = (idx - 1) * 0.4
                            local carProg = (coasterT - carOffset) % trackLen
                            
                            local x, y, z
                            local yaw, pitch, roll = 0, 0, 0
                            
                            if carProg < 6 then
                                                                       
                                local alpha = carProg / 6
                                x = math.sin(alpha * math.pi * 0.5) * 40
                                y = 5 + (alpha * 70)
                                z = -alpha * 60
                                pitch = math.rad(35)
                                yaw = 0
                            elseif carProg < 8 then
                                                                                    
                                local alpha = (carProg - 6) / 2
                                x = 40 + math.sin(alpha * math.pi) * 15
                                y = 75
                                z = -60 - (alpha * 15)
                                pitch = 0
                            elseif carProg < 13 then
                                                                               
                                local alpha = (carProg - 8) / 5
                                local dropCurve = math.cos(alpha * math.pi * 0.5)
                                x = 40 + math.sin(alpha * math.pi * 4) * (20 * dropCurve)
                                y = 5 + (dropCurve * 70)
                                z = -75 + (alpha * 90)
                                pitch = -math.rad(65 * dropCurve)
                                roll = alpha * math.pi * 4
                            else
                                                                       
                                local alpha = (carProg - 13) / 7
                                local ang = alpha * math.pi * 2
                                x = math.cos(ang) * 35
                                y = 5 + math.sin(alpha * math.pi) * 8
                                z = 15 + math.sin(ang) * 35
                                yaw = ang + math.rad(90)
                                roll = math.sin(alpha * math.pi) * math.rad(30)
                            end
                            
                            local carPos = basePos + Vector3.new(x, y, z)
                            local carCF = CFrame.new(carPos) * CFrame.Angles(pitch, yaw, roll)
                            pcall(function() scf:InvokeServer(carCF) end)
                        end
                    end)
                end)
            else
                if coasterLoop then coasterLoop:Disconnect() coasterLoop = nil end
                coasterSeats = {}
                local RE = game:GetService("ReplicatedStorage"):FindFirstChild("RE")
                if RE and RE:FindFirstChild("1Clea1rTool1s") then
                    pcall(function() RE["1Clea1rTool1s"]:FireServer("ClearAllProps") end)
                end
                aNotif("Hyper-Drive Coaster", "Coaster safely parked and cleared.")
            end
        end
    })

    BuildTab:AddSection({"Attraction: Ferris Wheel"})

    BuildTab:AddToggle({
        Name = "Spawn Ferris Wheel",
        Description = "Colossal dual counter-rotating observation wheel lifting riders 70 studs in the sky",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            wheelActive = val
            if val then
                aNotif("Ferris Wheel", "Constructing Quantum Wheel... Hop on a cabin!")
                task.spawn(function()
                    local myChar = lp.Character
                    local root = myChar and myChar:FindFirstChild("HumanoidRootPart")
                    local center = (root and (root.Position + Vector3.new(0, 35, 0))) or Vector3.new(0, 40, 0)
                    wheelCabins = {}

                    local RE = game:GetService("ReplicatedStorage"):FindFirstChild("RE")
                    if RE and RE:FindFirstChild("1Clea1rTool1s") then
                        pcall(function() RE["1Clea1rTool1s"]:FireServer("RequestingPropName", "FurnitureSilverThrone", "Furniture") end)
                    end
                    task.wait(0.2)

                    local wc = workspace:FindFirstChild("WorkspaceCom")
                    if wc then
                        for _, f in pairs(wc:GetChildren()) do
                            for _, p in pairs(f:GetChildren()) do
                                if p.Name == "Prop" .. lp.Name and p:FindFirstChild("SetCurrentCFrame") then
                                    table.insert(wheelCabins, p:FindFirstChild("SetCurrentCFrame"))
                                    if #wheelCabins >= 8 then break end
                                end
                            end
                        end
                    end

                    wheelAngle = 0
                    if wheelLoop then wheelLoop:Disconnect() end
                    wheelLoop = RunService.Heartbeat:Connect(function(dt)
                        if not wheelActive then return end
                        wheelAngle = wheelAngle + (dt * 0.45)
                        local count = math.max(#wheelCabins, 1)
                        local wheelRadius = 32

                        for i, scf in ipairs(wheelCabins) do
                            local cabinAng = wheelAngle + ((i / count) * math.pi * 2)
                            local cabinPos = center + Vector3.new(math.cos(cabinAng) * wheelRadius, math.sin(cabinAng) * wheelRadius, 0)
                                                                              
                            local cabinCF = CFrame.new(cabinPos)
                            pcall(function() scf:InvokeServer(cabinCF) end)
                        end
                    end)
                end)
            else
                if wheelLoop then wheelLoop:Disconnect() wheelLoop = nil end
                wheelCabins = {}
                local RE = game:GetService("ReplicatedStorage"):FindFirstChild("RE")
                if RE and RE:FindFirstChild("1Clea1rTool1s") then
                    pcall(function() RE["1Clea1rTool1s"]:FireServer("ClearAllProps") end)
                end
                aNotif("Ferris Wheel", "Ferris Wheel closed.")
            end
        end
    })

    BuildTab:AddSection({"Attraction: Space Sling"})

    BuildTab:AddToggle({
        Name = "Activate Space Sling Catapult",
        Description = "Supersonic human catapult launching riders 250 studs straight up",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            slingActive = val
            if val then
                aNotif("Space Sling", "Ready! Board the pod. Launching every 10 seconds!")
                task.spawn(function()
                    local myChar = lp.Character
                    local root = myChar and myChar:FindFirstChild("HumanoidRootPart")
                    local padPos = (root and root.Position) or Vector3.new(0, 5, 0)
                    slingPods = {}

                    local RE = game:GetService("ReplicatedStorage"):FindFirstChild("RE")
                    if RE and RE:FindFirstChild("1Clea1rTool1s") then
                        pcall(function() RE["1Clea1rTool1s"]:FireServer("RequestingPropName", "FurnitureSilverThrone", "Furniture") end)
                    end
                    task.wait(0.2)

                    local wc = workspace:FindFirstChild("WorkspaceCom")
                    if wc then
                        for _, f in pairs(wc:GetChildren()) do
                            for _, p in pairs(f:GetChildren()) do
                                if p.Name == "Prop" .. lp.Name and p:FindFirstChild("SetCurrentCFrame") then
                                    table.insert(slingPods, p:FindFirstChild("SetCurrentCFrame"))
                                    if #slingPods >= 2 then break end
                                end
                            end
                        end
                    end

                    local tSling = 0
                    slingHeight = 0
                    slingVel = 0
                    if slingLoop then slingLoop:Disconnect() end
                    slingLoop = RunService.Heartbeat:Connect(function(dt)
                        if not slingActive then return end
                        tSling = (tSling + dt) % 12

                        if tSling < 3 then
                                                           
                            slingHeight = -1.5 * (tSling / 3)
                        elseif tSling < 3.2 then
                                                                                     
                            slingVel = 260
                            slingHeight = slingHeight + (slingVel * dt)
                        elseif tSling < 8 then
                                                                    
                            slingVel = slingVel - (98 * dt)
                            slingHeight = math.max(0, slingHeight + (slingVel * dt))
                        else
                                                    
                            slingHeight = math.max(0, slingHeight * 0.9)
                        end

                        for idx, scf in ipairs(slingPods) do
                            local podOffset = (idx == 1) and Vector3.new(-1.8, 0, 0) or Vector3.new(1.8, 0, 0)
                            local rotOsc = math.sin(tSling * 8) * math.rad(15)
                            local podCF = CFrame.new(padPos + podOffset + Vector3.new(0, slingHeight, 0)) * CFrame.Angles(rotOsc, 0, 0)
                            pcall(function() scf:InvokeServer(podCF) end)
                        end
                    end)
                end)
            else
                if slingLoop then slingLoop:Disconnect() slingLoop = nil end
                slingPods = {}
                local RE = game:GetService("ReplicatedStorage"):FindFirstChild("RE")
                if RE and RE:FindFirstChild("1Clea1rTool1s") then
                    pcall(function() RE["1Clea1rTool1s"]:FireServer("ClearAllProps") end)
                end
                aNotif("Space Sling", "Space Sling deactivated.")
            end
        end
    })
end

