BuildTab:AddToggle({
    Name = "Build (Toggle to clear)",
    Description = "Starts the build. Toggle OFF to clear.",
    Default = false,
    Callback = function(Value)
        if not _G.BTR_UI_READY then return end
        BuildSystem.Active = Value
        local lp = game:GetService("Players").LocalPlayer
        local hrp = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
        local clearTools = game:GetService("ReplicatedStorage"):WaitForChild("RE"):WaitForChild("1Clea1rTool1s")

        if Value then
            if not hrp then BuildSystem.Active = false return end
            if hrp then hrp.Anchored = true end

            task.spawn(function()
                
                local tool = _0xH_3f2()
                
                if tool and hrp and hrp.Parent then
                    local hum = hrp.Parent:FindFirstChild("Humanoid")
                    if hum then 
                        hum:EquipTool(tool) 
                        
                        lp.Character:WaitForChild("PropMaker", 2)
                    end
                end
                task.wait(0.5)
                pcall(function() clearTools:FireServer("OpenPropMenu") end)
                task.wait(0.2)

                
                local startCFrame = hrp.CFrame * CFrame.new(0, 2, -12)
                local points = getPoints(BuildSystem.CurrentShape)
                local lastProp = ""
                local lastCat = ""
                
                
                local spawnedProps = {}
                local connection
                local myPropName = "Prop" .. lp.Name
                connection = workspace:WaitForChild("WorkspaceCom").DescendantAdded:Connect(function(desc)
                    if desc:IsA("Model") and desc.Name == myPropName then
                        table.insert(spawnedProps, desc)
                    end
                end)

                local allSameProp = true
                local firstP = points[1]
                for _, pt in ipairs(points) do
                    if pt.prop ~= firstP.prop or pt.cat ~= firstP.cat then
                        allSameProp = false
                        break
                    end
                end

                if allSameProp and #points > 1 then
                    pcall(function() game:GetService("ReplicatedStorage"):WaitForChild("Remotes"):WaitForChild("TelemetryClientInteraction"):FireServer("filterClick", {name = firstP.cat, itemType = "Props"}) end)
                    task.wait(0.1)
                    pcall(function() game:GetService("ReplicatedStorage"):WaitForChild("Remotes"):WaitForChild("TelemetryClientInteraction"):FireServer("filterClick", {name = firstP.prop, itemType = "Props"}) end)
                    task.wait(0.1)
                    pcall(function() clearTools:FireServer("RequestingPropName", firstP.prop, firstP.cat) end)
                    task.wait(0.3)

                    local currentTool = lp.Character:FindFirstChild("PropMaker")
                    local propMake = currentTool and currentTool:FindFirstChild("Tool_PropMake")
                    if propMake then
                        local dup = _0xH_3f4(propMake, startCFrame.Position, #points, 0)
                        if not dup then
                            for i, pt in ipairs(points) do
                                if not BuildSystem.Active then break end
                                local actualScale = (BuildSystem.CurrentShape == "AK-47" or BuildSystem.CurrentShape == "AK47 HD" or BuildSystem.CurrentShape == "Zizi") and 1.5 or BuildSystem.Scale
                                local targetPos = (startCFrame * CFrame.new(pt.x * actualScale, pt.y * actualScale, (pt.z or 0) * actualScale)).Position
                                pcall(function() propMake:FireServer(workspace.Terrain, targetPos) end)
                                task.wait(0.85)
                            end
                        end
                    end
                else
                    for i, pt in ipairs(points) do
                        if not BuildSystem.Active then break end
                        local useProp = pt.prop
                        local useCat  = pt.cat

                        if useProp ~= lastProp or useCat ~= lastCat then
                            pcall(function() game:GetService("ReplicatedStorage"):WaitForChild("Remotes"):WaitForChild("TelemetryClientInteraction"):FireServer("filterClick", {name = useCat, itemType = "Props"}) end)
                            task.wait(0.1)
                            pcall(function() game:GetService("ReplicatedStorage"):WaitForChild("Remotes"):WaitForChild("TelemetryClientInteraction"):FireServer("filterClick", {name = useProp, itemType = "Props"}) end)
                            task.wait(0.1)
                            pcall(function() clearTools:FireServer("RequestingPropName", useProp, useCat) end)
                            task.wait(0.3)
                            lastProp = useProp
                            lastCat  = useCat
                        end

                        local actualScale = (BuildSystem.CurrentShape == "AK-47" or BuildSystem.CurrentShape == "AK47 HD" or BuildSystem.CurrentShape == "Zizi") and 1.5 or BuildSystem.Scale
                        local targetPos = (startCFrame * CFrame.new(pt.x * actualScale, pt.y * actualScale, (pt.z or 0) * actualScale)).Position
                        local currentTool = lp.Character:FindFirstChild("PropMaker")
                        if currentTool then
                            local propMake = currentTool:FindFirstChild("Tool_PropMake")
                            if propMake then
                                propMake:FireServer(workspace.Terrain, targetPos)
                            end
                        end
                        task.wait(0.85)
                    end
                end
                
                if connection then connection:Disconnect() end
                
                
                task.wait(0.5)
                for i, pt in ipairs(points) do
                    if not BuildSystem.Active then break end
                    local propModel = spawnedProps[i]
                    if propModel then
                        local scf = propModel:FindFirstChild("SetCurrentCFrame")
                        if scf then
                            local rx = pt.rx and math.rad(pt.rx) or 0
                            local ry = pt.ry and math.rad(pt.ry) or 0
                            local rz = pt.rz and math.rad(pt.rz) or 0
                            local actualScale = (BuildSystem.CurrentShape == "AK-47" or BuildSystem.CurrentShape == "AK47 HD" or BuildSystem.CurrentShape == "Zizi") and 1.5 or BuildSystem.Scale
                            local targetCF = startCFrame * CFrame.new(pt.x * actualScale, pt.y * actualScale, (pt.z or 0) * actualScale) * CFrame.Angles(rx, ry, rz)
                            task.spawn(function() pcall(function() scf:InvokeServer(targetCF) end) end)
                        end
                    end
                end

                task.wait(1)
                pcall(function() game:GetService("ReplicatedStorage"):WaitForChild("RE"):WaitForChild("1Too1l"):InvokeServer("PickingTools", "PropMaker") end)
                local humanoid = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
                if humanoid then pcall(function() humanoid:UnequipTools() end) end
                pcall(function() clearTools:FireServer("ClosePropMenu") end)
                _0xH_3f1()
                if hrp then hrp.Anchored = false end
                BuildSystem.Active = false
            end)
        else
            if hrp then hrp.Anchored = false end
            pcall(function() clearTools:FireServer("ClearAllProps") end)
        end
    end
})

