        Default = "Bleachers",
        Callback = function(val)
            if val == "Bleachers" then selectedOrbitProp = "FurnitureBleachers"
            elseif val == "Chairs" then selectedOrbitProp = "FurnitureChairBlackBig"
            elseif val == "Futuristic Large Bed" then selectedOrbitProp = "FuturisticLargeBed"
            end
        end
    })

    BuildTab:AddToggle({
