            orbitRGB = val
        end
    })

    BuildTab:AddButton({
        Name = "Recall View the city",
        Callback = function()
            if selectedAuraShape ~= "View the city" then
                game:GetService("StarterGui"):SetCore("SendNotification", {Title="View the city", Text="Select 'View the city' first in Aura Shape!", Duration=4})
                return
            end
            if rideState == "RIDING" then
                cityRideRecallRequested = true
                game:GetService("StarterGui"):SetCore("SendNotification", {Title="View the city", Text="Return requested! The ride is coming back slowly...", Duration=4})
            elseif rideState == "WAITING" or rideState == "BOARDING" then
                game:GetService("StarterGui"):SetCore("SendNotification", {Title="View the city", Text="The attraction is already at the station!", Duration=3})
            else
                game:GetService("StarterGui"):SetCore("SendNotification", {Title="View the city", Text="Already returning...", Duration=3})
            end
        end
    })

    BuildTab:AddToggle({
        Name = "RGB Orbit Aura",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            orbitActive = val
            local lp = game.Players.LocalPlayer
            local RE = game:GetService("ReplicatedStorage"):WaitForChild("RE")
            local clearTools = RE:WaitForChild("1Clea1rTool1s")
            local toolRemote = RE:WaitForChild("1Too1l")

            
            if not orbitActive then
                if orbitLoopConnection then orbitLoopConnection:Disconnect() orbitLoopConnection = nil end
                aStream:stop()
                pcall(function() clearTools:FireServer("ClearAllProps") end)
                pcall(function() clearTools:FireServer("ClosePropMenu") end)
                orbitProps = {}
                _0xH_3f1()
                return
            end

            
            
            pcall(function() clearTools:FireServer("ClearAllProps") end)
            task.wait(0.3)
            
            local propsTool = _0xH_3f2()
            
            local humanoid = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
            if propsTool and humanoid then
                humanoid:EquipTool(propsTool)
                task.wait(0.3)
            end
            local toolPropMake = propsTool and propsTool:FindFirstChild("Tool_PropMake")
            if not toolPropMake then return end
            
            pcall(function() clearTools:FireServer("OpenPropMenu") end)
            task.wait(0.1)

            
            local category = (selectedOrbitProp == "LightsSpotLightWhite") and "Lights" or "Furniture"
            pcall(function() clearTools:FireServer("RequestingPropName", selectedOrbitProp, category) end)
            task.wait(0.1)

            orbitProps = {}

            
            local runService = game:GetService("RunService")
            local t = 0
            local lastColorUpdate = 0
            local lastMoveUpdate = 0
            
            orbitLoopConnection = runService.RenderStepped:Connect(function(dt)
                if not orbitActive then return end
                t = t + dt * orbitSpeed

                
                local updateMove = false
                if tick() - lastMoveUpdate > 0.05 then
                    updateMove = true
                    lastMoveUpdate = tick()
                end

                local updateColor = false
                if orbitRGB and (tick() - lastColorUpdate > 0.1) then
                    updateColor = true
                    lastColorUpdate = tick()
                end
                
                if not updateMove and not updateColor then return end 

                local myRoot = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
                if not myRoot then return end
                local center = myRoot.Position + Vector3.new(0, 5, 0) 

                local hue = (t * 0.6) % 1
                local rgbColor = Color3.fromHSV(hue, 1, 1)
                
                local totalProps = #orbitProps
                if totalProps == 0 then return end

                for i, pData in ipairs(orbitProps) do
                    local finalPos, finalCF
                    
                    if selectedAuraShape == "Ferris Wheel" then
                        
                        local baseAngle = (i / totalProps) * (2 * math.pi) + t * 0.7
                        local radius = orbitRadius + 4
                        local lookVector = myRoot.CFrame.LookVector
                        local rightVector = myRoot.CFrame.RightVector
                        
                        local rimX = math.cos(baseAngle) * radius
                        local rimY = math.sin(baseAngle) * radius
                        finalPos = center + (rightVector * rimX) + Vector3.new(0, rimY, 0)
                        
                        finalCF = CFrame.fromMatrix(finalPos, lookVector, Vector3.new(0, 1, 0))

                    elseif selectedAuraShape == "Black Hole" then
                        
                        
                        
                        local r = 2.5 + ((i - 1) / math.max(totalProps - 1, 1)) * 8
                        local keplerSpeed = 6 / math.sqrt(r + 0.5)
                        local ang = t * keplerSpeed + (i * 2.399)
                        local tilt = 0.6
                        local lx = math.cos(ang) * r
                        local lz = math.sin(ang) * r
                        local ly = math.sin(ang) * r * tilt
                        local shiver = (1 - r / 10.5) * math.sin(t * 9 + i * 1.7) * 0.35
                        finalPos = myRoot.Position + Vector3.new(lx, 3 + ly + shiver, lz)
                        
                        finalCF = CFrame.new(finalPos, finalPos + Vector3.new(-math.sin(ang) * r, math.cos(ang) * r * tilt, math.cos(ang) * r))

                    elseif selectedAuraShape == "Dragon Tail" then
                        
                        local dist = i * 2.4
                        local lookVector = myRoot.CFrame.LookVector
                        local rightVector = myRoot.CFrame.RightVector
                        
                        local wiggleH = math.sin(t * 2.8 - i * 0.42) * (3.5 + math.sin(t * 0.9) * 1.8)
                        local wiggleV = math.sin(t * 2.2 - i * 0.31) * 1.6
                        local archDown = i * 0.1 
                        finalPos = myRoot.Position - (lookVector * dist) + (rightVector * wiggleH) + Vector3.new(0, 2.5 + wiggleV - archDown, 0)
                        
                        local fwdBias = (-lookVector + rightVector * (math.cos(t * 2.8 - i * 0.42) * 0.5)).Unit
                        finalCF = CFrame.new(finalPos, finalPos + fwdBias)

                    elseif selectedAuraShape == "Tornado" then
                        
                        local heightPct = (i - 1) / math.max(totalProps - 1, 1)
                        local height = -3 + heightPct * 28
                        local radius = 1.2 + heightPct * 13 
                        local spinSpeed = 2.5 + heightPct * 9  
                        local spinAngle = t * spinSpeed + (i / totalProps) * 2 * math.pi
                        local lx = math.cos(spinAngle) * radius
                        local lz = math.sin(spinAngle) * radius
                        finalPos = myRoot.Position + Vector3.new(lx, height, lz)
                        
                        finalCF = CFrame.new(finalPos, finalPos + Vector3.new(-math.sin(spinAngle), 0.2 * heightPct, math.cos(spinAngle)))

                    elseif selectedAuraShape == "Meteor Shower" then
                        
                        
                        
                        local ph = ((t * 1.4 + (i / totalProps)) % 1)
                        local height = 32 * (1 - ph * ph) - 2
                        local radius = math.sin(ph * math.pi) * 5
                        local spin = ph * math.pi * 6 + i * 2.4
                        local lx = math.cos(spin) * radius
                        local lz = math.sin(spin) * radius
                        finalPos = myRoot.Position + Vector3.new(lx, height, lz)
                        
                        finalCF = CFrame.new(finalPos, finalPos + Vector3.new(lx * 0.2, -2, lz * 0.2))

                    elseif selectedAuraShape == "Dragon Spirit" then
                        
                        
                        
                        
                        local bodyPct = (i - 1) / math.max(totalProps - 1, 1)
                        local ang = t * 1.9 + bodyPct * 2 * math.pi * 3
                        local radius = 6 + math.sin(t * 2.1 + bodyPct * math.pi * 2) * 1.3
                        local yWave = math.sin(t * 2.6 - bodyPct * math.pi * 4) * 2.8
                        local lx = math.cos(ang) * radius
                        local lz = math.sin(ang) * radius
                        finalPos = myRoot.Position + Vector3.new(lx, 3 + yWave, lz)
                        
                        local nextAng = ang + 0.12
                        local nextRadius = 6 + math.sin(t * 2.1 + (bodyPct + 0.02) * math.pi * 2) * 1.3
                        local nextPos = myRoot.Position + Vector3.new(math.cos(nextAng) * nextRadius, 3 + math.sin(t * 2.6 - (bodyPct + 0.02) * math.pi * 4) * 2.8, math.sin(nextAng) * nextRadius)
                        finalCF = CFrame.new(finalPos, nextPos)

                    elseif selectedAuraShape == "DNA Helix" then
                        
                        local isStrand2 = (i % 2 == 0)
                        local strandIdx = math.ceil(i / 2)
                        local _0xH_424 = isStrand2 and math.pi or 0
                        local totalHeight = 20
                        local scrollSpeed = 1.8
                        local halfProps = math.max(math.ceil(totalProps / 2), 1)
                        
                        local yOffset = ((strandIdx / halfProps) * totalHeight + t * scrollSpeed) % totalHeight - 5
                        
                        local spinAngle = (strandIdx / halfProps) * 2 * math.pi * 3 + t * 2.2 + _0xH_424
                        local lx = math.cos(spinAngle) * 3.8
                        local lz = math.sin(spinAngle) * 3.8
                        finalPos = myRoot.Position + Vector3.new(lx, yOffset, lz)
                        finalCF = CFrame.new(finalPos, myRoot.Position + Vector3.new(0, yOffset, 0))

                    elseif selectedAuraShape == "Roller Coaster" or selectedAuraShape == "View the city" then
                        
                        local now = tick()
                        local parkAngSpeed = (selectedAuraShape == "View the city") and 0.4 or 2.0

                        local playersSeated = 0
                        for _, player in pairs(game.Players:GetPlayers()) do
                            local h = player.Character and player.Character:FindFirstChild("Humanoid")
                            if h and h.Sit and h.SeatPart then
                                for _, pData in ipairs(orbitProps) do
                                    if pData.scf and pData.scf.Parent and h.SeatPart:IsDescendantOf(pData.scf.Parent) then
                                        playersSeated = playersSeated + 1
                                        break
                                    end
                                end
                            end
                        end

                        if rideState == "WAITING" then
                            if playersSeated > 0 and #orbitProps == totalProps then
                                if now - rideArrivalTimer > rideCooldownTime then
                                    rideState = "BOARDING"
                                    rideTimer = now
                                    game:GetService("StarterGui"):SetCore("SendNotification", {Title="Coaster Mode", Text="Departing in "..rideBoardingTime.."s!", Duration=math.min(rideBoardingTime, 5)})
                                end
                            end
                        elseif rideState == "BOARDING" then
                            if playersSeated == 0 then
                                rideState = "WAITING"
                            elseif now - rideTimer > rideBoardingTime then
                                rideState = "RIDING"
                                rideTimer = now
                                
                                
                                rideAnchor = myRoot.Position
                                game:GetService("StarterGui"):SetCore("SendNotification", {Title=rideIntensity, Text="Hold on!! ("..rideDuration.."s)", Duration=3})
                            end
                        elseif rideState == "RIDING" then
                            if now - rideTimer > rideDuration or (selectedAuraShape == "View the city" and cityRideRecallRequested) then
                                rideState = "LANDING"
                                rideTimer = now
                                cityRideRecallRequested = false
                                game:GetService("StarterGui"):SetCore("SendNotification", {Title="View the city", Text="Returning smoothly...", Duration=3})
                            end
                        elseif rideState == "LANDING" then
                            local parkCycleTime = (2 * math.pi) / parkAngSpeed
                            local minWait = totalProps * 0.15 + 1
                            local maxLandTime = math.ceil(minWait / parkCycleTime) * parkCycleTime
                            if now - rideTimer > maxLandTime then
                                rideState = "WAITING"
                                rideArrivalTimer = now
                                game:GetService("StarterGui"):SetCore("SendNotification", {Title="Coaster Mode", Text="All clear!", Duration=3})
                            end
                        end

                        
                        local function getTrackPoint(tTrack)
                            local parkRadius = 15
                            local parkHeight = -4.5
                            local rideDurationSafe = math.max(rideDuration, 1)
                            local spinBase = parkAngSpeed * rideDurationSafe
                            local minSpins = math.ceil(spinBase / (2 * math.pi)) + 2
                            local finalAng = minSpins * 2 * math.pi
                            local spinFast = (finalAng - spinBase) / 2

                            if tTrack <= 0 then
                                return Vector3.new(math.cos(tTrack * parkAngSpeed)*parkRadius, parkHeight, math.sin(tTrack * parkAngSpeed)*parkRadius)
                            end
                            if tTrack >= rideDurationSafe then
                                local ang = finalAng + (tTrack - rideDurationSafe) * parkAngSpeed
                                return Vector3.new(math.cos(ang)*parkRadius, parkHeight, math.sin(ang)*parkRadius)
                            end

                            local pt = tTrack / rideDurationSafe
                            local pArc = math.sin(pt * math.pi) 

                            
                            local baseAng = spinBase * pt + spinFast * (1 - math.cos(pt * math.pi))
                            local baseX = math.cos(baseAng) * parkRadius
                            local baseZ = math.sin(baseAng) * parkRadius

                            
                            local shapeX, shapeY, shapeZ = 0, 0, 0

                            if selectedAuraShape == "View the city" then
                                
                                
                                
                                
                                

                                
                                local cityMaxRadius = 400 
                                local cityMaxHeight = 200 
                                local spiralTurns  = 2    
                                local cruiseTurns  = 1.0  

                                
                                if pt < 0.30 then
                                    
                                    
                                    local ph = pt / 0.30
                                    local easePh = ph * ph * (3 - 2*ph)  
                                    local spiralAng = easePh * spiralTurns * 2 * math.pi
                                    local r = easePh * cityMaxRadius
                                    
                                    local hillWave = math.sin(spiralAng * 2.1 + 0.5) * 30 * easePh
                                    shapeX = math.cos(spiralAng) * r
                                    shapeZ = math.sin(spiralAng) * r
                                    shapeY = easePh * cityMaxHeight + hillWave

                                elseif pt < 0.70 then
                                    
                                    
                                    local ph = (pt - 0.30) / 0.40
                                    local tourAng = ph * cruiseTurns * 2 * math.pi

                                    
                                    local rBase = cityMaxRadius
                                    local rWobble = math.sin(tourAng * 1.7) * 150 + math.cos(tourAng * 0.9) * 80
                                    local r = rBase + rWobble

                                    shapeX = math.cos(tourAng) * r
                                    shapeZ = math.sin(tourAng) * r

                                    
                                    local altBase   = cityMaxHeight
                                    local altWave1  = math.sin(tourAng * 3.1)  * 55  
                                    local altWave2  = math.sin(tourAng * 7.3 + 1.2) * 20  
                                    local altWave3  = math.cos(tourAng * 1.8 + 0.7) * 35  
                                    shapeY = altBase + altWave1 + altWave2 + altWave3

                                else
                                    
                                    local ph = (pt - 0.70) / 0.30
                                    local easePh = 1 - ph * ph * (3 - 2*ph)  
                                    local spiralAng = (1-ph) * spiralTurns * 2 * math.pi
                                    local r = easePh * cityMaxRadius
                                    local hillWave = math.sin(spiralAng * 2.1 + 0.5) * 30 * easePh
                                    shapeX = math.cos(spiralAng) * r
                                    shapeZ = math.sin(spiralAng) * r
                                    shapeY = easePh * cityMaxHeight + hillWave
                                end

                                
                                baseX = 0
                                baseZ = 0
                            elseif rideIntensity == "Sky Rider" then
                                
                                
                                
                                
                                
                                
                                
                                if pt < 0.15 then
                                    local ph = pt / 0.15
                                    
                                    shapeY = ph * ph * 170
                                    shapeX = math.sin(ph * math.pi) * 20
                                elseif pt < 0.55 then
                                    local ph = (pt - 0.15) / 0.40
                                    
                                    local loopAng = ph * 3 * 2 * math.pi
                                    shapeY = 170 + math.sin(loopAng) * 100
                                    
                                    shapeX = math.cos(loopAng * 0.4) * 75 * math.sin(ph * math.pi)
                                    shapeZ = math.sin(loopAng * 0.3) * 55 * math.sin(ph * math.pi)
                                elseif pt < 0.80 then
                                    local ph = (pt - 0.55) / 0.25
                                    
                                    local rawY = 170 - ph * 195 
                                    shapeY = math.max(2, rawY) 
                                    shapeX = math.sin(ph * math.pi * 2) * 90 * (1 - ph)
                                    shapeZ = math.cos(ph * math.pi * 3) * 60 * (1 - ph)
                                else
                                    local ph = (pt - 0.80) / 0.20
                                    
                                    shapeY = (1 - ph) * (1 - ph) * 18
                                end

                            elseif rideIntensity == "Grand Tour" then
                                
                                
                                
                                
                                
                                local bigRadius = 275 
                                
                                
                                
                                shapeX = math.cos(baseAng) * bigRadius * pArc
                                shapeZ = math.sin(baseAng) * bigRadius * pArc
                                
                                shapeY = pArc * 12 + math.sin(pt * math.pi * 5) * 4 * pArc

                            else 
                                
                                
                                
                                
                                
                                
                                if pt < 0.25 then
                                    local ph = pt / 0.25
                                    shapeY = ph * ph * 290
                                    shapeX = math.sin(ph * math.pi * 3) * 4 * ph
                                    shapeZ = math.cos(ph * math.pi * 3) * 4 * ph
                                elseif pt < 0.60 then
                                    local ph = (pt - 0.25) / 0.35
                                    shapeY = 290 - ph * 60
                                    local orbitR = 45 * math.sin(ph * math.pi)
                                    shapeX = math.cos(ph * math.pi * 4) * orbitR
                                    shapeZ = math.sin(ph * math.pi * 4) * orbitR
                                else
                                    local ph = (pt - 0.60) / 0.40
                                    shapeY = (1 - ph) * (1 - ph) * 230
                                    local vrille = ph * math.pi * 10
                                    local vrRadius = (1 - ph) * 30
                                    shapeX = math.cos(vrille) * vrRadius
                                    shapeZ = math.sin(vrille) * vrRadius
                                end
                            end

                            return Vector3.new(baseX + shapeX, parkHeight + shapeY, baseZ + shapeZ)
                        end

                        local pTime = 0
                        if rideState == "RIDING" then
                            pTime = now - rideTimer
                        elseif rideState == "LANDING" then
                            pTime = rideDuration + (now - rideTimer)
                        end

                        local carTrackTime
                        if selectedAuraShape == "View the city" then
                            
                            local rowIdx = math.ceil(i / 2) - 1
                            carTrackTime = pTime - (rowIdx * 0.35) 
                        else
                            carTrackTime = pTime - (i * 0.15)
                        end

                        local currentPos = getTrackPoint(carTrackTime)
                        local nextPos    = getTrackPoint(carTrackTime + 0.1)

                        local lookVector = myRoot.CFrame.LookVector
                        
                        local anchor = (rideState == "RIDING" or rideState == "LANDING") and rideAnchor or myRoot.Position
                        local worldPos  = anchor + currentPos
                        local worldLook = anchor + nextPos

                        if (worldLook - worldPos).Magnitude > 0.01 then
                            finalCF = CFrame.new(worldPos, worldLook)
                        else
                            finalCF = myRoot.CFrame
                        end
                          
                        local finalColor = rgbColor 

                        
                        if selectedAuraShape == "View the city" then
                            
                            local isRightSeat = (i % 2 == 0)
                            local xOffset = isRightSeat and 2.5 or -2.5
                            finalCF = finalCF * CFrame.new(xOffset, 0, 0)
                        end

                        
                        if rideState == "RIDING" then
                            local pt   = math.clamp(carTrackTime / rideDuration, 0, 1)
                            local pArc = math.sin(pt * math.pi)
                            local roll = 0

                            if selectedAuraShape == "View the city" then
                                
                                local nextNextPos = getTrackPoint(carTrackTime + 0.5)
                                local futureWorld = anchor + nextNextPos
                                local toFuture = (futureWorld - worldPos)
                                if toFuture.Magnitude > 0.01 then
                                    local rightVec = finalCF.RightVector
                                    local lateralDiff = toFuture:Dot(rightVec)
                                    roll = math.clamp(lateralDiff * 0.003, -0.25, 0.25)
                                end
                            elseif rideIntensity == "Sky Rider" then
                                
                                if pt > 0.15 and pt < 0.55 then
                                    local ph = (pt - 0.15) / 0.40
                                    roll = math.cos(ph * 3 * 2 * math.pi) * 2.2 * pArc
                                elseif pt > 0.55 and pt < 0.80 then
                                    
                                    roll = math.sin(pt * math.pi * 8) * 1.5 * pArc
                                end

                            elseif rideIntensity == "Grand Tour" then
                                
                                roll = math.sin(pt * 2 * math.pi) * 0.35 * pArc

                            else 
                                if pt > 0.60 then
                                    roll = ((pt - 0.60) / 0.40) * math.pi * 5
                                end
                            end

                            finalCF = finalCF * CFrame.Angles(0, 0, roll)
                        end
                        
                    else
                        
                        
                        local propsPerRing = 5
                        local ringIdx = math.floor((i - 1) / propsPerRing) + 1
                        if ringIdx > 3 then ringIdx = 3 end
                        local j = ((i - 1) % propsPerRing) + 1
                        local r = orbitRadius + 1
                        local speeds = {0.9, 1.6, 2.5} 
                        local ang = (j / propsPerRing) * 2 * math.pi + t * speeds[ringIdx]
                        local pivot = myRoot.Position + Vector3.new(0, 2, 0)
                        if ringIdx == 1 then
                            finalPos = pivot + Vector3.new(math.cos(ang)*r, 0, math.sin(ang)*r)
                        elseif ringIdx == 2 then
                            finalPos = pivot + Vector3.new(math.cos(ang)*r, math.sin(ang)*r, 0)
                        else
                            finalPos = pivot + Vector3.new(0, math.sin(ang)*r, math.cos(ang)*r)
                        end
                        finalCF = CFrame.new(finalPos, pivot)
                    end
                    
                    
                    if selectedOrbitProp == "FurnitureBleachers" then
                        if selectedAuraShape == "Dragon Tail" then
                            finalCF = finalCF * CFrame.Angles(0, math.pi/2, 0)
                        elseif selectedAuraShape == "Ferris Wheel" or selectedAuraShape == "Roller Coaster" then
                            finalCF = finalCF * CFrame.Angles(0, math.pi/2, 0)
                        elseif selectedAuraShape == "View the city" then
                            
                            finalCF = finalCF * CFrame.Angles(0, math.pi, 0)
                        end
                    end

                    if updateMove then
                        aStream:setCF(pData.scf, finalCF)
                    end
                    if updateColor and pData.cpc then
                        aStream:setColor(pData.scf, finalColor or rgbColor)
                    end
                end
            end)

            
            task.spawn(function()
                local spawnPos = lp.Character.HumanoidRootPart.Position
                local duplicated = _0xH_3f4(toolPropMake, spawnPos, 15, 0)
                if not duplicated then
                    for i = 1, 15 do
                        if not orbitActive then break end
                        pcall(function() toolPropMake:FireServer(workspace.Terrain, spawnPos) end)
                        task.wait(0.85) 
                        if not orbitActive then break end
                        
                        
                        local myPropName = "Prop" .. lp.Name
                        for _, folder in pairs(workspace:WaitForChild("WorkspaceCom"):GetChildren()) do
                            for _, prop in pairs(folder:GetChildren()) do
                                if prop.Name == myPropName then
                                    local scf = prop:FindFirstChild("SetCurrentCFrame")
                                    local cpc = prop:FindFirstChild("ChangePropColor")
                                    if scf then
                                        local alreadyHave = false
                                        for _, p in ipairs(orbitProps) do
                                            if p.scf == scf then alreadyHave = true break end
                                        end
                                        if not alreadyHave then
                                            table.insert(orbitProps, {scf = scf, cpc = cpc})
                                            aStream:add(scf, cpc)
                                        end
                                    end
                                end
                            end
                        end
                    end
                else
                    task.wait(0.2)
                    local myPropName = "Prop" .. lp.Name
                    for _, folder in pairs(workspace:WaitForChild("WorkspaceCom"):GetChildren()) do
                        for _, prop in pairs(folder:GetChildren()) do
                            if prop.Name == myPropName then
                                local scf = prop:FindFirstChild("SetCurrentCFrame")
                                local cpc = prop:FindFirstChild("ChangePropColor")
                                if scf then
                                    local alreadyHave = false
                                    for _, p in ipairs(orbitProps) do
                                        if p.scf == scf then alreadyHave = true break end
                                    end
                                    if not alreadyHave then
                                        table.insert(orbitProps, {scf = scf, cpc = cpc})
                                        aStream:add(scf, cpc)
                                    end
                                end
                            end
                        end
                    end
                end
                
                if orbitActive then
                    aStream:start()
                    task.wait(1)
                    pcall(function() game:GetService("ReplicatedStorage"):WaitForChild("RE"):WaitForChild("1Too1l"):InvokeServer("PickingTools", "PropMaker") end)
                    pcall(function() clearTools:FireServer("ClosePropMenu") end)
                    if humanoid then pcall(function() humanoid:UnequipTools() end) end
                    _0xH_3f1()
                end
            end)
        end
    })
end

