    }

    local function _0xH_40b(layout, partIdx, t, state, colorMode)
        if state == "scare" then
            
            if layout.key == "fangL" or layout.key == "fangR" then
                return Color3.fromRGB(12, 12, 14)
            elseif layout.key == "head" then
                return Color3.fromRGB(14, 14, 16)
            end
        end

        if colorMode == "Black Widow" then
            if layout.key == "saddle" then
                return Color3.fromRGB(22, 22, 26)
            elseif layout.key == "fangL" or layout.key == "fangR" then
                return Color3.fromRGB(18, 18, 22)
            elseif layout.key == "abdomen" then
                return Color3.fromRGB(10, 10, 12)
            else
                return Color3.fromRGB(14, 14, 16)
            end
        elseif colorMode == "Acid Green" or colorMode == "Acid Broodmother" then
            if layout.key == "fangL" or layout.key == "fangR" then
                return Color3.fromRGB(40, 255, 50)
            elseif layout.key == "abdomen" then
                return Color3.fromRGB(12, 35, 16)
            else
                return Color3.fromRGB(15, 45, 20)
            end
        elseif colorMode == "Tarantula Gold" then
            if layout.key == "fangL" or layout.key == "fangR" then
                return Color3.fromRGB(190, 130, 30)
            elseif layout.key == "abdomen" then
                return Color3.fromRGB(48, 28, 14)
            elseif layout.legIdx then
                return (layout.legIdx % 2 == 0) and Color3.fromRGB(210, 140, 45) or Color3.fromRGB(65, 40, 20)
            else
                return Color3.fromRGB(55, 32, 18)
            end
        elseif colorMode == "Dark Violet" or colorMode == "Shadow Void" then
            if layout.key == "fangL" or layout.key == "fangR" then
                return Color3.fromRGB(210, 50, 255)
            elseif layout.key == "abdomen" then
                return Color3.fromRGB(25, 10, 42)
            else
                return Color3.fromRGB(30, 12, 50)
            end
        elseif colorMode == "Ice Frost" or colorMode == "Glacial Weaver" then
            if layout.key == "fangL" or layout.key == "fangR" then
                return Color3.fromRGB(0, 220, 255)
            elseif layout.key == "abdomen" then
                return Color3.fromRGB(210, 240, 255)
            else
                return Color3.fromRGB(175, 225, 250)
            end
        elseif colorMode == "Rainbow" or colorMode == "Rainbow Venom" then
            return Color3.fromHSV((t * 0.5 + partIdx * 0.065) % 1, 0.9, 1)
        end

        return Color3.fromRGB(14, 14, 16)
    end

