    local function isDriverSitting()
        if not spiderDriverSeat or not isSpiderMounted then return false end
        local char = lp.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hum or not hrp then
            isSpiderMounted = false
            return false
        end
        if not hum.Sit then
            isSpiderMounted = false
            return false
        end
        if (hrp.Position - spiderAnchor).Magnitude > 8.0 then
            isSpiderMounted = false
            return false
        end
        if hum.SeatPart == spiderDriverSeat or (spiderDriverSeat:IsA("Seat") and spiderDriverSeat.Occupant == hum) then
            return true
        end
        isSpiderMounted = false
        return false
    end

