    local function getStickmanPartColor(theme, key, style, partIdx)
        if theme == "Black" or theme == "Shadow Void" then
            return Color3.fromRGB(15, 15, 15)
        elseif theme == "Rainbow" then
            local pIdx = partIdx or 1
            return Color3.fromHSV((tick() * 0.4 + pIdx * 0.08) % 1, 1, 1)
        elseif theme == "White" or theme == "Ghost Phantom" then
            if key == "halo" then
                return Color3.fromRGB(255, 255, 255)
            end
            return Color3.fromRGB(245, 248, 255)
        elseif theme == "Samurai" or theme == "Realistic" then
            if style == "Samurai" and stickmanSize ~= "Ultra Giant" then
                if key == "hat" then
                    return Color3.fromRGB(195, 155, 100) 
                elseif key == "sword" then
                    return Color3.fromRGB(215, 220, 225) 
                elseif key == "halo" then
                    return Color3.fromRGB(255, 215, 30) 
                elseif key == "wingL" or key == "wingR" then
                    return Color3.fromRGB(165, 25, 25) 
                elseif key == "head" then
                    return Color3.fromRGB(20, 20, 25) 
                elseif key:find("torso") then
                    return Color3.fromRGB(25, 25, 30) 
                else
                    return Color3.fromRGB(35, 35, 40) 
                end
            else
                return Color3.fromRGB(15, 15, 15)
            end
        elseif theme == "Red" or theme == "Blood Demon" then
            if key == "wingL" or key == "wingR" or key == "sword" or key == "halo" or key == "head" then
                return Color3.fromRGB(225, 20, 25)
