    BuildV2Tab:AddToggle({
        Name = "Spawn Stickman",
        Default = false,
        Callback = function(v)
            if not _G.BTR_UI_READY then return end
            if v then
                stickmanActive = true
                task.spawn(spawnStickmanTitan)
            else
                stopStickmanTitan()
            end
        end
    })

    BuildV2Tab:AddDropdown({
        Name = "Size",
        Default = "Medium",
        Options = {"Medium", "Large", "Giant", "Ultra Giant"},
        Callback = function(choice)
            stickmanSize = choice
            if stickmanActive then
                task.spawn(spawnStickmanTitan)
            end
        end
    })

    BuildV2Tab:AddDropdown({
        Name = "Style",
        Default = "Samurai",
        Options = {"Original", "Samurai"},
        Callback = function(choice)
            stickmanStyle = choice
            if stickmanActive and stickmanSize ~= "Ultra Giant" then
                task.spawn(spawnStickmanTitan)
            end
        end
    })

    BuildV2Tab:AddDropdown({
        Name = "Color Theme",
        Default = "Black",
        Options = {"Black", "Rainbow", "Samurai", "Red", "Blue", "Green", "Purple", "Orange", "Yellow", "White"},
        Callback = function(choice)
            stickmanColorTheme = choice
            if stickmanActive then
                applyStickmanColors()
            end
        end
    })

    BuildV2Tab:AddToggle({
        Name = "Follow Player",
        Default = false,
        Callback = function(v)
            stickmanFollow = v
        end
    })

    BuildV2Tab:AddButton({
        Name = "Teleport In Front",
        Callback = function()
            local char = lp.Character or lp.CharacterAdded:Wait()
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hrp and stickmanActive then
                local ignoreList = {char}
                local wc = workspace:FindFirstChild("WorkspaceCom")
                if wc then table.insert(ignoreList, wc) end

                local fwdDist = (stickmanSize == "Ultra Giant") and 30 or ((stickmanSize == "Giant") and 24 or ((stickmanSize == "Large") and 18 or 14))
                local forwardPos = hrp.Position + (hrp.CFrame.LookVector * fwdDist)
                local rayParams = RaycastParams.new()
                rayParams.FilterDescendantsInstances = ignoreList
                rayParams.FilterType = Enum.RaycastFilterType.Exclude

                local gRay = workspace:Raycast(forwardPos + Vector3.new(0, 35, 0), Vector3.new(0, -80, 0), rayParams)
                local groundY = gRay and gRay.Position.Y or (hrp.Position.Y - 2.5)

                stickmanAnchor = Vector3.new(forwardPos.X, groundY, forwardPos.Z)
                stickmanAngle = math.atan2(hrp.CFrame.LookVector.X, hrp.CFrame.LookVector.Z)
                sNotif("Stickman Titan", "Repositioned in front of you!", 2)
            end
        end
    })
end

