        ["Ginger Tabby (Orange)"] = Color3.fromRGB(225, 120, 38),
        ["Snow Angora (White)"]   = Color3.fromRGB(248, 248, 252),
        ["Russian Blue (Grey)"]   = Color3.fromRGB(115, 125, 138),
        ["Siamese (Cream)"]       = Color3.fromRGB(215, 192, 158),
        ["Caramel (Golden)"]      = Color3.fromRGB(195, 142, 78)
    }

    local currentBreed = "Bombay (Black)"
    local currentCatColor = CAT_BREEDS[currentBreed]

    local CAT_BASE_BLUEPRINT = {
        { key = "body",   prop = "Block2",           cat = "Building" },
        { key = "head",   prop = "Block1",           cat = "Building" },
        { key = "ear_L",  prop = "CornerWedgeSmall", cat = "Building" },
        { key = "ear_R",  prop = "CornerWedgeSmall", cat = "Building" },
        { key = "leg_FL", prop = "TubeLamp",          cat = "Lights" },
        { key = "leg_FR", prop = "TubeLamp",          cat = "Lights" },
        { key = "leg_RL", prop = "TubeLamp",          cat = "Lights" },
        { key = "leg_RR", prop = "TubeLamp",          cat = "Lights" },
        { key = "tail",   prop = "TubeLamp",          cat = "Lights" },
        { key = "saddle", prop = "FloorCushion",     cat = "Furniture" }
    }

    local function cNotif(title, text, dur)
        pcall(function()
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = title,
                Text = text,
                Duration = dur or 3
            })
        end)
    end

    local function _0xH_3f2()
        local char = lp.Character or lp.CharacterAdded:Wait()
        local pm = char:FindFirstChild("PropMaker") or lp.Backpack:FindFirstChild("PropMaker")
        if not pm then
            pcall(function()
                game:GetService("ReplicatedStorage"):WaitForChild("RE"):WaitForChild("1Too1l"):InvokeServer("PickingTools", "PropMaker")
            end)
            task.wait(0.4)
            pm = char:FindFirstChild("PropMaker") or lp.Backpack:FindFirstChild("PropMaker")
        end
        return pm
    end

    local function lerp(a, b, t)
        return a + (b - a) * t
    end

    local function lerpVec3(v1, v2, t)
        return Vector3.new(lerp(v1.X, v2.X, t), lerp(v1.Y, v2.Y, t), lerp(v1.Z, v2.Z, t))
    end

    local function computeDynamicPartPose(key, t, sAlpha, mAlpha, stridePhase)
        sAlpha = sAlpha or 0
        mAlpha = mAlpha or 0
        stridePhase = stridePhase or 0

        local smoothS = sAlpha * sAlpha * (3 - 2 * sAlpha)

        
        local breathSpeed = lerp(1.6, 0.85, smoothS)
        local breathAmp = lerp(0.045, 0.065, smoothS)
        local breathY = math.sin(t * breathSpeed) * breathAmp
        local breathPitch = math.sin(t * breathSpeed + 0.3) * lerp(0.8, 0.4, smoothS)

        
        local gazeYaw = math.sin(t * 0.45) * 5.0 * (1 - smoothS) * (1 - mAlpha * 0.7)
        local gazeRoll = math.cos(t * 0.35) * 2.2 * (1 - smoothS) * (1 - mAlpha * 0.7)
        local sniffPitch = math.sin(t * 1.8) * 1.2 * (1 - smoothS) * (1 - mAlpha * 0.7)

        
        local tailBaseSway = math.sin(t * 1.4) * 16.0
        local tailTipFlick = math.sin(t * 2.8 + 1.2) * 8.0
        local tailDynamicSway = (tailBaseSway + tailTipFlick) * (1 - smoothS * 0.85)
        local tailPitchWave = math.sin(t * 1.4) * 3.5 * (1 - smoothS)

        
        local runBounce = math.sin(stridePhase * 2) * 0.035 * mAlpha

        
        if key == "body" then
            local pStand = Vector3.new(0, 2.45 + breathY + runBounce, 0)
            local pSleep = Vector3.new(0, 1.25 + breathY, 0)
            local bodyY = lerp(pStand.Y, pSleep.Y, smoothS)
            local bodyPitch = lerp(breathPitch, 0, smoothS)
            return Vector3.new(0, bodyY, 0), Vector3.new(bodyPitch, 90, lerp(0, -3.5, smoothS))

        
        elseif key == "head" then
            local pStand = Vector3.new(0, 3.05 + breathY * 0.6 + runBounce * 0.7, 4.2)
            local pSleep = Vector3.new(-0.15, 1.55 + breathY * 0.6, 4.10)
            local pos = lerpVec3(pStand, pSleep, smoothS)
            local rotX = lerp(sniffPitch, 4.0, smoothS)
            local rotY = lerp(gazeYaw, -8.0, smoothS)
            local rotZ = lerp(gazeRoll, -14.0, smoothS)
            return pos, Vector3.new(rotX, rotY, rotZ)

        
        elseif key == "leg_FL" then
            local legZ = math.sin(stridePhase) * 0.35 * mAlpha
            local legLift = math.max(0, -math.cos(stridePhase)) * 0.16 * mAlpha
            local legRotX = math.sin(stridePhase) * 12 * mAlpha

            local pStand = Vector3.new(-0.82, -1.60 + legLift, 2.35 + legZ)
            local pSleep = Vector3.new(-0.82, -3.40, 2.20)
            local pos = lerpVec3(pStand, pSleep, smoothS)
            return pos, Vector3.new(legRotX * (1 - smoothS), 0, 0)

        
        elseif key == "leg_FR" then
            local legZ = math.sin(stridePhase + math.pi) * 0.35 * mAlpha
            local legLift = math.max(0, -math.cos(stridePhase + math.pi)) * 0.16 * mAlpha
            local legRotX = math.sin(stridePhase + math.pi) * 12 * mAlpha

            local pStand = Vector3.new(0.82, -1.60 + legLift, 2.35 + legZ)
            local pSleep = Vector3.new(0.82, -3.40, 2.20)
            local pos = lerpVec3(pStand, pSleep, smoothS)
            return pos, Vector3.new(legRotX * (1 - smoothS), 0, 0)

        
        elseif key == "leg_RL" then
            local legZ = math.sin(stridePhase + math.pi) * 0.35 * mAlpha
            local legLift = math.max(0, -math.cos(stridePhase + math.pi)) * 0.16 * mAlpha
            local legRotX = math.sin(stridePhase + math.pi) * 12 * mAlpha

            local pStand = Vector3.new(-0.82, -1.60 + legLift, -2.35 + legZ)
            local pSleep = Vector3.new(-0.82, -3.40, -2.15)
            local pos = lerpVec3(pStand, pSleep, smoothS)
            return pos, Vector3.new(legRotX * (1 - smoothS), 0, 0)

        
        elseif key == "leg_RR" then
            local legZ = math.sin(stridePhase) * 0.35 * mAlpha
            local legLift = math.max(0, -math.cos(stridePhase)) * 0.16 * mAlpha
            local legRotX = math.sin(stridePhase) * 12 * mAlpha

            local pStand = Vector3.new(0.82, -1.60 + legLift, -2.35 + legZ)
            local pSleep = Vector3.new(0.82, -3.40, -2.15)
            local pos = lerpVec3(pStand, pSleep, smoothS)
            return pos, Vector3.new(legRotX * (1 - smoothS), 0, 0)

        
        elseif key == "tail" then
            local pStand = Vector3.new(0, 2.10 + breathY * 0.7 + runBounce * 0.5, -3.80)
            local pSleep = Vector3.new(0.35, 0.35 + breathY * 0.4, -3.75)
            local pos = lerpVec3(pStand, pSleep, smoothS)
            local rotX = lerp(-52 + tailPitchWave, -78, smoothS)
            local rotY = lerp(tailDynamicSway + (math.sin(stridePhase) * 8 * mAlpha), 35 + math.sin(t * 0.9) * 2.5, smoothS)
            return pos, Vector3.new(rotX, rotY, 0)

        
        elseif key == "saddle" then
            local pStand = Vector3.new(0, 4.30 + breathY + runBounce, -0.40)
            local pSleep = Vector3.new(0, 2.90 + breathY, -0.40)
            local pos = lerpVec3(pStand, pSleep, smoothS)
            return pos, Vector3.new(0, 180, 0)
        end

        return Vector3.new(0, 0, 0), Vector3.new(0, 0, 0)
    end

    local function _0xH_3eb(key, anchor, yaw, t, sAlpha, mAlpha, stridePhase)
        local baseCF = CFrame.new(anchor) * CFrame.Angles(0, yaw, 0)

        
        if key == "ear_L" or key == "ear_R" then
            local headPos, headRot = computeDynamicPartPose("head", t, sAlpha, mAlpha, stridePhase)
            local headCF = baseCF * CFrame.new(headPos) * CFrame.Angles(
                math.rad(headRot.X),
                math.rad(headRot.Y),
                math.rad(headRot.Z)
            )

            local twitchWaveL = math.clamp(math.sin(t * 0.38) - 0.88, 0, 1) * 9.0 * math.sin(t * 22) * (1 - (sAlpha or 0) * 0.8)
            local twitchWaveR = math.clamp(math.cos(t * 0.42) - 0.88, 0, 1) * 9.0 * math.sin(t * 24) * (1 - (sAlpha or 0) * 0.8)

            if key == "ear_L" then
                
                local localOffset = CFrame.new(0.14, 0.63, 0)
                local localRot = CFrame.Angles(0, math.rad(-90), 0) * CFrame.Angles(math.rad(twitchWaveL), 0, 0)
                return headCF * localOffset * localRot
            else
                local localOffset = CFrame.new(-0.04, 0.63, 0)
                local localRot = CFrame.Angles(0, 0, 0) * CFrame.Angles(math.rad(twitchWaveR), 0, 0)
                return headCF * localOffset * localRot
            end
        end

        local pos, rot = computeDynamicPartPose(key, t, sAlpha, mAlpha, stridePhase)
        local offsetCF = CFrame.new(pos) * CFrame.Angles(
            math.rad(rot.X),
            math.rad(rot.Y),
            math.rad(rot.Z)
        )
        return baseCF * offsetCF
    end

    local function startCatWorker(w)
        task.spawn(function()
            while catActive and w.scf do
                local now = tick()
                if w.targetCF then
                    local cf = w.targetCF
                    local send = false
                    if not w.lastSentCF then
                        send = true
                    else
                        local pDiff = (cf.Position - w.lastSentCF.Position).Magnitude
                        if pDiff > 0.02 or (now - w.lastSendTimeCF > 0.08) then
                            send = true
                        end
                    end
                    if send then
                        w.lastSentCF = cf
                        w.lastSendTimeCF = now
                        pcall(function() w.scf:InvokeServer(cf) end)
                        if (now - (w.lastNeonCheck or 0) > 0.8) and w.prop then
                            w.lastNeonCheck = now
                            for _, d in ipairs(w.prop:GetDescendants()) do
                                if d:IsA("BasePart") and (d.Material == Enum.Material.Neon or d.Color ~= currentCatColor) then
                                    pcall(function()
                                        d.Material = Enum.Material.SmoothPlastic
                                        if currentCatColor then d.Color = currentCatColor end
                                    end)
                                elseif d:IsA("Light") and d.Enabled then
                                    d.Enabled = false
                                    d.Brightness = 0
                                end
                            end
                        end
                    end
                end
                task.wait(0.04)
            end
        end)
    end

    local function updateCatColor(newColor)
        currentCatColor = newColor
        for _, w in pairs(catWorkers) do
            if w.cpc then
                pcall(function() w.cpc:InvokeServer(newColor) end)
            end
            if w.prop then
                for _, d in ipairs(w.prop:GetDescendants()) do
                    if d:IsA("BasePart") then
                        pcall(function()
                            d.Material = Enum.Material.SmoothPlastic
                            d.Color = newColor
                        end)
                    end
                end
            end
        end
    end

    local function spawnCatCompanion()
        local char = lp.Character or lp.CharacterAdded:Wait()
        local hrp = char:WaitForChild("HumanoidRootPart")

        local RE = game:GetService("ReplicatedStorage"):WaitForChild("RE")
        local clearTools = RE:WaitForChild("1Clea1rTool1s")
        local toolRE = RE:WaitForChild("1Too1l")
        local Telemetry = game:GetService("ReplicatedStorage"):WaitForChild("Remotes"):WaitForChild("TelemetryClientInteraction")

        pcall(function() clearTools:FireServer("ClearAllProps") end)
        task.wait(0.5)

        local pm = _0xH_3f2()
        if not pm then
            cNotif("Cat Companion", "PropMaker not found!", 3)
            return
        end

        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then hum:EquipTool(pm) end
        task.wait(0.4)

        local toolPropMake = pm:FindFirstChild("Tool_PropMake") or pm:WaitForChild("Tool_PropMake", 3)
        if not toolPropMake then return end

        pcall(function() clearTools:FireServer("OpenPropMenu") end)
        task.wait(0.2)

        local fwd = hrp.CFrame.LookVector
        local forwardPos = hrp.Position + (fwd * 12) + Vector3.new(0, 10, 0)
        local rayParams = RaycastParams.new()
        rayParams.FilterDescendantsInstances = {char}
        rayParams.FilterType = Enum.RaycastFilterType.Exclude
        local groundRay = workspace:Raycast(forwardPos, Vector3.new(0, -40, 0), rayParams)
        local groundY = groundRay and groundRay.Position.Y or (hrp.Position.Y - 2.5)

        catAnchor = Vector3.new(forwardPos.X, groundY, forwardPos.Z)
        catAngle = math.atan2(fwd.X, fwd.Z)
        catWorkers = {}
        catSleepAlpha = 0
        catTargetSleepAlpha = 0
        catIsSleeping = false

        local myPropName = "Prop" .. lp.Name
        local knownScf = {}
        for _, folder in pairs(workspace:WaitForChild("WorkspaceCom"):GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName then
                    local scf = prop:FindFirstChild("SetCurrentCFrame")
                    if scf then knownScf[scf] = true end
                end
            end
        end

        local hitInst = workspace.Terrain

        for i, part in ipairs(CAT_BASE_BLUEPRINT) do
            if not catActive then break end

            local initialCF = _0xH_3eb(part.key, catAnchor, catAngle, 0, 0, 0, 0)

            pcall(function() Telemetry:FireServer("filterClick", {name = part.cat, itemType = "Props"}) end)
            task.wait(0.04)
            pcall(function() Telemetry:FireServer("filterClick", {name = part.prop, itemType = "Props"}) end)
            task.wait(0.04)
            pcall(function()
                if part.prop == "FloorCushion" then
                    clearTools:FireServer("RequestingPropFeatureName", part.prop, part.cat)
                else
                    clearTools:FireServer("RequestingPropName", part.prop, part.cat)
                end
            end)
            task.wait(0.18)

            pcall(function() toolPropMake:FireServer(hitInst, catAnchor) end)
            task.wait(0.65)

            local foundProp, foundScf, foundCpc = nil, nil, nil
            for _, folder in pairs(workspace:WaitForChild("WorkspaceCom"):GetChildren()) do
                for _, prop in pairs(folder:GetChildren()) do
                    if prop.Name == myPropName then
                        local scf = prop:FindFirstChild("SetCurrentCFrame")
                        local cpc = prop:FindFirstChild("ChangePropColor")
                        if scf and not knownScf[scf] then
                            foundProp = prop
                            foundScf = scf
                            foundCpc = cpc
                            knownScf[scf] = true
                            break
                        end
                    end
                end
                if foundScf then break end
            end

            if foundProp then
                for _, d in ipairs(foundProp:GetDescendants()) do
                    if d:IsA("Seat") or d:IsA("VehicleSeat") then
                        pcall(function() d.CanCollide = false end)
                        if part.key == "saddle" then
                            catSeat = d
                        end
                    elseif d:IsA("Light") then
                        d.Enabled = false
                        d.Brightness = 0
                        pcall(function() d:Destroy() end)
                    elseif d:IsA("BasePart") then
                        pcall(function()
                            d.Material = Enum.Material.SmoothPlastic
                            if part.key == "saddle" then
                                d.Color = Color3.fromRGB(42, 34, 30)
                                d.CanCollide = false
                            elseif currentCatColor then
                                d.Color = currentCatColor
                            end
                        end)
                    end
                end
            end

            local w = {
                key = part.key,
                prop = foundProp,
                scf = foundScf,
                cpc = foundCpc,
                targetCF = initialCF,
                lastSentCF = nil,
                lastSendTimeCF = 0
            }
            catWorkers[part.key] = w

            if foundScf then
                pcall(function() foundScf:InvokeServer(initialCF) end)
            end
            if foundCpc then
                pcall(function() foundCpc:InvokeServer(currentCatColor) end)
            end

            startCatWorker(w)
        end

        task.wait(1.0)
        pcall(function()
            toolRE:InvokeServer("PickingTools", "PropMaker")
        end)
        pcall(function() clearTools:FireServer("ClosePropMenu") end)

        cNotif("Cat Companion", "Feline Companion spawned!", 3)

        if catLoop then catLoop:Disconnect() catLoop = nil end
        catLoop = game:GetService("RunService").Heartbeat:Connect(function(dt)
            if not catActive then return end
            catAnimTime = catAnimTime + dt

            if catSleepAlpha < catTargetSleepAlpha then
                catSleepAlpha = math.min(catTargetSleepAlpha, catSleepAlpha + dt * 1.5)
            elseif catSleepAlpha > catTargetSleepAlpha then
                catSleepAlpha = math.max(catTargetSleepAlpha, catSleepAlpha - dt * 1.5)
            end

            
            local char = lp.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if catFollowActive and hrp and catSleepAlpha < 0.2 then
                local wsCom = workspace:FindFirstChild("WorkspaceCom")
                local ignoreList = {char}
                if wsCom then table.insert(ignoreList, wsCom) end
                local rayParams = RaycastParams.new()
                rayParams.FilterDescendantsInstances = ignoreList
                rayParams.FilterType = Enum.RaycastFilterType.Exclude

                local function getSafeGroundY(pos)
                    local gRay = workspace:Raycast(Vector3.new(pos.X, pos.Y + 3.5, pos.Z), Vector3.new(0, -14, 0), rayParams)
                    if gRay and gRay.Instance and gRay.Instance.CanCollide then
                        return gRay.Position.Y
                    end
                    return hrp.Position.Y - 2.85
                end

                local targetFollowPos = hrp.Position - (hrp.CFrame.LookVector * 4.8) + (hrp.CFrame.RightVector * 2.2)
                local targetGroundY = getSafeGroundY(targetFollowPos)
                local targetVec = Vector3.new(targetFollowPos.X, targetGroundY, targetFollowPos.Z)

                local toTarget = Vector3.new(targetVec.X - catAnchor.X, 0, targetVec.Z - catAnchor.Z)
                local hDist = toTarget.Magnitude

                if hDist > 90 then
                    catAnchor = targetVec
                    catAngle = math.atan2(hrp.CFrame.LookVector.X, hrp.CFrame.LookVector.Z)
                    catMoveAlpha = 0
                elseif hDist > 2.8 then
                    local hDir = toTarget.Unit
                    local targetAngle = math.atan2(hDir.X, hDir.Z)
                    local diffAngle = (targetAngle - catAngle + math.pi) % (math.pi * 2) - math.pi
                    catAngle = catAngle + diffAngle * math.clamp(dt * 7.0, 0, 1)

                    local catSpeed = math.clamp(hDist * 2.6 + 6, 12, 22)
                    local stepDist = math.min(hDist - 2.0, catSpeed * dt)
                    local step = hDir * stepDist

                    local newX = catAnchor.X + step.X
                    local newZ = catAnchor.Z + step.Z

                    
                    local groundY = getSafeGroundY(Vector3.new(newX, catAnchor.Y, newZ))
                    local smoothY = catAnchor.Y + (groundY - catAnchor.Y) * math.clamp(dt * 10, 0, 1)

                    catAnchor = Vector3.new(newX, smoothY, newZ)
                    catMoveAlpha = math.min(1, catMoveAlpha + dt * 4.0)
                    catRunStride = catRunStride + dt * (catSpeed * 0.45)
                else
                    catMoveAlpha = math.max(0, catMoveAlpha - dt * 3.5)
                    local groundY = getSafeGroundY(catAnchor)
                    local smoothY = catAnchor.Y + (groundY - catAnchor.Y) * math.clamp(dt * 8, 0, 1)
                    catAnchor = Vector3.new(catAnchor.X, smoothY, catAnchor.Z)

                    if catMoveAlpha < 0.2 then
                        local toPlayer = Vector3.new(hrp.Position.X - catAnchor.X, 0, hrp.Position.Z - catAnchor.Z)
                        if toPlayer.Magnitude > 0.5 then
                            local lookAngle = math.atan2(toPlayer.X, toPlayer.Z)
                            local diffAngle = (lookAngle - catAngle + math.pi) % (math.pi * 2) - math.pi
                            catAngle = catAngle + diffAngle * math.clamp(dt * 4.5, 0, 1)
                        end
                    end
                end
            else
                catMoveAlpha = math.max(0, catMoveAlpha - dt * 3.5)
            end

            for key, w in pairs(catWorkers) do
                w.targetCF = _0xH_3eb(key, catAnchor, catAngle, catAnimTime, catSleepAlpha, catMoveAlpha, catRunStride)
            end
        end)
    end

    
    BuildV2Tab:AddSection({"> Feline Companion"})

    BuildV2Tab:AddToggle({
        Name = "Spawn Cat Companion",
        Description = "Summon an animated realistic 10-prop feline companion with mountable beanbag cushion",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            if not val and not catActive then return end
            if val then
                catActive = true
                task.spawn(spawnCatCompanion)
            else
                if not catActive then return end
                catActive = false
                catSeat = nil
                if catLoop then catLoop:Disconnect() catLoop = nil end
                pcall(function()
                    game:GetService("ReplicatedStorage"):WaitForChild("RE"):WaitForChild("1Clea1rTool1s"):FireServer("ClearAllProps")
                end)
                catWorkers = {}
                catIsSleeping = false
                catFollowActive = false
                catMoveAlpha = 0
                catRunStride = 0
                catTargetSleepAlpha = 0
                cNotif("Cat Companion", "Cat dismissed.", 2)
            end
        end
    })

    BuildV2Tab:AddButton({
        Name = "Mount / Dismount Cat",
        Description = "Sit comfortably on the beanbag cushion for a fun stroll",
        Callback = function()
            if not catActive then
                cNotif("Cat Companion", "Spawn the cat first!", 2)
                return
            end
            local char = lp.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not hum then return end

            if hum.Sit then
                hum.Sit = false
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                cNotif("Cat Companion", "Dismounted.", 2)
            else
                if catSeat then
                    pcall(function()
                        catSeat.CanCollide = false
                        catSeat:Sit(hum)
                    end)
                    cNotif("Cat Companion", "Mounted! Enjoy the stroll!", 2)
                else
                    cNotif("Cat Companion", "Beanbag cushion not found!", 2)
                end
            end
        end
    })

    BuildV2Tab:AddButton({
        Name = "Toggle Follow Me",
        Description = "Cat follows you with realistic running strides and stops when you stop",
        Callback = function()
            if not catActive then
                cNotif("Cat Companion", "Spawn the cat first!", 2)
                return
            end
            catFollowActive = not catFollowActive
            if catFollowActive then
                catIsSleeping = false
                catTargetSleepAlpha = 0
            end
            cNotif("Cat Companion", catFollowActive and "Cat is now following you!" or "Cat stopped following.", 2)
        end
    })

    BuildV2Tab:AddButton({
        Name = "Toggle Sleep / Stand",
        Description = "Smoothly toggle posture between standing on all 4 legs and sleeping flat",
        Callback = function()
            if not catActive then
                cNotif("Cat Companion", "Spawn the cat first!", 2)
                return
            end
            catIsSleeping = not catIsSleeping
            catTargetSleepAlpha = catIsSleeping and 1 or 0
            cNotif("Cat Companion", catIsSleeping and "Cat is laying down flat to sleep..." or "Cat is rising to its feet...", 2)
        end
    })

    BuildV2Tab:AddDropdown({
        Name = "Cat Breed",
        Description = "Choose the cat breed and coat color theme",
        Options = {"Bombay (Black)", "Ginger Tabby (Orange)", "Snow Angora (White)", "Russian Blue (Grey)", "Siamese (Cream)", "Caramel (Golden)"},
        Default = "Bombay (Black)",
        Callback = function(choice)
            currentBreed = choice
            local col = CAT_BREEDS[choice]
            if col then
                updateCatColor(col)
                cNotif("Cat Breed", "Coat changed to " .. choice, 2)
            end
        end
    })

    BuildV2Tab:AddButton({
        Name = "Teleport In Front",
        Description = "Reposition the cat directly in front of you",
        Callback = function()
            local char = lp.Character or lp.CharacterAdded:Wait()
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hrp and catActive then
                local forwardPos = hrp.Position + (hrp.CFrame.LookVector * 12)
                local rayParams = RaycastParams.new()
                rayParams.FilterDescendantsInstances = {char}
                rayParams.FilterType = Enum.RaycastFilterType.Exclude

                local gRay = workspace:Raycast(forwardPos + Vector3.new(0, 35, 0), Vector3.new(0, -80, 0), rayParams)
                local groundY = gRay and gRay.Position.Y or (hrp.Position.Y - 2.5)

                catAnchor = Vector3.new(forwardPos.X, groundY, forwardPos.Z)
                catAngle = math.atan2(hrp.CFrame.LookVector.X, hrp.CFrame.LookVector.Z)
                cNotif("Cat Companion", "Repositioned in front of you!", 2)
            end
        end
    })
end

                                                             
