    local function getPartColorForTheme(themeName, key)
        if themeName == "Realistic (Default)" then
            return Color3.fromRGB(52, 34, 22)
        end
        if themeName == "Full Black" then
            return Color3.fromRGB(12, 12, 14)
        end
        local theme = SCORPION_THEMES[themeName] or SCORPION_THEMES["Realistic (Default)"]
        if key == "Torso" or key == "Tail_1" or key == "Tail_2" then
            return theme.Torso or Color3.fromRGB(52, 34, 22)
        elseif key:sub(1, 4) == "Leg_" then
            return theme.Legs or Color3.fromRGB(52, 34, 22)
        elseif key:sub(1, 4) == "Arm_" or key:sub(1, 4) == "Claw" then
            return theme.Claws or Color3.fromRGB(52, 34, 22)
        elseif key == "Stinger" then
            return theme.Stinger or (theme.Torso or Color3.fromRGB(52, 34, 22))
        end
        return Color3.fromRGB(52, 34, 22)
    end

    local function _0xH_404(w, col)
        if not w or w.key == "Saddle" or not col then return end
        if w.cpc then
            pcall(function() w.cpc:InvokeServer(col) end)
        end
        if w.prop then
            for _, d in ipairs(w.prop:GetDescendants()) do
                if d:IsA("BasePart") then
                    pcall(function()
                        d.Material = Enum.Material.SmoothPlastic
                        d.Color = col
                    end)
                end
            end
        end
    end

    local function applyTheme(themeName)
        currentTheme = themeName
        isRainbowMode = (themeName == "Rainbow")
        if isRainbowMode then
            sNotif("Scorpion", "Rainbow Mode On!", 2)
            return
        end

        for key, w in pairs(scorpionWorkers) do
            if w.key ~= "Saddle" then
                local col = getPartColorForTheme(themeName, key)
                _0xH_404(w, col)
            end
        end
        sNotif("Scorpion", "Color: " .. themeName, 2)
    end

