    local function getGroundPos(pos)
        local char = lp.Character
        local wsCom = ws:FindFirstChild("WorkspaceCom")
        local ignoreList = {}
        if char then table.insert(ignoreList, char) end
        if wsCom then table.insert(ignoreList, wsCom) end

        local rayParams = RaycastParams.new()
        rayParams.FilterType = Enum.RaycastFilterType.Exclude
        rayParams.FilterDescendantsInstances = ignoreList

        local ray = ws:Raycast(Vector3.new(pos.X, pos.Y + 4.0, pos.Z), Vector3.new(0, -24.0, 0), rayParams)
        if ray and ray.Instance and ray.Instance.CanCollide then
            return Vector3.new(pos.X, ray.Position.Y, pos.Z)
        end

        local deepRay = ws:Raycast(Vector3.new(pos.X, pos.Y + 12.0, pos.Z), Vector3.new(0, -50.0, 0), rayParams)
        if deepRay and deepRay.Instance and deepRay.Instance.CanCollide then
            return Vector3.new(pos.X, deepRay.Position.Y, pos.Z)
        end

        return Vector3.new(pos.X, pos.Y, pos.Z)
    end

    local function getPropMakerTool()
        local char = lp.Character or lp.CharacterAdded:Wait()
        local backpack = lp:WaitForChild("Backpack")
        local pm = char:FindFirstChild("PropMaker") or backpack:FindFirstChild("PropMaker")
        if not pm then
            local toolRE = rep:WaitForChild("RE"):WaitForChild("1Too1l")
            pcall(function() toolRE:InvokeServer("PickingTools", "PropMaker") end)
            local start = tick()
            while tick() - start < 3 do
                pm = char:FindFirstChild("PropMaker") or backpack:FindFirstChild("PropMaker")
                if pm then break end
                task.wait(0.1)
            end
        end
        return pm
    end

    local function startWorker(w)
        task.spawn(function()
            while scorpionActive and w.scf and w.scf.Parent do
                local now = tick()
                if w.targetCF then
                    local cf = w.targetCF
                    local send = false
                    if not w.lastSentCF then
                        send = true
                    else
                        local pDiff = (cf.Position - w.lastSentCF.Position).Magnitude
                        if pDiff > 0.03 or (now - w.lastSendTimeCF > 0.08) then
                            send = true
                        end
                    end
                    if send then
                        w.lastSentCF = cf
                        w.lastSendTimeCF = now
                        task.spawn(function()
                            pcall(function()
                                w.scf:InvokeServer(cf)
                            end)
                        end)
                        if not isRainbowMode and w.prop and (now - (w.lastColorCheck or 0) > 0.6) then
                            w.lastColorCheck = now
                            local targetCol = getPartColorForTheme(currentTheme, w.key)
                            for _, d in ipairs(w.prop:GetDescendants()) do
                                if d:IsA("BasePart") and w.key ~= "Saddle" and (d.Material ~= Enum.Material.SmoothPlastic or d.Color ~= targetCol) then
                                    pcall(function()
                                        d.Material = Enum.Material.SmoothPlastic
                                        d.Color = targetCol
                                    end)
                                end
                            end
                        end
                    end
                end
                task.wait(0.03)
            end
        end)
    end

    local function triggerStingerStrike()
        if not scorpionActive then
            sNotif("Scorpion", "Spawn the scorpion first!", 2)
            return
        end
        if isStriking then return end
        isStriking = true

        if _0xH_437 then task.cancel(_0xH_437) end
        _0xH_437 = task.spawn(function()
            local t0 = tick()
            while tick() - t0 < 0.12 do
                local a = (tick() - t0) / 0.12
                _0xH_428 = -0.35 * math.sin(a * math.pi * 0.5)
                task.wait(0.02)
            end

            local t1 = tick()
            while tick() - t1 < 0.09 do
                local a = (tick() - t1) / 0.09
                local _0xH_429 = 1 - (1 - a) * (1 - a) * (1 - a)
                _0xH_428 = -0.35 + (1.0 - (-0.35)) * _0xH_429
                task.wait(0.02)
            end
            _0xH_428 = 1.0

            task.wait(0.10)

            local t2 = tick()
            while tick() - t2 < 0.18 do
                local a = (tick() - t2) / 0.18
                local _0xH_42a = a < 0.5 and 2 * a * a or 1 - math.pow(-2 * a + 2, 2) / 2
                _0xH_428 = 1.0 * (1 - _0xH_42a)
                task.wait(0.02)
            end

            _0xH_428 = 0
            isStriking = false
        end)
    end

    local function removeScorpionPilotHUD()
        scorpionUIForward = false
        scorpionUIBackward = false
        scorpionUILeft = false
        scorpionUIRight = false
        scorpionUIBoost = false
        if scorpionPilotGui then
            pcall(function() scorpionPilotGui:Destroy() end)
            scorpionPilotGui = nil
        end
        scorpionPilotFrame = nil
    end

    local function setupScorpionPilotHUD()
        if scorpionPilotGui then pcall(function() scorpionPilotGui:Destroy() end) end
        scorpionPilotGui = Instance.new("ScreenGui")
        scorpionPilotGui.Name = "BTR_ScorpionPilotHUD"
        scorpionPilotGui.ResetOnSpawn = false
        scorpionPilotGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        local parent = (gethui and gethui()) or game:GetService("CoreGui") or lp:FindFirstChildOfClass("PlayerGui")

        local frame = Instance.new("Frame")
        frame.Name = "MainFrame"
        frame.AnchorPoint = Vector2.new(0.5, 1)
        frame.Position = UDim2.new(0.5, 0, 1, -14)
        frame.Size = UDim2.new(0, 520, 0, 118)
        frame.BackgroundColor3 = Color3.fromRGB(22, 14, 12)
        frame.BackgroundTransparency = 0.12
        frame.Parent = scorpionPilotGui
        scorpionPilotFrame = frame

        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 12)
        corner.Parent = frame
        local stroke = Instance.new("UIStroke")
        stroke.Color = Color3.fromRGB(225, 125, 60)
        stroke.Thickness = 1.5
        stroke.Transparency = 0.35
        stroke.Parent = frame

        local title = Instance.new("TextLabel")
        title.Size = UDim2.new(1, -16, 0, 22)
        title.Position = UDim2.new(0, 8, 0, 4)
        title.BackgroundTransparency = 1
        title.Text = "SCORPION • MOBILE RIDING CONTROLS"
        title.TextColor3 = Color3.fromRGB(255, 185, 95)
        title.Font = Enum.Font.GothamBold
        title.TextSize = 11
        title.TextXAlignment = Enum.TextXAlignment.Left
        title.Parent = frame

        local function makeBtn(name, text, x, y, w, h, onClick, onDown, onUp)
            local btn = Instance.new("TextButton")
            btn.Name = name
            btn.Position = UDim2.new(0, x, 0, y)
            btn.Size = UDim2.new(0, w or 58, 0, h or 36)
            btn.BackgroundColor3 = Color3.fromRGB(48, 32, 24)
            btn.BackgroundTransparency = 0.08
            btn.AutoButtonColor = true
            btn.Text = text
            btn.TextColor3 = Color3.fromRGB(245, 245, 245)
            btn.Font = Enum.Font.GothamBold
            btn.TextSize = 10
            btn.Parent = frame
            local bc = Instance.new("UICorner")
            bc.CornerRadius = UDim.new(0, 8)
            bc.Parent = btn
            local bs = Instance.new("UIStroke")
            bs.Color = Color3.fromRGB(120, 90, 70)
            bs.Transparency = 0.45
            bs.Parent = btn
            if onClick then btn.Activated:Connect(onClick) end
            if onDown then
                btn.MouseButton1Down:Connect(onDown)
                btn.InputBegan:Connect(function(inp)
                    if inp.UserInputType == Enum.UserInputType.Touch or inp.UserInputType == Enum.UserInputType.MouseButton1 then onDown() end
                end)
            end
            if onUp then
                btn.MouseButton1Up:Connect(onUp)
                btn.InputEnded:Connect(function(inp)
                    if inp.UserInputType == Enum.UserInputType.Touch or inp.UserInputType == Enum.UserInputType.MouseButton1 then onUp() end
                end)
            end
        end

        -- Steering uses Roblox's native joystick through Humanoid.MoveDirection, like Leviathan.
        makeBtn("Sprint", "SPRINT", 68, 30, 76, 34, nil, function() scorpionUIBoost = true end, function() scorpionUIBoost = false end)
        makeBtn("Stinger", "STINGER", 150, 30, 78, 34, function() triggerStingerStrike() end)
        makeBtn("Mount", "MOUNT", 234, 30, 70, 34, function()
            if not scorpionActive then return end
            local char = lp.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not hum then return end
            if hum.Sit then
                hum.Sit = false
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                removeScorpionPilotHUD()
            elseif scorpionSeat then
                pcall(function()
                    scorpionSeat.CanCollide = false
                    scorpionSeat:Sit(hum)
                end)
            end
        end)
        makeBtn("Exit", "EXIT", 310, 30, 70, 34, function()
            local hum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
            if hum then hum.Sit = false end
            removeScorpionPilotHUD()
        end)

        local hint = Instance.new("TextLabel")
        hint.Size = UDim2.new(1, -156, 0, 24)
        hint.Position = UDim2.new(0, 156, 0, 70)
        hint.BackgroundTransparency = 1
        hint.Text = "Use the Roblox joystick • Space/F = stinger"
        hint.TextColor3 = Color3.fromRGB(190, 180, 170)
        hint.Font = Enum.Font.Gotham
        hint.TextSize = 9
        hint.TextXAlignment = Enum.TextXAlignment.Left
        hint.Parent = frame

