    local function _0xH_3f2()
        local backpack = lp:FindFirstChild("Backpack")
        local character = lp.Character
        if not backpack or not character then return nil end
        local tool = character:FindFirstChild("PropMaker") or backpack:FindFirstChild("PropMaker")
        if not tool then
            pcall(function() toolRE:InvokeServer("PickingTools", "PropMaker") end)
            local start = tick()
            while tick() - start < 2.0 do
                tool = character:FindFirstChild("PropMaker") or backpack:FindFirstChild("PropMaker")
                if tool then break end
                task.wait(0.05)
            end
        end
        if not tool then return nil end

        if tool.Parent ~= character then
            local hum = character:FindFirstChildOfClass("Humanoid")
            if hum then
                hum:EquipTool(tool)
                local eqStart = tick()
                while tick() - eqStart < 2.0 do
                    if tool.Parent == character then break end
                    task.wait(0.05)
                end
            end
        end
        return tool
    end

    local function _0xH_3f3(firstProp, countNeeded)
        if not firstProp then return false end
        local dupRemote = firstProp:FindFirstChild("DuplicateProp") or firstProp:WaitForChild("DuplicateProp", 2)
        if not dupRemote then return false end

        for i = 1, countNeeded do
            pcall(function() dupRemote:InvokeServer() end)
            task.wait(0.05)
        end
        return true
    end

    local senders = {}
    local RATE_LIMIT = 0.03

    local function sendCF(scf, cf, prop)
        if not gorillaActive or not scf then return end

        if prop then
            pcall(function()
                if prop:IsA("Model") then
                    prop:PivotTo(cf)
                elseif prop:IsA("BasePart") then
                    prop.CFrame = cf
                end
            end)
        end

        local entry = senders[scf]
        local now = tick()
        if not entry then
            entry = { lastSent = 0, nextCF = cf, sending = false }
            senders[scf] = entry
        else
            entry.nextCF = cf
        end

        if not entry.sending and (now - entry.lastSent >= RATE_LIMIT) then
            entry.sending = true
            entry.lastSent = now
            local toSend = entry.nextCF
            entry.nextCF = nil
            task.spawn(function()
                pcall(function() scf:InvokeServer(toSend) end)
                entry.sending = false
                if gorillaActive and entry.nextCF and (tick() - entry.lastSent >= RATE_LIMIT) then
                    entry.sending = true
                    entry.lastSent = tick()
                    local nextSend = entry.nextCF
                    entry.nextCF = nil
                    task.spawn(function()
                        pcall(function() scf:InvokeServer(nextSend) end)
                        entry.sending = false
                    end)
                end
            end)
        end
    end

    local function getTargetSurface(targetWorldPos)
        local street = ws:FindFirstChild("Model") and ws.Model:FindFirstChild("Street") and ws.Model.Street:FindFirstChild("Street")

        local rayParams = RaycastParams.new()
        rayParams.FilterDescendantsInstances = {lp.Character, ws:FindFirstChild("WorkspaceCom")}
        rayParams.FilterType = Enum.RaycastFilterType.Exclude

        local ray = ws:Raycast(targetWorldPos + Vector3.new(0, 10, 0), Vector3.new(0, -30, 0), rayParams)
        local hitInst = street or (ray and ray.Instance) or ws.Terrain
        local hitPos = ray and ray.Position or targetWorldPos

        return hitInst, hitPos
    end

    local function setCharacterHidden(hidden)
        local char = lp.Character
        if not char then return end
        if hidden then
            savedTransparencies = {}
            for _, part in pairs(char:GetDescendants()) do
                if part:IsA("BasePart") or part:IsA("Decal") then
                    savedTransparencies[part] = part.Transparency
                    part.Transparency = 1
                end
            end
        else
            for part, origVal in pairs(savedTransparencies) do
                if part and part.Parent then
                    part.Transparency = origVal
                end
            end
            savedTransparencies = {}
        end
    end

    local function applyPlayerLift(newVal)
        local char = lp.Character
        if char then
            local hum = char:FindFirstChildOfClass("Humanoid")
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hum and hrp then
                hum.HipHeight = newVal
                if newVal > 3.0 then
                    hrp.CFrame = hrp.CFrame + Vector3.new(0, 0.5, 0)
                end
            end
        end
    end

    local function smoothClimbTo(targetVal, step)
        step = step or 2.0
        task.spawn(function()
            local char = lp.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            local current = (hum and hum.HipHeight) or 2.0
            if current < targetVal then
                for v = current + step, targetVal, step do
                    applyPlayerLift(v)
                    task.wait(0.02)
                end
                applyPlayerLift(targetVal)
            else
                for v = current - step, targetVal, -step do
                    applyPlayerLift(v)
                    task.wait(0.02)
                end
                applyPlayerLift(targetVal)
            end
        end)
    end

    local function loadAnim(animator, primaryId, containerId)
        local animTrack = nil
        if containerId then
            pcall(function()
                local objs = game:GetObjects(containerId)
                if objs and #objs > 0 then
                    local a = objs[1]:IsA("Animation") and objs[1] or objs[1]:FindFirstChildWhichIsA("Animation", true)
                    if a then
                        animTrack = animator:LoadAnimation(a)
                    end
                end
            end)
        end
        if not animTrack and primaryId then
            pcall(function()
                local a = Instance.new("Animation")
                a.AnimationId = primaryId
                animTrack = animator:LoadAnimation(a)
            end)
        end
        if not animTrack and primaryId then
            pcall(function()
                local objs = game:GetObjects(primaryId)
                if objs and #objs > 0 then
                    local a = objs[1]:IsA("Animation") and objs[1] or objs[1]:FindFirstChildWhichIsA("Animation", true)
                    if a then
                        animTrack = animator:LoadAnimation(a)
                    end
                end
            end)
        end
        if not animTrack and containerId then
            pcall(function()
                local a = Instance.new("Animation")
                a.AnimationId = containerId
                animTrack = animator:LoadAnimation(a)
            end)
        end
        if animTrack then
            animTrack.Looped = true
        end
        return animTrack
    end

    local function setupGhostRig()
        pcall(function()
            if ghostRig then
                ghostRig:Destroy()
                ghostRig = nil
            end
        end)

        local clone = nil
        pcall(function()
            local desc = Instance.new("HumanoidDescription")
            desc.HeightScale = 1.0
            desc.WidthScale = 1.0
            desc.DepthScale = 1.0
            desc.HeadScale = 1.0
            desc.BodyTypeScale = 0.0
            desc.ProportionScale = 0.0
            clone = game:GetService("Players"):CreateHumanoidModelFromDescription(desc, Enum.HumanoidRigType.R15)
        end)

        if not clone then
            local myChar = lp.Character or lp.CharacterAdded:Wait()
            myChar.Archivable = true
            clone = myChar:Clone()
            myChar.Archivable = false
            local hum = clone:FindFirstChildOfClass("Humanoid")
            if hum then
                for _, scaleName in ipairs({"BodyHeightScale", "BodyWidthScale", "BodyDepthScale", "HeadScale", "BodyTypeScale", "BodyProportionScale"}) do
                    local sVal = hum:FindFirstChild(scaleName)
                    if sVal and sVal:IsA("NumberValue") then
                        sVal.Value = 1.0
                    end
                end
                pcall(function() hum:BuildRigFromAttachments() end)
            end
        end

        clone.Name = "TitanGorilla_GhostRig"
        for _, desc in ipairs(clone:GetDescendants()) do
            if desc:IsA("BasePart") then
                desc.Transparency = 1
                desc.CanCollide = false
                desc.CanTouch = false
                desc.CanQuery = false
                desc.CastShadow = false
                desc.Massless = true
            elseif desc:IsA("Script") or desc:IsA("LocalScript") or desc:IsA("Sound") then
                desc:Destroy()
            end
        end

        local root = clone:FindFirstChild("HumanoidRootPart")
        if root then
            root.Anchored = true
            root.CFrame = CFrame.new(0, -500, 0)
        end

        clone.Parent = ws
        ghostRig = clone

        local hum = clone:FindFirstChildOfClass("Humanoid")
        if hum then
            hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
            local animator = hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum)

            ghostWalkTrack = loadAnim(animator, GORILLA_ANIMS.Walk, GORILLA_ANIMS.WalkAsset)
            ghostRunTrack = loadAnim(animator, GORILLA_ANIMS.Run, GORILLA_ANIMS.RunAsset)
            ghostIdleTrack = loadAnim(animator, GORILLA_ANIMS.Idle, GORILLA_ANIMS.IdleAsset)

            if ghostIdleTrack then
                ghostIdleTrack.Priority = Enum.AnimationPriority.Action4
                ghostIdleTrack.Looped = true
                ghostIdleTrack:Play()
            end
            if ghostRunTrack then
                ghostRunTrack.Priority = Enum.AnimationPriority.Action4
                ghostRunTrack.Looped = true
            end
            if ghostWalkTrack then
                ghostWalkTrack.Priority = Enum.AnimationPriority.Action4
                ghostWalkTrack.Looped = true
            end
        end

        return ghostRig
    end

    local function cleanGhostRig()
        if ghostWalkTrack then pcall(function() ghostWalkTrack:Stop() end) ghostWalkTrack = nil end
        if ghostIdleTrack then pcall(function() ghostIdleTrack:Stop() end) ghostIdleTrack = nil end
        if ghostRunTrack  then pcall(function() ghostRunTrack:Stop() end) ghostRunTrack = nil end
        if ghostRig then
            pcall(function() ghostRig:Destroy() end)
            ghostRig = nil
        end
    end

    local function getGhostLimb(rig, limbName)
        if not rig then return nil end
        local part = rig:FindFirstChild(limbName)
        if part then return part end
        if limbName == "UpperTorso" or limbName == "LowerTorso" then
            return rig:FindFirstChild("Torso") or rig:FindFirstChild("HumanoidRootPart")
        elseif limbName == "Head" then
            return rig:FindFirstChild("Head")
        elseif limbName:find("Left") and (limbName:find("Arm") or limbName:find("Hand")) then
            return rig:FindFirstChild("Left Arm")
        elseif limbName:find("Right") and (limbName:find("Arm") or limbName:find("Hand")) then
            return rig:FindFirstChild("Right Arm")
        elseif limbName:find("Left") and (limbName:find("Leg") or limbName:find("Foot")) then
            return rig:FindFirstChild("Left Leg")
        elseif limbName:find("Right") and (limbName:find("Leg") or limbName:find("Foot")) then
            return rig:FindFirstChild("Right Leg")
        end
        return nil
    end

    local function stopGorilla()
        gorillaActive = false
        if syncConnection then
            syncConnection:Disconnect()
            syncConnection = nil
        end
        if physicsConnection then
            physicsConnection:Disconnect()
            physicsConnection = nil
        end
        currentOrigin = nil
        senders = {}

        cleanGhostRig()

        local char = lp.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum then
            hum.WalkSpeed = savedWalkSpeed or 16
            hum.UseJumpPower = savedUseJumpPower or false
            hum.JumpPower = (savedJumpPower and savedJumpPower > 0) and savedJumpPower or 50
            pcall(function()
                hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
                hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true)
                hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
                hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, true)
            end)
        end

        rgbActive = false
        smoothClimbTo(savedHipHeight or 2.0, 4.0)
        setCharacterHidden(false)

        task.wait(0.15)
        pcall(function() clearTools:FireServer("ClearAllProps") end)
        task.wait(0.3)
        pcall(function() clearTools:FireServer("ClearAllProps") end)
        gNotif("Colossal Gorilla", "Gorilla dismissed and props cleared.")
    end

    local function spawnGorilla()
        if gorillaActive then stopGorilla() task.wait(0.5) end
        gorillaActive = true

        local char = lp.Character or lp.CharacterAdded:Wait()
        local hrp = char:WaitForChild("HumanoidRootPart")
        local hum = char:WaitForChild("Humanoid")

        savedHipHeight = hum.HipHeight
        savedWalkSpeed = hum.WalkSpeed
        savedJumpPower = hum.JumpPower
        savedUseJumpPower = hum.UseJumpPower

        hum.WalkSpeed = gorillaConfig.walkSpeed
        hum.UseJumpPower = true
        hum.JumpPower = 0

        pcall(function()
            hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, false)
            hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, false)
            hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
            hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)
        end)

        gNotif("Colossal Gorilla", "Summoning Colossal Titan Gorilla...", 3)

        pcall(function() clearTools:FireServer("ClearAllProps") end)
        task.wait(0.5)

        local propsTool = _0xH_3f2()
        if not propsTool then gNotif("Colossal Gorilla", "PropMaker tool missing!") return end

        pcall(function() clearTools:FireServer("OpenPropMenu") end)
        task.wait(0.2)

        local wc = ws:FindFirstChild("WorkspaceCom")
        if not wc then gNotif("Colossal Gorilla", "WorkspaceCom missing!") return end

        local chestTarget = hrp.Position + (hrp.CFrame.LookVector * 16)
        local limbTarget = hrp.Position - (hrp.CFrame.LookVector * 12)

        local chestHitInst, chestHitPos = getTargetSurface(chestTarget)
        local limbHitInst, limbHitPos = getTargetSurface(limbTarget)

        local existingProps = {}
        for _, folder in pairs(wc:GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName then
                    existingProps[prop] = true
                end
            end
        end

        local function spawnSingleProp(propName, categoryName, targetInst, targetPos)
            local tool = _0xH_3f2()
            if not tool then return nil end

            if Telemetry then
                pcall(function() Telemetry:FireServer("filterClick", {name = categoryName, itemType = "Props"}) end)
                task.wait(0.05)
                pcall(function() Telemetry:FireServer("filterClick", {name = propName, itemType = "Props"}) end)
                task.wait(0.05)
            end

            pcall(function() clearTools:FireServer("RequestingPropName", propName, categoryName) end)
            task.wait(0.3)

            local currentHum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
            if currentHum and tool.Parent ~= lp.Character then
                currentHum:EquipTool(tool)
                task.wait(0.1)
            end

            local tpm = tool:FindFirstChild("Tool_PropMake")
            local startW = tick()
            while not tpm and tick() - startW < 4.0 and gorillaActive do
                tpm = tool:FindFirstChild("Tool_PropMake")
                if not tpm then
                    local bp = lp.Backpack:FindFirstChild("PropMaker")
                    if bp then tpm = bp:FindFirstChild("Tool_PropMake") end
                end
                if not tpm then task.wait(0.1) end
            end

            if not tpm then return nil end

            pcall(function()
                if tpm:IsA("RemoteFunction") then
                    tpm:InvokeServer(targetInst, targetPos)
                else
                    tpm:FireServer(targetInst, targetPos)
                end
            end)

            local newProp = nil
            local t0 = tick()
            while tick() - t0 < 3.5 and gorillaActive do
                for _, folder in pairs(wc:GetChildren()) do
                    for _, prop in pairs(folder:GetChildren()) do
                        if prop.Name == myPropName and not existingProps[prop] then
                            existingProps[prop] = true
                            newProp = prop
                            break
                        end
                    end
                    if newProp then break end
                end
                if newProp then break end
                task.wait(0.05)
            end
            return newProp
        end

        local chestProp = spawnSingleProp(gorillaConfig.chestProp, gorillaConfig.chestCat, chestHitInst, chestHitPos)
        if not chestProp then
            chestProp = spawnSingleProp(gorillaConfig.chestProp, gorillaConfig.chestCat, chestHitInst, chestHitPos)
        end
        if not chestProp then gNotif("Colossal Gorilla", "Chest Bunker failed to spawn!") return end

        local firstLimb = spawnSingleProp(selectedLimbProp, selectedLimbCat, limbHitInst, limbHitPos)
        if not firstLimb and selectedLimbProp == "PowerTurbine" then
            firstLimb = spawnSingleProp("001_TrafficCones", "Barrel", limbHitInst, limbHitPos)
        end
        if not firstLimb then
            firstLimb = spawnSingleProp(selectedLimbProp, selectedLimbCat, limbHitInst, limbHitPos)
        end
        if not firstLimb then gNotif("Colossal Gorilla", "Limb prop failed to spawn!") return end

        local dupsNeeded = 13
        _0xH_3f3(firstLimb, dupsNeeded)
        task.wait(0.8)

                                                           
        task.wait(1.0)
        pcall(function() toolRE:InvokeServer("PickingTools", "PropMaker") end)
        pcall(function() clearTools:FireServer("ClosePropMenu") end)

        task.wait(0.3)
        local limbProps = {}

        for _, folder in pairs(wc:GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName then
                    local scf = prop:FindFirstChild("SetCurrentCFrame") or prop:FindFirstChildWhichIsA("RemoteFunction", true)
                    local cpc = prop:FindFirstChild("ChangePropColor") or prop:FindFirstChild("ChangePropColor", true)
                    if scf then
                        pcall(function()
                            for _, p in ipairs(prop:GetDescendants()) do
                                if p:IsA("BasePart") then
                                    p.CanCollide = false
                                    p.CanTouch = false
                                    p.CanQuery = false
                                    p.Massless = true
                                end
                            end
                        end)
                        if prop ~= chestProp then
                            table.insert(limbProps, { prop = prop, scf = scf, cpc = cpc })
                        end
                    end
                end
            end
        end

        local chestScf = chestProp:FindFirstChild("SetCurrentCFrame") or chestProp:FindFirstChildWhichIsA("RemoteFunction", true)
        local chestCpc = chestProp:FindFirstChild("ChangePropColor")
        if not chestScf then gNotif("Colossal Gorilla", "Torso SCF remote missing!") return end

        task.wait(0.3)
        setupGhostRig()

        local normY = 1.0
        local bhs = hum:FindFirstChild("BodyHeightScale")
        local curH = (bhs and bhs.Value) or 1.0
        if curH > 0.01 then normY = curH / REF_SCALES.BodyHeightScale end

        local effectivePlayerLift = gorillaConfig.playerLift / math.clamp(normY, 0.4, 2.5)

        if currentMode == "COCKPIT" then
            smoothClimbTo(effectivePlayerLift, 2.0)
            setCharacterHidden(true)
        else
            smoothClimbTo(savedHipHeight or 2.0, 2.0)
            setCharacterHidden(false)
        end

        gNotif("Colossal Gorilla", string.format("Titan Gorilla Online! (%d props)", #limbProps + 1))

        local GORILLA_PARTS = {
            {
                limbName = "UpperTorso",
                scf = chestScf,
                prop = chestProp,
                cpc = chestCpc,
                isChest = true,
                extraPos = Vector3.new(0, 0, 0),
                adaptation = CFrame.Angles(math.rad(28), 0, 0)
            },
            {
                limbName = "Head",
                scf = limbProps[1] and limbProps[1].scf,
                prop = limbProps[1] and limbProps[1].prop,
                cpc = limbProps[1] and limbProps[1].cpc,
                extraPos = Vector3.new(0, 2.8, -4.6),
                adaptation = CFrame.Angles(math.rad(18), 0, 0)
            },
            {
                limbName = "LowerTorso",
                scf = limbProps[2] and limbProps[2].scf,
                prop = limbProps[2] and limbProps[2].prop,
                cpc = limbProps[2] and limbProps[2].cpc,
                extraPos = Vector3.new(0, -1.6, 5.2),
                adaptation = CFrame.Angles(math.rad(-26), 0, 0)
            },
            {
                limbName = "LeftUpperArm",
                scf = limbProps[3] and limbProps[3].scf,
                prop = limbProps[3] and limbProps[3].prop,
                cpc = limbProps[3] and limbProps[3].cpc,
                extraPos = Vector3.new(-2.6, 0.6, -1.8),
                adaptation = CFrame.Angles(math.rad(26), math.rad(16), math.rad(-10))
            },
            {
                limbName = "LeftLowerArm",
                scf = limbProps[4] and limbProps[4].scf,
                prop = limbProps[4] and limbProps[4].prop,
                cpc = limbProps[4] and limbProps[4].cpc,
                extraPos = Vector3.new(-3.0, -1.2, -3.6),
                adaptation = CFrame.Angles(math.rad(22), math.rad(8), math.rad(-6))
            },
            {
                limbName = "LeftHand",
                scf = limbProps[5] and limbProps[5].scf,
                prop = limbProps[5] and limbProps[5].prop,
                cpc = limbProps[5] and limbProps[5].cpc,
                isFootOrKnuckle = true,
                extraPos = Vector3.new(-3.4, -2.2, -5.6),
                adaptation = CFrame.Angles(math.rad(85), math.rad(4), 0)
            },
            {
                limbName = "RightUpperArm",
                scf = limbProps[6] and limbProps[6].scf,
                prop = limbProps[6] and limbProps[6].prop,
                cpc = limbProps[6] and limbProps[6].cpc,
                extraPos = Vector3.new(2.6, 0.6, -1.8),
                adaptation = CFrame.Angles(math.rad(26), math.rad(-16), math.rad(10))
            },
            {
                limbName = "RightLowerArm",
                scf = limbProps[7] and limbProps[7].scf,
                prop = limbProps[7] and limbProps[7].prop,
                cpc = limbProps[7] and limbProps[7].cpc,
                extraPos = Vector3.new(3.0, -1.2, -3.6),
                adaptation = CFrame.Angles(math.rad(22), math.rad(-8), math.rad(6))
            },
            {
                limbName = "RightHand",
                scf = limbProps[8] and limbProps[8].scf,
                prop = limbProps[8] and limbProps[8].prop,
                cpc = limbProps[8] and limbProps[8].cpc,
                isFootOrKnuckle = true,
                extraPos = Vector3.new(3.4, -2.2, -5.6),
                adaptation = CFrame.Angles(math.rad(85), math.rad(-4), 0)
            },
            {
                limbName = "LeftUpperLeg",
                scf = limbProps[9] and limbProps[9].scf,
                prop = limbProps[9] and limbProps[9].prop,
                cpc = limbProps[9] and limbProps[9].cpc,
                extraPos = Vector3.new(-2.2, -1.2, 4.2),
                adaptation = CFrame.Angles(math.rad(-32), math.rad(10), 0)
            },
            {
                limbName = "LeftLowerLeg",
                scf = limbProps[10] and limbProps[10].scf,
                prop = limbProps[10] and limbProps[10].prop,
                cpc = limbProps[10] and limbProps[10].cpc,
                extraPos = Vector3.new(-2.4, -2.6, 5.0),
                adaptation = CFrame.Angles(math.rad(34), math.rad(5), 0)
            },
            {
                limbName = "LeftFoot",
                scf = limbProps[11] and limbProps[11].scf,
                prop = limbProps[11] and limbProps[11].prop,
                cpc = limbProps[11] and limbProps[11].cpc,
                isFootOrKnuckle = true,
                extraPos = Vector3.new(-2.6, -3.6, 5.8),
                adaptation = CFrame.Angles(0, math.rad(5), 0)
            },
            {
                limbName = "RightUpperLeg",
                scf = limbProps[12] and limbProps[12].scf,
                prop = limbProps[12] and limbProps[12].prop,
                cpc = limbProps[12] and limbProps[12].cpc,
                extraPos = Vector3.new(2.2, -1.2, 4.2),
                adaptation = CFrame.Angles(math.rad(-32), math.rad(-10), 0)
            },
            {
                limbName = "RightLowerLeg",
                scf = limbProps[13] and limbProps[13].scf,
                prop = limbProps[13] and limbProps[13].prop,
                cpc = limbProps[13] and limbProps[13].cpc,
                extraPos = Vector3.new(2.4, -2.6, 5.0),
                adaptation = CFrame.Angles(math.rad(34), math.rad(-5), 0)
            },
            {
                limbName = "RightFoot",
                scf = limbProps[14] and limbProps[14].scf,
                prop = limbProps[14] and limbProps[14].prop,
                cpc = limbProps[14] and limbProps[14].cpc,
                isFootOrKnuckle = true,
                extraPos = Vector3.new(2.6, -3.6, 5.8),
                adaptation = CFrame.Angles(0, math.rad(-5), 0)
            }
        }

        local function applyThemeColors(theme)
            local tData = GORILLA_THEMES[theme] or GORILLA_THEMES["Silverback"]
            for _, entry in ipairs(GORILLA_PARTS) do
                local color = entry.isChest and tData.chest or tData.limbs
                if entry.limbName == "Head" then color = tData.accent end
                if entry.prop then
                    pcall(function()
                        for _, p in ipairs(entry.prop:GetDescendants()) do
                            if p:IsA("BasePart") then p.Color = color end
                        end
                    end)
                end
                if entry.cpc then
                    pcall(function() entry.cpc:FireServer(color) end)
                end
            end
        end
        applyThemeColors(currentThemeName)

        physicsConnection = rs.Stepped:Connect(function()
            if not gorillaActive then return end
            local cc = lp.Character
            if cc then
                for _, part in ipairs(cc:GetDescendants()) do
                    if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                        part.CanCollide = false
                        part.CanTouch = false
                    end
                end
            end
        end)

        local floorRayParams = RaycastParams.new()
        floorRayParams.FilterType = Enum.RaycastFilterType.Exclude

        syncConnection = rs.RenderStepped:Connect(function()
            if not gorillaActive then return end

            local cc = lp.Character
            if not cc then return end
            local hrpNow = cc:FindFirstChild("HumanoidRootPart")
            local humNow = cc:FindFirstChildOfClass("Humanoid")
            if not hrpNow or not humNow then return end

            local hrpCF = hrpNow.CFrame
            local forwardFlat = (hrpCF.LookVector * Vector3.new(1, 0, 1)).Unit
            if forwardFlat.Magnitude < 0.001 then forwardFlat = hrpCF.LookVector end

            local moveMag = humNow.MoveDirection.Magnitude
            if moveMag > 0.08 then
                if ghostIdleTrack and ghostIdleTrack.IsPlaying then
                    ghostIdleTrack:Stop(0.15)
                end
                local targetTrack = ghostRunTrack or ghostWalkTrack
                if targetTrack and not targetTrack.IsPlaying then
                    targetTrack:Play(0.15)
                end
            else
                if ghostRunTrack and ghostRunTrack.IsPlaying then
                    ghostRunTrack:Stop(0.15)
                end
                if ghostWalkTrack and ghostWalkTrack.IsPlaying then
                    ghostWalkTrack:Stop(0.15)
                end
                if ghostIdleTrack and not ghostIdleTrack.IsPlaying then
                    ghostIdleTrack:Play(0.15)
                end
            end

            local ghostRoot = ghostRig and ghostRig:FindFirstChild("HumanoidRootPart")
            local ghostRootCF = ghostRoot and ghostRoot.CFrame or CFrame.new()

            local lowestTouchRelY = -3.2 * gorillaConfig.size
            if ghostRig then
                local candidateY = {}
                local limbsToCheck = {"LeftHand", "RightHand", "LeftFoot", "RightFoot"}
                for _, lName in ipairs(limbsToCheck) do
                    local limbPart = getGhostLimb(ghostRig, lName)
                    if limbPart then
                        local rel = ghostRootCF:ToObjectSpace(limbPart.CFrame)
                        local extra = 0
                        if lName:find("Hand") then
                            extra = (-gorillaConfig.armSpacing * 2.2) - 2.2
                        elseif lName:find("Foot") then
                            extra = (-gorillaConfig.legSpacing * 2.0) - 3.6
                        end
                        table.insert(candidateY, (rel.Position.Y * gorillaConfig.size) + extra)
                    end
                end
                if #candidateY > 0 then
                    lowestTouchRelY = math.min(unpack(candidateY))
                end
            end

            floorRayParams.FilterDescendantsInstances = { cc, ghostRig, ws:FindFirstChild("WorkspaceCom") }
            local rayOrigin = Vector3.new(hrpNow.Position.X, hrpNow.Position.Y + 25, hrpNow.Position.Z)
            local ray = ws:Raycast(rayOrigin, Vector3.new(0, -120, 0), floorRayParams)
            local groundY = (ray and ray.Position) and ray.Position.Y or (hrpNow.Position.Y - humNow.HipHeight - 1.5)

            local targetCenterY = groundY - lowestTouchRelY + gorillaConfig.height + gorillaConfig.footOffset

            local targetCenterCF
            if currentMode == "FRONT" then
                local frontPos = Vector3.new(hrpCF.Position.X, targetCenterY, hrpCF.Position.Z) + (forwardFlat * 18.0)
                targetCenterCF = CFrame.new(frontPos)
                    * (hrpCF - hrpCF.Position)
                    * CFrame.new(gorillaConfig.posX, 0, gorillaConfig.posZ)
                    * CFrame.Angles(0, math.rad(gorillaConfig.rotY), 0)
            else
                targetCenterCF = CFrame.new(hrpCF.Position.X, targetCenterY, hrpCF.Position.Z)
                    * (hrpCF - hrpCF.Position)
                    * CFrame.new(gorillaConfig.posX, 0, gorillaConfig.posZ)
                    * CFrame.Angles(0, math.rad(gorillaConfig.rotY), 0)
            end

            if not currentOrigin then
                currentOrigin = targetCenterCF
            else
                currentOrigin = currentOrigin:Lerp(targetCenterCF, 0.22)
            end
            local centerCF = currentOrigin

            if currentMode == "COCKPIT" then
                for _, p in pairs(cc:GetDescendants()) do
                    if (p:IsA("BasePart") or p:IsA("Decal")) and p.Transparency < 1 then
                        if not savedTransparencies[p] then
                            savedTransparencies[p] = p.Transparency
                        end
                        p.Transparency = 1
                    end
                end
            end

            for _, entry in ipairs(GORILLA_PARTS) do
                if entry.scf then
                    local limbPart = getGhostLimb(ghostRig, entry.limbName)
                    if limbPart then
                        local rel = ghostRootCF:ToObjectSpace(limbPart.CFrame)

                        local xMult = 1.0
                        if entry.limbName:find("Arm") or entry.limbName:find("Hand") then
                            xMult = gorillaConfig.armWidth
                        elseif entry.limbName:find("Leg") or entry.limbName:find("Foot") then
                            xMult = gorillaConfig.legWidth
                        end

                        local zMult = gorillaConfig.bodyLength or 1.0

                        local scaledPos = Vector3.new(
                            rel.Position.X * gorillaConfig.size * xMult,
                            rel.Position.Y * gorillaConfig.size,
                            rel.Position.Z * gorillaConfig.size * zMult
                        )

                        if entry.extraPos then
                            scaledPos = scaledPos + entry.extraPos
                        end

                        if entry.limbName:find("LowerArm") then
                            scaledPos = scaledPos + Vector3.new(0, -gorillaConfig.armSpacing, 0)
                        elseif entry.limbName:find("Hand") then
                            scaledPos = scaledPos + Vector3.new(0, -gorillaConfig.armSpacing * 2.2, 0)
                        end

                        if entry.limbName:find("LowerLeg") then
                            scaledPos = scaledPos + Vector3.new(0, -gorillaConfig.legSpacing, 0)
                        elseif entry.limbName:find("Foot") then
                            scaledPos = scaledPos + Vector3.new(0, -gorillaConfig.legSpacing * 2.0, 0)
                        end

                        local relRot = rel - rel.Position
                        local targetCF = centerCF * CFrame.new(scaledPos) * relRot * entry.adaptation

                        sendCF(entry.scf, targetCF, entry.prop)
                    end
                end
            end

            if rgbActive then
                local nowTick = tick()
                for i, entry in ipairs(GORILLA_PARTS) do
                    local waveColor = Color3.fromHSV((nowTick * 0.4 + (i / #GORILLA_PARTS)) % 1, 1, 1)
                    if entry.prop then
                        pcall(function()
                            for _, p in ipairs(entry.prop:GetDescendants()) do
                                if p:IsA("BasePart") then p.Color = waveColor end
                            end
                        end)
                    end
                    if entry.cpc and (nowTick - (entry.lastColorSent or 0) >= 0.25) then
                        entry.lastColorSent = nowTick
                        task.spawn(function()
                            pcall(function() entry.cpc:FireServer(waveColor) end)
                        end)
                    end
                end
            end
        end)
    end

    BuildV2Tab:AddSection({"> Colossal Silverback Gorilla"})

    BuildV2Tab:AddToggle({
        Name = "Spawn Silverback Gorilla",
        Description = "Pilot a colossal 15-prop knuckle-walking silverback gorilla with dynamic R15 animations",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            if not val and not gorillaActive then return end
            if val then
                task.spawn(spawnGorilla)
            else
                stopGorilla()
            end
        end
    })

    BuildV2Tab:AddDropdown({
        Name = "Gorilla Theme",
        Description = "Select gorilla color theme or dynamic rainbow chroma",
        Options = {
            "Silverback",
            "King Kong",
            "Golden Ape",
            "Cyber Gorilla",
            "Magma Beast",
            "Rainbow"
        },
        Default = "Silverback",
        Callback = function(choice)
            currentThemeName = choice
            if choice == "Rainbow" then
                rgbActive = true
            else
                rgbActive = false
                if gorillaActive then
                    local tData = GORILLA_THEMES[choice] or GORILLA_THEMES["Silverback"]
                    for _, entry in ipairs(GORILLA_PARTS or {}) do
                        local col = entry.isChest and tData.chest or tData.limbs
                        if entry.limbName == "Head" then col = tData.accent end
                        if entry.prop then
                            pcall(function()
                                for _, p in ipairs(entry.prop:GetDescendants()) do
                                    if p:IsA("BasePart") then p.Color = col end
                                end
                            end)
                        end
                        if entry.cpc then
                            pcall(function() entry.cpc:FireServer(col) end)
                        end
                    end
                end
            end
            gNotif("Colossal Gorilla", "Theme: " .. choice, 2)
        end
    })

    BuildV2Tab:AddDropdown({
        Name = "View Mode",
        Description = "Choose cockpit pilot view or 3rd person front view",
        Options = { "Cockpit (Pilot)", "Front (Third Person)" },
        Default = "Cockpit (Pilot)",
        Callback = function(choice)
            if choice == "Front (Third Person)" then
                currentMode = "FRONT"
                if gorillaActive then
                    smoothClimbTo(savedHipHeight or 2.0, 3.0)
                    setCharacterHidden(false)
                else
                    setCharacterHidden(false)
                end
            else
                currentMode = "COCKPIT"
                if gorillaActive then
                    local char = lp.Character
                    local hum = char and char:FindFirstChildOfClass("Humanoid")
                    local normY = 1.0
                    local bhs = hum and hum:FindFirstChild("BodyHeightScale")
                    local curH = (bhs and bhs.Value) or 1.0
                    if curH > 0.01 then normY = curH / REF_SCALES.BodyHeightScale end
                    local effectivePlayerLift = gorillaConfig.playerLift / math.clamp(normY, 0.4, 2.5)
                    smoothClimbTo(effectivePlayerLift, 3.0)
                    setCharacterHidden(true)
                end
            end
            gNotif("Colossal Gorilla", "View Mode: " .. currentMode, 2)
        end
    })

    BuildV2Tab:AddDropdown({
        Name = "Limb Prop Type",
        Description = "Select limb prop model (respawn required to take effect)",
        Options = { "BigGenerator", "PowerTurbine" },
        Default = "BigGenerator",
        Callback = function(choice)
            selectedLimbProp = choice
            selectedLimbCat = (choice == "PowerTurbine") and "Barrel" or "Building"
            gorillaConfig.limbProp = selectedLimbProp
            gorillaConfig.limbCat = selectedLimbCat
            gNotif("Colossal Gorilla", "Limb set to " .. choice .. " (respawn required)", 2)
        end
    })
end


do
    local lp = game:GetService("Players").LocalPlayer
    local rs = game:GetService("RunService")
    local rep = game:GetService("ReplicatedStorage")

