        mechaLoop = rs.RenderStepped:Connect(function()
            if not mechaActive then return end

            local cc = lp.Character
            if not cc then return end
            local hrpNow = cc:FindFirstChild("HumanoidRootPart")
            if not hrpNow then return end
            local humNow = cc:FindFirstChildOfClass("Humanoid")

            
            
            local rayFilter = {cc, workspace:FindFirstChild("WorkspaceCom")}
            for _, plr in ipairs(Players:GetPlayers()) do
                if plr.Character and plr.Character ~= cc then
                    table.insert(rayFilter, plr.Character)
                end
            end
            rayParams.FilterDescendantsInstances = rayFilter
            local ray = workspace:Raycast(hrpNow.Position + Vector3.new(0, 10, 0), Vector3.new(0, -250, 0), rayParams)
            local groundY = ray and ray.Position.Y
            local minFloorY = groundY and (groundY + currentHipHeightVal) or nil

            if minFloorY and hrpNow.Position.Y < minFloorY then
                local vel = hrpNow.AssemblyLinearVelocity
                if vel.Y < 0 then
                    hrpNow.AssemblyLinearVelocity = Vector3.new(vel.X, 0, vel.Z)
                end
                hrpNow.CFrame = CFrame.new(hrpNow.Position.X, minFloorY, hrpNow.Position.Z) * hrpNow.CFrame.Rotation
