            end
            local centerCF = currentMechOrigin

            local REF_WIDTH = 0.7000001072883606
            local REF_HEIGHT = 1.0499999523162842
            local REF_DEPTH = 0.8500000834465027

            local curDepth = REF_DEPTH
            local curHeight = REF_HEIGHT
            local curWidth = REF_WIDTH
            if humNow then
                local dVal = humNow:FindFirstChild("BodyDepthScale")
                if dVal and dVal:IsA("NumberValue") and dVal.Value > 0.001 then curDepth = dVal.Value end
                local hVal = humNow:FindFirstChild("BodyHeightScale")
                if hVal and hVal:IsA("NumberValue") and hVal.Value > 0.001 then curHeight = hVal.Value end
                local wVal = humNow:FindFirstChild("BodyWidthScale")
                if wVal and wVal:IsA("NumberValue") and wVal.Value > 0.001 then curWidth = wVal.Value end
            end

            local normX = curWidth / REF_WIDTH
            local normY = curHeight / REF_HEIGHT
            local normZ = curDepth / REF_DEPTH
            if math.abs(normX) < 0.001 then normX = 1 end
            if math.abs(normY) < 0.001 then normY = 1 end
            if math.abs(normZ) < 0.001 then normZ = 1 end

            for _, entry in ipairs(MECHA_PARTS) do
                if entry.scf then
                    local part = cc:FindFirstChild(entry.name)
                    if not part and entry.name == "UpperTorso" then
                        part = cc:FindFirstChild("Torso") or hrpNow
                    end
                    if part then
                        local rel = clampedHrpCF:ToObjectSpace(part.CFrame)

                        local xMult = 1.0
                        if entry.name:find("Arm") or entry.name:find("Hand") then
                            xMult = mechaConfig.armWidth
                        elseif entry.name:find("Leg") or entry.name:find("Foot") then
                            xMult = mechaConfig.legWidth
                        end

                        local unscaledX = rel.Position.X / normX
                        local unscaledY = rel.Position.Y / normY
                        local unscaledZ = rel.Position.Z / normZ

                        local scaledPos = Vector3.new(unscaledX * mechaConfig.size * xMult, unscaledY * mechaConfig.size, unscaledZ * mechaConfig.size)

                        if entry.name:find("LowerArm") then
                            scaledPos = scaledPos + Vector3.new(0, -mechaConfig.armSpacing, 0)
                        elseif entry.name:find("Hand") then
                            scaledPos = scaledPos + Vector3.new(0, -mechaConfig.armSpacing * 2, 0)
                        end

                        if entry.name:find("Leg") or entry.name:find("Foot") then
                            scaledPos = scaledPos + Vector3.new(0, mechaConfig.legOffsetY, 0)
                            if entry.name:find("LowerLeg") then
                                scaledPos = scaledPos + Vector3.new(0, mechaConfig.legSpacing, 0)
                            elseif entry.name:find("UpperLeg") then
                                scaledPos = scaledPos + Vector3.new(0, mechaConfig.legSpacing * 2, 0)
                            end
                        end

                        local relRot = rel - rel.Position

                        local extraOffset = entry.offset or CFrame.new()
                        if entry.name == "UpperTorso" then
                            extraOffset = CFrame.new(mechaConfig.torsoOffsetX, mechaConfig.torsoOffsetY, mechaConfig.torsoOffsetZ)
                                * CFrame.Angles(math.rad(mechaConfig.torsoRotX), math.rad(mechaConfig.torsoRotY), math.rad(mechaConfig.torsoRotZ))
                        elseif entry.name == "LowerTorso" then
                            extraOffset = (entry.offset or CFrame.new())
                                * CFrame.new(mechaConfig.pelvisOffsetX, mechaConfig.pelvisOffsetY, mechaConfig.pelvisOffsetZ)
                                * CFrame.Angles(math.rad(mechaConfig.pelvisRotX), math.rad(mechaConfig.pelvisRotY), math.rad(mechaConfig.pelvisRotZ))
                        end

                        local targetCF = centerCF * CFrame.new(scaledPos) * relRot * extraOffset

                        sendCF(entry.scf, targetCF, entry.prop)
                    end
                end
            end

            
            if humNow and humNow.MoveDirection.Magnitude > 0.05 then
                if humNow:GetState() ~= Enum.HumanoidStateType.Running then
                    pcall(function() humNow:ChangeState(Enum.HumanoidStateType.Running) end)
                end
                if humNow.WalkSpeed < mechaConfig.walkSpeed then
                    humNow.WalkSpeed = mechaConfig.walkSpeed
                end

                local hasRun = false
                for _, track in ipairs(humNow:GetPlayingAnimationTracks()) do
                    local animName = track.Name:lower()
                    if animName:find("idle") or animName:find("walk") then
                        track:Stop(0.05)
                    elseif animName:find("run") and track.Priority == Enum.AnimationPriority.Action4 then
                        hasRun = true
                        track:AdjustSpeed(mechaConfig.animSpeed)
                    end
                end

                if not hasRun then
                    local animScript = cc:FindFirstChild("Animate")
                    local runAnim = animScript and animScript:FindFirstChild("run") and animScript.run:FindFirstChildOfClass("Animation")
                    if runAnim then
                        pcall(function()
                            local runTrack = humNow:LoadAnimation(runAnim)
                            runTrack.Priority = Enum.AnimationPriority.Action4
                            runTrack:Play(0.05)
                            runTrack:AdjustSpeed(mechaConfig.animSpeed)
                        end)
                    end
                end
            else
                
                for _, track in ipairs(humNow:GetPlayingAnimationTracks()) do
                    local animName = track.Name:lower()
                    if animName:find("run") and track.Priority == Enum.AnimationPriority.Action4 then
                        track:Stop(0.1)
                    end
                end
            end

            
            if humNow and humNow.HipHeight ~= mechaConfig.playerLift and currentHipHeightVal >= mechaConfig.playerLift then
                humNow.HipHeight = mechaConfig.playerLift
            end

            
            if mechaColorTheme == "Rainbow" then
                local nowTick = tick()
                for i, entry in ipairs(MECHA_PARTS) do
                    local waveColor = Color3.fromHSV((nowTick * 0.4 + (i / #MECHA_PARTS)) % 1, 1, 1)

                    if entry.prop then
                        pcall(function()
                            for _, p in ipairs(entry.prop:GetDescendants()) do
                                if p:IsA("BasePart") then
                                    p.Color = waveColor
                                end
                            end
                        end)
                    end

                    if entry.cpc and (nowTick - (entry.lastColorSent or 0) >= 0.25) then
                        entry.lastColorSent = nowTick
                        task.spawn(function()
                            pcall(function() entry.cpc:InvokeServer(waveColor) end)
                        end)
                    end
                end
            end
        end)
    end

    
    
    
    _G.BTR_LOAD_PROGRESS = 0.78
_G.BTR_LOAD_STATUS = "Loading Heavy Mechas & Colossus..."

BuildV2Tab:AddSection({"> Mecha Titan (Robot 1)"})

    BuildV2Tab:AddToggle({
        Name = "Spawn Mecha Robot",
        Description = "Pilote a giant 15-prop humanoid mecha with real-time R15 motion replication",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            if not val and not mechaActive then return end
            if val then
                task.spawn(_0xH_40e)
            else
                _0xH_40d()
            end
        end
    })

    BuildV2Tab:AddDropdown({
        Name = "Mecha Color Theme",
        Description = "Select robot color or animated wave",
        Options = {
            "Default",
            "Rainbow",
            "Cyberpunk",
            "Obsidian",
            "Gold",
            "Crimson",
            "Violet",
            "Acid",
            "Ice",
            "Magma"
        },
        Default = "Default",
        Callback = function(choice)
            _0xH_40c(choice)
        end
    })
end

do
    local lp = game:GetService("Players").LocalPlayer
    local rs = game:GetService("RunService")
    local rep = game:GetService("ReplicatedStorage")

    local titanActive = false
    local titanLoop = nil
    local titanPhysicsConn = nil
    local myPropName = "Prop" .. lp.Name

    local savedHipHeight = 2.0
    local savedWalkSpeed = 16
    local currentHipHeightVal = 25.5
    local savedTransparencies = {}

    local titanColorTheme = "Default"
    local titanPartsList = {}

    local titanConfig = {
        propName = "BigOutToilet",
        category = "Building",
        size = 6.8,
        height = 0.0,
        posZ = 0.0,
        posX = 0.0,
        rotY = 0.0,
        walkSpeed = 40.0,
        animSpeed = 0.85,
        armWidth = 0.90,
        armSpacing = 0.0,
        legWidth = 0.72,
        legOffsetY = 0.0,
        legSpacing = 0.0,
    }

    local TITAN_THEMES = {
        ["Obsidian"] = Color3.fromRGB(15, 15, 18),
        ["Gold"] = Color3.fromRGB(255, 215, 0),
        ["Crimson"] = Color3.fromRGB(220, 20, 35),
        ["Violet"] = Color3.fromRGB(150, 40, 240),
        ["Acid"] = Color3.fromRGB(50, 255, 60),
        ["Ice"] = Color3.fromRGB(0, 230, 255),
        ["Magma"] = Color3.fromRGB(255, 115, 0),
    }

    local function tNotif(title, text, dur)
        pcall(function()
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = title,
                Text = text,
                Duration = dur or 3
            })
        end)
    end

    local function applyPlayerLift(newVal)
        local char = lp.Character
        if char then
            local hum = char:FindFirstChildOfClass("Humanoid")
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hum and hrp then
                hum.HipHeight = newVal
                if newVal > 3.0 then
                    hrp.CFrame = hrp.CFrame + Vector3.new(0, 0.5, 0)
                end
            end
        end
    end

    local function smoothClimbTo(targetVal, step)
        step = step or 3.0
        task.spawn(function()
            local char = lp.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            local current = (hum and hum.HipHeight) or 2.0
            if current < targetVal then
                for v = current + step, targetVal, step do
                    applyPlayerLift(v)
                    task.wait(0.02)
                end
                applyPlayerLift(targetVal)
            else
                for v = current - step, targetVal, -step do
                    applyPlayerLift(v)
                    task.wait(0.02)
                end
                applyPlayerLift(targetVal)
            end
        end)
    end

    local function setCharacterHidden(hidden)
        local char = lp.Character
        if not char then return end
        if hidden then
            for _, part in pairs(char:GetDescendants()) do
                if part:IsA("BasePart") or part:IsA("Decal") then
                    if not savedTransparencies[part] then
                        savedTransparencies[part] = part.Transparency
                    end
                    part.Transparency = 1
                end
            end
        else
            for part, origVal in pairs(savedTransparencies) do
                if part and part.Parent then
                    pcall(function() part.Transparency = origVal end)
                end
            end
            savedTransparencies = {}
        end
    end

    local function _0xH_3f2()
        local backpack = lp:FindFirstChild("Backpack")
        local character = lp.Character
        if not backpack or not character then return nil end
        local toolRE = rep:WaitForChild("RE"):WaitForChild("1Too1l")
        local tool = character:FindFirstChild("PropMaker") or backpack:FindFirstChild("PropMaker")
        if not tool then
            pcall(function() toolRE:InvokeServer("PickingTools", "PropMaker") end)
            local start = tick()
            while tick() - start < 2.0 do
                tool = character:FindFirstChild("PropMaker") or backpack:FindFirstChild("PropMaker")
                if tool then break end
                task.wait(0.05)
            end
        end
        if not tool then return nil end

        if tool.Parent ~= character then
            local hum = character:FindFirstChildOfClass("Humanoid")
            if hum then
                hum:EquipTool(tool)
                local eqStart = tick()
                while tick() - eqStart < 2.0 do
                    if tool.Parent == character then break end
                    task.wait(0.05)
                end
            end
        end
        return tool
    end

    local function _0xH_3f3(firstProp, countNeeded)
        if not firstProp then return false end
        local dupRemote = firstProp:FindFirstChild("DuplicateProp") or firstProp:WaitForChild("DuplicateProp", 2)
        if not dupRemote then return false end

        for i = 1, countNeeded do
            pcall(function() dupRemote:InvokeServer() end)
            task.wait(0.05)
        end
        return true
    end

    local senders = {}
    local RATE_LIMIT = 0.03

    local function sendCF(scf, cf, prop)
        if not titanActive or not scf then return end

        if prop then
            pcall(function()
                if prop:IsA("Model") then
                    prop:PivotTo(cf)
                elseif prop:IsA("BasePart") then
                    prop.CFrame = cf
                end
            end)
        end

        local entry = senders[scf]
        local now = tick()
        if not entry then
            entry = { lastSent = 0, nextCF = cf, sending = false }
            senders[scf] = entry
        else
            entry.nextCF = cf
        end

        if not entry.sending and (now - entry.lastSent >= RATE_LIMIT) then
            entry.sending = true
            entry.lastSent = now
            local toSend = entry.nextCF
            entry.nextCF = nil
            task.spawn(function()
                pcall(function() scf:InvokeServer(toSend) end)
                entry.sending = false
                if titanActive and entry.nextCF and (tick() - entry.lastSent >= RATE_LIMIT) then
                    entry.sending = true
                    entry.lastSent = tick()
                    local nextSend = entry.nextCF
                    entry.nextCF = nil
                    task.spawn(function()
                        pcall(function() scf:InvokeServer(nextSend) end)
                        entry.sending = false
                    end)
                end
            end)
        end
    end

    local function applyThemeToPart(prop, cpc, color)
        if prop then
            pcall(function()
                for _, p in ipairs(prop:GetDescendants()) do
                    if p:IsA("BasePart") then
                        p.Color = color
                    end
                end
            end)
        end
        if cpc then
            task.spawn(function()
                pcall(function() cpc:InvokeServer(color) end)
            end)
        end
    end

    local function applyToiletTitanTheme(themeName)
        titanColorTheme = themeName
        if not titanActive or #titanPartsList == 0 then return end

        if themeName == "Default" then
            for _, entry in ipairs(titanPartsList) do
                local col = (entry.name == "UpperTorso" or entry.name == "LowerTorso")
                    and Color3.fromRGB(163, 162, 165)
                    or Color3.fromRGB(180, 180, 185)
                applyThemeToPart(entry.prop, entry.cpc, col)
            end
            tNotif("Toilet Titan", "Theme: Default", 2)
            return
        elseif themeName == "Rainbow" then
            tNotif("Toilet Titan", "Theme: Rainbow", 2)
            return
        elseif themeName == "Cyberpunk" then
            for i, entry in ipairs(titanPartsList) do
                local col = (i % 2 == 0) and Color3.fromRGB(0, 235, 255) or Color3.fromRGB(255, 30, 150)
                applyThemeToPart(entry.prop, entry.cpc, col)
            end
            tNotif("Toilet Titan", "Theme: Cyberpunk", 2)
            return
        end

        local solidCol = TITAN_THEMES[themeName] or Color3.fromRGB(163, 162, 165)
        for _, entry in ipairs(titanPartsList) do
            applyThemeToPart(entry.prop, entry.cpc, solidCol)
        end
        tNotif("Toilet Titan", "Theme: " .. themeName, 2)
    end

    local function stopToiletTitan()
        if not titanActive then return end
        titanActive = false
        if titanLoop then
            titanLoop:Disconnect()
            titanLoop = nil
        end
        if titanPhysicsConn then
            titanPhysicsConn:Disconnect()
            titanPhysicsConn = nil
        end
        senders = {}
        titanPartsList = {}

        local char = lp.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum then
            hum.WalkSpeed = savedWalkSpeed or 16
            pcall(function()
                hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true)
                hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
                hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, true)
            end)
            for _, track in ipairs(hum:GetPlayingAnimationTracks()) do
                if track.Priority == Enum.AnimationPriority.Action4 or track.Name:lower():find("run") then
                    pcall(function() track:Stop(0.1) end)
                end
            end
            pcall(function() hum:ChangeState(Enum.HumanoidStateType.Landed) end)
        end

        smoothClimbTo(savedHipHeight or 2.0, 4.0)
        setCharacterHidden(false)

        task.wait(0.15)
        pcall(function() rep:WaitForChild("RE"):WaitForChild("1Clea1rTool1s"):FireServer("ClearAllProps") end)
        task.wait(0.3)
        pcall(function() rep:WaitForChild("RE"):WaitForChild("1Clea1rTool1s"):FireServer("ClearAllProps") end)
        tNotif("Toilet Titan", "Titan offline and props cleared.", 3)
    end

    local function getTargetSurface(targetWorldPos)
        local street = workspace:FindFirstChild("Model") and workspace.Model:FindFirstChild("Street") and workspace.Model.Street:FindFirstChild("Street")

        local rayParams = RaycastParams.new()
        rayParams.FilterDescendantsInstances = {lp.Character, workspace:FindFirstChild("WorkspaceCom")}
        rayParams.FilterType = Enum.RaycastFilterType.Exclude

        local ray = workspace:Raycast(targetWorldPos + Vector3.new(0, 10, 0), Vector3.new(0, -30, 0), rayParams)
        local hitInst = street or (ray and ray.Instance) or workspace.Terrain
        local hitPos = ray and ray.Position or targetWorldPos

        return hitInst, hitPos
    end

    local function spawnToiletTitan()
        if titanActive then stopToiletTitan() task.wait(0.5) end
        titanActive = true
        local char = lp.Character or lp.CharacterAdded:Wait()
        local hrp = char:WaitForChild("HumanoidRootPart")
        local hum = char:WaitForChild("Humanoid")
        savedHipHeight = hum.HipHeight
        savedWalkSpeed = hum.WalkSpeed
        hum.WalkSpeed = titanConfig.walkSpeed
        pcall(function()
            hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, false)
            hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
            hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)
        end)
        tNotif("Toilet Titan", "Spawning Toilet Titan Colossus...", 3)

        local clearTools = rep:WaitForChild("RE"):WaitForChild("1Clea1rTool1s")
        local toolRE = rep:WaitForChild("RE"):WaitForChild("1Too1l")
        local Telemetry = rep:FindFirstChild("Remotes") and rep.Remotes:FindFirstChild("TelemetryClientInteraction")

        pcall(function() clearTools:FireServer("ClearAllProps") end)
        task.wait(0.5)

        local propsTool = _0xH_3f2()
        if not propsTool then tNotif("Toilet Titan", "PropMaker missing!", 3) return end

        pcall(function() clearTools:FireServer("OpenPropMenu") end)
        task.wait(0.2)

        local wc = workspace:FindFirstChild("WorkspaceCom")
        if not wc then tNotif("Toilet Titan", "WorkspaceCom missing!", 3) return end

        local targetWorld = hrp.Position + (hrp.CFrame.LookVector * 14)
        local hitInst, hitPos = getTargetSurface(targetWorld)

        local existingProps = {}
        for _, folder in pairs(wc:GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName then
                    existingProps[prop] = true
                end
            end
        end

        local function spawnSingleProp(propName, categoryName, targetI, targetP)
            local tool = _0xH_3f2()
            if not tool then return nil end

            if Telemetry then
                pcall(function() Telemetry:FireServer("filterClick", {name = categoryName, itemType = "Props"}) end)
                task.wait(0.05)
                pcall(function() Telemetry:FireServer("filterClick", {name = propName, itemType = "Props"}) end)
                task.wait(0.05)
            end

            pcall(function() clearTools:FireServer("RequestingPropName", propName, categoryName) end)
            task.wait(0.3)

            local currentHum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
            if currentHum and tool.Parent ~= lp.Character then
                currentHum:EquipTool(tool)
                task.wait(0.1)
            end

            local tpm = tool:FindFirstChild("Tool_PropMake")
            local startW = tick()
            while not tpm and tick() - startW < 4.0 and titanActive do
                tpm = tool:FindFirstChild("Tool_PropMake")
                if not tpm then
                    local bp = lp.Backpack:FindFirstChild("PropMaker")
                    if bp then tpm = bp:FindFirstChild("Tool_PropMake") end
                end
                if not tpm then task.wait(0.1) end
            end

            if not tpm then return nil end

            local useInst = targetI or hitInst
            local usePos = targetP or hitPos
            pcall(function() tpm:FireServer(useInst, usePos) end)

            local spawned = nil
            local t0 = tick()
            while tick() - t0 < 4.0 and titanActive do
                for _, folder in pairs(wc:GetChildren()) do
                    for _, prop in pairs(folder:GetChildren()) do
                        if prop.Name == myPropName and not existingProps[prop] then
                            spawned = prop
                            existingProps[prop] = true
                            break
                        end
                    end
                    if spawned then break end
                end
                if spawned then break end
                task.wait(0.05)
            end

            return spawned
        end

        
        local firstToilet = spawnSingleProp(titanConfig.propName, titanConfig.category, hitInst, hitPos)
        if not firstToilet then
            firstToilet = spawnSingleProp(titanConfig.propName, titanConfig.category, hitInst, hitPos)
        end
        if not firstToilet then tNotif("Toilet Titan", "BigOutToilet spawn failed!", 3) return end

        
        _0xH_3f3(firstToilet, 14)
        task.wait(0.8)

                                                                           
        task.wait(1.0)
        pcall(function() toolRE:InvokeServer("PickingTools", "PropMaker") end)
        pcall(function() clearTools:FireServer("ClosePropMenu") end)

        
        task.wait(0.3)
        local allToilets = {}
        for _, folder in pairs(wc:GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName then
                    local scf = prop:FindFirstChild("SetCurrentCFrame")
                    local cpc = prop:FindFirstChild("ChangePropColor")
                    if scf then
                        table.insert(allToilets, {prop = prop, scf = scf, cpc = cpc})
                        pcall(function()
                            for _, p in ipairs(prop:GetDescendants()) do
                                if p:IsA("BasePart") then
                                    p.CanCollide = false
                                    p.CanTouch = false
                                    p.CanQuery = false
                                    p.Massless = true
                                end
                            end
                        end)
                    end
                end
            end
        end

        if #allToilets < 15 then
            tNotif("Toilet Titan", string.format("Warning: %d/15 toilets ready, continuing...", #allToilets), 3)
        end

        
        hum.HipHeight = currentHipHeightVal
        hrp.CFrame = hrp.CFrame + Vector3.new(0, currentHipHeightVal - 2.0, 0)
        setCharacterHidden(true)
        task.wait(0.3)

        
        titanPhysicsConn = rs.Stepped:Connect(function()
            if not titanActive then return end
            local cc = lp.Character
            if cc then
                for _, part in ipairs(cc:GetDescendants()) do
                    if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                        part.CanCollide = false
                        part.CanTouch = false
                    end
                end
            end
            for _, propData in ipairs(allToilets) do
                if propData.prop then
                    for _, p in ipairs(propData.prop:GetDescendants()) do
                        if p:IsA("BasePart") then
                            p.CanCollide = false
                            p.CanTouch = false
                            p.CanQuery = false
                        end
                    end
                end
            end
        end)

        tNotif("Toilet Titan", string.format("Toilet Titan Active! (%d props)", #allToilets), 3)

        
        
        
        local MECHA_PARTS = {
            { name = "UpperTorso",   scf = allToilets[1] and allToilets[1].scf,   prop = allToilets[1] and allToilets[1].prop,   cpc = allToilets[1] and allToilets[1].cpc,   offset = CFrame.new(0, 0, 0) },
            { name = "Head",         scf = allToilets[2] and allToilets[2].scf,   prop = allToilets[2] and allToilets[2].prop,   cpc = allToilets[2] and allToilets[2].cpc,   offset = CFrame.new(0, 1.2, -0.2) * CFrame.Angles(math.rad(-8), 0, 0) },
            { name = "LowerTorso",   scf = allToilets[3] and allToilets[3].scf,   prop = allToilets[3] and allToilets[3].prop,   cpc = allToilets[3] and allToilets[3].cpc,   offset = CFrame.new(0, -1.0, 0) },

            { name = "LeftUpperArm", scf = allToilets[4] and allToilets[4].scf,   prop = allToilets[4] and allToilets[4].prop,   cpc = allToilets[4] and allToilets[4].cpc,   offset = CFrame.new(-0.8, 0.4, 0) * CFrame.Angles(0, math.rad(15), math.rad(22)) },
            { name = "LeftLowerArm", scf = allToilets[5] and allToilets[5].scf,   prop = allToilets[5] and allToilets[5].prop,   cpc = allToilets[5] and allToilets[5].cpc,   offset = CFrame.new(-0.6, -0.4, -0.4) * CFrame.Angles(math.rad(-15), math.rad(10), math.rad(12)) },
            { name = "LeftHand",     scf = allToilets[6] and allToilets[6].scf,   prop = allToilets[6] and allToilets[6].prop,   cpc = allToilets[6] and allToilets[6].cpc,   offset = CFrame.new(-0.4, -0.8, -0.8) * CFrame.Angles(math.rad(-20), 0, math.rad(8)) },

            { name = "RightUpperArm",scf = allToilets[7] and allToilets[7].scf,   prop = allToilets[7] and allToilets[7].prop,   cpc = allToilets[7] and allToilets[7].cpc,   offset = CFrame.new(0.8, 0.4, 0) * CFrame.Angles(0, math.rad(-15), math.rad(-22)) },
            { name = "RightLowerArm",scf = allToilets[8] and allToilets[8].scf,   prop = allToilets[8] and allToilets[8].prop,   cpc = allToilets[8] and allToilets[8].cpc,   offset = CFrame.new(0.6, -0.4, -0.4) * CFrame.Angles(math.rad(-15), math.rad(-10), math.rad(-12)) },
            { name = "RightHand",    scf = allToilets[9] and allToilets[9].scf,   prop = allToilets[9] and allToilets[9].prop,   cpc = allToilets[9] and allToilets[9].cpc,   offset = CFrame.new(0.4, -0.8, -0.8) * CFrame.Angles(math.rad(-20), 0, math.rad(-8)) },

            { name = "LeftUpperLeg", scf = allToilets[10] and allToilets[10].scf, prop = allToilets[10] and allToilets[10].prop, cpc = allToilets[10] and allToilets[10].cpc, offset = CFrame.new(-0.4, -0.4, 0) * CFrame.Angles(0, math.rad(5), math.rad(4)) },
            { name = "LeftLowerLeg", scf = allToilets[11] and allToilets[11].scf, prop = allToilets[11] and allToilets[11].prop, cpc = allToilets[11] and allToilets[11].cpc, offset = CFrame.new(-0.3, -0.6, 0) * CFrame.Angles(0, math.rad(5), math.rad(2)) },
            { name = "LeftFoot",     scf = allToilets[12] and allToilets[12].scf, prop = allToilets[12] and allToilets[12].prop, cpc = allToilets[12] and allToilets[12].cpc, offset = CFrame.new(-0.2, -0.8, 0.4) * CFrame.Angles(math.rad(6), 0, 0) },

            { name = "RightUpperLeg",scf = allToilets[13] and allToilets[13].scf, prop = allToilets[13] and allToilets[13].prop, cpc = allToilets[13] and allToilets[13].cpc, offset = CFrame.new(0.4, -0.4, 0) * CFrame.Angles(0, math.rad(-5), math.rad(-4)) },
            { name = "RightLowerLeg",scf = allToilets[14] and allToilets[14].scf, prop = allToilets[14] and allToilets[14].prop, cpc = allToilets[14] and allToilets[14].cpc, offset = CFrame.new(0.3, -0.6, 0) * CFrame.Angles(0, math.rad(-5), math.rad(-2)) },
            { name = "RightFoot",    scf = allToilets[15] and allToilets[15].scf, prop = allToilets[15] and allToilets[15].prop, cpc = allToilets[15] and allToilets[15].cpc, offset = CFrame.new(0.2, -0.8, 0.4) * CFrame.Angles(math.rad(6), 0, 0) },
        }

        titanPartsList = MECHA_PARTS

        
        if titanColorTheme ~= "Default" then
            applyToiletTitanTheme(titanColorTheme)
        end

        local floorRayParams = RaycastParams.new()
        floorRayParams.FilterDescendantsInstances = {lp.Character, wc}
        floorRayParams.FilterType = Enum.RaycastFilterType.Exclude

        titanLoop = rs.RenderStepped:Connect(function()
            if not titanActive then return end

            local cc = lp.Character
            if not cc then return end
            local hrpNow = cc:FindFirstChild("HumanoidRootPart")
            local humNow = cc:FindFirstChildOfClass("Humanoid")
            if not hrpNow or not humNow then return end

            local hrpCF = hrpNow.CFrame
            local forwardFlat = (hrpCF.LookVector * Vector3.new(1, 0, 1)).Unit
            if forwardFlat.Magnitude < 0.001 then forwardFlat = hrpCF.LookVector end

            local groundRay = workspace:Raycast(hrpNow.Position, Vector3.new(0, -120, 0), floorRayParams)
            local groundY = groundRay and groundRay.Position.Y or (hrpNow.Position.Y - humNow.HipHeight - 1.5)

            local jumpDelta = math.max(0, (hrpNow.Position.Y - groundY) - humNow.HipHeight - 1.5)
            local baseHeight = 25.5 * (titanConfig.size / 6.8)
            local torsoCenterY = groundY + baseHeight + titanConfig.height + jumpDelta

            local centerCF = CFrame.new(hrpCF.Position.X, torsoCenterY, hrpCF.Position.Z)
                * CFrame.new(titanConfig.posX, 0, titanConfig.posZ)
                * CFrame.Angles(0, math.rad(titanConfig.rotY), 0)
                * (hrpCF - hrpCF.Position)

            local REF_WIDTH = 0.7000001072883606
            local REF_HEIGHT = 1.0499999523162842
            local REF_DEPTH = 0.8500000834465027

            local curDepth = REF_DEPTH
            local curHeight = REF_HEIGHT
            local curWidth = REF_WIDTH
            if humNow then
                local dVal = humNow:FindFirstChild("BodyDepthScale")
                if dVal and dVal:IsA("NumberValue") and dVal.Value > 0.001 then curDepth = dVal.Value end
                local hVal = humNow:FindFirstChild("BodyHeightScale")
                if hVal and hVal:IsA("NumberValue") and hVal.Value > 0.001 then curHeight = hVal.Value end
                local wVal = humNow:FindFirstChild("BodyWidthScale")
                if wVal and wVal:IsA("NumberValue") and wVal.Value > 0.001 then curWidth = wVal.Value end
            end

            local normX = curWidth / REF_WIDTH
            local normY = curHeight / REF_HEIGHT
            local normZ = curDepth / REF_DEPTH
            if math.abs(normX) < 0.001 then normX = 1 end
            if math.abs(normY) < 0.001 then normY = 1 end
            if math.abs(normZ) < 0.001 then normZ = 1 end

            
            for _, p in pairs(cc:GetDescendants()) do
                if (p:IsA("BasePart") or p:IsA("Decal")) and p.Transparency < 1 then
                    if not savedTransparencies[p] then
                        savedTransparencies[p] = p.Transparency
                    end
                    p.Transparency = 1
                end
            end

            
            for _, entry in ipairs(MECHA_PARTS) do
                if entry.scf then
                    local part = cc:FindFirstChild(entry.name)
                    if not part and entry.name == "UpperTorso" then
                        part = cc:FindFirstChild("Torso") or hrpNow
                    end

                    if part then
                        local rel = hrpCF:ToObjectSpace(part.CFrame)

                        local xMult = 1.0
                        if entry.name:find("Arm") or entry.name:find("Hand") then
                            xMult = titanConfig.armWidth
                        elseif entry.name:find("Leg") or entry.name:find("Foot") then
                            xMult = titanConfig.legWidth
                        end

                        local unscaledX = rel.Position.X / normX
                        local unscaledY = rel.Position.Y / normY
                        local unscaledZ = rel.Position.Z / normZ

                        local scaledPos = Vector3.new(
                            unscaledX * titanConfig.size * xMult,
                            unscaledY * titanConfig.size,
                            unscaledZ * titanConfig.size
                        )

                        if entry.name:find("LowerArm") then
                            scaledPos = scaledPos + Vector3.new(0, -titanConfig.armSpacing, 0)
                        elseif entry.name:find("Hand") then
                            scaledPos = scaledPos + Vector3.new(0, -titanConfig.armSpacing * 2, 0)
                        end

                        if entry.name:find("Leg") or entry.name:find("Foot") then
                            scaledPos = scaledPos + Vector3.new(0, titanConfig.legOffsetY, 0)
                            if entry.name:find("LowerLeg") then
                                scaledPos = scaledPos + Vector3.new(0, titanConfig.legSpacing, 0)
                            elseif entry.name:find("Foot") then
                                scaledPos = scaledPos + Vector3.new(0, titanConfig.legSpacing * 2, 0)
                            end
                        end

                        local relRot = rel - rel.Position
                        local extraOffset = entry.offset or CFrame.new()

                        local targetCF = centerCF * CFrame.new(scaledPos) * relRot * extraOffset

                        sendCF(entry.scf, targetCF, entry.prop)
                    end
                end
            end

            
            if humNow and humNow.MoveDirection.Magnitude > 0.05 then
                if humNow:GetState() ~= Enum.HumanoidStateType.Running then
                    pcall(function() humNow:ChangeState(Enum.HumanoidStateType.Running) end)
                end
                if humNow.WalkSpeed < titanConfig.walkSpeed then
                    humNow.WalkSpeed = titanConfig.walkSpeed
                end

                local hasRun = false
                for _, track in ipairs(humNow:GetPlayingAnimationTracks()) do
                    local animName = track.Name:lower()
                    if animName:find("idle") or animName:find("walk") then
                        track:Stop(0.05)
                    elseif animName:find("run") and track.Priority == Enum.AnimationPriority.Action4 then
                        hasRun = true
                        track:AdjustSpeed(titanConfig.animSpeed)
                    end
                end

                if not hasRun then
                    local animScript = cc:FindFirstChild("Animate")
                    local runAnim = animScript and animScript:FindFirstChild("run") and animScript.run:FindFirstChildOfClass("Animation")
                    if runAnim then
                        pcall(function()
                            local runTrack = humNow:LoadAnimation(runAnim)
                            runTrack.Priority = Enum.AnimationPriority.Action4
                            runTrack:Play(0.05)
                            runTrack:AdjustSpeed(titanConfig.animSpeed)
                        end)
                    end
                end
            else
                
                for _, track in ipairs(humNow:GetPlayingAnimationTracks()) do
                    local animName = track.Name:lower()
                    if animName:find("run") and track.Priority == Enum.AnimationPriority.Action4 then
                        track:Stop(0.1)
                    end
                end
            end

            
            if titanColorTheme == "Rainbow" then
                local nowTick = tick()
                for i, entry in ipairs(MECHA_PARTS) do
                    local waveColor = Color3.fromHSV((nowTick * 0.4 + (i / #MECHA_PARTS)) % 1, 1, 1)

                    if entry.prop then
                        pcall(function()
                            for _, p in ipairs(entry.prop:GetDescendants()) do
                                if p:IsA("BasePart") then
                                    p.Color = waveColor
                                end
                            end
                        end)
                    end

                    if entry.cpc and (nowTick - (entry.lastColorSent or 0) >= 0.25) then
                        entry.lastColorSent = nowTick
                        task.spawn(function()
                            pcall(function() entry.cpc:InvokeServer(waveColor) end)
                        end)
                    end
                end
            end
        end)
    end

    
    
    
    BuildV2Tab:AddSection({"> Toilet Titan (Robot 2)"})

    BuildV2Tab:AddToggle({
        Name = "Spawn Toilet Titan",
        Description = "Pilot a giant 15-prop toilet mech with real-time R15 motion replication",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            if not val and not titanActive then return end
            if val then
                task.spawn(spawnToiletTitan)
            else
                stopToiletTitan()
            end
        end
    })

    BuildV2Tab:AddDropdown({
        Name = "Toilet Titan Color Theme",
        Description = "Select robot color or animated wave",
        Options = {
            "Default",
            "Rainbow",
            "Cyberpunk",
            "Obsidian",
            "Gold",
            "Crimson",
            "Violet",
            "Acid",
            "Ice",
            "Magma"
        },
        Default = "Default",
        Callback = function(choice)
            applyToiletTitanTheme(choice)
        end
    })
end

do
    local lp = game:GetService("Players").LocalPlayer
    local rs = game:GetService("RunService")
    local rep = game:GetService("ReplicatedStorage")

    local genActive = false
    local genLoop = nil
    local genPhysicsConn = nil
    local myPropName = "Prop" .. lp.Name

    local savedHipHeight = 2.0
    local savedWalkSpeed = 16
    local currentHipHeightVal = 62.0
    local savedTransparencies = {}

    local genColorTheme = "Default"
    local genPartsList = {}

    local mechaConfig = {
        size = 11.0,
        height = 1.0,
        posZ = 0.0,
        posX = 0.0,
        rotY = 0.0,
        walkSpeed = 40.0,
        animSpeed = 0.85,
        torsoRotX = 90.0,
        torsoRotY = 0.0,
        torsoRotZ = 0.0,
        torsoOffsetX = 1.0,
        torsoOffsetY = -2.0,
        torsoOffsetZ = -3.0,
        armWidth = 1.03,
        armSpacing = 5.45,
        legWidth = 0.74,
        legOffsetY = 0.0,
        legSpacing = 0.0,
        pelvisOffsetX = -2.00,
        pelvisOffsetY = -3.50,
        pelvisOffsetZ = -1.00,
        pelvisRotX = 0.00,
        pelvisRotY = 85.00,
        pelvisRotZ = 0.00,
    }

    local limbRot = {
        armPitch = 0,
        armYaw = 33,
        armRoll = 0,
        legPitch = 0,
        legYaw = 33,
        legRoll = 0,
        headPitch = 0,
        headYaw = 0,
        headRoll = 0,
        pelvisPitch = 0,
        pelvisYaw = 0,
        pelvisRoll = 0,
    }

    local GEN_THEMES = {
        ["Obsidian"] = Color3.fromRGB(15, 15, 18),
        ["Gold"]     = Color3.fromRGB(255, 215, 0),
        ["Crimson"]  = Color3.fromRGB(220, 20, 35),
        ["Violet"]   = Color3.fromRGB(150, 40, 240),
        ["Acid"]     = Color3.fromRGB(50, 255, 60),
        ["Ice"]      = Color3.fromRGB(0, 230, 255),
        ["Magma"]    = Color3.fromRGB(255, 115, 0),
    }

    local function gNotif(title, text, dur)
        pcall(function()
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = title,
                Text = text,
                Duration = dur or 3
            })
        end)
    end

    local function applyPlayerLift(newVal)
        local char = lp.Character
        if char then
            local hum = char:FindFirstChildOfClass("Humanoid")
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hum and hrp then
                hum.HipHeight = newVal
                if newVal > 3.0 then
                    hrp.CFrame = hrp.CFrame + Vector3.new(0, 0.5, 0)
                end
            end
        end
    end

    local function smoothClimbTo(targetVal, step)
        step = step or 2.0
        task.spawn(function()
            local char = lp.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            local current = (hum and hum.HipHeight) or 2.0
            if current < targetVal then
                for v = current + step, targetVal, step do
                    applyPlayerLift(v)
                    task.wait(0.02)
                end
                applyPlayerLift(targetVal)
            else
                for v = current - step, targetVal, -step do
                    applyPlayerLift(v)
                    task.wait(0.02)
                end
                applyPlayerLift(targetVal)
            end
        end)
    end

    local function setCharacterHidden(hidden)
        local char = lp.Character
        if not char then return end
        if hidden then
            for _, part in pairs(char:GetDescendants()) do
                if part:IsA("BasePart") or part:IsA("Decal") then
                    if not savedTransparencies[part] then
                        savedTransparencies[part] = part.Transparency
                    end
                    part.Transparency = 1
                end
            end
        else
            for part, origVal in pairs(savedTransparencies) do
                if part and part.Parent then
                    pcall(function() part.Transparency = origVal end)
                end
            end
            savedTransparencies = {}
        end
    end

    local function _0xH_3f2()
        local backpack = lp:FindFirstChild("Backpack")
        local character = lp.Character
        if not backpack or not character then return nil end
        local tool = character:FindFirstChild("PropMaker") or backpack:FindFirstChild("PropMaker")
        if not tool then
            pcall(function()
                rep:WaitForChild("RE"):WaitForChild("1Too1l"):InvokeServer("PickingTools", "PropMaker")
            end)
            local start = tick()
            while tick() - start < 2.0 do
                tool = character:FindFirstChild("PropMaker") or backpack:FindFirstChild("PropMaker")
                if tool then break end
                task.wait(0.05)
            end
        end
        if tool and tool.Parent ~= character then
            local hum = character:FindFirstChildOfClass("Humanoid")
            if hum then
                hum:EquipTool(tool)
                local eqStart = tick()
                while tick() - eqStart < 2.0 do
                    if tool.Parent == character then break end
                    task.wait(0.05)
                end
            end
        end
        return tool
    end

    local function _0xH_3f3(firstProp, countNeeded)
        if not firstProp then return false end
        local dupRemote = firstProp:FindFirstChild("DuplicateProp") or firstProp:WaitForChild("DuplicateProp", 2)
        if not dupRemote then return false end

        for _ = 1, countNeeded do
            pcall(function() dupRemote:InvokeServer() end)
            task.wait(0.05)
        end
        return true
    end

    local senders = {}
    local RATE_LIMIT = 0.03

    local function sendCF(scf, cf, prop)
        if not genActive or not scf then return end

        if prop then
            pcall(function()
                if prop:IsA("Model") then
                    prop:PivotTo(cf)
                elseif prop:IsA("BasePart") then
                    prop.CFrame = cf
                end
            end)
        end

        local entry = senders[scf]
        local now = tick()
        if not entry then
            entry = { lastSent = 0, nextCF = cf, sending = false }
            senders[scf] = entry
        else
            entry.nextCF = cf
        end

        if not entry.sending and (now - entry.lastSent >= RATE_LIMIT) then
            entry.sending = true
            entry.lastSent = now
            local toSend = entry.nextCF
            entry.nextCF = nil
            task.spawn(function()
                pcall(function() scf:InvokeServer(toSend) end)
                entry.sending = false
                if genActive and entry.nextCF and (tick() - entry.lastSent >= RATE_LIMIT) then
                    entry.sending = true
                    entry.lastSent = tick()
                    local nextSend = entry.nextCF
                    entry.nextCF = nil
                    task.spawn(function()
                        pcall(function() scf:InvokeServer(nextSend) end)
                        entry.sending = false
                    end)
                end
            end)
        end
    end

    local function applyThemeToPart(prop, cpc, col)
        if prop then
            pcall(function()
                for _, p in ipairs(prop:GetDescendants()) do
                    if p:IsA("BasePart") then
                        p.Color = col
                    end
                end
            end)
        end
        if cpc then
            task.spawn(function()
                pcall(function() cpc:InvokeServer(col) end)
            end)
        end
    end

    local function applyGeneratorTitanTheme(themeName)
        genColorTheme = themeName
        if not genActive or #genPartsList == 0 then return end

        if themeName == "Default" then
            for _, entry in ipairs(genPartsList) do
                applyThemeToPart(entry.prop, entry.cpc, Color3.fromRGB(163, 162, 165))
            end
            gNotif("Generator Titan", "Theme: Default", 2)
            return
        elseif themeName == "Rainbow" then
            gNotif("Generator Titan", "Theme: Rainbow Wave", 2)
            return
        elseif themeName == "Cyberpunk" then
            for i, entry in ipairs(genPartsList) do
                local col = (i % 2 == 0) and Color3.fromRGB(0, 235, 255) or Color3.fromRGB(255, 30, 150)
                applyThemeToPart(entry.prop, entry.cpc, col)
            end
            gNotif("Generator Titan", "Theme: Cyberpunk", 2)
            return
        end

        local solidCol = GEN_THEMES[themeName] or Color3.fromRGB(163, 162, 165)
        for _, entry in ipairs(genPartsList) do
            applyThemeToPart(entry.prop, entry.cpc, solidCol)
        end
        gNotif("Generator Titan", "Theme: " .. themeName, 2)
    end

    local function stopGeneratorTitan()
        if not genActive then return end
        genActive = false
        if genLoop then
            genLoop:Disconnect()
            genLoop = nil
        end
        if genPhysicsConn then
            genPhysicsConn:Disconnect()
            genPhysicsConn = nil
        end
        senders = {}
        genPartsList = {}

        local char = lp.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum then
            hum.WalkSpeed = savedWalkSpeed or 16
            pcall(function()
                hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true)
                hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
                hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, true)
            end)
            for _, track in ipairs(hum:GetPlayingAnimationTracks()) do
                if track.Priority == Enum.AnimationPriority.Action4 or track.Name:lower():find("run") then
                    pcall(function() track:Stop(0.1) end)
                end
            end
            pcall(function() hum:ChangeState(Enum.HumanoidStateType.Landed) end)
        end

        smoothClimbTo(savedHipHeight or 2.0, 4.0)
        setCharacterHidden(false)

        task.wait(0.15)
        pcall(function() rep:WaitForChild("RE"):WaitForChild("1Clea1rTool1s"):FireServer("ClearAllProps") end)
        task.wait(0.3)
        pcall(function() rep:WaitForChild("RE"):WaitForChild("1Clea1rTool1s"):FireServer("ClearAllProps") end)
        gNotif("Generator Titan", "Titan offline and props cleared.", 3)
    end

    local function getTargetSurface(targetWorldPos)
        local street = workspace:FindFirstChild("Model") and workspace.Model:FindFirstChild("Street") and workspace.Model.Street:FindFirstChild("Street")

        local rayParams = RaycastParams.new()
        rayParams.FilterDescendantsInstances = {lp.Character, workspace:FindFirstChild("WorkspaceCom")}
        rayParams.FilterType = Enum.RaycastFilterType.Exclude

        local ray = workspace:Raycast(targetWorldPos + Vector3.new(0, 10, 0), Vector3.new(0, -30, 0), rayParams)
        local hitInst = street or (ray and ray.Instance) or workspace.Terrain
        local hitPos = ray and ray.Position or targetWorldPos

        return hitInst, hitPos
    end

    local function spawnGeneratorTitan()
        if genActive then stopGeneratorTitan() task.wait(0.5) end
        genActive = true

        local char = lp.Character or lp.CharacterAdded:Wait()
        local hrp = char:WaitForChild("HumanoidRootPart")
        local hum = char:WaitForChild("Humanoid")
        savedHipHeight = hum.HipHeight
        savedWalkSpeed = hum.WalkSpeed
        hum.WalkSpeed = mechaConfig.walkSpeed

        pcall(function()
            hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, false)
            hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
            hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)
        end)

        gNotif("Generator Titan", "Assembling 15-prop Titan...", 3)

        local clearRE = rep:WaitForChild("RE"):WaitForChild("1Clea1rTool1s")
        local toolRE = rep:WaitForChild("RE"):WaitForChild("1Too1l")
        local Telemetry = rep:FindFirstChild("Remotes") and rep.Remotes:FindFirstChild("TelemetryClientInteraction")

        pcall(function() clearRE:FireServer("ClearAllProps") end)
        task.wait(0.5)

        local propsTool = _0xH_3f2()
        if not propsTool then gNotif("Generator Titan", "PropMaker tool unavailable!", 3) return end

        pcall(function() clearRE:FireServer("OpenPropMenu") end)
        task.wait(0.2)

        local wc = workspace:FindFirstChild("WorkspaceCom")
        if not wc then gNotif("Generator Titan", "WorkspaceCom missing!", 3) return end

        local bunkerTarget = hrp.Position + (hrp.CFrame.LookVector * 14)
        local generatorTarget = hrp.Position - (hrp.CFrame.LookVector * 10)

        local bunkerHitInst, bunkerHitPos = getTargetSurface(bunkerTarget)
        local generatorHitInst, generatorHitPos = getTargetSurface(generatorTarget)

        local existingProps = {}
        for _, folder in pairs(wc:GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName then
                    existingProps[prop] = true
                end
            end
        end

        local function spawnSingleProp(propName, categoryName, targetInst, targetPos)
            local tool = _0xH_3f2()
            if not tool then return nil end

            if Telemetry then
                pcall(function() Telemetry:FireServer("filterClick", {name = categoryName, itemType = "Props"}) end)
                task.wait(0.05)
                pcall(function() Telemetry:FireServer("filterClick", {name = propName, itemType = "Props"}) end)
                task.wait(0.05)
            end

            pcall(function() clearRE:FireServer("RequestingPropName", propName, categoryName) end)
            task.wait(0.3)

            local currentHum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
            if currentHum and tool.Parent ~= lp.Character then
                currentHum:EquipTool(tool)
                task.wait(0.1)
            end

            local tpm = tool:FindFirstChild("Tool_PropMake")
            local startW = tick()
            while not tpm and tick() - startW < 4.0 and genActive do
                tpm = tool:FindFirstChild("Tool_PropMake")
                if not tpm then
                    local bp = lp.Backpack:FindFirstChild("PropMaker")
                    if bp then tpm = bp:FindFirstChild("Tool_PropMake") end
                end
                if not tpm then task.wait(0.1) end
            end

            if not tpm then return nil end

            local useInst = targetInst or bunkerHitInst
            local usePos = targetPos or bunkerHitPos
            pcall(function() tpm:FireServer(useInst, usePos) end)

            local spawned = nil
            local t0 = tick()
            while tick() - t0 < 4.0 and genActive do
                for _, folder in pairs(wc:GetChildren()) do
                    for _, prop in pairs(folder:GetChildren()) do
                        if prop.Name == myPropName and not existingProps[prop] then
                            spawned = prop
                            existingProps[prop] = true
                            break
                        end
                    end
                    if spawned then break end
                end
                if spawned then break end
                task.wait(0.05)
            end

            return spawned
        end

        
        local chestProp = spawnSingleProp("BigGunBunker", "Big", bunkerHitInst, bunkerHitPos)
        if not chestProp then
            chestProp = spawnSingleProp("BigGunBunker", "Big", bunkerHitInst, bunkerHitPos)
        end
        if not chestProp then gNotif("Generator Titan", "Chest prop failed!", 3) return end

        
        local firstGen = spawnSingleProp("BigGenerator", "Building", generatorHitInst, generatorHitPos)
        if not firstGen then
            firstGen = spawnSingleProp("BigGenerator", "Building", generatorHitInst, generatorHitPos)
        end
        if not firstGen then gNotif("Generator Titan", "BigGenerator failed!", 3) return end

        
        _0xH_3f3(firstGen, 13)
        task.wait(0.8)

                                                                   
        task.wait(1.0)
        pcall(function() toolRE:InvokeServer("PickingTools", "PropMaker") end)
        pcall(function() clearRE:FireServer("ClosePropMenu") end)

        task.wait(0.3)
        local generatorProps = {}
        for _, folder in pairs(wc:GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName and prop ~= chestProp then
                    local scf = prop:FindFirstChild("SetCurrentCFrame") or prop:FindFirstChildWhichIsA("RemoteFunction", true)
                    local cpc = prop:FindFirstChild("ChangePropColor") or prop:FindFirstChild("ChangePropColor", true)
                    if scf then
                        table.insert(generatorProps, {prop = prop, scf = scf, cpc = cpc})
                        pcall(function()
                            for _, p in ipairs(prop:GetDescendants()) do
                                if p:IsA("BasePart") then
                                    p.CanCollide = false
                                    p.CanTouch = false
                                    p.CanQuery = false
                                    p.Massless = true
                                end
                            end
                        end)
                    end
                end
            end
        end

        local chestScf = chestProp:FindFirstChild("SetCurrentCFrame") or chestProp:FindFirstChild("SetCurrentCFrame", true) or chestProp:FindFirstChildWhichIsA("RemoteFunction", true)
        local chestCpc = chestProp:FindFirstChild("ChangePropColor") or chestProp:FindFirstChild("ChangePropColor", true)
        if not chestScf then gNotif("Generator Titan", "Chest SetCurrentCFrame missing!", 3) return end

        pcall(function()
            for _, p in ipairs(chestProp:GetDescendants()) do
                if p:IsA("BasePart") then
                    p.CanCollide = false
                    p.CanTouch = false
                    p.CanQuery = false
                    p.Massless = true
                end
            end
        end)

        task.wait(0.3)
        smoothClimbTo(currentHipHeightVal, 2.0)
        setCharacterHidden(true)

        
        genPhysicsConn = rs.Stepped:Connect(function()
            if not genActive then return end
            local cc = lp.Character
            if cc then
                for _, part in ipairs(cc:GetDescendants()) do
                    if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                        part.CanCollide = false
                        part.CanTouch = false
                    end
                end
            end
            if chestProp then
                for _, p in ipairs(chestProp:GetDescendants()) do
                    if p:IsA("BasePart") then
                        p.CanCollide = false
                        p.CanTouch = false
                        p.CanQuery = false
                    end
                end
            end
            for _, genData in ipairs(generatorProps) do
                if genData.prop then
                    for _, p in ipairs(genData.prop:GetDescendants()) do
                        if p:IsA("BasePart") then
                            p.CanCollide = false
                            p.CanTouch = false
                            p.CanQuery = false
                        end
                    end
                end
            end
        end)

        gNotif("Generator Titan", string.format("Generator Titan Active! (%d props)", #generatorProps + 1), 3)

        
        
        
        local MECHA_PARTS = {
            { name = "UpperTorso", scf = chestScf, prop = chestProp, cpc = chestCpc, offset = CFrame.new(0, -2.5, 0) },
            { name = "Head", scf = generatorProps[1] and generatorProps[1].scf, prop = generatorProps[1] and generatorProps[1].prop, cpc = generatorProps[1] and generatorProps[1].cpc, isHead = true },
            { name = "LowerTorso", scf = generatorProps[2] and generatorProps[2].scf, prop = generatorProps[2] and generatorProps[2].prop, cpc = generatorProps[2] and generatorProps[2].cpc, isPelvis = true },

            { name = "LeftUpperArm", scf = generatorProps[3] and generatorProps[3].scf, prop = generatorProps[3] and generatorProps[3].prop, cpc = generatorProps[3] and generatorProps[3].cpc, isLeftArm = true },
            { name = "LeftLowerArm", scf = generatorProps[4] and generatorProps[4].scf, prop = generatorProps[4] and generatorProps[4].prop, cpc = generatorProps[4] and generatorProps[4].cpc, isLeftArm = true },
            { name = "LeftHand",     scf = generatorProps[5] and generatorProps[5].scf, prop = generatorProps[5] and generatorProps[5].prop, cpc = generatorProps[5] and generatorProps[5].cpc, isLeftArm = true },

            { name = "RightUpperArm", scf = generatorProps[6] and generatorProps[6].scf, prop = generatorProps[6] and generatorProps[6].prop, cpc = generatorProps[6] and generatorProps[6].cpc, isRightArm = true },
            { name = "RightLowerArm", scf = generatorProps[7] and generatorProps[7].scf, prop = generatorProps[7] and generatorProps[7].prop, cpc = generatorProps[7] and generatorProps[7].cpc, isRightArm = true },
            { name = "RightHand",     scf = generatorProps[8] and generatorProps[8].scf, prop = generatorProps[8] and generatorProps[8].prop, cpc = generatorProps[8] and generatorProps[8].cpc, isRightArm = true },

            { name = "LeftUpperLeg", scf = generatorProps[9] and generatorProps[9].scf, prop = generatorProps[9] and generatorProps[9].prop, cpc = generatorProps[9] and generatorProps[9].cpc, isLeftLeg = true },
            { name = "LeftLowerLeg", scf = generatorProps[10] and generatorProps[10].scf, prop = generatorProps[10] and generatorProps[10].prop, cpc = generatorProps[10] and generatorProps[10].cpc, isLeftLeg = true },
            { name = "LeftFoot",     scf = generatorProps[11] and generatorProps[11].scf, prop = generatorProps[11] and generatorProps[11].prop, cpc = generatorProps[11] and generatorProps[11].cpc, isLeftLeg = true },

            { name = "RightUpperLeg", scf = generatorProps[12] and generatorProps[12].scf, prop = generatorProps[12] and generatorProps[12].prop, cpc = generatorProps[12] and generatorProps[12].cpc, isRightLeg = true },
            { name = "RightLowerLeg", scf = generatorProps[13] and generatorProps[13].scf, prop = generatorProps[13] and generatorProps[13].prop, cpc = generatorProps[13] and generatorProps[13].cpc, isRightLeg = true },
            { name = "RightFoot",     scf = generatorProps[14] and generatorProps[14].scf, prop = generatorProps[14] and generatorProps[14].prop, cpc = generatorProps[14] and generatorProps[14].cpc, isRightLeg = true },
        }

        genPartsList = MECHA_PARTS

        if genColorTheme ~= "Default" then
            applyGeneratorTitanTheme(genColorTheme)
        end

        local rayParams = RaycastParams.new()
        rayParams.FilterType = Enum.RaycastFilterType.Exclude

        genLoop = rs.RenderStepped:Connect(function()
            if not genActive then return end

            local cc = lp.Character
            if not cc then return end
            local hrpNow = cc:FindFirstChild("HumanoidRootPart")
            local humNow = cc:FindFirstChildOfClass("Humanoid")
            if not hrpNow or not humNow then return end

            
            local rayFilter = {cc, workspace:FindFirstChild("WorkspaceCom")}
            for _, plr in ipairs(Players:GetPlayers()) do
                if plr.Character and plr.Character ~= cc then
                    table.insert(rayFilter, plr.Character)
                end
            end
            rayParams.FilterDescendantsInstances = rayFilter
            local ray = workspace:Raycast(hrpNow.Position + Vector3.new(0, 10, 0), Vector3.new(0, -250, 0), rayParams)
            local groundY = ray and ray.Position.Y
            local minFloorY = groundY and (groundY + currentHipHeightVal) or nil

            if minFloorY and hrpNow.Position.Y < minFloorY then
                local vel = hrpNow.AssemblyLinearVelocity
                if vel.Y < 0 then
                    hrpNow.AssemblyLinearVelocity = Vector3.new(vel.X, 0, vel.Z)
                end
                hrpNow.CFrame = CFrame.new(hrpNow.Position.X, minFloorY, hrpNow.Position.Z) * hrpNow.CFrame.Rotation
                if humNow and humNow:GetState() == Enum.HumanoidStateType.Freefall then
                    pcall(function() humNow:ChangeState(Enum.HumanoidStateType.Landed) end)
                end
            end

            local hrpCF = hrpNow.CFrame
            local forwardFlat = (hrpCF.LookVector * Vector3.new(1, 0, 1)).Unit
            if forwardFlat.Magnitude < 0.001 then forwardFlat = hrpCF.LookVector end

            local centerCF = hrpCF * CFrame.new(mechaConfig.posX, mechaConfig.height, mechaConfig.posZ) * CFrame.Angles(0, math.rad(mechaConfig.rotY), 0)

            local REF_WIDTH = 0.7000001072883606
            local REF_HEIGHT = 1.0499999523162842
            local REF_DEPTH = 0.8500000834465027

            local curDepth = REF_DEPTH
            local curHeight = REF_HEIGHT
            local curWidth = REF_WIDTH
            if humNow then
                local dVal = humNow:FindFirstChild("BodyDepthScale")
                if dVal and dVal:IsA("NumberValue") and dVal.Value > 0.001 then curDepth = dVal.Value end
                local hVal = humNow:FindFirstChild("BodyHeightScale")
                if hVal and hVal:IsA("NumberValue") and hVal.Value > 0.001 then curHeight = hVal.Value end
                local wVal = humNow:FindFirstChild("BodyWidthScale")
                if wVal and wVal:IsA("NumberValue") and wVal.Value > 0.001 then curWidth = wVal.Value end
            end

            local normX = curWidth / REF_WIDTH
            local normY = curHeight / REF_HEIGHT
            local normZ = curDepth / REF_DEPTH
            if math.abs(normX) < 0.001 then normX = 1 end
            if math.abs(normY) < 0.001 then normY = 1 end
            if math.abs(normZ) < 0.001 then normZ = 1 end

            
            for _, p in pairs(cc:GetDescendants()) do
                if (p:IsA("BasePart") or p:IsA("Decal")) and p.Transparency < 1 then
                    if not savedTransparencies[p] then
                        savedTransparencies[p] = p.Transparency
                    end
                    p.Transparency = 1
                end
            end

            for _, entry in ipairs(MECHA_PARTS) do
                if entry.scf then
                    local part = cc:FindFirstChild(entry.name)
                    if not part and entry.name == "UpperTorso" then
                        part = cc:FindFirstChild("Torso") or hrpNow
                    end
                    if part then
                        local rel = hrpCF:ToObjectSpace(part.CFrame)

                        local xMult = 1.0
                        if entry.name:find("Arm") or entry.name:find("Hand") then
                            xMult = mechaConfig.armWidth
                        elseif entry.name:find("Leg") or entry.name:find("Foot") then
                            xMult = mechaConfig.legWidth
                        end

                        local unscaledX = rel.Position.X / normX
                        local unscaledY = rel.Position.Y / normY
                        local unscaledZ = rel.Position.Z / normZ

                        local scaledPos = Vector3.new(unscaledX * mechaConfig.size * xMult, unscaledY * mechaConfig.size, unscaledZ * mechaConfig.size)

                        if entry.name:find("LowerArm") then
                            scaledPos = scaledPos + Vector3.new(0, -mechaConfig.armSpacing, 0)
                        elseif entry.name:find("Hand") then
                            scaledPos = scaledPos + Vector3.new(0, -mechaConfig.armSpacing * 2, 0)
                        end

                        if entry.name:find("Leg") or entry.name:find("Foot") then
                            scaledPos = scaledPos + Vector3.new(0, mechaConfig.legOffsetY, 0)
                            if entry.name:find("LowerLeg") then
                                scaledPos = scaledPos + Vector3.new(0, mechaConfig.legSpacing, 0)
                            elseif entry.name:find("UpperLeg") then
                                scaledPos = scaledPos + Vector3.new(0, mechaConfig.legSpacing * 2, 0)
                            end
                        end

                        local relRot = rel - rel.Position

                        local extraOffset = entry.offset or CFrame.new()
                        if entry.name == "UpperTorso" then
                            extraOffset = CFrame.new(mechaConfig.torsoOffsetX, mechaConfig.torsoOffsetY, mechaConfig.torsoOffsetZ)
                                * CFrame.Angles(math.rad(mechaConfig.torsoRotX), math.rad(mechaConfig.torsoRotY), math.rad(mechaConfig.torsoRotZ))
                        elseif entry.isHead then
                            extraOffset = CFrame.new(0, 1.5, 0) * CFrame.Angles(math.rad(limbRot.headPitch), math.rad(limbRot.headYaw), math.rad(limbRot.headRoll))
                        elseif entry.isPelvis then
                            extraOffset = (entry.offset or CFrame.new())
                                * CFrame.new(mechaConfig.pelvisOffsetX, mechaConfig.pelvisOffsetY, mechaConfig.pelvisOffsetZ)
                                * CFrame.Angles(math.rad(mechaConfig.pelvisRotX + limbRot.pelvisPitch), math.rad(mechaConfig.pelvisRotY + limbRot.pelvisYaw), math.rad(mechaConfig.pelvisRotZ + limbRot.pelvisRoll))
                        elseif entry.isLeftArm then
                            extraOffset = CFrame.Angles(math.rad(limbRot.armPitch), math.rad(limbRot.armYaw), math.rad(limbRot.armRoll))
                        elseif entry.isRightArm then
                            extraOffset = CFrame.Angles(math.rad(limbRot.armPitch), math.rad(-limbRot.armYaw), math.rad(-limbRot.armRoll))
                        elseif entry.isLeftLeg then
                            extraOffset = CFrame.Angles(math.rad(limbRot.legPitch), math.rad(limbRot.legYaw), math.rad(limbRot.legRoll))
                        elseif entry.isRightLeg then
                            extraOffset = CFrame.Angles(math.rad(limbRot.legPitch), math.rad(-limbRot.legYaw), math.rad(-limbRot.legRoll))
                        end

                        local targetCF = centerCF * CFrame.new(scaledPos) * relRot * extraOffset

                        sendCF(entry.scf, targetCF, entry.prop)
                    end
                end
            end

            
            if humNow and humNow.MoveDirection.Magnitude > 0.05 then
                if humNow:GetState() ~= Enum.HumanoidStateType.Running then
                    pcall(function() humNow:ChangeState(Enum.HumanoidStateType.Running) end)
                end
                if humNow.WalkSpeed < mechaConfig.walkSpeed then
                    humNow.WalkSpeed = mechaConfig.walkSpeed
                end

                local hasRun = false
                for _, track in ipairs(humNow:GetPlayingAnimationTracks()) do
                    local animName = track.Name:lower()
                    if animName:find("idle") or animName:find("walk") then
                        track:Stop(0.05)
                    elseif animName:find("run") and track.Priority == Enum.AnimationPriority.Action4 then
                        hasRun = true
                        track:AdjustSpeed(mechaConfig.animSpeed)
                    end
                end

                if not hasRun then
                    local animScript = cc:FindFirstChild("Animate")
                    local runAnim = animScript and animScript:FindFirstChild("run") and animScript.run:FindFirstChildOfClass("Animation")
                    if runAnim then
                        pcall(function()
                            local runTrack = humNow:LoadAnimation(runAnim)
                            runTrack.Priority = Enum.AnimationPriority.Action4
                            runTrack:Play(0.05)
                            runTrack:AdjustSpeed(mechaConfig.animSpeed)
                        end)
                    end
                end
            else
                
                for _, track in ipairs(humNow:GetPlayingAnimationTracks()) do
                    local animName = track.Name:lower()
                    if animName:find("run") and track.Priority == Enum.AnimationPriority.Action4 then
                        track:Stop(0.1)
                    end
                end
            end

            
            if humNow.HipHeight ~= currentHipHeightVal and currentHipHeightVal >= 60.0 then
                humNow.HipHeight = currentHipHeightVal
            end

            
            if genColorTheme == "Rainbow" then
                local nowTick = tick()
                for i, entry in ipairs(MECHA_PARTS) do
                    local waveColor = Color3.fromHSV((nowTick * 0.4 + (i / #MECHA_PARTS)) % 1, 1, 1)

                    if entry.prop then
                        pcall(function()
                            for _, p in ipairs(entry.prop:GetDescendants()) do
                                if p:IsA("BasePart") then
                                    p.Color = waveColor
                                end
                            end
                        end)
                    end

                    if entry.cpc and (nowTick - (entry.lastColorSent or 0) >= 0.25) then
                        entry.lastColorSent = nowTick
                        task.spawn(function()
                            pcall(function() entry.cpc:InvokeServer(waveColor) end)
                        end)
                    end
                end
            end
        end)
    end

    
    
    
    BuildV2Tab:AddSection({"> Generator Titan (Robot 3)"})

    BuildV2Tab:AddToggle({
        Name = "Spawn Generator Titan",
        Description = "Pilot a colossal 15-prop generator mecha with real-time R15 motion replication",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            if not val and not genActive then return end
            if val then
                task.spawn(spawnGeneratorTitan)
            else
                stopGeneratorTitan()
            end
        end
    })

    BuildV2Tab:AddDropdown({
        Name = "Generator Titan Color Theme",
        Description = "Select robot color or animated wave",
        Options = {
            "Default",
            "Rainbow",
            "Cyberpunk",
            "Obsidian",
            "Gold",
            "Crimson",
            "Violet",
            "Acid",
            "Ice",
            "Magma"
        },
        Default = "Default",
        Callback = function(choice)
            applyGeneratorTitanTheme(choice)
        end
    })
end

do
    local lp = game:GetService("Players").LocalPlayer
    local rs = game:GetService("RunService")
    local rep = game:GetService("ReplicatedStorage")

    local fusionActive = false
    local fusionLoop = nil
    local fusionPhysicsConn = nil
    local myPropName = "Prop" .. lp.Name

    local savedHipHeight = 2.0
    local savedWalkSpeed = 16
    local savedJumpPower = 50
    local savedUseJumpPower = false
    local currentHipHeightVal = 62.0
    local savedTransparencies = {}
    local fusionColorTheme = "Default"

    local fusionPartsList = {}
    local currentFusionOrigin = nil

    local fusionConfig = {
        size = 11.0,
        height = -7.50,
        posZ = 0.0,
        posX = 0.0,
        rotY = 0.0,
        walkSpeed = 42.0,
        animSpeed = 0.85,
        playerLift = 62.0,
        torsoRotX = 90.0,
        torsoRotY = 0.0,
        torsoRotZ = 0.0,
        torsoOffsetX = 1.0,
        torsoOffsetY = -2.0,
        torsoOffsetZ = -3.0,
        armWidth = 1.03,
        armSpacing = 5.45,
        legWidth = 0.74,
        legOffsetY = 0.0,
        legSpacing = 0.0,
        pelvisOffsetX = -2.00,
        pelvisOffsetY = -3.50,
        pelvisOffsetZ = -1.00,
        pelvisRotX = 0.00,
        pelvisRotY = 85.00,
        pelvisRotZ = 0.00,
    }

    local FUSION_THEMES = {
        ["Default"]   = Color3.fromRGB(130, 135, 145),
        ["Obsidian"]  = Color3.fromRGB(15, 15, 18),
        ["Gold"]      = Color3.fromRGB(255, 215, 0),
        ["Crimson"]   = Color3.fromRGB(220, 20, 35),
        ["Violet"]    = Color3.fromRGB(150, 40, 240),
        ["Acid"]      = Color3.fromRGB(50, 255, 60),
        ["Ice"]       = Color3.fromRGB(0, 230, 255),
        ["Magma"]     = Color3.fromRGB(255, 115, 0),
    }

    local function fNotif(title, text, dur)
        pcall(function()
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = title,
                Text = text,
                Duration = dur or 3
            })
        end)
    end

    local function applyPlayerLift(newVal)
        local char = lp.Character
        if char then
            local hum = char:FindFirstChildOfClass("Humanoid")
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hum and hrp then
                hum.HipHeight = newVal
                if newVal > 3.0 then
                    hrp.CFrame = hrp.CFrame + Vector3.new(0, 0.5, 0)
                end
            end
        end
    end

    local function smoothClimbTo(targetVal, step)
        step = step or 3.0
        task.spawn(function()
            local char = lp.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            local current = (hum and hum.HipHeight) or 2.0
            if current < targetVal then
                for v = current + step, targetVal, step do
                    if not fusionActive then break end
                    applyPlayerLift(v)
                    task.wait(0.02)
                end
                if fusionActive then applyPlayerLift(targetVal) end
            else
                for v = current - step, targetVal, -step do
                    applyPlayerLift(v)
                    task.wait(0.02)
                end
                applyPlayerLift(targetVal)
            end
        end)
    end

    local function setCharacterHidden(hide)
        local char = lp.Character
        if not char then return end
        for _, part in ipairs(char:GetDescendants()) do
            if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                if hide then
                    if savedTransparencies[part] == nil then
                        savedTransparencies[part] = part.Transparency
                    end
                    part.Transparency = 1
                else
                    if savedTransparencies[part] ~= nil then
                        part.Transparency = savedTransparencies[part]
                    end
                end
            elseif part:IsA("Decal") then
                if hide then
                    if savedTransparencies[part] == nil then
                        savedTransparencies[part] = part.Transparency
                    end
                    part.Transparency = 1
                else
                    if savedTransparencies[part] ~= nil then
                        part.Transparency = savedTransparencies[part]
                    end
                end
            end
        end
        if not hide then savedTransparencies = {} end
    end

    local function _0xH_3f2()
        local tool = lp.Character and lp.Character:FindFirstChild("PropMaker")
        if not tool then
            tool = lp.Backpack:FindFirstChild("PropMaker")
        end
        if not tool then
            local toolRE = rep:WaitForChild("RE"):WaitForChild("1Too1l")
            pcall(function() toolRE:InvokeServer("PickingTools", "PropMaker") end)
            task.wait(0.3)
            tool = lp.Character and lp.Character:FindFirstChild("PropMaker")
            if not tool then tool = lp.Backpack:FindFirstChild("PropMaker") end
        end
        return tool
    end

    local function _0xH_3f3(firstProp, countNeeded)
        if not firstProp then return false end
        local dupRemote = firstProp:FindFirstChild("DuplicateProp") or firstProp:WaitForChild("DuplicateProp", 2)
        if not dupRemote then return false end

        for i = 1, countNeeded do
            pcall(function() dupRemote:InvokeServer() end)
            task.wait(0.05)
        end
        return true
    end

    local senders = {}
    local RATE_LIMIT = 0.03

    local function sendCF(scf, cf, prop)
        if not fusionActive or not scf then return end

        if prop then
            pcall(function()
                if prop:IsA("Model") then
                    prop:PivotTo(cf)
                elseif prop:IsA("BasePart") then
                    prop.CFrame = cf
                end
            end)
        end

        local entry = senders[scf]
        local now = tick()
        if not entry then
            entry = { lastSent = 0, nextCF = cf, sending = false }
            senders[scf] = entry
        else
            entry.nextCF = cf
        end

        if not entry.sending and (now - entry.lastSent >= RATE_LIMIT) then
            entry.sending = true
            entry.lastSent = now
            local toSend = entry.nextCF
            entry.nextCF = nil
            task.spawn(function()
                pcall(function() scf:InvokeServer(toSend) end)
                entry.sending = false
                if fusionActive and entry.nextCF and (tick() - entry.lastSent >= RATE_LIMIT) then
                    entry.sending = true
                    entry.lastSent = tick()
                    local nextSend = entry.nextCF
                    entry.nextCF = nil
                    task.spawn(function()
                        pcall(function() scf:InvokeServer(nextSend) end)
                        entry.sending = false
                    end)
                end
            end)
        end
    end

    local function applyThemeToPart(prop, cpc, color)
        if prop then
            pcall(function()
                for _, p in ipairs(prop:GetDescendants()) do
                    if p:IsA("BasePart") then
                        p.Color = color
                    end
                end
            end)
        end
        if cpc then
            task.spawn(function()
                pcall(function() cpc:InvokeServer(color) end)
            end)
        end
    end

    local function applyFusionTheme(themeName)
        fusionColorTheme = themeName
        if not fusionActive or #fusionPartsList == 0 then return end

        if themeName == "Default" then
            for _, entry in ipairs(fusionPartsList) do
                local col = (entry.name == "UpperTorso" or entry.name == "LowerTorso")
                    and Color3.fromRGB(115, 120, 130)
                    or Color3.fromRGB(145, 150, 160)
                applyThemeToPart(entry.prop, entry.cpc, col)
            end
            fNotif("Fusion Titan", "Theme: Default", 2)
            return
        elseif themeName == "Rainbow" then
            fNotif("Fusion Titan", "Theme: Rainbow", 2)
            return
        elseif themeName == "Cyberpunk" then
            for i, entry in ipairs(fusionPartsList) do
                local col = (i % 2 == 0) and Color3.fromRGB(0, 235, 255) or Color3.fromRGB(255, 30, 150)
                applyThemeToPart(entry.prop, entry.cpc, col)
            end
            fNotif("Fusion Titan", "Theme: Cyberpunk", 2)
            return
        end

        local solidCol = FUSION_THEMES[themeName] or Color3.fromRGB(145, 150, 160)
        for _, entry in ipairs(fusionPartsList) do
            applyThemeToPart(entry.prop, entry.cpc, solidCol)
        end
        fNotif("Fusion Titan", "Theme: " .. themeName, 2)
    end

    local function stopFusionTitan()
        if not fusionActive then return end
        fusionActive = false
        if fusionLoop then
            fusionLoop:Disconnect()
            fusionLoop = nil
        end
        currentFusionOrigin = nil
        senders = {}
        fusionPartsList = {}

        local char = lp.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum then
            hum.WalkSpeed = savedWalkSpeed or 16
            if savedJumpPower then hum.JumpPower = savedJumpPower end
            if savedUseJumpPower ~= nil then hum.UseJumpPower = savedUseJumpPower end
            pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true) end)
            for _, track in ipairs(hum:GetPlayingAnimationTracks()) do
                if track.Priority == Enum.AnimationPriority.Action4 or track.Name:lower():find("run") then
                    pcall(function() track:Stop(0.1) end)
                end
            end
            pcall(function() hum:ChangeState(Enum.HumanoidStateType.Landed) end)
        end

        smoothClimbTo(savedHipHeight or 2.0, 4.0)
        setCharacterHidden(false)

        task.wait(0.15)
        local clearTools = rep:WaitForChild("RE"):WaitForChild("1Clea1rTool1s")
        pcall(function() clearTools:FireServer("ClearAllProps") end)
        task.wait(0.3)
        pcall(function() clearTools:FireServer("ClearAllProps") end)
        fNotif("Fusion Titan", "Mega Fusion Titan dismantled.", 2)
    end

    local function spawnFusionTitan()
        if fusionActive then stopFusionTitan() task.wait(0.5) end
        fusionActive = true
        local char = lp.Character or lp.CharacterAdded:Wait()
        local hrp = char:WaitForChild("HumanoidRootPart")
        local hum = char:WaitForChild("Humanoid")

        savedHipHeight = hum.HipHeight
        savedWalkSpeed = hum.WalkSpeed
        savedJumpPower = hum.JumpPower
        savedUseJumpPower = hum.UseJumpPower
        hum.WalkSpeed = fusionConfig.walkSpeed
        hum.UseJumpPower = true
        hum.JumpPower = 110
        pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true) end)
        fNotif("Fusion Titan", "Forging Mega Fusion Chimera (Robot 4)...", 4)

        local clearTools = rep:WaitForChild("RE"):WaitForChild("1Clea1rTool1s")
        local toolRE = rep:WaitForChild("RE"):WaitForChild("1Too1l")
        pcall(function() clearTools:FireServer("ClearAllProps") end)
        task.wait(0.5)

        local propsTool = _0xH_3f2()
        if not propsTool then fNotif("Fusion Titan", "PropMaker missing!", 3) return end

        pcall(function() clearTools:FireServer("OpenPropMenu") end)
        task.wait(0.2)

        local wc = workspace:FindFirstChild("WorkspaceCom")
        if not wc then fNotif("Fusion Titan", "WorkspaceCom missing!", 3) return end

        local bunkerTarget  = hrp.Position + (hrp.CFrame.LookVector * 14)
        local toiletTarget  = hrp.Position + (hrp.CFrame.RightVector * 10)
        local genTarget     = hrp.Position - (hrp.CFrame.RightVector * 10)
        local turbineTarget = hrp.Position - (hrp.CFrame.LookVector * 12)

        local Telemetry = rep:FindFirstChild("Remotes") and rep.Remotes:FindFirstChild("TelemetryClientInteraction")
        local existingProps = {}
        for _, folder in pairs(wc:GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName then
                    existingProps[prop] = true
                end
            end
        end

        local function spawnSingleProp(propName, categoryName, targetPos)
            local tool = _0xH_3f2()
            if not tool then return nil end

            if Telemetry then
                pcall(function() Telemetry:FireServer("filterClick", {name = categoryName, itemType = "Props"}) end)
                task.wait(0.05)
                pcall(function() Telemetry:FireServer("filterClick", {name = propName, itemType = "Props"}) end)
                task.wait(0.05)
            end

            pcall(function() clearTools:FireServer("RequestingPropName", propName, categoryName) end)
            task.wait(0.3)

            local currentHum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
            if currentHum and tool.Parent ~= lp.Character then
                currentHum:EquipTool(tool)
                task.wait(0.1)
            end

            local tpm = tool:FindFirstChild("Tool_PropMake")
            local startW = tick()
            while not tpm and tick() - startW < 4.0 and fusionActive do
                tpm = tool:FindFirstChild("Tool_PropMake")
                if not tpm then
                    local bp = lp.Backpack:FindFirstChild("PropMaker")
                    if bp then tpm = bp:FindFirstChild("Tool_PropMake") end
                end
                if not tpm then task.wait(0.1) end
            end

            if not tpm then return nil end

            pcall(function() tpm:FireServer(workspace.Terrain, targetPos) end)

            local spawned = nil
            local t0 = tick()
            while tick() - t0 < 4.0 and fusionActive do
                for _, folder in pairs(wc:GetChildren()) do
                    for _, prop in pairs(folder:GetChildren()) do
                        if prop.Name == myPropName and not existingProps[prop] then
                            spawned = prop
                            existingProps[prop] = true
                            break
                        end
                    end
                    if spawned then break end
                end
                if spawned then break end
                task.wait(0.05)
            end

            return spawned
        end

        
        local chestProp = spawnSingleProp("BigGunBunker", "Big", bunkerTarget)
        if not chestProp then chestProp = spawnSingleProp("BigGunBunker", "Big", bunkerTarget) end
        if not chestProp then fNotif("Fusion Titan", "Chest prop failed!", 3) return end

        
        local firstToilet = spawnSingleProp("BigOutToilet", "Building", toiletTarget)
        if not firstToilet then firstToilet = spawnSingleProp("BigOutToilet", "Building", toiletTarget) end
        if not firstToilet then fNotif("Fusion Titan", "Toilet prop failed!", 3) return end
        _0xH_3f3(firstToilet, 3)
        task.wait(0.2)

        local toiletProps = { firstToilet }
        for _, folder in pairs(wc:GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName and not existingProps[prop] then
                    existingProps[prop] = true
                    table.insert(toiletProps, prop)
                end
            end
        end

        
        local firstGen = spawnSingleProp("BigGenerator", "Building", genTarget)
        if not firstGen then firstGen = spawnSingleProp("BigGenerator", "Building", genTarget) end
        if not firstGen then fNotif("Fusion Titan", "Generator prop failed!", 3) return end
        _0xH_3f3(firstGen, 3)
        task.wait(0.2)

        local genProps = { firstGen }
        for _, folder in pairs(wc:GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName and not existingProps[prop] then
                    existingProps[prop] = true
                    table.insert(genProps, prop)
                end
            end
        end

        
        local firstTurbine = spawnSingleProp("PowerTurbine", "Barrel", turbineTarget)
        if not firstTurbine then firstTurbine = spawnSingleProp("PowerTurbine", "001_TrafficCones", turbineTarget) end
        if not firstTurbine then firstTurbine = spawnSingleProp("PowerTurbine", "Barrel", turbineTarget) end
        if not firstTurbine then fNotif("Fusion Titan", "Turbine prop failed!", 3) return end
        _0xH_3f3(firstTurbine, 5)
        task.wait(0.8)

        local turbineProps = { firstTurbine }
        for _, folder in pairs(wc:GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName and not existingProps[prop] then
                    existingProps[prop] = true
                    table.insert(turbineProps, prop)
                end
            end
        end

                                                     
        task.wait(1.0)
        pcall(function() toolRE:InvokeServer("PickingTools", "PropMaker") end)
        pcall(function() clearTools:FireServer("ClosePropMenu") end)

        local function getPropRemotes(p)
            if not p then return nil, nil end
            local scf = p:FindFirstChild("SetCurrentCFrame") or p:FindFirstChild("SetCurrentCFrame", true) or p:FindFirstChildWhichIsA("RemoteFunction", true)
            local cpc = p:FindFirstChild("ChangePropColor") or p:FindFirstChild("ChangePropColor", true)
            return scf, cpc
        end

        local cScf, cCpc = getPropRemotes(chestProp)
        local t1Scf, t1Cpc = getPropRemotes(toiletProps[1])
        local t2Scf, t2Cpc = getPropRemotes(toiletProps[2])
        local t3Scf, t3Cpc = getPropRemotes(toiletProps[3])
        local t4Scf, t4Cpc = getPropRemotes(toiletProps[4])

        local g1Scf, g1Cpc = getPropRemotes(genProps[1])
        local g2Scf, g2Cpc = getPropRemotes(genProps[2])
        local g3Scf, g3Cpc = getPropRemotes(genProps[3])
        local g4Scf, g4Cpc = getPropRemotes(genProps[4])

        local tb1Scf, tb1Cpc = getPropRemotes(turbineProps[1])
        local tb2Scf, tb2Cpc = getPropRemotes(turbineProps[2])
        local tb3Scf, tb3Cpc = getPropRemotes(turbineProps[3])
        local tb4Scf, tb4Cpc = getPropRemotes(turbineProps[4])
        local tb5Scf, tb5Cpc = getPropRemotes(turbineProps[5])
        local tb6Scf, tb6Cpc = getPropRemotes(turbineProps[6])

        if not cScf then fNotif("Fusion Titan", "Chest SCF missing!", 3) return end

        task.wait(0.3)
        smoothClimbTo(fusionConfig.playerLift, 2.0)
        setCharacterHidden(true)

        
        
        
        
        
        
        
        
        
        
        local FUSION_PARTS = {
            { name = "UpperTorso",   scf = cScf,   prop = chestProp,       cpc = cCpc,   offset = CFrame.new(1.0, -2.0, -3.0) * CFrame.Angles(math.rad(90), 0, 0) },
            { name = "LowerTorso",   scf = t1Scf,  prop = toiletProps[1],  cpc = t1Cpc,  offset = CFrame.new(-2.0, -3.5, -1.0) * CFrame.Angles(0, math.rad(85), 0) },
            { name = "Head",         scf = tb1Scf, prop = turbineProps[1], cpc = tb1Cpc, offset = CFrame.new(0, 1.8, 0) * CFrame.Angles(0, math.rad(90), math.rad(90)) },

            
            { name = "LeftUpperArm", scf = g1Scf,  prop = genProps[1],     cpc = g1Cpc,  offset = CFrame.new(0, 0.5, 0) * CFrame.Angles(0, math.rad(33), 0) },
            { name = "LeftLowerArm", scf = tb2Scf, prop = turbineProps[2], cpc = tb2Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
            { name = "LeftHand",     scf = t2Scf,  prop = toiletProps[2],  cpc = t2Cpc,  offset = CFrame.new(0, -1.0, 0) * CFrame.Angles(math.rad(180), 0, 0) },

            
            { name = "RightUpperArm",scf = g2Scf,  prop = genProps[2],     cpc = g2Cpc,  offset = CFrame.new(0, 0.5, 0) * CFrame.Angles(0, math.rad(-33), 0) },
            { name = "RightLowerArm",scf = tb3Scf, prop = turbineProps[3], cpc = tb3Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
            { name = "RightHand",    scf = tb4Scf, prop = turbineProps[4], cpc = tb4Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },

            
            { name = "LeftUpperLeg", scf = g3Scf,  prop = genProps[3],     cpc = g3Cpc,  offset = CFrame.Angles(0, math.rad(33), 0) },
            { name = "LeftLowerLeg", scf = tb5Scf, prop = turbineProps[5], cpc = tb5Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
            { name = "LeftFoot",     scf = t3Scf,  prop = toiletProps[3],  cpc = t3Cpc,  offset = CFrame.new(0, -0.5, 0) * CFrame.Angles(0, math.rad(90), 0) },

            
            { name = "RightUpperLeg",scf = g4Scf,  prop = genProps[4],     cpc = g4Cpc,  offset = CFrame.Angles(0, math.rad(-33), 0) },
            { name = "RightLowerLeg",scf = tb6Scf, prop = turbineProps[6], cpc = tb6Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
            { name = "RightFoot",    scf = t4Scf,  prop = toiletProps[4],  cpc = t4Cpc,  offset = CFrame.new(0, -0.5, 0) * CFrame.Angles(0, math.rad(-90), 0) },
        }
        fusionPartsList = FUSION_PARTS

        applyFusionTheme(fusionColorTheme)
        fNotif("Fusion Titan", "Omega Chimera Titan 100% Online!", 3)

        if fusionLoop then fusionLoop:Disconnect() fusionLoop = nil end
        local rayParams = RaycastParams.new()
        rayParams.FilterType = Enum.RaycastFilterType.Exclude

        fusionLoop = rs.RenderStepped:Connect(function()
            if not fusionActive then return end

            local cc = lp.Character
            if not cc then return end
            local hrpNow = cc:FindFirstChild("HumanoidRootPart")
            if not hrpNow then return end
            local humNow = cc:FindFirstChildOfClass("Humanoid")

            local rayFilter = {cc, workspace:FindFirstChild("WorkspaceCom")}
            for _, plr in ipairs(game:GetService("Players"):GetPlayers()) do
                if plr.Character and plr.Character ~= cc then
                    table.insert(rayFilter, plr.Character)
                end
            end
            rayParams.FilterDescendantsInstances = rayFilter
            local ray = workspace:Raycast(hrpNow.Position + Vector3.new(0, 10, 0), Vector3.new(0, -250, 0), rayParams)
            local groundY = ray and ray.Position.Y
            local minFloorY = groundY and (groundY + currentHipHeightVal) or nil

            if minFloorY and hrpNow.Position.Y < minFloorY then
                local vel = hrpNow.AssemblyLinearVelocity
                if vel.Y < 0 then
                    hrpNow.AssemblyLinearVelocity = Vector3.new(vel.X, 0, vel.Z)
                end
                hrpNow.CFrame = CFrame.new(hrpNow.Position.X, minFloorY, hrpNow.Position.Z) * hrpNow.CFrame.Rotation
                if humNow and humNow:GetState() == Enum.HumanoidStateType.Freefall then
                    pcall(function() humNow:ChangeState(Enum.HumanoidStateType.Landed) end)
                end
            end

            local clampedY = hrpNow.Position.Y
            if minFloorY and clampedY < minFloorY then
                clampedY = minFloorY
            end
            local clampedHrpCF = CFrame.new(hrpNow.Position.X, clampedY, hrpNow.Position.Z) * hrpNow.CFrame.Rotation
            local targetCenterCF = clampedHrpCF * CFrame.new(fusionConfig.posX, fusionConfig.height, fusionConfig.posZ) * CFrame.Angles(0, math.rad(fusionConfig.rotY), 0)
            if not currentFusionOrigin then
                currentFusionOrigin = targetCenterCF
            else
                currentFusionOrigin = currentFusionOrigin:Lerp(targetCenterCF, 0.22)
            end
            local centerCF = currentFusionOrigin

            local REF_WIDTH = 0.7000001072883606
            local REF_HEIGHT = 1.0499999523162842
            local REF_DEPTH = 0.8500000834465027

            local curDepth = REF_DEPTH
            local curHeight = REF_HEIGHT
            local curWidth = REF_WIDTH
            if humNow then
                local dVal = humNow:FindFirstChild("BodyDepthScale")
                if dVal and dVal:IsA("NumberValue") and dVal.Value > 0.001 then curDepth = dVal.Value end
                local hVal = humNow:FindFirstChild("BodyHeightScale")
                if hVal and hVal:IsA("NumberValue") and hVal.Value > 0.001 then curHeight = hVal.Value end
                local wVal = humNow:FindFirstChild("BodyWidthScale")
                if wVal and wVal:IsA("NumberValue") and wVal.Value > 0.001 then curWidth = wVal.Value end
            end

            local normX = curWidth / REF_WIDTH
            local normY = curHeight / REF_HEIGHT
            local normZ = curDepth / REF_DEPTH
            if math.abs(normX) < 0.001 then normX = 1 end
            if math.abs(normY) < 0.001 then normY = 1 end
            if math.abs(normZ) < 0.001 then normZ = 1 end

            for _, entry in ipairs(FUSION_PARTS) do
                if entry.scf then
                    local part = cc:FindFirstChild(entry.name)
                    if not part and entry.name == "UpperTorso" then
                        part = cc:FindFirstChild("Torso") or hrpNow
                    end
                    if part then
                        local rel = clampedHrpCF:ToObjectSpace(part.CFrame)

                        local xMult = 1.0
                        if entry.name:find("Arm") or entry.name:find("Hand") then
                            xMult = fusionConfig.armWidth
                        elseif entry.name:find("Leg") or entry.name:find("Foot") then
                            xMult = fusionConfig.legWidth
                        end

                        local unscaledX = rel.Position.X / normX
                        local unscaledY = rel.Position.Y / normY
                        local unscaledZ = rel.Position.Z / normZ

                        local scaledPos = Vector3.new(unscaledX * fusionConfig.size * xMult, unscaledY * fusionConfig.size, unscaledZ * fusionConfig.size)

                        if entry.name:find("LowerArm") then
                            scaledPos = scaledPos + Vector3.new(0, -fusionConfig.armSpacing, 0)
                        elseif entry.name:find("Hand") then
                            scaledPos = scaledPos + Vector3.new(0, -fusionConfig.armSpacing * 2, 0)
                        end

                        if entry.name:find("Leg") or entry.name:find("Foot") then
                            scaledPos = scaledPos + Vector3.new(0, fusionConfig.legOffsetY, 0)
                            if entry.name:find("LowerLeg") then
                                scaledPos = scaledPos + Vector3.new(0, fusionConfig.legSpacing, 0)
                            elseif entry.name:find("UpperLeg") then
                                scaledPos = scaledPos + Vector3.new(0, fusionConfig.legSpacing * 2, 0)
                            end
                        end

                        local relRot = rel - rel.Position

                        local extraOffset = entry.offset or CFrame.new()
                        if entry.name == "UpperTorso" then
                            extraOffset = CFrame.new(fusionConfig.torsoOffsetX, fusionConfig.torsoOffsetY, fusionConfig.torsoOffsetZ)
                                * CFrame.Angles(math.rad(fusionConfig.torsoRotX), math.rad(fusionConfig.torsoRotY), math.rad(fusionConfig.torsoRotZ))
                        elseif entry.name == "LowerTorso" then
                            extraOffset = (entry.offset or CFrame.new())
                                * CFrame.new(fusionConfig.pelvisOffsetX, fusionConfig.pelvisOffsetY, fusionConfig.pelvisOffsetZ)
                                * CFrame.Angles(math.rad(fusionConfig.pelvisRotX), math.rad(fusionConfig.pelvisRotY), math.rad(fusionConfig.pelvisRotZ))
                        end

                        local targetCF = centerCF * CFrame.new(scaledPos) * relRot * extraOffset

                        sendCF(entry.scf, targetCF, entry.prop)
                    end
                end
            end

            
            if humNow and humNow.MoveDirection.Magnitude > 0.05 then
                if humNow:GetState() ~= Enum.HumanoidStateType.Running then
                    pcall(function() humNow:ChangeState(Enum.HumanoidStateType.Running) end)
                end
                if humNow.WalkSpeed < fusionConfig.walkSpeed then
                    humNow.WalkSpeed = fusionConfig.walkSpeed
                end

                local hasRun = false
                for _, track in ipairs(humNow:GetPlayingAnimationTracks()) do
                    local animName = track.Name:lower()
                    if animName:find("idle") or animName:find("walk") then
                        track:Stop(0.05)
                    elseif animName:find("run") and track.Priority == Enum.AnimationPriority.Action4 then
                        hasRun = true
                        track:AdjustSpeed(fusionConfig.animSpeed)
                    end
                end

                if not hasRun then
                    local animScript = cc:FindFirstChild("Animate")
                    local runAnim = animScript and animScript:FindFirstChild("run") and animScript.run:FindFirstChildOfClass("Animation")
                    if runAnim then
                        pcall(function()
                            local runTrack = humNow:LoadAnimation(runAnim)
                            runTrack.Priority = Enum.AnimationPriority.Action4
                            runTrack:Play(0.05)
                            runTrack:AdjustSpeed(fusionConfig.animSpeed)
                        end)
                    end
                end
            else
                
                for _, track in ipairs(humNow:GetPlayingAnimationTracks()) do
                    local animName = track.Name:lower()
                    if animName:find("run") and track.Priority == Enum.AnimationPriority.Action4 then
                        track:Stop(0.1)
                    end
                end
            end

            
            if humNow and humNow.HipHeight ~= fusionConfig.playerLift and currentHipHeightVal >= fusionConfig.playerLift then
                humNow.HipHeight = fusionConfig.playerLift
            end

            
            if fusionColorTheme == "Rainbow" then
                local nowTick = tick()
                for i, entry in ipairs(FUSION_PARTS) do
                    local waveColor = Color3.fromHSV((nowTick * 0.4 + (i / #FUSION_PARTS)) % 1, 1, 1)

                    if entry.prop then
                        pcall(function()
                            for _, p in ipairs(entry.prop:GetDescendants()) do
                                if p:IsA("BasePart") then
                                    p.Color = waveColor
                                end
                            end
                        end)
                    end

                    if entry.cpc and (nowTick - (entry.lastColorSent or 0) >= 0.25) then
                        entry.lastColorSent = nowTick
                        task.spawn(function()
                            pcall(function() entry.cpc:InvokeServer(waveColor) end)
                        end)
                    end
                end
            end
        end)
    end

    
    
    
    BuildV2Tab:AddSection({"> Hybrid Titan (Robot 4)"})

    BuildV2Tab:AddToggle({
        Name = "Spawn Hybrid Titan",
        Description = "Pilot a 15-prop hybrid mech fusing Bunker, Toilet, Generator & Turbines",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            if not val and not fusionActive then return end
            if val then
                task.spawn(spawnFusionTitan)
            else
                stopFusionTitan()
            end
        end
    })

    BuildV2Tab:AddDropdown({
        Name = "Fusion Titan Color Theme",
        Description = "Select fusion robot color or animated wave",
        Options = {
            "Default",
            "Rainbow",
            "Cyberpunk",
            "Obsidian",
            "Gold",
            "Crimson",
            "Violet",
            "Acid",
            "Ice",
            "Magma"
        },
        Default = "Default",
        Callback = function(choice)
            applyFusionTheme(choice)
        end
    })
end

do
    local lp = game:GetService("Players").LocalPlayer
    local rs = game:GetService("RunService")
    local rep = game:GetService("ReplicatedStorage")

    local apexActive = false
    local apexLoop = nil
    local myPropName = "Prop" .. lp.Name

    local savedHipHeight = 2.0
    local savedWalkSpeed = 16
    local savedJumpPower = 50
    local savedUseJumpPower = false
    local currentHipHeightVal = 62.0
    local savedTransparencies = {}
    local apexColorTheme = "Default"

    local apexPartsList = {}
    local currentApexOrigin = nil

    local apexConfig = {
        size = 11.0,
        height = 1.0,
        playerLift = 62.0,
        posZ = 0.0,
        posX = 0.0,
        rotY = 0.0,
        walkSpeed = 44.0,
        animSpeed = 0.90,
        torsoRotX = 90.0,
        torsoRotY = 0.0,
        torsoRotZ = 0.0,
        torsoOffsetX = 1.0,
        torsoOffsetY = -2.0,
        torsoOffsetZ = -3.0,
        armWidth = 1.03,
        armSpacing = 5.45,
        legWidth = 0.74,
        legOffsetY = 0.0,
        legSpacing = 0.0,
        pelvisOffsetX = -2.00,
        pelvisOffsetY = -3.50,
        pelvisOffsetZ = -1.00,
        pelvisRotX = 0.00,
        pelvisRotY = 85.00,
        pelvisRotZ = 0.00,
    }

    local APEX_THEMES = {
        ["Default"]        = Color3.fromRGB(140, 150, 165),
        ["Cyber Neon"]     = Color3.fromRGB(0, 240, 255),
        ["Solar Flare"]    = Color3.fromRGB(255, 215, 0),
        ["Abyssal Void"]   = Color3.fromRGB(18, 18, 22),
        ["Toxic Hazard"]   = Color3.fromRGB(57, 255, 20),
