            { name = "Head",         scf = tb1Scf, prop = turbineProps[1], cpc = tb1Cpc, offset = CFrame.new(0, 1.5, 0) * CFrame.Angles(math.rad(-90), 0, 0) },
            { name = "LowerTorso",   scf = tb2Scf, prop = turbineProps[2], cpc = tb2Cpc, offset = CFrame.Angles(0, 0, math.rad(90)) },

            
            { name = "LeftUpperArm", scf = bd2Scf, prop = bedProps[2],     cpc = bd2Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
            { name = "LeftLowerArm", scf = bk1Scf, prop = bunkerProps[1],  cpc = bk1Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
            { name = "LeftHand",     scf = bd4Scf, prop = bedProps[4],     cpc = bd4Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },

            
            { name = "RightUpperArm",scf = bd3Scf, prop = bedProps[3],     cpc = bd3Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
            { name = "RightLowerArm",scf = bk2Scf, prop = bunkerProps[2],  cpc = bk2Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
            { name = "RightHand",    scf = tb3Scf, prop = turbineProps[3], cpc = tb3Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },

            
            { name = "LeftUpperLeg", scf = tb4Scf, prop = turbineProps[4], cpc = tb4Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
            { name = "LeftLowerLeg", scf = bk3Scf, prop = bunkerProps[3],  cpc = bk3Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
            { name = "LeftFoot",     scf = tb6Scf, prop = turbineProps[6], cpc = tb6Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },

            
            { name = "RightUpperLeg",scf = tb5Scf, prop = turbineProps[5], cpc = tb5Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
            { name = "RightLowerLeg",scf = bk4Scf, prop = bunkerProps[4],  cpc = bk4Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
