local function getOrEquipVIPPropMaker()
    local lp = game:GetService("Players").LocalPlayer
    local char = lp.Character or lp.CharacterAdded:Wait()
    local pm = char:FindFirstChild("PropMaker")
    if pm then return pm end
    pm = lp.Backpack:FindFirstChild("PropMaker")
    if not pm then
        local RE = game:GetService("ReplicatedStorage"):FindFirstChild("RE")
        local toolRemote = RE and RE:FindFirstChild("1Too1l")
        if toolRemote then
            pcall(function() toolRemote:InvokeServer("PickingTools", "PropMaker") end)
            task.wait(0.2)
        end
        pm = lp.Backpack:FindFirstChild("PropMaker") or char:FindFirstChild("PropMaker")
    end
    if pm and pm.Parent ~= char then
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then hum:EquipTool(pm) end
        task.wait(0.15)
    end
    return char:FindFirstChild("PropMaker") or pm
end

local function vipNotify(title, text)
    pcall(function()
        game:GetService("StarterGui"):SetCore("SendNotification", {
            Title = title,
            Text = text,
            Duration = 3
        })
    end)
end

