    Description = "Spawns the VIP prop directly where you are standing",
    Callback = function()
        task.spawn(function()
            local lp = game:GetService("Players").LocalPlayer
            local char = lp.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if not hrp then
                vipNotify("Prop Unlocker", "Character not found!")
                return
            end

            local pm = getOrEquipVIPPropMaker()
            if not pm then
                vipNotify("Prop Unlocker", "Failed to get PropMaker!")
                return
            end

            local RE = game:GetService("ReplicatedStorage"):FindFirstChild("RE")
            local clearRemote = RE and RE:FindFirstChild("1Clea1rTool1s")
            local toolRemote = RE and RE:FindFirstChild("1Too1l")
            if not clearRemote then return end

            pcall(function() clearRemote:FireServer("OpenPropMenu") end)
            pcall(function() clearRemote:FireServer("RequestingPropName", selectedVIPPropId, "Car", "Gamepass") end)

            local toolPropMake = pm:FindFirstChild("Tool_PropMake") or (lp.Backpack:FindFirstChild("PropMaker") and lp.Backpack.PropMaker:FindFirstChild("Tool_PropMake"))
            if not toolPropMake then
                local ws = tick()
                while not toolPropMake and tick() - ws < 1.5 do
                    task.wait(0.05)
                    toolPropMake = pm:FindFirstChild("Tool_PropMake") or (lp.Backpack:FindFirstChild("PropMaker") and lp.Backpack.PropMaker:FindFirstChild("Tool_PropMake"))
                end
            end

            if not toolPropMake then
                vipNotify("Prop Unlocker", "Tool_PropMake not ready!")
                return
            end

            local forwardPos = hrp.Position + (hrp.CFrame.LookVector * 6)
            local rayParams = RaycastParams.new()
            rayParams.FilterDescendantsInstances = {char}
            rayParams.FilterType = Enum.RaycastFilterType.Exclude

            local gRay = workspace:Raycast(forwardPos + Vector3.new(0, 5, 0), Vector3.new(0, -20, 0), rayParams)
            local hitInst = gRay and gRay.Instance or workspace.Terrain
            local groundPos = gRay and gRay.Position or Vector3.new(forwardPos.X, hrp.Position.Y - 2.5, forwardPos.Z)

            pcall(function() toolPropMake:FireServer(hitInst, groundPos) end)
            vipNotify("Prop Unlocker", "Spawned: " .. selectedVIPPropName .. "!")

            task.spawn(function()
                task.wait(1)
                if toolRemote then pcall(function() toolRemote:InvokeServer("PickingTools", "PropMaker") end) end
                pcall(function() clearRemote:FireServer("ClosePropMenu") end)
            end)
        end)
    end
})

