local MUSIC_SELECTED = ""
local MUSIC_CUSTOM_ID = ""
local MUSIC_NAMES = {}
local MUSIC_ID_MAP = {}
for _, mus in ipairs(MUSIC_PRESET_LIST) do
    table.insert(MUSIC_NAMES, mus.Name)
    MUSIC_ID_MAP[mus.Name] = tostring(mus.Id)
end
if MUSIC_NAMES[1] then MUSIC_SELECTED = MUSIC_ID_MAP[MUSIC_NAMES[1]] or "" end

local function musicForcePlay(id)
    if not musicVehicleRemote or id == "" then return end
    pcall(function() musicVehicleRemote:FireServer("PickingScooterMusicText", id, nil, true) end)
    pcall(function() musicVehicleRemote:FireServer("PickingScooterMusicText", id) end)
    pcall(function() musicVehicleRemote:FireServer("PickingScooterMusicText", tonumber(id), nil, true) end)
end

local function musicStop()
    if musicVehicleRemote then pcall(function() musicVehicleRemote:FireServer("Delete NoMotorVehicle") end) end
    task.spawn(function()
        task.wait(0.1)
        if musicClearRemote then pcall(function() musicClearRemote:FireServer("ClearAllTools") end) end
    end)
end

local function musicPlay(id)
    if not musicVehicleRemote or id == "" then return end
    task.spawn(function()
        pcall(function() musicVehicleRemote:FireServer("Delete NoMotorVehicle") end)
        task.wait(0.1)
        if musicClearRemote then pcall(function() musicClearRemote:FireServer("ClearAllTools") end) end
        task.wait(0.15)
        pcall(function() musicVehicleRemote:FireServer("SkateBoard") end)
        task.wait(1.0)
        musicForcePlay(id)
    end)
end

