local function startSkateRGB()
    if skateRGBOn then return end
    skateRGBOn = true
    task.spawn(function()
        local RE = game:GetService("ReplicatedStorage"):FindFirstChild("RE")
        local CarRemote = RE and RE:FindFirstChild("1Player1sCa1r")
        while skateRGBOn do
            local c = Color3.fromHSV(tick() % 5 / 5, 1, 1)
            if CarRemote then
                pcall(function() CarRemote:FireServer("NoMotorColor", c) end)
            end
            pcall(function()
                game.Players.LocalPlayer.PlayerGui.MainGUIHandler
                    .NoMotorVehicleControl.NoMotorColorPicks.SetColor:FireServer(c)
            end)
            task.wait(0.1)
        end
    end)
end

