local toggleshots = false
local function playFENote(noteId)
    pcall(function()
        local player = game:GetService("Players").LocalPlayer
        local char = player.Character
        if not char then return end
        local tool = char:FindFirstChild("Assault")
        if not tool then return end
        local handle = tool:FindFirstChild("Handle")
        if not handle then return end
        local rs = game:GetService("ReplicatedStorage")
        local ws = workspace
        toggleshots = not toggleshots
        if toggleshots then
            local a = {
                ws:WaitForChild("Model", 9e9):GetChildren()[154]:GetChildren()[45],
                handle,
                Vector3.new(0.2, 0.3, -2.5),
                Vector3.new(16.8228, 0.025, -43.4795),
                tool:WaitForChild("GunScript_Local", 9e9):WaitForChild("MuzzleEffect", 9e9),
                tool:WaitForChild("GunScript_Local", 9e9):WaitForChild("HitEffect", 9e9),
                noteId, noteId,
                { false },
                { 25, Vector3.new(0.25, 0.25, 100), BrickColor.new("Bright yellow"), 0.25, Enum.Material.SmoothPlastic, 0.25 },
                true, false
            }
            rs:WaitForChild("RE", 9e9):WaitForChild("1Gu1n", 9e9):FireServer(unpack(a))
        else
            local args = {
                handle,
                noteId,
                1
            }
            rs:WaitForChild("RE", 9e9):WaitForChild("1Gu1nSound1s", 9e9):FireServer(unpack(args))
        end
    end)
end

local function playNote(note)
    local id = PianoNotes[note]
    if not id then return end
    local snd = Instance.new("Sound", workspace)
    snd.SoundId = "rbxassetid://" .. id
    snd.Volume = 1
    snd:Play()
    game:GetService("Debris"):AddItem(snd, 3)
    playFENote(id)
end

local function playSheet(sheet, tempo)
    local beat = 60 / ((tempo or 200) * 4)
    local i = 1
    local myID = pianoPlayID
    while i <= #sheet and pianoPlaying and pianoPlayID == myID do
        local c = sheet:sub(i, i)
        if c == "[" then
            local close = sheet:find("]", i, true)
            if close then
                local group = sheet:sub(i+1, close-1)
                for ch in group:gmatch(".") do
                    if pianoPlayID ~= myID then break end
                    local note = KeysToNotes[ch]
                    if note then playNote(note) end
                    task.wait(0.05)
                end
                task.wait(beat)
                i = close
            end
        elseif c == " " or c == "\n" or c == "\r" then
            task.wait(beat)
        elseif c == "-" then
            task.wait(beat * 0.5)
        else
            local note = KeysToNotes[c]
            if note then playNote(note) end
            task.wait(beat)
        end
        i = i + 1
    end
    pianoPlaying = false
end

local function equipAssault()
    pcall(function()
        local RE = game:GetService("ReplicatedStorage"):FindFirstChild("RE")
        local toolRemote = RE and RE:FindFirstChild("1Too1l")
        if not toolRemote then return end
        toolRemote:InvokeServer("PickingTools", "Assault")
        local player = game:GetService("Players").LocalPlayer
        local backpack = player:WaitForChild("Backpack", 5)
        local assault
        for _ = 1, 20 do
            assault = backpack:FindFirstChild("Assault")
            if assault then break end
            task.wait(0.15)
        end
        if assault and player.Character then
            assault.Parent = player.Character
            task.wait(0.3)
        end
    end)
end

