local globalMemeNames = {}
local globalMemeMap = {}
for _, v in ipairs(globalMemeSounds) do
    table.insert(globalMemeNames, v.name)
    globalMemeMap[v.name] = v.id
end

local selectedGlobalSound = globalMemeSounds[1].id
local globalLoopRunning = false

local function playSoundGlobally(soundId)
    if not soundId or soundId == "" then return end
    local Players = game:GetService("Players")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local remote = ReplicatedStorage:FindFirstChild("RE")
    local gunRemote = remote and remote:FindFirstChild("1Gu1n")
    if not gunRemote then return end

    for _, player in ipairs(Players:GetPlayers()) do
        if player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
            local hrp = player.Character.HumanoidRootPart
            local args = {
                [1] = hrp,
                [2] = hrp,
                [3] = Vector3.new(0, -1, 0),
                [4] = Vector3.new(0, 0, 0),
                [5] = hrp,
                [6] = hrp,
                [7] = tostring(soundId),
                [8] = tostring(soundId),
                [9] = { [1] = true },
                [10] = {
                    [1] = 25,
                    [2] = Vector3.new(0.25, 0.25, 100),
                    [3] = BrickColor.new(24),
                    [4] = 0.25,
                    [5] = Enum.Material.SmoothPlastic,
                    [6] = 0.25
                },
                [11] = true,
                [12] = false
            }
            pcall(function()
                gunRemote:FireServer(unpack(args))
            end)
        end
    end
end

local function playLocalSoundPreview(soundId)
    pcall(function()
        local s = Instance.new("Sound")
        s.SoundId = "rbxassetid://" .. tostring(soundId)
        s.Volume = 3
        s.Looped = false
        s.Parent = workspace
        s:Play()
        task.delay(5, function()
            pcall(function() s:Destroy() end)
        end)
    end)
end

AudioTab:AddDropdown({
    Name = "Global Meme Sounds",
    Description = "Choose a sound to play globally",
    Default = globalMemeNames[1],
    Options = globalMemeNames,
    Callback = function(val)
