    Description = "Repeats the selected sound globally",
    Default = false,
    Callback = function(state)
        globalLoopRunning = state
        if globalLoopRunning then
            task.spawn(function()
                while globalLoopRunning do
                    if selectedGlobalSound then
                        playSoundGlobally(selectedGlobalSound)
                        playLocalSoundPreview(selectedGlobalSound)
                    end
                    task.wait(1)
                end
            end)
        end
    end
})
