local function scanVehicles()
    _G.FunVehicleData = {}
    _G.FunVehicleLabels = { "---" }
    _G.FunLabelToKey = {}
    local vehiclesFolder = workspace:FindFirstChild("Vehicles")
    if not vehiclesFolder then return end
    
    local playerNames = {}
    for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
        playerNames[string.lower(p.Name)] = true
        if p.DisplayName and p.DisplayName ~= "" then
            playerNames[string.lower(p.DisplayName)] = true
        end
    end
    for _, v in ipairs(vehiclesFolder:GetChildren()) do
        pcall(function()
            if not v:IsA("Model") then return end
            
            local seat = nil
            for _, d in ipairs(v:GetDescendants()) do
                if d:IsA("VehicleSeat") or d:IsA("Seat") then
                    seat = d
                    break
                end
            end
            if not seat then return end
            
            if string.find(string.lower(v.Name), "brookhaven", 1, true) then return end

            
            local ownerVal = v:FindFirstChild("Owner")
            local ownerName = nil
            if ownerVal then
                pcall(function()
                    if ownerVal:IsA("ObjectValue") and ownerVal.Value then
                        ownerName = ownerVal.Value.Name
                    elseif ownerVal.Value then
                        ownerName = tostring(ownerVal.Value)
                    end
                end)
            end
            
            local lowerName = string.lower(v.Name)
            if not ownerName or ownerName == "" or ownerName == "nil" then
                for pname, _ in pairs(playerNames) do
                    if string.find(lowerName, pname, 1, true) then
                        ownerName = pname
                        break
                    end
                end
            end

            
            local hasGuid = string.find(lowerName, "-%x+") ~= nil
            local hasChassis = v:FindFirstChild("Chassis") ~= nil
            local isPlayerNamed = false
            local ownerNameLower = ownerName and string.lower(ownerName) or ""
            if ownerNameLower ~= "" then
                if string.find(lowerName, ownerNameLower .. "car", 1, true) then
                    isPlayerNamed = true
                end
            end

            local ownerIsOnline = false
            if ownerName then
                ownerIsOnline = playerNames[string.lower(ownerName)] == true
            end
            local nameHasOnline = false
            for pname, _ in pairs(playerNames) do
                if string.find(lowerName, pname, 1, true) then
                    nameHasOnline = true
                    break
                end
            end

            local isPlayerVehicle = (hasGuid or isPlayerNamed or hasChassis) and (ownerIsOnline or nameHasOnline)
            if not isPlayerVehicle then return end

            
            local occupied = (seat.Occupant ~= nil)
            if occupied then return end

            
            local groundCheck = v.PrimaryPart or seat or v:FindFirstChildOfClass("BasePart")
            if groundCheck then
                if groundCheck.Position.Y < -50 then return end
                local rayParams = RaycastParams.new()
                rayParams.FilterType = Enum.RaycastFilterType.Exclude
                rayParams.FilterDescendantsInstances = { v }
                local rayOrigin = groundCheck.Position + Vector3.new(0, 1, 0)
                local rayDir = Vector3.new(0, -50, 0)
                local rayHit = workspace:Raycast(rayOrigin, rayDir, rayParams)
                if rayHit then
                    local distToGround = (groundCheck.Position.Y + 1 - rayHit.Position.Y)
                    if distToGround > 8 then return end
                end
            end

            local key = v.Name
            local cleanName = key:gsub("%-%-?%x+$", "")
            if cleanName == "" then cleanName = key end

            _G.FunVehicleData[key] = {
                model = v,
                seat = seat,
                occupied = false,
                ownerName = ownerName,
                cleanName = cleanName
            }

            local display = (ownerName and ownerName ~= "" and ownerName ~= "nil") and ownerName or cleanName
            local uniqueDisplay = display
            local counter = 2
            while _G.FunLabelToKey[uniqueDisplay] do
                uniqueDisplay = display .. " #" .. counter
                counter = counter + 1
            end

            _G.FunLabelToKey[uniqueDisplay] = key
            table.insert(_G.FunVehicleLabels, uniqueDisplay)
        end)
    end
end

local funTargetDD = nil
local lastVehicleSig = ""

local function softRefreshFunTargets()
    local prevKey = _G.FunTarget
    scanVehicles()
    if funTargetDD then
        local currentSig = table.concat(_G.FunVehicleLabels or {}, "|")
        if currentSig ~= lastVehicleSig then
            lastVehicleSig = currentSig
            pcall(function() funTargetDD:Set(_G.FunVehicleLabels) end)
        end
        
        if prevKey and prevKey ~= "---" and _G.FunVehicleData[prevKey] then
            local newLabel = nil
            for lbl, key in pairs(_G.FunLabelToKey or {}) do
                if key == prevKey then
                    newLabel = lbl
                    break
                end
            end
            if newLabel then
                pcall(function() funTargetDD:SetValue(newLabel) end)
                _G.FunTarget = prevKey
            end
        else
            pcall(function() funTargetDD:SetValue("---") end)
            _G.FunTarget = "---"
        end
    end
end

local function refreshFunTargets()
    scanVehicles()
    if funTargetDD then
        lastVehicleSig = table.concat(_G.FunVehicleLabels or {}, "|")
        pcall(function() funTargetDD:Set(_G.FunVehicleLabels) end)
        pcall(function() funTargetDD:SetValue("---") end)
    end
    _G.FunTarget = "---"
end

task.spawn(function()
    local vehiclesFolder = workspace:WaitForChild("Vehicles", 10)
    if vehiclesFolder then
        vehiclesFolder.ChildAdded:Connect(function()
            task.wait(0.5) 
            softRefreshFunTargets()
        end)
        vehiclesFolder.ChildRemoved:Connect(function()
            softRefreshFunTargets()
        end)
    end
end)

task.spawn(function()
    while true do
        task.wait(8)
        softRefreshFunTargets()
    end
end)

