VehicleTab:AddButton({
    Name = "Destroy",
    Description = "Destroys the selected vehicle",
    Callback = function()
        task.spawn(function()
            _G.withAntiSitDisabled(function()
                local Players = game:GetService("Players")
                local lp = Players.LocalPlayer
                local char = lp.Character or lp.CharacterAdded:Wait()
                local hrp = char:WaitForChild("HumanoidRootPart")
                local hum = char:WaitForChild("Humanoid")
                local startCF = hrp.CFrame

                if not _G.FunTarget or _G.FunTarget == "---" then
                    game:GetService("StarterGui"):SetCore("SendNotification", {Title="Carjack", Text="Scan + select a vehicle first!", Duration=3})
                    return
                end

                local data = _G.FunVehicleData[_G.FunTarget]
                if not data then
                    
                    scanVehicles()
                    data = _G.FunVehicleData[_G.FunTarget]
                end
                if not data then
                    game:GetService("StarterGui"):SetCore("SendNotification", {Title="Carjack", Text="Vehicle not found! Re-scan.", Duration=3})
                    return
                end

                local car, seat = data.model, data.seat
                if not car or not seat then
                    game:GetService("StarterGui"):SetCore("SendNotification", {Title="Carjack", Text="No seat found on this vehicle!", Duration=3})
                    return
                end
                if data.occupied then
                    game:GetService("StarterGui"):SetCore("SendNotification", {Title="Carjack", Text="Seat occupied! (FREE vehicles only)", Duration=3})
                    return
                end

                
                pcall(function() hrp.CFrame = seat.CFrame * CFrame.new(0, 1.5, 0) end)
                task.wait(0.2)
                
                hum.Sit = true
                local sitTries = 0
                local sat = false
                while sitTries < 15 do
                    if hum.SeatPart == seat then sat = true break end
                    pcall(function() seat:Sit(hum) end)
                    hum.Sit = true
                    task.wait(0.1)
                    sitTries = sitTries + 1
                end
                if not sat then
                    pcall(function()
                        local myChar = lp.Character
                        local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
                        if myHrp then myHrp.CFrame = startCF end
                    end)
                    game:GetService("StarterGui"):SetCore("SendNotification", {Title="Carjack", Text="Carjack failed! (can't sit in this vehicle)", Duration=3})
                    return
                end

                
                task.wait(0.5)
                game:GetService("StarterGui"):SetCore("SendNotification", {Title="Carjack", Text="Carjacked! Flinging " .. car.Name .. " to the void...", Duration=3})

                
                
                
                local pp = car.PrimaryPart or seat
                local bv = nil
                pcall(function()
                    bv = Instance.new("BodyVelocity")
                    bv.Name = "CarjackPower"
                    bv.Velocity = Vector3.new(0, 5000, 0) 
                    bv.MaxForce = Vector3.new(9e8, 9e8, 9e8)
                    bv.P = 125000
                    bv.Parent = pp
                end)
                pcall(function()
                    pp.AssemblyLinearVelocity = Vector3.new(0, 5000, 0)
                end)
                
                task.wait(0.15)

                
                pcall(function()
                    pp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                    pp.RotVelocity = Vector3.new(0, 0, 0)
                end)
                task.wait()
                pcall(function() hum.Sit = false end)
                pcall(function() hum:ChangeState(Enum.HumanoidStateType.GettingUp) end)
                pcall(function() hum.Jump = true end)
                pcall(function() hum:UnequipTools() end)
                local myHrpNow = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
                if myHrpNow then
                    pcall(function()
                        myHrpNow.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                        myHrpNow.RotVelocity = Vector3.new(0, 0, 0)
                    end)
                end

                
                pcall(function()
                    local myChar = lp.Character
                    local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
                    if myHrp then myHrp.CFrame = startCF end
                end)

                
                task.wait(0.2)
                if bv then
                    
                    pcall(function() bv.Velocity = Vector3.new(1500, -5000, 1500) end)
                end
                pcall(function()
                    pp.AssemblyLinearVelocity = Vector3.new(1500, -5000, 1500)
                end)
                task.wait(0.2)
                pcall(function()
                    if car.PrimaryPart then
                        car:PivotTo(CFrame.new(car.PrimaryPart.Position.X, -90000, car.PrimaryPart.Position.Z))
                    else
                        seat.CFrame = CFrame.new(seat.Position.X, -90000, seat.Position.Z)
                    end
                end)
                game:GetService("StarterGui"):SetCore("SendNotification", {Title="Carjack", Text="Vehicle sent to the void! TP back done.", Duration=4})
            end)
        end)
    end
})

                                          

