local function isVehicleOccupied(car)
    if not car or not car:IsA("Model") then return false end
    local lp = game:GetService("Players").LocalPlayer
    local lpChar = lp and lp.Character
    for _, obj in ipairs(car:GetDescendants()) do
        if obj:IsA("Seat") or obj:IsA("VehicleSeat") then
            if obj.Occupant and obj.Occupant.Parent and obj.Occupant.Parent ~= lpChar then
                return true
            end
        end
    end
    return false
end

local function _bringVehicleToPlayer(car, seat, targetCF, returnCF)
    local lp   = game:GetService("Players").LocalPlayer
    local char = lp.Character or lp.CharacterAdded:Wait()
    local hrp  = char:WaitForChild("HumanoidRootPart")
    local hum  = char:WaitForChild("Humanoid")

    if isVehicleOccupied(car) then return false end

    pcall(function() hum.Sit = false end)
    task.wait(0.05)
    for _ = 1, 15 do
        if isVehicleOccupied(car) then return false end
        pcall(function() hrp.CFrame = seat.CFrame * CFrame.new(0, 1.5, 0) end)
        task.wait(0.06)
        if seat:IsA("Seat") or seat:IsA("VehicleSeat") then
            pcall(function() seat:Sit(hum) end)
        end
        if hum.Sit then break end
    end
    task.wait(0.2)
    if not hum.Sit then return false end

    if not car.PrimaryPart then
        pcall(function() car.PrimaryPart = seat end)
    end
    pcall(function()
        if car.PrimaryPart then
            car:SetPrimaryPartCFrame(targetCF)
        else
            car:PivotTo(targetCF)
        end
    end)
    task.wait(0.15)

    pcall(function()
        if seat then
            for _, w in ipairs(seat:GetChildren()) do
                if w:IsA("Weld") or w.Name == "SeatWeld" or w.Name:find("Seat") then
                    w:Destroy()
                end
            end
        end
        for _, p in ipairs(char:GetDescendants()) do
            if p:IsA("Weld") and (p.Name == "SeatWeld" or p.Name:find("Seat")) then
                p:Destroy()
            end
        end
        hum.Sit = false
        hum.PlatformStand = false
        hum:ChangeState(Enum.HumanoidStateType.Running)
        if returnCF then
            hrp.CFrame = returnCF
        end
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
        hrp.Velocity = Vector3.zero
    end)
    task.wait(0.05)
    return true
end

