                    return
                end
                if isVehicleOccupied(data.model) then
                    game:GetService("StarterGui"):SetCore("SendNotification", {Title="Bring Car", Text="Seat occupied! Vehicle must be free to bring.", Duration=3})
                    return
                end

                local targetCF = startCF * CFrame.new(0, 0, -7)
                local ok = _bringVehicleToPlayer(data.model, data.seat, targetCF, startCF)
                pcall(function() hrp.CFrame = startCF end)
                if ok then
                    game:GetService("StarterGui"):SetCore("SendNotification", {Title="Bring Car", Text="Car brought to your position!", Duration=4})
                else
                    game:GetService("StarterGui"):SetCore("SendNotification", {Title="Bring Car", Text="Failed to sit in this vehicle!", Duration=3})
                end
            end)
        end)
    end
})

VehicleTab:AddButton({
    Name = "Bring All Cars",
    Description = "Brings every free player vehicle to you instantly (circle formation)",
    Callback = function()
        task.spawn(function()
            _G.withAntiSitDisabled(function()
                local lp = game:GetService("Players").LocalPlayer
                local char = lp.Character or lp.CharacterAdded:Wait()
                local hrp = char:WaitForChild("HumanoidRootPart")
                local startCF = hrp.CFrame

                scanVehicles()
                local allList = {}
                for _, d in pairs(_G.FunVehicleData) do
                    if d and not isVehicleOccupied(d.model) then
                        table.insert(allList, d)
                    end
                end

                if #allList == 0 then
                    game:GetService("StarterGui"):SetCore("SendNotification", {Title="Bring All Cars", Text="No free player vehicles found!", Duration=3})
                    return
                end

                local brought = 0
                for i, d in ipairs(allList) do
                    if not isVehicleOccupied(d.model) then
                        pcall(function()
                            local angle  = (i - 1) * (math.pi * 2 / #allList)
                            local target = startCF * CFrame.new(math.sin(angle) * 10, 0, math.cos(angle) * 10)
                            local ok = _bringVehicleToPlayer(d.model, d.seat, target, startCF)
                            if ok then brought = brought + 1 end
                        end)
                    end
                end

                pcall(function() hrp.CFrame = startCF end)
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = "Bring All Cars",
                    Text  = "All vehicles brought to your position!",
                    Duration = 4
                })
            end)
        end)
    end
})

VehicleTab:AddSection({
