do
    local Players = game:GetService("Players")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local RunService = game:GetService("RunService")
    local LocalPlayer = Players.LocalPlayer

    local ShipSystem = {
        tornadoActive = false,
        currentShip = nil,
        antiSitWasActive = false,
        prevFling = false,
        tornadoSession = 0
    }

    local function spawnPirateShip()
        local character = LocalPlayer.Character
        if not character then return nil end

        local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
        if not humanoidRootPart then return nil end

        humanoidRootPart.CFrame = CFrame.new(1754, -2, 58)
        task.wait(0.5)

        local re = ReplicatedStorage:WaitForChild("RE")
        local carRemote = re:FindFirstChild("1Ca1r")
        if carRemote then
            carRemote:FireServer("PickingBoat", "PirateFree")
        end
        task.wait(1)

        local vehicles = workspace:WaitForChild("Vehicles", 5)
        if vehicles then
            for _ = 1, 15 do
                local ship = vehicles:FindFirstChild(LocalPlayer.Name .. "Car")
                if ship then return ship end
                task.wait(0.2)
            end
        end
        return nil
    end

    local function playShipAudio()
        local audioID = 9068077052
        local args = {workspace, audioID, 1}

        for i = 1, 5 do
            local re = ReplicatedStorage.RE:FindFirstChild("1Gu1nSound1s")
            if re then
                re:FireServer(unpack(args))
            end

            if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
                local sound = Instance.new("Sound")
                sound.SoundId = "rbxassetid://" .. audioID
                sound.Parent = LocalPlayer.Character.HumanoidRootPart
                sound:Play()

                task.wait(1.5)
                sound:Destroy()
            end
        end
    end

    local function startTornado()
        local character = LocalPlayer.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
        if not character or not humanoid or not humanoidRootPart then return end

        _G.VehicleFlingActive = true
        pcall(function()
            humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
        end)

        ShipSystem.tornadoActive = true
        ShipSystem.currentShip = spawnPirateShip()
        if not ShipSystem.currentShip then
            _G.VehicleFlingActive = false
            ShipSystem.tornadoActive = false
            return
        end

        local seat = ShipSystem.currentShip:FindFirstChild("Body")
        seat = seat and seat:FindFirstChild("VehicleSeat")
        if not seat then
            seat = ShipSystem.currentShip:FindFirstChildWhichIsA("VehicleSeat", true) or ShipSystem.currentShip:FindFirstChildWhichIsA("Seat", true)
        end
        if not seat then
            _G.VehicleFlingActive = false
            ShipSystem.tornadoActive = false
            return
        end

        if not ShipSystem.currentShip.PrimaryPart then
            ShipSystem.currentShip.PrimaryPart = seat
        end

        local sitTimeout = tick() + 6
        repeat
            task.wait(0.1)
            if not ShipSystem.tornadoActive then return end
            humanoidRootPart.CFrame = seat.CFrame * CFrame.new(0, 1, 0)
        until humanoid.SeatPart == seat or tick() > sitTimeout

        if humanoid.SeatPart ~= seat then
            _G.VehicleFlingActive = false
            ShipSystem.tornadoActive = false
            return
        end

        task.spawn(playShipAudio)

        task.delay(4, function()
            if not ShipSystem.tornadoActive then return end
            if humanoid.SeatPart then
                humanoid.Sit = false
            end
            pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.GettingUp) end)
            pcall(function() humanoid.Jump = true end)
            task.wait(0.05)
            pcall(function() humanoid.Jump = false end)
            if humanoidRootPart then
                humanoidRootPart.CFrame = CFrame.new(0, 5, 0)
            end
            _G.VehicleFlingActive = false
        end)

        task.spawn(function()
            local re = ReplicatedStorage:WaitForChild("RE"):WaitForChild("1Player1sCa1r")
            while ShipSystem.tornadoActive and ShipSystem.currentShip and ShipSystem.currentShip.Parent do
                re:FireServer("Flip")
                task.wait(0.5)
            end
        end)

        local waypoints = {
            Vector3.new(-16, 0, -47),
            Vector3.new(-110, 0, -45),
            Vector3.new(16, 0, -55)
        }

        ShipSystem.currentShip:SetPrimaryPartCFrame(CFrame.new(waypoints[1]))

        local currentIndex = 1
        local nextIndex = 2
        local moveSpeed = 30
        local rotationSpeed = math.rad(720)
        local progress = 0
        local currentRotation = 0

        local connection
        connection = RunService.Heartbeat:Connect(function(dt)
            if not ShipSystem.tornadoActive or not ShipSystem.currentShip or not ShipSystem.currentShip.PrimaryPart or not ShipSystem.currentShip.Parent then
                connection:Disconnect()
                return
            end

            local startPos = waypoints[currentIndex]
            local endPos = waypoints[nextIndex]

            progress = progress + (moveSpeed * dt) / (startPos - endPos).Magnitude
            if progress >= 1 then
                progress = 0
                currentIndex = nextIndex
                nextIndex = (nextIndex % #waypoints) + 1
            end

            local newPos = startPos:lerp(endPos, progress)
            currentRotation = currentRotation + rotationSpeed * dt

            local cframe = CFrame.new(newPos) * CFrame.Angles(0, currentRotation, 0)
            ShipSystem.currentShip:SetPrimaryPartCFrame(cframe)
        end)
    end

    local function stopTornado()
        ShipSystem.tornadoActive = false
        _G.VehicleFlingActive = false

        task.spawn(function()
            local args = {"DeleteAllVehicles"}
            local re = ReplicatedStorage:WaitForChild("RE"):WaitForChild("1Ca1r")
            if re then
                re:FireServer(unpack(args))
            end
        end)
    end

    local tornadoLockOwner = false 
    local TornadoToggle = VehicleTab:AddToggle({
        Name = "Pirate Ship Tornado",
        Description = "Pulls Pirate Ship to the Square",
        Default = false
    })

    TornadoToggle:Callback(function(Value)
        if Value then
            if _G.TornadoLock then
                pcall(function() game:GetService("StarterGui"):SetCore("SendNotification", {Title="Pirate Ship Tornado", Text="Tornado already active! Turn off the other one first.", Duration=3}) end)
                TornadoToggle:SetValue(false)
                return
            end
            tornadoLockOwner = true
            _G.TornadoLock = true
            task.spawn(function()
                startTornado()
                task.wait(5)
                TornadoToggle:SetValue(false)
            end)
        else
            stopTornado()
            if tornadoLockOwner then
                tornadoLockOwner = false
                _G.TornadoLock = false
            end
        end
    end)
end

                                                                   

_G.CanoeSpamActive = false
local canoeOriginalPos = nil

VehicleTab:AddToggle({
    Name = "Canoe Spam",
    Description = "Spawns and scatters canoes at spawn area",
    Default = false,
    Callback = function(p163)
        getgenv().Toggle = p163
        _G.CanoeSpamActive = p163

        if p163 then
            local LocalPlayer4 = game:GetService("Players").LocalPlayer
            local v836 = LocalPlayer4.Character or LocalPlayer4.CharacterAdded:Wait()
            local HumanoidRootPart = v836:WaitForChild("HumanoidRootPart")
            local Humanoid = v836:FindFirstChildOfClass("Humanoid")
            local wc = workspace:WaitForChild("WorkspaceCom", 5)
            local buttonModel = wc and wc:WaitForChild("001_CanoeCloneButton", 5)
            local Button = buttonModel and buttonModel:WaitForChild("Button", 5)
            local ClickDetector = Button and Button:FindFirstChild("ClickDetector")
            local storage = wc and wc:WaitForChild("001_CanoeStorage", 5)

            if not Button or not ClickDetector or not storage then
                _G.CanoeSpamActive = false
                getgenv().Toggle = false
                pcall(function()
                    game:GetService("StarterGui"):SetCore("SendNotification", {
                        Title = "Canoe Spam",
                        Text = "Canoe button or storage not found!",
                        Duration = 3
                    })
                end)
                return
            end

            canoeOriginalPos = HumanoidRootPart.CFrame
            local sessionToken = tick()
            _G.BTR_CANOE_SESSION = sessionToken

            
            task.spawn(function()
                while getgenv().Toggle and _G.CanoeSpamActive and _G.BTR_CANOE_SESSION == sessionToken do
                    local char = LocalPlayer4.Character
                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                    local hum = char and char:FindFirstChildOfClass("Humanoid")
                    if not hrp or not hum then
                        task.wait(0.3)
                        continue
                    end

                    
                    hum:SetStateEnabled(Enum.HumanoidStateType.Seated, true)

                    
                    hrp.CFrame = Button.CFrame
                    task.wait(0.08)

                    
                    pcall(function()
                        fireclickdetector(ClickDetector, 0)
                        fireclickdetector(ClickDetector)
                    end)

                    
                    pcall(function()
                        local pGui = LocalPlayer4:FindFirstChild("PlayerGui")
                        if pGui then
                            for _, g in ipairs(pGui:GetDescendants()) do
                                if (g:IsA("TextLabel") or g:IsA("TextButton")) and g.Visible then
                                    local t = g.Text:lower()
                                    if t:find("patienter") or t:find("please wait") or t:find("wait a moment") then
                                        local container = g:FindFirstAncestorOfClass("Frame") or g:FindFirstAncestorOfClass("ScreenGui") or g
                                        if container then container.Visible = false end
                                    end
                                end
                            end
                        end
                    end)

                    
                    local targetCanoe = nil
                    local t0 = tick()
                    while tick() - t0 < 1.2 and getgenv().Toggle and _G.CanoeSpamActive do
                        if storage then
                            local c = storage:FindFirstChild("Canoe")
                            if c and c:FindFirstChild("VehicleSeat") then
                                targetCanoe = c
                                break
                            end
                        end
                        task.wait(0.04)
                    end

                    
                    if targetCanoe and getgenv().Toggle and _G.CanoeSpamActive then
                        local seat = targetCanoe:FindFirstChild("VehicleSeat")
                        if seat then
                            local sitAttempts = 0
                            local maxSitAttempts = 35
                            repeat
                                sitAttempts = sitAttempts + 1
                                if char and char:FindFirstChild("HumanoidRootPart") then
                                    char.HumanoidRootPart.CFrame = seat.CFrame + Vector3.new(0, math.random(-0.5, 0.5), 0)
                                end
                                pcall(function() seat:Sit(hum) end)
                                task.wait(0.03)
                            until hum.Sit or not getgenv().Toggle or not _G.CanoeSpamActive or sitAttempts >= maxSitAttempts

                            
                            if hum.Sit and getgenv().Toggle and _G.CanoeSpamActive then
                                
                                if char and char:FindFirstChild("HumanoidRootPart") then
                                    char.HumanoidRootPart.CFrame = char.HumanoidRootPart.CFrame * CFrame.new(0, 0, -25)
                                    if seat and seat:IsA("BasePart") then
                                        seat.AssemblyLinearVelocity = char.HumanoidRootPart.CFrame.LookVector * 50
                                    end
                                end
                                task.wait(0.2)

                                
                                local dest = CFrame.new(math.random(-45, 45), 4.55, math.random(-45, 45))
                                if char and char:FindFirstChild("HumanoidRootPart") then
                                    char.HumanoidRootPart.CFrame = dest
                                end
                                task.wait(0.2)

                                
                                hum.Sit = false
                                pcall(function() targetCanoe.Name = "CanoeMolestaHavens" end)
                                task.wait(0.1)
                            end
                        end
                    end

                    task.wait(0.6)
                end
            end)
        else
            getgenv().Toggle = false
            _G.CanoeSpamActive = false
            _G.BTR_CANOE_SESSION = nil
            local lp = game:GetService("Players").LocalPlayer
            local char = lp and lp.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hum then
                hum.Sit = false
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                if _G.AntiSitValue then
                    hum:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
                end
            end
            if canoeOriginalPos and hrp then
                task.wait(0.1)
                pcall(function()
                    hrp.CFrame = canoeOriginalPos
                end)
                canoeOriginalPos = nil
            end
        end
    end
})

do
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local LocalPlayer = Players.LocalPlayer
    local Workspace = game:GetService("Workspace")
    local StarterGui = game:GetService("StarterGui")

    
    _G.VehicleFlingActive = false
    _G.VehicleFlingCar = nil

    local function isOurFlingVehicle(item)
        
        if (_G.VehicleFlingActive or _G.TornadoLock) and item.Name == LocalPlayer.Name .. "Car" then
            return true
        end
        
        if LocalPlayer.Character then
            for _, seat in ipairs(item:GetDescendants()) do
                if (seat:IsA("VehicleSeat") or seat:IsA("Seat")) and seat.Occupant and seat.Occupant.Parent == LocalPlayer.Character then
                    return true
                end
            end
        end
        return false
    end

    
    ;(function()
        local antiSitConnections = {}
        local disabledSeats = {}
        local isAntiSitActive = false

        local function disableSingleSeat(seat)
            if seat and (seat:IsA("Seat") or seat:IsA("VehicleSeat")) then
                disabledSeats[seat] = true
                pcall(function()
                    seat.Disabled = true
                    seat.CanTouch = false
                end)
            end
        end

        local function restoreAllSeats()
            for seat in pairs(disabledSeats) do
                if seat and seat.Parent then
                    pcall(function()
                        seat.Disabled = false
                        seat.CanTouch = true
                    end)
                end
            end
            disabledSeats = {}
        end

        local function resetSitting()
            local player = game.Players.LocalPlayer
            for _, connection in ipairs(antiSitConnections) do
                if connection and connection.Connected then
                    connection:Disconnect()
                end
            end
            antiSitConnections = {}
            restoreAllSeats()
            local humanoid = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
            if humanoid then
                humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
            end
            isAntiSitActive = false
        end

        local function activateAntiSit()
            local player = game.Players.LocalPlayer
            resetSitting()
            isAntiSitActive = true

            
            local vFolder = workspace:FindFirstChild("Vehicles")
            if vFolder then
                for _, car in ipairs(vFolder:GetChildren()) do
                    for _, s in ipairs(car:GetDescendants()) do
                        disableSingleSeat(s)
                    end
                end
                local vAddedConn = vFolder.DescendantAdded:Connect(function(inst)
                    if _G.AntiSitValue and not _G.VehicleFlingActive and not _G.CanoeSpamActive then
                        disableSingleSeat(inst)
                    end
                end)
                table.insert(antiSitConnections, vAddedConn)
            end

            local function preventSitting(humanoid, character)
                if humanoid then
                    humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, false)

                    local sitConnection = humanoid.StateChanged:Connect(function(_, newState)
                        if newState == Enum.HumanoidStateType.Seated and _G.AntiSitValue and not _G.VehicleFlingActive and not _G.CanoeSpamActive then
                            humanoid.Sit = false
                            humanoid.PlatformStand = false
                            humanoid:ChangeState(Enum.HumanoidStateType.Running)
                        end
                    end)
                    table.insert(antiSitConnections, sitConnection)
                end
            end

            local function onCharacterAdded(character)
                local humanoid = character:WaitForChild("Humanoid")
                preventSitting(humanoid, character)
            end

            local characterAddedConnection = player.CharacterAdded:Connect(onCharacterAdded)
            table.insert(antiSitConnections, characterAddedConnection)
            if player.Character then
                onCharacterAdded(player.Character)
            end

            local heartbeatConnection = RunService.Heartbeat:Connect(function()
                local charObj = player.Character
                local humanoid = charObj and charObj:FindFirstChildOfClass("Humanoid")
                if humanoid then
                    if _G.AntiSitValue and not _G.VehicleFlingActive and not _G.CanoeSpamActive then
                        humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
                        if humanoid.Sit or humanoid.SeatPart then
                            local sp = humanoid.SeatPart
                            if sp then
                                disableSingleSeat(sp)
                            end
                            humanoid.Sit = false
                            humanoid.PlatformStand = false
                            humanoid:ChangeState(Enum.HumanoidStateType.Running)
                        end
                    elseif _G.VehicleFlingActive or _G.CanoeSpamActive then
                        humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
                    end
                end
            end)
            table.insert(antiSitConnections, heartbeatConnection)
        end

        local function setAntiSitCallback(Value)
            _G.AntiSitValue = Value
            if Value then
                activateAntiSit()
            else
                resetSitting()
            end
        end
        _G.BTR_PROT_CALLBACKS.AntiSit = setAntiSitCallback

        _G.AntiSitToggle = ProtectionTab:AddToggle({
            Name = "Anti-Sit",
            Description = "No sitting (auto-paused during your own Vehicle Fling)",
            Default = (_G.BTR_AUTORUN and _G.BTR_AUTORUN.AntiSit ~= false),
            Callback = function(Value)
                _G.setBTRProtection("AntiSit", Value, "ProtectionTab")
            end
        })
        _G.BTR_PROT_TOGGLES.AntiSit = _G.AntiSitToggle

        _G.AntiSitValue = (_G.BTR_AUTORUN and _G.BTR_AUTORUN.AntiSit ~= false)

                                                                                 
        
        
        _G.AntiSitForceOff = function()
            _G.AntiSitValue = false
            resetSitting()  
            
            if _G.AntiSitToggle then
                pcall(function() _G.AntiSitToggle:Set(false) end)
            end
        end
        _G.AntiSitForceOn = function()
            _G.AntiSitValue = true
            activateAntiSit()
            
            if _G.AntiSitToggle then
                pcall(function() _G.AntiSitToggle:Set(true) end)
            end
        end
    end)()

    
    
    ;(function()
    local antiFlingStates = {
        Vehicles = false,
        Canoes = false,
        Jets = false,
        Helis = false,
        Balls = false,
        Doors = false
    }

    local function destroyForeignIn(folder)
        if not folder then return end
        local lpName = LocalPlayer and LocalPlayer.Name or ""
        for _, item in ipairs(folder:GetChildren()) do
            
            if isOurFlingVehicle(item) then continue end
            if item.Name == ("Soccer" .. lpName) then continue end
            if item.Name:find(lpName) then continue end
            if _G.CanoeSpamActive and (item.Name == "Canoe" or item.Name:find("Canoe")) then continue end

            local occupiedByUs = false
            if LocalPlayer.Character then
                for _, seat in ipairs(item:GetDescendants()) do
                    if (seat:IsA("VehicleSeat") or seat:IsA("Seat")) and seat.Occupant and seat.Occupant.Parent == LocalPlayer.Character then
                        occupiedByUs = true
                        break
                    end
                end
            end
            if not occupiedByUs then
                pcall(function()
                    if item:IsA("BasePart") then
                        item.CanCollide = false
                        item.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                        item.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                    end
                    for _, p in ipairs(item:GetDescendants()) do
                        if p:IsA("BasePart") then
                            p.CanCollide = false
                            p.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                        end
                    end
                    item:Destroy()
                end)
            end
        end
    end

    
    local function hideDoors()
        for _, v in ipairs(Workspace:GetDescendants()) do
            if v:IsA("BasePart") and v.Name:lower():find("door") then
                v.Transparency = 1
                v.CanCollide = false
            end
        end
    end

    
    local lastVehFlingCheck = 0
    local vehSteppedConn = RunService.Stepped:Connect(function()
        if not antiFlingStates.Vehicles then return end
        local now = tick()
        if now - lastVehFlingCheck < 0.1 then return end
        lastVehFlingCheck = now

        pcall(function()
            local vehicles = Workspace:FindFirstChild("Vehicles")
            if not vehicles then return end
            for _, item in ipairs(vehicles:GetChildren()) do
                if not isOurFlingVehicle(item) then
                    local root = item.PrimaryPart or item:FindFirstChildWhichIsA("BasePart")
                    if root and (root.AssemblyLinearVelocity.Magnitude > 80 or root.Velocity.Magnitude > 80) then
                        for _, veh in ipairs(item:GetDescendants()) do
                            if veh:IsA("BasePart") then
                                veh.CanCollide = false
                                veh.AssemblyLinearVelocity = Vector3.zero
                                veh.AssemblyAngularVelocity = Vector3.zero
                                veh.Velocity = Vector3.zero
                                veh.RotVelocity = Vector3.zero
                            end
                        end
                    end
                end
            end
        end)
    end)
    table.insert(_G.BTR_CONNECTIONS, vehSteppedConn)

    local function antiFlingTick()
        local anyActive = antiFlingStates.Canoes or antiFlingStates.Jets
            or antiFlingStates.Helis or antiFlingStates.Balls
        if not anyActive then return end

        if antiFlingStates.Canoes and not _G.CanoeSpamActive then
            local wc = Workspace:FindFirstChild("WorkspaceCom")
            local canoes = wc and wc:FindFirstChild("001_CanoeStorage")
            if canoes then destroyForeignIn(canoes) end
        end
        if antiFlingStates.Jets then
            local wc = Workspace:FindFirstChild("WorkspaceCom")
            local airport = wc and wc:FindFirstChild("001_Airport")
            local hangar = airport and airport:FindFirstChild("AirportHanger")
            local jetStorage = hangar and hangar:FindFirstChild("001_JetStorage")
            local jets = jetStorage and jetStorage:FindFirstChild("JetAirport")
            if jets then destroyForeignIn(jets) end
        end
        if antiFlingStates.Helis then
            local wc = Workspace:FindFirstChild("WorkspaceCom")
            local helis = wc and wc:FindFirstChild("001_HeliStorage")
            local heli = helis and helis:FindFirstChild("PoliceStationHeli")
            if heli then destroyForeignIn(heli) end
        end
        if antiFlingStates.Balls then
            local wc = Workspace:FindFirstChild("WorkspaceCom")
            local balls = wc and wc:FindFirstChild("001_SoccerBalls")
            if balls then destroyForeignIn(balls) end
        end
    end

    task.spawn(function()
        local currentSession = _G.BTR_SESSION_ID
        local wc = Workspace:WaitForChild("WorkspaceCom", 10)
        local ballsFolder = wc and (wc:FindFirstChild("001_SoccerBalls") or wc:WaitForChild("001_SoccerBalls", 5))
        if ballsFolder then
            local ballConn = ballsFolder.ChildAdded:Connect(function(child)
                if antiFlingStates.Balls then
                    local lpName = LocalPlayer and LocalPlayer.Name or ""
                    if child.Name ~= ("Soccer" .. lpName) and not child.Name:find(lpName) then
                        pcall(function()
                            if child:IsA("BasePart") then
                                child.CanCollide = false
                                child.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                            end
                            for _, p in ipairs(child:GetDescendants()) do
                                if p:IsA("BasePart") then p.CanCollide = false end
                            end
                            child:Destroy()
                        end)
                    end
                end
            end)
            table.insert(_G.BTR_CONNECTIONS, ballConn)
        end

        while currentSession == _G.BTR_SESSION_ID do
            antiFlingTick()
            task.wait(0.25)
        end
    end)

    
    _G.BTR_PROT_TOGGLES = _G.BTR_PROT_TOGGLES or {}
    _G.BTR_PROT_CALLBACKS = _G.BTR_PROT_CALLBACKS or {}

    local function setVehicles(state)
        antiFlingStates.Vehicles = state
    end
    local function setCanoes(state) antiFlingStates.Canoes = state end
    local function setJets(state) antiFlingStates.Jets = state end
    local function setHelis(state) antiFlingStates.Helis = state end
    local function setBalls(state) antiFlingStates.Balls = state end
    local function setDoors(state)
