    local _vehRamProtectRunning = false
    local _vehRamSteppedConn = nil
    local function setVehicleRamProtect(state)
        _vehRamProtectRunning = (state == true)
        if state then
            if _vehRamSteppedConn then return end
            local lastCheck = 0
            _vehRamSteppedConn = RunService.Stepped:Connect(function()
                if not _vehRamProtectRunning then
                    if _vehRamSteppedConn then
                        _vehRamSteppedConn:Disconnect()
                        _vehRamSteppedConn = nil
                    end
                    return
                end
                local now = tick()
                if now - lastCheck < 0.06 then return end
                lastCheck = now

                pcall(function()
                    local myChar = LocalPlayer.Character
                    local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
                    local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
                    if not myChar or not myHrp then return end

                    local myPos = myHrp.Position
                    local myVeh = _G.VehicleFlingCar
                    local myVehName = LocalPlayer.Name .. "Car"

                                                              
                    if myHum and myHum.Sit then
                        local sPart = myHum.SeatPart
                        if sPart then
                            local isOurSeat = false
                            if myVeh and sPart:IsDescendantOf(myVeh) then
                                isOurSeat = true
                            elseif sPart.Parent and sPart.Parent.Name == myVehName then
                                isOurSeat = true
                            elseif sPart:FindFirstAncestor(myVehName) then
                                isOurSeat = true
                            end

                            if not isOurSeat then
                                myHum.Sit = false
                                pcall(function()
                                    sPart.Disabled = true
                                    sPart.CanTouch = false
                                    myHum:ChangeState(Enum.HumanoidStateType.Running)
                                end)
                            end
                        end
                    end

                                                                                                                   
                    local vFolder = Workspace:FindFirstChild("Vehicles")
                    local list = vFolder and vFolder:GetChildren() or Workspace:GetChildren()

                    for _, item in ipairs(list) do
                        if item:IsA("Model") and item.Name ~= myVehName and item ~= myVeh then
                            local pPart = item.PrimaryPart or item:FindFirstChildWhichIsA("BasePart")
                            if pPart and (pPart.Position - myPos).Magnitude < 45 then
                                for _, part in ipairs(item:GetDescendants()) do
                                    if part:IsA("BasePart") then
                                        if part.CanCollide then
                                            part.CanCollide = false
                                        end
                                    end
                                    if part:IsA("Seat") or part:IsA("VehicleSeat") then
                                        if part.CanTouch then
                                            part.CanTouch = false
                                        end
                                        if not part.Disabled then
                                            part.Disabled = true
                                        end
                                    end
                                end
                            end
                        end
                    end

                                                                      
                    if myHrp and (myHrp.AssemblyLinearVelocity.Magnitude > 75 or myHrp.Velocity.Magnitude > 75) then
                        if not _G.VehicleFlingActive then
                            myHrp.AssemblyLinearVelocity = Vector3.zero
                            myHrp.Velocity = Vector3.zero
                            myHrp.RotVelocity = Vector3.zero
                        end
                    end
                end)
            end)
            table.insert(_G.BTR_CONNECTIONS, _vehRamSteppedConn)
        else
            if _vehRamSteppedConn then
                _vehRamSteppedConn:Disconnect()
                _vehRamSteppedConn = nil
            end
        end
    end

