    ProtectionTab:AddSection({"> Anti-Copy Avatar"})

    local _antiCopyActive = false
    local _notifiedCopyPlayers = {}
    local _baselinePlayerAssets = {}
    local _isRejoiningServer = false
    local _lastMyIds = nil
    local _lastMyCount = 0

    local function loadSlotOutfit(slotNum)
        pcall(function()
            local RS = game:GetService("ReplicatedStorage")
            local remotes = RS:FindFirstChild("Remotes")
            local loadOutfit = remotes and remotes:FindFirstChild("LoadOutfit")
            if loadOutfit then
                loadOutfit:InvokeServer(tonumber(slotNum) or 1)
            end
        end)
    end

    local function getPlayerAssetIds(char)
        local ids = {}
        if not char then return ids end
        for _, c in ipairs(char:GetChildren()) do
            if c:IsA("Accessory") then
                local handle = c:FindFirstChild("Handle")
                if handle then
                    local sm = handle:FindFirstChildOfClass("SpecialMesh") or handle:FindFirstChildOfClass("FileMesh")
                    local meshId = sm and sm.MeshId or (handle:IsA("MeshPart") and handle.MeshId or "")
                    local num = meshId:match("%d+")
                    if num and #num > 4 then
                        ids["acc_" .. num] = true
                    elseif c.Name ~= "Accessory" and #c.Name > 3 then
                        ids["acc_name_" .. c.Name:lower()] = true
                    end
                end
            elseif c:IsA("Shirt") and c.ShirtTemplate ~= "" then
                local num = c.ShirtTemplate:match("%d+")
                if num and #num > 4 then ids["shirt_" .. num] = true end
            elseif c:IsA("Pants") and c.PantsTemplate ~= "" then
                local num = c.PantsTemplate:match("%d+")
                if num and #num > 4 then ids["pants_" .. num] = true end
            elseif c:IsA("ShirtGraphic") and c.Graphic ~= "" then
                local num = c.Graphic:match("%d+")
                if num and #num > 4 then ids["tshirt_" .. num] = true end
            end
        end
        return ids
    end

    local function syncBaseline()
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LocalPlayer and plr.Character then
                _baselinePlayerAssets[plr.UserId] = getPlayerAssetIds(plr.Character)
            end
        end
    end
    _G.BTR_SYNC_ANTI_COPY_BASELINE = syncBaseline

    local function setAntiCopy(state)
        _antiCopyActive = state
        _notifiedCopyPlayers = {}
        _baselinePlayerAssets = {}
        _lastMyIds = nil
        _lastMyCount = 0
        if state then
            task.spawn(function()
                task.wait(4)
                syncBaseline()

                while _antiCopyActive and not _isRejoiningServer do
                    if _G.BTR_IS_COPYING_AVATAR or (os.clock() - (_G.BTR_LAST_COPY_TIME or 0) < 3) then
                        task.wait(1)
                        continue
                    end

                    local lpChar = LocalPlayer.Character
                    if lpChar then
                        local myIds = getPlayerAssetIds(lpChar)
                        local myCount = 0
                        for _ in pairs(myIds) do myCount = myCount + 1 end

                        if myCount >= 3 then
                            local myOutfitChanged = false
                            if _lastMyIds then
                                local matchCount = 0
                                for id in pairs(myIds) do
                                    if _lastMyIds[id] then matchCount = matchCount + 1 end
                                end
                                if myCount ~= _lastMyCount or matchCount < math.min(myCount, 3) then
                                    myOutfitChanged = true
                                end
                            end
                            _lastMyIds = myIds
                            _lastMyCount = myCount

                            if myOutfitChanged then
                                syncBaseline()
                                task.wait(1)
                                continue
                            end

                            for _, plr in ipairs(Players:GetPlayers()) do
                                if plr ~= LocalPlayer and plr.Character and not _notifiedCopyPlayers[plr.UserId] then
                                    if _G.BTR_COPIED_PLAYERS and _G.BTR_COPIED_PLAYERS[plr.UserId] then
                                        continue
                                    end

                                    local currentIds = getPlayerAssetIds(plr.Character)
                                    local currentCount = 0
                                    for _ in pairs(currentIds) do currentCount = currentCount + 1 end

                                    local baseline = _baselinePlayerAssets[plr.UserId]
                                    local baselineCount = 0
                                    if baseline then
                                        for _ in pairs(baseline) do baselineCount = baselineCount + 1 end
                                    end

                                    if not baseline or baselineCount == 0 then
                                        _baselinePlayerAssets[plr.UserId] = currentIds
                                    else
                                        local newlyEquippedMatches = 0
                                        local totalMatches = 0
                                        for id in pairs(currentIds) do
                                            if myIds[id] then
                                                totalMatches = totalMatches + 1
                                                if not baseline[id] then
                                                    newlyEquippedMatches = newlyEquippedMatches + 1
                                                end
                                            end
                                        end

                                        if newlyEquippedMatches >= 3 then
                                            _notifiedCopyPlayers[plr.UserId] = true
                                            _baselinePlayerAssets[plr.UserId] = currentIds

                                            StarterGui:SetCore("SendNotification", {
                                                Title = "Anti-Copy Alert!",
                                                Text = plr.Name .. " is copying your avatar!",
                                                Duration = 4
                                            })

                                            local reaction = _G.BTR_ANTI_COPY_REACTION or "Load Saved Slot Outfit"
                                            local slot = _G.BTR_OUTFIT_SLOT or 1

                                            if reaction == "Load Saved Slot Outfit" then
                                                loadSlotOutfit(slot)
                                                StarterGui:SetCore("SendNotification", {
                                                    Title = "Anti-Copy",
                                                    Text = "Loaded Slot " .. tostring(slot) .. " Outfit instantly!",
                                                    Duration = 3
                                                })
                                            elseif reaction == "Auto Rejoin" then
                                                _isRejoiningServer = true
                                                StarterGui:SetCore("SendNotification", {
                                                    Title = "Anti-Copy",
                                                    Text = "Copycat detected! Rejoining server...",
                                                    Duration = 3
                                                })
                                                task.wait(0.3)
                                                pcall(function()
                                                    local TS = game:GetService("TeleportService")
                                                    local Players = game:GetService("Players")
                                                    if #Players:GetPlayers() <= 1 then
                                                        Players.LocalPlayer:Kick("\nRejoining...")
                                                        task.wait()
                                                        TS:Teleport(game.PlaceId, Players.LocalPlayer)
                                                    else
                                                        TS:TeleportToPlaceInstance(game.PlaceId, game.JobId, Players.LocalPlayer)
                                                    end
                                                end)
                                                break
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    task.wait(1)
                end
            end)
        end
    end

    _G.BTR_PROT_CALLBACKS.AntiCopy = setAntiCopy
    _G.BTR_PROT_TOGGLES.AntiCopy = ProtectionTab:AddToggle({
        Name = "Anti-Copy Avatar",
        Description = "Detects players copying 3+ of your items and reacts immediately",
        Default = (_G.BTR_AUTORUN and _G.BTR_AUTORUN.AntiCopy == true) or false,
        Callback = function(state) _G.setBTRProtection("AntiCopy", state, "ProtectionTab") end
    })

    local slotStrDefault = "Slot " .. tostring(_G.BTR_OUTFIT_SLOT or 1)

    ProtectionTab:AddDropdown({
        Name = "Copy Reaction Mode",
        Description = "Action to take when a copycat is detected",
        Options = {"Load Saved Slot Outfit", "Auto Rejoin", "Notification Only"},
        Default = _G.BTR_ANTI_COPY_REACTION or "Load Saved Slot Outfit",
        Callback = function(mode)
            _G.BTR_ANTI_COPY_REACTION = mode
            _G.saveBTRConfig()
        end
    })

    ProtectionTab:AddDropdown({
        Name = "Bait Outfit Slot",
        Description = "Brookhaven wardrobe slot to load if copied (1, 2 or 3)",
        Options = {"Slot 1", "Slot 2", "Slot 3"},
        Default = slotStrDefault,
        Callback = function(slot)
            if slot == "Slot 1" then _G.BTR_OUTFIT_SLOT = 1
            elseif slot == "Slot 2" then _G.BTR_OUTFIT_SLOT = 2
            elseif slot == "Slot 3" then _G.BTR_OUTFIT_SLOT = 3
            end
            _G.saveBTRConfig()
        end
    })

    ProtectionTab:AddButton({
        Name = "Load Selected Slot Now",
        Description = "Manually loads your chosen Brookhaven outfit slot",
        Callback = function()
            local slot = _G.BTR_OUTFIT_SLOT or 1
            loadSlotOutfit(slot)
            StarterGui:SetCore("SendNotification", {Title="Outfit Loaded", Text="Slot " .. tostring(slot) .. " loaded!", Duration=2})
        end
    })
end)()
end

                                                                                     

;(function()
    local PropSystem = {
        active = false,
        running = false,
    }

    local lotAddedConn = nil
    local lotRemotes = {}

    
    local function getLotRemotes(lot)
        if not lot or not lot:IsA("Instance") then return nil, nil end
        local cached = lotRemotes[lot]
        if cached and cached.set and cached.set.Parent then
            return cached.set, cached.is
        end
        local setBlocked = lot:FindFirstChild("Permissions:SetPropPlacementBlockedForOthers", true)
        local isBlocked = lot:FindFirstChild("Permissions:IsPropPlacementBlockedForOthers", true)
        if setBlocked and setBlocked:IsA("RemoteFunction") then
            lotRemotes[lot] = { set = setBlocked, is = isBlocked }
            return setBlocked, isBlocked
        end
        return nil, nil
    end

    local function unlockLotRemote(lot)
        local setBlocked = lot and lot:FindFirstChild("Permissions:SetPropPlacementBlockedForOthers", true)
        if setBlocked and setBlocked:IsA("RemoteFunction") then
            task.spawn(function()
                pcall(function() setBlocked:InvokeServer(false) end)
            end)
        end
    end

    local function sweepRemoteLots()
        local lots = workspace:FindFirstChild("001_Lots")
        if lots then
            for _, lot in pairs(lots:GetChildren()) do
                if not PropSystem.active then break end
                unlockLotRemote(lot)
                task.wait(0.05)
            end
        end
    end

    
    local function propProtectLoop()
        PropSystem.running = true
        while PropSystem.active do
            sweepRemoteLots()
            task.wait(12)
        end
        PropSystem.running = false
    end

    local function ensurePropLoop()
        if PropSystem.active and not PropSystem.running then
            task.spawn(function()
                pcall(function() propProtectLoop() end)
            end)
        end
    end

    local function setupListener()
        if lotAddedConn then
            pcall(function() lotAddedConn:Disconnect() end)
            lotAddedConn = nil
        end

        local lots = workspace:FindFirstChild("001_Lots")
        if not lots then return end

        lotAddedConn = lots.DescendantAdded:Connect(function(descendant)
            if not PropSystem.active then return end
            if descendant.Name == "Permissions:SetPropPlacementBlockedForOthers" and descendant:IsA("RemoteFunction") then
                local lot = descendant:FindFirstAncestorOfClass("Model") or descendant.Parent
                if lot then
                    task.defer(function()
                        unlockLotRemote(lot)
                    end)
                end
            end
        end)
    end

    local function setPropPlacement(state)
        if state then
            if PropSystem.active then return end
            PropSystem.active = true

            setupListener()
            ensurePropLoop()
            task.spawn(function()
                pcall(function() sweepRemoteLots() end)
            end)
        else
            PropSystem.active = false
            if lotAddedConn then
                pcall(function() lotAddedConn:Disconnect() end)
                lotAddedConn = nil
            end
        end
    end
    _G.BTR_PROT_CALLBACKS.PropPlacement = setPropPlacement

    _G.setBTRPropBypassMode = function(newMode)
        _G.BTR_PROP_BYPASS_MODE = "Remote"
        if _G.saveBTRConfig then _G.saveBTRConfig() end
    end

    
    ProtectionTab:AddButton({
        Name = "1-Click Force Unlock House Props (Instant)",
        Description = "Instantly forces every house lot on the server to UNLOCKED in 1 click",
        Callback = function()
            local lots = workspace:FindFirstChild("001_Lots")
            local count = 0
            if lots then
                for _, lot in pairs(lots:GetChildren()) do
                    local setBlocked = lot:FindFirstChild("Permissions:SetPropPlacementBlockedForOthers", true)
                    if setBlocked and setBlocked:IsA("RemoteFunction") then
                        count = count + 1
                        task.spawn(function() pcall(function() setBlocked:InvokeServer(false) end) end)
                    end
                end
            end
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = "House Props",
                Text = "Force unlocked " .. count .. " houses across server!",
                Duration = 3
            })
        end
    })

    _G.BTR_PROT_TOGGLES.PropPlacement = ProtectionTab:AddToggle({
        Name = "Unlock House Props (All)",
        Description = "Global protection: automatically unblocks prop placement on EVERY house via server Remote. ON by default.",
        Default = (_G.BTR_AUTORUN and _G.BTR_AUTORUN.PropPlacement == true) or false,
        Callback = function(state) _G.setBTRProtection("PropPlacement", state, "ProtectionTab") end
    })
end)()

                                                    

;(function()
local invincibleShieldActive = false
local invincibleCharConn = nil
local invincibleHeartbeat = nil

local function applyUndeadShield(char)
    if not char then return end
    local hum = char:WaitForChild("Humanoid", 4)
    local hrp = char:WaitForChild("HumanoidRootPart", 4)
    if not hum or not hrp then return end

    hum:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
    pcall(function() char.BreakJointsOnDeath = false end)
    pcall(function() hum.Health = 0 end)

    pcall(function()
        hrp.CustomPhysicalProperties = PhysicalProperties.new(100, 0, 0, 0, 0)
    end)
end

local function restoreNormalState()
    local char = game:GetService("Players").LocalPlayer.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if hum then
        hum:SetStateEnabled(Enum.HumanoidStateType.Dead, true)
        pcall(function() hum.Health = 100 end)
    end
    if hrp then
        pcall(function()
            hrp.CustomPhysicalProperties = nil
        end)
    end
end

local function setInvincibleShieldCallback(state)
    invincibleShieldActive = (state == true)
    _G.InvincibleShieldActive = invincibleShieldActive

    if invincibleCharConn then
        invincibleCharConn:Disconnect()
        invincibleCharConn = nil
    end
    if invincibleHeartbeat then
        invincibleHeartbeat:Disconnect()
        invincibleHeartbeat = nil
    end

    local lp = game:GetService("Players").LocalPlayer

    if invincibleShieldActive then
        applyUndeadShield(lp.Character)

        invincibleCharConn = lp.CharacterAdded:Connect(function(newChar)
            task.wait(0.3)
            if invincibleShieldActive then
                applyUndeadShield(newChar)
            end
        end)

        invincibleHeartbeat = game:GetService("RunService").Heartbeat:Connect(function()
            local char = lp.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not hum then return end

            
            if hum.Health > 0 then
                hum:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
                pcall(function() char.BreakJointsOnDeath = false end)
                pcall(function() hum.Health = 0 end)
            end
        end)

        if _G.BTR_ALL_LOADED and not _G.BTR_STARTUP_SILENT then
            pcall(function()
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = "Invincible Shield",
                    Text = "Exploit Immunity ACTIVE! Health = 0 (Undead). Hubs will refuse to attack you.",
                    Duration = 4
                })
            end)
        end
    else
        restoreNormalState()
        if _G.BTR_ALL_LOADED and not _G.BTR_STARTUP_SILENT then
            pcall(function()
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = "Invincible Shield",
                    Text = "Exploit Immunity disabled. Health restored to normal.",
                    Duration = 3
                })
            end)
        end
    end
end

_G.BTR_PROT_CALLBACKS.InvincibleShield = setInvincibleShieldCallback

local _noCollisionConn = nil
local _noCollisionSteppedConn = nil
local _noCollisionDescAddedConn = nil
local _noCollisionActive = false
local _trackedDoors = {}

local function setNoCollisionCallback(state)
    _noCollisionActive = state
    if _noCollisionConn then
        pcall(function() _noCollisionConn:Disconnect() end)
        _noCollisionConn = nil
    end
    if _noCollisionSteppedConn then
        pcall(function() _noCollisionSteppedConn:Disconnect() end)
        _noCollisionSteppedConn = nil
    end
    if _noCollisionDescAddedConn then
        pcall(function() _noCollisionDescAddedConn:Disconnect() end)
        _noCollisionDescAddedConn = nil
    end

    if state then
        local RunService = game:GetService("RunService")
        local Players = game:GetService("Players")
        local Workspace = game:GetService("Workspace")
        local lp = Players.LocalPlayer

                                          
        _trackedDoors = {}
        for _, d in ipairs(Workspace:GetDescendants()) do
            if d:IsA("BasePart") and (d.Name:lower():find("door") or (d.Parent and d.Parent.Name:lower():find("door"))) then
                table.insert(_trackedDoors, d)
            end
        end

        _noCollisionDescAddedConn = Workspace.DescendantAdded:Connect(function(d)
            if not _noCollisionActive then return end
            if d:IsA("BasePart") and (d.Name:lower():find("door") or (d.Parent and d.Parent.Name:lower():find("door"))) then
                table.insert(_trackedDoors, d)
                pcall(function()
                    d.CanCollide = false
                    d.CanTouch = false
                end)
            end
        end)

                                                                            
        _noCollisionSteppedConn = RunService.Stepped:Connect(function()
            if not _noCollisionActive then return end

            local myChar = lp and lp.Character
            local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
            local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")

                                                                                 
            if myChar then
                for _, part in ipairs(myChar:GetDescendants()) do
                    if part:IsA("BasePart") then
                        part.CanCollide = false
                        part.CanTouch = false
                    end
                end
            end

                                                                               
            if myHum then
                myHum:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
                if myHum.Sit then myHum.Sit = false end
            end

                                                                    
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= lp and p.Character then
                    for _, part in ipairs(p.Character:GetDescendants()) do
                        if part:IsA("BasePart") then
                            part.CanCollide = false
                            part.CanTouch = false
                        end
                    end
                end
            end

                                                                             
            for i = #_trackedDoors, 1, -1 do
                local door = _trackedDoors[i]
                if door and door.Parent then
                    door.CanCollide = false
                    door.CanTouch = false
                    if not door.Anchored then
                        door.AssemblyLinearVelocity = Vector3.zero
                        door.AssemblyAngularVelocity = Vector3.zero
                        door.Velocity = Vector3.zero
                        door.RotVelocity = Vector3.zero
                        for _, c in ipairs(door:GetChildren()) do
                            if c:IsA("AlignPosition") or c:IsA("Torque") or c:IsA("BodyAngularVelocity") or c:IsA("BodyVelocity") or c:IsA("BodyThrust") then
                                pcall(function() c.Enabled = false end)
                            end
                        end
                    end
                else
                    table.remove(_trackedDoors, i)
                end
            end

                                                                               
            if myHrp then
                local myPos = myHrp.Position
                local vehicles = Workspace:FindFirstChild("Vehicles")
                if vehicles then
                    for _, veh in ipairs(vehicles:GetChildren()) do
                        local vPrimary = veh.PrimaryPart or veh:FindFirstChildWhichIsA("BasePart")
                        if vPrimary and (vPrimary.Position - myPos).Magnitude < 120 then
                            for _, vPart in ipairs(veh:GetDescendants()) do
                                if vPart:IsA("BasePart") then
                                    vPart.CanCollide = false
                                    vPart.CanTouch = false
                                end
                            end
                        end
                    end
                end
            end
        end)

                                                                                         
        _noCollisionConn = RunService.Heartbeat:Connect(function()
            if not _noCollisionActive then return end
            local myChar = lp and lp.Character
            local hrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if hrp then
                local linVel = hrp.AssemblyLinearVelocity
                local angVel = hrp.AssemblyAngularVelocity
                local horizSpeed = Vector3.new(linVel.X, 0, linVel.Z).Magnitude

                                                                           
                if horizSpeed > 60 then
                    hrp.AssemblyLinearVelocity = Vector3.new(0, math.clamp(linVel.Y, -50, 50), 0)
                    hrp.Velocity = Vector3.new(0, math.clamp(hrp.Velocity.Y, -50, 50), 0)
                end

                                                         
                if math.abs(linVel.Y) > 85 then
                    hrp.AssemblyLinearVelocity = Vector3.new(linVel.X, math.clamp(linVel.Y, -50, 50), linVel.Z)
                    hrp.Velocity = Vector3.new(hrp.Velocity.X, math.clamp(hrp.Velocity.Y, -50, 50), hrp.Velocity.Z)
                end

                                                                              
                if angVel.Magnitude > 15 then
                    hrp.AssemblyAngularVelocity = Vector3.zero
                    hrp.RotVelocity = Vector3.zero
                end
            end
        end)

        if _G.BTR_ALL_LOADED and not _G.BTR_STARTUP_SILENT then
            pcall(function()
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = "No Collision",
                    Text = "True Absolute Immunity ACTIVE! Doors, vehicles & flings completely neutralized.",
                    Duration = 3
                })
            end)
        end
    else
        local lp = game:GetService("Players").LocalPlayer
        local myChar = lp and lp.Character
        local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
        if myHum then
            pcall(function() myHum:SetStateEnabled(Enum.HumanoidStateType.Seated, true) end)
        end
        if myChar then
            for _, part in ipairs(myChar:GetDescendants()) do
                if part:IsA("BasePart") and not part:IsA("Accessory") and part.Parent and not part.Parent:IsA("Accessory") then
                    pcall(function()
                        if part.Name == "UpperTorso" or part.Name == "LowerTorso" or part.Name == "Torso" or part.Name == "Head" then
                            part.CanCollide = true
                        end
                        part.CanTouch = true
                    end)
                end
            end
        end

        _trackedDoors = {}

        if _G.BTR_ALL_LOADED and not _G.BTR_STARTUP_SILENT then
            pcall(function()
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = "No Collision",
                    Text = "No Collision disabled. Normal collisions restored.",
                    Duration = 3
                })
            end)
        end
    end
end

_G.BTR_PROT_CALLBACKS.NoCollision = setNoCollisionCallback

