            _G.BTR_CUSTOM_WALLPAPER_ID = cleanId
            _G.BTR_SELECTED_WALLPAPER = "Custom ID"
            _G.BTR_CUSTOM_WALLPAPERS_HISTORY = _G.BTR_CUSTOM_WALLPAPERS_HISTORY or {}
            local exists = false
            for _, id in ipairs(_G.BTR_CUSTOM_WALLPAPERS_HISTORY) do
                if id == cleanId then exists = true break end
            end
            if not exists then
                table.insert(_G.BTR_CUSTOM_WALLPAPERS_HISTORY, 1, cleanId)
                if #_G.BTR_CUSTOM_WALLPAPERS_HISTORY > 10 then
                    table.remove(_G.BTR_CUSTOM_WALLPAPERS_HISTORY)
