;(function()
local _savedGraphics = {}
local _antiLagActive = false
SettingsTab:AddToggle({
    Name = "Anti-Lag (FPS Boost)",
    Description = "Boosts FPS by simplifying textures (restores on toggle OFF)",
    Default = false,
    Callback = function(state)
        _antiLagActive = state
        local Lighting = game:GetService("Lighting")
        local Terrain = workspace:FindFirstChildOfClass("Terrain")

        if state then
            
            _savedGraphics = {
                GlobalShadows = Lighting.GlobalShadows,
                FogEnd = Lighting.FogEnd,
                Brightness = Lighting.Brightness,
                TerrainWaterWaveSize = Terrain and Terrain.WaterWaveSize or 0,
                Parts = {}
            }

            pcall(function()
                Lighting.GlobalShadows = false
                Lighting.FogEnd = 9e9
                if Terrain then Terrain.WaterWaveSize = 0 end
            end)

            for _, obj in ipairs(workspace:GetDescendants()) do
                pcall(function()
                    if obj:IsA("BasePart") and not obj.Parent:FindFirstChildOfClass("Humanoid") then
                        _savedGraphics.Parts[obj] = {
                            Material = obj.Material,
                            CastShadow = obj.CastShadow
                        }
                        obj.Material = Enum.Material.SmoothPlastic
                        obj.CastShadow = false
                    elseif obj:IsA("Decal") or obj:IsA("Texture") then
                        _savedGraphics.Parts[obj] = { Transparency = obj.Transparency }
                        obj.Transparency = 0.8
                    elseif obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Smoke") or obj:IsA("Fire") then
                        _savedGraphics.Parts[obj] = { Enabled = obj.Enabled }
                        obj.Enabled = false
                    end
                end)
            end
        else
            
            pcall(function()
                if _savedGraphics.GlobalShadows ~= nil then Lighting.GlobalShadows = _savedGraphics.GlobalShadows end
                if _savedGraphics.FogEnd ~= nil then Lighting.FogEnd = _savedGraphics.FogEnd end
                if _savedGraphics.Brightness ~= nil then Lighting.Brightness = _savedGraphics.Brightness end
                if Terrain and _savedGraphics.TerrainWaterWaveSize ~= nil then Terrain.WaterWaveSize = _savedGraphics.TerrainWaterWaveSize end
            end)

            for obj, props in pairs(_savedGraphics.Parts or {}) do
                pcall(function()
                    if obj and obj.Parent then
                        if props.Material ~= nil then obj.Material = props.Material end
                        if props.CastShadow ~= nil then obj.CastShadow = props.CastShadow end
                        if props.Transparency ~= nil then obj.Transparency = props.Transparency end
                        if props.Enabled ~= nil then obj.Enabled = props.Enabled end
                    end
                end)
            end
            _savedGraphics = {}
        end
    end
})

local _shadersActive = false
local _shaderSavedLighting = {}
local _shaderSavedMaterials = {}
local _shaderOrigSky = nil
local _shaderInstances = {}
local _shaderConnections = {}

local function revertDarkBrookShaders()
    _shadersActive = false

    for _, conn in ipairs(_shaderConnections) do
        pcall(function() conn:Disconnect() end)
    end
    _shaderConnections = {}

    for _, inst in ipairs(_shaderInstances) do
        pcall(function()
            if inst and inst.Parent then
                inst:Destroy()
            end
        end)
    end
    _shaderInstances = {}

    for part, origMat in pairs(_shaderSavedMaterials) do
        pcall(function()
            if part and part.Parent then
                part.Material = origMat
            end
        end)
    end
    _shaderSavedMaterials = {}

    local Lighting = game:GetService("Lighting")
    pcall(function()
        if _shaderSavedLighting.Brightness ~= nil then Lighting.Brightness = _shaderSavedLighting.Brightness end
        if _shaderSavedLighting.GlobalShadows ~= nil then Lighting.GlobalShadows = _shaderSavedLighting.GlobalShadows end
        if _shaderSavedLighting.OutdoorAmbient ~= nil then Lighting.OutdoorAmbient = _shaderSavedLighting.OutdoorAmbient end
        if _shaderSavedLighting.FogColor ~= nil then Lighting.FogColor = _shaderSavedLighting.FogColor end
        if _shaderSavedLighting.FogStart ~= nil then Lighting.FogStart = _shaderSavedLighting.FogStart end
        if _shaderSavedLighting.FogEnd ~= nil then Lighting.FogEnd = _shaderSavedLighting.FogEnd end
        if _shaderSavedLighting.EnvironmentSpecularScale ~= nil then Lighting.EnvironmentSpecularScale = _shaderSavedLighting.EnvironmentSpecularScale end
        if _shaderSavedLighting.EnvironmentDiffuseScale ~= nil then Lighting.EnvironmentDiffuseScale = _shaderSavedLighting.EnvironmentDiffuseScale end
    end)
    _shaderSavedLighting = {}

    if _shaderOrigSky and _shaderOrigSky.Parent == nil then
        pcall(function() _shaderOrigSky.Parent = Lighting end)
    end
    _shaderOrigSky = nil
end

local function applyDarkBrookShaders()
    _shadersActive = true
    local Lighting = game:GetService("Lighting")
    local TweenService = game:GetService("TweenService")
    local RunService = game:GetService("RunService")
    local Debris = game:GetService("Debris")
    local Players = game:GetService("Players")
    local player = Players.LocalPlayer

    _shaderSavedLighting = {
        Brightness = Lighting.Brightness,
        GlobalShadows = Lighting.GlobalShadows,
        OutdoorAmbient = Lighting.OutdoorAmbient,
        FogColor = Lighting.FogColor,
        FogStart = Lighting.FogStart,
        FogEnd = Lighting.FogEnd,
        EnvironmentSpecularScale = Lighting.EnvironmentSpecularScale,
        EnvironmentDiffuseScale = Lighting.EnvironmentDiffuseScale
    }

    local existingSky = Lighting:FindFirstChildOfClass("Sky")
    if existingSky then
        _shaderOrigSky = existingSky
        existingSky.Parent = nil
    end

    local model = workspace:FindFirstChild("Model")
    if model then
        local function setMat(obj)
            for _, c in pairs(obj:GetChildren()) do
                if c:IsA("BasePart") then
                    if not _shaderSavedMaterials[c] then _shaderSavedMaterials[c] = c.Material end
                    c.Material = Enum.Material.Basalt
                elseif c:IsA("Model") or c:IsA("Folder") then
                    setMat(c)
                end
            end
        end

        if model:FindFirstChild("001_SnowStreet") then setMat(model["001_SnowStreet"]) end
        if model:FindFirstChild("Street") then
            for _, o in pairs(model.Street:GetDescendants()) do
                if o:IsA("BasePart") then
                    if not _shaderSavedMaterials[o] then _shaderSavedMaterials[o] = o.Material end
                    o.Material = Enum.Material.Basalt
                end
            end
        end

        for _, o in pairs(model:GetChildren()) do
            if o:IsA("BasePart") and (o.Name == "Sidewalk" or o.Name == "Wedge") and o.Material == Enum.Material.SmoothPlastic then
                if not _shaderSavedMaterials[o] then _shaderSavedMaterials[o] = o.Material end
                o.Material = Enum.Material.Cobblestone
            end
        end

        local conn = model.ChildAdded:Connect(function(obj)
            if not _shadersActive then return end
            if obj:IsA("BasePart") and (obj.Name == "Sidewalk" or obj.Name == "Wedge") and obj.Material == Enum.Material.SmoothPlastic then
                if not _shaderSavedMaterials[obj] then _shaderSavedMaterials[obj] = obj.Material end
                obj.Material = Enum.Material.Cobblestone
            end
        end)
        table.insert(_shaderConnections, conn)
    end

    local soundPart = Instance.new("Part")
    soundPart.Name = "BTR_ShaderSoundPart"
    soundPart.Size = Vector3.new(1, 1, 1)
    soundPart.Transparency = 1
    soundPart.Anchored = true
    soundPart.CanCollide = false
    soundPart.Parent = workspace
    table.insert(_shaderInstances, soundPart)

    local birdSound = Instance.new("Sound")
    birdSound.Name = "BirdsSound"
    birdSound.SoundId = "rbxassetid://1237969272"
    birdSound.Looped = true
    birdSound.Volume = 0.5
    birdSound.Parent = soundPart

    local wolfSound = Instance.new("Sound")
    wolfSound.Name = "WolfSound"
    wolfSound.SoundId = "rbxassetid://9069609200"
    wolfSound.Looped = false
    wolfSound.Volume = 0.7
    wolfSound.Parent = soundPart

    local function isNight()
        local t = Lighting.ClockTime
        return t >= 18 or t <= 6
    end

    task.spawn(function()
        while _shadersActive do
            if isNight() then
                if birdSound.IsPlaying then birdSound:Stop() end
                if not wolfSound.IsPlaying then wolfSound:Play() end
            else
                if wolfSound.IsPlaying then wolfSound:Stop() end
                if not birdSound.IsPlaying then birdSound:Play() end
            end
            task.wait(20)
        end
    end)

    local shootingStarsFolder = Instance.new("Folder")
    shootingStarsFolder.Name = "BTR_ShootingStars"
    shootingStarsFolder.Parent = workspace
    table.insert(_shaderInstances, shootingStarsFolder)

    local spaceSound = Instance.new("Sound")
    spaceSound.Name = "SpaceSound"
    spaceSound.SoundId = "rbxassetid://9069609200"
    spaceSound.Looped = true
    spaceSound.Volume = 0.4
    spaceSound.Parent = soundPart

    local function createShootingStar()
        if not _shadersActive or not shootingStarsFolder.Parent then return end
        local char = player.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end

        local star = Instance.new("Part")
        star.Size = Vector3.new(0.3, 0.3, 0.3)
        star.Material = Enum.Material.Neon
        star.Color = Color3.fromRGB(255, 255, 255)
        star.Anchored = true
        star.CanCollide = false
        star.Parent = shootingStarsFolder

        local angle = math.rad(math.random(0, 360))
        local dist = math.random(100, 300)
        local startPos = hrp.Position + Vector3.new(math.cos(angle) * dist, math.random(150, 300), math.sin(angle) * dist)
        star.Position = startPos

        local dir = Vector3.new(math.random(-100, 100) / 100, -0.7, math.random(-100, 100) / 100).Unit
        local speed = math.random(250, 450)
        local lifetime = math.random(1, 1.5)
        local timePassed = 0

        local moveConn
        moveConn = RunService.Heartbeat:Connect(function(dt)
            if not _shadersActive or not star.Parent then
                if moveConn then moveConn:Disconnect() end
                if star.Parent then star:Destroy() end
                return
            end
            timePassed = timePassed + dt
            if timePassed >= lifetime then
                if moveConn then moveConn:Disconnect() end
                if star.Parent then star:Destroy() end
                return
            end
            star.Position = star.Position + dir * speed * dt
        end)
    end

    task.spawn(function()
        while _shadersActive do
            if isNight() then
                createShootingStar()
                task.wait(math.random(2, 5))
            else
                task.wait(3)
            end
        end
    end)

    local rainFolder = Instance.new("Folder")
    rainFolder.Name = "BTR_FakeRain"
    rainFolder.Parent = workspace
    table.insert(_shaderInstances, rainFolder)

    local function spawnRain()
        if not _shadersActive or not rainFolder.Parent then return end
        local char = player.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end

        for i = 1, 10 do
            local drop = Instance.new("Part")
            drop.Size = Vector3.new(0.05, 0.7, 0.05)
            drop.Color = Color3.fromRGB(180, 200, 255)
            drop.Material = Enum.Material.Glass
            drop.Transparency = 0.5
            drop.Anchored = true
            drop.CanCollide = false
            drop.Position = hrp.Position + Vector3.new(math.random(-40, 40), 30, math.random(-40, 40))
            drop.Parent = rainFolder

            local tween = TweenService:Create(drop, TweenInfo.new(0.6), { Position = drop.Position - Vector3.new(0, 45, 0) })
            tween:Play()
            Debris:AddItem(drop, 0.65)
        end
    end

    task.spawn(function()
        while _shadersActive do
            spawnRain()
            task.wait(0.2)
        end
    end)

    Lighting.Brightness = 2
    Lighting.GlobalShadows = true
    Lighting.OutdoorAmbient = Color3.fromRGB(70, 70, 70)
    Lighting.FogColor = Color3.fromRGB(120, 130, 140)
    Lighting.FogStart = 80
    Lighting.FogEnd = 600
    Lighting.EnvironmentSpecularScale = 1
    Lighting.EnvironmentDiffuseScale = 0.5

    local sky = Instance.new("Sky")
    sky.Name = "BTR_DarkBrookSky"
    sky.SkyboxBk = "rbxassetid://159454299"
    sky.SkyboxDn = "rbxassetid://159454296"
    sky.SkyboxFt = "rbxassetid://159454293"
    sky.SkyboxLf = "rbxassetid://159454286"
    sky.SkyboxRt = "rbxassetid://159454300"
    sky.SkyboxUp = "rbxassetid://159454304"
    sky.Parent = Lighting
    table.insert(_shaderInstances, sky)

    local color = Instance.new("ColorCorrectionEffect")
    color.Name = "BTR_ColorCorrection"
    color.Brightness = 0.03
    color.Contrast = 0.15
    color.Saturation = 0.05
    color.TintColor = Color3.fromRGB(255, 240, 220)
    color.Parent = Lighting
    table.insert(_shaderInstances, color)

    local bloom = Instance.new("BloomEffect")
    bloom.Name = "BTR_Bloom"
    bloom.Intensity = 0.8
    bloom.Size = 56
    bloom.Threshold = 0.9
    bloom.Parent = Lighting
    table.insert(_shaderInstances, bloom)

    local sunRays = Instance.new("SunRaysEffect")
    sunRays.Name = "BTR_SunRays"
    sunRays.Intensity = 0.05
    sunRays.Spread = 0.8
    sunRays.Parent = Lighting
    table.insert(_shaderInstances, sunRays)

    local blur = Instance.new("BlurEffect")
    blur.Name = "BTR_Blur"
    blur.Size = 0
    blur.Parent = Lighting
    table.insert(_shaderInstances, blur)
end

SettingsTab:AddToggle({
    Name = "DarkBrook Shaders (Reversible)",
    Description = "Realistic sky, lighting, ambient audio & materials (fully reversible on OFF)",
    Default = false,
    Callback = function(state)
        if state then
            applyDarkBrookShaders()
            game:GetService("StarterGui"):SetCore("SendNotification", { Title = "Shaders", Text = "DarkBrook Shaders enabled!", Duration = 3 })
        else
            revertDarkBrookShaders()
            game:GetService("StarterGui"):SetCore("SendNotification", { Title = "Shaders", Text = "Default graphics restored!", Duration = 3 })
        end
    end
})

