local function _btrInitStalkerMimic()
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer
    local RunService = game:GetService("RunService")
    local TextChatService = game:GetService("TextChatService")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local StarterGui = game:GetService("StarterGui")

    local stalkSelectedTarget = nil
    local copyChatEnabled = false
    local copyMoveEnabled = false
    local stalkerEnabled = false

    local copyMoveMode = "Mirror"
    local copyMoveDistance = 6
    local stalkPositionMode = "Dynamic"
    local stalkDistance = 30
    local stalkFleeOnSight = true

    local function resolveTarget()
        if stalkSelectedTarget and stalkSelectedTarget ~= "---" then
            local p = Players:FindFirstChild(stalkSelectedTarget)
            if p then return p end
        end
        if _G.TrollTarget and _G.TrollTarget ~= "---" then
            local p = Players:FindFirstChild(_G.TrollTarget)
            if p then return p end
        end
        return nil
    end

    local function notify(title, text)
        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = title,
                Text = text,
                Duration = 3
            })
        end)
    end

    
    local lastParrotMsg = ""
    local lastParrotTime = 0

    local function sendChatMsg(msg)
        if not msg or msg == "" then return end
        local sent = false
        pcall(function()
            if TextChatService and TextChatService.ChatVersion == Enum.ChatVersion.TextChatService then
                local channels = TextChatService:FindFirstChild("TextChannels")
                local rbxGeneral = channels and channels:FindFirstChild("RBXGeneral")
                if rbxGeneral then
                    rbxGeneral:SendAsync(msg)
                    sent = true
                end
            end
        end)
        if sent then return end
        pcall(function()
            local defaultChat = ReplicatedStorage:FindFirstChild("DefaultChatSystemChatEvents")
            local sayMsg = defaultChat and defaultChat:FindFirstChild("SayMessageRequest")
            if sayMsg then
                sayMsg:FireServer(msg, "All")
            end
        end)
    end

    local function onChatReceived(sender, msg)
        if not copyChatEnabled then return end
        local target = resolveTarget()
        if not target or sender ~= target then return end
        if sender == LocalPlayer then return end

        local now = tick()
        if msg == lastParrotMsg and (now - lastParrotTime) < 0.5 then return end
        lastParrotMsg = msg
        lastParrotTime = now

        task.spawn(function()
            task.wait(0.12)
            sendChatMsg(msg)
        end)
    end

    pcall(function()
        if TextChatService then
            TextChatService.MessageReceived:Connect(function(textChatMessage)
                if textChatMessage.TextSource then
                    local sender = Players:GetPlayerByUserId(textChatMessage.TextSource.UserId)
                    if sender then
                        onChatReceived(sender, textChatMessage.Text)
                    end
                end
            end)
        end
    end)

    local function hookPlayerLegacyChat(p)
        p.Chatted:Connect(function(msg)
            onChatReceived(p, msg)
        end)
    end
    for _, p in ipairs(Players:GetPlayers()) do
        hookPlayerLegacyChat(p)
    end
    Players.PlayerAdded:Connect(hookPlayerLegacyChat)

    
    local copyMoveConn = nil
    local noClipMoveConn = nil

    local function stopCopyMovement()
        if copyMoveConn then copyMoveConn:Disconnect(); copyMoveConn = nil end
        if noClipMoveConn then noClipMoveConn:Disconnect(); noClipMoveConn = nil end
        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum then
            hum:Move(Vector3.zero, false)
            hum.WalkSpeed = 16
        end
    end

    local function startCopyMovement()
        stopCopyMovement()
        local target = resolveTarget()
        if not target then
            notify("Copy Movement", "Select a target first")
            return false
        end

        noClipMoveConn = RunService.Stepped:Connect(function()
            local char = LocalPlayer.Character
            if char then
                for _, part in ipairs(char:GetDescendants()) do
                    if part:IsA("BasePart") and part.CanCollide and part.Name ~= "HumanoidRootPart" then
                        part.CanCollide = false
                    end
                end
            end
        end)

        copyMoveConn = RunService.RenderStepped:Connect(function(dt)
            local currentTarget = resolveTarget()
            if not currentTarget or not currentTarget.Character then return end
            local tChar = currentTarget.Character
            local tHrp = tChar:FindFirstChild("HumanoidRootPart")
            local tHum = tChar:FindFirstChildOfClass("Humanoid")
            if not tHrp or not tHum then return end

            local myChar = LocalPlayer.Character
            if not myChar then return end
            local myHrp = myChar:FindFirstChild("HumanoidRootPart")
            local myHum = myChar:FindFirstChildOfClass("Humanoid")
            if not myHrp or not myHum then return end

            if myHum.WalkSpeed ~= tHum.WalkSpeed then
                myHum.WalkSpeed = tHum.WalkSpeed
            end

            if tHum.Jump or tHum:GetState() == Enum.HumanoidStateType.Jumping then
                myHum.Jump = true
            end

            if tHum.Sit and not myHum.Sit then
                myHum.Sit = true
            elseif not tHum.Sit and myHum.Sit then
                myHum.Sit = false
                pcall(function() myHum:ChangeState(Enum.HumanoidStateType.GettingUp) end)
            end

            local idealPos = myHrp.Position
            local lookAtPos = tHrp.Position

            if copyMoveMode == "Mirror" then
                idealPos = tHrp.Position + (tHrp.CFrame.LookVector * copyMoveDistance)
                lookAtPos = tHrp.Position
            elseif copyMoveMode == "Follow" then
                idealPos = tHrp.Position - (tHrp.CFrame.LookVector * copyMoveDistance)
                lookAtPos = idealPos + tHrp.CFrame.LookVector
            elseif copyMoveMode == "Exact" then
                idealPos = tHrp.Position + (tHrp.CFrame.RightVector * copyMoveDistance)
                lookAtPos = idealPos + tHrp.CFrame.LookVector
            end

            local distError = (idealPos - myHrp.Position).Magnitude
            if distError > 12 then
                myHrp.CFrame = CFrame.lookAt(idealPos, Vector3.new(lookAtPos.X, idealPos.Y, lookAtPos.Z))
            else
                local offset = (idealPos - myHrp.Position)
                local horizontalOffset = Vector3.new(offset.X, 0, offset.Z)
                if horizontalOffset.Magnitude > 0.25 then
                    myHum:Move(horizontalOffset.Unit, false)
                else
                    myHum:Move(Vector3.zero, false)
                end
                local targetRot = CFrame.lookAt(myHrp.Position, Vector3.new(lookAtPos.X, myHrp.Position.Y, lookAtPos.Z))
                myHrp.CFrame = myHrp.CFrame:Lerp(targetRot, math.clamp(dt * 15, 0, 1))
            end
        end)
        return true
    end

    
    local stalkerRunning = false
    local stalkerThread = nil
    local lastRelocateTime = 0
    local isRelocating = false

    local function findGroundLevel(pos, ignoreList)
        local rayParams = RaycastParams.new()
        rayParams.FilterType = Enum.RaycastFilterType.Exclude
        rayParams.FilterDescendantsInstances = ignoreList or {}
        local res = workspace:Raycast(pos + Vector3.new(0, 10, 0), Vector3.new(0, -60, 0), rayParams)
        if res then
            return res.Position.Y
        end
        return pos.Y
    end

    local function calculateStalkPosition(tHrp, myChar)
        local tPos = tHrp.Position
        local tCF = tHrp.CFrame
        local chosenMode = stalkPositionMode

        if chosenMode == "Dynamic" then
            local modes = { "Behind", "Rooftops", "Corners" }
            chosenMode = modes[math.random(1, #modes)]
        end

        local candidate = tPos
        local ignore = { myChar, tHrp.Parent }

        if chosenMode == "Behind" then
            local angle = math.rad(math.random(-50, 50))
            local dist = stalkDistance + math.random(-4, 6)
            local offset = CFrame.Angles(0, angle, 0) * Vector3.new(0, 0, dist)
            candidate = tCF:PointToWorldSpace(offset)
            local groundY = findGroundLevel(candidate, ignore)
            candidate = Vector3.new(candidate.X, groundY + 3, candidate.Z)

        elseif chosenMode == "Rooftops" then
            local foundElevated = false
            for attempt = 1, 8 do
                local ang = math.rad(math.random(0, 360))
                local dist = stalkDistance + math.random(-5, 10)
                local sample = tPos + Vector3.new(math.sin(ang) * dist, 0, math.cos(ang) * dist)
                local highY = findGroundLevel(sample + Vector3.new(0, 25, 0), ignore)
                if (highY - tPos.Y) >= 10 then
                    candidate = Vector3.new(sample.X, highY + 3, sample.Z)
                    foundElevated = true
                    break
                end
            end
            if not foundElevated then
                local offset = Vector3.new(math.random(-15, 15), 0, stalkDistance)
                candidate = tCF:PointToWorldSpace(offset)
                local groundY = findGroundLevel(candidate, ignore)
                candidate = Vector3.new(candidate.X, groundY + 3, candidate.Z)
            end

        elseif chosenMode == "Corners" then
            local side = (math.random(1, 2) == 1) and 1 or -1
            local offset = Vector3.new(side * (stalkDistance * 0.7), 0, (stalkDistance * 0.8))
            candidate = tCF:PointToWorldSpace(offset)
            local groundY = findGroundLevel(candidate, ignore)
            candidate = Vector3.new(candidate.X, groundY + 3, candidate.Z)
        end

        return candidate
    end

    local function isTargetLookingAtUs(tChar, myChar)
        local tHead = tChar:FindFirstChild("Head") or tChar:FindFirstChild("HumanoidRootPart")
        local myHrp = myChar:FindFirstChild("HumanoidRootPart")
        if not tHead or not myHrp then return false end

        local toUs = (myHrp.Position - tHead.Position)
        local dist = toUs.Magnitude
        if dist < 0.1 then return false end
        local dir = toUs.Unit

        local lookDot = tHead.CFrame.LookVector:Dot(dir)
        if lookDot > 0.45 then
            local rayParams = RaycastParams.new()
            rayParams.FilterType = Enum.RaycastFilterType.Exclude
            rayParams.FilterDescendantsInstances = { tChar, myChar }
            local res = workspace:Raycast(tHead.Position, toUs, rayParams)
            if not res or (res.Instance and res.Instance:IsDescendantOf(myChar)) then
                return true
            end
        end
        return false
    end

    local function relocateStalker(tHrp, myChar)
        if isRelocating then return end
        isRelocating = true
        local myHrp = myChar:FindFirstChild("HumanoidRootPart")
        if not myHrp then isRelocating = false; return end

        local newPos = calculateStalkPosition(tHrp, myChar)
        myHrp.CFrame = CFrame.lookAt(newPos, Vector3.new(tHrp.Position.X, newPos.Y, tHrp.Position.Z))
        myHrp.AssemblyLinearVelocity = Vector3.zero
        lastRelocateTime = tick()
        task.wait(0.2)
        isRelocating = false
    end

    local function startStalker()
        stalkerRunning = true
        lastRelocateTime = 0
        isRelocating = false

        stalkerThread = task.spawn(function()
            while stalkerRunning do
                local target = resolveTarget()
                local myChar = LocalPlayer.Character
                local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
                local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")

                if target and target.Character and myHrp and myHum then
                    local tChar = target.Character
                    local tHrp = tChar:FindFirstChild("HumanoidRootPart")
                    if tHrp then
                        local dist = (myHrp.Position - tHrp.Position).Magnitude

                        if dist > 110 or dist < 8 or lastRelocateTime == 0 then
                            relocateStalker(tHrp, myChar)
                        else
                            myHrp.CFrame = CFrame.lookAt(myHrp.Position, Vector3.new(tHrp.Position.X, myHrp.Position.Y, tHrp.Position.Z))
                            myHum:Move(Vector3.zero, false)

                            if stalkFleeOnSight and not isRelocating then
                                if isTargetLookingAtUs(tChar, myChar) then
                                    task.wait(0.15)
                                    if stalkerRunning and target.Character then
                                        relocateStalker(tHrp, myChar)
                                    end
                                end
                            end

                            if tick() - lastRelocateTime > 16 and not isRelocating then
                                relocateStalker(tHrp, myChar)
                            end
                        end
                    end
                end
                task.wait(0.08)
            end
        end)
    end

    local function stopStalker()
        stalkerRunning = false
        if stalkerThread then
            pcall(function() task.cancel(stalkerThread) end)
            stalkerThread = nil
        end
        isRelocating = false
    end

    
    TrollV2Tab:AddSection({ "> Stalker & Mimic" })

    local function getPlayerList()
        local list = {}
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer then
                table.insert(list, p.Name)
            end
        end
        return list
    end

    local stalkTargetDropdown = TrollV2Tab:AddDropdown({
        Name = "Stalk Target",
        Description = "Target player for Mimic and Stalker features",
        Options = getPlayerList(),
        Default = _G.TrollTarget or "---",
        Callback = function(val)
            stalkSelectedTarget = val
            _G.StalkTarget = val
        end
    })

    TrollV2Tab:AddButton({
        Name = "Refresh Player List",
        Description = "Update the player selection dropdown",
        Callback = function()
            local opts = getPlayerList()
            pcall(function() stalkTargetDropdown:Set(opts) end)
        end
    })

    _G.BTR_CopyChatToggle = TrollV2Tab:AddToggle({
        Name = "Copy Chat",
        Description = "Automatically repeats anything the target says in chat",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            copyChatEnabled = val
            if val then
                local target = resolveTarget()
                if not target then
                    notify("Copy Chat", "Select a target first")
                    pcall(function() _G.BTR_CopyChatToggle:Set(false) end)
                    copyChatEnabled = false
                    return
                end

                
                if _G.BTR_AUTOLOAD_OUTFIT then
                    pcall(function()
                        local slotToLoad = tonumber(_G.BTR_AUTOLOAD_SLOT) or 3
                        local RS = game:GetService("ReplicatedStorage")
                        local remotes = RS:FindFirstChild("Remotes")
                        local loadRemote = remotes and remotes:FindFirstChild("LoadOutfit")
                        if loadRemote then
                            loadRemote:InvokeServer(slotToLoad)
                        end
                    end)
                end

                notify("Copy Chat", "Enabled for " .. target.Name)
            else
                notify("Copy Chat", "Disabled")
            end
        end
    })

    _G.BTR_CopyMoveToggle = TrollV2Tab:AddToggle({
        Name = "Copy Movement",
        Description = "Mirrors or follows target movement in real-time",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            copyMoveEnabled = val
            if val then
                local ok = startCopyMovement()
                if not ok then
                    pcall(function() _G.BTR_CopyMoveToggle:Set(false) end)
                    copyMoveEnabled = false
                else
                    local target = resolveTarget()
                    notify("Copy Movement", "Active on " .. (target and target.Name or "target"))
                end
            else
                stopCopyMovement()
                notify("Copy Movement", "Disabled")
            end
        end
    })

    TrollV2Tab:AddDropdown({
        Name = "Movement Mode",
        Description = "Mirror (facing reflection), Follow (bodyguard), Exact (synchronous)",
        Options = { "Mirror", "Follow", "Exact" },
        Default = "Mirror",
        Callback = function(val)
            copyMoveMode = val
        end
    })

    TrollV2Tab:AddSlider({
        Name = "Movement Distance",
        Description = "Distance kept from the target",
        Min = 3,
        Max = 25,
        Default = 6,
        Suffix = " studs",
        Callback = function(val)
            copyMoveDistance = val
        end
    })

    _G.BTR_StalkerToggle = TrollV2Tab:AddToggle({
        Name = "Stalker Mode",
        Description = "Haunts the target from creepy vantage points and flees when seen",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            stalkerEnabled = val
            if val then
                local target = resolveTarget()
                if not target then
                    notify("Stalker Mode", "Select a target first")
                    pcall(function() _G.BTR_StalkerToggle:Set(false) end)
                    stalkerEnabled = false
                    return
                end
                startStalker()
                notify("Stalker Mode", "Stalking " .. target.Name)
            else
                stopStalker()
                notify("Stalker Mode", "Disabled")
            end
        end
    })

    TrollV2Tab:AddDropdown({
        Name = "Stalk Position",
        Description = "Where the stalker lurks relative to the target",
        Options = { "Dynamic", "Behind", "Rooftops", "Corners" },
        Default = "Dynamic",
        Callback = function(val)
            stalkPositionMode = val
        end
    })

    TrollV2Tab:AddSlider({
        Name = "Stalk Distance",
        Description = "Distance from target while lurking",
        Min = 15,
        Max = 70,
        Default = 30,
        Suffix = " studs",
        Callback = function(val)
            stalkDistance = val
        end
    })

    TrollV2Tab:AddToggle({
        Name = "Flee on Sight",
        Description = "Instantly vanish to a new spot when the target looks at you",
        Default = true,
        Callback = function(val)
            stalkFleeOnSight = val
        end
    })
end
_btrInitStalkerMimic()

local function _btrInitDoorOrbit()
    TrollV2Tab:AddSection({ "> Door Fling / Orbit" })

    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local Workspace = game:GetService("Workspace")
    local StarterGui = game:GetService("StarterGui")
    local LocalPlayer = Players.LocalPlayer

    local isRunning = false
    local controlledDoors = {}
    local connections = {}
    local blackHolePart = nil
    local baseAttachment = nil

    local function notify(title, text)
        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = title,
                Text = text,
                Duration = 3
            })
        end)
    end

    local function cleanDoor(part)
        pcall(function()
            if not part or not part.Parent then return end
            part.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
            part.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
            part.CanCollide = false
            for _, child in ipairs(part:GetChildren()) do
                if child:IsA("AlignPosition") or child:IsA("Torque") or child:IsA("Attachment") or child.Name == "Luscaa_Attached" then
                    child:Destroy()
                end
            end
            task.delay(0.8, function()
                pcall(function()
                    if part and part.Parent and not isRunning then
                        part.CanCollide = true
                    end
                end)
            end)
        end)
    end

    local function setupDoor(part)
        if not isRunning or not baseAttachment or not baseAttachment.Parent then return end
        if not part:IsA("BasePart") or not string.find(part.Name:lower(), "door") then return end
        if part:FindFirstChild("Luscaa_Attached") then return end

        pcall(function()
            part.CanCollide = false
            part.Anchored = false
            part:BreakJoints()
        end)

        for _, obj in ipairs(part:GetChildren()) do
            if obj:IsA("AlignPosition") or obj:IsA("Torque") or obj:IsA("Attachment") then
                obj:Destroy()
            end
        end

        local marker = Instance.new("BoolValue")
        marker.Name = "Luscaa_Attached"
        marker.Parent = part

        local doorAttachment = Instance.new("Attachment")
        doorAttachment.Name = "DoorAttachment"
        doorAttachment.Parent = part

        local align = Instance.new("AlignPosition")
        align.Attachment0 = doorAttachment
        align.Attachment1 = baseAttachment
        align.MaxForce = 1e20
        align.MaxVelocity = math.huge
        align.Responsiveness = 99999
        align.Parent = part

        local torque = Instance.new("Torque")
        torque.Attachment0 = doorAttachment
        torque.RelativeTo = Enum.ActuatorRelativeTo.World
        torque.Torque = Vector3.new(
            math.random(-10e5, 10e5) * 10000,
            math.random(-10e5, 10e5) * 10000,
            math.random(-10e5, 10e5) * 10000
        )
        torque.Parent = part

        table.insert(controlledDoors, { Part = part, Align = align })
    end

    local function _0xH_40f()
        isRunning = false
        for _, conn in ipairs(connections) do
            if conn and conn.Connected then
                conn:Disconnect()
            end
        end
        connections = {}

        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if hrp then
            hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
            hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
        end

        for _, data in ipairs(controlledDoors) do
            cleanDoor(data.Part)
        end
        controlledDoors = {}

        if blackHolePart and blackHolePart.Parent then
            blackHolePart:Destroy()
            blackHolePart = nil
        end
        baseAttachment = nil

        task.spawn(function()
            local start = tick()
            while tick() - start < 0.5 do
                if hrp and hrp.Parent then
                    hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                    hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                end
                RunService.Heartbeat:Wait()
            end
        end)

        notify("Door Orbit", "Disabled. Doors safely released")
    end

    local function _0xH_410()
        local char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
        local hrp = char:WaitForChild("HumanoidRootPart")
        isRunning = true

        pcall(function()
            sethiddenproperty(LocalPlayer, "SimulationRadius", math.huge)
            sethiddenproperty(LocalPlayer, "MaximumSimulationRadius", math.huge)
        end)

        blackHolePart = Instance.new("Part")
        blackHolePart.Size = Vector3.new(100000, 100000, 100000)
        blackHolePart.Transparency = 1
        blackHolePart.Anchored = true
        blackHolePart.CanCollide = false
        blackHolePart.Name = "BlackHoleTarget"
        blackHolePart.CFrame = hrp.CFrame
        blackHolePart.Parent = Workspace

        baseAttachment = Instance.new("Attachment")
        baseAttachment.Name = "Luscaa_BlackHoleAttachment"
        baseAttachment.Parent = blackHolePart

        local hbConn = RunService.Heartbeat:Connect(function()
            if not isRunning or not blackHolePart or not blackHolePart.Parent then return end
            pcall(function()
                sethiddenproperty(LocalPlayer, "SimulationRadius", math.huge)
                sethiddenproperty(LocalPlayer, "MaximumSimulationRadius", math.huge)
            end)
            local currentChar = LocalPlayer.Character
            local currentHRP = currentChar and currentChar:FindFirstChild("HumanoidRootPart")
            if currentHRP then
                blackHolePart.CFrame = currentHRP.CFrame
            end
        end)
        table.insert(connections, hbConn)

        for _, obj in ipairs(Workspace:GetDescendants()) do
            if obj:IsA("BasePart") and string.find(obj.Name:lower(), "door") then
                setupDoor(obj)
            end
        end

        local descConn = Workspace.DescendantAdded:Connect(function(obj)
            if isRunning and obj:IsA("BasePart") and string.find(obj.Name:lower(), "door") then
                task.wait(0.1)
                setupDoor(obj)
            end
        end)
        table.insert(connections, descConn)

        notify("Door Orbit", "Enabled! Doors are orbiting around you")
    end

    _G.BTR_StopDoorOrbit = _0xH_40f

    LocalPlayer.CharacterAdded:Connect(function()
        if isRunning then
            _0xH_40f()
            if _G.BTR_DoorOrbitToggle then
                pcall(function() _G.BTR_DoorOrbitToggle:Set(false) end)
            end
        end
    end)

    _G.BTR_DoorOrbitToggle = TrollV2Tab:AddToggle({
        Name = "Door Orbit Fling",
        Description = "Controls map doors to orbit around you and fling nearby players",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            if val then
                _0xH_410()
            else
                _0xH_40f()
            end
        end
    })
end
_btrInitDoorOrbit()

local function _btrInitOutdoorBillboard()
    TrollV2Tab:AddSection({ "> Outdoor Billboard" })

    local Players = game:GetService("Players")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local Workspace = game:GetService("Workspace")
    local StarterGui = game:GetService("StarterGui")
    local LocalPlayer = Players.LocalPlayer
    local Remotes = ReplicatedStorage:FindFirstChild("RE") or ReplicatedStorage

    
    local BILLBOARD_1 = CFrame.new(-242.68, 89.69, -549.65)
    local BILLBOARD_2 = CFrame.new(-630.48, 26.59, 365.14)

    local isUpdating = false
    local customMessage = "BTR CLIENT // TOTAL CONTROL"

    local function notify(title, text)
        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = title or "Billboard",
                Text = text or "",
                Duration = 3
            })
        end)
    end

    local function getRoot()
        local char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
        return char and char:FindFirstChild("HumanoidRootPart")
    end

    local function fireBillboardRemotes(text)
        if not Remotes then return end
        local remCemetery = Remotes:FindFirstChild("1Cemeter1y")
        if remCemetery then
            for spot = 1, 3 do
                pcall(function()
                    remCemetery:FireServer("ReturningCommercialWords", spot, nil, text)
                end)
                pcall(function()
                    remCemetery:FireServer("CommercialWordColor", spot, Color3.fromRGB(255, 255, 255))
                end)
                pcall(function()
                    remCemetery:FireServer("CommercialBackGround", spot, Color3.fromRGB(0, 0, 0))
                end)
            end
        end
        local remCommercial = Remotes:FindFirstChild("1Commercial1s") or Remotes:FindFirstChild("1Commercial")
        if remCommercial then
            for spot = 1, 3 do
                pcall(function() remCommercial:FireServer("ReturningCommercialWords", spot, nil, text) end)
                pcall(function() remCommercial:FireServer("BillboardText", spot, text) end)
            end
        end
        local remSign = Remotes:FindFirstChild("1Sign")
        if remSign then
            pcall(function() remSign:FireServer("BillboardText", text) end)
        end
    end

    local function runBillboardSequence(message)
        if isUpdating then
            notify("Billboard", "Sequence already in progress, please wait...")
            return
        end

        local root = getRoot()
        if not root then
            notify("Billboard", "Character or HumanoidRootPart not found!")
            return
        end

        isUpdating = true
        task.spawn(function()
            local origCF = root.CFrame
            notify("Billboard", "Starting cycle: Teleporting to Billboard 1...")

            
            pcall(function()
                root.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                root.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                root.CFrame = BILLBOARD_1 + Vector3.new(0, 3, 0)
            end)
            task.wait(0.5)
            fireBillboardRemotes(message)
            task.wait(0.5)

            
            notify("Billboard", "Teleporting to Billboard 2...")
            pcall(function()
                root.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                root.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                root.CFrame = BILLBOARD_2 + Vector3.new(0, 3, 0)
            end)
            task.wait(0.5)
            fireBillboardRemotes(message)
            task.wait(0.5)

            
            pcall(function()
                root.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                root.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                root.CFrame = origCF
            end)
            notify("Billboard", "Billboards updated on server & returned to initial position!")
            isUpdating = false
        end)
    end

    _G.BTR_StopBillboardSequence = function()
        isUpdating = false
    end

    
    local PRESET_1 = "BTR CLIENT // TOTAL CONTROL"
    local PRESET_2 = "THE MATRIX HAS YOU // BTR"
    local PRESET_3 = "ERROR 404: REALITY NOT FOUND"

    TrollV2Tab:AddButton({
        Name = "Preset: TOTAL CONTROL",
        Description = "Applies '" .. PRESET_1 .. "' on Highway & Lake, then returns",
        Callback = function()
            runBillboardSequence(PRESET_1)
        end
    })

    TrollV2Tab:AddButton({
        Name = "Preset: THE MATRIX",
        Description = "Applies '" .. PRESET_2 .. "' on Highway & Lake, then returns",
        Callback = function()
            runBillboardSequence(PRESET_2)
        end
    })

    TrollV2Tab:AddButton({
        Name = "Preset: ERROR 404",
        Description = "Applies '" .. PRESET_3 .. "' on Highway & Lake, then returns",
        Callback = function()
            runBillboardSequence(PRESET_3)
        end
    })

    TrollV2Tab:AddTextBox({
        Name = "Custom Billboard Message",
        PlaceholderText = "Enter custom message...",
        Default = "",
        Callback = function(text)
            if text and text ~= "" then
                customMessage = text
            end
        end
    })

    TrollV2Tab:AddButton({
        Name = "Apply Custom Billboard",
        Description = "Applies custom message on Highway & Lake, then returns",
        Callback = function()
            if customMessage and customMessage ~= "" then
                runBillboardSequence(customMessage)
            else
                notify("Billboard", "Please enter a custom message first!")
            end
        end
    })
end
_btrInitOutdoorBillboard()

local function _btrInitStealItems()
    TrollV2Tab:AddSection({ "> Steal Items" })

    local Players = game:GetService("Players")
    local Workspace = game:GetService("Workspace")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local StarterGui = game:GetService("StarterGui")
    local LocalPlayer = Players.LocalPlayer

    local Remotes = ReplicatedStorage:FindFirstChild("RE") or ReplicatedStorage
    local RemoteTool = Remotes and Remotes:FindFirstChild("1Too1l")

    local function notify(title, text)
        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = title or "Steal Items",
                Text = text or "",
                Duration = 3
            })
        end)
    end

    local function getRoot()
        local char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
        return char and char:FindFirstChild("HumanoidRootPart")
    end

    local selectedStealTarget = "---"

    local function getPlayerNames()
        local list = {"---"}
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer then
                table.insert(list, p.Name)
            end
        end
        return list
    end

    local function getTargetPlayer()
        if selectedStealTarget and selectedStealTarget ~= "---" then
            local p = Players:FindFirstChild(selectedStealTarget)
            if p then return p end
        end
        if _G.TrollTarget and _G.TrollTarget ~= "---" then
            local p = Players:FindFirstChild(_G.TrollTarget)
            if p then return p end
        end
        return nil
    end

    local stealDropdown = TrollV2Tab:AddDropdown({
        Name = "Target Player",
        Description = "Choose the player to steal items from",
        Options = getPlayerNames(),
        Default = "---",
        Callback = function(val)
            selectedStealTarget = val
        end
    })

    Players.PlayerAdded:Connect(function()
        pcall(function()
            if stealDropdown and stealDropdown.SetOptions then
                stealDropdown:SetOptions(getPlayerNames())
            end
        end)
    end)
    Players.PlayerRemoving:Connect(function()
        pcall(function()
            if stealDropdown and stealDropdown.SetOptions then
                stealDropdown:SetOptions(getPlayerNames())
            end
        end)
    end)

    
    TrollV2Tab:AddButton({
        Name = "Steal Items (Target Player)",
        Description = "Clones and steals all tools from selected target player",
        Callback = function()
            local target = getTargetPlayer()
            if not target or not target.Character then
                notify("Steal Items", "Please select a target player in the dropdown above!")
                return
            end
            local count = 0
            if RemoteTool then
                for _, t in ipairs(target.Character:GetChildren()) do
                    if t:IsA("Tool") then
                        pcall(function() RemoteTool:InvokeServer("PickingTools", t.Name) end)
                        count = count + 1
                    end
                end
                if target:FindFirstChild("Backpack") then
                    for _, t in ipairs(target.Backpack:GetChildren()) do
                        if t:IsA("Tool") then
                            pcall(function() RemoteTool:InvokeServer("PickingTools", t.Name) end)
                            count = count + 1
                        end
                    end
                end
            end
            notify("Steal Items", "Stole " .. count .. " items from " .. target.Name)
        end
    })

    
    TrollV2Tab:AddButton({
        Name = "Steal Items (All Players & Map)",
        Description = "Vacuums dropped map tools and clones all player inventory tools",
        Callback = function()
            local count = 0
            local root = getRoot()
            for _, obj in ipairs(Workspace:GetChildren()) do
                if obj:IsA("Tool") and obj:FindFirstChild("Handle") and root then
                    pcall(function()
                        if firetouchinterest then
                            firetouchinterest(root, obj.Handle, 0)
                            firetouchinterest(root, obj.Handle, 1)
                        else
                            obj.Handle.CFrame = root.CFrame
                        end
                        count = count + 1
                    end)
                end
            end
            if RemoteTool then
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= LocalPlayer and p.Character then
                        for _, t in ipairs(p.Character:GetChildren()) do
                            if t:IsA("Tool") then
                                pcall(function() RemoteTool:InvokeServer("PickingTools", t.Name) end)
                                count = count + 1
                            end
                        end
                        if p:FindFirstChild("Backpack") then
                            for _, t in ipairs(p.Backpack:GetChildren()) do
                                if t:IsA("Tool") then
                                    pcall(function() RemoteTool:InvokeServer("PickingTools", t.Name) end)
                                    count = count + 1
                                end
                            end
                        end
                    end
                end
            end
            notify("Steal Items", "Stole total " .. count .. " items across all players & map!")
        end
    })
end
_btrInitStealItems()

local function _btrInitCouchMethod()
    local Players = game:GetService("Players")
    local Workspace = game:GetService("Workspace")
    local RunService = game:GetService("RunService")
    local CoreGui = game:GetService("CoreGui")
    local StarterGui = game:GetService("StarterGui")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local LocalPlayer = Players.LocalPlayer

    pcall(function() Workspace.FallenPartsDestroyHeight = 0/0 end)
    pcall(function() Workspace.FallenPartsDestroyHeight = -50000 end)

    local selectedCouchTarget = "---"
    local selectedCouchDest = "---"
    local PROTECTED_NAME = "tii_mada0972"

    local function getCouchPlayerNames()
        local list = {"---"}
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer and p.Name:lower() ~= PROTECTED_NAME:lower() then
                table.insert(list, p.Name)
            end
        end
        return list
    end

    local function notifyCouch(title, text)
        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = title or "BTR Couch",
                Text = text or "",
                Duration = 3
            })
        end)
    end

    local function zeroAllVelocities(char)
        if not char then return end
        for _, p in ipairs(char:GetDescendants()) do
            if p:IsA("BasePart") then
                p.AssemblyLinearVelocity = Vector3.zero
                p.AssemblyAngularVelocity = Vector3.zero
                p.Velocity = Vector3.zero
                p.RotVelocity = Vector3.zero
            end
        end
    end

    local function GetCouchTarget()
        if not selectedCouchTarget or selectedCouchTarget == "---" then return nil end
        local p = Players:FindFirstChild(selectedCouchTarget)
        if p and p.Name:lower() ~= PROTECTED_NAME:lower() and p ~= LocalPlayer then
            return p
        end
        return nil
    end

    local function GetCouchDest()
        if not selectedCouchDest or selectedCouchDest == "---" then return nil end
        local p = Players:FindFirstChild(selectedCouchDest)
        if p and p ~= LocalPlayer then
            return p
        end
        return nil
    end

    local CouchEngine = {
        Active = false,
        CurrentThread = nil,
        SteppedConn = nil
    }

    function CouchEngine.stop()
        CouchEngine.Active = false
        if CouchEngine.CurrentThread then
            task.cancel(CouchEngine.CurrentThread)
            CouchEngine.CurrentThread = nil
        end

        if CouchEngine.SteppedConn then
            CouchEngine.SteppedConn:Disconnect()
            CouchEngine.SteppedConn = nil
        end

        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local hrp = char and char:FindFirstChild("HumanoidRootPart")

        if hum then
            hum:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
            hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
            hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, true)
            hum.PlatformStand = false
            hum.Sit = false
            pcall(function() hum:UnequipTools() end)
        end

        zeroAllVelocities(char)

        if hrp then
            hrp.Anchored = false
        end

        local target = GetCouchTarget()
        if target and target.Character and target.Character:FindFirstChild("HumanoidRootPart") then
            local bp = target.Character.HumanoidRootPart:FindFirstChild("BringPosition")
            if bp then bp:Destroy() end
        end
    end

    function CouchEngine.execute(actionType)
        local target = GetCouchTarget()
        if not target or not target.Character then
            notifyCouch("Couch Method", "Please select a valid target player in the dropdown!")
            return
        end

        local tChar = target.Character
        local tRoot = tChar:FindFirstChild("HumanoidRootPart")
        local tHum = tChar:FindFirstChildOfClass("Humanoid")
        if not tRoot or not tHum or tHum.Health <= 0 then
            notifyCouch("Couch Method", "Target player is dead or invalid!")
            return
        end

        local myChar = LocalPlayer.Character
        local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myChar or not myHum or not myRoot then return end

        CouchEngine.stop()
        CouchEngine.Active = true

        CouchEngine.CurrentThread = task.spawn(function()
            local originalPos = myRoot.CFrame

            local RE = ReplicatedStorage:WaitForChild("RE")
            local clearRem = RE:WaitForChild("1Clea1rTool1s")
            local toolRem = RE:WaitForChild("1Too1l")

            pcall(function()
                toolRem:InvokeServer("PickingTools", "Couch")
            end)

            task.spawn(function()
                local backpack = LocalPlayer:WaitForChild("Backpack")
                local tool = backpack:WaitForChild("Couch", 2) or myChar:FindFirstChild("Couch")
                if tool and tool:IsA("Tool") then
                    tool.Parent = myChar
                    task.wait(1.3)
                    if tool.Parent == myChar then
                        tool.Parent = backpack
                    end
                end
            end)

            local function isTargetSeated()
                if not target or not target.Character then return false end
                local tHumanoid = target.Character:FindFirstChildOfClass("Humanoid")
                if not tHumanoid then return false end

                local couch = myChar:FindFirstChild("Couch")
                if couch then
                    local s1 = couch:FindFirstChild("Seat1")
                    local s2 = couch:FindFirstChild("Seat2")

                    if s1 and s1:IsA("Seat") and s1.Occupant == tHumanoid then
                        return true
                    end
                    if s2 and s2:IsA("Seat") and s2.Occupant == tHumanoid then
                        return true
                    end

                    for _, desc in ipairs(couch:GetDescendants()) do
                        if desc:IsA("Weld") or desc:IsA("Motor6D") then
                            if (desc.Part0 and desc.Part0:IsDescendantOf(target.Character)) or
                               (desc.Part1 and desc.Part1:IsDescendantOf(target.Character)) then
                                return true
                            end
                        end
                    end
                end
                return false
            end

            notifyCouch("Couch Method", "Catching target " .. target.Name .. " (waiting for sit)...")

            local startTime = tick()
            while CouchEngine.Active and (tick() - startTime < 15.0) do
                if isTargetSeated() then break end

                if not target or not target.Character then break end
                local tHumanoid = target.Character:FindFirstChildOfClass("Humanoid")
                local tHrp = tHumanoid and tHumanoid.RootPart
                if not tHrp then break end

                local couchInChar = myChar:FindFirstChild("Couch")
                if not couchInChar then
                    local backpack = LocalPlayer:FindFirstChild("Backpack")
                    local tool = backpack and backpack:FindFirstChild("Couch")
                    if tool then tool.Parent = myChar end
                end

                local rot = CFrame.Angles(
                    math.rad(math.random(-9000, 9000)),
                    math.rad(math.random(-9000, 9000)),
                    math.rad(math.random(-9000, 9000))
                )
                local pos = CFrame.new(math.random(-3, 3), math.random(-3, 3), math.random(-3, 3))
                myRoot.CFrame = tHrp.CFrame * pos * rot
                myChar:SetPrimaryPartCFrame(myRoot.CFrame)
                task.wait(0.01)
            end

            if not isTargetSeated() and not CouchEngine.Active then
                pcall(function() clearRem:FireServer("ClearAllTools") end)
                myRoot.CFrame = originalPos
                myChar:SetPrimaryPartCFrame(originalPos)
                return
            end

            if actionType == "Bring" then
                notifyCouch("Couch Method", "Target seated! Bringing to your position...")
                myRoot.CFrame = originalPos
                myChar:SetPrimaryPartCFrame(originalPos)
                task.wait(1.5)

                myRoot.CFrame = originalPos
                myChar:SetPrimaryPartCFrame(originalPos)
                zeroAllVelocities(myChar)

                pcall(function() clearRem:FireServer("ClearAllTools") end)
                CouchEngine.stop()
                notifyCouch("Couch Method", "Target brought successfully!")

            elseif actionType == "Redirect" then
                local dest = GetCouchDest()
                if not dest or not dest.Character or not dest.Character:FindFirstChild("HumanoidRootPart") then
                    notifyCouch("Couch Method", "Destination player not found! Please select a destination.")
                    myRoot.CFrame = originalPos
                    myChar:SetPrimaryPartCFrame(originalPos)
                    pcall(function() clearRem:FireServer("ClearAllTools") end)
                    CouchEngine.stop()
                    return
                end
                local destPos = dest.Character.HumanoidRootPart.CFrame * CFrame.new(0, 0, 3)
                notifyCouch("Couch Method", "Target seated! Delivering to destination: " .. dest.Name)
                myRoot.CFrame = destPos
                myChar:SetPrimaryPartCFrame(destPos)
                task.wait(1.5)

                myRoot.CFrame = destPos
                myChar:SetPrimaryPartCFrame(destPos)
                zeroAllVelocities(myChar)

                pcall(function() clearRem:FireServer("ClearAllTools") end)
                task.wait(0.2)

                myRoot.CFrame = originalPos
                myChar:SetPrimaryPartCFrame(originalPos)
                zeroAllVelocities(myChar)
                CouchEngine.stop()
                notifyCouch("Couch Method", "Delivered target to " .. dest.Name .. " successfully!")

            elseif actionType == "Kill" then
                notifyCouch("Couch Method", "Target seated! Dropping in Void (Kill)...")
                local killVoidPos = CFrame.new(600.99, -499.29, -92.99)
                myRoot.CFrame = killVoidPos
                myChar:SetPrimaryPartCFrame(killVoidPos)
                task.wait(0.5)

                pcall(function() clearRem:FireServer("ClearAllTools") end)
                task.wait(0.2)

                myRoot.CFrame = originalPos
                myChar:SetPrimaryPartCFrame(originalPos)
                zeroAllVelocities(myChar)
                CouchEngine.stop()
                notifyCouch("Couch Method", "Target eliminated in void!")

            elseif actionType == "Void" then
                notifyCouch("Couch Method", "Target seated! Exiling to 55B Coordinates...")
                local farVoidPos = CFrame.new(-422211026944.00, 1169641963520.00, -45246541824.00)
                myRoot.CFrame = farVoidPos
                myChar:SetPrimaryPartCFrame(farVoidPos)
                task.wait(0.5)

                pcall(function() clearRem:FireServer("ClearAllTools") end)
                task.wait(0.2)

                myRoot.CFrame = originalPos
                myChar:SetPrimaryPartCFrame(originalPos)
                zeroAllVelocities(myChar)
                CouchEngine.stop()
                notifyCouch("Couch Method", "Target exiled to far space!")

            elseif actionType == "Fling" then
                notifyCouch("Couch Method", "Target seated! Flinging into stratosphere...")
                local skyPos = myRoot.CFrame + Vector3.new(0, 120, 0)
                myRoot.CFrame = skyPos
                myChar:SetPrimaryPartCFrame(skyPos)
                task.wait(0.1)

                local bodyAngularVel = Instance.new("BodyAngularVelocity")
                bodyAngularVel.Name = "CouchFlingSpin"
                bodyAngularVel.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
                bodyAngularVel.AngularVelocity = Vector3.new(0, 99999, 0)
                bodyAngularVel.Parent = myRoot

                local bodyVel = Instance.new("BodyVelocity")
                bodyVel.Name = "CouchFlingVel"
                bodyVel.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                bodyVel.Velocity = (myRoot.CFrame.LookVector * 500) + Vector3.new(0, 250, 0)
                bodyVel.Parent = myRoot

                task.wait(0.3)

                pcall(function() clearRem:FireServer("ClearAllTools") end)
                task.wait(0.2)

                if bodyAngularVel and bodyAngularVel.Parent then bodyAngularVel:Destroy() end
                if bodyVel and bodyVel.Parent then bodyVel:Destroy() end

                myRoot.CFrame = originalPos
                myChar:SetPrimaryPartCFrame(originalPos)
                zeroAllVelocities(myChar)
                CouchEngine.stop()
                notifyCouch("Couch Method", "Target flung successfully!")
            end
        end)
    end

    TrollV2Tab:AddSection({
        "> Couch Method"
    })

    local couchTargetDropdown = TrollV2Tab:AddDropdown({
        Name = "Target Player",
        Description = "Choose the player to catch on the Couch",
        Options = getCouchPlayerNames(),
        Default = "---",
        Callback = function(val)
            selectedCouchTarget = val
        end
    })

    local couchDestDropdown = TrollV2Tab:AddDropdown({
        Name = "Destination Player (For Redirect)",
        Description = "Choose destination player to deliver the target to",
        Options = getCouchPlayerNames(),
        Default = "---",
        Callback = function(val)
            selectedCouchDest = val
        end
    })

    TrollV2Tab:AddButton({
        Name = "Refresh Couch Player Lists",
        Description = "Refreshes player dropdown lists for Couch Method",
        Callback = function()
            local list = getCouchPlayerNames()
            pcall(function()
                if couchTargetDropdown and couchTargetDropdown.SetOptions then
                    couchTargetDropdown:SetOptions(list)
                end
                if couchDestDropdown and couchDestDropdown.SetOptions then
                    couchDestDropdown:SetOptions(list)
                end
            end)
            notifyCouch("Couch Method", "Player list refreshed!")
        end
    })

    Players.PlayerAdded:Connect(function()
        pcall(function()
            local list = getCouchPlayerNames()
            if couchTargetDropdown and couchTargetDropdown.SetOptions then
                couchTargetDropdown:SetOptions(list)
            end
            if couchDestDropdown and couchDestDropdown.SetOptions then
                couchDestDropdown:SetOptions(list)
            end
        end)
    end)

    Players.PlayerRemoving:Connect(function()
        pcall(function()
            local list = getCouchPlayerNames()
            if couchTargetDropdown and couchTargetDropdown.SetOptions then
                couchTargetDropdown:SetOptions(list)
            end
            if couchDestDropdown and couchDestDropdown.SetOptions then
                couchDestDropdown:SetOptions(list)
            end
        end)
    end)

    TrollV2Tab:AddButton({
        Name = "Couch Bring (To Me)",
        Description = "Catches the selected player and brings them to your position",
        Callback = function()
            CouchEngine.execute("Bring")
        end
    })

    TrollV2Tab:AddButton({
        Name = "Couch Redirect (To Player)",
        Description = "Catches the selected player and delivers them to the destination player",
        Callback = function()
            CouchEngine.execute("Redirect")
        end
    })

    TrollV2Tab:AddButton({
        Name = "Couch Kill (Drop Void)",
        Description = "Catches the selected player and drops them into the map void",
        Callback = function()
            CouchEngine.execute("Kill")
        end
    })

    TrollV2Tab:AddButton({
        Name = "Couch Void (55B Far Space)",
        Description = "Catches the selected player and exiles them into 55 billion far space",
        Callback = function()
            CouchEngine.execute("Void")
        end
    })

    TrollV2Tab:AddButton({
        Name = "Couch Fling (Spin High Altitude)",
        Description = "Catches the selected player and spins them at extreme speed into the stratosphere",
        Callback = function()
            CouchEngine.execute("Fling")
        end
    })

    TrollV2Tab:AddButton({
        Name = "Stop Couch Action",
        Description = "Instantly aborts current Couch operation and restores your character",
        Callback = function()
            CouchEngine.stop()
            notifyCouch("Couch Method", "Couch action stopped.")
        end
    })
end
_btrInitCouchMethod()

                           
local function _btrInitTrollV3GunFling()
    if not TrollV3Tab then return end

    TrollV3Tab:AddSection({
        "> Gun Fling (FE)"
    })

    local Players           = game:GetService("Players")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
