    local function getGuiContainer()
        if gethui then
            local h = gethui()
            if h then return h end
        end
        local success, _ = pcall(function() return CoreGui.Name end)
        if success then return CoreGui end
        return lp:WaitForChild("PlayerGui")
    end

    local function enableSimulationMax()
        pcall(function()
            lp.ReplicationFocus = Workspace
            if setscriptable then
                setscriptable(lp, "SimulationRadius", true)
                setscriptable(lp, "MaximumSimulationRadius", true)
            end
            if sethiddenproperty then
                sethiddenproperty(lp, "MaximumSimulationRadius", math.huge)
                sethiddenproperty(lp, "SimulationRadius", math.huge)
            end
        end)
    end

    local function safeFreezeDoor(part)
        pcall(function()
            if not part or not part.Parent then return end
            part.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
            part.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
            part.CanCollide = false
            for _, child in ipairs(part:GetChildren()) do
                if child:IsA("AlignPosition") or child:IsA("Torque") or child:IsA("Attachment") or child.Name == "Luscaa_Attached" then
                    child:Destroy()
                end
            end
            part.Anchored = true
        end)
    end

    local function setupDoor(part)
        if not isExecuting or not baseAttachment or not baseAttachment.Parent then return end
        if not part:IsA("BasePart") or not string.find(part.Name:lower(), "door") then return end
        if part:FindFirstChild("Luscaa_Attached") then return end

        pcall(function()
            part.CanCollide = false
            part.Anchored = false
            part:BreakJoints()
        end)

        for _, obj in ipairs(part:GetChildren()) do
            if obj:IsA("AlignPosition") or obj:IsA("Torque") or obj:IsA("Attachment") then
                obj:Destroy()
            end
        end

        local marker = Instance.new("BoolValue")
        marker.Name = "Luscaa_Attached"
        marker.Parent = part

        local doorAttachment = Instance.new("Attachment")
        doorAttachment.Name = "DoorAttachment"
        doorAttachment.Parent = part

        local align = Instance.new("AlignPosition")
        align.Attachment0 = doorAttachment
        align.Attachment1 = baseAttachment
        align.MaxForce = 1e20
        align.MaxVelocity = math.huge
        align.Responsiveness = 99999
        align.Parent = part

        local torque = Instance.new("Torque")
        torque.Attachment0 = doorAttachment
        torque.RelativeTo = Enum.ActuatorRelativeTo.World
        torque.Torque = Vector3.new(
            math.random(-10e5, 10e5) * 10000,
            math.random(-10e5, 10e5) * 10000,
            math.random(-10e5, 10e5) * 10000
        )
        torque.Parent = part

        table.insert(controlledDoors, { Part = part, Align = align })
    end

    local function cleanAllDoors()
        isExecuting = false
        for _, conn in ipairs(executionConnections) do
            if conn and conn.Connected then
                conn:Disconnect()
            end
        end
        executionConnections = {}

        for _, data in ipairs(controlledDoors) do
            safeFreezeDoor(data.Part)
        end
        controlledDoors = {}

        if blackHolePart and blackHolePart.Parent then
            blackHolePart:Destroy()
            blackHolePart = nil
        end
        baseAttachment = nil
        executingTarget = nil
    end

    local function resetPlayerHealthToFull(targetPlayer)
        playerHealthMap[targetPlayer] = 100
        local uiData = playerGuis[targetPlayer]
        if uiData and uiData.fill and uiData.lbl then
            TweenService:Create(uiData.fill, TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Size = UDim2.new(1, 0, 1, 0),
                BackgroundColor3 = Color3.fromRGB(0, 230, 110)
            }):Play()
            uiData.lbl.Text = targetPlayer.DisplayName .. " [100 HP]"
        end
    end

    local function launchDoorExecution(targetPlayer)
        if not targetPlayer or not targetPlayer.Character then return end
        if executingTarget ~= nil then return end
        executingTarget = targetPlayer

        local char = targetPlayer.Character
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if not hrp then executingTarget = nil; return end

        if isExecuting then cleanAllDoors() end
        isExecuting = true

        enableSimulationMax()

        blackHolePart = Instance.new("Part")
        blackHolePart.Size = Vector3.new(100000, 100000, 100000)
        blackHolePart.Transparency = 1
        blackHolePart.Anchored = true
        blackHolePart.CanCollide = false
        blackHolePart.Name = "BlackHoleTarget"
        blackHolePart.CFrame = hrp.CFrame
        blackHolePart.Parent = Workspace

        baseAttachment = Instance.new("Attachment")
        baseAttachment.Name = "Luscaa_BlackHoleAttachment"
        baseAttachment.Parent = blackHolePart

        local initialChar = targetPlayer.Character
        local startTime = tick()

        local hbStrikeConn
        local function finishExecution()
            if hbStrikeConn then hbStrikeConn:Disconnect() end
            cleanAllDoors()
            resetPlayerHealthToFull(targetPlayer)

            if screenGui and screenGui.Parent then
                task.spawn(function()
                    local killBanner = Instance.new("Frame")
                    killBanner.Size = UDim2.new(0, 380, 0, 50)
                    killBanner.Position = UDim2.new(0.5, -190, 0.18, 0)
                    killBanner.BackgroundColor3 = Color3.fromRGB(15, 18, 26)
                    killBanner.BorderSizePixel = 0
                    killBanner.Parent = screenGui
                    local kbC = Instance.new("UICorner")
                    kbC.CornerRadius = UDim.new(0, 8)
                    kbC.Parent = killBanner
                    local kbS = Instance.new("UIStroke")
                    kbS.Color = Color3.fromRGB(0, 220, 130)
                    kbS.Thickness = 1.5
                    kbS.Parent = killBanner

                    local kbText = Instance.new("TextLabel")
                    kbText.Size = UDim2.new(1, 0, 1, 0)
                    kbText.BackgroundTransparency = 1
                    kbText.Text = "DOOR FLING COMPLETED // TARGET ELIMINATED\n" .. targetPlayer.DisplayName .. " HEALTH RESTORED TO 100%"
                    kbText.Font = Enum.Font.GothamBold
                    kbText.TextSize = 11
                    kbText.TextColor3 = Color3.fromRGB(230, 255, 240)
                    kbText.Parent = killBanner

                    task.wait(3.5)
                    if killBanner and killBanner.Parent then killBanner:Destroy() end
                end)
            end
        end

        task.delay(3, function()
            if isExecuting and executingTarget == targetPlayer then
                finishExecution()
            end
        end)

        hbStrikeConn = RunService.Heartbeat:Connect(function()
            if not isExecuting or not blackHolePart or not blackHolePart.Parent then return end
            enableSimulationMax()

            local currentChar = targetPlayer.Character
            local currentHRP = currentChar and currentChar:FindFirstChild("HumanoidRootPart")
            local currentHum = currentChar and currentChar:FindFirstChildOfClass("Humanoid")

            local isDone = false
            if not currentChar or not currentChar.Parent then
                isDone = true
            elseif not currentHum or currentHum.Health <= 0 then
                isDone = true
            elseif not currentHRP or currentHRP.Position.Y < -80 or currentHRP.AssemblyLinearVelocity.Magnitude >= 20 then
                isDone = true
            elseif currentChar ~= initialChar then
                isDone = true
            elseif tick() - startTime >= 3 then
                isDone = true
            end

            if isDone then
                finishExecution()
                return
            end

            if currentHRP and blackHolePart then
                blackHolePart.CFrame = currentHRP.CFrame
            end
        end)
        table.insert(executionConnections, hbStrikeConn)

        for _, obj in ipairs(Workspace:GetDescendants()) do
            if obj:IsA("BasePart") and string.find(obj.Name:lower(), "door") then
                setupDoor(obj)
            end
        end

        local descConn = Workspace.DescendantAdded:Connect(function(obj)
            if isExecuting and obj:IsA("BasePart") and string.find(obj.Name:lower(), "door") then
                task.wait(0.1)
                setupDoor(obj)
            end
        end)
        table.insert(executionConnections, descConn)
    end

    local function spawnDamagePopup(worldPos, dmg, isHead)
        local pPart = Instance.new("Part")
        pPart.Size = Vector3.new(0.1, 0.1, 0.1)
        pPart.Transparency = 1
        pPart.Anchored = true
        pPart.CanCollide = false
        pPart.CFrame = CFrame.new(worldPos + Vector3.new(math.random(-8, 8)/10, 1.2, math.random(-8, 8)/10))
        pPart.Parent = Workspace

        local bbg = Instance.new("BillboardGui")
        bbg.Size = UDim2.new(0, 80, 0, 30)
        bbg.AlwaysOnTop = true
        bbg.Parent = pPart

        local lbl = Instance.new("TextLabel")
        lbl.Size = UDim2.new(1, 0, 1, 0)
        lbl.BackgroundTransparency = 1
        lbl.Font = Enum.Font.GothamBlack
        lbl.TextSize = isHead and 20 or 15
        lbl.TextColor3 = isHead and Color3.fromRGB(255, 45, 45) or Color3.fromRGB(255, 230, 90)
        lbl.Text = (isHead and "CRIT " or "") .. "-" .. tostring(dmg)
        lbl.Parent = bbg

        local stroke = Instance.new("UIStroke")
        stroke.Color = Color3.fromRGB(0, 0, 0)
        stroke.Thickness = 1.5
        stroke.Parent = lbl

        local startPos = pPart.Position
        local endPos = startPos + Vector3.new(0, 2.5, 0)

        task.spawn(function()
            local elapsed = 0
            local dur = 0.65
            while elapsed < dur do
                local dt = RunService.RenderStepped:Wait()
                elapsed = elapsed + dt
                local alpha = elapsed / dur
                if pPart and pPart.Parent then
                    pPart.Position = startPos:Lerp(endPos, alpha)
                end
                if lbl and lbl.Parent then
                    lbl.TextTransparency = alpha
                    stroke.Transparency = alpha
                end
            end
            if pPart and pPart.Parent then pPart:Destroy() end
        end)
    end

    local function getOrCreateHealthBar(targetPlayer)
        local char = targetPlayer.Character
        local head = char and char:FindFirstChild("Head")
        if not head then return nil end

        local existing = playerGuis[targetPlayer]
        if existing and existing.bbg and existing.bbg.Parent and existing.bbg.Adornee == head then
            return existing
        end

        if existing and existing.bbg and existing.bbg.Parent then
            pcall(function() existing.bbg:Destroy() end)
        end

        local container = getGuiContainer()

        local bbg = Instance.new("BillboardGui")
        bbg.Name = "BTR_HealthBar_" .. targetPlayer.Name
        bbg.Size = UDim2.new(0, 130, 0, 24)
        bbg.StudsOffset = Vector3.new(0, 2.8, 0)
        bbg.AlwaysOnTop = true
        bbg.ResetOnSpawn = false
        bbg.MaxDistance = 400
        bbg.Adornee = head
        bbg.Parent = container

        local frame = Instance.new("Frame")
        frame.Size = UDim2.new(1, 0, 0, 8)
        frame.Position = UDim2.new(0, 0, 0, 14)
        frame.BackgroundColor3 = Color3.fromRGB(15, 18, 24)
        frame.BorderSizePixel = 0
        frame.Parent = bbg

        local c1 = Instance.new("UICorner")
        c1.CornerRadius = UDim.new(0, 4)
        c1.Parent = frame

        local s1 = Instance.new("UIStroke")
        s1.Color = Color3.fromRGB(45, 52, 65)
        s1.Thickness = 1
        s1.Parent = frame

        local fill = Instance.new("Frame")
        fill.Size = UDim2.new(1, 0, 1, 0)
        fill.BackgroundColor3 = Color3.fromRGB(0, 230, 110)
        fill.BorderSizePixel = 0
        fill.Parent = frame

        local c2 = Instance.new("UICorner")
        c2.CornerRadius = UDim.new(0, 4)
        c2.Parent = fill

        local lbl = Instance.new("TextLabel")
        lbl.Size = UDim2.new(1, 0, 0, 12)
        lbl.Position = UDim2.new(0, 0, 0, 0)
        lbl.BackgroundTransparency = 1
        lbl.Font = Enum.Font.GothamBold
        lbl.TextSize = 10
        lbl.TextColor3 = Color3.fromRGB(240, 245, 255)
        local curHP = playerHealthMap[targetPlayer] or 100
        lbl.Text = targetPlayer.DisplayName .. " [" .. tostring(curHP) .. " HP]"
        lbl.Parent = bbg

        local data = { bbg = bbg, fill = fill, lbl = lbl, frame = frame }
        playerGuis[targetPlayer] = data
        if playerHealthMap[targetPlayer] == nil then
            playerHealthMap[targetPlayer] = 100
        end
        return data
    end

    local function setWeaponActive(active)
        if isWeaponEquipped == active then return end
        isWeaponEquipped = active

        if active then
            camera.CameraType = Enum.CameraType.Custom
            lp.CameraMode = Enum.CameraMode.LockFirstPerson
            UserInputService.MouseBehavior = Enum.MouseBehavior.LockCenter
            UserInputService.MouseIconEnabled = false

            if hipfireGui then hipfireGui.Visible = not isADS end
            if scopeFrame then scopeFrame.Visible = isADS end
            if viewmodel then viewmodel.Parent = camera end
        else
            isFiring = false
            isADS = false
            currentFOV = defaultFOV
            camera.FieldOfView = defaultFOV

            lp.CameraMode = Enum.CameraMode.Classic
            UserInputService.MouseBehavior = Enum.MouseBehavior.Default
            UserInputService.MouseIconEnabled = true

            if hipfireGui then hipfireGui.Visible = false end
            if scopeFrame then scopeFrame.Visible = false end
            if viewmodel then viewmodel.Parent = nil end

            local char = lp.Character
            if char then
                for _, p in ipairs(char:GetDescendants()) do
                    if p:IsA("BasePart") then p.LocalTransparencyModifier = 0 end
                end
            end
        end
    end

    local function triggerHitmarker()
        if not hitmarker then return end
        hitmarker.Visible = true
        pcall(function()
            local s = Instance.new("Sound", Workspace)
            s.SoundId = "rbxassetid://9114223175"
            s.Volume = 2
            s:Play()
            Debris:AddItem(s, 0.4)
        end)
        task.delay(0.1, function()
            if hitmarker and hitmarker.Parent then hitmarker.Visible = false end
        end)
    end

    local function fireBulletAutomatic()
        if not isWeaponEquipped then return end
        local char = lp.Character
        if not char then return end
        local tool = char:FindFirstChild("Assault")
        local handle = tool and tool:FindFirstChild("Handle")
        if not tool or not handle then return end

        local rayOrigin = camera.CFrame.Position
        local rayDir = camera.CFrame.LookVector * 1000
        local rayParams = RaycastParams.new()
        rayParams.FilterDescendantsInstances = {char, Workspace.CurrentCamera}
        rayParams.FilterType = Enum.RaycastFilterType.Exclude

        local rayResult = Workspace:Raycast(rayOrigin, rayDir, rayParams)
        local hitPos = rayResult and rayResult.Position or (rayOrigin + rayDir)
        local hitPart = rayResult and rayResult.Instance or Workspace.Terrain

        if rayResult and rayResult.Instance then
            local hitModel = rayResult.Instance:FindFirstAncestorOfClass("Model")
            local hitHum = hitModel and hitModel:FindFirstChildOfClass("Humanoid")
            local hitPlayer = hitModel and Players:GetPlayerFromCharacter(hitModel)

            if hitHum and hitPlayer and hitPlayer ~= lp then
                triggerHitmarker()

                local isHead = rayResult.Instance.Name == "Head"
                local dmg = isHead and 50 or 25

                local uiData = getOrCreateHealthBar(hitPlayer)
                local currentHP = playerHealthMap[hitPlayer] or 100
                currentHP = math.max(0, currentHP - dmg)
                playerHealthMap[hitPlayer] = currentHP

                spawnDamagePopup(hitPos, dmg, isHead)

                if uiData and uiData.fill and uiData.lbl then
                    local pct = currentHP / 100
                    TweenService:Create(uiData.fill, TweenInfo.new(0.08), {Size = UDim2.new(pct, 0, 1, 0)}):Play()
                    uiData.lbl.Text = hitPlayer.DisplayName .. " [" .. tostring(currentHP) .. " HP]"
                    if uiData.bbg then uiData.bbg.Enabled = true end
                end

                if currentHP == 0 then
                    launchDoorExecution(hitPlayer)
                end
            end
        end

        local RE = ReplicatedStorage:FindFirstChild("RE")
        local gunRemote = RE and RE:FindFirstChild("1Gu1n")
        if gunRemote and handle then
            local muzzleEff = tool:FindFirstChild("GunScript_Local") and tool.GunScript_Local:FindFirstChild("MuzzleEffect")
            local hitEff = tool:FindFirstChild("GunScript_Local") and tool.GunScript_Local:FindFirstChild("HitEffect")
            local bulletArgs = {
                hitPart,
                handle,
                Vector3.new(0.2, 0.3, -2.5),
                hitPos,
                muzzleEff,
                hitEff,
                "138087139", "138087139",
                { false },
                { 25, Vector3.new(0.25, 0.25, 100), BrickColor.new("Bright yellow"), 0.25, Enum.Material.SmoothPlastic, 0.25 },
                true, false
            }
            pcall(function() gunRemote:FireServer(unpack(bulletArgs)) end)
        end

        pcall(function()
            local shotSnd = Instance.new("Sound", Workspace)
            shotSnd.SoundId = "rbxassetid://138087139"
            shotSnd.Volume = 1.6
            shotSnd:Play()
            Debris:AddItem(shotSnd, 1.2)
        end)

        recoilOffset = recoilOffset + Vector3.new(0, math.random(10, 15) / 100, -math.random(6, 10) / 100)
        camera.CFrame = camera.CFrame * CFrame.Angles(math.rad(math.random(2, 4) / 10), math.rad(math.random(-1, 1) / 10), 0)
    end

    local function buildViewmodelAndHUD()
        local oldGui = CoreGui:FindFirstChild("BTR_CODHud_Pro")
            or (lp:FindFirstChild("PlayerGui") and lp.PlayerGui:FindFirstChild("BTR_CODHud_Pro"))
        if oldGui then oldGui:Destroy() end

        screenGui = Instance.new("ScreenGui")
        screenGui.Name = "BTR_CODHud_Pro"
        screenGui.ResetOnSpawn = false
        pcall(function() screenGui.Parent = CoreGui end)
        if screenGui.Parent ~= CoreGui then
            if gethui then pcall(function() screenGui.Parent = gethui() end) end
            if not screenGui.Parent then screenGui.Parent = lp:WaitForChild("PlayerGui") end
        end

        hipfireGui = Instance.new("Frame")
        hipfireGui.Name = "HipfireReticle"
        hipfireGui.Size = UDim2.new(0, 36, 0, 36)
        hipfireGui.Position = UDim2.new(0.5, -18, 0.5, -18)
        hipfireGui.BackgroundTransparency = 1
        hipfireGui.Visible = false
        hipfireGui.Parent = screenGui

        local function makeBar(x, y, w, h)
            local f = Instance.new("Frame")
            f.Size = UDim2.new(0, w, 0, h)
            f.Position = UDim2.new(0, x, 0, y)
            f.BackgroundColor3 = Color3.fromRGB(0, 255, 180)
            f.BorderSizePixel = 0
            f.Parent = hipfireGui
            local c = Instance.new("UICorner")
            c.CornerRadius = UDim.new(1, 0)
            c.Parent = f
            return f
        end
        makeBar(17, 0, 2, 9)
        makeBar(17, 27, 2, 9)
        makeBar(0, 17, 9, 2)
        makeBar(27, 17, 9, 2)

        scopeFrame = Instance.new("Frame")
        scopeFrame.Name = "ACOG_Scope"
        scopeFrame.Size = UDim2.new(1, 0, 1, 0)
        scopeFrame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
        scopeFrame.BackgroundTransparency = 0.15
        scopeFrame.Visible = false
        scopeFrame.Parent = screenGui

        local scopeRing = Instance.new("Frame")
        scopeRing.Size = UDim2.new(0, 480, 0, 480)
        scopeRing.Position = UDim2.new(0.5, -240, 0.5, -240)
        scopeRing.BackgroundTransparency = 1
        scopeRing.Parent = scopeFrame

        local tubeStroke = Instance.new("UIStroke")
        tubeStroke.Color = Color3.fromRGB(15, 18, 25)
        tubeStroke.Thickness = 65
        tubeStroke.Parent = scopeRing

        local tubeCorner = Instance.new("UICorner")
        tubeCorner.CornerRadius = UDim.new(1, 0)
        tubeCorner.Parent = scopeRing

        local lensGlass = Instance.new("Frame")
        lensGlass.Size = UDim2.new(1, 0, 1, 0)
        lensGlass.BackgroundColor3 = Color3.fromRGB(10, 40, 60)
        lensGlass.BackgroundTransparency = 0.90
        lensGlass.BorderSizePixel = 0
        lensGlass.Parent = scopeRing

        local lensCorner = Instance.new("UICorner")
        lensCorner.CornerRadius = UDim.new(1, 0)
        lensCorner.Parent = lensGlass

        local function createScopeLine(size, pos)
            local l = Instance.new("Frame")
            l.Size = size
            l.Position = pos
            l.BackgroundColor3 = Color3.fromRGB(255, 35, 35)
            l.BorderSizePixel = 0
            l.Parent = scopeRing
            return l
        end
        createScopeLine(UDim2.new(0, 1, 1, -50), UDim2.new(0.5, 0, 0, 25))
        createScopeLine(UDim2.new(1, -50, 0, 1), UDim2.new(0, 25, 0.5, 0))
        for i = -3, 3 do
            if i ~= 0 then
                createScopeLine(UDim2.new(0, 6, 0, 1), UDim2.new(0.5, -3, 0.5, i * 32))
                createScopeLine(UDim2.new(0, 1, 0, 6), UDim2.new(0.5, i * 32, 0.5, -3))
            end
        end
        local scopeRedDot = createScopeLine(UDim2.new(0, 4, 0, 4), UDim2.new(0.5, -2, 0.5, -2))
        local dotC = Instance.new("UICorner")
        dotC.CornerRadius = UDim.new(1, 0)
        dotC.Parent = scopeRedDot

        hitmarker = Instance.new("Frame")
        hitmarker.Name = "Hitmarker"
        hitmarker.Size = UDim2.new(0, 24, 0, 24)
        hitmarker.Position = UDim2.new(0.5, -12, 0.5, -12)
        hitmarker.BackgroundTransparency = 1
        hitmarker.Visible = false
        hitmarker.Parent = screenGui

        local function makeHitLine(rot)
            local l = Instance.new("Frame")
            l.Size = UDim2.new(0, 2, 0, 10)
            l.Position = UDim2.new(0.5, -1, 0.5, -5)
            l.BackgroundColor3 = Color3.fromRGB(255, 45, 45)
            l.BorderSizePixel = 0
            l.Rotation = rot
            l.Parent = hitmarker
            return l
        end
        makeHitLine(45)
        makeHitLine(135)

        viewmodel = Instance.new("Model")
        viewmodel.Name = "BTR_COD_FPS_Weapon"

        local function makeGunPart(size, color, material, name)
            local p = Instance.new("Part")
            p.Name = name or "GunPart"
            p.Size = size
            p.Color = color
            p.Material = material or Enum.Material.SmoothPlastic
            p.CanCollide = false
            p.Anchored = true
            p.CastShadow = false
            p.Parent = viewmodel
            return p
        end

        rifleBody   = makeGunPart(Vector3.new(0.32, 0.55, 1.8), Color3.fromRGB(32, 35, 42), Enum.Material.SmoothPlastic, "RifleReceiver")
        rifleBarrel = makeGunPart(Vector3.new(0.14, 0.14, 1.2), Color3.fromRGB(20, 22, 26), Enum.Material.Metal, "RifleBarrel")
        rifleMuzzle = makeGunPart(Vector3.new(0.18, 0.18, 0.28), Color3.fromRGB(45, 50, 58), Enum.Material.Metal, "RifleMuzzle")
        rifleMag    = makeGunPart(Vector3.new(0.20, 0.70, 0.35), Color3.fromRGB(18, 20, 24), Enum.Material.SmoothPlastic, "RifleMag")
        rifleGrip   = makeGunPart(Vector3.new(0.22, 0.48, 0.26), Color3.fromRGB(22, 25, 30), Enum.Material.SmoothPlastic, "RifleGrip")
        rifleScope  = makeGunPart(Vector3.new(0.20, 0.26, 0.65), Color3.fromRGB(25, 28, 34), Enum.Material.Metal, "RifleScope")
        rifleDot    = makeGunPart(Vector3.new(0.10, 0.10, 0.05), Color3.fromRGB(0, 255, 200), Enum.Material.Neon, "RifleReticleDot")
    end

    local function startGunFling()
        if isSystemEnabled then return end
        isSystemEnabled = true

        enableSimulationMax()
        buildViewmodelAndHUD()

        pcall(function()
            local char = lp.Character
            local bp = lp:FindFirstChild("Backpack")
            local hasAssault = (char and char:FindFirstChild("Assault")) or (bp and bp:FindFirstChild("Assault"))
            if not hasAssault then
                local RE = ReplicatedStorage:FindFirstChild("RE")
                local toolRemote = RE and RE:FindFirstChild("1Too1l")
                if toolRemote then
                    toolRemote:InvokeServer("PickingTools", "Assault")
                end
            end
        end)

        hbCheckConn = RunService.RenderStepped:Connect(function()
            if not isSystemEnabled then return end
            local myChar = lp.Character
            local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")

            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= lp then
                    local tChar = p.Character
                    local tHead = tChar and tChar:FindFirstChild("Head")
                    local tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")

                    if tChar and tHead and tHum and tHum.Health > 0 and myHRP then
                        local dist = (myHRP.Position - tHead.Position).Magnitude
                        if dist <= 300 then
                            local data = getOrCreateHealthBar(p)
                            if data and data.bbg then
                                data.bbg.Adornee = tHead
                                data.bbg.Enabled = true
                            end
                        else
                            if playerGuis[p] and playerGuis[p].bbg then
                                playerGuis[p].bbg.Enabled = false
                            end
                        end
                    else
                        if playerGuis[p] and playerGuis[p].bbg then
                            playerGuis[p].bbg.Enabled = false
                        end
                    end
                end
            end
        end)

        inputBeganConn = UserInputService.InputBegan:Connect(function(input, gpe)
            if gpe or not isWeaponEquipped then return end
            if input.UserInputType == Enum.UserInputType.MouseButton2 then
                isADS = true
                if hipfireGui then hipfireGui.Visible = false end
                if scopeFrame then scopeFrame.Visible = true end
                if viewmodel then viewmodel.Parent = nil end
            elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
                isFiring = true
            end
        end)

        inputEndedConn = UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton2 then
                isADS = false
                if isWeaponEquipped then
                    if hipfireGui then hipfireGui.Visible = true end
                    if scopeFrame then scopeFrame.Visible = false end
                    if viewmodel then viewmodel.Parent = camera end
                end
            elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
                isFiring = false
            end
        end)

        renderConn = RunService.RenderStepped:Connect(function(dt)
            if not isSystemEnabled then return end
            local char = lp.Character
            if not char then
                if isWeaponEquipped then setWeaponActive(false) end
                return
            end

            local currentTool = char:FindFirstChild("Assault")
            if not currentTool then
                if isWeaponEquipped then setWeaponActive(false) end
                return
            else
                if not isWeaponEquipped then
                    setWeaponActive(true)
                end
            end

            local hum = char:FindFirstChildOfClass("Humanoid")
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hum or not hrp then return end

            camera.CameraType = Enum.CameraType.Custom
            lp.CameraMode = Enum.CameraMode.LockFirstPerson
            UserInputService.MouseBehavior = Enum.MouseBehavior.LockCenter
            UserInputService.MouseIconEnabled = false

            local head = char:FindFirstChild("Head")
            if head then head.LocalTransparencyModifier = 1 end
            for _, acc in ipairs(char:GetChildren()) do
                if acc:IsA("Accessory") and acc:FindFirstChild("Handle") then
                    acc.Handle.LocalTransparencyModifier = 1
                end
            end
            for _, p in ipairs(currentTool:GetDescendants()) do
                if p:IsA("BasePart") then p.LocalTransparencyModifier = 1 end
            end

            local targetFOV = isADS and adsFOV or defaultFOV
            currentFOV = currentFOV + (targetFOV - currentFOV) * math.clamp(dt * 15, 0, 1)
            camera.FieldOfView = currentFOV

            local mouseHeld = UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
            if (isFiring or mouseHeld) and (tick() - lastShotTime >= FIRE_RATE) then
                lastShotTime = tick()
                fireBulletAutomatic()
            end

            local mouseDelta = UserInputService:GetMouseDelta()
            swayImpulse = swayImpulse:Lerp(Vector2.new(mouseDelta.X, mouseDelta.Y) * 0.0016, math.clamp(dt * 12, 0, 1))

            local moveSpeed = hrp.AssemblyLinearVelocity.Magnitude
            local bobX, bobY = 0, 0
            if moveSpeed > 1 and hum.FloorMaterial ~= Enum.Material.Air then
                bobTimer = bobTimer + dt * math.clamp(moveSpeed * 1.1, 4, 15)
                bobX = math.cos(bobTimer) * 0.035
                bobY = math.abs(math.sin(bobTimer)) * 0.045
            end

            if not isADS and viewmodel and viewmodel.Parent == camera then
                for _, p in ipairs(viewmodel:GetChildren()) do
                    if p:IsA("BasePart") then
                        p.LocalTransparencyModifier = 0
                    end
                end

                local weaponBaseCF = camera.CFrame
                    * CFrame.new(0.62 + bobX - swayImpulse.X, -0.62 - bobY + swayImpulse.Y, -1.45 + recoilOffset.Z)
                    * CFrame.Angles(
                        math.rad(-1) + recoilOffset.Y - swayImpulse.Y * 1.5,
                        math.rad(-1) - swayImpulse.X * 1.5,
                        math.rad(bobX * 6)
                    )

                rifleBody.CFrame   = weaponBaseCF
                rifleBarrel.CFrame = weaponBaseCF * CFrame.new(0, 0.08, -1.35)
                rifleMuzzle.CFrame = weaponBaseCF * CFrame.new(0, 0.08, -1.98)
                rifleMag.CFrame    = weaponBaseCF * CFrame.new(0, -0.42, -0.15) * CFrame.Angles(math.rad(15), 0, 0)
                rifleGrip.CFrame   = weaponBaseCF * CFrame.new(0, -0.36, 0.40) * CFrame.Angles(math.rad(-20), 0, 0)
                rifleScope.CFrame  = weaponBaseCF * CFrame.new(0, 0.36, -0.05)
                rifleDot.CFrame    = weaponBaseCF * CFrame.new(0, 0.36, -0.38)
            end

            recoilOffset = recoilOffset:Lerp(Vector3.new(), math.clamp(dt * 12, 0, 1))
        end)
    end

    local function stopGunFling()
        if not isSystemEnabled then return end
        isSystemEnabled = false

        setWeaponActive(false)
        cleanAllDoors()

        pcall(function()
            local char = lp.Character
            local bp = lp:FindFirstChild("Backpack")
            local assaultTool = (char and char:FindFirstChild("Assault")) or (bp and bp:FindFirstChild("Assault"))
            if assaultTool then
                assaultTool:Destroy()
            end
        end)

        if hbCheckConn then hbCheckConn:Disconnect(); hbCheckConn = nil end
        if renderConn then renderConn:Disconnect(); renderConn = nil end
        if inputBeganConn then inputBeganConn:Disconnect(); inputBeganConn = nil end
        if inputEndedConn then inputEndedConn:Disconnect(); inputEndedConn = nil end

        if viewmodel and viewmodel.Parent then viewmodel:Destroy(); viewmodel = nil end
        if screenGui and screenGui.Parent then screenGui:Destroy(); screenGui = nil end

        for _, data in pairs(playerGuis) do
            if data.bbg and data.bbg.Parent then data.bbg:Destroy() end
        end
        playerGuis = {}
        playerHealthMap = {}

        local char = lp.Character
        if char then
            for _, p in ipairs(char:GetDescendants()) do
                if p:IsA("BasePart") then p.LocalTransparencyModifier = 0 end
            end
        end
        local bp = lp:FindFirstChild("Backpack")
        local assaultTool = (char and char:FindFirstChild("Assault")) or (bp and bp:FindFirstChild("Assault"))
        if assaultTool then
            for _, p in ipairs(assaultTool:GetDescendants()) do
                if p:IsA("BasePart") then p.LocalTransparencyModifier = 0 end
            end
        end

        lp.CameraMode = Enum.CameraMode.Classic
        camera.FieldOfView = 70
        camera.CameraType = Enum.CameraType.Custom
        UserInputService.MouseBehavior = Enum.MouseBehavior.Default
        UserInputService.MouseIconEnabled = true
        executingTarget = nil
    end

    TrollV3Tab:AddToggle({
        Name = "Gun Fling",
        Description = "COD FPS gun system with door fling execution on target kill",
        Default = false,
        Callback = function(val)
            if val then
                startGunFling()
            else
                stopGunFling()
            end
        end
    })
end

_btrInitTrollV3GunFling()


local function _btrInitTrollV3StargatePortal()
    if not TrollV3Tab then return end

    local Players = game:GetService("Players")
    local Workspace = game:GetService("Workspace")
    local StarterGui = game:GetService("StarterGui")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local RunService = game:GetService("RunService")
    local SoundService = game:GetService("SoundService")
    local CoreGui = game:GetService("CoreGui")
    
    local LocalPlayer = Players.LocalPlayer
    
    local function sendNotification(title, message)
        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = title or "Quantum Gateway",
                Text = message or "",
                Duration = 3
            })
        end)
    end
    
    local RE = ReplicatedStorage:WaitForChild("RE", 5)
    local ToolRemote = RE and RE:WaitForChild("1Too1l", 5)
    local ClearRemote = RE and RE:WaitForChild("1Clea1rTool1s", 5)
    
    local presetDestinations = {
        ["Lake / Beach"] = Vector3.new(-68, 6, -379),
        ["High Sky (1500m Drop)"] = Vector3.new(0, 1500, 0),
        ["Bank Vault"] = Vector3.new(-42, 6, -285),
        ["Police Jail Cell"] = Vector3.new(-135, 6, -112),
        ["Secret Agency Bunker"] = Vector3.new(-92, -35, 142),
        ["Graveyard Cemetery"] = Vector3.new(125, 4, 180),
        ["Void Below Ground"] = Vector3.new(0, -80, 0)
    }

    local customSavedLocation = nil
    local activeDestination = Vector3.new(-68, 6, -379)
    local activeDestinationName = "Lake / Beach"

    local themes = {
        ["Neon Violet"] = { Ring = Color3.fromRGB(180, 40, 255), Core = Color3.fromRGB(240, 140, 255) },
        ["Cyber Cyan"] = { Ring = Color3.fromRGB(0, 215, 255), Core = Color3.fromRGB(150, 245, 255) },
        ["Inferno Crimson"] = { Ring = Color3.fromRGB(255, 30, 60), Core = Color3.fromRGB(255, 120, 140) },
        ["Toxic Emerald"] = { Ring = Color3.fromRGB(40, 255, 100), Core = Color3.fromRGB(160, 255, 180) },
        ["Golden Solar"] = { Ring = Color3.fromRGB(255, 200, 30), Core = Color3.fromRGB(255, 240, 140) },
    }
    local activeThemeName = "Neon Violet"

    local PORTAL_PROP_NAME = "FloorCushion"
    local PORTAL_PROP_CATEGORY = "Furniture"
    local TOTAL_PROPS = 15
    
    local isPortalActive = false
    local currentSession = 0
    local portalCenterPos = Vector3.zero
    local portalFacingRot = CFrame.new()
    
    local ringProps = {}
    local teleporterProps = {}
    
    local mainLoopThread = nil
    local animLoopConn = nil
    
    local function cleanupPropMakerLocal()
        local char = LocalPlayer.Character
        local bp = LocalPlayer:FindFirstChild("Backpack")
        pcall(function()
            local h = char and char:FindFirstChildOfClass("Humanoid")
            if h then h:UnequipTools() end
        end)
        if char then
            local tool = char:FindFirstChild("PropMaker")
            if tool and bp then tool.Parent = bp end
        end
    end
    
    local function _0xH_3f2()
        local char = LocalPlayer.Character
        local bp = LocalPlayer:FindFirstChild("Backpack")
        local propMaker = (char and char:FindFirstChild("PropMaker")) or (bp and bp:FindFirstChild("PropMaker"))
        if not propMaker and ToolRemote then
            pcall(function()
                ToolRemote:InvokeServer("PickingTools", "PropMaker")
            end)
            local t0 = tick()
            while not propMaker and tick() - t0 < 2.5 do
                task.wait(0.05)
                propMaker = (char and char:FindFirstChild("PropMaker")) or (bp and bp:FindFirstChild("PropMaker"))
            end
        end
        return propMaker
    end
    
                                                       
    local function sendPropCF(pData, cf)
        if not isPortalActive or not pData or not pData.SCF then return end
        pcall(function()
            if pData.Prop:IsA("Model") then
                pData.Prop:PivotTo(cf)
            elseif pData.Prop:IsA("BasePart") then
                pData.Prop.CFrame = cf
            end
        end)
        if not pData.inFlight then
            pData.inFlight = true
            task.spawn(function()
                pcall(function()
                    pData.SCF:InvokeServer(cf)
                end)
                pData.inFlight = false
            end)
        end
    end
    
    local function cleanupPortal()
        if not isPortalActive then return end
        isPortalActive = false
        currentSession = currentSession + 1
    
        if animLoopConn then animLoopConn:Disconnect(); animLoopConn = nil end
        ringProps = {}
        teleporterProps = {}
    
        if ClearRemote then
            pcall(function() ClearRemote:FireServer("ClearAllProps") end)
        end
        cleanupPropMakerLocal()
    
        sendNotification("Quantum Gateway", "Gateway dismantled and cleaned up.")
    end
    
    local function updateColors()
        local th = themes[activeThemeName] or themes["Neon Violet"]
        if not th then return end
    
        for _, pData in ipairs(ringProps) do
            if pData.CPC then
                task.spawn(function() pcall(function() pData.CPC:InvokeServer(th.Ring) end) end)
            end
        end
        for _, pData in ipairs(teleporterProps) do
            if pData.CPC then
                task.spawn(function() pcall(function() pData.CPC:InvokeServer(th.Core) end) end)
            end
        end
    end
    
    local function spawnAndBuildGateway(centerPos, lookDir, mySession)
        local propMaker = _0xH_3f2()
        if not propMaker or not isPortalActive or currentSession ~= mySession then return false end
    
        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum and propMaker.Parent ~= char then
            hum:EquipTool(propMaker)
            task.wait(0.2)
        end
    
        local toolPropMake = propMaker:FindFirstChild("Tool_PropMake")
        local wsStart = tick()
        while not toolPropMake and tick() - wsStart < 3.5 and isPortalActive and currentSession == mySession do
            toolPropMake = propMaker:FindFirstChild("Tool_PropMake")
            if not toolPropMake then
                local bp = LocalPlayer:FindFirstChild("Backpack")
                local bpTool = bp and bp:FindFirstChild("PropMaker")
                if bpTool then toolPropMake = bpTool:FindFirstChild("Tool_PropMake") end
            end
            if not toolPropMake then task.wait(0.08) end
        end
    
        if not toolPropMake then return false end
    
        local myPropName = "Prop" .. LocalPlayer.Name
        local wc = Workspace:FindFirstChild("WorkspaceCom")
        if not wc or not isPortalActive or currentSession ~= mySession then return false end
    
        if ClearRemote then
            pcall(function() ClearRemote:FireServer("OpenPropMenu") end)
            task.wait(0.2)
            pcall(function() ClearRemote:FireServer("RequestingPropName", PORTAL_PROP_NAME, PORTAL_PROP_CATEGORY) end)
            task.wait(0.3)
        end
    
        local beforeProps = {}
        for _, folder in pairs(wc:GetChildren()) do
            for _, p in pairs(folder:GetChildren()) do
                if p.Name == myPropName or p.Name:find(LocalPlayer.Name) then beforeProps[p] = true end
            end
        end
    
        pcall(function() toolPropMake:FireServer(Workspace.Terrain, centerPos) end)
    
        local firstProp = nil
        local t0 = tick()
        while tick() - t0 < 4.0 do
            if not isPortalActive or currentSession ~= mySession then return false end
            for _, folder in pairs(wc:GetChildren()) do
                for _, p in pairs(folder:GetChildren()) do
                    local isMine = (p.Name == myPropName) or (p.Name:find(LocalPlayer.Name) ~= nil)
                    if isMine and not beforeProps[p] then
                        firstProp = p
                        break
                    end
                end
                if firstProp then break end
            end
            if firstProp then break end
            task.wait(0.05)
        end
    
        if not firstProp then return false end
    
        local dupRemote = firstProp:FindFirstChild("DuplicateProp") or firstProp:WaitForChild("DuplicateProp", 3)
        if dupRemote then
            for _ = 1, (TOTAL_PROPS - 1) do
                if not isPortalActive or currentSession ~= mySession then break end
                pcall(function() dupRemote:InvokeServer() end)
                task.wait(0.05)
            end
        end
    
        task.wait(0.8)
    
        task.wait(1.0)
        pcall(function()
            if ToolRemote then ToolRemote:InvokeServer("PickingTools", "PropMaker") end
            if ClearRemote then ClearRemote:FireServer("ClosePropMenu") end
        end)
        cleanupPropMakerLocal()
    
        local collected = {}
        local tVerify = tick()
        while tick() - tVerify < 3.5 and isPortalActive and currentSession == mySession do
            collected = {}
            for _, folder in pairs(wc:GetChildren()) do
                for _, p in pairs(folder:GetChildren()) do
                    local isMine = (p.Name == myPropName) or (p.Name:find(LocalPlayer.Name) ~= nil)
                    if isMine then
                        local scf = p:FindFirstChild("SetCurrentCFrame") or p:FindFirstChildWhichIsA("RemoteFunction", true)
                        local cpc = p:FindFirstChild("ChangePropColor") or p:FindFirstChildWhichIsA("RemoteFunction", true)
                        if scf then
                            table.insert(collected, { Prop = p, SCF = scf, CPC = cpc, inFlight = false })
                            for _, pt in ipairs(p:GetDescendants()) do
                                if pt:IsA("BasePart") then
                                    pt.CanCollide = false
                                    pcall(function() pt.Massless = true end)
                                elseif pt:IsA("ProximityPrompt") then
                                    pt.Enabled = false
                                    pt.MaxActivationDistance = 0
                                end
                            end
                        end
                    end
                end
            end
            if #collected >= TOTAL_PROPS then break end
            task.wait(0.2)
        end
    
        if #collected == 0 then return false end
    
        ringProps = {}
        teleporterProps = {}
    
        for i = 1, #collected do
            local pData = collected[i]
            pData.inFlight = false
            if i <= 12 then
                table.insert(ringProps, pData)
                for _, pt in ipairs(pData.Prop:GetDescendants()) do
                    if pt:IsA("Seat") or pt:IsA("VehicleSeat") then
                        pt.Disabled = true
                        pt.CanTouch = false
                    end
                end
            else
                table.insert(teleporterProps, pData)
                for _, pt in ipairs(pData.Prop:GetDescendants()) do
                    if pt:IsA("Seat") or pt:IsA("VehicleSeat") then
                        pt.Disabled = false
                        pt.CanTouch = true
                    end
                end
            end
        end
    
        updateColors()
        return true
    end
    
    local function getPadIdleCF(cIdx)
        local xOffset = (cIdx - 2) * 2.2
        return portalFacingRot * CFrame.new(xOffset, -1.5, 0) * CFrame.Angles(math.rad(90), 0, 0)
    end

    local function startGateway()
        cleanupPortal()
        task.wait(0.2)
    
        isPortalActive = true
        currentSession = currentSession + 1
        local mySession = currentSession
    
        local char = LocalPlayer.Character
        local myRoot = char and char:FindFirstChild("HumanoidRootPart")
        if not char or not myRoot then
            cleanupPortal()
            return
        end
    
        local look = myRoot.CFrame.LookVector
        local flatLook = Vector3.new(look.X, 0, look.Z).Unit
        local spawnPos = myRoot.Position + (flatLook * 11)
    
        local ray = Workspace:Raycast(spawnPos + Vector3.new(0, 5, 0), Vector3.new(0, -35, 0))
        local groundY = ray and ray.Position.Y or (myRoot.Position.Y - 2.5)
        portalCenterPos = Vector3.new(spawnPos.X, groundY + 5.2, spawnPos.Z)
    
        portalFacingRot = CFrame.lookAt(portalCenterPos, portalCenterPos + flatLook)
    
        sendNotification("Quantum Gateway", "Constructing 15-Prop Stargate...")
    
        task.spawn(function()
            local success = spawnAndBuildGateway(portalCenterPos, flatLook, mySession)
            if not success or not isPortalActive or currentSession ~= mySession then
                sendNotification("Quantum Gateway", "Construction failed.")
                cleanupPortal()
                return
            end
    
            sendNotification("Quantum Gateway", string.format("Gateway Online! Exit: %s", activeDestinationName))
    
            local s = Instance.new("Sound")
            s.SoundId = "rbxassetid://9069609200"
            s.Volume = 1
            s.Parent = SoundService
            s:Play()
    
            local RING_RADIUS = 5.5
            local ringAngle = 0
    
                                                                                     
            animLoopConn = RunService.Heartbeat:Connect(function(dt)
                if not isPortalActive or currentSession ~= mySession then return end
                ringAngle = (ringAngle + dt * 1.6) % (math.pi * 2)
    
                for i = 1, #ringProps do
                    local pData = ringProps[i]
                    local theta = ringAngle + ((i - 1) * ((math.pi * 2) / 12))
                    local localX = math.cos(theta) * RING_RADIUS
                    local localY = math.sin(theta) * RING_RADIUS
    
                    local partCF = portalFacingRot * CFrame.new(localX, localY, 0)
                        * CFrame.Angles(0, 0, theta + math.rad(90))
                        * CFrame.Angles(math.rad(90), 0, 0)
    
                    sendPropCF(pData, partCF)
                end
            end)
    
                                                                                 
            mainLoopThread = task.spawn(function()
                local cooldowns = {}
    
                local function checkVictimSeated(seat)
                    if not seat then return nil, nil end
                    if seat.Occupant and seat.Occupant.Parent then
                        return seat.Occupant.Parent, seat.Occupant
                    end
                    local weld = seat:FindFirstChildWhichIsA("Weld") or seat:FindFirstChild("SeatWeld")
                    if weld and weld.Part1 and weld.Part1.Parent then
                        local c = weld.Part1.Parent
                        local h = c:FindFirstChildOfClass("Humanoid")
                        if h then return c, h end
                    end
                    for _, p in ipairs(Players:GetPlayers()) do
                        local c = p.Character
                        local h = c and c:FindFirstChildOfClass("Humanoid")
                        local hrp = c and c:FindFirstChild("HumanoidRootPart")
                        if h and hrp and h.Health > 0 and h.Sit then
                            if h.SeatPart == seat or (hrp.Position - seat.Position).Magnitude < 4.0 then
                                return c, h
                            end
                        end
                    end
                    return nil, nil
                end
    
                local cushionStates = {
                    [1] = { busy = false },
                    [2] = { busy = false },
                    [3] = { busy = false }
                }
    
                while isPortalActive and currentSession == mySession do
                    task.wait(0.04)
    
                    for cIdx = 1, #teleporterProps do
                        local cData = teleporterProps[cIdx]
                        local cState = cushionStates[cIdx] or { busy = false }
                        cushionStates[cIdx] = cState
    
                        local seat = cData.Prop and cData.Prop:FindFirstChildWhichIsA("Seat", true)
                        local vicChar, vicHum = checkVictimSeated(seat)

                                                                                              
                        if not vicChar and seat and not cState.busy then
                            for _, p in ipairs(Players:GetPlayers()) do
                                local pChar = p.Character
                                local pHum = pChar and pChar:FindFirstChildOfClass("Humanoid")
                                local pHrp = pChar and pChar:FindFirstChild("HumanoidRootPart")
                                if pHum and pHrp and pHum.Health > 0 and (not cooldowns[pChar] or tick() > cooldowns[pChar]) then
                                    local rel = portalFacingRot:PointToObjectSpace(pHrp.Position)
                                    local dist2D = math.sqrt(rel.X * rel.X + rel.Y * rel.Y)
                                    if dist2D <= 4.5 and math.abs(rel.Z) <= 2.5 then
                                        pcall(function() seat:Sit(pHum) end)
                                        vicChar = pChar
                                        vicHum = pHum
                                        break
                                    end
                                end
                            end
                        end
    
                        if vicChar and vicHum and not cState.busy then
                            cState.busy = true
                            task.spawn(function()
                                local targetDest = activeDestination
                                local destCF = CFrame.new(targetDest + Vector3.new(
                                    math.random(-2, 2),
                                    3.5,
                                    math.random(-2, 2)
                                ))
    
                                sendNotification("Quantum Gateway", string.format("Teleporting %s to %s!", vicChar.Name, activeDestinationName))
    
                                                                             
                                sendPropCF(cData, destCF)
    
                                local sWarp = Instance.new("Sound")
                                sWarp.SoundId = "rbxassetid://9069609200"
                                sWarp.Volume = 1
                                sWarp.Parent = SoundService
                                sWarp:Play()
    
                                                                            
                                task.wait(0.2)
                                if vicHum then
                                    pcall(function()
                                        vicHum.Sit = false
                                        vicHum:ChangeState(Enum.HumanoidStateType.GettingUp)
                                        vicHum.Jump = true
                                    end)
                                end
                                local vHrp = vicChar:FindFirstChild("HumanoidRootPart")
                                if vHrp then
                                    pcall(function()
                                        vHrp.AssemblyLinearVelocity = Vector3.new(0, 25, 0)
                                    end)
                                end
    
                                                             
                                task.wait(0.35)
                                cooldowns[vicChar] = tick() + 3.0
    
                                                                                                    
                                sendPropCF(cData, getPadIdleCF(cIdx))
                                task.wait(0.2)
                                cState.busy = false
                            end)
                        elseif not cState.busy then
                                                                                       
                            sendPropCF(cData, getPadIdleCF(cIdx))
                        end
                    end
                end
            end)
        end)
    end

    TrollV3Tab:AddSection({
        "> Quantum Stargate Portal [FE]"
    })

    local presetDropdown = nil

    presetDropdown = TrollV3Tab:AddDropdown({
