        Description = "Teleports yourself to test and verify where victims will appear",
        Callback = function()
            local char = LocalPlayer.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if hrp and activeDestination then
                hrp.CFrame = CFrame.new(activeDestination + Vector3.new(0, 3, 0))
                sendNotification("Quantum Gateway", "Teleported to exit: " .. activeDestinationName)
            end
        end
    })

    TrollV3Tab:AddDropdown({
        Name = "Portal Visual Theme",
        Description = "Choose color theme of the spinning ring and core",
        Options = { "Neon Violet", "Cyber Cyan", "Inferno Crimson", "Toxic Emerald", "Golden Solar" },
        Default = "Neon Violet",
        Callback = function(val)
            activeThemeName = val
            updateColors()
            sendNotification("Quantum Gateway", "Visual theme: " .. val)
        end
    })

    local stargateToggle = TrollV3Tab:AddToggle({
        Name = "Activate Stargate Portal",
        Description = "Spawns 15-prop quantum portal that captures and teleports players into the exit zone",
        Default = false,
        Callback = function(val)
            if val then
                startGateway()
            else
                cleanupPortal()
            end
        end
    })

    LocalPlayer.CharacterAdded:Connect(function(char)
        local hum = char:WaitForChild("Humanoid", 5)
        if hum then
            hum.Died:Connect(function()
                if isPortalActive then cleanupPortal() end
            end)
        end
    end)
end
_btrInitTrollV3StargatePortal()


local function _btrInitTrollV3ServerDestroyer()
    if not TrollV3Tab then return end

    local Players = game:GetService("Players")
    local Workspace = game:GetService("Workspace")
    local StarterGui = game:GetService("StarterGui")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local RunService = game:GetService("RunService")
    local SoundService = game:GetService("SoundService")
    local CoreGui = game:GetService("CoreGui")
    
    local LocalPlayer = Players.LocalPlayer
    
    local function sendNotification(title, message)
        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = title or "Server Destroyer",
                Text = message or "",
                Duration = 3
            })
        end)
    end
    
    local RE = ReplicatedStorage:WaitForChild("RE", 5)
    local ToolRemote = RE and RE:WaitForChild("1Too1l", 5)
    local ClearRemote = RE and RE:WaitForChild("1Clea1rTool1s", 5)
    
    local SEAT_PROPS = {
        { Display = "Toilet", Name = "FurnitureToilet", Category = "Furniture" },
        { Display = "Bleachers", Name = "FurnitureBleachers", Category = "Furniture" },
        { Display = "Silver Throne", Name = "FurnitureSilverThrone", Category = "Furniture" },
        { Display = "BeanBag", Name = "FurnitureBeanBag", Category = "Furniture" },
        { Display = "Brown Couch", Name = "FurnitureCouchBrown", Category = "Furniture" },
        { Display = "Futuristic Bed", Name = "FuturisticLargeBed", Category = "Furniture" },
        { Display = "Floor Cushion", Name = "FloorCushion", Category = "Furniture" },
    }
    
    local currentPropIndex = 1
    local selectedProp = SEAT_PROPS[1]
    local TOTAL_PROPS = 15
    
    local isDestroyerRunning = false
    local currentSession = 0
    local destroyerCenterPos = Vector3.zero
    local isHandlingPropMaker = false
    
    local gravityFolder = nil
    local gravityAnchorPart = nil
    local gravityAtt1 = nil
    local forcedParts = {}
    local forcedVehicles = {}
    
    local heartbeatConn = nil
    local descendantConn = nil
    local antiSitConn = nil
    local mainLoopThread = nil
    local senders = {}
    
    local function enableAntiSit()
        if antiSitConn then return end
        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum then
            hum:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
            hum.Sit = false
        end
        antiSitConn = RunService.Stepped:Connect(function()
            local c = LocalPlayer.Character
            local h = c and c:FindFirstChildOfClass("Humanoid")
            if h then
                if h.Sit then
                    h.Sit = false
                end
                h:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
            end
        end)
    end
    
    local function disableAntiSit()
        if antiSitConn then
            antiSitConn:Disconnect()
            antiSitConn = nil
        end
        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum then
            hum:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
        end
    end
    
    local function cleanupPropMakerLocal()
        local char = LocalPlayer.Character
        local bp = LocalPlayer:FindFirstChild("Backpack")
        pcall(function()
            local h = char and char:FindFirstChildOfClass("Humanoid")
            if h then h:UnequipTools() end
        end)
        if char then
            local tool = char:FindFirstChild("PropMaker")
            if tool and bp then tool.Parent = bp end
        end
    end
    
    local function _0xH_3f2()
        local char = LocalPlayer.Character
        local bp = LocalPlayer:FindFirstChild("Backpack")
        local propMaker = (char and char:FindFirstChild("PropMaker")) or (bp and bp:FindFirstChild("PropMaker"))
        if not propMaker and ToolRemote then
            pcall(function()
                ToolRemote:InvokeServer("PickingTools", "PropMaker")
            end)
            local t0 = tick()
            while not propMaker and tick() - t0 < 2.5 do
                task.wait(0.05)
                propMaker = (char and char:FindFirstChild("PropMaker")) or (bp and bp:FindFirstChild("PropMaker"))
            end
        end
        return propMaker
    end
    
    local function sendCF(scf, cf, prop)
        if not isDestroyerRunning or not scf then return end
    
        if prop then
            pcall(function()
                if prop:IsA("Model") then
                    prop:PivotTo(cf)
                elseif prop:IsA("BasePart") then
                    prop.CFrame = cf
                end
            end)
        end
    
        local entry = senders[scf]
        local now = tick()
        if not entry then
            entry = { lastSent = 0, nextCF = cf, sending = false }
            senders[scf] = entry
        else
            entry.nextCF = cf
        end
    
        if not entry.sending and (now - entry.lastSent >= 0.03) then
            entry.sending = true
            task.spawn(function()
                while isDestroyerRunning and entry.nextCF do
                    local toSend = entry.nextCF
                    entry.nextCF = nil
                    entry.lastSent = tick()
                    pcall(function() scf:InvokeServer(toSend) end)
                    task.wait(0.03)
                end
                entry.sending = false
            end)
        end
    end
    
    local function isBuildingDoor(part)
        local vehiclesFolder = Workspace:FindFirstChild("Vehicles")
        if vehiclesFolder and part:IsDescendantOf(vehiclesFolder) then
            return false
        end
        local n = part.Name:lower()
        if n:find("door") or n:find("porte") or n:find("gate") then
            return true
        end
        if part.Parent and (part.Parent.Name:lower():find("door") or part.Parent.Name:lower():find("gate")) then
            return true
        end
        return false
    end
    
    local function findVehicleModel(part)
        if not part then return nil end
        local cur = part.Parent
        while cur and cur ~= Workspace do
            if cur:IsA("Model") then
                local vf = Workspace:FindFirstChild("Vehicles")
                if vf and cur.Parent == vf then return cur end
                local wc = Workspace:FindFirstChild("WorkspaceCom")
                if wc and cur:IsDescendantOf(wc) then return cur end
                for _, d in ipairs(cur:GetChildren()) do
                    if d:IsA("VehicleSeat") then return cur end
                end
                local n = cur.Name:lower()
                if n:find("heli") or n:find("car") or n:find("vehicle") or n:find("boat") or n:find("plane") then
                    return cur
                end
            end
            cur = cur.Parent
        end
        return nil
    end
    
    local function applyGravityToPart(v)
        if not isDestroyerRunning or not gravityAtt1 then return end
        if not v or not v:IsA("BasePart") or v.Anchored then return end
        if isBuildingDoor(v) then return end
    
        local myChar = LocalPlayer.Character
        if myChar and v:IsDescendantOf(myChar) then return end
        local myBp = LocalPlayer:FindFirstChild("Backpack")
        if myBp and v:IsDescendantOf(myBp) then return end
        if v == gravityAnchorPart then return end
    
        local resp = 350
        local spinPwr = 15000000
    
        local vehModel = findVehicleModel(v)
        if vehModel then
            if forcedVehicles[vehModel] then return end
            forcedVehicles[vehModel] = true
    
            pcall(function()
                local root = vehModel.PrimaryPart or vehModel:FindFirstChild("Body") or vehModel:FindFirstChildWhichIsA("VehicleSeat") or vehModel:FindFirstChildWhichIsA("BasePart")
                if not root or root.Anchored then return end
    
                for _, d in ipairs(vehModel:GetDescendants()) do
                    if d:IsA("BasePart") then
                        d.CanCollide = false
                        pcall(function() d.Massless = true end)
                        for _, x in ipairs(d:GetChildren()) do
                            if x.Name:find("SD_") then x:Destroy() end
                        end
                    elseif d:IsA("VehicleSeat") or d:IsA("Seat") then
                        d.Disabled = true
                        pcall(function() d.HandBrake = false end)
                    end
                end
    
                local att0 = Instance.new("Attachment")
                att0.Name = "SD_Att"
                att0.Position = Vector3.new(math.random(-4, 4), math.random(-2, 2), math.random(-4, 4))
                att0.Parent = root
    
                local align = Instance.new("AlignPosition")
                align.Name = "SD_Align"
                align.Mode = Enum.PositionAlignmentMode.TwoAttachment
                align.Attachment0 = att0
                align.Attachment1 = gravityAtt1
                align.MaxForce = math.huge
                align.MaxVelocity = math.huge
                align.Responsiveness = resp
                align.ReactionForceEnabled = false
                align.ApplyAtCenterOfMass = true
                align.Parent = root
    
                local torque = Instance.new("Torque")
                torque.Name = "SD_Torque"
                torque.Attachment0 = att0
                torque.RelativeTo = Enum.ActuatorRelativeTo.World
                torque.Torque = Vector3.new(
                    math.random(-1, 1) * spinPwr,
                    spinPwr,
                    math.random(-1, 1) * spinPwr
                )
                torque.Parent = root
    
                forcedParts[root] = {
                    Part = root,
                    Model = vehModel,
                    Align = align,
                    Torque = torque,
                    Att = att0
                }
            end)
            return
        end
    
        if forcedParts[v] then return end
    
        pcall(function()
            for _, x in ipairs(v:GetChildren()) do
                if x.Name:find("SD_") then x:Destroy() end
            end
    
            v.CanCollide = false
    
            local att0 = Instance.new("Attachment")
            att0.Name = "SD_Att"
            att0.Position = Vector3.new(math.random(-3, 3), math.random(-2, 2), math.random(-3, 3))
            att0.Parent = v
    
            local align = Instance.new("AlignPosition")
            align.Name = "SD_Align"
            align.Mode = Enum.PositionAlignmentMode.TwoAttachment
            align.Attachment0 = att0
            align.Attachment1 = gravityAtt1
            align.MaxForce = math.huge
            align.MaxVelocity = math.huge
            align.Responsiveness = resp
            align.ReactionForceEnabled = false
            align.ApplyAtCenterOfMass = true
            align.Parent = v
    
            local torque = Instance.new("Torque")
            torque.Name = "SD_Torque"
            torque.Attachment0 = att0
            torque.RelativeTo = Enum.ActuatorRelativeTo.World
            torque.Torque = Vector3.new(
                math.random(-1, 1) * spinPwr,
                spinPwr,
                math.random(-1, 1) * spinPwr
            )
            torque.Parent = v
    
            forcedParts[v] = {
                Part = v,
                Align = align,
                Torque = torque,
                Att = att0
            }
        end)
    end
    
    local function scanAllUnanchored()
        local count = 0
        local all = Workspace:GetDescendants()
        for i = 1, #all do
            if not isDestroyerRunning then break end
            local obj = all[i]
            if obj:IsA("BasePart") and not obj.Anchored and not isBuildingDoor(obj) then
                applyGravityToPart(obj)
            elseif obj:IsA("VehicleSeat") or obj:IsA("Seat") then
                pcall(function()
                    obj.HandBrake = false
                    obj.Disabled = true
                end)
            end
            count = count + 1
            if count % 250 == 0 then task.wait() end
        end
    
        local vf = Workspace:FindFirstChild("Vehicles")
        if vf then
            for _, veh in ipairs(vf:GetChildren()) do
                for _, d in ipairs(veh:GetDescendants()) do
                    if d:IsA("BasePart") and not d.Anchored then
                        applyGravityToPart(d)
                    elseif d:IsA("VehicleSeat") or d:IsA("Seat") then
                        pcall(function()
                            d.HandBrake = false
                            d.Disabled = true
                        end)
                    end
                end
            end
        end
    end
    
    local function setupGravityVoid()
        if gravityFolder then pcall(function() gravityFolder:Destroy() end) end
    
        gravityFolder = Instance.new("Folder")
        gravityFolder.Name = "SD_GravityVoid"
        gravityFolder.Parent = Workspace
    
        gravityAnchorPart = Instance.new("Part")
        gravityAnchorPart.Name = "SD_CenterAnchor"
        gravityAnchorPart.Size = Vector3.new(2, 2, 2)
        gravityAnchorPart.CFrame = CFrame.new(destroyerCenterPos)
        gravityAnchorPart.Anchored = true
        gravityAnchorPart.CanCollide = false
        gravityAnchorPart.Transparency = 1
        gravityAnchorPart.Parent = gravityFolder
    
        gravityAtt1 = Instance.new("Attachment")
        gravityAtt1.Name = "SD_Att1"
        gravityAtt1.Parent = gravityAnchorPart
    
        pcall(function()
            LocalPlayer.ReplicationFocus = Workspace
            if setscriptable then
                setscriptable(LocalPlayer, "SimulationRadius", true)
                setscriptable(LocalPlayer, "MaximumSimulationRadius", true)
            end
            if sethiddenproperty then
                sethiddenproperty(LocalPlayer, "MaximumSimulationRadius", 1e9)
                sethiddenproperty(LocalPlayer, "SimulationRadius", 1e9)
            end
        end)
    
        task.spawn(scanAllUnanchored)
    
        descendantConn = Workspace.DescendantAdded:Connect(function(v)
            if isDestroyerRunning then
                task.wait(0.04)
                if v:IsA("BasePart") and not v.Anchored and not isBuildingDoor(v) then
                    applyGravityToPart(v)
                end
            end
        end)
    
        local lastPeriodicScan = tick()
        heartbeatConn = RunService.Heartbeat:Connect(function()
            if not isDestroyerRunning then return end
    
            pcall(function()
                if sethiddenproperty then
                    sethiddenproperty(LocalPlayer, "MaximumSimulationRadius", 1e9)
                    sethiddenproperty(LocalPlayer, "SimulationRadius", 1e9)
                end
            end)
    
            local now = tick()
            if now - lastPeriodicScan > 2.0 then
                lastPeriodicScan = now
                task.spawn(scanAllUnanchored)
            end
        end)
    end
    
    local updateGuiStatus = nil
    
    local function stopServerDestroyer()
        if not isDestroyerRunning then return end
        isDestroyerRunning = false
        currentSession = currentSession + 1
    
        disableAntiSit()
    
        if heartbeatConn then heartbeatConn:Disconnect(); heartbeatConn = nil end
        if descendantConn then descendantConn:Disconnect(); descendantConn = nil end
    
        for _, data in pairs(forcedParts) do
            if typeof(data) == "table" and data.Part and data.Part.Parent then
                pcall(function()
                    if data.Align then data.Align:Destroy() end
                    if data.Torque then data.Torque:Destroy() end
                    if data.Att then data.Att:Destroy() end
                    data.Part.CanCollide = true
                    if data.Model and data.Model.Parent then
                        for _, d in ipairs(data.Model:GetDescendants()) do
                            if d:IsA("BasePart") then
                                d.CanCollide = true
                                pcall(function() d.Massless = false end)
                            elseif d:IsA("VehicleSeat") or d:IsA("Seat") then
                                d.Disabled = false
                            end
                        end
                    end
                end)
            end
        end
        forcedParts = {}
        forcedVehicles = {}
    
        if gravityFolder then
            pcall(function() gravityFolder:Destroy() end)
            gravityFolder = nil
            gravityAnchorPart = nil
            gravityAtt1 = nil
        end
    
        if ClearRemote then
            pcall(function() ClearRemote:FireServer("ClearAllProps") end)
        end
        cleanupPropMakerLocal()
    
        if updateGuiStatus then updateGuiStatus(false) end
        sendNotification("Server Destroyer", "Destroyer collapsed and cleaned up.")
    end
    
    local function spawnAndCollectToilets(spawnPos, mySession)
        isHandlingPropMaker = true
        local propMaker = _0xH_3f2()
        if not propMaker or not isDestroyerRunning or currentSession ~= mySession then
            isHandlingPropMaker = false
            return {}
        end
    
        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum and propMaker.Parent ~= char then
            hum:EquipTool(propMaker)
            local eqStart = tick()
            while tick() - eqStart < 1.5 do
                if propMaker.Parent == char then break end
                task.wait(0.05)
            end
        end
    
        if ClearRemote then
            pcall(function() ClearRemote:FireServer("OpenPropMenu") end)
            task.wait(0.2)
            pcall(function() ClearRemote:FireServer("RequestingPropName", selectedProp.Name, selectedProp.Category) end)
            task.wait(0.3)
        end
    
        local toolPropMake = propMaker:FindFirstChild("Tool_PropMake")
        local wsStart = tick()
        while not toolPropMake and tick() - wsStart < 3.5 and isDestroyerRunning and currentSession == mySession do
            toolPropMake = propMaker:FindFirstChild("Tool_PropMake")
            if not toolPropMake then
                local bp = LocalPlayer:FindFirstChild("Backpack")
                local bpTool = bp and bp:FindFirstChild("PropMaker")
                if bpTool then toolPropMake = bpTool:FindFirstChild("Tool_PropMake") end
            end
            if not toolPropMake then task.wait(0.08) end
        end
    
        if not toolPropMake then
            isHandlingPropMaker = false
            return {}
        end
    
        local myPropName = "Prop" .. LocalPlayer.Name
        local wc = Workspace:FindFirstChild("WorkspaceCom")
        if not wc or not isDestroyerRunning or currentSession ~= mySession then
            isHandlingPropMaker = false
            return {}
        end
    
        local existingProps = {}
        for _, folder in pairs(wc:GetChildren()) do
            for _, p in pairs(folder:GetChildren()) do
                if p.Name == myPropName then existingProps[p] = true end
            end
        end
    
        pcall(function() toolPropMake:FireServer(Workspace.Terrain, spawnPos) end)
    
        local firstProp = nil
        local t0 = tick()
        while tick() - t0 < 4.0 do
            if not isDestroyerRunning or currentSession ~= mySession then
                isHandlingPropMaker = false
                return {}
            end
            for _, folder in pairs(wc:GetChildren()) do
                for _, p in pairs(folder:GetChildren()) do
                    if p.Name == myPropName and not existingProps[p] then
                        firstProp = p
                        break
                    end
                end
                if firstProp then break end
            end
            if firstProp then break end
            task.wait(0.05)
        end
    
        if not firstProp then
            isHandlingPropMaker = false
            return {}
        end
    
        local dupRemote = firstProp:FindFirstChild("DuplicateProp") or firstProp:WaitForChild("DuplicateProp", 3)
        if dupRemote then
            for i = 1, (TOTAL_PROPS - 1) do
                if not isDestroyerRunning or currentSession ~= mySession then break end
                pcall(function() dupRemote:InvokeServer() end)
                task.wait(0.05)
            end
        end
    
        task.wait(0.8)
    
        task.wait(1.0)
        pcall(function()
            if ToolRemote then ToolRemote:InvokeServer("PickingTools", "PropMaker") end
            if ClearRemote then ClearRemote:FireServer("ClosePropMenu") end
        end)
        cleanupPropMakerLocal()
        isHandlingPropMaker = false
    
        local collectedProps = {}
        local tVerify = tick()
        while tick() - tVerify < 3.0 and isDestroyerRunning and currentSession == mySession do
            collectedProps = {}
            for _, folder in pairs(wc:GetChildren()) do
                for _, p in pairs(folder:GetChildren()) do
                    if p.Name == myPropName then
                        local scf = p:FindFirstChild("SetCurrentCFrame") or p:FindFirstChildWhichIsA("RemoteFunction", true)
                        local cpc = p:FindFirstChild("ChangePropColor") or p:FindFirstChildWhichIsA("RemoteFunction", true)
                        if scf then
                            table.insert(collectedProps, { Prop = p, SCF = scf, CPC = cpc })
                            for _, pt in ipairs(p:GetDescendants()) do
                                if pt:IsA("BasePart") then
                                    pt.CanCollide = false
                                    pcall(function() pt.Massless = true end)
                                end
                            end
                        end
                    end
                end
            end
            if #collectedProps >= TOTAL_PROPS then break end
            task.wait(0.2)
        end
    
        return collectedProps
    end
    
    local function startServerDestroyer()
        stopServerDestroyer()
        task.wait(0.2)
    
        isDestroyerRunning = true
        currentSession = currentSession + 1
        local mySession = currentSession
        senders = {}
    
        enableAntiSit()
        if updateGuiStatus then updateGuiStatus(true) end
    
        task.spawn(function()
            local char = LocalPlayer.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            local myRoot = char and char:FindFirstChild("HumanoidRootPart")
            if not char or not hum or not myRoot then
                stopServerDestroyer()
                return
            end
    
            local startCF = myRoot.CFrame
            destroyerCenterPos = (startCF * CFrame.new(0, 8, -25)).Position
    
            sendNotification("Server Destroyer", string.format("Summoning 15 %s & Singularity...", selectedProp.Display))
    
            local activeProps = spawnAndCollectToilets(destroyerCenterPos, mySession)
    
            if #activeProps == 0 or not isDestroyerRunning or currentSession ~= mySession then
                sendNotification("Server Destroyer", "Failed to initialize toilets.")
                stopServerDestroyer()
                return
            end
    
            for _, item in ipairs(activeProps) do
                if item.CPC then
                    pcall(function() item.CPC:InvokeServer(Color3.fromRGB(15, 15, 15)) end)
                end
            end
    
            setupGravityVoid()
    
            local sound = Instance.new("Sound")
            sound.SoundId = "rbxassetid://9069609200"
            sound.Volume = 1
            sound.Parent = SoundService
            sound:Play()
    
                                                                
            task.spawn(function()
                task.wait(1.0)
                if not isDestroyerRunning or currentSession ~= mySession then return end
    
                local targets = {}
                local vf = Workspace:FindFirstChild("Vehicles")
                if vf then
                    for _, veh in ipairs(vf:GetChildren()) do
                        local seat = veh:FindFirstChildWhichIsA("VehicleSeat", true) or veh:FindFirstChildWhichIsA("BasePart", true)
                        if seat then table.insert(targets, { Model = veh, TargetPart = seat }) end
                    end
                end
    
                local wcRef = Workspace:FindFirstChild("WorkspaceCom")
                local helis = wcRef and wcRef:FindFirstChild("001_HeliStorage")
                if helis then
                    for _, h in ipairs(helis:GetChildren()) do
                        local seat = h:FindFirstChildWhichIsA("VehicleSeat", true) or h:FindFirstChildWhichIsA("BasePart", true)
                        if seat then table.insert(targets, { Model = h, TargetPart = seat }) end
                    end
                end
    
                if #targets > 0 then
                    for _, item in ipairs(targets) do
                        if not isDestroyerRunning or currentSession ~= mySession then break end
                        if item.TargetPart and item.TargetPart.Parent and myRoot and myRoot.Parent then
                            myRoot.CFrame = item.TargetPart.CFrame * CFrame.new(0, 3.5, 0)
                            task.wait(0.04)
                        end
                    end
                    task.wait(0.3)
                end
    
                if myRoot and myRoot.Parent and isDestroyerRunning and currentSession == mySession then
                    myRoot.CFrame = startCF
                    myRoot.AssemblyLinearVelocity = Vector3.zero
                    myRoot.AssemblyAngularVelocity = Vector3.zero
                end
            end)
    
                                                           
            sendNotification("Server Destroyer", string.format("Chaos Active! 15 %s Hunting & Randomly Teleporting Players...", selectedProp.Display))
    
                                                                 
            mainLoopThread = task.spawn(function()
                local loopCount = 0
    
                while isDestroyerRunning and currentSession == mySession do
                    task.wait(0.03)
                    loopCount = loopCount + 1
    
                                                                       
                    local eligibleVictims = {}
                    for _, p in ipairs(Players:GetPlayers()) do
                        if p ~= LocalPlayer and p.Character then
                            local pHrp = p.Character:FindFirstChild("HumanoidRootPart")
                            local pHum = p.Character:FindFirstChildOfClass("Humanoid")
                            if pHrp and pHum and pHum.Health > 0 then
                                table.insert(eligibleVictims, { Player = p, HRP = pHrp, Hum = pHum, Char = p.Character })
                            end
                        end
                    end
    
                    local numVictims = #eligibleVictims
    
                                                                                                 
                    for idx = 1, #activeProps do
                        local propData = activeProps[idx]
                        if not propData then break end
    
                        if numVictims > 0 then
                            local targetVictim = eligibleVictims[((idx - 1) % numVictims) + 1]
                            local vHrp = targetVictim.HRP
                            local vHum = targetVictim.Hum
    
                            if vHum.Sit then
                                                                                                       
                                local rndDist = math.random(6, 32)
                                local rndAngle = math.random() * math.pi * 2
                                local rndHeight = math.random(-4, 22)
                                local randPos = destroyerCenterPos + Vector3.new(
                                    math.cos(rndAngle) * rndDist,
                                    rndHeight,
                                    math.sin(rndAngle) * rndDist
                                )
                                local randRot = CFrame.Angles(
                                    math.rad(math.random(-180, 180)),
                                    math.rad(math.random(-180, 180)),
                                    math.rad(math.random(-180, 180))
                                )
                                sendCF(propData.SCF, CFrame.new(randPos) * randRot, propData.Prop)
                            else
                                                                                                  
                                local vVel = vHrp.AssemblyLinearVelocity
                                local targetPos = vHrp.Position + (vVel * 0.1) - Vector3.new(0, 1.85, 0)
                                local targetCF = CFrame.new(targetPos, targetPos + vHrp.CFrame.LookVector)
                                sendCF(propData.SCF, targetCF, propData.Prop)
                            end
                        else
                                                                                         
                            local rndDist = math.random(8, 25)
                            local rndAngle = math.random() * math.pi * 2
                            local rndHeight = math.random(-2, 18)
                            local randPos = destroyerCenterPos + Vector3.new(
                                math.cos(rndAngle) * rndDist,
                                rndHeight,
                                math.sin(rndAngle) * rndDist
                            )
                            sendCF(propData.SCF, CFrame.new(randPos, destroyerCenterPos), propData.Prop)
                        end
                    end
                end
            end)
        end)
    end
    

    TrollV3Tab:AddSection({
        "> Server Destroyer (Black Hole Void)"
    })

    local seatOptions = {}
    for _, p in ipairs(SEAT_PROPS) do
        table.insert(seatOptions, p.Display)
    end

    TrollV3Tab:AddDropdown({
        Name = "Seat Prop Model",
        Description = "Select which prop is used for the black hole gravity vortex",
        Options = seatOptions,
        Default = selectedProp.Display,
        Callback = function(choice)
            for i, p in ipairs(SEAT_PROPS) do
                if p.Display == choice then
                    currentPropIndex = i
                    selectedProp = p
                    sendNotification("Server Destroyer", "Selected: " .. p.Display)
                    if isDestroyerRunning then
                        task.spawn(function()
                            startServerDestroyer()
                        end)
                    end
                    break
                end
            end
        end
    })

    local destroyerToggle = TrollV3Tab:AddToggle({
        Name = "Server Destroyer",
        Description = "Spawns 15 props in a swirling black hole vortex that pulls all unanchored objects and players",
        Default = false,
        Callback = function(val)
            if val then
                startServerDestroyer()
            else
                stopServerDestroyer()
            end
        end
    })

    LocalPlayer.CharacterAdded:Connect(function(char)
        local hum = char:WaitForChild("Humanoid", 5)
        if hum then
            hum.Died:Connect(function()
                if isDestroyerRunning then stopServerDestroyer() end
            end)
        end
    end)
end
_btrInitTrollV3ServerDestroyer()


local function _btrInitTrollV3GyrosphereFling()
    if not TrollV3Tab then return end

    local Players = game:GetService("Players")
    local Workspace = game:GetService("Workspace")
    local RunService = game:GetService("RunService")
    local CoreGui = game:GetService("CoreGui")
    local StarterGui = game:GetService("StarterGui")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    
    local lp = Players.LocalPlayer
    local char = lp.Character or lp.CharacterAdded:Wait()
    local hrp = char:WaitForChild("HumanoidRootPart")
    local hum = char:WaitForChild("Humanoid")
    
    lp.CharacterAdded:Connect(function(c)
        char = c
        hrp = c:WaitForChild("HumanoidRootPart")
        hum = c:WaitForChild("Humanoid")
    end)
    
    local function notify(title, text, dur)
        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = title or "Gyrosphere Fling",
                Text = text or "",
                Duration = dur or 3
            })
        end)
    end
    
    local function boostSimulationRadius()
        pcall(function()
            lp.ReplicationFocus = Workspace
            if setscriptable then
                setscriptable(lp, "SimulationRadius", true)
                setscriptable(lp, "MaximumSimulationRadius", true)
            end
            if sethiddenproperty then
                sethiddenproperty(lp, "MaximumSimulationRadius", 1e9)
                sethiddenproperty(lp, "SimulationRadius", 1e9)
            end
        end)
    end
    
    local VEHICLE_NAME = "Jurassic2026_Gyrosphere"
    local myCarName = lp.Name .. "Car"
    
    local function getMyVehicle()
        local vFolder = Workspace:FindFirstChild("Vehicles")
        if vFolder then
            local found = vFolder:FindFirstChild(myCarName)
            if found and found:IsA("Model") then return found end
        end
        for _, v in ipairs(Workspace:GetChildren()) do
            if v:IsA("Model") and v.Name == myCarName then return v end
        end
        return nil
    end
    
    local function spawnGyrosphere()
        local existing = getMyVehicle()
        if existing then return existing end
    
        local re = ReplicatedStorage:FindFirstChild("RE")
        local carRemote = re and re:FindFirstChild("1Ca1r")
        if not carRemote then
            notify("Error", "Car remote (1Ca1r) not found!", 3)
            return nil
        end
    
        carRemote:FireServer("PickingCar", VEHICLE_NAME)
    
        local start = tick()
        while tick() - start < 3.5 do
            task.wait(0.1)
            local veh = getMyVehicle()
            if veh then return veh end
        end
        return nil
    end
    
    local function deleteMyVehicle()
        local re = ReplicatedStorage:FindFirstChild("RE")
        local carRemote = re and re:FindFirstChild("1Ca1r")
        if carRemote then
            carRemote:FireServer("DeleteAllVehicles")
        end
    end
    
    local function sitInVehicle(veh)
        if not veh then return false end
        local myChar = lp.Character
        local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
        local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myHum or not myHrp then return false end

                                                                 
        if myHum.Sit and myHum.SeatPart and myHum.SeatPart:IsDescendantOf(veh) then
            return true
        end

        local seat = veh:FindFirstChildWhichIsA("VehicleSeat", true)
        if not seat then
            for _, s in ipairs(veh:GetDescendants()) do
                if s:IsA("VehicleSeat") or s:IsA("Seat") then
                    seat = s
                    break
                end
            end
        end
        if not seat then return false end
    
        boostSimulationRadius()
    
        pcall(function()
            seat.Disabled = false
            seat.CanTouch = true
            myHum:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
        end)
    
        local start = tick()
        while tick() - start < 2.5 do
            if myHum.Sit and myHum.SeatPart then return true end
            myHrp.CFrame = seat.CFrame * CFrame.new(0, 1.2, 0)
            pcall(function()
                seat.Disabled = false
                seat.CanTouch = true
                myHum:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
                if firetouchinterest then
                    firetouchinterest(myHrp, seat, 0)
                    task.wait(0.02)
                    firetouchinterest(myHrp, seat, 1)
                end
                seat:Sit(myHum)
                myHum:ChangeState(Enum.HumanoidStateType.Seated)
            end)
            task.wait(0.08)
        end
    
        return myHum.Sit and (myHum.SeatPart ~= nil)
    end
    
    local isFlingActive = false
    local isStoppingFling = false
    local currentVehicle = nil
    local flingLoopConn = nil
    local steppedConn = nil
    local originalCFrame = nil
    
                                                                                                     
    local function stopFling(returnToOriginal, success)
        if isStoppingFling then return end
        isStoppingFling = true
        isFlingActive = false

        _G.VehicleFlingActive = false
        _G.VehicleFlingCar = nil

        if flingLoopConn then
            flingLoopConn:Disconnect()
            flingLoopConn = nil
        end
        if steppedConn then
            steppedConn:Disconnect()
            steppedConn = nil
        end
    
        local myChar = lp.Character
        local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
        local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")

                                                                                
        if myHrp and myHrp.Parent then
            pcall(function() myHrp.Anchored = true end)
        end

                                     
        local veh = currentVehicle or getMyVehicle()
        if veh then
            local primary = veh.PrimaryPart or veh:FindFirstChildWhichIsA("VehicleSeat", true) or veh:FindFirstChildWhichIsA("BasePart", true)
            if primary then
                pcall(function()
                    primary.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                    primary.AssemblyAngularVelocity = Vector3.zero
                    primary.RotVelocity = Vector3.new(0, 0, 0)
                    primary.Velocity = Vector3.new(0, 0, 0)
                end)
            end
        end
        task.wait()

                                              
        if myHum then
            myHum.Sit = false
            pcall(function() myHum:UnequipTools() end)
        end
        task.wait()

                                             
        if myHrp and myHrp.Parent then
            pcall(function()
                myHrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                myHrp.RotVelocity = Vector3.new(0, 0, 0)
                myHrp.Velocity = Vector3.new(0, 0, 0)
            end)
        end

                                                                                    
        if veh then
            pcall(function()
                veh:PivotTo(CFrame.new(0, -90000, 0))
            end)
        end
        task.wait(0.1)

                                        
        deleteMyVehicle()
        task.wait(0.15)

                                                                                                   
        if returnToOriginal and originalCFrame and myHrp and myHrp.Parent then
            for _ = 1, 3 do
                pcall(function() myHrp.CFrame = originalCFrame end)
                task.wait()
            end
            pcall(function()
                myHrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                myHrp.RotVelocity = Vector3.new(0, 0, 0)
                myHrp.Velocity = Vector3.new(0, 0, 0)
            end)
            originalCFrame = nil
        end

                                                                                                 
        task.spawn(function()
            for _ = 1, 5 do
                task.wait()
                if myHrp and myHrp.Parent then
                    pcall(function()
                        myHrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                        myHrp.Velocity = Vector3.new(0, 0, 0)
                    end)
                end
            end
            if myHrp and myHrp.Parent then
                pcall(function() myHrp.Anchored = false end)
            end
            isStoppingFling = false
        end)

        currentVehicle = nil
    end
    
    local function runFlingAttack(targetPlayer)
        if isFlingActive then stopFling(false) task.wait(0.2) end
        if not targetPlayer or targetPlayer == lp then
            notify("Error", "Select a valid target player!", 3)
            return
        end
    
        local tChar = targetPlayer.Character
        local tHrp = tChar and tChar:FindFirstChild("HumanoidRootPart")
        local tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")
        if not tHrp or not tHum then
            notify("Error", "Target player has no HumanoidRootPart!", 3)
            return
        end
    
        local myChar = lp.Character
        local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
        local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
        if not myHrp or not myHum then return end
    
        originalCFrame = myHrp.CFrame
        notify("Gyrosphere", "Spawning & Mounting Jurassic Gyrosphere...", 2)
    
        local veh = spawnGyrosphere()
        if not veh then
            notify("Error", "Failed to spawn Gyrosphere!", 3)
            return
        end
        currentVehicle = veh
        _G.VehicleFlingCar = veh
        _G.VehicleFlingActive = true
    
        local seated = sitInVehicle(veh)
        if not seated then
            notify("Error", "Failed to sit in Gyrosphere!", 3)
            stopFling(false)
            return
        end
    
        local primary = veh.PrimaryPart or veh:FindFirstChildWhichIsA("VehicleSeat", true) or veh:FindFirstChildWhichIsA("BasePart", true)
        if not primary then
            notify("Error", "Gyrosphere has no PrimaryPart!", 3)
            stopFling(false)
            return
        end
    
        for _, part in ipairs(veh:GetDescendants()) do
            if part:IsA("BasePart") then
                part.CanCollide = true
                if part ~= primary then
                    local wc = part:FindFirstChild("GyrosphereGlassLock")
                    if not wc then
                        wc = Instance.new("WeldConstraint")
                        wc.Name = "GyrosphereGlassLock"
                        wc.Part0 = primary
                        wc.Part1 = part
                        wc.Parent = part
                    end
                end
            end
        end
    
        pcall(function()
            myHum:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
            myHum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
            myHum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)
        end)
    
        isFlingActive = true
        notify("FLING ENGAGED", "Solid Glass Ram active on " .. targetPlayer.DisplayName .. "!", 3)
    
        steppedConn = RunService.Stepped:Connect(function()
            if not isFlingActive then return end
            local c = lp.Character
            if c then
                for _, p in ipairs(c:GetDescendants()) do
                    if p:IsA("BasePart") then
                        p.CanCollide = false
                    end
                end
            end
            if veh and veh.Parent then
                for _, p in ipairs(veh:GetDescendants()) do
                    if p:IsA("BasePart") then
                        p.CanCollide = true
                    end
                end
            end
        end)
    
        flingLoopConn = RunService.Heartbeat:Connect(function(dt)
            if not isFlingActive then return end
    
            local curTChar = targetPlayer.Character
            local curTHrp = curTChar and curTChar:FindFirstChild("HumanoidRootPart")
            local curTHum = curTChar and curTChar:FindFirstChildOfClass("Humanoid")
    
            if not curTHrp or not curTHum or curTHum.Health <= 0 then
                return
            end
    
            local myCurChar = lp.Character
            local myCurHum = myCurChar and myCurChar:FindFirstChildOfClass("Humanoid")
            if not myCurHum or not myCurHum.Sit then
                pcall(function() sitInVehicle(veh) end)
            end
    
            boostSimulationRadius()
    
            local targetPart = curTHrp
            local isCarTarget = false
            if curTHum.Sit and curTHum.SeatPart then
                local tVeh = curTHum.SeatPart:FindFirstAncestorOfClass("Model")
                if tVeh and tVeh ~= veh then
                    targetPart = tVeh.PrimaryPart or curTHum.SeatPart
                    isCarTarget = true
                end
            end
    
            local tPos = targetPart.Position
            local t = tick()
            local spinSpeed = 28
            local angle = t * spinSpeed
    
            local baseDist = isCarTarget and 3.0 or 1.2
            local pulseDist = math.max(0.5, baseDist + (math.sin(t * 40) * 0.8))
    
            local strikeOffset = Vector3.new(
                math.cos(angle) * pulseDist,
                math.sin(t * 16) * 0.3,
                math.sin(angle) * pulseDist
            )
            local strikePos = tPos + strikeOffset
            local strikeCF = CFrame.lookAt(strikePos, tPos)
    
            local ramDir = (tPos - strikePos).Unit
            local flingLinear = (ramDir * 40000) + Vector3.new(0, 15000, 0)
    
            pcall(function()
                veh:PivotTo(strikeCF)
            end)
    
            if primary and primary.Parent then
                pcall(function()
                    primary.AssemblyLinearVelocity = flingLinear
                    primary.AssemblyAngularVelocity = Vector3.zero
                    primary.Velocity = flingLinear
                    primary.RotVelocity = Vector3.new(0, 10000, 0)
                end)
            end
        end)

        local attackStart = tick()
        local success = false
        while isFlingActive do
            task.wait(0.05)
            local curTChar = targetPlayer.Character
            local curTHrp = curTChar and curTChar:FindFirstChild("HumanoidRootPart")
            local curTHum = curTChar and curTChar:FindFirstChildOfClass("Humanoid")
            if not curTHrp or not curTHum or curTHum.Health <= 0 then
                success = true
                break
            end
            local elapsed = tick() - attackStart
            local isFlinged = (curTHrp.Position.Y < -20) or (curTHrp.AssemblyLinearVelocity.Magnitude > 150) or (curTHum.Sit and not (curTHum.SeatPart and curTHum.SeatPart:FindFirstAncestorOfClass("Model") == veh))
            if isFlinged then
                success = true
                break
            end
            if elapsed > 2.5 then
                break
            end
        end

        stopFling(true, success)
        local notifMsg = success and "Target flinged & safe return complete!" or "Attack finished & safe return complete!"
        notify("Gyrosphere Fling", notifMsg, 2)
    end

    TrollV3Tab:AddSection({
        "> Gyrosphere Vehicle Fling (Solid Physics)"
    })

    local function getTargetPlayerList()
        local list = {}
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer then
                table.insert(list, p.Name)
            end
        end
        return list
    end

    local selectedTargetName = nil

    local gyroPlayerDropdown = TrollV3Tab:AddDropdown({
        Name = "Target Player",
        Description = "Select player to ram and fling with the Gyrosphere",
        Options = getTargetPlayerList(),
        Default = "---",
        Callback = function(val)
            selectedTargetName = val
        end
    })

    TrollV3Tab:AddButton({
        Name = "Refresh Player List",
        Description = "Refresh the list of available target players",
        Callback = function()
            pcall(function() gyroPlayerDropdown:Set(getTargetPlayerList()) end)
        end
    })

    TrollV3Tab:AddButton({
        Name = "Fling Target (Gyrosphere)",
        Description = "Rams target with solid Gyrosphere collision (auto disables Anti-Sit during attack)",
        Callback = function()
            if not selectedTargetName or selectedTargetName == "---" then
                notify("Gyrosphere", "Select a target player first!", 2)
                return
            end
            local tgt = Players:FindFirstChild(selectedTargetName)
            if not tgt then
                notify("Gyrosphere", "Target player not found in server!", 2)
                return
            end
            if isFlingActive then
                notify("Gyrosphere", "Fling is already running!", 2)
                return
            end
            task.spawn(function()
                local wrapper = _G.withAntiSitDisabled or withAntiSitDisabled
                if wrapper then
                    wrapper(function()
                        runFlingAttack(tgt)
                    end)
                else
                    runFlingAttack(tgt)
                end
            end)
        end
    })

    TrollV3Tab:AddButton({
        Name = "Stop Fling",
        Description = "Immediately aborts vehicle fling and safely teleports back without velocity",
        Callback = function()
            stopFling(true, false)
            notify("Gyrosphere", "Fling aborted & safely returned!", 2)
        end
    })

    TrollV3Tab:AddButton({
        Name = "Spawn Gyrosphere",
        Description = "Spawns the Jurassic 2026 Gyrosphere vehicle",
        Callback = function()
            task.spawn(function()
                local v = spawnGyrosphere()
                if v then
                    notify("Spawned", "Jurassic Gyrosphere ready!", 2)
                end
            end)
        end
    })

    TrollV3Tab:AddButton({
        Name = "Delete Vehicle",
        Description = "Deletes your currently spawned vehicle",
        Callback = function()
            stopFling(false, false)
            deleteMyVehicle()
            notify("Deleted", "Vehicle deleted!", 2)
        end
    })
end
_btrInitTrollV3GyrosphereFling()


local function _btrInitTrollV3SpinPlayer()
    if not TrollV3Tab then return end

                           
                                                   
                                                                              
    
    local Players = game:GetService("Players")
    local Workspace = game:GetService("Workspace")
    local RunService = game:GetService("RunService")
    local CoreGui = game:GetService("CoreGui")
    local StarterGui = game:GetService("StarterGui")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local TweenService = game:GetService("TweenService")
    local UserInputService = game:GetService("UserInputService")
    
    local LocalPlayer = Players.LocalPlayer
    
                       
    pcall(function() Workspace.FallenPartsDestroyHeight = 0/0 end)
    pcall(function() Workspace.FallenPartsDestroyHeight = -50000 end)
    
    local function getGuiParent()
        if gethui then
            local h = gethui()
            if h then return h end
        end
        local ok, res = pcall(function() return CoreGui end)
        if ok and res then return res end
        return LocalPlayer:WaitForChild("PlayerGui")
    end
    
    local function notify(title, text, duration)
        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = title or "Spin Admin",
                Text = text or "",
                Duration = duration or 3
            })
        end)
    end
    
                        
    local EXISTING_GUI = getGuiParent():FindFirstChild("BTR_SpinTest_GUI")
    if EXISTING_GUI then EXISTING_GUI:Destroy() end
    
    local RE = ReplicatedStorage:WaitForChild("RE", 5)
    local ToolRemote = RE and RE:WaitForChild("1Too1l", 5)
    local ClearRemote = RE and RE:WaitForChild("1Clea1rTool1s", 5)
    
    local PROP_NAME = "FloorCushion"
    local PROP_CATEGORY = "Furniture"
    
    local SpinSystem = {
        Active = false,
        CurrentSession = 0,
        TargetName = nil,
        SpinSpeed = 45,                                
        Elevation = 7,                       
        Mode = "Spin",                       
        PropData = nil,
        MainThread = nil,
        RateLimit = 0.03
    }
    
    local function cleanupPropMakerLocal()
        local char = LocalPlayer.Character
        local bp = LocalPlayer:FindFirstChild("Backpack")
        local t1 = char and char:FindFirstChild("PropMaker")
        local t2 = bp and bp:FindFirstChild("PropMaker")
        if t1 then t1.Parent = bp end
        if t2 then
            pcall(function()
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                if hum then hum:UnequipTools() end
            end)
        end
    end
    
    local function _0xH_3f2()
