            task.wait(0.2)
        end
    
        local beforeProps = {}
        for _, folder in pairs(wc:GetChildren()) do
            for _, p in pairs(folder:GetChildren()) do
                if p.Name == myPropName or p.Name:find(LocalPlayer.Name) then 
                    beforeProps[p] = true 
                end
            end
        end
    
        local myRoot = char and char:FindFirstChild("HumanoidRootPart")
        local spawnPos = (myRoot and myRoot.Position) or Vector3.new(0, 5, 0)
        pcall(function() toolPropMake:FireServer(Workspace.Terrain, spawnPos) end)
    
        local targetProp = nil
        local t0 = tick()
        while tick() - t0 < 3.5 do
            if not SpinSystem.Active or SpinSystem.CurrentSession ~= mySession then return nil end
            for _, folder in pairs(wc:GetChildren()) do
                for _, p in pairs(folder:GetChildren()) do
                    local isMine = (p.Name == myPropName) or (p.Name:find(LocalPlayer.Name) ~= nil)
                    if isMine and not beforeProps[p] then
                        targetProp = p
                        break
                    end
                end
                if targetProp then break end
            end
            if targetProp then break end
            task.wait(0.05)
        end
    
        if not targetProp then return nil end
    
                                                                                
        task.wait(1.0)
        pcall(function()
            if ToolRemote then ToolRemote:InvokeServer("PickingTools", "PropMaker") end
            if ClearRemote then ClearRemote:FireServer("ClosePropMenu") end
        end)
        cleanupPropMakerLocal()
    
        local scf = targetProp:FindFirstChild("SetCurrentCFrame") or targetProp:FindFirstChildWhichIsA("RemoteFunction", true)
        local seat = targetProp:FindFirstChildWhichIsA("Seat", true)
        if seat then seat.Disabled = false end
    
        for _, pt in ipairs(targetProp:GetDescendants()) do
            if pt:IsA("BasePart") then
                pt.CanCollide = false
                pcall(function() pt.Massless = true end)
            elseif pt:IsA("ProximityPrompt") then
                pt.Enabled = false
                pt.MaxActivationDistance = 0
            end
        end
    
        return { Prop = targetProp, SCF = scf, Seat = seat }
    end
    
    function SpinSystem.stop()
        if not SpinSystem.Active then return end
        SpinSystem.Active = false
        SpinSystem.CurrentSession = SpinSystem.CurrentSession + 1
    
        if SpinSystem.MainThread then
            task.cancel(SpinSystem.MainThread)
            SpinSystem.MainThread = nil
        end
    
        SpinSystem.PropData = nil
    
                                                       
        if ClearRemote then
            pcall(function() ClearRemote:FireServer("ClearAllProps") end)
        end
        cleanupPropMakerLocal()
        notify("Spin Admin", "System deactivated and props cleared.")
    end
    
    function SpinSystem.start(targetPlayerName, spinSpeed, launchAfterSpin)
        SpinSystem.stop()
        task.wait(0.15)
    
        SpinSystem.Active = true
        SpinSystem.CurrentSession = SpinSystem.CurrentSession + 1
        local mySession = SpinSystem.CurrentSession
        SpinSystem.TargetName = targetPlayerName
        SpinSystem.SpinSpeed = spinSpeed or 45
    
        notify("Spin Admin", "Deploying prop for " .. tostring(targetPlayerName) .. "...")
    
        SpinSystem.MainThread = task.spawn(function()
            local pData = spawnSingleProp(mySession)
            if not pData or not SpinSystem.Active or SpinSystem.CurrentSession ~= mySession then
                SpinSystem.stop()
                return
            end
            SpinSystem.PropData = pData
    
            notify("Spin Admin", "Prop ready! Engaging capture sequence.")
    
            local angle = 0
            local target = Players:FindFirstChild(targetPlayerName)
            local captureCooldown = 0
            local spinStartTime = 0
            local isTargetSeated = false
            local anchorPos = nil
    
            while SpinSystem.Active and SpinSystem.CurrentSession == mySession do
                local dt = task.wait(SpinSystem.RateLimit)
    
                if not target or not target.Parent then
                    target = Players:FindFirstChild(targetPlayerName)
                end
    
                local tChar = target and target.Character
                local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                local tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")
    
                if not tChar or not tRoot or not tHum or tHum.Health <= 0 then
                                                       
                    local myChar = LocalPlayer.Character
                    local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                    if myRoot then
                        sendCF(pData.SCF, myRoot.CFrame * CFrame.new(0, 15, 0), pData.Prop)
                    end
                else
                    local vicChar, vicHum = checkVictimSeated(pData.Seat)
                    local isCurrentTargetOnSeat = (vicChar == tChar)
    
                    if isCurrentTargetOnSeat then
                                                                                        
                        if not isTargetSeated then
                            isTargetSeated = true
                            spinStartTime = tick()
                                                                                                          
                            local ray = Workspace:Raycast(tRoot.Position + Vector3.new(0, 2, 0), Vector3.new(0, -15, 0))
                            local groundY = ray and ray.Position.Y or (tRoot.Position.Y - 2.5)
                            anchorPos = Vector3.new(tRoot.Position.X, groundY + 0.35, tRoot.Position.Z)
                            notify("Spin Admin", target.DisplayName .. " trapped! Pure Ground-Locked Spin active!")
                        end
    
                        angle = (angle + dt * SpinSystem.SpinSpeed) % (math.pi * 2)
    
                                                                                          
                        local spinCF = CFrame.new(anchorPos) * CFrame.Angles(0, angle, 0)
    
                        sendCF(pData.SCF, spinCF, pData.Prop)
    
                                                                                      
                        if launchAfterSpin and (tick() - spinStartTime > 4.0) then
                            notify("Spin Admin", "Centrifugal launch triggered!")
                            local launchHeight = anchorPos.Y
                            for h = 1, 15 do
                                if not SpinSystem.Active or SpinSystem.CurrentSession ~= mySession then break end
                                launchHeight = launchHeight + (h * 15)
                                angle = angle + 2.0
                                local upCF = CFrame.new(anchorPos.X, launchHeight, anchorPos.Z) * CFrame.Angles(0, angle, 0)
                                sendCF(pData.SCF, upCF, pData.Prop)
                                task.wait(0.03)
                            end
                            task.wait(0.2)
                            spinStartTime = tick()
                        end
                    else
                                                                                         
                        isTargetSeated = false
                        angle = (angle + dt * 10) % (math.pi * 2)
    
                                                                    
                        local vel = tRoot.AssemblyLinearVelocity or Vector3.zero
                        local leadOffset = vel * 0.12
    
                                                                                                                             
                        local microJitter = Vector3.new(
                            math.sin(tick() * 30) * 0.4,
                            -1.8,
                            math.cos(tick() * 30) * 0.4
                        )
                        local harpoonCF = CFrame.new(tRoot.Position + leadOffset + microJitter)
                            * CFrame.Angles(0, angle, 0)
    
                        sendCF(pData.SCF, harpoonCF, pData.Prop)
                    end
                end
            end
        end)
    end
    

    TrollV3Tab:AddSection({
        "> Spin Player (Centrifugal Launcher)"
    })

    local function getSpinPlayerList()
        local list = {}
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer then
                table.insert(list, p.Name)
            end
        end
        return list
    end

    local spinTargetName = nil
    local spinSpeedSetting = 45
    local launchAfterSpinSetting = false

    local spinTargetDropdown = TrollV3Tab:AddDropdown({
        Name = "Target Player",
        Description = "Select player to capture and spin at hyper-velocity",
        Options = getSpinPlayerList(),
        Default = "---",
        Callback = function(val)
            spinTargetName = val
        end
    })

    TrollV3Tab:AddButton({
        Name = "Refresh Player List",
        Description = "Refresh the target player list",
        Callback = function()
            pcall(function() spinTargetDropdown:Set(getSpinPlayerList()) end)
        end
    })

    TrollV3Tab:AddSlider({
        Name = "Spin Speed",
        Description = "Rotation speed in radians per second",
        Min = 10,
        Max = 100,
        Increase = 5,
        Default = 45,
        Callback = function(val)
            spinSpeedSetting = val
            if SpinSystem.Active then
                SpinSystem.SpinSpeed = val
            end
        end
    })

    TrollV3Tab:AddToggle({
        Name = "Centrifugal Launch Mode",
        Description = "Launch player into the stratosphere after 2.5 seconds of high-speed spin",
        Default = false,
        Callback = function(val)
            launchAfterSpinSetting = val
        end
    })

    local spinToggle = TrollV3Tab:AddToggle({
        Name = "Spin Target Player",
        Description = "Captures the victim with FloorCushion and starts spinning or launching them",
        Default = false,
        Callback = function(val)
            if val then
                if not spinTargetName or spinTargetName == "---" then
                    notify("Spin Admin", "Select a target player first!", 2)
                    return
                end
                SpinSystem.start(spinTargetName, spinSpeedSetting, launchAfterSpinSetting)
            else
                SpinSystem.stop()
            end
        end
    })
end
_btrInitTrollV3SpinPlayer()


