    function SwapSystem.stop()
        if not SwapSystem.Active then return end
        SwapSystem.Active = false
        SwapSystem.CurrentSession = SwapSystem.CurrentSession + 1
    
        if SwapSystem.MainThread then
            task.cancel(SwapSystem.MainThread)
            SwapSystem.MainThread = nil
        end
    
        SwapSystem.Props = {}
    
                                                       
        if ClearRemote then
            pcall(function() ClearRemote:FireServer("ClearAllProps") end)
        end
        cleanupPropMakerLocal()
        notify("Swap Admin", "System stopped and props cleared.")
    end
    
    function SwapSystem.start(nameA, nameB, loopSwap)
        SwapSystem.stop()
        task.wait(0.15)
    
        SwapSystem.Active = true
        SwapSystem.CurrentSession = SwapSystem.CurrentSession + 1
        local mySession = SwapSystem.CurrentSession
        SwapSystem.PlayerA = nameA
        SwapSystem.PlayerB = nameB
    
        notify("Swap Admin", string.format("Deploying 2 Props for %s & %s...", nameA, nameB))
    
        SwapSystem.MainThread = task.spawn(function()
            local pair = spawnTwoProps(mySession)
            if not pair or not SwapSystem.Active or SwapSystem.CurrentSession ~= mySession then
                SwapSystem.stop()
                notify("Swap Admin", "Failed to spawn 2 props.")
                return
            end
            SwapSystem.Props = pair
            local propA = pair[1]
            local propB = pair[2]
    
            notify("Swap Admin", "Both props ready! Tracking players...")
    
            local angle = 0
    
            while SwapSystem.Active and SwapSystem.CurrentSession == mySession do
                local pA = Players:FindFirstChild(nameA)
                local pB = Players:FindFirstChild(nameB)
    
                local cA = pA and pA.Character
                local cB = pB and pB.Character
                local rA = cA and cA:FindFirstChild("HumanoidRootPart")
                local rB = cB and cB:FindFirstChild("HumanoidRootPart")
                local hA = cA and cA:FindFirstChildOfClass("Humanoid")
                local hB = cB and cB:FindFirstChildOfClass("Humanoid")
    
                if not rA or not rB or not hA or not hB or hA.Health <= 0 or hB.Health <= 0 then
                    task.wait(0.2)
                else
                                                                   
                    local vicA = checkVictimSeated(propA.Seat)
                    local vicB = checkVictimSeated(propB.Seat)
    
                    local aReady = (vicA == cA)
                    local bReady = (vicB == cB)
    
                    angle = (angle + 0.5) % (math.pi * 2)
    
                    if not aReady then
                        local velA = rA.AssemblyLinearVelocity or Vector3.zero
                        local jitterA = Vector3.new(math.sin(tick() * 25) * 0.35, -1.8, math.cos(tick() * 25) * 0.35)
                        local cfHarpoonA = CFrame.new(rA.Position + (velA * 0.12) + jitterA) * CFrame.Angles(0, angle, 0)
                        sendCF(propA.SCF, cfHarpoonA, propA.Prop)
                    end
    
                    if not bReady then
                        local velB = rB.AssemblyLinearVelocity or Vector3.zero
                        local jitterB = Vector3.new(math.sin(tick() * 25 + 1) * 0.35, -1.8, math.cos(tick() * 25 + 1) * 0.35)
                        local cfHarpoonB = CFrame.new(rB.Position + (velB * 0.12) + jitterB) * CFrame.Angles(0, angle, 0)
                        sendCF(propB.SCF, cfHarpoonB, propB.Prop)
                    end
    
                                                                                                                   
                    if aReady and bReady then
                        local posA = rA.Position
                        local posB = rB.Position
    
                        notify("Swap Admin", "Both players seated! SWAPPING POSITIONS NOW!")
    
                        local sound = Instance.new("Sound")
                        sound.SoundId = "rbxassetid://9069609200"
                        sound.Volume = 1
                        sound.Parent = SoundService
                        sound:Play()
    
                                                                                    
                        local destA = CFrame.new(posB + Vector3.new(0, 0.5, 0))
                        sendCF(propA.SCF, destA, propA.Prop)
    
                                                                                    
                        local destB = CFrame.new(posA + Vector3.new(0, 0.5, 0))
                        sendCF(propB.SCF, destB, propB.Prop)
    
                        task.wait(0.12)
    
                                                                        
                        if ClearRemote then
                            pcall(function() ClearRemote:FireServer("ClearAllProps") end)
                        end
                        cleanupPropMakerLocal()
    
                        if not loopSwap then
                            SwapSystem.stop()
                            if SwapSystem.ActionBtn then
                                SwapSystem.ActionBtn.Text = "EXECUTE :swap"
                                SwapSystem.ActionBtn.BackgroundColor3 = Color3.fromRGB(0, 185, 255)
                            end
                            break
                        else
                                                                             
                            task.wait(3.0)
                        end
                    end
                end
    
                task.wait(SwapSystem.RateLimit)
            end
        end)
    end
    

    TrollV3Tab:AddSection({
        "> Swap Player Positions (FE)"
    })

    local function getSwapPlayerList()
        local list = {}
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer then
                table.insert(list, p.Name)
            end
        end
        return list
    end

    local swapPlayerA = nil
    local swapPlayerB = nil
    local loopSwapSetting = false

    local dropdownA = TrollV3Tab:AddDropdown({
        Name = "Target Player A",
        Description = "First player to capture and swap",
        Options = getSwapPlayerList(),
        Default = "---",
        Callback = function(val)
            swapPlayerA = val
        end
    })

    local dropdownB = TrollV3Tab:AddDropdown({
        Name = "Target Player B",
        Description = "Second player to swap with Player A",
        Options = getSwapPlayerList(),
        Default = "---",
        Callback = function(val)
            swapPlayerB = val
        end
    })

    TrollV3Tab:AddButton({
        Name = "Refresh Player Lists",
        Description = "Update player dropdowns with current server players",
        Callback = function()
            local plrs = getSwapPlayerList()
            pcall(function() dropdownA:Set(plrs) end)
            pcall(function() dropdownB:Set(plrs) end)
        end
    })

    TrollV3Tab:AddToggle({
        Name = "Continuous Loop Swap",
        Description = "Continuously swap positions back and forth every second",
        Default = false,
        Callback = function(val)
            loopSwapSetting = val
        end
    })

    local swapToggle = TrollV3Tab:AddToggle({
        Name = "Execute Swap",
        Description = "Spawns 2 props, captures Player A & B, and swaps their positions immediately",
        Default = false,
        Callback = function(val)
            if val then
                if not swapPlayerA or swapPlayerA == "---" or not swapPlayerB or swapPlayerB == "---" then
                    notify("Swap Admin", "Select both Player A and Player B first!", 2)
                    return
                end
                if swapPlayerA == swapPlayerB then
                    notify("Swap Admin", "Player A and Player B must be different!", 2)
                    return
                end
                SwapSystem.start(swapPlayerA, swapPlayerB, loopSwapSetting)
            else
                SwapSystem.stop()
            end
        end
    })
end
_btrInitTrollV3SwapPlayer()


