        local function playFENote(soundId)
            if not soundId or soundId == "" then return end
            task.spawn(function()
                local remote = ReplicatedStorage:FindFirstChild("RE")
                if not (remote and remote:FindFirstChild("1Gu1n")) then return end
                local gunRemote = remote["1Gu1n"]

                for _, player in ipairs(Players:GetPlayers()) do
                    if player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
                        local hrp = player.Character.HumanoidRootPart
                        local args = {
                            [1] = hrp,
                            [2] = hrp,
                            [3] = Vector3.new(0, -1, 0),
                            [4] = Vector3.new(0, 0, 0),
                            [5] = hrp,
                            [6] = hrp,
                            [7] = tostring(soundId),
                            [8] = tostring(soundId),
                            [9] = { [1] = true },
                            [10] = {
                                [1] = 25,
                                [2] = Vector3.new(0.25, 0.25, 100),
                                [3] = BrickColor.new(24),
                                [4] = 0.25,
                                [5] = Enum.Material.SmoothPlastic,
                                [6] = 0.25
                            },
                            [11] = true,
                            [12] = false
                        }
                        pcall(function()
                            gunRemote:FireServer(unpack(args))
                        end)
                    end
                end
            end)
        end

                                                       
        local NOTE_STAGGER_INTERVAL = 0.045
        local nextAvailablePlayTime = 0

        local function queueFENote(soundId)
            if not soundId or soundId == "" then return end
            local now = os.clock()
            local scheduledTime = math.max(now, nextAvailablePlayTime + NOTE_STAGGER_INTERVAL)
            nextAvailablePlayTime = math.min(scheduledTime, now + 0.45)

            local delay = nextAvailablePlayTime - now
            if delay <= 0.002 then
                playFENote(soundId)
            else
                task.delay(delay, function()
                    playFENote(soundId)
                end)
            end
        end

        local function animateKeyPress(noteName)
            local btn = keyButtons[noteName]
            if not btn then return end

            local isBlack = noteName:find("#") ~= nil
            local origColor = isBlack and Color3.fromRGB(24, 26, 32) or Color3.fromRGB(245, 245, 250)
            local activeColor = isBlack and Color3.fromRGB(0, 230, 255) or Color3.fromRGB(130, 235, 255)

            btn.BackgroundColor3 = activeColor
            task.delay(0.14, function()
                if btn and btn.Parent then
                    TweenService:Create(btn, TweenInfo.new(0.16), {BackgroundColor3 = origColor}):Play()
                end
            end)
        end

        local function playLocalSound(soundId)
            local cam = Workspace.CurrentCamera or Workspace:FindFirstChildWhichIsA("Camera")
            local snd = Instance.new("Sound")
            snd.SoundId = "rbxassetid://" .. soundId
            snd.Volume = 2.0
            snd.RollOffMaxDistance = 10000
            snd.Parent = cam or Workspace
            snd:Play()
            Debris:AddItem(snd, 3.5)
        end

        local function playNote(noteName)
            if not noteName then return end

                              
            animateKeyPress(noteName)

                                           
            if octaveShift ~= 0 then
                local base = noteName:match("^([A-G]#?)")
                local oct = tonumber(noteName:match("(%d+)$"))
                if oct then
                    local newOct = math.clamp(oct + octaveShift, 2, 6)
                    local shiftedNote = base .. newOct
                    if PianoNotes[shiftedNote] then
                        noteName = shiftedNote
                    end
                end
            end

            local id = PianoNotes[noteName]
            if not id then return end

                                                                                                                      
            task.spawn(function()
                playLocalSound(id)
            end)

                                                                                                                                   
            queueFENote(id)
        end

                                                                                    
                               
                                                                                    
