        local function makeActionBtn(txt, bgCol, width)
            local b = Instance.new("TextButton")
            b.Size = UDim2.new(0, width or 80, 0, 28)
            b.BackgroundColor3 = bgCol
            b.Text = txt
            b.Font = Enum.Font.GothamBold
