        local stopBtn        = makeActionBtn("STOP", Color3.fromRGB(215, 45, 65), 60)
        local octaveBtn      = makeActionBtn("OCT: 0", Color3.fromRGB(35, 40, 56), 55)
        local layoutBtn      = makeActionBtn("ZQSD = WASD", Color3.fromRGB(0, 165, 220), 92)
        local minimizeBtn    = makeActionBtn("-", Color3.fromRGB(35, 38, 52), 26)
        local closeBtn       = makeActionBtn("X", Color3.fromRGB(35, 38, 52), 26)

        layoutBtn.MouseButton1Click:Connect(function()
            isRemapActive = not isRemapActive
            if isRemapActive then
                layoutBtn.Text = "ZQSD = WASD"
                layoutBtn.BackgroundColor3 = Color3.fromRGB(0, 165, 220)
                statusLabel.Text = "Keyboard: ZQSD remapped to WASD"
            else
                layoutBtn.Text = "KEY: ZQSD"
                layoutBtn.BackgroundColor3 = Color3.fromRGB(36, 44, 65)
                statusLabel.Text = "Keyboard: Direct ZQSD layout"
            end
            updateKeyHints()
        end)

        closeBtn.MouseButton1Click:Connect(function()
            pianoPlaying = false
            pianoPlayID = tick()
            pcall(function()
                ContextActionService:UnbindAction("BTR_PianoBlockCameraZoom")
            end)
            pcall(function()
                StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Backpack, true)
            end)
            screenGui:Destroy()
        end)

                                              
        octaveBtn.MouseButton1Click:Connect(function()
            if octaveShift == 0 then
                octaveShift = 1
                octaveBtn.Text = "OCT: +1"
                octaveBtn.BackgroundColor3 = Color3.fromRGB(0, 165, 220)
            elseif octaveShift == 1 then
                octaveShift = -1
                octaveBtn.Text = "OCT: -1"
                octaveBtn.BackgroundColor3 = Color3.fromRGB(200, 120, 30)
            else
                octaveShift = 0
                octaveBtn.Text = "OCT: 0"
                octaveBtn.BackgroundColor3 = Color3.fromRGB(35, 40, 56)
            end
        end)

                          
        local isMinimized = false
