            [Enum.KeyCode.Eight] = "8", [Enum.KeyCode.KeypadEight] = "8",
            [Enum.KeyCode.Nine] = "9", [Enum.KeyCode.KeypadNine] = "9",
            [Enum.KeyCode.Zero] = "0", [Enum.KeyCode.KeypadZero] = "0",
        }

        local NumberShiftMap = {
            [Enum.KeyCode.One] = "!", [Enum.KeyCode.KeypadOne] = "!",
            [Enum.KeyCode.Two] = "@", [Enum.KeyCode.KeypadTwo] = "@",
            [Enum.KeyCode.Three] = "3", [Enum.KeyCode.KeypadThree] = "3",
            [Enum.KeyCode.Four] = "$", [Enum.KeyCode.KeypadFour] = "$",
            [Enum.KeyCode.Five] = "%", [Enum.KeyCode.KeypadFive] = "%",
            [Enum.KeyCode.Six] = "^", [Enum.KeyCode.KeypadSix] = "^",
            [Enum.KeyCode.Seven] = "7", [Enum.KeyCode.KeypadSeven] = "7",
            [Enum.KeyCode.Eight] = "*", [Enum.KeyCode.KeypadEight] = "*",
            [Enum.KeyCode.Nine] = "(", [Enum.KeyCode.KeypadNine] = "(",
            [Enum.KeyCode.Zero] = "0", [Enum.KeyCode.KeypadZero] = "0",
        }

        local keyConnection
        keyConnection = UserInputService.InputBegan:Connect(function(input, gpe)
                                                                                       
            if UserInputService:GetFocusedTextBox() then return end

            if input.UserInputType == Enum.UserInputType.Keyboard then
                local code = input.KeyCode
                local isShift = UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) or UserInputService:IsKeyDown(Enum.KeyCode.RightShift)
                local char = nil

                                                               
                if NumberKeyMap[code] then
                    if isShift then
                        char = NumberShiftMap[code] or NumberKeyMap[code]
                    else
                        char = NumberKeyMap[code]
                    end
                else
                                                      
                    local keyName = code.Name
                    if #keyName == 1 and keyName:match("%a") then
                        char = isShift and keyName:upper() or keyName:lower()
                    else
                        local raw = UserInputService:GetStringForKeyCode(code)
                        if raw and #raw == 1 then
                            char = isShift and raw:upper() or raw:lower()
                        end
                    end
                end

                if not char then return end

                local playedChar = char
                if isRemapActive and azertyToQwerty[char] then
                    playedChar = azertyToQwerty[char]
                end

                local targetNote = KeysToNotes[playedChar]
                if targetNote then
                    playNote(targetNote)
                    local keyDisplay = (isRemapActive and azertyToQwerty[char]) and (tostring(char) .. " -> " .. tostring(playedChar)) or tostring(char)
                    statusLabel.Text = "PC Key [" .. keyDisplay .. "] -> " .. targetNote
                end
            end
        end)

