                StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Backpack, true)
            end)
        end)

                                                                                    
                                                     
                                                                                    
        local function playSheet(sheet)
            local i = 1
            local totalLen = #sheet
            local myID = pianoPlayID

            while i <= totalLen and pianoPlaying and pianoPlayID == myID do
                                                         
                local beat = 60 / ((liveTempo or 150) * 4)

                                      
                progressBar.Size = UDim2.new(math.clamp(i / totalLen, 0, 1), 0, 1, 0)

                local c = sheet:sub(i, i)
                if c == "[" then
                    local close = sheet:find("]", i, true)
                    if close then
                        local group = sheet:sub(i + 1, close - 1)
                        for ch in group:gmatch(".") do
                            if pianoPlayID ~= myID then break end
                            local note = KeysToNotes[ch]
                            if note then
                                playNote(note)
                                statusLabel.Text = "Playing: " .. note
                            end
                            task.wait(0.045)
                        end
                        task.wait(beat)
                        i = close
                    end
                elseif c == " " or c == "\n" or c == "\r" then
                    task.wait(beat)
                elseif c == "-" then
                    task.wait(beat * 0.5)
                else
                    local note = KeysToNotes[c]
                    if note then
                        playNote(note)
                        statusLabel.Text = "Playing: " .. note
                    end
                    task.wait(beat)
                end

                i = i + 1
            end

            if pianoPlayID == myID then
                pianoPlaying = false
                progressBar.Size = UDim2.new(1, 0, 1, 0)
                statusLabel.Text = "Song Completed!"
                autoPlayBtn.BackgroundColor3 = Color3.fromRGB(0, 150, 255)
                autoPlayBtn.Text = "PLAY"
            end
        end

        autoPlayBtn.MouseButton1Click:Connect(function()
            task.spawn(function()
                if pianoPlaying then
                    pianoPlaying = false
                    pianoPlayID = tick()
                    autoPlayBtn.BackgroundColor3 = Color3.fromRGB(0, 150, 255)
                    autoPlayBtn.Text = "PLAY"
                    statusLabel.Text = "Paused"
                    return
                end

                local selected = SONGS[selectedSongIdx]
                if not selected then return end

                pianoPlaying = true
                pianoPlayID = tick()
                autoPlayBtn.BackgroundColor3 = Color3.fromRGB(35, 185, 100)
                autoPlayBtn.Text = "PAUSE"

                playSheet(selected.sheet)
            end)
        end)

        csPlayBtn.MouseButton1Click:Connect(function()
            local text = csTextBox.Text
            if text and #text > 2 then
                customSheetBoxFrame.Visible = false
                if pianoPlaying then
                    pianoPlaying = false
