                    task.wait(0.1)
                end

                pianoPlaying = true
                pianoPlayID = tick()
                autoPlayBtn.BackgroundColor3 = Color3.fromRGB(35, 185, 100)
                autoPlayBtn.Text = "PAUSE"
                statusLabel.Text = "Playing Custom Sheet..."

                playSheet(text)
            end
        end)

