    local function fakeKickPlayer(targetName)
        local playersService = game:GetService("Players")
        local textChatService = game:GetService("TextChatService")
        local coreGui = game:GetService("CoreGui")
        local ws = game:GetService("Workspace")

        local target = nil
        if type(targetName) == "string" and targetName ~= "" then
            local lowerQuery = string.lower(targetName)
            for _, plr in ipairs(playersService:GetPlayers()) do
                if string.lower(plr.Name) == lowerQuery or string.lower(plr.DisplayName) == lowerQuery then
                    target = plr
                    break
                end
            end
            if not target then
                for _, plr in ipairs(playersService:GetPlayers()) do
                    if string.find(string.lower(plr.Name), lowerQuery) or string.find(string.lower(plr.DisplayName), lowerQuery) then
                        target = plr
                        break
                    end
                end
            end
        end

        if not target then
            safeVisualNotify("Fake Kick", "Target player not found!", 2)
            return
        end

        local tName = target.Name
        local tDisplayName = target.DisplayName
        blacklistedKickedPlayers[tName] = true

        
        if target.Character then
            pcall(function() target.Character:Destroy() end)
        end

        local charConn = target.CharacterAdded:Connect(function(newChar)
            if blacklistedKickedPlayers[tName] then
                task.wait()
                pcall(function() newChar:Destroy() end)
            end
        end)
        table.insert(visualConnections, charConn)

        local wsConn = ws.ChildAdded:Connect(function(child)
            if blacklistedKickedPlayers[tName] and child.Name == tName then
                task.wait()
                pcall(function() child:Destroy() end)
            end
        end)
        table.insert(visualConnections, wsConn)

        
        local function purgeFromPlayerList()
            pcall(function()
                local playerList = coreGui:FindFirstChild("PlayerList")
                if playerList then
                    for _, item in ipairs(playerList:GetDescendants()) do
                        if item:IsA("TextLabel") and (item.Text == tName or item.Text == tDisplayName) then
                            local row = item:FindFirstAncestorWhichIsA("Frame") or item.Parent
                            if row then
                                row.Visible = false
                                pcall(function() row:Destroy() end)
                            end
                        end
                    end
                end
            end)
        end
        purgeFromPlayerList()
        task.delay(0.5, purgeFromPlayerList)
        task.delay(1.5, purgeFromPlayerList)

        
        
        showFakeAnnouncement("MODERATION LOG", tDisplayName .. " (@" .. tName .. ") was kicked from the server.")
        safeVisualNotify("Player Purged", tDisplayName .. " (@" .. tName .. ") is completely erased from your game (3D & TAB)!", 4)
    end

    
    
    
    local VERIFIED_EMOJI = utf8.char(0xE000)

    local function formatVerifiedChatPrefix(originalPrefix, defaultName)
        local prefix = (originalPrefix and originalPrefix ~= "") and originalPrefix or (defaultName .. ":")
        prefix = prefix:gsub(VERIFIED_EMOJI, "")
        local beforeColon, afterColon = prefix:match("^(.-)(%s*:%s*)$")
        if beforeColon and afterColon then
            return beforeColon .. " " .. VERIFIED_EMOJI .. afterColon
        else
            return prefix .. " " .. VERIFIED_EMOJI .. ":"
        end
    end

    local verifiedChatConnections = {}
    local isPatchingText = false

    local function patchChatTextLabel(lbl)
        if not verifiedBadgeActive or isPatchingText then return end
        if not lbl or (not lbl:IsA("TextLabel") and not lbl:IsA("TextButton")) then return end

        local txt = lbl.Text
        if not txt or txt == "" then return end
        if txt:find(VERIFIED_EMOJI, 1, true) then return end

        local myName = localPlr and localPlr.Name
        local myDisp = localPlr and localPlr.DisplayName

        local isMine = false
        if myName and myName ~= "" and (txt:find(myName, 1, true) or lbl.Name:find(myName, 1, true)) then
            isMine = true
        elseif myDisp and myDisp ~= "" and (txt:find(myDisp, 1, true) or lbl.Name:find(myDisp, 1, true)) then
            isMine = true
        end

        if isMine then
            isPatchingText = true
            lbl.RichText = true
            if txt:find(":") then
                lbl.Text = txt:gsub("(:)", " " .. VERIFIED_EMOJI .. "%1", 1)
            else
                lbl.Text = txt .. " " .. VERIFIED_EMOJI
            end
            isPatchingText = false
        end
    end

    local stopSolaraChatScanner
    local function startSolaraChatScanner()
        if stopSolaraChatScanner then stopSolaraChatScanner() end

        local containers = {}
        pcall(function()
            local pg = localPlr and (localPlr:FindFirstChild("PlayerGui") or localPlr:WaitForChild("PlayerGui", 3))
            if pg then table.insert(containers, pg) end
        end)
        pcall(function()
            if gethui then table.insert(containers, gethui()) end
        end)
        pcall(function()
            table.insert(containers, game:GetService("CoreGui"))
        end)

        for _, c in ipairs(containers) do
            pcall(function()
                for _, desc in ipairs(c:GetDescendants()) do
                    if desc:IsA("TextLabel") or desc:IsA("TextButton") then
                        patchChatTextLabel(desc)
                    end
                end

                local conn = c.DescendantAdded:Connect(function(desc)
                    if not verifiedBadgeActive then return end
                    if desc:IsA("TextLabel") or desc:IsA("TextButton") then
                        task.defer(function()
                            patchChatTextLabel(desc)
                        end)
                        local textConn = desc:GetPropertyChangedSignal("Text"):Connect(function()
                            if verifiedBadgeActive and not isPatchingText then
                                patchChatTextLabel(desc)
                            end
                        end)
                        table.insert(verifiedChatConnections, textConn)
                    end
                end)
                table.insert(verifiedChatConnections, conn)
            end)
        end
    end

    local function stopSolaraChatScanner()
        for _, c in ipairs(verifiedChatConnections) do
            pcall(function() c:Disconnect() end)
        end
        verifiedChatConnections = {}
        isPatchingText = false
    end

    
    pcall(function()
        if textChatService and textChatService.ChatVersion == Enum.ChatVersion.TextChatService then
            textChatService.OnIncomingMessage = function(msg)
                if msg.TextSource and blacklistedKickedPlayers[msg.TextSource.Name] then
                    local prop = Instance.new("TextChatMessageProperties")
                    prop.Text = ""
                    return prop
                end

                if verifiedBadgeActive and msg.TextSource and localPlr and (msg.TextSource.UserId == localPlr.UserId or msg.TextSource.Name == localPlr.Name) then
                    local prop = Instance.new("TextChatMessageProperties")
                    prop.PrefixText = formatVerifiedChatPrefix(msg.PrefixText, localPlr.DisplayName or localPlr.Name)
                    return prop
                end
            end
        end
    end)

    local function getCleanPlayerDisplayName()
        local localPlr = game:GetService("Players").LocalPlayer
        if not localPlr then return "Player" end
        local name = ""
        local bag = localPlr:FindFirstChild("PlayersBag")
        if bag then
            local rpName = bag:FindFirstChild("RPName")
            if rpName and rpName.Value and tostring(rpName.Value) ~= "" and tostring(rpName.Value) ~= " " then
                name = tostring(rpName.Value)
            end
        end
        if name == "" then
            name = localPlr.DisplayName or localPlr.Name or "Player"
        end
        name = name:gsub(VERIFIED_EMOJI, ""):gsub("%s+$", "")
        return name
    end

