    local function createVaultHighlight(targetObj, labelName)
        if not targetObj then return end
        local coreGuiService = game:GetService("CoreGui")
        local localPlr = game:GetService("Players").LocalPlayer

        local hl = Instance.new("Highlight")
        hl.Name = "BTR_VaultHL"
        hl.Adornee = targetObj
        hl.FillColor = Color3.fromRGB(255, 205, 0)
        hl.FillTransparency = 0.35
        hl.OutlineColor = Color3.fromRGB(255, 255, 255)
        hl.OutlineTransparency = 0
        hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        local ok = pcall(function() hl.Parent = coreGuiService end)
        if not ok or not hl.Parent then
            pcall(function()
                hl.Parent = (localPlr and localPlr:FindFirstChild("PlayerGui")) or targetObj
            end)
        end
        table.insert(espVaultObjects, hl)

        local part = targetObj:IsA("BasePart") and targetObj or (targetObj.PrimaryPart or targetObj:FindFirstChildWhichIsA("BasePart"))
        if part then
            local tag = Instance.new("BillboardGui")
            tag.Name = "BTR_VaultTag"
            tag.Adornee = part
            tag.Size = UDim2.new(0, 130, 0, 32)
            tag.StudsOffset = Vector3.new(0, 2.5, 0)
            tag.AlwaysOnTop = true
            tag.MaxDistance = 2500
            local tagOk = pcall(function() tag.Parent = coreGuiService end)
            if not tagOk or not tag.Parent then
                pcall(function()
                    tag.Parent = (localPlr and localPlr:FindFirstChild("PlayerGui")) or part
                end)
            end

            local frame = Instance.new("Frame", tag)
            frame.Size = UDim2.new(1, 0, 1, 0)
            frame.BackgroundColor3 = Color3.fromRGB(20, 18, 12)
            frame.BackgroundTransparency = 0.2
            Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 6)
            local stroke = Instance.new("UIStroke", frame)
            stroke.Color = Color3.fromRGB(255, 205, 0)
            stroke.Thickness = 1.2

            local lbl = Instance.new("TextLabel", frame)
            lbl.Size = UDim2.new(1, 0, 1, 0)
            lbl.BackgroundTransparency = 1
            lbl.Font = Enum.Font.GothamBold
            lbl.Text = "[ " .. tostring(labelName) .. " ]"
            lbl.TextColor3 = Color3.fromRGB(255, 220, 50)
            lbl.TextSize = 11

            table.insert(espVaultObjects, tag)
