        scanAndHighlightVaults()

        local descConn = game:GetService("Workspace").DescendantAdded:Connect(function(newObj)
            if espVaultsActive then
                local name = newObj.Name
                local lowerName = string.lower(name)
                if name == "001_Safe" or name == "Safe" or name == "SafeDoor" then
                    task.wait(0.2)
                    createVaultHighlight(newObj, "HOUSE SAFE")
                elseif string.find(lowerName, "vault") and (newObj:IsA("BasePart") or newObj:IsA("Model")) then
                    task.wait(0.2)
                    createVaultHighlight(newObj, "BANK VAULT")
                end
            end
        end)
        table.insert(visualConnections, descConn)

        safeVisualNotify("Vault ESP", "Bank Vault & House Safes highlighted across map!", 3)
    end

    
    
    
