    local function getBestAdorneePart(char)
        if not char then return nil end
        return char:FindFirstChild("Head")
            or char:FindFirstChild("UpperTorso")
            or char:FindFirstChild("Torso")
            or char:FindFirstChild("HumanoidRootPart")
            or char.PrimaryPart
            or char:FindFirstChildWhichIsA("BasePart")
    end

    local function removeHackerVisual(uid)
        if hackerHighlights[uid] then
            pcall(function() hackerHighlights[uid]:Destroy() end)
            hackerHighlights[uid] = nil
        end
        if hackerTags[uid] then
            pcall(function() hackerTags[uid]:Destroy() end)
            hackerTags[uid] = nil
        end
    end

    local function applyHackerVisual(plr, hubName, cheatType)
        if not hackerEspActive or not plr or not plr.Character then return end
        local char = plr.Character
        local uid = plr.UserId
        local adornee = getBestAdorneePart(char)
        if not adornee then return end

        
        if not hackerHighlights[uid] or hackerHighlights[uid].Parent ~= char then
            pcall(function() if hackerHighlights[uid] then hackerHighlights[uid]:Destroy() end end)
            local hl = Instance.new("Highlight")
            hl.Name = "BTR_HackerHL"
            hl.Adornee = char
            hl.FillColor = Color3.fromRGB(255, 30, 30)
            hl.FillTransparency = 0.35
            hl.OutlineColor = Color3.fromRGB(255, 255, 255)
            hl.OutlineTransparency = 0
            hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            hl.Parent = char
            hackerHighlights[uid] = hl
        end

        
        if not hackerTags[uid] or hackerTags[uid].Parent ~= adornee then
            pcall(function() if hackerTags[uid] then hackerTags[uid]:Destroy() end end)

            local tag = Instance.new("BillboardGui")
            tag.Name = "BTR_HackerTag"
            tag.Adornee = adornee
            tag.Size = UDim2.new(0, 230, 0, 75)
            tag.StudsOffset = Vector3.new(0, 3.2, 0)
            tag.AlwaysOnTop = true
            tag.MaxDistance = 1500
            tag.Parent = adornee

            local frame = Instance.new("Frame", tag)
            frame.Name = "TagFrame"
            frame.Size = UDim2.new(1, 0, 1, 0)
            frame.BackgroundColor3 = Color3.fromRGB(16, 18, 24)
            frame.BackgroundTransparency = 0.15
            frame.BorderSizePixel = 0
            Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 8)

            local stroke = Instance.new("UIStroke", frame)
            stroke.Color = Color3.fromRGB(255, 45, 45)
            stroke.Thickness = 1.5

            local lblHeader = Instance.new("TextLabel", frame)
            lblHeader.Size = UDim2.new(1, -10, 0, 16)
            lblHeader.Position = UDim2.new(0, 5, 0, 3)
            lblHeader.BackgroundTransparency = 1
            lblHeader.Font = Enum.Font.GothamBold
            lblHeader.Text = "[!] EXPLOIT DETECTED"
            lblHeader.TextColor3 = Color3.fromRGB(255, 65, 65)
            lblHeader.TextSize = 11

            local lblPlayer = Instance.new("TextLabel", frame)
            lblPlayer.Name = "PlayerLabel"
            lblPlayer.Size = UDim2.new(1, -10, 0, 17)
            lblPlayer.Position = UDim2.new(0, 5, 0, 19)
            lblPlayer.BackgroundTransparency = 1
            lblPlayer.Font = Enum.Font.GothamBold
            lblPlayer.Text = plr.DisplayName .. " (@" .. plr.Name .. ")"
            lblPlayer.TextColor3 = Color3.fromRGB(255, 255, 255)
            lblPlayer.TextSize = 11
            lblPlayer.TextTruncate = Enum.TextTruncate.AtEnd

            local lblInfo = Instance.new("TextLabel", frame)
            lblInfo.Name = "InfoLabel"
            lblInfo.Size = UDim2.new(1, -10, 0, 16)
            lblInfo.Position = UDim2.new(0, 5, 0, 37)
            lblInfo.BackgroundTransparency = 1
            lblInfo.Font = Enum.Font.GothamMedium
            lblInfo.Text = "Hub: " .. tostring(hubName or "None") .. " | ... studs"
            lblInfo.TextColor3 = Color3.fromRGB(255, 210, 70)
            lblInfo.TextSize = 10

            local lblCheat = Instance.new("TextLabel", frame)
            lblCheat.Name = "CheatLabel"
            lblCheat.Size = UDim2.new(1, -10, 0, 16)
            lblCheat.Position = UDim2.new(0, 5, 0, 54)
            lblCheat.BackgroundTransparency = 1
            lblCheat.Font = Enum.Font.GothamMedium
            lblCheat.Text = "Cheat: " .. tostring(cheatType or "Unknown")
            lblCheat.TextColor3 = Color3.fromRGB(255, 120, 90)
            lblCheat.TextSize = 10
            lblCheat.TextTruncate = Enum.TextTruncate.AtEnd

            hackerTags[uid] = tag
        else
            
            local frame = hackerTags[uid]:FindFirstChild("TagFrame")
            if frame then
                local lblPlayer = frame:FindFirstChild("PlayerLabel")
                if lblPlayer then lblPlayer.Text = plr.DisplayName .. " (@" .. plr.Name .. ")" end
                local lblCheat = frame:FindFirstChild("CheatLabel")
                if lblCheat then lblCheat.Text = "Cheat: " .. tostring(cheatType or "Unknown") end
            end
        end
    end

    local function detectHubSignature(plr)
        if not plr then return "None" end
        local bag = plr:FindFirstChild("PlayersBag")
        if bag then
            local rpName = bag:FindFirstChild("RPName") and tostring(bag.RPName.Value) or ""
            local rpBio = bag:FindFirstChild("RPBio") and tostring(bag.RPBio.Value) or ""
            local bioCol = bag:FindFirstChild("RPBioColor") and bag.RPBioColor.Value
            local nameCol = bag:FindFirstChild("RPNameColor") and bag.RPNameColor.Value

            if rpName == "Ez by ash" or rpBio == "Ez by ash" or string.find(rpName, "Dark Hub") or string.find(rpName, "DarkBrook") or string.find(rpBio, "Dark Hub") then
                return "Dark Hub"
            end
            if string.find(rpName, "KitK4t") or string.find(rpBio, "KitK4t") or string.find(rpName, "Slayer") then
                return "KitK4t / Slayer Hub"
            end
            if string.find(rpName, "Hexagon") or string.find(rpBio, "Hexagon") then
                return "Hexagon Hub"
            end
            if bioCol and nameCol and typeof(bioCol) == "Color3" and typeof(nameCol) == "Color3" then
                if bioCol.R > 0.9 and bioCol.G < 0.1 and bioCol.B < 0.1 and nameCol.R < 0.05 and nameCol.G < 0.05 and nameCol.B < 0.05 then
                    return "Dark Hub"
                end
            end
        end

        local char = plr.Character
        local backpack = plr:FindFirstChild("Backpack")
        if char then
            if char:FindFirstChild("Chaos.Couch") or (backpack and backpack:FindFirstChild("Chaos.Couch")) then
                return "Dark Hub"
            end
            local couch = char:FindFirstChild("Couch") or (backpack and backpack:FindFirstChild("Couch"))
            if couch and couch:FindFirstChild("Handle ") then
                return "Dark Hub"
            end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hrp and hrp:FindFirstChild("FlingForce") then
                return "Dark Hub"
            end
        end

        return "None"
    end

    local function evaluatePlayerCheat(plr)
        if not plr or plr == lpLocal then return nil, "None" end
        local char = plr.Character
        if not char then return nil, "None" end
        local hum = char:FindFirstChildOfClass("Humanoid")
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if not hum or not hrp or hum.Health <= 0 then return nil, "None" end

        local hub = detectHubSignature(plr)
        local uid = plr.UserId

        
        local spawnTick = spawnTimes[uid] or 0
        if tick() - spawnTick < 3.5 then
            if hub ~= "None" then
                return "Hub User (" .. hub .. ")", hub
            end
            return nil, hub
        end

        
        local head = char:FindFirstChild("Head")
        local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
        if head and torso and head.Transparency >= 0.85 and torso.Transparency >= 0.85 then
            local totalParts = 0
            local invisParts = 0
            for _, p in ipairs(char:GetChildren()) do
                if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" then
                    totalParts = totalParts + 1
                    if p.Transparency >= 0.85 then invisParts = invisParts + 1 end
                end
            end
            if totalParts >= 3 and invisParts >= (totalParts - 1) then
                return "Invisibility", hub
            end
        end

        
        local velMag = hrp.AssemblyLinearVelocity.Magnitude
        local rotMag = hrp.AssemblyAngularVelocity.Magnitude
        if velMag ~= velMag or rotMag ~= rotMag or velMag > 50000 or rotMag > 10000 then
            return "Desync / Godmode", hub
        end
        if torso and (hrp.Position - torso.Position).Magnitude > 45 then
            return "Desync (Detached Hitbox)", hub
        end

        
        if char:FindFirstChild("Chaos.Couch") or (plr:FindFirstChild("Backpack") and plr.Backpack:FindFirstChild("Chaos.Couch")) then
            return "Couch Fling Attacker", "Dark Hub"
        end
        local couch = char:FindFirstChild("Couch") or (plr:FindFirstChild("Backpack") and plr.Backpack:FindFirstChild("Couch"))
        if couch and couch:FindFirstChild("Handle ") then
            return "Couch Fling Attacker", "Dark Hub"
        end
        if hrp:FindFirstChild("FlingForce") then
            return "Force Fling Attacker", "Dark Hub"
        end
        if rotMag > 160 and not hum.Sit and not hum.SeatPart then
            spinCounters[uid] = (spinCounters[uid] or 0) + 1
            if spinCounters[uid] >= 4 then
                return "Fling Spinner (" .. math.floor(rotMag) .. " rad/s)", hub
            end
        else
            spinCounters[uid] = 0
        end

        
        if not hum.Sit and not hum.SeatPart and not char:FindFirstChildWhichIsA("VehicleSeat", true) then
            for _, child in ipairs(char:GetDescendants()) do
                if (child:IsA("BodyVelocity") or child:IsA("BodyPosition") or child:IsA("LinearVelocity") or child:IsA("AlignPosition")) then
                    local name = string.lower(child.Name)
                    if not string.find(name, "root") and not string.find(name, "vehicle") and not string.find(name, "btr") and not string.find(name, "seat") then
                        return "Fly / Mover Hack", hub
                    end
                end
            end
        end

        
        local isSeated = hum.Sit or (hum.SeatPart ~= nil) or (char:FindFirstChildWhichIsA("Seat", true) ~= nil) or (char:FindFirstChildWhichIsA("VehicleSeat", true) ~= nil)
        if not isSeated and hum.FloorMaterial ~= Enum.Material.Air then
            local hSpeed = math.sqrt(hrp.AssemblyLinearVelocity.X^2 + hrp.AssemblyLinearVelocity.Z^2)
            if hSpeed > 125 and hum.MoveDirection.Magnitude > 0.4 then
                speedCounters[uid] = (speedCounters[uid] or 0) + 1
                if speedCounters[uid] >= 5 then
                    return "Speedhack (" .. math.floor(hSpeed) .. " studs/s)", hub
                end
            else
                speedCounters[uid] = 0
            end
        else
            speedCounters[uid] = 0
        end

        
        if hub ~= "None" then
            return "Hub Signature (" .. hub .. ")", hub
        end

        return nil, hub
    end

    local function runRealtimeScan()
        local myChar = lpLocal.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")

        for _, plr in ipairs(plrsService:GetPlayers()) do
            if plr ~= lpLocal then
                local uid = plr.UserId
                local cheat, hub = evaluatePlayerCheat(plr)

                if cheat then
                    local dist = 0
                    if myRoot and plr.Character then
                        local pRoot = getBestAdorneePart(plr.Character)
                        if pRoot then
                            dist = math.floor((pRoot.Position - myRoot.Position).Magnitude)
                        end
                    end

                    
                    detectedHackers[uid] = {
                        player = plr,
                        hub = hub or "None",
                        cheatType = cheat,
                        detectedAt = tick(),
                        dist = dist
                    }

                    
                    if not notifiedHackers[uid] then
                        notifiedHackers[uid] = true
                        safeVisualNotify(
                            "HACKER DETECTED!",
                            plr.DisplayName .. " (@" .. plr.Name .. ")\nHub: " .. (hub or "None") .. "\nCheat: " .. cheat .. "\nDistance: " .. dist .. " studs",
                            6
                        )
                    end

                    
                    applyHackerVisual(plr, hub, cheat)
                elseif detectedHackers[uid] and hackerEspActive and plr.Character then
                    
                    applyHackerVisual(plr, detectedHackers[uid].hub, detectedHackers[uid].cheatType)
                end
            end
        end
    end

    local function startHackerDetector()
        if detectorThread then return end

        
        for _, plr in ipairs(plrsService:GetPlayers()) do
            if plr.Character then spawnTimes[plr.UserId] = tick() end
            local cConn = plr.CharacterAdded:Connect(function()
                spawnTimes[plr.UserId] = tick()
                floatCounters[plr.UserId] = 0
                speedCounters[plr.UserId] = 0
                spinCounters[plr.UserId] = 0
            end)
            table.insert(detectorConnections, cConn)
        end
        local pConn = plrsService.PlayerAdded:Connect(function(plr)
            local cpConn = plr.CharacterAdded:Connect(function()
                spawnTimes[plr.UserId] = tick()
            end)
            table.insert(detectorConnections, cpConn)
        end)
        table.insert(detectorConnections, pConn)

        
        detectorThread = task.spawn(function()
            while hackerEspActive do
                pcall(runRealtimeScan)
                task.wait(0.4)
            end
            detectorThread = nil
        end)

        
        if not distanceRenderConn then
            distanceRenderConn = runService.RenderStepped:Connect(function()
                if not hackerEspActive then return end
                local myChar = lpLocal.Character
                local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                if not myRoot then return end

                for uid, tag in pairs(hackerTags) do
                    local data = detectedHackers[uid]
                    if data and tag and tag.Parent then
                        local frame = tag:FindFirstChild("TagFrame")
                        local infoLbl = frame and frame:FindFirstChild("InfoLabel")
                        if infoLbl and tag.Adornee then
                            local d = math.floor((tag.Adornee.Position - myRoot.Position).Magnitude)
                            infoLbl.Text = "Hub: " .. tostring(data.hub or "None") .. " | " .. d .. " studs"
                        end
                    end
                end
            end)
        end
    end

    stopHackerDetector = function()
        hackerEspActive = false
        detectorThread = nil
        if distanceRenderConn then
            distanceRenderConn:Disconnect()
            distanceRenderConn = nil
        end
        for _, c in ipairs(detectorConnections) do
            pcall(function() c:Disconnect() end)
        end
        detectorConnections = {}
        for uid, _ in pairs(hackerHighlights) do
            removeHackerVisual(uid)
        end
        table.clear(hackerHighlights)
        table.clear(hackerTags)
    end

    
    
    
    VisualTab:AddSection({"> Hacker & Exploit Detector"})

    VisualTab:AddToggle({
        Name = "Real-Time Hacker ESP",
        Description = "Detects Fly, Speed, Fling, Desync, Invisibility & Dark Hub in real time. Highlights in red with live distance tag.",
        Default = false,
        Callback = function(val)
            hackerEspActive = val
            if val then
                startHackerDetector()
                safeVisualNotify("Hacker ESP", "Real-Time Hacker ESP ACTIVE! Scanning for exploiters...", 3)
            else
                stopHackerDetector()
                safeVisualNotify("Hacker ESP", "Hacker ESP stopped.", 2)
            end
        end
    })

    VisualTab:AddButton({
        Name = "View Detected Hackers (Logs)",
        Description = "Shows all hackers detected in this session with full details",
        Callback = function()
            local count = 0
            local list = {}
            for uid, data in pairs(detectedHackers) do
                local p = data.player
                if p and p.Parent then
                    count = count + 1
                    table.insert(list, string.format(
                        "[%d] %s (@%s)\n    Hub: %s | Cheat: %s\n    Distance: %d studs",
                        count, p.DisplayName, p.Name, tostring(data.hub or "None"), tostring(data.cheatType or "Unknown"), data.dist or 0
                    ))
                end
            end

            if count > 0 then
                local fullLog = table.concat(list, "\n-------------------\n")
                if setclipboard then
                    pcall(function() setclipboard(fullLog) end)
                end
                safeVisualNotify(
                    "Hacker Logs (" .. count .. " Found)",
                    fullLog .. "\n\n(Full log copied to clipboard!)",
                    7
                )
            else
                safeVisualNotify("Hacker Logs", "No hackers detected in this session yet.", 3)
            end
        end
    })

    VisualTab:AddButton({
        Name = "Clear Hacker Memory",
        Description = "Resets the list of detected hackers for a fresh scan",
        Callback = function()
            table.clear(detectedHackers)
            table.clear(notifiedHackers)
            for uid, _ in pairs(hackerHighlights) do
                removeHackerVisual(uid)
            end
            table.clear(hackerHighlights)
            table.clear(hackerTags)
            safeVisualNotify("Hacker Memory", "Hacker history cleared. Ready for fresh scan.", 2)
        end
    })
end
