    local function getHubUserList()
        local list = {}
        local Players = game:GetService("Players")
        local count = 0
        for _, p in ipairs(Players:GetPlayers()) do
            if p.UserId ~= OWNER_USER_ID and _G.BTR_ONLINE_USERS and _G.BTR_ONLINE_USERS[p.Name] then
                count = count + 1
                table.insert(list, "[BTR USER] " .. p.Name)
                if count >= 10 then break end
            end
        end
        if #list == 0 then
            return { "No Hub Users in Server (0)" }
        end
        return list
    end

    local ownerPlayerDropdown = OwnerTab:AddDropdown({
        Name = "Found Players (Hub Users Only - Max 10)",
        Description = "Lists only players in this server running BTR Client",
        Options = getHubUserList(),
        Default = "No Hub Users in Server (0)",
        Callback = function(val)
            if val and val:find("%[BTR USER%] ") then
                selectedOwnerTarget = val:gsub("%[BTR USER%] ", "")
            elseif val and val ~= "No Hub Users in Server (0)" then
                selectedOwnerTarget = val
            else
                selectedOwnerTarget = ""
            end
        end
    })

    _G.BTR_UpdateOwnerPlayerDropdown = function()
        if ownerPlayerDropdown and ownerPlayerDropdown.Set then
            pcall(function()
                ownerPlayerDropdown:Set(getHubUserList())
            end)
        end
    end

    local function scanForHubUsers(silent)
        local Players = game:GetService("Players")
        local lp = Players.LocalPlayer
        _G.BTR_ONLINE_USERS = _G.BTR_ONLINE_USERS or {}

                                                        
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= lp and p.UserId ~= OWNER_USER_ID and p.Character then
                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                if hum then
                    for _, tr in ipairs(hum:GetPlayingAnimationTracks()) do
                        if tr.Animation and tostring(tr.Animation.AnimationId):find("10921054344") then
                            _G.BTR_ONLINE_USERS[p.Name] = p
                            break
                        end
                    end
                end
            end
        end

                                            
        task.spawn(function()
            pcall(function()
                local jobId = tostring(game.JobId)
                if jobId and jobId ~= "" then
                    local HttpService = game:GetService("HttpService")
                    local res = game:HttpGet("https://btr-x-client.btrxclient.workers.dev/api/active_users?job=" .. HttpService:UrlEncode(jobId))
                    if res and res:sub(1, 1) == "[" then
                        local parsed = HttpService:JSONDecode(res)
                        if type(parsed) == "table" then
                            for _, entry in ipairs(parsed) do
                                if entry.user and entry.user ~= lp.Name then
                                    local foundPlr = Players:FindFirstChild(entry.user)
                                    if foundPlr and foundPlr.UserId ~= OWNER_USER_ID then
                                        _G.BTR_ONLINE_USERS[entry.user] = foundPlr
                                    end
                                end
                            end
                        end
                    end
                end
            end)

            for name, _ in pairs(_G.BTR_ONLINE_USERS) do
                if not Players:FindFirstChild(name) then
                    _G.BTR_ONLINE_USERS[name] = nil
                end
            end

            if _G.BTR_UpdateOwnerPlayerDropdown then
                pcall(_G.BTR_UpdateOwnerPlayerDropdown)
            end

            local count = 0
            for _ in pairs(_G.BTR_ONLINE_USERS) do count = count + 1 end
            if not silent then
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = "Hub Scan Complete",
                    Text = "Found " .. tostring(count) .. " BTR Client user(s) in this server.",
                    Duration = 3
                })
            end
        end)
    end

