    OwnerTab:AddSection({ "> Global Hub Users (Cross-Server)" })

    local globalUserMap = {}
    local selectedGlobalUser = nil
    local globalDropdownRef = nil

    local function fetchGlobalUsers()
        local lp = game:GetService("Players").LocalPlayer
        local res = nil
        local success = pcall(function()
            res = game:HttpGet("https://btr-x-client.btrxclient.workers.dev/api/active_users")
        end)
        if not success or not res or res == "" or res:sub(1, 1) ~= "[" then
            pcall(function()
                res = game:HttpGet("https://btr-x-client.btrxclient.workers.dev/active_users")
            end)
        end

        if not res or res == "" or res:sub(1, 1) ~= "[" then
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = "Global Users",
                Text = "No active users found on gateway server.",
                Duration = 3
            })
            return
        end

        local HttpService = game:GetService("HttpService")
        local parsed = nil
        pcall(function() parsed = HttpService:JSONDecode(res) end)

        globalUserMap = {}
        local options = {}

        if type(parsed) == "table" and #parsed > 0 then
            local myJob = tostring(game.JobId)
            for _, entry in ipairs(parsed) do
                if entry.user and entry.job then
                                             
                    if entry.user ~= lp.Name then
                        if tostring(entry.job) == myJob then
                            _G.BTR_ONLINE_USERS[entry.user] = true
                        else
                            local label = tostring(entry.user) .. " (Job: " .. string.sub(tostring(entry.job), 1, 8) .. "...)"
                            table.insert(options, label)
                            globalUserMap[label] = entry
                            if #options >= 10 then break end                  
                        end
                    end
                end
            end
        end

        if _G.BTR_UpdateOwnerPlayerDropdown then
            pcall(_G.BTR_UpdateOwnerPlayerDropdown)
        end

        if #options == 0 then
            table.insert(options, "No external users online (0)")
        end

        if globalDropdownRef and globalDropdownRef.Set then
            pcall(function() globalDropdownRef:Set(options) end)
        end

        local count = (#options == 1 and options[1] == "No external users online (0)") and 0 or #options
        game:GetService("StarterGui"):SetCore("SendNotification", {
            Title = "Global Hub Users",
            Text = "Found " .. tostring(count) .. " active player(s) on other servers (Max 10).",
            Duration = 3
        })
    end

    globalDropdownRef = OwnerTab:AddDropdown({
        Name = "Global Hub Users (Cross-Server - Max 10)",
        Description = "Players on other servers. Selecting them sets them as target",
        Options = {"Click Refresh below..."},
        Default = "Click Refresh below...",
        Callback = function(val)
            if globalUserMap[val] then
                selectedGlobalUser = globalUserMap[val]
                if selectedGlobalUser.user then
                    selectedOwnerTarget = selectedGlobalUser.user
                end
            else
                selectedGlobalUser = nil
            end
        end
    })

    OwnerTab:AddButton({
        Name = "Refresh Global Users",
        Description = "Scan other Roblox servers for active BTR players (max 10)",
        Callback = function()
            fetchGlobalUsers()
        end
    })

    OwnerTab:AddButton({
        Name = "Join Player Server (Teleport)",
        Description = "Teleports you directly to the selected player's server",
        Callback = function()
            if selectedGlobalUser and selectedGlobalUser.job and selectedGlobalUser.job ~= "" then
                local TeleportService = game:GetService("TeleportService")
                local targetPlace = tonumber(selectedGlobalUser.place) or game.PlaceId
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = "Teleporting",
                    Text = "Joining " .. tostring(selectedGlobalUser.user) .. "'s server...",
                    Duration = 4
                })
                task.wait(0.5)
                pcall(function()
                    TeleportService:TeleportToPlaceInstance(targetPlace, tostring(selectedGlobalUser.job), game:GetService("Players").LocalPlayer)
                end)
            else
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = "Teleport Error",
                    Text = "Please select a valid player from the list first!",
                    Duration = 3
                })
            end
        end
    })
