    task.spawn(function()
        local lastSeenMsgId = os.time() - 600
        local lp = game:GetService("Players").LocalPlayer
        while true do
            task.wait(5)
            pcall(function()
                if not lp then return end
                local HttpService = game:GetService("HttpService")
                local uName = HttpService:UrlEncode(lp.Name)
                local uUid = tostring(lp.UserId)
                local url = "https://btr-x-client.btrxclient.workers.dev/api/get_message?user=" .. uName .. "&userid=" .. uUid
                local res = game:HttpGet(url)
                if res and res:sub(1, 1) == "{" then
                    local data = HttpService:JSONDecode(res)
                    if data and data.id and data.id > lastSeenMsgId and data.message and data.message ~= "" then
                        lastSeenMsgId = data.id
                        if _G.BTR_ShowOwnerMessageMenu then
                            _G.BTR_ShowOwnerMessageMenu(data.message, data.author or "Ash", data.timestamp)
                        end
                    end
                end
            end)
        end
    end)

    task.spawn(function()
        local function sendPresencePing()
            pcall(function()
                local lp = game:GetService("Players").LocalPlayer
                local jobId = tostring(game.JobId)
                local placeId = tostring(game.PlaceId)
                if jobId and jobId ~= "" and lp then
                    local HttpService = game:GetService("HttpService")
                    local hwid = ""
                    pcall(function()
                        if gethwid then hwid = gethwid()
                        elseif get_hwid then hwid = get_hwid()
                        elseif getgenv and getgenv().gethwid then hwid = getgenv().gethwid()
                        elseif game:GetService("RbxAnalyticsService") and game:GetService("RbxAnalyticsService").GetClientId then
                            hwid = game:GetService("RbxAnalyticsService"):GetClientId()
                        end
                    end)
                    local uName = HttpService:UrlEncode(lp.Name)
                    local uUid = tostring(lp.UserId)
                    local uJob = HttpService:UrlEncode(jobId)
                    local uPlace = HttpService:UrlEncode(placeId)
                    local uHwid = HttpService:UrlEncode(hwid)
                    game:HttpGet("https://btr-x-client.btrxclient.workers.dev/api/ping?user=" .. uName .. "&userid=" .. uUid .. "&job=" .. uJob .. "&place=" .. uPlace .. "&hwid=" .. uHwid)
                end
            end)
        end

        sendPresencePing()
        while true do
            task.wait(45)
            sendPresencePing()
        end
    end)


task.spawn(function()
