                collectgarbage("step", 60)
            end
        end)
    end
end)

                                                                   
task.spawn(function()
    local Players = game:GetService("Players")
    local TweenService = game:GetService("TweenService")

    local TAG_CONFIG = {
        [10909094240] = {
            title = "👑 BTR CREATOR",
            color = Color3.fromRGB(0, 160, 255),
            bg = Color3.fromRGB(8, 16, 28),
            isCreator = true
        },
        [1183676951] = {
            title = "🤝 CREATOR FRIEND",
            color = Color3.fromRGB(46, 213, 115),
            bg = Color3.fromRGB(12, 22, 16),
            isCreator = false
        }
    }

    local function attachBtrRoleTag(char, cfg)
        if not char then return end
        local head = char:WaitForChild("Head", 6)
        if not head then return end

        local existing = head:FindFirstChild("BTR_RoleTag")
        if existing then existing:Destroy() end

        local bb = Instance.new("BillboardGui")
        bb.Name = "BTR_RoleTag"
        bb.Adornee = head
        bb.Size = UDim2.new(0, 150, 0, 24)
        bb.StudsOffset = Vector3.new(0, 2.0, 0)
        bb.AlwaysOnTop = false
        bb.ResetOnSpawn = false
        bb.MaxDistance = 45
        bb.Parent = head

        local pill = Instance.new("Frame")
        pill.Name = "BadgePill"
        pill.AnchorPoint = Vector2.new(0.5, 0.5)
        pill.Position = UDim2.new(0.5, 0, 0.5, 0)
        pill.AutomaticSize = Enum.AutomaticSize.X
        pill.Size = UDim2.new(0, 0, 0, 20)
        pill.BackgroundColor3 = cfg.bg
        pill.BackgroundTransparency = 0.15
        pill.BorderSizePixel = 0
        pill.Parent = bb

        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 5)
        corner.Parent = pill

        local stroke = Instance.new("UIStroke")
        stroke.Name = "PillStroke"
        stroke.Color = cfg.color
        stroke.Thickness = cfg.isCreator and 1.5 or 1.2
        stroke.Transparency = cfg.isCreator and 0.05 or 0.15
        stroke.Parent = pill

        if cfg.isCreator then
            local strokeGradient = Instance.new("UIGradient")
            strokeGradient.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0.0, Color3.fromRGB(0, 180, 255)),
                ColorSequenceKeypoint.new(0.5, Color3.fromRGB(255, 255, 255)),
                ColorSequenceKeypoint.new(1.0, Color3.fromRGB(0, 120, 255)),
            })
            strokeGradient.Parent = stroke

            task.spawn(function()
                while bb.Parent do
                    local tw = TweenService:Create(strokeGradient, TweenInfo.new(2.8, Enum.EasingStyle.Linear), { Rotation = 360 })
                    tw:Play()
                    tw.Completed:Wait()
                    strokeGradient.Rotation = 0
                end
            end)
        end

        local padding = Instance.new("UIPadding")
        padding.PaddingLeft = UDim.new(0, 8)
        padding.PaddingRight = UDim.new(0, 8)
        padding.Parent = pill

        local titleLbl = Instance.new("TextLabel")
        titleLbl.Name = "TitleLabel"
        titleLbl.AutomaticSize = Enum.AutomaticSize.X
        titleLbl.Size = UDim2.new(0, 0, 1, 0)
        titleLbl.BackgroundTransparency = 1
        titleLbl.Font = Enum.Font.GothamBold
        titleLbl.Text = cfg.title
        titleLbl.TextColor3 = cfg.isCreator and Color3.fromRGB(240, 250, 255) or cfg.color
        titleLbl.TextSize = 10
        titleLbl.Parent = pill

        if cfg.isCreator then
            local textGradient = Instance.new("UIGradient")
            textGradient.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0.0, Color3.fromRGB(255, 255, 255)),
                ColorSequenceKeypoint.new(1.0, Color3.fromRGB(0, 200, 255)),
            })
            textGradient.Parent = titleLbl
        end
    end

    local function setupPlayerTags(player)
        local cfg = TAG_CONFIG[player.UserId]
        if not cfg then return end

        if player.Character then
            task.spawn(attachBtrRoleTag, player.Character, cfg)
        end

        player.CharacterAdded:Connect(function(character)
            task.spawn(attachBtrRoleTag, character, cfg)
        end)
    end

    for _, p in ipairs(Players:GetPlayers()) do
        setupPlayerTags(p)
    end

    Players.PlayerAdded:Connect(setupPlayerTags)
end)

