    local function addPart(p,key,prop,cat,x,y,z,rx,ry,rz,group,index,side)
        p[#p+1]={key=key,prop=prop,cat=cat,x=x,y=y,z=z,rx=rx or 0,ry=ry or 0,rz=rz or 0,group=group or "body",index=index or 1,side=side or 0}
    end

    local function dragon15()
        local p={}
        addPart(p,"bodyA","Block2","Building",0,3.5,-2.2,0,90,0,"body",1)
        addPart(p,"bodyB","Block2","Building",0,3.7,2.2,5,90,0,"body",2)
