    local BLUEPRINTS = {
        Dragon = {[15]=dragon15,[25]=dragon25},
        Phoenix = {[15]=phoenix15,[25]=phoenix25},
        ["Dire Wolf"] = {[15]=wolf15,[25]=wolf25},
        ["Crystal Serpent"] = {[15]=serpent15,[25]=serpent25},
        ["Abyssal Mantis"] = {[15]=mantis15,[25]=mantis25},
        ["Thunder Raptor"] = {[15]=raptor15,[25]=raptor25},
        ["Obsidian Basilisk"] = {[15]=basilisk15,[25]=basilisk25},
        ["Ember Wyvern"] = {[15]=wyvern15,[25]=wyvern25},
        ["Frosthorn Beast"] = {[15]=frost15,[25]=frost25}
    }

    local function variantNumber()
        return (Forge.selectedVariant == "15 Props — Compact") and 15 or 25
    end
    local function blueprint()
        local b=BLUEPRINTS[Forge.selectedCreature]
        return b and b[variantNumber()]() or {}
    end
    local function currentPalette()
        local creature=Forge.selectedCreature
        local list=PALETTES[creature] or {}
        local map=THEME_MAPS[creature] or {}
        local key=map[Forge.theme] or Forge.theme or "Default"
        return list[key] or list.Default
    end
    local function themeNames()
        return THEME_ORDER
    end

    local function notify(title,msg,dur)
        pcall(function()
            game:GetService("StarterGui"):SetCore("SendNotification", {Title=title,Text=msg,Duration=dur or 3})
        end)
    end
    local function lerp(a,b,t) return a+(b-a)*t end
    local function safeUnit(v,fallback)
        if v.Magnitude>0.001 then return v.Unit end
        return fallback or Vector3.new(0,0,-1)
    end

    local function getGroundY(pos,fallback)
        local char=lp.Character
        local wc=Workspace:FindFirstChild("WorkspaceCom")
        local ignore={}
        if char then ignore[#ignore+1]=char end
        if wc then ignore[#ignore+1]=wc end
        local rp=RaycastParams.new()
        rp.FilterType=Enum.RaycastFilterType.Exclude
        rp.FilterDescendantsInstances=ignore
        local hit=Workspace:Raycast(pos+Vector3.new(0,6,0),Vector3.new(0,-80,0),rp)
        return hit and hit.Position.Y or (fallback or pos.Y)
    end

    local function getDimensions(inst)
        if not inst then return Vector3.new(0,0,0) end
        local ok,cf,size=pcall(function() return inst:GetBoundingBox() end)
        if ok and size then return size end
        if inst:IsA("BasePart") then return inst.Size end
        return Vector3.new(0,0,0)
    end

    local function describeProp(prop,cat)
        return string.format("%s [%s]",PROP_FRIENDLY[prop] or prop,cat or "?")
    end

    local function cleanLightsAndPrepare(prop,def)
        if not prop then return end
        for _,d in ipairs(prop:GetDescendants()) do
            if d:IsA("Light") then
                pcall(function() d.Enabled=false d.Brightness=0 d.Range=0 d:Destroy() end)
            elseif d:IsA("Seat") or d:IsA("VehicleSeat") then
                pcall(function() d.CanCollide=false end)
            elseif d:IsA("BasePart") then
                pcall(function()
                    d.CanCollide=false
                    if def.group=="eye" or def.group=="glow" then d.Material=Enum.Material.Neon end
                end)
            end
        end
    end

    local function colorFor(def,t,abilityActive)
        local pal=currentPalette()
        local pulse=(math.sin(t*8+(def.index or 1)*0.6)+1)*0.5
        if abilityActive then
            if def.group=="eye" or def.group=="glow" or def.group=="accent" then
                return pal.glow:Lerp(Color3.new(1,1,1),0.22+0.18*pulse)
            end
            if math.sin(t*18+(def.index or 1))>0.45 then return pal.accent end
        end
        if def.group=="eye" or def.group=="glow" then return pal.eye end
        if def.group=="wing" then return pal.wing end
        if def.group=="horn" or def.group=="claw" or def.group=="talon" or def.group=="fin" or def.group=="crest" or def.group=="jaw" or def.group=="muzzle" or def.group=="beak" then return pal.accent end
        if def.group=="detail" or def.group=="paw" or def.group=="foot" or def.group=="plate" then return pal.secondary end
        if def.group=="tail" and ((def.index or 1)%2==0) then return pal.secondary end
        return pal.base
    end

    local function paintProp(prop,def,t,abilityActive)
        if not prop then return end
        local col=colorFor(def,t or 0,abilityActive)
        cleanLightsAndPrepare(prop,def)
        for _,d in ipairs(prop:GetDescendants()) do
            if d:IsA("BasePart") then
                pcall(function() d.Color=col end)
            end
        end
        local cpc=prop:FindFirstChild("ChangePropColor") or prop:FindFirstChild("ChangePropColor",true)
        if cpc then
            pcall(function()
                if cpc:IsA("RemoteFunction") then cpc:InvokeServer(col)
                elseif cpc:IsA("RemoteEvent") then cpc:FireServer(col) end
            end)
        end
    end

    -- ========================================================================
    -- UNIQUE ANIMATION / POSE SOLVER
    -- ========================================================================
    local function poseCF(def,t,moveAlpha,stride,ability,abilityT)
        local cfg=CREATURES[Forge.selectedCreature]
        local sc=cfg.scale or 1
        local x,y,z=def.x*sc,def.y*sc,def.z*sc
        local rx,ry,rz=math.rad(def.rx or 0),math.rad(def.ry or 0),math.rad(def.rz or 0)
        local a=math.clamp(moveAlpha or 0,0,1)
        local s=stride or 0
        local at=abilityT or 0
        local idx=def.index or 1
        local side=def.side or 0

        if Forge.selectedCreature=="Dragon" then
            if def.group=="body" or def.group=="chest" then
                y=y+math.sin(t*1.9)*0.16+math.sin(s*2)*0.22*a
                rx=rx+math.rad(math.sin(t*1.9)*2.0)
            elseif def.group=="neck" then
                ry=ry+math.rad(math.sin(t*1.25+idx*0.4)*6)
                rx=rx+math.rad(math.sin(t*1.7+idx)*2.5)
            elseif def.group=="head" or def.group=="jaw" then
                ry=ry+math.rad(math.sin(t*0.8)*5)
                rx=rx+math.rad(math.sin(t*1.6)*2)
                if def.group=="jaw" then rx=rx-math.rad(math.max(0,math.sin(t*1.8))*7) end
                if ability=="Roar" and def.group=="jaw" then rx=rx-math.rad(math.max(0,math.sin(at*5))*28) end
            elseif def.group=="wing" then
                local amp=a>0.2 and 48 or 25
                local rate=a>0.2 and 5.4 or 2.8
                rz=rz+math.rad(-side*math.sin(t*rate+idx*0.21)*amp)
                y=y+math.sin(t*rate+idx)*0.12
            elseif def.group=="leg" then
                local ph=s+((idx%2==0) and math.pi or 0)+((idx>2) and 0.18 or 0)
                local u=math.sin(ph)
                rx=rx+math.rad(u*28*a)
                y=y+math.max(0,-u)*0.28*a
            elseif def.group=="paw" then
                rx=rx+math.rad(math.sin(s+(idx%2)*math.pi)*18*a)
            elseif def.group=="horn" then
                rz=rz+math.rad(math.sin(t*1.6+idx)*2)
            elseif def.group=="tail" then
                local w=math.sin(t*2.4-idx*0.9)
                x=x+w*(0.28+idx*0.23)*sc
                ry=ry+math.rad(w*(8+idx*5))
                rz=rz+math.rad(math.cos(t*2.1-idx)*5)
            elseif def.group=="eye" then
                y=y+math.sin(t*7+idx)*0.025
            end

        elseif Forge.selectedCreature=="Phoenix" then
            if def.group=="body" or def.group=="chest" then
                y=y+math.sin(t*2.2)*0.15+math.abs(math.sin(t*4))*0.18*a
                rx=rx+math.rad(math.sin(t*2.2)*2.2)
            elseif def.group=="neck" then
                ry=ry+math.rad(math.sin(t*1.0+idx*0.45)*7)
                rx=rx+math.rad(math.sin(t*1.8)*2.4)
            elseif def.group=="head" or def.group=="beak" then
                rx=rx+math.rad(math.sin(t*1.55)*3)
                ry=ry+math.rad(math.sin(t*0.75)*5)
            elseif def.group=="wing" then
                local amp=a>0.2 and 58 or 28
                local rate=a>0.2 and 5.8 or 3.1
                rz=rz+math.rad(-side*math.sin(t*rate+idx*0.2)*amp)
                y=y+math.sin(t*rate+idx)*0.13
            elseif def.group=="crest" then
                rx=rx+math.rad(math.sin(t*3+idx)*8)
                rz=rz+math.rad(side*math.sin(t*1.4+idx)*4)
            elseif def.group=="leg" or def.group=="talon" then
                local ph=s+((idx%2==0) and math.pi or 0)
                rx=rx+math.rad(math.sin(ph)*22*a)
                y=y+math.max(0,-math.cos(ph))*0.18*a
            elseif def.group=="tail" then
                local w=math.sin(t*3.4+idx*0.8)
                x=x+w*(0.35+idx*0.17)*sc
                rz=rz+math.rad(w*(11+idx*2.5))
                y=y+math.cos(t*2.6+idx)*0.17
            elseif def.group=="eye" then
                y=y+math.sin(t*7+idx)*0.025
            elseif def.group=="glow" then
                y=y+math.sin(t*4)*0.08
            end
            if ability=="Rebirth" and at<1.35 and (def.group=="wing" or def.group=="tail" or def.group=="crest") then
                rz=rz+math.rad(math.sin(at*14)*14)
            end

        elseif Forge.selectedCreature=="Dire Wolf" or Forge.selectedCreature=="Frosthorn Beast" then
            local beast=Forge.selectedCreature=="Dire Wolf"
            if def.group=="body" or def.group=="chest" or def.group=="shoulder" then
                y=y+math.sin(t*(beast and 2.7 or 2.3))*0.11+math.sin(s*2)*0.18*a
                rx=rx+math.rad(math.sin(t*2.7)*1.8)
                rz=rz+math.rad(math.cos(t*1.5)*1.1)
            elseif def.group=="neck" then
                ry=ry+math.rad(math.sin(t*0.9)*6)
                rx=rx+math.rad(math.sin(t*1.5)*2.2)
            elseif def.group=="head" or def.group=="muzzle" or def.group=="jaw" then
                ry=ry+math.rad(math.sin(t*0.7)*6)
                rx=rx+math.rad(math.sin(t*1.15)*2.4)
                if def.group=="jaw" then rx=rx-math.rad(math.max(0,math.sin(t*1.6))*8) end
                if ability=="Howl" and def.group=="jaw" then rx=rx-math.rad(24*math.max(0,math.sin(at*5))) end
                if ability=="Frost Charge" and def.group=="head" then rx=rx-math.rad(7) end
            elseif def.group=="ear" then
                rx=rx+math.rad(math.sin(t*2.7+idx)*8)
                rz=rz+math.rad(math.cos(t*1.4+idx)*3)
            elseif def.group=="leg" then
                local ph=s+((idx%2==0) and math.pi or 0)+((idx>2) and 0.22 or 0)
                local u=math.sin(ph)
                rx=rx+math.rad(u*34*a)
                y=y+math.max(0,-math.cos(ph))*0.24*a
            elseif def.group=="paw" then
                rx=rx+math.rad(math.sin(s+idx)*12*a)
            elseif def.group=="horn" and not beast then
                rz=rz+math.rad(math.sin(t*1.8+idx)*2.5)
            elseif def.group=="tail" then
                local w=math.sin(t*3.0+idx*0.7)
                ry=ry+math.rad(w*(11+idx*4))
                rz=rz+math.rad(math.cos(t*2.1+idx)*5)
                y=y+math.sin(t*2.4+idx)*0.10
            elseif def.group=="eye" then
                ry=ry+math.rad(math.sin(t*4+idx)*2)
            end

        elseif Forge.selectedCreature=="Crystal Serpent" or Forge.selectedCreature=="Obsidian Basilisk" then
            local serpent=Forge.selectedCreature=="Crystal Serpent"
            if def.group=="segment" then
                local ph=t*(serpent and 2.45 or 2.0)-idx*0.48
                local w=math.sin(ph)
                local w2=math.sin(ph+0.65)
                x=x+w*(0.32+idx*0.075)*sc
                y=y+w2*0.25*sc
                ry=ry+math.rad(w*(8+idx*0.6))
                rz=rz+math.rad(math.cos(ph)*3)
            elseif def.group=="body" or def.group=="chest" then
                y=y+math.sin(t*2.0+idx)*0.10
                rx=rx+math.rad(math.sin(t*2.0)*1.8)
            elseif def.group=="neck" then
                ry=ry+math.rad(math.sin(t*1.1+idx*0.45)*5)
                rx=rx+math.rad(math.sin(t*1.6)*2.0)
            elseif def.group=="head" or def.group=="snout" or def.group=="jaw" then
                ry=ry+math.rad(math.sin(t*0.75)*6)
                rx=rx+math.rad(math.sin(t*1.35)*2.4)
                if def.group=="jaw" then rx=rx-math.rad(math.max(0,math.sin(t*1.8))*9) end
                if ability=="Venom Gaze" and def.group=="head" then ry=ry+math.rad(math.sin(at*6)*8) end
            elseif def.group=="fin" or def.group=="horn" or def.group=="plate" or def.group=="crest" then
                rz=rz+math.rad(-side*math.sin(t*3.0+idx*0.35)*16)
                y=y+math.cos(t*2.1+idx)*0.06
            elseif def.group=="tail" then
                ry=ry+math.rad(math.sin(t*2.8+idx)*12)
            elseif def.group=="eye" then
                y=y+math.sin(t*6+idx)*0.03
            end
            if ability=="Crystal Pulse" and def.group=="segment" then
                local pulse=math.max(0,1-math.abs(math.sin(at*6-idx*0.28)))
                ry=ry+math.rad(pulse*5)
            end

        elseif Forge.selectedCreature=="Abyssal Mantis" then
            if def.group=="body" then
                y=y+math.sin(t*2.4)*0.10
                rz=rz+math.rad(math.sin(t*1.6)*1.5)
            elseif def.group=="head" or def.group=="jaw" then
                ry=ry+math.rad(math.sin(t*1.1)*8)
                rx=rx+math.rad(math.sin(t*1.8)*3)
            elseif def.group=="antenna" then
                ry=ry+math.rad(math.sin(t*2.4+idx)*11)
                rz=rz+math.rad(math.cos(t*1.7+idx)*5)
            elseif def.group=="arm" or def.group=="claw" then
                local swing=math.sin(t*2.0+idx*0.7)*10
                rz=rz+math.rad(-side*swing)
                if ability=="Void Slash" and (def.group=="claw" or def.group=="arm") then
                    rz=rz+math.rad(-side*38*math.sin(math.clamp(at*8,0,math.pi)))
                end
            elseif def.group=="leg" or def.group=="foot" then
                local ph=s*1.15+idx*0.7
                ry=ry+math.rad(math.sin(ph)*10*a)
                rz=rz+math.rad(-side*math.cos(ph)*9*a)
                y=y+math.max(0,-math.sin(ph))*0.16*a
            elseif def.group=="eye" then
                y=y+math.sin(t*8+idx)*0.02
            elseif def.group=="detail" then
                y=y+math.sin(t*3+idx)*0.08
            end

        elseif Forge.selectedCreature=="Thunder Raptor" then
            if def.group=="body" or def.group=="chest" then
                y=y+math.sin(t*2.5)*0.10+math.abs(math.sin(s*2))*0.18*a
                rx=rx+math.rad(math.sin(t*2.5)*2)
            elseif def.group=="neck" then
                ry=ry+math.rad(math.sin(t*1.3+idx)*7)
            elseif def.group=="head" or def.group=="beak" then
                ry=ry+math.rad(math.sin(t*0.9)*5)
                rx=rx+math.rad(math.sin(t*1.8)*3)
            elseif def.group=="wing" then
                local amp=a>0.2 and 48 or 18
                rz=rz+math.rad(-side*math.sin(t*(a>0.2 and 6.0 or 2.8)+idx*0.25)*amp)
            elseif def.group=="leg" or def.group=="talon" then
                local ph=s+((idx%2==0) and math.pi or 0)
                rx=rx+math.rad(math.sin(ph)*28*a)
                y=y+math.max(0,-math.cos(ph))*0.20*a
            elseif def.group=="tail" then
                local w=math.sin(t*3.7+idx)
                x=x+w*0.22*sc
                rz=rz+math.rad(w*12)
            elseif def.group=="crest" then
                rx=rx+math.rad(math.sin(t*3+idx)*8)
            elseif def.group=="eye" then
                y=y+math.sin(t*8+idx)*0.02
            end
            if ability=="Thunder Dive" and def.group=="wing" then rz=rz+math.rad(-side*22*math.sin(at*12)) end

        elseif Forge.selectedCreature=="Ember Wyvern" then
            if def.group=="body" or def.group=="chest" then
                y=y+math.sin(t*2.0)*0.12
                rx=rx+math.rad(math.sin(t*2.0)*2)
            elseif def.group=="neck" then
                ry=ry+math.rad(math.sin(t*1.15+idx)*6)
                rx=rx+math.rad(math.sin(t*1.8)*2)
            elseif def.group=="head" or def.group=="jaw" then
                ry=ry+math.rad(math.sin(t*0.8)*5)
                if def.group=="jaw" then rx=rx-math.rad(math.max(0,math.sin(t*1.7))*8) end
            elseif def.group=="horn" then
                rz=rz+math.rad(math.sin(t*1.5+idx)*3)
            elseif def.group=="wing" then
                rz=rz+math.rad(-side*math.sin(t*(a>0.2 and 5.2 or 2.7)+idx*0.18)*(a>0.2 and 54 or 25))
            elseif def.group=="leg" or def.group=="talon" then
                local ph=s+((idx%2==0) and math.pi or 0)
                rx=rx+math.rad(math.sin(ph)*25*a)
                y=y+math.max(0,-math.cos(ph))*0.18*a
            elseif def.group=="tail" then
                local w=math.sin(t*3.0+idx*0.85)
                x=x+w*0.28*sc
                rz=rz+math.rad(w*(8+idx*3))
            elseif def.group=="eye" then
                y=y+math.sin(t*8+idx)*0.025
            elseif def.group=="glow" then
                y=y+math.sin(t*7)*0.12
            end
            if ability=="Ember Burst" and def.group=="glow" then y=y+math.sin(at*16)*0.25 end
        end

        local base=CFrame.new(Forge.anchor)*CFrame.Angles(0,Forge.yaw,0)
        return base*CFrame.new(x,y,z)*CFrame.Angles(rx,ry,rz)
    end

    local function sendCFrame(w,cf)
        if not w or not w.scf or not cf then return end
        pcall(function()
            if w.scf:IsA("RemoteFunction") then w.scf:InvokeServer(cf)
            elseif w.scf:IsA("RemoteEvent") then w.scf:FireServer(cf) end
        end)
    end

    local function clearConstruction()
        if Forge.loop then pcall(function() Forge.loop:Disconnect() end) Forge.loop=nil end
        if Forge.syncLoop then pcall(function() Forge.syncLoop:Disconnect() end) Forge.syncLoop=nil end
        Forge.workers={}
        Forge.spawning=false
        Forge._cursor=0
    end

    local function clearBrookhavenProps()
        pcall(function()
            local re=ReplicatedStorage:FindFirstChild("RE")
            local ct=re and re:FindFirstChild("1Clea1rTool1s")
            if ct then ct:FireServer("ClearAllProps") end
        end)
    end

    local function ensurePropMaker()
        local char=lp.Character or lp.CharacterAdded:Wait()
        local backpack=lp:FindFirstChildOfClass("Backpack")
        local pm=char:FindFirstChild("PropMaker") or (backpack and backpack:FindFirstChild("PropMaker"))
        if pm then return pm end
        local re=ReplicatedStorage:FindFirstChild("RE")
        local tool=re and re:FindFirstChild("1Too1l")
        if tool then pcall(function() tool:InvokeServer("PickingTools","PropMaker") end) end
        local deadline=os.clock()+5
        while os.clock()<deadline do
            backpack=lp:FindFirstChildOfClass("Backpack")
            pm=char:FindFirstChild("PropMaker") or (backpack and backpack:FindFirstChild("PropMaker"))
            if pm then return pm end
            task.wait(0.1)
        end
        return nil
    end

    local function waitForToolRemote(pm)
        if not pm then return nil end
        local r=pm:FindFirstChild("Tool_PropMake")
        local deadline=os.clock()+5
        while not r and os.clock()<deadline do
            r=pm:FindFirstChild("Tool_PropMake")
            task.wait(0.1)
        end
        return r
    end

    local function snapshotOwnedProps()
        local out={}
        local wc=Workspace:FindFirstChild("WorkspaceCom")
        if not wc then return out end
        local mine="Prop"..lp.Name
        for _,folder in ipairs(wc:GetChildren()) do
            for _,prop in ipairs(folder:GetChildren()) do
                if prop.Name==mine then
                    local scf=prop:FindFirstChild("SetCurrentCFrame") or prop:FindFirstChild("SetCurrentCFrame",true)
                    if scf then out[scf]=true end
                end
            end
        end
        return out
    end

    local function waitForNewProp(known,timeout)
        local deadline=os.clock()+timeout
        local wc=Workspace:FindFirstChild("WorkspaceCom")
        local mine="Prop"..lp.Name
        while os.clock()<deadline do
            if wc then
                for _,folder in ipairs(wc:GetChildren()) do
                    for _,prop in ipairs(folder:GetChildren()) do
                        if prop.Name==mine then
                            local scf=prop:FindFirstChild("SetCurrentCFrame") or prop:FindFirstChild("SetCurrentCFrame",true)
                            if scf and not known[scf] then
                                return prop,scf,(prop:FindFirstChild("ChangePropColor") or prop:FindFirstChild("ChangePropColor",true))
                            end
                        end
                    end
                end
            end
            task.wait(0.07)
        end
        return nil,nil,nil
    end

    local function requestProp(def,pm,toolPropMake,known,telemetry,clearRemote,stagingCF)
        Forge.lastRequestedProp=def.prop
        pcall(function() telemetry:FireServer("filterClick",{name=def.cat,itemType="Props"}) end)
        task.wait(0.05)
        pcall(function() telemetry:FireServer("filterClick",{name=def.prop,itemType="Props"}) end)
        task.wait(0.05)
        pcall(function()
            if def.prop=="FloorCushion" then
                clearRemote:FireServer("RequestingPropFeatureName",def.prop,def.cat)
            else
                clearRemote:FireServer("RequestingPropName",def.prop,def.cat)
            end
        end)
        task.wait(0.16)
        pcall(function() toolPropMake:FireServer(Workspace.Terrain,stagingCF.Position) end)
        local prop,scf,cpc=waitForNewProp(known,2.8)
        Forge.lastActualProp=prop and prop.Name or ""
        return prop,scf,cpc
    end

    local stopCreature

    local function buildHud()
        if Forge.hud then pcall(function() Forge.hud:Destroy() end) end
        Forge.hudButtons={}
        local pg=lp:FindFirstChildOfClass("PlayerGui")
        if not pg then return end
        local gui=Instance.new("ScreenGui")
        gui.Name="BTR_CreatureController_v10"
        gui.ResetOnSpawn=false
        gui.ZIndexBehavior=Enum.ZIndexBehavior.Sibling
        gui.Parent=pg
        Forge.hud=gui

        local frame=Instance.new("Frame")
        frame.Size=UDim2.fromOffset(250,92)
        frame.Position=UDim2.new(1,-260,1,-122)
        frame.BackgroundColor3=Color3.fromRGB(15,18,24)
        frame.BackgroundTransparency=0.08
        frame.Parent=gui
        Instance.new("UICorner",frame).CornerRadius=UDim.new(0,14)

        local title=Instance.new("TextLabel")
        title.Size=UDim2.new(1,-18,0,20)
        title.Position=UDim2.fromOffset(9,6)
        title.BackgroundTransparency=1
        title.Font=Enum.Font.GothamBold
        title.TextSize=11
        title.TextXAlignment=Enum.TextXAlignment.Left
        title.TextColor3=Color3.fromRGB(240,245,255)
        title.Text=Forge.selectedCreature
        title.Parent=frame
        Forge.hudButtons.title=title

        local status=Instance.new("TextLabel")
        status.Size=UDim2.new(1,-18,0,30)
        status.Position=UDim2.fromOffset(9,27)
        status.BackgroundTransparency=1
        status.Font=Enum.Font.GothamMedium
        status.TextSize=9
        status.TextWrapped=true
        status.TextXAlignment=Enum.TextXAlignment.Left
        status.TextColor3=Color3.fromRGB(185,200,220)
        status.Text=Forge.status
        status.Parent=frame
        Forge.hudButtons.status=status

        local sprint=Instance.new("TextButton")
        sprint.Size=UDim2.fromOffset(72,28)
        sprint.Position=UDim2.fromOffset(9,59)
        sprint.BackgroundColor3=Color3.fromRGB(37,50,69)
        sprint.TextColor3=Color3.fromRGB(240,245,255)
        sprint.Font=Enum.Font.GothamBold
        sprint.TextSize=9
        sprint.Text="SPRINT"
        sprint.Parent=frame
        Instance.new("UICorner",sprint).CornerRadius=UDim.new(0,8)
        sprint.Activated:Connect(function()
            Forge.sprint=not Forge.sprint
            sprint.BackgroundColor3=Forge.sprint and Color3.fromRGB(45,88,74) or Color3.fromRGB(37,50,69)
            status.Text=Forge.selectedCreature.." • "..(Forge.sprint and "SPRINT" or "WALK")
        end)
        Forge.hudButtons.sprint=sprint

        local ability=Instance.new("TextButton")
        ability.Size=UDim2.fromOffset(92,28)
        ability.Position=UDim2.fromOffset(87,59)
        ability.BackgroundColor3=Color3.fromRGB(70,44,55)
        ability.TextColor3=Color3.fromRGB(255,236,242)
        ability.Font=Enum.Font.GothamBold
        ability.TextSize=9
        ability.Text="ABILITY"
        ability.Parent=frame
        Instance.new("UICorner",ability).CornerRadius=UDim.new(0,8)
        ability.Activated:Connect(function()
            if Forge.active then
                Forge.ability=CREATURES[Forge.selectedCreature].ability
                Forge.abilityT=0
            end
        end)
        Forge.hudButtons.ability=ability

        local exit=Instance.new("TextButton")
        exit.Size=UDim2.fromOffset(54,28)
        exit.Position=UDim2.fromOffset(187,59)
        exit.BackgroundColor3=Color3.fromRGB(63,34,42)
        exit.TextColor3=Color3.fromRGB(255,224,230)
        exit.Font=Enum.Font.GothamBold
        exit.TextSize=9
        exit.Text="CLEAR"
        exit.Parent=frame
        Instance.new("UICorner",exit).CornerRadius=UDim.new(0,8)
        exit.Activated:Connect(function()
            stopCreature()
        end)
        Forge.hudButtons.exit=exit
    end

    local function destroyHud()
        if Forge.hud then pcall(function() Forge.hud:Destroy() end) Forge.hud=nil end
        Forge.hudButtons={}
    end

    stopCreature = function()
        Forge.active=false
        Forge.sprint=false
        Forge.ability=nil
        Forge.abilityT=0
        clearConstruction()
        destroyHud()
        clearBrookhavenProps()
        Forge.status="Idle • props cleared"
    end

    local function setStatus(s)
        Forge.status=s
        if Forge.hudButtons.status then Forge.hudButtons.status.Text=s end
    end

    local function spawnCreature()
        if Forge.spawning then return end
        Forge.spawning=true
        Forge.active=true
        Forge.lastFailure=""
        Forge.workers={}
        Forge.time=0
        Forge.stride=0
        Forge.moveAlpha=0
        Forge.ability=nil
        Forge.abilityT=0

        local cfg=CREATURES[Forge.selectedCreature]
        local parts=blueprint()
        local total=#parts
        if total~=15 and total~=25 then
            Forge.lastFailure="Blueprint count is "..tostring(total)
            Forge.spawning=false
            notify("Creature Forge","Invalid blueprint count: "..tostring(total),4)
            return
        end

        local char=lp.Character or lp.CharacterAdded:Wait()
        local hrp=char:FindFirstChild("HumanoidRootPart")
        if not hrp then Forge.spawning=false return end

        setStatus("Preparing "..Forge.selectedCreature.." • "..total.." props")
        clearBrookhavenProps()
        task.wait(0.35)
        if not Forge.active then Forge.spawning=false return end

        local pm=ensurePropMaker()
        if not pm then
            Forge.lastFailure="PropMaker not found"
            Forge.spawning=false
            Forge.active=false
            notify("Creature Forge","PropMaker could not be acquired.",4)
            return
        end
        local hum=char:FindFirstChildOfClass("Humanoid")
        if hum then pcall(function() hum:EquipTool(pm) end) task.wait(0.35) end
        local toolPropMake=waitForToolRemote(pm)
        if not toolPropMake then
            Forge.lastFailure="Tool_PropMake not found"
            Forge.spawning=false
            Forge.active=false
            notify("Creature Forge","Tool_PropMake not found.",4)
            return
        end

        local re=ReplicatedStorage:WaitForChild("RE")
        local clearRemote=re:WaitForChild("1Clea1rTool1s")
        local telemetry=(ReplicatedStorage:FindFirstChild("Remotes") and ReplicatedStorage.Remotes:FindFirstChild("TelemetryClientInteraction"))
        if not telemetry then
            telemetry={FireServer=function() end}
        end
        pcall(function() clearRemote:FireServer("OpenPropMenu") end)
        task.wait(0.2)

        local fwd=safeUnit(Vector3.new(hrp.CFrame.LookVector.X,0,hrp.CFrame.LookVector.Z),Vector3.new(0,0,-1))
        local spawnPos=hrp.Position+fwd*18
        local ground=getGroundY(spawnPos,hrp.Position.Y)
        Forge.anchor=Vector3.new(spawnPos.X,ground+cfg.ground,spawnPos.Z)
        Forge.yaw=math.atan2(-fwd.X,-fwd.Z)

        local known=snapshotOwnedProps()
        for i,def in ipairs(parts) do
            if not Forge.active then Forge.spawning=false return end
            local label=string.format("%02d/%02d %s",i,total,describeProp(def.prop,def.cat))
            setStatus("BUILDING "..label)
            local staging=Forge.anchor+Vector3.new(0,28+i*0.5,0)
            local stageCF=CFrame.new(staging)*CFrame.Angles(0,Forge.yaw,0)*CFrame.Angles(math.rad(def.rx or 0),math.rad(def.ry or 0),math.rad(def.rz or 0))
            local prop,scf,cpc=requestProp(def,pm,toolPropMake,known,telemetry,clearRemote,stageCF)
            if not prop or not scf then
                -- Retry the same exact prop before giving up. This mirrors the
                -- original systems' wait/reacquire pattern rather than silently
                -- replacing anatomy with a random approximation.
                setStatus("RETRY "..label)
                pcall(function() clearRemote:FireServer("ClosePropMenu") end)
                task.wait(0.12)
                pcall(function() clearRemote:FireServer("OpenPropMenu") end)
                task.wait(0.18)
                known=snapshotOwnedProps()
                prop,scf,cpc=requestProp(def,pm,toolPropMake,known,telemetry,clearRemote,stageCF)
            end
            if not prop or not scf then
                Forge.lastFailure=label.." | requested="..tostring(def.prop)
                setStatus("ERROR • "..label)
                Forge.active=false
                Forge.spawning=false
                clearConstruction()
                clearBrookhavenProps()
                notify("Creature Forge","Construction stopped cleanly at "..label,5)
                return
            end
            cleanLightsAndPrepare(prop,def)
            paintProp(prop,def,0,false)
            Forge.workers[#Forge.workers+1]={def=def,prop=prop,scf=scf,cpc=cpc,last=nil,lastColor=Forge.theme,lastColorSync=0,size=getDimensions(prop)}
            known[scf]=true
            -- Keep all parts hidden above the creature until the full anatomy is complete.
            sendCFrame(Forge.workers[#Forge.workers],stageCF)
        end

        pcall(function() clearRemote:FireServer("ClosePropMenu") end)
        pcall(function() re:FindFirstChild("1Too1l"):InvokeServer("PickingTools","PropMaker") end)
        task.wait(0.3)
        if not Forge.active then Forge.spawning=false return end

        setStatus("REVEALING "..Forge.selectedCreature.." • "..total.." props")
        for _,w in ipairs(Forge.workers) do
            local target=poseCF(w.def,0,0,0,nil,0)
            w.last=target
            sendCFrame(w,target)
            task.wait(0.025)
        end

        Forge.spawning=false
        setStatus(Forge.selectedCreature.." • "..total.." props • READY")
        notify("Creature Forge",Forge.selectedCreature.." ready • "..cfg.class.." • "..cfg.speed.." studs/s",4)

        if Forge.loop then Forge.loop:Disconnect() end
        Forge.loop=RunService.RenderStepped:Connect(function(dt)
            if not Forge.active then return end
            local cfgNow=CREATURES[Forge.selectedCreature]
            Forge.time=Forge.time+dt
            local c=lp.Character
            local humNow=c and c:FindFirstChildOfClass("Humanoid")
            local md=humNow and humNow.MoveDirection or Vector3.new()
            local planar=Vector3.new(md.X,0,md.Z)
            local moving=planar.Magnitude>0.05
            Forge.moveAlpha=lerp(Forge.moveAlpha,moving and 1 or 0,math.clamp(dt*8,0,1))
            if moving then
                local speed=Forge.sprint and cfgNow.sprint or cfgNow.speed
                Forge.stride=Forge.stride+dt*(speed*0.18)
                local desired=safeUnit(planar,Vector3.new(0,0,-1))
                local targetYaw=math.atan2(-desired.X,-desired.Z)
                local diff=(targetYaw-Forge.yaw+math.pi)%(2*math.pi)-math.pi
                Forge.yaw=Forge.yaw+math.clamp(diff,-cfgNow.turn*dt,cfgNow.turn*dt)
                Forge.anchor=Forge.anchor+desired*speed*dt
            end
            local gy=getGroundY(Forge.anchor,Forge.anchor.Y)
            Forge.anchor=Vector3.new(Forge.anchor.X,gy+cfgNow.ground,Forge.anchor.Z)

            if Forge.mode=="FOLLOW" and c and c:FindFirstChild("HumanoidRootPart") then
                local root=c.HumanoidRootPart
                local target=root.Position-root.CFrame.LookVector*5
                local to=Vector3.new(target.X-Forge.anchor.X,0,target.Z-Forge.anchor.Z)
                if to.Magnitude>2 then
                    local d=to.Unit
                    local followSpeed=math.min(cfgNow.speed, math.max(8,to.Magnitude*2.0))
                    Forge.anchor=Forge.anchor+d*followSpeed*dt
                    local targetYaw=math.atan2(-d.X,-d.Z)
                    local diff=(targetYaw-Forge.yaw+math.pi)%(2*math.pi)-math.pi
                    Forge.yaw=Forge.yaw+math.clamp(diff,-cfgNow.turn*dt,cfgNow.turn*dt)
                    Forge.moveAlpha=math.max(Forge.moveAlpha,0.45)
                    Forge.stride=Forge.stride+dt*(followSpeed*0.18)
                end
            end

            if Forge.ability then
                Forge.abilityT=Forge.abilityT+dt
                if Forge.abilityT>1.45 then Forge.ability=nil Forge.abilityT=0 end
            end

            for _,w in ipairs(Forge.workers) do
                w.target=poseCF(w.def,Forge.time,Forge.moveAlpha,Forge.stride,Forge.ability,Forge.abilityT)
            end

            Forge._cursor=(Forge._cursor or 0)+1
            if Forge._cursor>#Forge.workers then Forge._cursor=1 end
            if #Forge.workers>0 then
                local count=(#Forge.workers>=25) and 7 or 6
                for n=1,math.min(count,#Forge.workers) do
                    local i=((Forge._cursor+n-2)%#Forge.workers)+1
                    local w=Forge.workers[i]
                    if w and w.scf and w.target then
                        local delta=not w.last or (w.target.Position-w.last.Position).Magnitude>0.03
                        if delta then
                            w.last=w.target
                            sendCFrame(w,w.target)
                        end
                    end
                    if w and w.prop and (os.clock()-(w.lastColorSync or 0)>=0.30) then
                        w.lastColorSync=os.clock()
                        paintProp(w.prop,w.def,Forge.time,Forge.ability~=nil)
                    end
                end
            end

            if Forge.hudButtons.title then Forge.hudButtons.title.Text=Forge.selectedCreature.." • "..cfgNow.class end
            if Forge.hudButtons.status then
                Forge.hudButtons.status.Text=Forge.selectedCreature.." • "..#Forge.workers.." props\n"..(moving and (Forge.sprint and "SPRINT" or "MOVE") or "IDLE").." • "..(Forge.ability or cfgNow.trait) 
            end
        end)
    end

    local function triggerAbility()
        if not Forge.active or Forge.spawning then return end
        Forge.ability=CREATURES[Forge.selectedCreature].ability
        Forge.abilityT=0
    end

    local function measureLiveProps()
        print("========== BTR CREATURE FORGE v10 LIVE SIZES ==========")
        print("Creature:",Forge.selectedCreature,"Variant:",variantNumber(),"Workers:",#Forge.workers)
        for i,w in ipairs(Forge.workers) do
            local sz=w.prop and getDimensions(w.prop) or w.size or Vector3.new()
            print(string.format("[%02d] %s | %s | size=(%.2f, %.2f, %.2f)",i,w.def.key,describeProp(w.def.prop,w.def.cat),sz.X,sz.Y,sz.Z))
        end
        local parts=blueprint()
        print("Blueprint count:",#parts)
        print("Creature class:",CREATURES[Forge.selectedCreature].class,"Trait:",CREATURES[Forge.selectedCreature].trait)
        print("Movement:",CREATURES[Forge.selectedCreature].speed,"/ sprint:",CREATURES[Forge.selectedCreature].sprint)
        if Forge.lastFailure~="" then print("Last failure:",Forge.lastFailure) end
        print("========================================================")
        notify("Creature Forge","Live prop sizes printed to the console.",3)
    end

    UIS.InputBegan:Connect(function(input,gp)
        if gp then return end
        if input.KeyCode==Enum.KeyCode.F then triggerAbility() end
    end)

    local function selectCreature(v)
        if not CREATURES[v] then return end
        local wasActive=Forge.active
        if wasActive then
            stopCreature()
            task.wait(0.15)
        end
        Forge.selectedCreature=v
        local valid=false
        for _,n in ipairs(THEME_ORDER) do if n==Forge.theme then valid=true break end end
        if not valid then Forge.theme="Default" end
        if Forge.hudButtons.title then Forge.hudButtons.title.Text=v end
        if Forge.hudButtons.status then Forge.hudButtons.status.Text="Selected: "..v.." • "..CREATURES[v].class.." • "..CREATURES[v].speed.." studs/s" end
        if wasActive then
            Forge.active=true
            buildHud()
            task.spawn(spawnCreature)
        end
    end

    local CREATURE_LIST={"Dragon","Phoenix","Dire Wolf","Crystal Serpent","Abyssal Mantis","Thunder Raptor","Obsidian Basilisk","Ember Wyvern","Frosthorn Beast"}

    local function addControls(tab)
        tab:AddSection({"> Creature Forge v10 • Original-Style Anatomy"})
        tab:AddDropdown({
            Name="Creature",
            Description="9 creatures with individual silhouettes, scales, speeds, traits and animation styles",
            Options=CREATURE_LIST,
            Default=Forge.selectedCreature,
            Callback=selectCreature
        })
        tab:AddDropdown({
            Name="Detail Variant",
            Description="15 props = compact detailed anatomy • 25 props = same scale with 10 extra anatomical details",
            Options={"15 Props — Compact","25 Props — Deluxe"},
            Default=Forge.selectedVariant,
            Callback=function(v) Forge.selectedVariant=v end
        })
        tab:AddDropdown({
            Name="Theme / Trait Colors",
            Description="Colors alter body, accents, wings, eyes and ability glow",
            Options=THEME_ORDER,
            Default=Forge.theme,
            Callback=function(v)
                Forge.theme=v
                for _,w in ipairs(Forge.workers) do paintProp(w.prop,w.def,Forge.time,Forge.ability~=nil) end
            end
        })
        tab:AddDropdown({
            Name="Movement Mode",
            Description="Native Roblox joystick drives the creature; Follow keeps the same creature style",
            Options={"MANUAL","FOLLOW"},
            Default=Forge.mode,
            Callback=function(v) Forge.mode=v end
        })
        tab:AddToggle({
            Name="Spawn / Despawn Creature",
            Description="Builds the complete construction, then disabling immediately clears the whole prop build like the original creatures",
            Default=false,
            Callback=function(v)
                if Forge.suppressToggle then return end
                if v then
                    if Forge.active then stopCreature() task.wait(0.15) end
                    Forge.active=true
                    buildHud()
                    task.spawn(spawnCreature)
                else
                    stopCreature()
                end
            end
        })
        tab:AddButton({Name="Ability",Description="Unique visual animation + characteristic color pulse",Callback=triggerAbility})
        tab:AddButton({Name="Rebuild Clean",Description="Clear all props and rebuild the selected creature from zero",Callback=function()
            stopCreature()
            task.wait(0.15)
            Forge.active=true
            buildHud()
            task.spawn(spawnCreature)
        end})
        tab:AddButton({Name="Live Prop Size Diagnostics",Description="Prints every live prop's actual bounding-box size, key and category",Callback=measureLiveProps})
        tab:AddButton({Name="Creature Profile",Description="Prints scale class, trait, walk speed, sprint speed and prop count",Callback=function()
            local cfg=CREATURES[Forge.selectedCreature]
            print("===== BTR CREATURE PROFILE =====")
            print(Forge.selectedCreature,cfg.class,cfg.role)
            print("Trait:",cfg.trait)
            print("Walk:",cfg.speed,"Sprint:",cfg.sprint,"Turn:",cfg.turn,"Scale:",cfg.scale)
            print("15 props:",#BLUEPRINTS[Forge.selectedCreature][15](),"25 props:",#BLUEPRINTS[Forge.selectedCreature][25]())
            print("================================")
        end})
    end

    addControls(BuildTab)
    addControls(BuildV2Tab)
    notify("Creature Forge v10","Redesigned 9-creature set loaded • each creature now has its own scale, speed, colors and animation profile.",5)
end

